const uid = () => (crypto.randomUUID ? crypto.randomUUID() :
  "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16);
  }));
// ★重要：new Date().toISOString()はUTC基準のため、日本時間の夜〜早朝（UTCとの9時間のズレの間）に
// 日付が1日ずれてしまう不具合があった。利用者は全員日本国内のため、常に日本時間(JST/UTC+9)を
// 明示的に計算して「今日の日付」とする。
const today  = () => {
  // ★Date.getTime()（絶対時刻）は端末のタイムゾーン設定に関わらず常にUTC基準の値なので、
  // 端末のタイムゾーンオフセットを混ぜて補正しようとすると、端末が既に日本時間の場合に
  // 補正が相殺されて何も直らないバグになる。単純にUTC+9時間した絶対時刻をUTC表記で
  // 読み出すだけで、端末の設定に関係なく常に正しい「日本時間の今日」が得られる。
  const jst = new Date(Date.now() + 9 * 60 * 60 * 1000);
  return jst.toISOString().slice(0, 10);
};
// ★ログアウトなど「意図した画面遷移」の際は、beforeunloadの確認ダイアログ（アプリを終了しますか？）
// を出さないようにするための共有フラグ。ログアウト確認→リロードの間に二重で確認が出る不具合を防ぐ。
let skipUnloadConfirm = false;
// ============================================================
// 画面共通のキャッシュ
// ============================================================
// ★同じ画面を開き直すたびに全部を取り直していると、そのつど「読み込み中...」で
// 　待たされてしまう。そこで、一度取得した内容を画面ごとに覚えておき、
// 　次に開いたときは「まず前回の内容をすぐ表示 → 裏で最新に差し替える」動きにする。
// 　（キャッシュはページを閉じるまでの一時的なもの。保存はしていない）
const screenCache = {};
const readScreenCache  = (key) => screenCache[key] ?? null;
const writeScreenCache = (key, data) => { screenCache[key] = data; };
const clearScreenCache = () => { Object.keys(screenCache).forEach(k => { delete screenCache[k]; }); clearDataCaches(); };

// ★データ取得のキャッシュ（処理速度改善）
//   分析画面を開くたび・条件を変えるたびに、全試合一覧やポイント明細を毎回サーバーから取り直していたため、
//   タップしてから表示までに時間がかかっていた。取得結果を短時間だけ覚えておき、同じ内容はすぐ返す。
//   ・自分が保存・削除した試合は、その場でキャッシュを捨てるので古い内容は出ない
//   ・他の人が記録した内容は、下の有効期限が切れた時点で最新になる
const MATCH_LIST_CACHE_MS   = 3 * 60 * 1000;  // 全試合一覧（分析画面用）：3分（自分の保存・削除ではその場で捨てる）
const FULL_MATCH_CACHE_MS   = 30 * 60 * 1000; // 終了済み試合のポイント明細：30分（終了済みの明細はほぼ変わらない。自分が保存した試合はその場で捨てる）
const PROFILE_CACHE_MS      = 5 * 60 * 1000;  // 自分のプロフィール：5分
let _matchListCache = null;      // { at, promise }
const _fullMatchCache = new Map(); // matchId -> { at, data }
let _profileCache = null;        // { at, promise }
// ★選手マスター：試合作成・試合を開く・一覧など多くの画面で毎回全件を取り直していたため、2分間だけ覚えておく。
//   自分が選手を追加・編集・削除したときは、その場で捨てて取り直す。
const ROSTER_CACHE_MS       = 2 * 60 * 1000;
let _rosterCache = null;         // { at, promise }
// ★最後に取得した全試合一覧（学校名・会場名の候補づくりに使い回す。候補なので少し古くても問題ない）
let _lastMatchListData = null;   // { at, list }
// ★作成した直後の試合。記録画面を開くときに、サーバーから取り直さずこれを使う（1回だけ）
const _primedMatches = new Map(); // matchId -> { at, data }
// ★サーブを選んで「試合開始」した直後の試合：記録画面を開いたら「第1ゲームの準備」を出さずに第1ゲームを始める
const _autoStartMatchIds = new Set();
function markAutoStart(id) { if (id) _autoStartMatchIds.add(id); }
function takeAutoStart(id) { const hit = _autoStartMatchIds.has(id); _autoStartMatchIds.delete(id); return hit; }
// ★個人戦の試合ID（団体戦の番手ではないと分かっている試合）。試合を開く前の問い合わせを省くために使う
let _knownIndividualMatchIds = new Set();
// ★団体戦の番手として登録されている試合ID（分析の「個人戦のみ／団体戦のみ」に使う）。試合一覧の取得時にも作る
let _teamBoutIdsCache = null;     // { at, promise }
// ★チームのシーズン設定（分析画面の期間の既定値）。管理者が変更したときはその場で捨てる
const SEASON_CACHE_MS = 5 * 60 * 1000;
let _seasonCache = null;          // { at, schoolId, promise }
function clearDataCaches() {
  _teamBoutIdsCache = null;
  _seasonCache = null;
  _matchListCache = null;
  _fullMatchCache.clear();
  _profileCache = null;
  _rosterCache = null;
  _lastMatchListData = null;
  _primedMatches.clear();
  _knownIndividualMatchIds = new Set();
  _savedMatchSnapshots.clear();
}
function invalidateRosterCache() { _rosterCache = null; }
function primeMatch(data) { if (data?.id) _primedMatches.set(data.id, { at: Date.now(), data }); }
function takePrimedMatch(id) {
  const hit = _primedMatches.get(id);
  _primedMatches.delete(id);
  return (hit && Date.now() - hit.at < 60 * 1000) ? hit.data : null;
}

// ★Supabase（PostgREST）は標準設定だと1回の取得で最大1000行までしか返さない。
//   件数が多いテーブルを「全部」取りたいときは、この関数で何回かに分けて取得する。
//   1回目で総件数を聞き、残りのページは同時に取りに行く（待ち時間はほぼ2回分で済む）。
//   apply には絞り込み・並び順を書く（並び順は必ず一意になるよう id などを最後に足すこと）。
const FETCH_PAGE_SIZE = 1000;
// ============================================================
// ★処理時間の計測表示（調査用）。URLに ?perf=1 を付けて開くとON、?perf=0 でOFF。
//   ONのときだけ画面下に「どの処理に何ミリ秒かかったか」を表示する。OFFのときは何もしない。
// ============================================================
const PERF_ON = (() => {
  try {
    const q = new URLSearchParams(window.location.search).get("perf");
    if (q === "1") localStorage.setItem("perfDebug", "1");
    if (q === "0") localStorage.removeItem("perfDebug");
    return localStorage.getItem("perfDebug") === "1";
  } catch { return false; }
})();
let _perfT0 = 0;
const _perfLines = [];
function perfStart(label) {
  if (!PERF_ON) return;
  _perfT0 = performance.now();
  _perfLines.length = 0;
  perfLog(`▶ ${label}`);
}
function perfLog(msg) {
  if (!PERF_ON) return;
  const t = _perfT0 ? Math.round(performance.now() - _perfT0) : 0;
  _perfLines.push(`${String(t).padStart(5, " ")}ms  ${msg}`);
  if (_perfLines.length > 30) _perfLines.shift();
  try {
    let box = document.getElementById("perf-box");
    if (!box) {
      box = document.createElement("pre");
      box.id = "perf-box";
      box.style.cssText = "position:fixed;left:4px;right:4px;bottom:4px;max-height:45vh;overflow:auto;z-index:99999;margin:0;padding:6px 8px;background:rgba(0,0,0,0.82);color:#7CFC9A;font:11px/1.35 monospace;border-radius:6px;white-space:pre-wrap;pointer-events:auto;";
      box.onclick = () => { box.style.display = box.style.display === "none" ? "block" : "none"; };
      document.body.appendChild(box);
    }
    box.textContent = _perfLines.join("\n");
  } catch {}
}
// 非同期処理の所要時間を測って記録する
async function perfTime(label, fn) {
  if (!PERF_ON) return fn();
  const t = performance.now();
  try { return await fn(); }
  finally { perfLog(`${label}: ${Math.round(performance.now() - t)}ms`); }
}

async function fetchAllRows(table, columns, apply = (q) => q) {
  const first = await apply(supabase.from(table).select(columns, { count: "exact" })).range(0, FETCH_PAGE_SIZE - 1);
  if (first.error) return { data: null, error: first.error };
  const rows = [...(first.data ?? [])];
  const total = first.count ?? rows.length;
  if (rows.length === 0 || total <= rows.length) return { data: rows, error: null };
  // サーバー側の上限が1000より小さい設定でも取りこぼさないよう、実際に返ってきた件数を1ページの大きさにする
  const step = rows.length;
  const pages = [];
  for (let from = step; from < total; from += step) {
    pages.push(apply(supabase.from(table).select(columns)).range(from, from + step - 1));
  }
  const results = await Promise.all(pages);
  for (const r of results) {
    if (r.error) return { data: null, error: r.error };
    rows.push(...(r.data ?? []));
  }
  return { data: rows, error: null };
}
// ★試合を保存・削除したときに呼ぶ（その試合の明細と、全試合一覧のキャッシュを捨てる）
function invalidateMatchCaches(matchId) {
  _matchListCache = null;
  _matchListPrefetchedAt = 0; // ★先読みした試合一覧も、そのままは使わない
  _teamBoutIdsCache = null;
  if (matchId) _fullMatchCache.delete(matchId); else _fullMatchCache.clear();
}
// ★ログイン中のユーザー。supabase.auth.getUser()は毎回サーバーに問い合わせるため、
//   画面表示の判定用には端末内に保存されているセッションから読む（通信なし）。
//   データの読み書きの権限は、これまで通りサーバー側（RLS）で守られている。
async function getAuthUserFast() {
  const { data } = await supabase.auth.getSession();
  if (data?.session?.user) return data.session.user;
  const { data: { user } } = await supabase.auth.getUser();
  return user ?? null;
}

// ★スマホ本体の「戻る」用：画面に出ているボタンを探すヘルパー
//   ・findOverlayCloseButton：画面に重なって表示されている小窓・シートの ✕／閉じる／キャンセル／←（一番手前のもの）
//   ・findPageBackButton：画面左上の「←」（無ければ画面内の「← 戻る」）
const BACK_BUTTON_LABELS = new Set(["←", "← 戻る", "✕", "×", "閉じる", "キャンセル", "戻る"]);
function collectBackCandidates() {
  const labelOf = (el) => (el.textContent || "").replace(/\s+/g, " ").trim();
  const inOverlay = (el) => {
    for (let n = el.parentElement; n && n !== document.body; n = n.parentElement) {
      if (getComputedStyle(n).position === "fixed") return true;
    }
    return false;
  };
  // ★一部の画面（AI分析など）は「←」をbuttonではなくspanで作っているため、文字が「←」だけのspanも対象にする
  const els = Array.from(document.querySelectorAll("button, span"))
    .filter(el => el.tagName === "BUTTON" || labelOf(el) === "←")
    .filter(el => el.getClientRects().length > 0 && !el.disabled);
  return { els, labelOf, inOverlay };
}
function findOverlayCloseButton() {
  try {
    const { els, labelOf, inOverlay } = collectBackCandidates();
    const list = els.filter(b => { const t = labelOf(b); return (BACK_BUTTON_LABELS.has(t) || t.startsWith("← ")) && inOverlay(b); });
    return list.length ? list[list.length - 1] : null;
  } catch (e) { console.error(e); return null; }
}
function findPageBackButton() {
  try {
    const { els, labelOf, inOverlay } = collectBackCandidates();
    const page = els.filter(b => !inOverlay(b));
    return page.find(b => labelOf(b) === "←") ?? page.find(b => labelOf(b) === "← 戻る") ?? null;
  } catch (e) { console.error(e); return null; }
}

// ★ログアウト処理を1箇所に共通化（確認ダイアログの表示 → 実際のログアウト → リロード）
async function performLogout() {
  if (!window.confirm("ログアウトしますか？")) return;
  skipUnloadConfirm = true;
  clearScreenCache(); // ★別のアカウントのデータが残らないように破棄する
  _isViewerCache = null; // ★閲覧専用かどうかの判定も、次のアカウントに引き継がないよう破棄する
  await supabase.auth.signOut();
  window.location.reload();
}
const fmtDate = (iso) => iso ? iso.replace(/-/g, "/") : "";
// ★大会予定日までの残り日数を計算（当日=0、翌日=1、過去はマイナス）
const daysUntil = (iso) => {
  if (!iso) return null;
  const d1 = new Date(`${today()}T00:00:00`);
  const d2 = new Date(`${iso}T00:00:00`);
  return Math.round((d2 - d1) / (1000 * 60 * 60 * 24));
};
// ★一覧等で試合の状態を短く表示するための共通ヘルパー（中断した試合を「進行中」と誤表示しないようにする）
// 　「途中終了」ボタンは手動操作なので、実際は最後まで消化してゲーム数を先取している（例：7Gマッチで4ゲーム先取済み）
// 　スコアであれば、誤操作／本当は最後まで行われた試合とみなし、表示上は「終了」として扱う。
const looksNaturallyFinished = (m) => {
  const fmt = m?.game_format ?? 7;
  const need = Math.ceil(fmt / 2);
  return Math.max(m?.match_score_a ?? 0, m?.match_score_b ?? 0) >= need;
};
// ★成績・分析で「終わった試合」として数えるか。
//   「途中終了」で保存されていても、スコアが先取ゲーム数に達していれば（押し間違いなど）、
//   団体戦の画面と同じく「終了」とみなして数える。本当に途中で打ち切った試合（1-1など）は数えない。
const countsAsFinished = (m) => !!m && (m.status === "finished" || (m.status === "abandoned" && looksNaturallyFinished(m)));
// ★以前は「終了・途中終了・中断」以外をすべて「進行中」と表示していたため、
//   まだ始まっていない予定（scheduled）や待機中（waiting）の試合まで「進行中」と出てしまっていた。
//   試合一覧では「予定」と出るのに戦績画面では「進行中」と出る、という食い違いの原因。
const matchStatusShortLabel = (m) => (m.status==="finished" || (m.status==="abandoned" && looksNaturallyFinished(m))) ? `${m.match_score_a}-${m.match_score_b}` : m.status==="abandoned" ? `途中終了 ${m.match_score_a}-${m.match_score_b}` : m.status==="suspended" ? `中断 ${m.match_score_a}-${m.match_score_b}` : m.status==="scheduled" ? "予定" : m.status==="waiting" ? "待機中" : "進行中";
// ★選手選択チップの並び順をバラバラ（登録順）ではなく五十音順に揃えるための比較関数。
//   読み仮名（ふりがな）は選手マスターに保存していないため完全な厳密さではないが、
//   日本語ロケールでの文字列比較（Intl collation）により実用上ほぼ五十音順になる。
const byPlayerNameKana = (a, b) => (a.player_name || "").localeCompare(b.player_name || "", "ja");
// ★試合レコードのどちらの選手たちが「自チーム」かを判定する共通ヘルパー。
//   通常の試合記録は「自チーム＝Aチーム」の前提で保存されるが、ドロー表の「結果だけ記録」機能は
//   ブラケット上のA/Bどちらが自チームかが一定しないため、club_nameで判定する。一致しない場合は
//   従来通りAチーム側を自チームとみなす（フォールバック）。
const mySideOf = (m, mySchoolName) => {
  if (!mySchoolName) return "A";
  const bIsMine = (m.players || []).some(p => p.team === "B" && p.club_name === mySchoolName);
  const aIsMine = (m.players || []).some(p => p.team === "A" && p.club_name === mySchoolName);
  if (bIsMine && !aIsMine) return "B";
  return "A";
};
// ★試合の勝者側（"A" | "B" | null）を判定する共通関数。
//   通常はゲームカウントの大小で決まるが、「棄権による試合終了」ではゲームカウントの数字だけでは
//   勝敗が決まらない（棄権した側の方が数字上多いこともある）ため、その場合はmatch.walkover_winnerを
//   最優先で使う。勝敗が関わるすべての箇所は、直接スコアを比較せず必ずこの関数を使うこと。
const sortByRecord = (sort) => (a,b) => {
  // ★勝率順：丸めた%ではなく勝数÷試合数で比べる。同じ勝率なら試合数が多い方（＝より確かな数字）を上にする
  if (sort === "rate") {
    const ra = a.total > 0 ? a.wins / a.total : -1;
    const rb = b.total > 0 ? b.wins / b.total : -1;
    return (rb - ra) || (b.total - a.total) || (b.wins - a.wins);
  }
  if (sort === "lose")  return (b.losses - a.losses) || (b.total - a.total);
  if (sort === "count") return (b.total - a.total) || (b.wins - a.wins);
  return (b.wins - a.wins) || (b.total - a.total);
};

const winnerSideOf = (m) => {
  if (m.walkover_winner === "A" || m.walkover_winner === "B") return m.walkover_winner;
  if (m.match_score_a > m.match_score_b) return "A";
  if (m.match_score_a < m.match_score_b) return "B";
  return null; // 同点かつ棄権情報も無い（本来起こらないはずのデータ）
};
// ★品質改善：「清見 祐吾」「清見祐吾」のように空白の有無だけが違う同一人物を
// 別選手として重複登録してしまわないよう、選手名の比較は空白を除去してから行う
const normalizePlayerName = (name) => (name || "").replace(/\s+/g, "");
const fmtDateRange = (start, end) => {
  if (!start) return "";
  const s = fmtDate(start);
  const e = end ? fmtDate(end) : s;
  return s === e ? s : `${s} 〜 ${e}`;
};
// ★大会一覧用：曜日付きの日付（例：2026/10/04（日）、2026/10/10（土）〜10/11（日））。
//   終了日は同じ年なら年を省く。
const fmtDateDow = (iso) => {
  if (!iso) return "";
  const d = new Date(iso + "T00:00:00");
  if (isNaN(d.getTime())) return fmtDate(iso);
  return `${fmtDate(iso)}（${"日月火水木金土"[d.getDay()]}）`;
};
const fmtDateRangeDow = (start, end) => {
  if (!start) return "";
  if (!end || end === start) return fmtDateDow(start);
  const e = fmtDateDow(end);
  return `${fmtDateDow(start)}〜${start.slice(0,4) === end.slice(0,4) ? e.slice(5) : e}`;
};

// ============================================================
// 統計集計用 共通ヘルパー
// ============================================================
// 指定選手が、この試合でどちら側(A/B)として出場したかを判定する。
// ★東福岡 対 東福岡 のような自チーム同士の練習試合の場合、B側の選手も自チームの一員なので、
// 　mySchoolNameを渡すことでB側の出場も対象に含められる（通常はteam A側のみを対象にする）
function ownSideFor(m, playerName, mySchoolName) {
  const onA = m.players.find(p=>p.player_name===playerName && p.team==="A");
  if (onA) return "A";
  if (mySchoolName) {
    const onB = m.players.find(p=>p.player_name===playerName && p.team==="B" && p.club_name && p.club_name.trim()===mySchoolName.trim());
    if (onB) return "B";
  }
  return null;
}
// 指定選手の視点で、その試合が勝ちかどうかを判定（出場していなければnull）
// ★この関数は常に自チーム選手の戦績を見る用途で使われるため、同名の選手が
// 　相手チームにも存在する場合の取り違えを防ぐよう、まず自チーム(A)側を優先して探す
// 　mySchoolNameを渡すと、自チーム同士の練習試合でB側に出た場合も対象にする
function winForPlayer(m, playerName, mySchoolName) {
  const team = ownSideFor(m, playerName, mySchoolName)
            ?? m.players.find(p=>p.player_name===playerName)?.team;
  if (!team) return null;
  return team==="A" ? winnerSideOf(m)==="A" : winnerSideOf(m)==="B";
}
// 指定選手の、その試合での相方（ペア）名を取得
function partnerOf(m, playerName, mySchoolName) {
  const team = ownSideFor(m, playerName, mySchoolName)
            ?? m.players.find(p=>p.player_name===playerName)?.team;
  if (!team) return null;
  const partner = m.players.find(p=>p.team===team && p.player_name!==playerName);
  return partner ? partner.player_name : null;
}
// 試合配列から成績（試合数・勝敗・勝率）を算出
function recordOf(finishedMatches, winFn) {
  const total = finishedMatches.length;
  const wins = finishedMatches.filter(winFn).length;
  return { total, wins, losses: total-wins, rate: total>0 ? Math.round(wins/total*100) : 0 };
}
// 直近n日に絞り込み
function withinLastDays(matchList, days) {
  const cutoff = new Date(); cutoff.setDate(cutoff.getDate()-days);
  return matchList.filter(m => m.match_date && new Date(m.match_date) >= cutoff);
}
// 期間チップ＋勝率ソートチップ（一覧画面で共通使用）
function PeriodSortBar({ period, setPeriod, sort, setSort }) {
  return (
    <div style={{ display:"flex",gap:6,flexWrap:"wrap",marginBottom:12 }}>
      <button style={{ ...S.togBtn(period==="all",C.navy),fontSize:11,padding:"6px 10px" }} onClick={()=>setPeriod("all")}>全期間</button>
      <button style={{ ...S.togBtn(period==="month1",C.navy),fontSize:11,padding:"6px 10px" }} onClick={()=>setPeriod("month1")}>直近1ヶ月</button>
      <button style={{ ...S.togBtn(sort==="rate",C.accent),fontSize:12.5,padding:"8px 12px" }} onClick={()=>setSort("rate")}>勝率順</button>
      <button style={{ ...S.togBtn(sort==="win",C.accent),fontSize:12.5,padding:"8px 12px" }} onClick={()=>setSort("win")}>勝数順</button>
      <button style={{ ...S.togBtn(sort==="lose",C.accent),fontSize:12.5,padding:"8px 12px" }} onClick={()=>setSort("lose")}>負数順</button>
      <button style={{ ...S.togBtn(sort==="count",C.accent),fontSize:12.5,padding:"8px 12px" }} onClick={()=>setSort("count")}>試合数順</button>
    </div>
  );
}
// 月別の勝率推移カード（複数画面で共通使用）
// ★onToggle を渡すと、見出しをタップして開閉できる折りたたみ表示になる（open＝開いているか）
function MonthlyTrendCard({ finishedMatches, winFn, title="月別の勝率推移", open=true, onToggle }) {
  const byMonth = {};
  finishedMatches.forEach(m=>{
    const month = (m.match_date||"").slice(0,7);
    if (!month) return;
    (byMonth[month] ??= { wins:0, total:0 });
    byMonth[month].total++;
    if (winFn(m)) byMonth[month].wins++;
  });
  const months = Object.keys(byMonth).sort();
  if (months.length===0) return null;
  return (
    <div style={{ ...S.card, padding:onToggle?"13px 14px":16, marginBottom:onToggle?12:16 }}>
      <div onClick={onToggle} style={{ display:"flex",justifyContent:"space-between",alignItems:"center",fontSize:15,fontWeight:800,color:C.navy,marginBottom:open?12:0,cursor:onToggle?"pointer":"default" }}>
        <span>{title}</span>
        {onToggle && <span style={{ fontSize:14,color:C.textSec }}>{open?"▲":"▼"}</span>}
      </div>
      {open && months.map(month=>{
        const { wins, total } = byMonth[month];
        const rate = Math.round(wins/total*100);
        const [y,mo] = month.split("-");
        return (
          <div key={month} style={{ marginBottom:12 }}>
            <div style={{ display:"flex",justifyContent:"space-between",fontSize:13.5,color:"#5a6478",marginBottom:5 }}>
              <span>{y}年{Number(mo)}月（{total}試合）</span>
              <span style={{ fontSize:14,fontWeight:800,color:C.text }}>{wins}勝{total-wins}敗・{rate}%</span>
            </div>
            <div style={{ height:10,background:"#e8edf3",borderRadius:5,overflow:"hidden" }}>
              <div style={{ width:`${rate}%`,height:"100%",background:C.accent,borderRadius:5 }}/>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// DBのshot_type制約に合う組み合わせのみ許可。合わなければnull（保存はできる）
const VALID_SHOT_TYPES = new Set([
  "serve_ace","volley_winner","smash_winner","stroke_winner","return_winner",
  "drop_winner","lob_winner","approach_winner","stroke_error","volley_error",
  "smash_error","return_error","drop_error","lob_error","net_cord","double_fault",
]);
const toShotType = (play, result) => {
  const key = buildShotKey(play, result);
  return VALID_SHOT_TYPES.has(key) ? key : null;
};

// ★トーナメント表の「簡易記録」（勝敗とスコアだけを直接入力したdraw_matches）を、
// 　選手別/ペア別の勝敗数集計に使えるよう「疑似的な試合」の形に変換して取得する。
// 　通常の試合記録（matchesテーブル）は一切作られないため、統計画面でのみこれを使う。
async function getSimpleRecordedDrawMatches(tournamentId) {
  // ★1000件を超えても取りこぼさないよう分けて取得する
  const { data: dms, error } = await fetchAllRows("draw_matches",
    "id, tournament_id, side_a_entry_id, side_b_entry_id, simple_result_winner, simple_result_score_a, simple_result_score_b",
    q => {
      let qq = q.not("simple_result_winner", "is", null);
      if (tournamentId) qq = qq.eq("tournament_id", tournamentId);
      return qq.order("id");
    });
  if (error) { console.error(error); return []; }
  if (!dms || dms.length === 0) return [];

  const entryIds = Array.from(new Set(dms.flatMap(d => [d.side_a_entry_id, d.side_b_entry_id]).filter(Boolean)));
  const tournamentIds = Array.from(new Set(dms.map(d => d.tournament_id).filter(Boolean)));

  // ★IDが多いと1回のリクエストが長くなりすぎるため、150件ずつに分けて同時に取得する
  const inChunks = (table, cols, ids) => {
    const reqs = [];
    for (let i = 0; i < ids.length; i += 150) reqs.push(supabase.from(table).select(cols).in("id", ids.slice(i, i + 150)));
    return Promise.all(reqs).then(rs => rs.flatMap(r => { if (r.error) console.error(r.error); return r.data ?? []; }));
  };
  const [entries, tournaments] = await Promise.all([
    inChunks("draw_entries", "id, player1_name, player2_name, school_name, is_own_team", entryIds),
    inChunks("tournaments", "id, name, start_date, end_date", tournamentIds),
  ]);
  const entryMap = {}; entries.forEach(e => { entryMap[e.id] = e; });
  const tMap = {}; tournaments.forEach(t => { tMap[t.id] = t; });

  return dms.map(dm => {
    const eA = dm.side_a_entry_id ? entryMap[dm.side_a_entry_id] : null;
    const eB = dm.side_b_entry_id ? entryMap[dm.side_b_entry_id] : null;
    const t = tMap[dm.tournament_id];
    const players = [];
    if (eA?.player1_name) players.push({ team: "A", player_name: eA.player1_name, club_name: eA.school_name || null, order_num: 1 });
    if (eA?.player2_name) players.push({ team: "A", player_name: eA.player2_name, club_name: eA.school_name || null, order_num: 2 });
    if (eB?.player1_name) players.push({ team: "B", player_name: eB.player1_name, club_name: eB.school_name || null, order_num: 1 });
    if (eB?.player2_name) players.push({ team: "B", player_name: eB.player2_name, club_name: eB.school_name || null, order_num: 2 });
    const hasScore = dm.simple_result_score_a != null && dm.simple_result_score_b != null;
    const scoreA = hasScore ? dm.simple_result_score_a : (dm.simple_result_winner === "A" ? 1 : 0);
    const scoreB = hasScore ? dm.simple_result_score_b : (dm.simple_result_winner === "B" ? 1 : 0);
    return {
      id: "draw-" + dm.id,
      tournament_name: t?.name || "",
      match_date: t?.start_date || t?.end_date || null,
      status: "finished",
      match_score_a: scoreA,
      match_score_b: scoreB,
      players,
      games: [],
      is_simple_draw_result: true,
    };
  }).filter(m => m.players.length > 0);
}

// ★複数の試合IDから、games/points/faultsまで含めた完全な試合データを一括取得する
// 　（個人分析画面で選ばれた複数の試合をまとめて集計するために使う）
// ★キャッシュから返すときは複製を渡す（呼び出し側が中身を書き換えてもキャッシュが壊れないように）
const cloneMatchData = (m) => (typeof structuredClone === "function" ? structuredClone(m) : JSON.parse(JSON.stringify(m)));

// ★明細の取得列（rowToMatchFull が使う列だけ。select("*") より転送量が少ない）
const FULL_PLAYER_COLS = "id, match_id, team, player_name, club_name, position, order_num, entry_no";
const FULL_GAME_COLS = "id, match_id, game_number, server_team, is_final, score_a, score_b, winner_team";
const FULL_POINT_COLS = "id, game_id, match_id, point_number, scoring_team, player_name, play_type, side_type, course_type, miss_type, result_type, is_winner, fault_count, score_a_after, score_b_after, scored_at";
const FULL_FAULT_COLS = "id, game_id, match_id, fault_number, server_team, player_name, score_a_at, score_b_at";

// ★取得中の試合明細（試合ID -> Promise<試合データ|null>）。
//   ホーム画面の先読みが終わる前に分析を開いたとき、同じ試合をもう一度取得して回線を奪い合っていたため、
//   取得中のものがあればその完了を待って使う。
const _fullMatchInflight = new Map();

async function getFullMatchesByIds(ids) {
  const allIds = Array.from(new Set((ids ?? []).filter(Boolean)));
  if (allIds.length === 0) return [];

  // ★終了済みの試合の明細はしばらくキャッシュする。分析画面で条件や選手を切り替えるたびに
  //   同じ試合のポイントを取り直していたのが、表示が遅い一番の原因だったため。
  //   進行中の試合は刻々と変わるので、キャッシュせず毎回取得する。
  const now = Date.now();
  const cachedResults = [];
  const waiting = [];
  const toFetch = [];
  allIds.forEach(id => {
    const hit = _fullMatchCache.get(id);
    if (hit && now - hit.at < FULL_MATCH_CACHE_MS) cachedResults.push(cloneMatchData(hit.data));
    else if (_fullMatchInflight.has(id)) waiting.push(_fullMatchInflight.get(id));
    else toFetch.push(id);
  });
  perfLog(`明細: ${allIds.length}試合（キャッシュ${cachedResults.length} / 取得中を待つ${waiting.length} / 新規取得${toFetch.length}）`);
  if (toFetch.length === 0 && waiting.length === 0) return cachedResults;

  let fetchP = Promise.resolve([]);
  if (toFetch.length > 0) {
    fetchP = fetchFullMatchesUncached(toFetch);
    toFetch.forEach(id => {
      const one = fetchP.then(list => list.find(m => m.id === id) ?? null, () => null);
      _fullMatchInflight.set(id, one);
    });
    fetchP.finally(() => { toFetch.forEach(id => _fullMatchInflight.delete(id)); }).catch(() => {});
  }
  const tFull = performance.now();
  const [fetched, waited] = await Promise.all([fetchP, Promise.all(waiting)]);
  perfLog(`明細の取得完了: ${Math.round(performance.now() - tFull)}ms（ポイント${fetched.reduce((a, m) => a + (m.games ?? []).reduce((b, g) => b + (g.points?.length ?? 0), 0), 0)}件）`);
  return [
    ...cachedResults,
    ...fetched,
    ...waited.filter(Boolean).map(cloneMatchData), // 他の取得の結果を共有するので、書き換えられないよう複製を渡す
  ];
}

async function fetchFullMatchesUncached(uniqueIds) {
  // ★試合数が多い大会だと、.in()に渡すID一覧が長くなりすぎて
  //   リクエストが失敗したり、スマホの通信・メモリ負荷が大きくなり画面が固まる
  //   （真っ白になる）ことがあったため、一定件数ごとに分割して取得する。
  // ★以前は40試合ずつだったため、ポイントが1回の上限（1000件）を必ず超え、
  //   「件数を数える→残りのページを取る」の2往復になっていた。15試合ずつにして
  //   ほとんどの分割が1往復で終わるようにし、分割はすべて同時に取得する。
  const CHUNK_SIZE = 15;
  const chunks = [];
  for (let i = 0; i < uniqueIds.length; i += CHUNK_SIZE) {
    chunks.push(uniqueIds.slice(i, i + CHUNK_SIZE));
  }

  const ms = [];
  const playersByMatch = {};
  const gamesByMatch = {};
  const pointsByMatch = {};
  const faultsByMatch = {};

  // ★以前は40件ずつ「順番に」取得していたため、試合数が多いほど待ち時間が積み上がっていた。
  //   サーバーに負荷をかけすぎないよう、同時に3チャンクまで並行して取得する。
  const fetchChunk = async (chunkIds) => {
    const [
      { data: msChunk, error: mErr },
      { data: playersData, error: pErr },
      { data: gamesData, error: gErr },
      { data: pointsData, error: ptErr },
      { data: faultsData, error: fErr },
    ] = await Promise.all([
      supabase.from("matches").select("*").in("id", chunkIds),
      // ★明細は画面で使う列だけを取得する（rowToMatchFullで使う列と同じ）。
      // ★40試合分のポイントは1000件を超えるため、1回の取得では途中で切れていた
      //   （＝分析の数字が一部の試合で欠けていた）。全ページを取得する。
      // ★ポイントは必ずpoint_number順で取得する。サーブを誰が打ったかの推定は
      //   「そのゲームの何本目か」を配列の並び順で数えているため、順番が崩れると
      //   ダブルフォルトや1st/2ndの内訳がペアの別の選手に割り当てられてしまう（取得後にも並べ直す）。
      fetchAllRows("match_players", FULL_PLAYER_COLS, q => q.in("match_id", chunkIds).order("id")),
      fetchAllRows("games", FULL_GAME_COLS, q => q.in("match_id", chunkIds).order("match_id").order("game_number").order("id")),
      fetchAllRows("points", FULL_POINT_COLS, q => q.in("match_id", chunkIds).order("match_id").order("point_number").order("id")),
      fetchAllRows("faults", FULL_FAULT_COLS, q => q.in("match_id", chunkIds).order("match_id").order("fault_number").order("id")),
    ]);
    const chunkErr = mErr || pErr || gErr || ptErr || fErr;
    if (chunkErr) { console.error(chunkErr); return; } // 1チャンク失敗しても他は続行する
    (msChunk ?? []).forEach(m => ms.push(m));
    (playersData ?? []).forEach(p => { (playersByMatch[p.match_id] ??= []).push(p); });
    (gamesData ?? []).forEach(g => { (gamesByMatch[g.match_id] ??= []).push(g); });
    (pointsData ?? []).forEach(pt => { (pointsByMatch[pt.match_id] ??= []).push(pt); });
    (faultsData ?? []).forEach(f => { (faultsByMatch[f.match_id] ??= []).push(f); });
  };
  const PARALLEL = 7; // 100試合（分析の上限）なら一度に全部
  for (let i = 0; i < chunks.length; i += PARALLEL) {
    await Promise.all(chunks.slice(i, i + PARALLEL).map(fetchChunk));
  }

  // ★チャンクごとに取得しているため、詰め直した後にも必ず番号順へ並べ直しておく
  const byNumFull = (key) => (a, b) => (a[key] ?? 0) - (b[key] ?? 0);
  Object.values(gamesByMatch).forEach(list => list.sort(byNumFull("game_number")));
  Object.values(pointsByMatch).forEach(list => list.sort(byNumFull("point_number")));
  Object.values(faultsByMatch).forEach(list => list.sort(byNumFull("fault_number")));

  const fetched = ms.map(m => rowToMatchFull(
    m,
    playersByMatch[m.id] ?? [],
    gamesByMatch[m.id] ?? [],
    pointsByMatch[m.id] ?? [],
    faultsByMatch[m.id] ?? [],
  ));
  // ★終了済み・削除されていない試合だけ覚えておく
  const savedAt = Date.now();
  ms.forEach((row, i) => {
    if (row.status === "finished" && !row.deleted_at) _fullMatchCache.set(row.id, { at: savedAt, data: cloneMatchData(fetched[i]) });
  });
  return fetched;
}

// ============================================================
// 日別選手ランキング専用のデータ取得（軽量版）
// ★以前はgetMatches()/getTeamMatches()で「全試合・全団体戦」を取得してから
// 　大会名でフィルタしていたため、チームの利用期間が長くなるほど無駄な通信・
// 　メモリ使用量が増え、試合数の多い大会でスマホが固まる（真っ白になる）
// 　原因になっていた。ここではDB側で最初から対象大会だけに絞り込む。
// ============================================================

// ★大会に属する「集計対象の試合ID＋日付」だけを軽量に取得する（点数等のフル取得はしない）
async function getRankingTargetRows(tournamentName) {
  const [
    { data: matchRows, error: mErr },
    { data: teamRows, error: tErr },
  ] = await Promise.all([
    supabase.from("matches").select("id, match_date")
      .eq("tournament_name", tournamentName).is("deleted_at", null),
    supabase.from("team_matches").select("id, match_date, round, status, format")
      .eq("tournament_name", tournamentName).is("deleted_at", null),
  ]);
  if (mErr) { console.error(mErr); throw mErr; }
  if (tErr) { console.error(tErr); throw tErr; }

  const teamMatchIds = (teamRows ?? []).map(tm => tm.id);
  let teamGames = [];
  if (teamMatchIds.length > 0) {
    const { data: gamesData, error: gErr } = await supabase
      .from("team_match_games")
      .select("id, team_match_id, match_id, order_num, status")
      .in("team_match_id", teamMatchIds);
    if (gErr) { console.error(gErr); throw gErr; }
    teamGames = gamesData ?? [];
  }
  const gamesByTeamMatch = {};
  teamGames.forEach(g => { (gamesByTeamMatch[g.team_match_id] ??= []).push(g); });

  // ★診断用：この大会の団体戦(ラウンド)ごとに、番手が何件あり、
  //   うちmatch_idが入っている(＝集計対象になる)のは何件かを可視化する
  const roundBreakdown = (teamRows ?? []).map(tm => {
    const games = gamesByTeamMatch[tm.id] ?? [];
    return {
      id: tm.id, round: tm.round || "(ラウンド名なし)", date: tm.match_date,
      status: tm.status, format: tm.format, totalGames: games.length,
      withMatchId: games.filter(g => g.match_id).length,
      games: games.map(g => ({ order_num: g.order_num, has_match_id: !!g.match_id, status: g.status })),
    };
  });

  const teamBoutIds = new Set();
  teamGames.forEach(g => { if (g.match_id) teamBoutIds.add(g.match_id); });
  const teamMatchDateById = {};
  (teamRows ?? []).forEach(tm => { teamMatchDateById[tm.id] = tm.match_date; });

  // ★対象となる試合ID＋その日付（個人戦はmatch_date、団体戦の各番手は団体戦本体のmatch_dateを使う）
  const targetRows = [];
  (matchRows ?? [])
    .filter(m => !teamBoutIds.has(m.id))
    .forEach(m => targetRows.push({ matchId: m.id, date: m.match_date }));
  teamGames.forEach(g => {
    if (g.match_id) targetRows.push({ matchId: g.match_id, date: teamMatchDateById[g.team_match_id] });
  });
  const uniqueRows = Array.from(new Map(targetRows.map(row => [row.matchId, row])).values());

  // ★診断用：targetRows→uniqueRowsで件数が減っていれば、
  //   複数の番手が同じmatch_idを参照している（重複除去で消えている）ことになる
  const dedupDiag = {
    targetRowsCount: targetRows.length,
    uniqueRowsCount: uniqueRows.length,
    duplicateMatchIds: (() => {
      const counts = {};
      targetRows.forEach(r => { counts[r.matchId] = (counts[r.matchId]||0) + 1; });
      return Object.entries(counts).filter(([,c]) => c > 1).map(([id,c]) => ({ id, count:c }));
    })(),
  };

  return { uniqueRows, roundBreakdown, dedupDiag };
}

// ★指定した試合IDについて、選手別ランキング集計(calcPlayerStats)に必要な列だけをまとめて取得する。
// 　select("*")だと、メモ・動画同期用時刻(scored_at)など集計に使わない列まで転送されてしまい、
// 　pointsのようにレコード数が多いテーブルほどデータ量・処理量が膨らむ原因になっていたため、
// 　必要な列だけに絞る。また、points/faultsはgame_id単位で事前にグルーピングしておくことで、
// 　rowToMatchFull()で行っていた「ゲームごとにpoints/faults全体をfilterする」処理も避けられる。
async function getRankingMatchDetails(ids) {
  const uniqueIds = Array.from(new Set((ids ?? []).filter(Boolean)));
  if (uniqueIds.length === 0) return [];

  const CHUNK_SIZE = 40;
  const chunks = [];
  for (let i = 0; i < uniqueIds.length; i += CHUNK_SIZE) chunks.push(uniqueIds.slice(i, i + CHUNK_SIZE));

  const ms = [];
  const playersByMatch = {};
  const gamesByMatch = {};
  const pointsByGame = {};
  const faultsByGame = {};

  for (const chunkIds of chunks) {
    const [
      { data: msChunk, error: mErr },
      { data: playersData, error: pErr },
      { data: gamesData, error: gErr },
      { data: pointsData, error: ptErr },
      { data: faultsData, error: fErr },
    ] = await Promise.all([
      supabase.from("matches")
        .select("id, match_date, tournament_name, status, order_a, order_b, receive_order_a, receive_order_b, match_score_a, match_score_b, walkover_winner")
        .in("id", chunkIds),
      // ★40試合分のポイントは1000件を超えるため、全ページを取得する（以前は途中で切れていた）
      fetchAllRows("match_players", "id, match_id, team, player_name, order_num, club_name",
        q => q.in("match_id", chunkIds).order("id")),
      fetchAllRows("games", "id, match_id, game_number, server_team, is_final",
        q => q.in("match_id", chunkIds).order("match_id").order("game_number").order("id")),
      // ★重要：サーブを誰が打ったかは「そのゲームの何本目のサーブか」を配列の並び順で数えて割り出しているため、
      //   point_number順で取得しないと、DFや1st/2ndの内訳がペアの別の選手に割り当てられてしまう。
      //   （試合詳細のスタッツタブはorder指定済みなので、以前はこの分析メニューだけ数字が食い違っていた）
      fetchAllRows("points", "id, game_id, match_id, point_number, player_name, scoring_team, play_type, result_type, is_winner, fault_count",
        q => q.in("match_id", chunkIds).order("match_id").order("point_number").order("id")),
      fetchAllRows("faults", "id, game_id, match_id, fault_number, player_name, server_team",
        q => q.in("match_id", chunkIds).order("match_id").order("fault_number").order("id")),
    ]);
    const chunkErr = mErr || pErr || gErr || ptErr || fErr;
    if (chunkErr) { console.error(chunkErr); continue; } // 1チャンク失敗しても他は続行する
    (msChunk ?? []).forEach(m => ms.push(m));
    (playersData ?? []).forEach(p => { (playersByMatch[p.match_id] ??= []).push(p); });
    (gamesData ?? []).forEach(g => { (gamesByMatch[g.match_id] ??= []).push(g); });
    (pointsData ?? []).forEach(pt => { (pointsByGame[pt.game_id] ??= []).push(pt); });
    (faultsData ?? []).forEach(f => { (faultsByGame[f.game_id] ??= []).push(f); });
  }

  // ★念のための二重の保険：チャンク単位で取得しているため、配列に詰め直した後にも
  //   ゲーム・ポイント・フォルトを必ず番号順に並べ直しておく。
  const byNum = (key) => (a, b) => (a[key] ?? 0) - (b[key] ?? 0);
  Object.values(gamesByMatch).forEach(list => list.sort(byNum("game_number")));
  Object.values(pointsByGame).forEach(list => list.sort(byNum("point_number")));
  Object.values(faultsByGame).forEach(list => list.sort(byNum("fault_number")));

  return ms.map(m => ({
    id: m.id, match_date: m.match_date, tournament_name: m.tournament_name ?? "", status: m.status,
    order_a: m.order_a === "p2" ? "p2" : "p1", order_b: m.order_b === "p2" ? "p2" : "p1",
    receive_order_a: m.receive_order_a === "p2" ? "p2" : m.receive_order_a === "p1" ? "p1" : null, receive_order_b: m.receive_order_b === "p2" ? "p2" : m.receive_order_b === "p1" ? "p1" : null,
    match_score_a: m.match_score_a, match_score_b: m.match_score_b, walkover_winner: m.walkover_winner ?? null,
    players: (playersByMatch[m.id] ?? []).map(p => ({
      id: p.id, team: p.team, player_name: p.player_name, order_num: p.order_num, club_name: p.club_name ?? null,
    })),
    games: (gamesByMatch[m.id] ?? []).map(g => ({
      id: g.id, match_id: m.id, game_number: g.game_number, server_team: g.server_team, is_final: g.is_final,
      faults: faultsByGame[g.id] ?? [],
      points: pointsByGame[g.id] ?? [],
    })),
  }));
}


// ★分析画面は再描画のたびに「通算・勝ち・負け・推移」と同じ試合を何度も集計していたため、
//   1試合分の calcPlayerStats の結果を試合オブジェクトごとに覚えておく。
//   中身（ゲーム・ポイント・選手）が変わっていれば計算し直す。
const _playerStatsMemo = new WeakMap();
function playerStatsSignature(match) {
  const games = Array.isArray(match.games) ? match.games : [];
  let n = 0;
  for (const g of games) n += (g?.points?.length ?? 0) * 1000 + (g?.faults?.length ?? 0);
  return `${games.length}:${n}:${match.players?.length ?? 0}`;
}
function calcPlayerStatsMemo(match) {
  if (!match || typeof match !== "object") return calcPlayerStats(match);
  const sig = playerStatsSignature(match);
  const hit = _playerStatsMemo.get(match);
  if (hit && hit.games === match.games && hit.players === match.players && hit.sig === sig) return hit.rows;
  const rows = calcPlayerStats(match);
  _playerStatsMemo.set(match, { games: match.games, players: match.players, sig, rows });
  return rows;
}

function playerStatsInMatch(match, playerName, mySchoolName, pairNames) {
  // ★相手ペアの集計（pairNamesあり）では、2人がそろって出ている側を探す。
  //   自チーム側だけを探す ownSideFor では相手選手が見つからず、相手分析の内訳がいつも空になっていた。
  const side = pairNames
    ? (["A","B"].find(t => pairNames.every(n => (match.players||[]).some(p => p.team===t && p.player_name===n))) || null)
    : ownSideFor(match, playerName, mySchoolName);
  if (!side) return null;
  const all = calcPlayerStatsMemo(match);
  return all.find(r => r.team === side && r.player_name === playerName) || null;
}

// 複数の試合をまたいで、指定選手のスタッツを合算する
// ============================================================
// 集計対象（スコープ）の共通処理：個人・ペア・チームで同じ条件指定を使う
// ============================================================
const DEFAULT_SCOPE = {
  period: "all",        // all | season | 1m | 3m | fy | range
  rangeStart: "", rangeEnd: "",
  tournaments: [],      // 大会名の配列。空＝すべて
  limit: 0,             // 0＝すべて（上限100）／それ以外は直近N試合
  kind: "all",          // all | individual | team
  pickedIds: [],        // 個別に選んだ試合ID。空でなければ他の条件より優先
};
const SCOPE_MAX = 100;   // スマホで快適に集計できる上限

// ★期間の開始日を求める（season＝シーズン設定の起点日）
function scopePeriodStart(scope, seasonStart) {
  const today = new Date();
  const fmt = d => d.toISOString().slice(0,10);
  switch (scope.period) {
    case "season": return seasonStart || null;
    case "1m":     { const d=new Date(today); d.setMonth(d.getMonth()-1); return fmt(d); }
    case "3m":     { const d=new Date(today); d.setMonth(d.getMonth()-3); return fmt(d); }
    case "fy":     { const y = today.getMonth()+1 >= 4 ? today.getFullYear() : today.getFullYear()-1; return `${y}-04-01`; }
    case "range":  return scope.rangeStart || null;
    default:       return null;
  }
}
function scopePeriodEnd(scope) {
  return scope.period === "range" ? (scope.rangeEnd || null) : null;
}

// ★条件を順に適用して、集計対象の試合を決める。
//   期間・大会・対象試合でしぼったあと、新しい順に「直近N試合」を取る。
function applyScope(matches, scope, { seasonStart, teamMatchIds } = {}) {
  if (scope.pickedIds && scope.pickedIds.length > 0) {
    const set = new Set(scope.pickedIds);
    return { list: matches.filter(m => set.has(m.id)), capped: 0 };
  }
  const start = scopePeriodStart(scope, seasonStart);
  const end   = scopePeriodEnd(scope);
  const tset  = new Set(scope.tournaments ?? []);
  let list = matches.filter(m => {
    const d = m.match_date || "";
    if (start && d < start) return false;
    if (end && d > end) return false;
    if (tset.size > 0 && !tset.has(m.tournament_name || "")) return false;
    if (scope.kind !== "all" && teamMatchIds) {
      const isTeam = teamMatchIds.has(m.id);
      if (scope.kind === "team" && !isTeam) return false;
      if (scope.kind === "individual" && isTeam) return false;
    }
    return true;
  });
  // 新しい順に並べてから必要数だけ取る
  list.sort((a,b) => {
    const d = new Date(b.match_date) - new Date(a.match_date);
    if (d !== 0) return d;
    return roundProgressRank(b.round) - roundProgressRank(a.round);
  });
  const want = scope.limit > 0 ? Math.min(scope.limit, SCOPE_MAX) : SCOPE_MAX;
  // ★「直近5試合」などで自分から数を絞った場合は、上限（100試合）で切ったわけではないので警告を出さない
  const capped = (scope.limit > 0 && scope.limit <= SCOPE_MAX) ? 0 : Math.max(0, list.length - want);
  list = list.slice(0, want);
  list.sort((a,b) => {
    const d = new Date(a.match_date) - new Date(b.match_date);
    if (d !== 0) return d;
    return roundProgressRank(a.round) - roundProgressRank(b.round);
  });
  return { list, capped };
}

// ★画面に1行で出すラベル（試合数だけを短く。細かい条件はシートを開けば分かる）
function scopeShortLabel(scope, seasonLabel) {
  if (scope.pickedIds && scope.pickedIds.length > 0) return `選んだ${scope.pickedIds.length}試合`;
  const n = scope.limit > 0 ? `直近${scope.limit}試合` : `すべて（上限${SCOPE_MAX}）`;
  if (scope.period === "season" && seasonLabel) return `${seasonLabel}以降・${n}`;
  return n;
}

// ★団体戦の番手として登録されている試合のIDを集める（対象試合のしぼり込みに使う）
// ★試合一覧を開いたときに作ったものがあれば使い回す（通信なし）。
//   以前は分析画面を開くたびに取得し直しており、しかも1000件で打ち切られていた。
async function getTeamMatchMatchIds() {
  const now = Date.now();
  if (_teamBoutIdsCache && now - _teamBoutIdsCache.at < MATCH_LIST_CACHE_MS) return new Set(await _teamBoutIdsCache.promise);
  const promise = fetchAllRows("team_match_games", "id, match_id", q => q.not("match_id", "is", null).order("id"))
    .then(({ data, error }) => {
      if (error) throw error;
      return new Set((data ?? []).map(r => r.match_id).filter(Boolean));
    });
  _teamBoutIdsCache = { at: now, promise };
  try {
    return new Set(await promise);
  } catch (e) {
    console.error(e);
    if (_teamBoutIdsCache?.promise === promise) _teamBoutIdsCache = null; // 失敗は覚えない
    return new Set();
  }
}

// ============================================================
// 相手ペアへのメモ（opponent_notes）
// ・相手ペアに紐づけて何件でも残せる。試合への紐づけは任意。
// ============================================================
async function getOpponentNotes(schoolId, pairKey) {
  if (!schoolId || !pairKey) return [];
  const { data, error } = await supabase.from("opponent_notes")
    .select("*").eq("school_id", schoolId).eq("pair_key", pairKey)
    .is("deleted_at", null).order("created_at", { ascending:false });
  if (error) { console.error(error); return []; }
  return data ?? [];
}
async function saveOpponentNote({ id, school_id, opponent_club, pair_key, pair_label, note_text, match_id }) {
  const payload = {
    id: id || uid(), school_id, opponent_club: opponent_club || "",
    pair_key, pair_label, note_text: note_text.trim(),
    match_id: match_id || null, updated_at: new Date().toISOString(),
  };
  const { error } = await supabase.from("opponent_notes").upsert(payload);
  if (error) throw error;
  return payload;
}
async function deleteOpponentNote(id) {
  const { error } = await supabase.from("opponent_notes")
    .update({ deleted_at: new Date().toISOString() }).eq("id", id);
  if (error) throw error;
}

// ★回戦名をトーナメントの進行順に並べるための順位（1回戦→…→決勝）。
//   同じ日に何試合もある大会で、試合を正しい順番に並べるために使う。
function roundProgressRank(round) {
  if (!round) return 999;
  const idx = ROUND_OPTIONS.indexOf(round);
  if (idx >= 0) return idx;
  const m = String(round).match(/(\d+)\s*回戦/);
  if (m) return 1 + Number(m[1]);
  return 900;
}

// ★ペアの識別キー：2人の名前を並べ替えて連結する（登録順が入れ替わっても同じペアとして扱う）
function pairKeyOf(nameA, nameB) {
  return [nameA, nameB].filter(Boolean).sort().join(" / ");
}
// ★ペアの表示名を「選手1（後衛）／選手2（前衛）」の順にそろえる。
//   同じペアでも試合ごとに入力順が違うことがあるため、そのペアの試合で一番多かった並び順を採用する。
//   votes は { "後衛名\t前衛名": 回数 } の形。
function majorityPairOrder(votes) {
  let best = null, bestN = -1;
  Object.entries(votes || {}).forEach(([k, n]) => { if (n > bestN) { best = k; bestN = n; } });
  return best ? best.split("\t") : [];
}
// ★ペアの表示名（キーと同じ並び順にして、画面ごとに前後が入れ替わらないようにする）
function pairLabelOf(nameA, nameB) {
  return [nameA, nameB].filter(Boolean).sort().join("・");
}
// ★指定した試合で、あるチーム側に出ていた2人をペアとして取り出す
function pairOnSide(m, team) {
  const list = m.players.filter(p => p.team === team).sort((a,b)=>(a.order_num??0)-(b.order_num??0));
  if (list.length < 2) return null;
  return {
    names: [list[0].player_name, list[1].player_name],
    key: pairKeyOf(list[0].player_name, list[1].player_name),
    label: pairLabelOf(list[0].player_name, list[1].player_name),
    club: list[0].club_name || list[1].club_name || "",
  };
}
// ★自チーム側／相手側のペアを取り出す（自チーム同士の試合ではA側を自チーム扱いにする）
function ownPairOf(m, mySchoolName) {
  const aIsOwn = m.players.some(p => p.team==="A" && p.club_name && mySchoolName && p.club_name.trim()===mySchoolName.trim());
  return pairOnSide(m, aIsOwn ? "A" : "A"); // 自チームは常にA側に保存されている
}
function oppPairOf(m) { return pairOnSide(m, "B"); }
// ★自チームがB側に記録されている試合（部内戦のB側・トーナメント表の簡易記録でB側）を、
//   A側＝自チームになるように左右を入れ替えた複製を作る（勝敗の集計用。idはそのまま）
function flipMatchSides(m) {
  const sw = (t) => t==="A" ? "B" : t==="B" ? "A" : t;
  return {
    ...m,
    players: (m.players||[]).map(p => ({ ...p, team: sw(p.team) })),
    match_score_a: m.match_score_b, match_score_b: m.match_score_a,
    walkover_winner: sw(m.walkover_winner),
    games: (m.games||[]).map(g => ({ ...g, winner_team: sw(g.winner_team) })),
    _flipped: true,
  };
}
// ★ペア・選手の勝敗集計に使う「自チーム側から見た試合」の一覧を作る。
//   ・通常の試合は自チームがA側に保存されているのでそのまま
//   ・部内戦（両側とも自チーム）は、B側のペアの分も入れ替えた複製を追加
//   ・トーナメント表の簡易記録は、自チームの学校名の側をA側にそろえる（どちらも他校なら除外）
function ownPerspectiveMatches(list, mySchoolName) {
  const my = (mySchoolName||"").trim();
  const clubOf = (m, t) => (m.players.find(p=>p.team===t && p.club_name)?.club_name || "").trim();
  const out = [];
  list.forEach(m => {
    if (!countsAsFinished(m)) return;
    const aClub = clubOf(m, "A"), bClub = clubOf(m, "B");
    if (m.is_simple_draw_result) {
      if (my && aClub === my) out.push(m);
      if (my && bClub === my) out.push(flipMatchSides(m));
      return;
    }
    if (!m.players.some(p => p.team==="A")) return;
    out.push(m);
    if (my && bClub === my) out.push(flipMatchSides(m));
  });
  return out;
}

function aggregatePlayerStats(fullMatches, playerName, mySchoolName, pairNames) {
  const agg = {
    total: 0, winners: 0, errors: 0, plays: {}, playsWin: {}, playsErr: {},
    serveTotal: 0, serveFault: 0, receiveTotal: 0, receiveMiss: 0, matchesCounted: 0,
    serve1st: 0, serve2nd: 0, serveDf: 0, serve1stWin: 0, serve2ndWin: 0,
    missTypes: {}, missTyped: 0, sideWin: {}, sideErr: {}, missCombos: {},
    courseWin: {}, courseErr: {},
    sideCourseWin: {}, sideCourseErr: {},
  };
  for (const m of fullMatches) {
    const s = playerStatsInMatch(m, playerName, mySchoolName, pairNames);
    if (!s) continue;
    agg.matchesCounted++;
    agg.total += s.total; agg.winners += s.winners; agg.errors += s.errors;
    agg.serveTotal += s.serveTotal; agg.serveFault += s.serveFault;
    agg.serve1st += s.serve1st ?? 0; agg.serve2nd += s.serve2nd ?? 0; agg.serveDf += s.serveDf ?? 0;
    agg.serve1stWin += s.serve1stWin ?? 0; agg.serve2ndWin += s.serve2ndWin ?? 0;
    agg.receiveTotal += s.receiveTotal; agg.receiveMiss += s.receiveMiss;
    for (const k in s.plays)    agg.plays[k]    = (agg.plays[k]    ?? 0) + s.plays[k];
    for (const k in s.playsWin) agg.playsWin[k] = (agg.playsWin[k] ?? 0) + s.playsWin[k];
    for (const k in s.playsErr) agg.playsErr[k] = (agg.playsErr[k] ?? 0) + s.playsErr[k];
    agg.missTyped += s.missTyped ?? 0;
    for (const k in (s.missTypes  ?? {})) agg.missTypes[k]  = (agg.missTypes[k]  ?? 0) + s.missTypes[k];
    for (const k in (s.sideWin    ?? {})) agg.sideWin[k]    = (agg.sideWin[k]    ?? 0) + s.sideWin[k];
    for (const k in (s.sideErr    ?? {})) agg.sideErr[k]    = (agg.sideErr[k]    ?? 0) + s.sideErr[k];
    for (const k in (s.missCombos ?? {})) agg.missCombos[k] = (agg.missCombos[k] ?? 0) + s.missCombos[k];
    for (const k in (s.courseWin  ?? {})) agg.courseWin[k]  = (agg.courseWin[k]  ?? 0) + s.courseWin[k];
    for (const k in (s.courseErr  ?? {})) agg.courseErr[k]  = (agg.courseErr[k]  ?? 0) + s.courseErr[k];
    for (const k in (s.sideCourseWin ?? {})) agg.sideCourseWin[k] = (agg.sideCourseWin[k] ?? 0) + s.sideCourseWin[k];
    for (const k in (s.sideCourseErr ?? {})) agg.sideCourseErr[k] = (agg.sideCourseErr[k] ?? 0) + s.sideCourseErr[k];
  }
  return agg;
}
// ★2人分の集計を足し合わせて「ペアの集計」にする
function aggregatePairStats(fullMatches, nameA, nameB, mySchoolName, isOpponent) {
  const pairNames = isOpponent ? [nameA, nameB] : undefined;
  const a = aggregatePlayerStats(fullMatches, nameA, mySchoolName, pairNames);
  const b = aggregatePlayerStats(fullMatches, nameB, mySchoolName, pairNames);
  const sum = { ...a };
  const numKeys = ["total","winners","errors","serveTotal","serveFault","receiveTotal","receiveMiss",
                   "serve1st","serve2nd","serveDf","serve1stWin","serve2ndWin","missTyped"];
  numKeys.forEach(k => { sum[k] = (a[k]??0) + (b[k]??0); });
  const mapKeys = ["plays","playsWin","playsErr","missTypes","sideWin","sideErr","missCombos",
                   "courseWin","courseErr","sideCourseWin","sideCourseErr"];
  mapKeys.forEach(k => {
    const merged = {};
    for (const key in (a[k]??{})) merged[key] = (merged[key]??0) + a[k][key];
    for (const key in (b[k]??{})) merged[key] = (merged[key]??0) + b[k][key];
    sum[k] = merged;
  });
  sum.matchesCounted = fullMatches.length;
  return { pair: sum, byPlayer: { [nameA]: a, [nameB]: b } };
}

// ★コース分析の集計（個人・ペアの両方で使う）。aggはaggregatePlayerStats/aggregatePairStatsの結果。
function buildCourseStats(agg) {
    const cell = (key) => {
      const win = agg.courseWin?.[key] ?? 0;
      const err = agg.courseErr?.[key] ?? 0;
      return { key, label: getCourseLabel(key), win, err, total: win + err };
    };
    const byKey = {};
    COURSE_TYPES.forEach(ct => { byKey[ct.key] = cell(ct.key); });
    const all = COURSE_TYPES.reduce((a, ct) => a + byKey[ct.key].total, 0);

    // ① 引っ張り／流しのどちらを多く打っているか
    const pull = byKey.pull.total;
    const nagashi = byKey.nagashi.total;

    // ② フォア／バックそれぞれの中での引っ張り／流し
    const scCell = (side, courseKey) => {
      const k = side + "__" + courseKey;
      return (agg.sideCourseWin?.[k] ?? 0) + (agg.sideCourseErr?.[k] ?? 0);
    };
    const sides = SIDE_TYPES.map(st => {
      const pullN = scCell(st.key, "pull"), nagashiN = scCell(st.key, "nagashi");
      return { side: st.key, label: st.label, total: pullN + nagashiN, pull: pullN, nagashi: nagashiN };
    });

    // ③ コース（引っ張り／流し）それぞれの決めた／ミス
    const rows = COURSE_TYPES.map(ct => byKey[ct.key]);

    // 気づきの一文（本数が少ないと割合が極端に出るため3本以上のコースだけを対象にする）
  let best = null, worst = null;
    rows.forEach(r => {
      if (r.total < 3) return;
      const rate = r.win / r.total;
      if (!best  || rate > best.rate)  best  = { ...r, rate };
      if (!worst || rate < worst.rate) worst = { ...r, rate };
    });

  return { all, pull, nagashi, sides, rows, best, worst };
}

// 合算スタッツから、画面表示用の主要指標（%）を計算する
function keyRatesFromAgg(agg) {
  return {
    serveRate: agg.serveTotal > 0 ? Math.round((1 - agg.serveFault / agg.serveTotal) * 100) : null,
    receiveMissRate: agg.receiveTotal > 0 ? Math.round(agg.receiveMiss / agg.receiveTotal * 100) : null,
    decisionRate: agg.total > 0 ? Math.round(agg.winners / agg.total * 100) : null,
  };
}


// ★一覧・集計用の試合取得（試合一覧／分析／選手別・対戦相手別成績／動画画面で共用）。
// 　これらの画面が使うのは「試合の基本情報」と「出場選手名」だけで、
// 　ゲームごとの得点(games)もポイント(points)も一切使っていない
// 　（必要な画面は個別に getMatch() / getFullMatchesByIds() で詳細を取り直している）。
// 　にもかかわらず全試合分の games まで取得していたため、
// 　試合数が増えるほど、これらの画面の表示が軒並み遅くなっていた。
// 　あわせて、以前は分割取得(チャンク)をforループ内でawaitしていたため、
// 　チャンクの数だけ通信の往復を「順番待ち」していた（例：600試合＝10回分の
// 　待ち時間の合計）。同時に投げることで待ち時間はほぼ1回分で済む。
// ★分析画面用：全試合一覧を1分間だけ使い回す（分析タブの切り替えや、試合を見て戻ったときに再取得しない）。
//   試合一覧画面など「今の状態」を必ず見せたい画面は、これまで通り getMatches() を使う。
async function getMatchesCached() {
  const now = Date.now();
  if (_matchListCache && now - _matchListCache.at < MATCH_LIST_CACHE_MS) return _matchListCache.promise;
  const promise = getMatches();
  _matchListCache = { at: now, promise };
  const list = await promise;
  if ((!list || list.length === 0) && _matchListCache?.promise === promise) _matchListCache = null; // 失敗・空は覚えない
  return list;
}

async function getMatches() {
  return perfTime("全試合一覧の取得(getMatches)", getMatchesInner);
}
async function getMatchesInner() {
  // ★1000件を超えても全試合を取れるよう、分けて取得する（以前は1000件で打ち切られていた）
  const { data, error } = await fetchAllRows("matches", "*", q => q
    .is("deleted_at", null)
    .order("created_at", { ascending: false })
    .order("id"));
  if (error) { console.error(error); return []; }
  if (!data || data.length === 0) { _lastMatchListData = { at: Date.now(), list: [] }; return []; }

  const matchIds = data.map(m => m.id);
  const CHUNK_SIZE = 100;
  const chunks = [];
  for (let i = 0; i < matchIds.length; i += CHUNK_SIZE) chunks.push(matchIds.slice(i, i + CHUNK_SIZE));

  const results = await Promise.all(chunks.map(chunkIds =>
    supabase.from("match_players")
      .select("id, match_id, team, player_name, club_name, position, order_num, entry_no")
      .in("match_id", chunkIds)
  ));

  const playersByMatch = {};
  results.forEach(({ data: rows, error: err }) => {
    if (err) console.error(err);
    (rows ?? []).forEach(p => { (playersByMatch[p.match_id] ??= []).push(p); });
  });
  // 並び順（A→B、番号順）はDB側ではなくここで整える（通信量・待ち時間を増やさないため）
  Object.values(playersByMatch).forEach(list => list.sort((a, b) =>
    a.team === b.team ? (a.order_num ?? 0) - (b.order_num ?? 0) : (a.team < b.team ? -1 : 1)
  ));

  const list = data.map(m => rowToMatchSummary(m, playersByMatch[m.id] ?? [], []));
  _lastMatchListData = { at: Date.now(), list };
  return list;
}

// ★ホーム画面専用の軽量データ取得。
// 　ホーム画面が実際に使うのは「進行中の試合」「直近数件の試合カード」
// 　「全体の勝敗数・直近の調子」「紐づけ選手（自分／お子さん）の勝敗」だけで、
// 　ゲームごとの得点(games)は一切使っていない。以前はgetMatches()で
// 　チームの利用期間中の全試合をgames付きで取得していたため、試合数が
// 　増えるほどホーム画面の表示が遅くなっていた。
async function getHomeScreenData(linkedPlayerName) {
  // ★紐づけ選手（自分／お子さん）の出場試合の検索は、試合一覧の取得結果に依存しないので
  //   最初から同時に走らせる（以前は試合を取り終えてから、さらにもう1往復待っていた）。
  const [
    { data: matchRows, error: mErr },
    { data: linkedRows, error: lErr },
  ] = await Promise.all([
    supabase
      .from("matches")
      .select("id, match_date, tournament_name, status, match_score_a, match_score_b, walkover_winner, game_format, created_at")
      .is("deleted_at", null)
      .order("created_at", { ascending: false }),
    linkedPlayerName
      ? supabase.from("match_players").select("match_id, team, club_name").eq("player_name", linkedPlayerName)
      : Promise.resolve({ data: [], error: null }),
  ]);
  if (mErr) { console.error(mErr); return { allMatchesLite: [], liveMatch: null, recent: [], upcoming: [], linkedMatches: [] }; }
  if (lErr) console.error(lErr);

  const allMatchesLite = matchRows ?? [];

  // カード表示（進行中の試合／これからの試合／終わった試合）に必要な出場選手だけ、対象を絞って取得する
  const liveRow = allMatchesLite.find(m => m.status === "active");
  // ★以前は「作成が新しい順に3件」をまとめて『最近の試合』として出していたため、
  //   これから先の予定が『最近の試合』として並んでしまい分かりにくかった。
  //   「これからの試合（予定）」と「終わった試合」に分けて、それぞれ適切な順番で並べる。
  const byDateAsc  = (a,b) => String(a.match_date??"").localeCompare(String(b.match_date??""));
  const byDateDesc = (a,b) => String(b.match_date??"").localeCompare(String(a.match_date??""));
  // ★「これから」なので、日付が過ぎたまま残っている予定は除く。
  //   （結局やらなかった試合や古いテストデータが、いつまでも先頭に居座ってしまうため）
  const todayStr = today();
  const upcomingRows = allMatchesLite
    .filter(m => (m.status === "scheduled" || m.status === "waiting") && String(m.match_date ?? "") >= todayStr)
    .sort(byDateAsc)     // 日付が近いものから
    .slice(0, 3);
  const recentRows = allMatchesLite
    .filter(m => m.status === "finished" || m.status === "abandoned" || m.status === "suspended")
    .sort(byDateDesc)    // 新しく行われたものから
    .slice(0, 3);
  const cardIds = Array.from(new Set([liveRow?.id, ...upcomingRows.map(m => m.id), ...recentRows.map(m => m.id)].filter(Boolean)));
  const playersByMatch = {};
  if (cardIds.length > 0) {
    const { data: playersData, error: pErr } = await supabase
      .from("match_players").select("match_id, team, player_name, club_name").in("match_id", cardIds);
    if (pErr) console.error(pErr);
    (playersData ?? []).forEach(p => { (playersByMatch[p.match_id] ??= []).push(p); });
  }
  const withPlayers = (row) => row ? { ...row, players: playersByMatch[row.id] ?? [] } : null;
  const liveMatch = withPlayers(liveRow);
  const recent = recentRows.map(withPlayers);
  const upcoming = upcomingRows.map(withPlayers);

  // ★紐づけ選手（自分／お子さん）の対戦履歴：match_playersを起点にその選手の
  //   出場試合IDだけに絞り込む（全試合の選手データを経由しない）
  let linkedMatches = [];
  if (linkedPlayerName) {
    const rowByMatch = {};
    (linkedRows ?? []).forEach(r => { rowByMatch[r.match_id] = r; });
    linkedMatches = allMatchesLite
      .filter(m => rowByMatch[m.id])
      .map(m => ({ ...m, players: [{ player_name: linkedPlayerName, team: rowByMatch[m.id].team, club_name: rowByMatch[m.id].club_name }] }));
  }

  return { allMatchesLite, liveMatch, recent, upcoming, linkedMatches };
}

// 試合1件を、関連テーブルすべて含めて取得
async function getMatch(id) {
  if (!id) return null;
  // ★試合本体と明細（選手・ゲーム・ポイント・フォルト）を同時に取得する。
  //   以前は試合本体を取ってから明細を取っていたため、通信の往復が2回かかっていた。
  const [
    { data: m, error },
    { data: players, error: playersErr },
    { data: games, error: gamesErr },
    { data: points, error: pointsErr },
    { data: faults, error: faultsErr },
  ] = await Promise.all([
    supabase.from("matches").select("*").eq("id", id).single(),
    supabase.from("match_players").select("*").eq("match_id", id).order("team").order("order_num"),
    supabase.from("games").select("*").eq("match_id", id).order("game_number"),
    supabase.from("points").select("*").eq("match_id", id).order("point_number"),
    supabase.from("faults").select("*").eq("match_id", id).order("fault_number"),
  ]);
  if (error || !m) { console.error(error); return null; }
  // ★重要：ここでエラーを握りつぶして空配列のまま先に進めてしまうと、
  // 　その後に何らかの保存操作（メモ編集・中断/途中終了フラグなど）が行われた際、
  // 　saveMatch()の「クライアント側に無い行を削除する」処理により、
  // 　本当は存在していたgames/points/faultsが誤って全削除されてしまう危険がある。
  // 　そのため、一部でも取得に失敗した場合はここで確実にエラーにする。
  const fetchErr = playersErr || gamesErr || pointsErr || faultsErr;
  if (fetchErr) { console.error(fetchErr); throw new Error("試合データの取得に失敗しました。再読み込みしてください。"); }

  return rowToMatchFull(m, players ?? [], games ?? [], points ?? [], faults ?? []);
}

// ★試合に紐づけるYouTube動画リンク（複数登録できる）
//   ・DBには matches.video_links（jsonb）に [{id, title, url}] の配列で保存する
//   ・古いデータや壊れた値が入っていても落ちないよう、読み込み時に必ずこの関数を通す
function youtubeIdOf(url) {
  if (!url) return null;
  const m = String(url).match(/(?:youtu\.be\/|[?&]v=|embed\/|shorts\/|live\/)([A-Za-z0-9_-]{11})/);
  return m ? m[1] : null;
}
function youtubeThumbOf(videoId) {
  return `https://img.youtube.com/vi/${videoId}/hqdefault.jpg`;
}
function normalizeVideoLinks(raw) {
  let arr = raw;
  if (typeof arr === "string") { try { arr = JSON.parse(arr); } catch { arr = []; } }
  if (!Array.isArray(arr)) return [];
  return arr
    .map(v => {
      if (!v) return null;
      const url = typeof v === "string" ? v : (v.url || "");
      const id = youtubeIdOf(url);
      if (!id) return null;
      const title = (typeof v === "object" && v.title) ? String(v.title) : "";
      return { id, title, url: `https://youtu.be/${id}` };
    })
    .filter(Boolean);
}

function rowToMatchSummary(m, players=[], games=[]) {
  return {
    id: m.id, created_by: m.created_by,
    match_date: m.match_date, venue: m.venue ?? "",
    tournament_name: m.tournament_name ?? "", round: m.round ?? "",
    match_number: m.match_number ?? "",
    match_type: m.match_type, game_format: m.game_format,
    is_doubles: m.is_doubles, first_server: m.first_server, status: m.status,
    order_a: m.order_a === "p2" ? "p2" : "p1", order_b: m.order_b === "p2" ? "p2" : "p1",
    receive_order_a: m.receive_order_a === "p2" ? "p2" : m.receive_order_a === "p1" ? "p1" : null, receive_order_b: m.receive_order_b === "p2" ? "p2" : m.receive_order_b === "p1" ? "p1" : null,
    match_score_a: m.match_score_a, match_score_b: m.match_score_b,
    memo: m.memo ?? "",
    video_links: normalizeVideoLinks(m.video_links),
    court_number: m.court_number ?? "",
    is_younger: m.is_younger === true,
    walkover_winner: m.walkover_winner ?? null,
    players: players.map(p => ({
      id: p.id, team: p.team, player_name: p.player_name,
      club_name: p.club_name ?? "", position: p.position ?? "", order_num: p.order_num,
      entry_no: p.entry_no ?? null,
    })),
    games: games.map(g => ({
      id: g.id, game_number: g.game_number, is_final: g.is_final,
      score_a: g.score_a, score_b: g.score_b, winner_team: g.winner_team,
      points: g.points ?? [],
    })),
  };
}

function rowToMatchFull(m, players, games, points, faults) {
  // ★ゲームごとに全ポイントをfilterし直すと、試合数×ゲーム数×ポイント数の処理になるため、先にゲーム別に分けておく
  const pointsByGame = {};
  for (const pt of points) (pointsByGame[pt.game_id] ??= []).push(pt);
  const faultsByGame = {};
  for (const f of faults) (faultsByGame[f.game_id] ??= []).push(f);
  return {
    id: m.id, created_by: m.created_by,
    // ★記録者ロック（今この試合を記録している人）。観戦モードの「○○ 記録中」表示に使う。
    recorder_id: m.recorder_id ?? null, recorder_name: m.recorder_name ?? null,
    match_date: m.match_date, venue: m.venue ?? "",
    tournament_name: m.tournament_name ?? "", round: m.round ?? "",
    match_number: m.match_number ?? "",
    match_type: m.match_type, game_format: m.game_format,
    is_doubles: m.is_doubles, first_server: m.first_server, status: m.status,
    order_a: m.order_a === "p2" ? "p2" : "p1", order_b: m.order_b === "p2" ? "p2" : "p1",
    receive_order_a: m.receive_order_a === "p2" ? "p2" : m.receive_order_a === "p1" ? "p1" : null, receive_order_b: m.receive_order_b === "p2" ? "p2" : m.receive_order_b === "p1" ? "p1" : null,
    match_score_a: m.match_score_a, match_score_b: m.match_score_b,
    memo: m.memo ?? "",
    video_links: normalizeVideoLinks(m.video_links),
    court_number: m.court_number ?? "",
    is_younger: m.is_younger === false ? false : true,
    walkover_winner: m.walkover_winner ?? null,
    players: players.map(p => ({
      id: p.id, team: p.team, player_name: p.player_name,
      club_name: p.club_name ?? "", position: p.position ?? "", order_num: p.order_num,
      entry_no: p.entry_no ?? null,
    })),
    games: games.map(g => ({
      id: g.id, match_id: m.id, game_number: g.game_number, server_team: g.server_team,
      is_final: g.is_final, score_a: g.score_a, score_b: g.score_b, winner_team: g.winner_team,
      faults: (faultsByGame[g.id] ?? []).map(f => ({
        id: f.id, game_id: f.game_id, match_id: m.id, fault_number: f.fault_number,
        server_team: f.server_team, player_name: f.player_name,
        score_a_at: f.score_a_at, score_b_at: f.score_b_at,
      })),
      points: (pointsByGame[g.id] ?? []).map(pt => ({
        id: pt.id, game_id: pt.game_id, match_id: m.id, point_number: pt.point_number,
        scoring_team: pt.scoring_team, player_name: pt.player_name,
        play_type: pt.play_type ?? null, side_type: pt.side_type ?? null, course_type: pt.course_type ?? null, miss_type: pt.miss_type ?? null, result_type: pt.result_type ?? null,
        is_winner: pt.is_winner, fault_count: pt.fault_count ?? 0, score_a_after: pt.score_a_after, score_b_after: pt.score_b_after,
        scored_at: pt.scored_at ?? null, // ★動画同期用：得点を記録した時刻
      })),
    })),
  };
}

// ★記録者ロックの値を決める。
//   ・試合が終了／中断／途中終了になったらロックを外す（次に誰でも記録を引き継げるように）
//   ・進行中なのにロックが空なら、いま保存している人を記録者にする（新規に試合を始めた人＝記録者）
//   ・それ以外は今のロックをそのまま維持する
async function resolveRecorderFields(match, user) {
  const ended = match.status === "finished" || match.status === "suspended" || match.status === "abandoned";
  if (ended) return { recorder_id: null, recorder_name: null };
  if (match.status === "active" && !match.recorder_id && user) {
    const profile = await getMyProfile();
    return { recorder_id: user.id, recorder_name: profile?.name || null };
  }
  return { recorder_id: match.recorder_id ?? null, recorder_name: match.recorder_name ?? null };
}

// ============================================================
// ★保存する行の形（全部保存・差分保存・保存済みの記録で共通に使う）
// ============================================================
const playerRowOf = (p, matchId) => ({
  id: p.id, match_id: matchId, team: p.team, player_name: p.player_name,
  club_name: p.club_name || null, position: p.position || null, order_num: p.order_num,
  entry_no: p.entry_no || null,
});
const gameRowOf = (g, matchId) => ({
  id: g.id, match_id: matchId, game_number: g.game_number, server_team: g.server_team,
  is_final: g.is_final, score_a: g.score_a, score_b: g.score_b, winner_team: g.winner_team || null,
});
const pointRowOf = (pt, g, matchId) => ({
  id: pt.id, game_id: g.id, match_id: matchId, point_number: pt.point_number,
  scoring_team: pt.scoring_team, player_name: pt.player_name || null,
  shot_type: toShotType(pt.play_type, pt.result_type),
  play_type: pt.play_type || null, side_type: pt.side_type || null, course_type: pt.course_type || null, miss_type: pt.miss_type || null, result_type: pt.result_type || null,
  is_winner: pt.is_winner, fault_count: pt.fault_count ?? 0, score_a_after: pt.score_a_after, score_b_after: pt.score_b_after,
  scored_at: pt.scored_at || null, // ★動画同期用：得点を記録した時刻
});
const faultRowOf = (f, g, matchId) => ({
  id: f.id, game_id: g.id, match_id: matchId, fault_number: f.fault_number,
  server_team: f.server_team, player_name: f.player_name || null,
  score_a_at: f.score_a_at, score_b_at: f.score_b_at,
});
// 変わったかどうかの比較に使う文字列（得点時刻は作った後に変わらないうえ、DBから読むと書式が変わるため比較から外す）
const rowKeyOf = (row) => JSON.stringify({ ...row, scored_at: undefined, is_winner: row.is_winner ?? null });

// ★DBに保存済みの内容の控え（試合ID -> 控え）。記録中の1点ごとの保存では、この控えと比べて
//   「変わった行だけ」を送る。控えは、全部保存が成功したとき・記録画面でDBから読み込んだときに作り直す。
//   DBをこの仕組みの外から書き換える処理（リセット・名前の置き換え・削除など）では必ず捨てる。
const _savedMatchSnapshots = new Map();
function makeSavedSnapshot(match) {
  const mid = match.id;
  const games = new Map(), points = new Map(), faults = new Map();
  (match.games ?? []).forEach(g => {
    games.set(g.id, rowKeyOf(gameRowOf(g, mid)));
    (g.points ?? []).forEach(pt => points.set(pt.id, rowKeyOf(pointRowOf(pt, g, mid))));
    (g.faults ?? []).forEach(f => faults.set(f.id, rowKeyOf(faultRowOf(f, g, mid))));
  });
  return {
    status: match.status,
    playersKey: JSON.stringify((match.players ?? []).map(p => playerRowOf(p, mid))),
    games, points, faults,
  };
}
function seedSavedSnapshot(match) { if (match?.id) _savedMatchSnapshots.set(match.id, makeSavedSnapshot(match)); }
function dropSavedSnapshot(matchId) { if (matchId) _savedMatchSnapshots.delete(matchId); else _savedMatchSnapshots.clear(); }

// 試合の行を保存する（動画リンクの列がまだ無い環境では、その項目だけ外して保存し直す）
async function upsertMatchRow(matchRow) {
  let { error: mErr } = await supabase.from("matches").upsert(matchRow);
  // ★video_links 列がまだ無い場合は、その項目だけ外して保存し直す。
  //   動画リンクは保存されないが、スコア・メモなど本体の記録は必ず守る。
  if (mErr && matchRow.video_links && /video_links/.test(mErr.message || "")) {
    console.warn("saveMatch: video_links列が無いため、動画リンクを除いて保存します。");
    const { video_links, ...rowWithoutVideo } = matchRow;
    ({ error: mErr } = await supabase.from("matches").upsert(rowWithoutVideo));
  }
  if (mErr) throw mErr;
}
async function deleteRowsByIds(table, ids) {
  if (!ids.length) return;
  const CHUNK = 150;
  for (let i = 0; i < ids.length; i += CHUNK) {
    const { error } = await supabase.from(table).delete().in("id", ids.slice(i, i + CHUNK));
    if (error) throw error;
  }
}
// ★ポイント（フォルト）をまとめて保存する。番号の重複で弾かれたときは、そのゲームの分を一度消して入れ直す
//   （入れ直す内容は手元にある今の内容そのものなので、記録は消えない）
async function upsertNumberedRows(table, rows, numberField, allRowsOfGame) {
  if (!rows.length) return;
  let { error } = await supabase.from(table).upsert(rows);
  if (error && new RegExp(numberField).test(error.message || "")) {
    console.warn(`saveMatch: ${table} の番号の重複を検出したため、ゲーム単位で作り直します。`);
    const gameIds = Array.from(new Set(rows.map(r => r.game_id)));
    for (const gid of gameIds) {
      const { error: dErr } = await supabase.from(table).delete().eq("game_id", gid);
      if (dErr) throw dErr;
      const all = allRowsOfGame(gid);
      if (all.length) {
        const { error: iErr } = await supabase.from(table).insert(all);
        if (iErr) throw iErr;
      }
    }
    return;
  }
  if (error) throw error;
}

// ★記録中の1点ごとの保存（差分保存）。控えと比べて変わった行だけを送る。
//   以前は1点ごとに「選手の消して入れ直し・全ゲームの保存・消えた記録の確認」を順番に行い、12〜20往復かかっていた。
//   ふだんの1点は「試合・そのゲーム・そのポイント」を同時に送る1往復で済む。
async function saveMatchIncremental(match, matchRow, snap) {
  const mid = match.id;
  const games = match.games ?? [];
  const gameRows = games.map(g => gameRowOf(g, mid));
  const pointRows = [], faultRows = [];
  games.forEach(g => {
    (g.points ?? []).forEach(pt => pointRows.push(pointRowOf(pt, g, mid)));
    (g.faults ?? []).forEach(f => faultRows.push(faultRowOf(f, g, mid)));
  });
  const has = (list) => { const set = new Set(list.map(r => r.id)); return (id) => set.has(id); };
  const hasGame = has(gameRows), hasPoint = has(pointRows), hasFault = has(faultRows);
  const staleGameIds  = [...snap.games.keys()].filter(id => !hasGame(id));
  const stalePointIds = [...snap.points.keys()].filter(id => !hasPoint(id));
  const staleFaultIds = [...snap.faults.keys()].filter(id => !hasFault(id));
  const changedGames  = gameRows.filter(r => snap.games.get(r.id) !== rowKeyOf(r));
  const changedPoints = pointRows.filter(r => snap.points.get(r.id) !== rowKeyOf(r));
  const changedFaults = faultRows.filter(r => snap.faults.get(r.id) !== rowKeyOf(r));
  const hasNewGame = changedGames.some(r => !snap.games.has(r.id));
  const playersChanged = JSON.stringify((match.players ?? []).map(p => playerRowOf(p, mid))) !== snap.playersKey;
  const pointsOfGame = (gid) => pointRows.filter(r => r.game_id === gid);
  const faultsOfGame = (gid) => faultRows.filter(r => r.game_id === gid);

  // ① 消えたポイント・フォルトを先に消す（番号を振り直したとき、同じ番号の行とぶつからないように）
  if (stalePointIds.length || staleFaultIds.length) {
    await Promise.all([deleteRowsByIds("points", stalePointIds), deleteRowsByIds("faults", staleFaultIds)]);
  }
  // ② 試合・ゲーム・ポイントを同時に保存する。
  //   新しいゲームがあるときだけ、ゲームを先に保存してからポイントを保存する（ポイントの親がまだ無いと保存できないため）
  const saveNumbered = () => Promise.all([
    upsertNumberedRows("points", changedPoints, "point_number", pointsOfGame),
    upsertNumberedRows("faults", changedFaults, "fault_number", faultsOfGame),
  ]);
  const first = [upsertMatchRow(matchRow)];
  if (playersChanged) {
    first.push((async () => {
      const { error: dErr } = await supabase.from("match_players").delete().eq("match_id", mid);
      if (dErr) throw dErr;
      if (match.players?.length) {
        const { error: pErr } = await supabase.from("match_players").insert(match.players.map(p => playerRowOf(p, mid)));
        if (pErr) throw pErr;
      }
    })());
  }
  if (changedGames.length) {
    first.push((async () => { const { error } = await supabase.from("games").upsert(changedGames); if (error) throw error; })());
  }
  if (!hasNewGame) first.push(saveNumbered());
  await Promise.all(first);
  if (hasNewGame) await saveNumbered();
  // ③ 消えたゲームは最後に消す（ポイントが先に消えていないと消せないため）
  if (staleGameIds.length) await deleteRowsByIds("games", staleGameIds);
}

// 試合1件を関連テーブルごと保存（新規・更新どちらも対応）
// ★isNew: 今まさに新しく作る試合（IDを新しく発行したばかりで、DBにまだ何も無い）ときだけ true にする。
//   その場合は「既存の行の確認・削除」を全部省き、試合と選手を入れるだけにする（通信が約10往復→2往復）。
// ★incremental: 記録中の1点ごとの保存。保存済みの控えがあれば、変わった行だけを送る（控えが無いときは全部保存）。
async function saveMatch(match, { isNew = false, incremental = false } = {}) {
  invalidateMatchCaches(match?.id); // ★分析画面のキャッシュに古い内容が残らないように
  // ★ログイン確認は端末内の情報で行う（以前は毎回サーバーに問い合わせていた。書き込みの権限はRLSで守られている）
  const user = await getAuthUserFast();
  if (!user) throw new Error("ログインしていません");

  const matchRow = {
    id: match.id, created_by: (match.created_by && match.created_by !== "me") ? match.created_by : user.id,
    match_date: match.match_date, venue: match.venue || null,
    tournament_name: match.tournament_name || null, round: match.round || null,
    match_number: match.match_number || null,
    match_type: match.match_type, game_format: match.game_format,
    is_doubles: match.is_doubles, first_server: match.first_server, status: match.status,
    order_a: match.order_a === "p2" ? "p2" : "p1", order_b: match.order_b === "p2" ? "p2" : "p1",
    // ★レシーブの1人目（サーブとは別）。未設定(null)の古い試合は、サーブの1人目と同じ人として扱う
    receive_order_a: match.receive_order_a === "p2" ? "p2" : match.receive_order_a === "p1" ? "p1" : null,
    receive_order_b: match.receive_order_b === "p2" ? "p2" : match.receive_order_b === "p1" ? "p1" : null,
    match_score_a: match.match_score_a, match_score_b: match.match_score_b,
    memo: match.memo || null,
    court_number: match.court_number || null,
    is_younger: match.is_younger !== false,
    walkover_winner: match.walkover_winner || null,
    // ★記録者ロック：今この試合のスコアを記録している人。団体戦(team_match_games)と同じ考え方。
    //   試合を作る人と実際に記録する人は別なことが多いので、created_byとは分けて持つ。
    ...(await resolveRecorderFields(match, user)),
  };
  // ★動画リンクは「登録されているときだけ」保存する。
  //   毎回この項目を送っていると、DB側に video_links 列が無い環境では
  //   スコアや試合メモの保存まで丸ごと失敗してしまうため。
  //   （列が無い環境でも、動画リンクを使わない限り記録は普通に続けられる）
  const videoLinks = normalizeVideoLinks(match.video_links);
  if (videoLinks.length > 0) matchRow.video_links = videoLinks;

  // ★差分保存：控えがあり、状態（進行中→終了など）が変わっておらず、選手・ゲームが空でないときだけ使う。
  //   状態が変わるとき（試合終了・中断など）や、いつもと違う形の保存は、念のため全部保存で確認し直す。
  const snap = _savedMatchSnapshots.get(match.id);
  if (incremental && !isNew && snap && snap.status === match.status
      && (match.games?.length ?? 0) > 0 && (match.players?.length ?? 0) > 0) {
    try {
      await saveMatchIncremental(match, matchRow, snap);
      seedSavedSnapshot(match);
      return matchRow;
    } catch (e) {
      // 途中で失敗したときは控えを捨てる（次の保存は全部保存でDBと突き合わせ直す）
      dropSavedSnapshot(match.id);
      throw e;
    }
  }
  // ここから先は全部保存。途中で失敗しても控えがずれないよう、先に捨てておく（成功したら作り直す）
  dropSavedSnapshot(match.id);
  // ★確認・削除のどれかが失敗していたら、DBと手元が一致しているとは言えないので控えを作らない
  let cleanOk = true;
  const chk = (res) => { if (res?.error) { cleanOk = false; console.error(res.error); } return res; };

  await upsertMatchRow(matchRow);

  // ★新しく作る試合（まだゲームが無い）は、選手を入れるだけで保存完了
  if (isNew && !(match.games?.length)) {
    if (match.players?.length) {
      const { error: pErr } = await supabase.from("match_players").insert(match.players.map(p => playerRowOf(p, match.id)));
      if (pErr) throw pErr;
    }
    seedSavedSnapshot(match);
    return matchRow;
  }

  // 選手情報：一旦削除してから入れ直す（シンプルで確実な方式）
  // ★安全装置：本来選手が登録されているはずの試合で、保存内容の選手が0人の場合は
  // 　取得エラー等で空のまま読み込んでしまった可能性が高いため、削除をスキップして実データを保護する
  const { data: existingPlayers } = chk(await supabase.from("match_players").select("id").eq("match_id", match.id));
  const playersLooksLikeAccidentalWipe = !(match.players?.length) && (existingPlayers ?? []).length > 0;
  if (playersLooksLikeAccidentalWipe) {
    console.error("saveMatch: 既存のmatch_playersがあるのに保存内容が空のため、削除処理をスキップしました。match_id=", match.id);
  } else {
    chk(await supabase.from("match_players").delete().eq("match_id", match.id));
    if (match.players?.length) {
      const playerRows = match.players.map(p => playerRowOf(p, match.id));
      const { error: pErr } = await supabase.from("match_players").insert(playerRows);
      if (pErr) throw pErr;
    }
  }

  // ゲーム・ポイント・フォルト：
  // ★以前は「全部削除→全部挿入」の順で処理していたが、連続でスコア登録が走ると
  // 　保存の合間に「ポイントはあるがその親のゲーム行がまだ存在しない」瞬間ができてしまい、
  // 　外部キー制約違反（points_game_id_fkey）でエラーになることがあった。
  // 　そのため、先に現在の内容をすべて保存（upsert）し、その後で
  // 　クライアント側に無くなった（削除された）行だけを掃除する順番に変更した。
  //
  // ★ただしそれだけだと、ポイントを修正・削除して番号が振り直された場合に
  // 　「消すべき古い行がまだ残っているのに、同じ番号の新しい行を入れようとする」状態になり、
  // 　points_game_id_point_number_key（同じゲーム内で番号が重複）で保存が止まってしまう。
  // 　そこで、ポイントとフォルトの「もう存在しない行の削除」だけは先に済ませておく。
  // 　（ゲーム行の削除は後のまま。先に消すと、まだ保存していないポイントの親が居なくなるため）
  {
    const keepPointIds = (match.games ?? []).flatMap(g => (g.points ?? []).map(p => p.id));
    const keepFaultIds = (match.games ?? []).flatMap(g => (g.faults ?? []).map(f => f.id));
    const { data: existingPointsBefore } = chk(await supabase.from("points").select("id").eq("match_id", match.id));
    const stalePointIdsBefore = (existingPointsBefore ?? []).map(r => r.id).filter(id => !keepPointIds.includes(id));
    if (stalePointIdsBefore.length) chk(await supabase.from("points").delete().in("id", stalePointIdsBefore));

    const { data: existingFaultsBefore } = chk(await supabase.from("faults").select("id").eq("match_id", match.id));
    const staleFaultIdsBefore = (existingFaultsBefore ?? []).map(r => r.id).filter(id => !keepFaultIds.includes(id));
    if (staleFaultIdsBefore.length) chk(await supabase.from("faults").delete().in("id", staleFaultIdsBefore));
  }

  for (const g of (match.games ?? [])) {
    const gameRow = gameRowOf(g, match.id);
    const { error: gErr } = await supabase.from("games").upsert(gameRow);
    if (gErr) throw gErr;

    if (g.points?.length) {
      const pointRows = g.points.map(pt => pointRowOf(pt, g, match.id));
      let { error: ptErr } = await supabase.from("points").upsert(pointRows);
      // ★それでも番号の重複で弾かれた場合の最後の手段：
      //   そのゲームのポイントを一度すべて消してから入れ直す。
      //   （記録が消えないよう、入れ直す内容は手元にある今の内容そのもの）
      if (ptErr && /point_number/.test(ptErr.message || "")) {
        console.warn("saveMatch: ポイント番号の重複を検出したため、ゲーム" + g.game_number + "を作り直します。");
        chk(await supabase.from("points").delete().eq("game_id", g.id));
        ({ error: ptErr } = await supabase.from("points").insert(pointRows));
      }
      if (ptErr) throw ptErr;
    }
    if (g.faults?.length) {
      const faultRows = g.faults.map(f => faultRowOf(f, g, match.id));
      let { error: fErr } = await supabase.from("faults").upsert(faultRows);
      if (fErr && /fault_number/.test(fErr.message || "")) {
        chk(await supabase.from("faults").delete().eq("game_id", g.id));
        ({ error: fErr } = await supabase.from("faults").insert(faultRows));
      }
      if (fErr) throw fErr;
    }
  }

  // クライアント側に存在しなくなった行（1点前に戻す、修正で削除、等）だけを後から掃除する
  const currentGameIds = (match.games ?? []).map(g => g.id);
  const currentPointIds = (match.games ?? []).flatMap(g => (g.points ?? []).map(p => p.id));
  const currentFaultIds = (match.games ?? []).flatMap(g => (g.faults ?? []).map(f => f.id));

  const { data: existingGames } = chk(await supabase.from("games").select("id").eq("match_id", match.id));

  // ★安全装置：本来ゲームが存在するはずの試合で、今回保存しようとしている内容にゲームが
  // 　1件も無い場合、それは「取得エラーなどで空のまま読み込んでしまった」可能性が高い。
  // 　このケースで無条件に削除処理を走らせると、既存のgames/points/faultsが全消失してしまうため、
  // 　スコアを本当にゼロへ戻したい場合は必ずresetMatchToUnrecorded()の専用フローを使う前提とし、
  // 　ここでは削除をスキップして実データを保護する。
  const looksLikeAccidentalWipe = currentGameIds.length === 0 && (existingGames ?? []).length > 0;

  if (!looksLikeAccidentalWipe) {
    const { data: existingPoints } = chk(await supabase.from("points").select("id").eq("match_id", match.id));
    const stalePointIds = (existingPoints ?? []).map(r => r.id).filter(id => !currentPointIds.includes(id));
    if (stalePointIds.length) chk(await supabase.from("points").delete().in("id", stalePointIds));

    const { data: existingFaults } = chk(await supabase.from("faults").select("id").eq("match_id", match.id));
    const staleFaultIds = (existingFaults ?? []).map(r => r.id).filter(id => !currentFaultIds.includes(id));
    if (staleFaultIds.length) chk(await supabase.from("faults").delete().in("id", staleFaultIds));

    const staleGameIds = (existingGames ?? []).map(r => r.id).filter(id => !currentGameIds.includes(id));
    if (staleGameIds.length) chk(await supabase.from("games").delete().in("id", staleGameIds));
  } else {
    console.error("saveMatch: 既存のgamesがあるのに保存内容が空のため、削除処理をスキップしました。match_id=", match.id);
  }
  // ★DBの中身が手元と一致していると言えるときだけ、差分保存用の控えを作る
  //   （安全装置で削除をスキップした場合は、DBに手元に無い行が残っているので作らない）
  if (cleanOk && !looksLikeAccidentalWipe && !playersLooksLikeAccidentalWipe) seedSavedSnapshot(match);
  return matchRow;
}

// ★誤削除対策のため、即時完全削除ではなくゴミ箱行き（論理削除）にする
// ★削除したものを、スマホ本体の「戻る」用の画面履歴から取り除くための通知。
//   これが無いと、削除した試合の記録画面などが履歴に残っていて、戻るで開けてしまう。
function notifyDeleted(kind, ids) {
  try { window.dispatchEvent(new CustomEvent("st:deleted", { detail: { kind, ids: (Array.isArray(ids) ? ids : [ids]).filter(Boolean) } })); } catch (e) { /* 通知できなくても削除自体は続ける */ }
}
// ★ゴミ箱から元に戻したときは、「削除済み」の印を外す（また履歴に残せるように）
function notifyRestored(kind, id) {
  try { window.dispatchEvent(new CustomEvent("st:restored", { detail: { kind, id } })); } catch (e) {}
}
async function deleteMatch(id) {
  invalidateMatchCaches(id);
  dropSavedSnapshot(id);
  const { error } = await supabase.from("matches").update({ deleted_at: new Date().toISOString() }).eq("id", id);
  if (error) throw error;
  notifyDeleted("match", id);
}

// ★「結果だけ記録」で終えた試合を、後からポイントごとの詳細記録に切り替えたい時に使う。
//   既存のgames/points/faultsを消し、スコアと状態を未開始に戻す（recorder_idも解放する）。
async function resetMatchToUnrecorded(matchId) {
  invalidateMatchCaches(matchId);
  dropSavedSnapshot(matchId);
  const { data: existingGames } = await supabase.from("games").select("id").eq("match_id", matchId);
  const gameIds = (existingGames ?? []).map(g => g.id);
  if (gameIds.length) {
    await supabase.from("points").delete().in("game_id", gameIds);
    await supabase.from("faults").delete().in("game_id", gameIds);
    await supabase.from("games").delete().in("id", gameIds);
  }
  await supabase.from("matches").update({ match_score_a:0, match_score_b:0, status:"waiting" }).eq("id", matchId);
}

// ゴミ箱に入っている（個人戦の）試合一覧を取得（軽量：明細は含めない）
async function getDeletedMatches() {
  const { data, error } = await supabase
    .from("matches")
    .select("id, match_date, tournament_name, match_score_a, match_score_b, deleted_at")
    .not("deleted_at", "is", null)
    .order("deleted_at", { ascending: false });
  if (error) { console.error(error); return []; }
  return data ?? [];
}
async function restoreMatch(id) {
  dropSavedSnapshot(id);
  notifyRestored("match", id);
  invalidateMatchCaches(id);
  const { error } = await supabase.from("matches").update({ deleted_at: null }).eq("id", id);
  if (error) throw error;
}
async function permanentlyDeleteMatch(id) {
  invalidateMatchCaches(id);
  const { error } = await supabase.from("matches").delete().eq("id", id);
  if (error) throw error;
}

// ============================================================
// AI動画分析（外部AIで分析したテキストを試合に紐づけて保存）
// ============================================================
// 複数試合分のAI分析をまとめて取得（一覧のバッジ表示・AI分析タブ用）
async function getAiAnalyses(matchIds) {
  const ids = Array.from(new Set((matchIds ?? []).filter(Boolean)));
  if (ids.length === 0) return [];
  // ★試合IDが多いとリクエストのURLが長くなりすぎて失敗するため、分けて同時に取得する
  const CHUNK = 150;
  const chunks = [];
  for (let i = 0; i < ids.length; i += CHUNK) chunks.push(ids.slice(i, i + CHUNK));
  const results = await Promise.all(chunks.map(c =>
    supabase.from("ai_analyses").select("*").in("match_id", c).is("deleted_at", null)
  ));
  const rows = [];
  results.forEach(({ data, error }) => { if (error) console.error(error); rows.push(...(data ?? [])); });
  return rows;
}
async function saveAiAnalysis({ id, match_id, youtube_url, comment_text }) {
  const payload = {
    id: id || uid(), match_id,
    youtube_url: youtube_url ? youtube_url.trim() : null,
    comment_text: comment_text.trim(),
  };
  const { error } = await supabase.from("ai_analyses").upsert(payload);
  if (error) throw error;
  return payload;
}
async function deleteAiAnalysis(id) {
  const { error } = await supabase.from("ai_analyses").update({ deleted_at: new Date().toISOString() }).eq("id", id);
  if (error) throw error;
}

// ★AI分析一覧画面専用：まず「AI分析が付いている試合」だけをai_analysesテーブルから直接取得し、
// 　その試合IDだけに絞って必要な列（試合情報・出場選手）を取得する。
// 　以前はgetMatches()でチームの利用期間中の全試合を取得してからAI分析付きのものを
// 　絞り込んでいたため、利用期間が長くなるほど（AI分析の有無に関わらず）表示が遅くなっていた。
// 　sinceDateを指定すると、試合日（match_date）でさらに絞り込む（「1ヶ月以内」等の期間フィルタ用）。
async function getAiAnalysesWithMatches(sinceDate) {
  const { data: analyses, error: aErr } = await supabase
    .from("ai_analyses").select("id, match_id, youtube_url, comment_text, created_at").is("deleted_at", null);
  if (aErr) { console.error(aErr); return []; }

  const matchIds = Array.from(new Set((analyses ?? []).map(a => a.match_id).filter(Boolean)));
  if (matchIds.length === 0) return [];

  const CHUNK_SIZE = 40;
  const chunks = [];
  for (let i = 0; i < matchIds.length; i += CHUNK_SIZE) chunks.push(matchIds.slice(i, i + CHUNK_SIZE));

  const matches = [];
  const playersByMatch = {};
  for (const chunkIds of chunks) {
    let matchQuery = supabase.from("matches")
      .select("id, match_date, tournament_name, round, status, match_score_a, match_score_b")
      .in("id", chunkIds);
    if (sinceDate) matchQuery = matchQuery.gte("match_date", sinceDate);
    const [
      { data: msChunk, error: mErr },
      { data: playersData, error: pErr },
    ] = await Promise.all([
      matchQuery,
      supabase.from("match_players").select("match_id, team, player_name").in("match_id", chunkIds),
    ]);
    if (mErr || pErr) { console.error(mErr || pErr); continue; } // 1チャンク失敗しても他は続行する
    (msChunk ?? []).forEach(m => matches.push(m));
    (playersData ?? []).forEach(p => { (playersByMatch[p.match_id] ??= []).push(p); });
  }

  const analysisByMatch = {};
  (analyses ?? []).forEach(a => { analysisByMatch[a.match_id] = a; });

  return matches.map(m => ({
    match: { ...m, players: playersByMatch[m.id] ?? [] },
    analysis: analysisByMatch[m.id],
  }));
}

// 予定 → 進行中に切り替え
async function startScheduledMatch(id, firstServer, orderA, orderB, recvA, recvB) {
  invalidateMatchCaches(id);
  const updates = { status:"active" };
  if (firstServer) updates.first_server = firstServer;
  if (orderA) updates.order_a = orderA;
  if (orderB) updates.order_b = orderB;
  if (recvA) updates.receive_order_a = recvA; // ★レシーブの1人目（サーブとは別）
  if (recvB) updates.receive_order_b = recvB;
  // ★試合を開始した人がそのまま記録者になる（作成者とは別に管理する）
  const user = await getAuthUserFast(); // ★端末内の情報で確認（サーバーへの問い合わせを省く）
  if (user) {
    const profile = await getMyProfile();
    updates.recorder_id = user.id;
    updates.recorder_name = profile?.name || null;
  }
  const { error } = await supabase.from("matches").update(updates).eq("id", id);
  if (error) throw error;
  if (firstServer) markAutoStart(id); // ★サーブを選んで開始したので、記録画面ですぐ第1ゲームを始める
}

// ★記録者ロックを外す（試合終了・中断・途中終了のとき）
async function releaseMatchRecorder(id) {
  const { error } = await supabase.from("matches").update({ recorder_id:null, recorder_name:null }).eq("id", id);
  if (error) console.error(error);
}

// ============================================================
// ★仮の名前（「選手A」「選手B」）で記録されたポイント・フォルトを、今の選手名に直す
// ------------------------------------------------------------
// 相手の名前が分からないまま試合を始めると、記録された1点ごとに「選手A」「選手B」という
// 仮名が文字列としてそのまま書き込まれる。あとから正しい名前を登録しても、
// 既に記録済みのポイントは仮名のまま残ってしまうため、それをまとめて置き換える。
// 　「選手A」＝相手チーム（B）の1人目 / 「選手B」＝相手チーム（B）の2人目
// ============================================================
const PLACEHOLDER_NAMES = ["選手A", "選手B"];

function findPlaceholderRenameMap(match) {
  const bPlayers = (match?.players ?? []).filter(p => p.team === "B").sort((a,b)=>a.order_num-b.order_num);
  const map = {};
  PLACEHOLDER_NAMES.forEach((ph, i) => {
    const real = (bPlayers[i]?.player_name ?? "").trim();
    // 今の選手名がまだ仮名のままなら置き換えない（意味がないので）
    if (real && !PLACEHOLDER_NAMES.includes(real)) map[ph] = real;
  });
  return map;
}

// 仮名が実際に記録に残っているかを調べる（ボタンを出すかどうかの判定用）
function countPlaceholderRecords(match) {
  const map = findPlaceholderRenameMap(match);
  if (Object.keys(map).length === 0) return 0;
  let n = 0;
  (match?.games ?? []).forEach(g => {
    (g.points ?? []).forEach(pt => { if (map[pt.player_name]) n++; });
    (g.faults ?? []).forEach(f  => { if (map[f.player_name])  n++; });
  });
  return n;
}

// ★チーム内の全試合をまとめて修正する（1試合ずつ開いて直すのは大変なため）
async function repairAllPlaceholderPlayerNames() {
  invalidateMatchCaches();
  dropSavedSnapshot();
  // 仮名が残っているポイント・フォルトから、対象の試合を洗い出す
  const [{ data: pRows, error: pErr }, { data: fRows, error: fErr }] = await Promise.all([
    supabase.from("points").select("match_id").in("player_name", PLACEHOLDER_NAMES),
    supabase.from("faults").select("match_id").in("player_name", PLACEHOLDER_NAMES),
  ]);
  if (pErr) throw pErr;
  if (fErr) throw fErr;
  const matchIds = [...new Set([...(pRows ?? []), ...(fRows ?? [])].map(r => r.match_id).filter(Boolean))];
  if (matchIds.length === 0) return { matches: 0, fixed: 0 };

  // 対象試合の選手情報だけをまとめて取得する（ポイントまで読み込むと重くなるため）
  const { data: players, error: plErr } = await supabase
    .from("match_players").select("match_id, team, order_num, player_name").in("match_id", matchIds);
  if (plErr) throw plErr;
  const byMatch = {};
  (players ?? []).forEach(p => { (byMatch[p.match_id] ??= []).push(p); });

  let fixed = 0, matches = 0;
  for (const mid of matchIds) {
    const n = await repairPlaceholderPlayerNames({ id: mid, players: byMatch[mid] ?? [] });
    if (n > 0) { fixed += n; matches++; }
  }
  return { matches, fixed };
}

async function repairPlaceholderPlayerNames(match) {
  invalidateMatchCaches(match?.id);
  dropSavedSnapshot(match?.id);
  const map = findPlaceholderRenameMap(match);
  if (Object.keys(map).length === 0) return 0;
  let fixed = 0;
  for (const [placeholder, realName] of Object.entries(map)) {
    const { error: pErr, count: pCount } = await supabase.from("points")
      .update({ player_name: realName }, { count: "exact" })
      .eq("match_id", match.id).eq("player_name", placeholder);
    if (pErr) throw pErr;
    fixed += pCount ?? 0;
    const { error: fErr, count: fCount } = await supabase.from("faults")
      .update({ player_name: realName }, { count: "exact" })
      .eq("match_id", match.id).eq("player_name", placeholder);
    if (fErr) throw fErr;
    fixed += fCount ?? 0;
  }
  return fixed;
}

// ============================================================
// プロフィール
// ============================================================
// ★プロフィールはほぼ全画面の最初に読むため、短時間キャッシュして同じ問い合わせを繰り返さない。
//   取得に失敗した（null）場合は覚えずに、次回また取りに行く。
async function getMyProfile() {
  const now = Date.now();
  if (_profileCache && now - _profileCache.at < PROFILE_CACHE_MS) return _profileCache.promise;
  const promise = getMyProfileFresh();
  _profileCache = { at: now, promise };
  const data = await promise;
  if (!data && _profileCache?.promise === promise) _profileCache = null;
  return data;
}
async function getMyProfileFresh() {
  const user = await getAuthUserFast();
  if (!user) return null;
  const { data, error } = await supabase.from("users").select("*").eq("id", user.id).single();
  if (error) { console.error(error); return null; }
  // ★school_name が空のまま保存されてしまっていた場合に備え、読み込み時に自動修復する
  if (data && data.school_id && !data.school_name) {
    const { data: schoolRow } = await supabase.from("schools").select("name").eq("id", data.school_id).single();
    if (schoolRow?.name) {
      await supabase.from("users").update({ school_name: schoolRow.name }).eq("id", user.id);
      data.school_name = schoolRow.name;
    }
  }
  return data;
}

// プロフィール画像（LINEのような丸アイコン）
async function uploadAvatarImage(file) {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("ログインしていません");
  const ext = (file.name.split(".").pop() || "jpg").toLowerCase();
  const path = `${user.id}/${uid()}.${ext}`;
  const { error: upErr } = await supabase.storage.from("avatars").upload(path, file, { upsert: true, contentType: file.type || "image/jpeg" });
  if (upErr) throw upErr;
  const { data } = supabase.storage.from("avatars").getPublicUrl(path);
  return data.publicUrl;
}
async function updateMyAvatar(avatarUrl) {
  _profileCache = null;
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("ログインしていません");
  const { error } = await supabase.from("users").update({ avatar_url: avatarUrl }).eq("id", user.id);
  if (error) throw error;
}

// 大会要項（PDF）アップロード
async function uploadTournamentGuideline(file) {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("ログインしていません");
  const ext = (file.name.split(".").pop() || "pdf").toLowerCase();
  const path = `${user.id}/${uid()}.${ext}`;
  const { error: upErr } = await supabase.storage.from("guidelines").upload(path, file, { upsert: true, contentType: file.type || "application/pdf" });
  if (upErr) throw upErr;
  const { data } = supabase.storage.from("guidelines").getPublicUrl(path);
  return data.publicUrl;
}

async function saveMyProfile(profile) {
  _profileCache = null;
  invalidateRosterCache(); // ★承認状態が変わると見える選手が変わるため
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("ログインしていません");
  if (!profile.school_id) throw new Error("学校を選択してください。");

  // ★usersテーブルの school_name は NOT NULL 制約があるため、school_id から必ず引いてセットする。
  // 取得できなかった場合は空文字でごまかさず、はっきりエラーにして呼び出し元に伝える。
  const { data: schoolRow, error: schoolError } = await supabase
    .from("schools")
    .select("name")
    .eq("id", profile.school_id)
    .single();
  if (schoolError || !schoolRow) {
    throw new Error("学校情報を取得できませんでした。もう一度学校を選択してください。");
  }

  const updates = {
    id: user.id,
    name: profile.name,
    school_id: profile.school_id,
    school_name: schoolRow.name,
    prefecture: profile.prefecture,
    category: profile.category,
    gender_category: profile.gender_category,
    linked_player_id: profile.linked_player_id ?? null,
  };
  if (profile.is_approved !== undefined) updates.is_approved = profile.is_approved;
  // ★新規登録フローの「途中経過」を判定するためのフラグ。明示的に渡された時だけ更新し、
  //   通常のプロフィール編集（ProfileScreenなど）からの保存では触らないようにする
  //   （うっかり完了済みユーザーを未完了扱いに戻してしまわないため）。
  if (profile.signup_completed !== undefined) updates.signup_completed = profile.signup_completed;
  // ★閲覧専用アカウントかどうか。閲覧専用コードで参加したときだけ true になる。
  if (profile.is_viewer !== undefined) updates.is_viewer = profile.is_viewer;
  // ★update だと usersテーブルに行がまだ存在しない場合、0件更新のままエラーも出さずに終わってしまい、
  // 保存できたように見えて実は何も保存されていない、という無限ループの原因になっていた。
  // upsert にすることで、行がなければ新規作成、あれば更新、のどちらでも確実に保存されるようにする。
  const { error } = await supabase.from("users").upsert(updates);
  if (error) {
    console.error(error);
    throw error;
  }
  // ★チームへの参加（承認）は、招待コードをデータベース側で確認して行う。
  //   承認済み・閲覧専用・管理者の項目は、本人が直接書き換えられないようにしてあるため。
  if (profile.invite_code) {
    const { data: kind, error: jErr } = await supabase.rpc("join_team", { p_school_id: profile.school_id, p_code: profile.invite_code });
    if (jErr) { console.error(jErr); throw jErr; }
    if (!kind) throw new Error("招待コードが正しくありません。管理者に確認してください。");
    _profileCache = null;
    _isViewerCache = null;
  }
}

// ★閲覧専用アカウント（先生・保護者）かどうかを判定するための共通の仕組み。
//   画面ごとに毎回プロフィールを取りに行くと遅いので、一度取った結果は使い回す。
//   ※ここで隠すのは操作の入口だけなので、実際の書き込み禁止はSupabase側(RLS)でも設定すること。
let _isViewerCache = null;
async function fetchIsViewer() {
  const p = await getMyProfile();
  _isViewerCache = !!p?.is_viewer;
  return _isViewerCache;
}
function useIsViewer() {
  const [isViewer, setIsViewer] = useState(_isViewerCache === null ? false : _isViewerCache);
  useEffect(() => {
    let alive = true;
    if (_isViewerCache !== null) { setIsViewer(_isViewerCache); return; }
    fetchIsViewer().then(v => { if (alive) setIsViewer(v); });
    return () => { alive = false; };
  }, []);
  return isViewer;
}
// 閲覧専用の人に見せる「押せないボタン」の見た目
const viewerDisabledStyle = { opacity:0.4, cursor:"not-allowed", filter:"grayscale(0.6)" };
function viewerAlert() { alert("閲覧専用アカウントのため、この操作はできません。"); }

// 招待コード・管理者情報を取得
// ★viewer_invite_code は「閲覧専用」で参加するためのコード（先生・保護者向け）
// ★招待コードは管理者以外には読めないようにしてあるため、コードは専用の関数（管理者のみ）で取得する
async function getSchoolInviteInfo(schoolId) {
  if (!schoolId) return null;
  const { data, error } = await supabase.from("schools").select("admin_user_id").eq("id", schoolId).single();
  if (error) { console.error(error); return null; }
  let codes = null;
  const { data: c, error: cErr } = await supabase.rpc("get_my_school_codes");
  if (!cErr && Array.isArray(c) && c.length) codes = c[0];
  return { admin_user_id: data.admin_user_id, invite_code: codes?.invite_code || "", viewer_invite_code: codes?.viewer_invite_code || "" };
}

// 招待コードを照合する。
// 戻り値: "member"（記録もできる通常メンバー） / "viewer"（閲覧専用） / null（不一致）
async function verifyInviteCodeKind(schoolId, code) {
  const input = (code || "").trim().toUpperCase();
  if (!schoolId || !input) return null;
  const { data, error } = await supabase.rpc("check_invite_code", { p_school_id: schoolId, p_code: input });
  if (error) { console.error(error); return null; }
  return data === "member" || data === "viewer" ? data : null;
}

// 招待コードを照合（真偽値だけ欲しい既存の呼び出し用）
async function verifyInviteCode(schoolId, code) {
  return (await verifyInviteCodeKind(schoolId, code)) !== null;
}

// 招待コードを再発行（学校の管理者のみ・データベース側で発行）
async function reissueInviteCode(schoolId) {
  const { data, error } = await supabase.rpc("reissue_invite_code", { p_kind: "member" });
  if (error) throw error;
  return data;
}

// 閲覧専用コードを発行・再発行
async function reissueViewerInviteCode(schoolId) {
  const { data, error } = await supabase.rpc("reissue_invite_code", { p_kind: "viewer" });
  if (error) throw error;
  return data;
}

