// 同じ大会・同じブロック内で、指定したentry_noが既に別のエントリーで使われていないか確認する
// （excludeEntryIdsに含まれるエントリー自身との重複は無視する＝自分自身の更新はOK）
async function checkDuplicateEntryNo(tournamentId, category, blockLabel, entryNo, excludeEntryIds) {
  if (!entryNo) return false;
  let query = supabase.from("draw_entries").select("id").eq("tournament_id", tournamentId).eq("category", category).eq("entry_no", entryNo);
  query = blockLabel ? query.eq("block_label", blockLabel) : query.is("block_label", null);
  const { data, error } = await query;
  if (error) { console.error(error); return false; }
  return (data || []).some(row => !(excludeEntryIds || []).includes(row.id));
}

// ★同じ大会名の中で、指定したペア出場番号(entry_no)がこれまでに使われている試合を探し、
//   そのチーム名/学校名・選手名を返す（次の回戦の試合を作るとき、番号だけ入力すれば
//   チーム名・選手名を自動入力できるようにするため）。
//   同じ番号の行が複数見つかった場合は、直近に作成された試合のものを優先する。
async function findPairByEntryNo(tournamentName, entryNo) {
  const t = (tournamentName || "").trim();
  const n = (entryNo || "").trim();
  if (!t || !n) return null;

  // ①まずペアマスター（事前登録リスト）を探す。ここに登録があれば最優先で使う。
  const { data: master, error: masterErr } = await supabase
    .from("tournament_pairs").select("*").eq("tournament_name", t).eq("entry_no", n)
    .order("created_at", { ascending: false }).limit(1);
  if (!masterErr && master && master.length > 0) {
    const row = master[0];
    return {
      club_name: row.club_name || "",
      player1: row.player1_name || "",
      player2: row.player2_name || "",
    };
  }

  // ②ペアマスターに無ければ、過去に作成済みの試合から探す（従来通り）
  const { data: matches, error: mErr } = await supabase
    .from("matches").select("id, created_at")
    .eq("tournament_name", t).is("deleted_at", null)
    .order("created_at", { ascending: false });
  if (mErr || !matches || matches.length === 0) return null;
  const orderByRecency = {};
  matches.forEach((m, i) => { orderByRecency[m.id] = i; });
  const matchIds = matches.map(m => m.id);
  const { data: players, error: pErr } = await supabase
    .from("match_players").select("*").in("match_id", matchIds).eq("entry_no", n);
  if (pErr || !players || players.length === 0) return null;
  // 最も新しい試合のものを優先
  players.sort((a, b) => (orderByRecency[a.match_id] ?? 999999) - (orderByRecency[b.match_id] ?? 999999));
  const bestMatchId = players[0].match_id;
  const pair = players.filter(p => p.match_id === bestMatchId).sort((a, b) => a.order_num - b.order_num);
  if (pair.length === 0) return null;
  const cleanName = (n, ph) => (n && n !== ph) ? n : "";
  return {
    club_name: pair[0].club_name || "",
    player1: cleanName(pair.find(p => p.order_num === 1)?.player_name, "選手A"),
    player2: cleanName(pair.find(p => p.order_num === 2)?.player_name, "選手B"),
  };
}

// ============================================================
// ペアマスター（大会ごとに事前登録しておくペア一覧：tournament_pairs）
// ============================================================
async function getTournamentPairs(tournamentId) {
  const { data, error } = await supabase
    .from("tournament_pairs").select("*").eq("tournament_id", tournamentId)
    .order("created_at", { ascending: true });
  if (error) { console.error(error); return []; }
  // 出場番号は数値として扱えるものは数値順、それ以外は末尾に文字列順で並べる
  return (data ?? []).slice().sort((a, b) => {
    const na = Number(a.entry_no), nb = Number(b.entry_no);
    const aNum = a.entry_no !== "" && a.entry_no != null && !isNaN(na);
    const bNum = b.entry_no !== "" && b.entry_no != null && !isNaN(nb);
    if (aNum && bNum) return na - nb;
    if (aNum) return -1;
    if (bNum) return 1;
    return (a.entry_no || "").localeCompare(b.entry_no || "", "ja");
  });
}

async function saveTournamentPair(p) {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("ログインしていません");
  const row = {
    id: p.id || uid(),
    created_by: p.created_by || user.id,
    tournament_id: p.tournament_id,
    tournament_name: (p.tournament_name || "").trim(),
    entry_no: (p.entry_no || "").trim(),
    club_name: (p.club_name || "").trim() || null,
    player1_name: (p.player1_name || "").trim() || null,
    player2_name: (p.player2_name || "").trim() || null,
  };
  const { error } = await supabase.from("tournament_pairs").upsert(row);
  if (error) throw error;
  return row;
}

async function deleteTournamentPair(id) {
  const { error } = await supabase.from("tournament_pairs").delete().eq("id", id);
  if (error) throw error;
}

// ドローの枠（両サイドとも埋まっている状態）から、実際にスコアを付けられる試合(matches)を作成し、
// draw_matches.match_id に紐づける。作成後は通常の試合一覧にも表示されるようになる。
//
// ★二重作成防止：連打・通信遅延・複数端末からの同時操作で同じ枠から
//   複数のmatchesが作られないよう、以下の手順を踏む。
//   1) 呼び出し直後に最新のmatch_idをDBから再取得し、既にあればそれを返す
//   2) 新規作成後の更新は match_id が null のときだけ（.is("match_id", null)）
//   3) 更新が0件（＝他で先に作成済み）だった場合は、今回作った孤立試合を削除して
//      既存の方のmatch_idを返す
//   4) 更新自体がエラーだった場合も、孤立試合を削除してからエラーを投げる
async function createMatchFromDrawSlot(drawMatch, tournamentName, roundLabel) {
  // 1) 最新状態を確認（画面上の情報が古い可能性があるため）
  const { data: latest, error: fetchErr } = await supabase
    .from("draw_matches")
    .select("id, match_id")
    .eq("id", drawMatch.id)
    .single();
  if (fetchErr) throw fetchErr;
  if (latest?.match_id) return latest.match_id; // 既に作成済みならそれを使い回す

  const matchId = uid();
  const players = [];
  const addSide = (entry, team) => {
    if (!entry) return;
    if (entry.player1_name) players.push({ id: uid(), team, player_name: entry.player1_name, club_name: entry.school_name || "", position: "", order_num: 1, entry_no: entry.entry_no || null });
    if (entry.player2_name) players.push({ id: uid(), team, player_name: entry.player2_name, club_name: entry.school_name || "", position: "", order_num: 2, entry_no: entry.entry_no || null });
  };
  // ★自チームは必ずチームA、相手を必ずチームBにする（ドロー上の上側/下側の並び順とは無関係）。
  //   アプリ全体の色分け（緑=自チーム/オレンジ=相手）や統計はチームA=自チーム前提のため、
  //   ドロー入力時にどちらを上側/下側に入れたかで色分けが崩れないようにする。
  const ownIsB = drawMatch.sideB?.is_own_team && !drawMatch.sideA?.is_own_team;
  if (ownIsB) {
    addSide(drawMatch.sideB, "A");
    addSide(drawMatch.sideA, "B");
  } else {
    addSide(drawMatch.sideA, "A");
    addSide(drawMatch.sideB, "B");
  }

  const match = {
    id: matchId,
    match_date: new Date().toISOString().slice(0, 10),
    venue: "",
    tournament_name: tournamentName,
    round: roundLabel,
    match_type: "tournament",
    game_format: 7,
    is_doubles: true,
    first_server: null,
    status: "scheduled",
    match_score_a: 0,
    match_score_b: 0,
    memo: "",
    court_number: "",
    is_younger: true,
    players,
  };
  await saveMatch(match, { isNew: true });

  // 2) match_id が null のときだけ更新する（他の端末が先に作成していたら0件になる）
  //    ★あわせて「結果だけ記録」の内容が残っていたら消す（実際の試合＝正としてスコアを付け直すため）
  const { data: updatedRows, error: updateErr } = await supabase
    .from("draw_matches")
    .update({
      match_id: matchId, updated_at: new Date().toISOString(),
      simple_result_winner: null, simple_result_score_a: null, simple_result_score_b: null,
    })
    .eq("id", drawMatch.id)
    .is("match_id", null)
    .select("id, match_id");

  if (updateErr) {
    // 更新に失敗した場合、作成済みの試合が孤立してしまうため削除しておく
    await deleteMatch(matchId).catch(() => {});
    throw updateErr;
  }

  if (!updatedRows || updatedRows.length === 0) {
    // 3) 競合発生：既に別の操作でmatch_idがセットされていた
    //    今回作った孤立試合を削除し、既存の方のmatch_idを返す
    await deleteMatch(matchId).catch(() => {});
    const { data: current, error: recheckErr } = await supabase
      .from("draw_matches")
      .select("match_id")
      .eq("id", drawMatch.id)
      .single();
    if (recheckErr) throw recheckErr;
    return current?.match_id ?? null;
  }

  return matchId;
}

// 棄権による不戦勝処理：片方のサイドが棄権になったタイミングで、
// 実際のスコア入力を待たずに「終了扱い（不戦勝）」の試合を作成し、draw_matches.match_id に紐づける。
// winnerSide: 勝ち上がる側（棄権していない側）"A" | "B"
// 二重作成防止の考え方は createMatchFromDrawSlot と同様（先に最新状態を確認し、更新は match_id が null のときだけ行う）
async function createWalkoverMatch(drawMatch, tournamentName, roundLabel, winnerSide) {
  const { data: latest, error: fetchErr } = await supabase
    .from("draw_matches")
    .select("id, match_id")
    .eq("id", drawMatch.id)
    .single();
  if (fetchErr) throw fetchErr;
  if (latest?.match_id) return latest.match_id; // 既に試合が作成済みならそれを使い回す

  const matchId = uid();
  const players = [];
  const addSide = (entry, team) => {
    if (!entry) return;
    if (entry.player1_name) players.push({ id: uid(), team, player_name: entry.player1_name, club_name: entry.school_name || "", position: "", order_num: 1, entry_no: entry.entry_no || null });
    if (entry.player2_name) players.push({ id: uid(), team, player_name: entry.player2_name, club_name: entry.school_name || "", position: "", order_num: 2, entry_no: entry.entry_no || null });
  };
  // ★通常の試合作成と同様、自チームは必ずチームAになるようにする
  const ownIsB = drawMatch.sideB?.is_own_team && !drawMatch.sideA?.is_own_team;
  const effectiveWinnerSide = ownIsB ? (winnerSide === "A" ? "B" : "A") : winnerSide;
  if (ownIsB) {
    addSide(drawMatch.sideB, "A");
    addSide(drawMatch.sideA, "B");
  } else {
    addSide(drawMatch.sideA, "A");
    addSide(drawMatch.sideB, "B");
  }

  const gameFormat = 7;
  const winGames = calcWinGames(gameFormat);
  const match = {
    id: matchId,
    match_date: new Date().toISOString().slice(0, 10),
    venue: "",
    tournament_name: tournamentName,
    round: roundLabel,
    match_type: "tournament",
    game_format: gameFormat,
    is_doubles: true,
    first_server: null,
    status: "finished",
    match_score_a: effectiveWinnerSide === "A" ? winGames : 0,
    match_score_b: effectiveWinnerSide === "B" ? winGames : 0,
    memo: "不戦勝（相手棄権）",
    court_number: "",
    is_younger: true,
    players,
  };
  await saveMatch(match, { isNew: true });

  const { data: updatedRows, error: updateErr } = await supabase
    .from("draw_matches")
    .update({ match_id: matchId, updated_at: new Date().toISOString() })
    .eq("id", drawMatch.id)
    .is("match_id", null)
    .select("id, match_id");

  if (updateErr) {
    await deleteMatch(matchId).catch(() => {});
    throw updateErr;
  }
  if (!updatedRows || updatedRows.length === 0) {
    await deleteMatch(matchId).catch(() => {});
    const { data: current, error: recheckErr } = await supabase
      .from("draw_matches")
      .select("match_id")
      .eq("id", drawMatch.id)
      .single();
    if (recheckErr) throw recheckErr;
    return current?.match_id ?? null;
  }
  return matchId;
}
const calcWinGames = (fmt) => Math.ceil(fmt / 2);
const isFinalGame  = (fmt, sA, sB) => { const w = calcWinGames(fmt); return sA === w-1 && sB === w-1; };
const gameServer   = (first, num)  => num % 2 === 1 ? first : (first === "A" ? "B" : "A");

function checkNormalWinner(a, b) {
  if (a >= 4 && a - b >= 2) return "A";
  if (b >= 4 && b - a >= 2) return "B";
  return null;
}
function checkFinalWinner(a, b) {
  if (a >= 7 && a - b >= 2) return "A";
  if (b >= 7 && b - a >= 2) return "B";
  return null;
}
// ★「勝敗のみ」のゲーム：ゲームを飛ばした／途中から記録した場合など、どちらが取ったかだけが分かっていて
//   スコアが入っていない（0-0のまま勝者だけある）ゲーム。表示では「勝敗のみ」と出す。
const isWinOnlyGame = (g) => !!g?.winner_team && (g.score_a ?? 0) === 0 && (g.score_b ?? 0) === 0;
function finalServer(first, played) {
  return Math.floor(played / 2) % 2 === 0 ? first : (first === "A" ? "B" : "A");
}

// ============================================================
// ★サーブ／レシーブの担当者を1ポイントずつ割り出す（検算シートと統計の共通処理）
// ------------------------------------------------------------
// ソフトテニスのダブルス規則：
// 　サーブ側は2ポイントずつ交代（1人目が1-2点目、2人目が3-4点目…／チームの通算サーブ数で判定）
// 　レシーブ側は1ポイントごとに交代（コート左右の位置で決まるため、ゲーム内の総ポイント数で判定）
// シングルスの場合は1人しかいないので常にその選手になる。
//
// ★重要：スタッツ（calcPlayerStats）も検算シートもこの関数を使う。
// 　別々に同じ計算を書くと、片方だけ直したときに数字がズレて
// 　「検算したのに合っているのか分からない」状態になるため、必ずここに一本化する。
// ============================================================
function buildServeReceiveRows(match) {
  if (!match) return [];
  const matchPlayers = Array.isArray(match.players) ? match.players : [];
  const matchGames   = Array.isArray(match.games) ? match.games : [];

  // チームごとの選手をorder_num順に並べる（[0]=選手1, [1]=選手2）
  const teamPlayers = {
    A: matchPlayers.filter(p=>p.team==="A").sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name),
    B: matchPlayers.filter(p=>p.team==="B").sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name),
  };
  // ★どちらの選手が先に始めるか（通常は選手1＝配列[0]から）。稀に選手2から始まるケースがあるため、
  // 　match.order_a / match.order_b（"p1" | "p2"）で入れ替え可能にしている。
  const orderFlags = { A: match?.order_a === "p2" ? "p2" : "p1", B: match?.order_b === "p2" ? "p2" : "p1" };
  // ★レシーブの1人目はサーブとは別に設定できる（receive_order_a/b）。
  //   未設定(null)の古い試合は、これまで通りサーブの1人目と同じ人から始まるものとして扱う（数字は変わらない）。
  const recvFlags = {
    A: match?.receive_order_a === "p2" ? "p2" : match?.receive_order_a === "p1" ? "p1" : orderFlags.A,
    B: match?.receive_order_b === "p2" ? "p2" : match?.receive_order_b === "p1" ? "p1" : orderFlags.B,
  };
  const orderedPlayers = (players, flag) => {
    if (!Array.isArray(players) || players.length<=1) return players;
    return flag==="p2" ? [players[1], players[0]] : players;
  };
  const serverIndividualAt = (players, turn, flag) => {
    const ps = orderedPlayers(players, flag);
    if (!Array.isArray(ps) || ps.length===0) return null;
    if (ps.length===1) return ps[0];
    return Math.floor(turn/2)%2===0 ? ps[0] : ps[1];
  };
  const receiverIndividualAt = (players, turn, flag) => {
    const ps = orderedPlayers(players, flag);
    if (!Array.isArray(ps) || ps.length===0) return null;
    if (ps.length===1) return ps[0];
    return turn%2===0 ? ps[0] : ps[1];
  };

  const out = [];
  for (const g of matchGames) {
    // ★サーブ担当は「そのゲームの何本目か」を配列の先頭から数えて決めるため、必ず番号順に整える。
    const points = (Array.isArray(g.points) ? g.points.slice() : []).sort((a,b)=>(a.point_number ?? 0)-(b.point_number ?? 0));
    let serveTurnA = 0, serveTurnB = 0; // 各チームがこのゲームで通算何ポイント目のサーブか
    for (let idx=0; idx<points.length; idx++) {
      const pt = points[idx];
      const serverTeam = g.is_final ? finalServer(g.server_team, idx) : g.server_team;
      if (serverTeam !== "A" && serverTeam !== "B") {
        out.push({ game: g, point: pt, idx, serverTeam: null, receiveTeam: null, serverPlayer: null, receiverPlayer: null, serveResult: null });
        continue;
      }
      const receiveTeam = serverTeam==="A" ? "B" : "A";
      const serveTurn   = serverTeam==="A" ? serveTurnA : serveTurnB;
      const serverPlayer   = serverIndividualAt(teamPlayers[serverTeam], serveTurn, orderFlags[serverTeam]);
      // ★レシーブ側は「そのゲームで何点目か（idx）」で1ポイントごとに交代する（サーブ側の通算カウントとは別）
      const receiverPlayer = receiverIndividualAt(teamPlayers[receiveTeam], idx, recvFlags[receiveTeam]);
      const fc = pt.fault_count ?? 0;
      const serveResult = fc===0 ? "1st" : fc===1 ? "2nd" : fc===2 ? "df" : null;
      out.push({
        game: g, point: pt, idx, serverTeam, receiveTeam, serverPlayer, receiverPlayer, serveResult,
        serverWonPoint: pt.scoring_team === serverTeam,
      });
      if (serverTeam==="A") serveTurnA++; else serveTurnB++;
    }
  }
  return out;
}

// ============================================================
// 統計計算（play_type / result_type ベースに対応）
// ============================================================
function calcPlayerStats(match) {
  if (!match) return [];
  const matchPlayers = Array.isArray(match.players) ? match.players : [];
  const matchGames = Array.isArray(match.games) ? match.games : [];

  // 選手名 -> 所属チーム('A'/'B') の対応表（match_playersが正、scoring_teamには依存しない）
  const teamOf = {};
  for (const p of matchPlayers) { if (p?.player_name) teamOf[p.player_name] = p.team; }

  const result = {};
  const ensure = (playerTeam, playerName) => {
    const key = playerTeam + "__" + playerName;
    if (!result[key]) {
      result[key] = {
        team: playerTeam, player_name: playerName, total: 0, winners: 0, errors: 0, plays: {}, results: {},
        playsWin: {}, playsErr: {}, // ★決めたプレイ／ミスしたプレイの内訳用
        // ★ミスの種類（ネット／オーバー／チップ）と、フォア／バックの内訳。
        //   ミスの種類は入力が任意なので、母数として missTyped（種類まで入力されたミスの件数）も持つ。
        missTypes: {}, missTyped: 0,
        sideWin: {}, sideErr: {},
        // ★打球コース（引っ張り／流し）別の得点・ミス
        courseWin: {}, courseErr: {},
        // ★フォア/バック × コース（引っ張り/流し）の掛け合わせ（分析メニューのコース分析③用）
        sideCourseWin: {}, sideCourseErr: {},
        // ★「プレー内容 × フォア/バック × ミスの種類」の組み合わせ（練習メニューに直結させるため）
        missCombos: {},
        // ★1stサーブ確率・レシーブミス率用
        serveTotal: 0, serveFault: 0, receiveTotal: 0, receiveMiss: 0,
        // ★サーブ分析（集計）用：1st/2nd/DFの本数と、それぞれでの得点本数
        serve1st: 0, serve2nd: 0, serveDf: 0, serve1stWin: 0, serve2ndWin: 0,
      };
    }
    return result[key];
  };

  // ★サーブ／レシーブ担当者の割り出しは buildServeReceiveRows() に一本化した（下のループで使う）

  for (const g of matchGames) {
    // ★最後の砦：サーブを誰が打ったかは、この配列を先頭から数えた「そのゲームの何本目か」で決めている。
    //   呼び出し元が並べ替え忘れた場合でもダブルフォルト等が別の選手に付かないよう、ここでも必ず番号順に整える。
    const points = (Array.isArray(g.points) ? g.points.slice() : []).sort((a,b)=>(a.point_number ?? 0)-(b.point_number ?? 0));
    const faults = (Array.isArray(g.faults) ? g.faults.slice() : []).sort((a,b)=>(a.fault_number ?? 0)-(b.fault_number ?? 0));
    for (const pt of points) {
      if (!pt.player_name) continue;
      // ★重要：「得点(勝ち)」はscoring_teamの選手の得点だが、「ミス」はscoring_teamの
      // 　"相手"側の選手の失点であり、scoring_teamそのものとイコールではない。
      // 　（例：相手のレシーブミスで自チームが得点した場合、scoring_team="A"だが
      // 　　player_nameは相手チームの選手であり、そのミスは相手チームの記録になる）
      // 　そのためis_winnerとscoring_teamから選手の所属チームを正しく推定し、
      // 　同名選手が両チームに存在する場合の取り違えを防ぐ。teamOfは推定できない時の保険。
      const inferredTeam = pt.scoring_team==="A" ? (pt.is_winner ? "A" : "B")
                         : pt.scoring_team==="B" ? (pt.is_winner ? "B" : "A")
                         : null;
      const playerTeam = inferredTeam ?? teamOf[pt.player_name];
      const r = ensure(playerTeam, pt.player_name);
      r.total++;
      if (pt.is_winner) r.winners++; else r.errors++;
      if (pt.play_type)   r.plays[pt.play_type]     = (r.plays[pt.play_type]   ?? 0) + 1;
      if (pt.result_type) r.results[pt.result_type] = (r.results[pt.result_type] ?? 0) + 1;
      if (pt.play_type) {
        const bucket = pt.is_winner ? r.playsWin : r.playsErr;
        bucket[pt.play_type] = (bucket[pt.play_type] ?? 0) + 1;
      }
      if (pt.side_type) {
        const sideBucket = pt.is_winner ? r.sideWin : r.sideErr;
        sideBucket[pt.side_type] = (sideBucket[pt.side_type] ?? 0) + 1;
      }
      const ptCourse = normCourse(pt.course_type); // ★以前の正クロス／逆クロス付きの記録も引っ張り／流しにまとめる
      if (ptCourse) {
        const courseBucket = pt.is_winner ? r.courseWin : r.courseErr;
        courseBucket[ptCourse] = (courseBucket[ptCourse] ?? 0) + 1;
      }
      if (pt.side_type && ptCourse) {
        const sideCourseBucket = pt.is_winner ? r.sideCourseWin : r.sideCourseErr;
        const scKey = pt.side_type + "__" + ptCourse;
        sideCourseBucket[scKey] = (sideCourseBucket[scKey] ?? 0) + 1;
      }
      if (!pt.is_winner && pt.miss_type) {
        r.missTypes[pt.miss_type] = (r.missTypes[pt.miss_type] ?? 0) + 1;
        r.missTyped++;
        const comboKey = [pt.play_type ?? "", pt.side_type ?? "", pt.miss_type].join("|");
        r.missCombos[comboKey] = (r.missCombos[comboKey] ?? 0) + 1;
      }
    }
    for (const f of faults) {
      if (!f.player_name) continue;
      const playerTeam = f.server_team ?? teamOf[f.player_name];
      const r = ensure(playerTeam, f.player_name);
      r.plays["fault"] = (r.plays["fault"] ?? 0) + 1;
    }

  }

  // ★1stサーブ確率・レシーブミス率（サーブは2ポイントごと、レシーブは1ポイントごとの選手交代を反映して個人に按分）
  // 　担当者の割り出しは buildServeReceiveRows() に一本化している。検算シートも同じ関数を使うので、
  // 　画面に出ている「誰が打ったか」とここでの集計が食い違うことはない。
  for (const row of buildServeReceiveRows(match)) {
    const { point: pt, serverTeam, receiveTeam, serverPlayer, receiverPlayer } = row;
    if (!serverTeam) continue;

    // ★このポイントの直前に1stフォルトがあったかは、ポイント自身が持つfault_countで確実に判定できる
    // 　（別テーブルのfaultsとスコアで突き合わせる方式は、フォルト記録時のスコアが実際とズレていると
    // 　　対応が取れなくなり、集計から漏れることがあったため廃止）
    const hadFault = (pt.fault_count ?? 0) >= 1;

    if (serverPlayer) {
      const r = ensure(serverTeam, serverPlayer);
      r.serveTotal++;
      if (hadFault) r.serveFault++;
      if (pt.fault_count===0)      { r.serve1st++; if (pt.scoring_team===serverTeam) r.serve1stWin++; }
      else if (pt.fault_count===1) { r.serve2nd++; if (pt.scoring_team===serverTeam) r.serve2ndWin++; }
      else if (pt.fault_count===2) {
        r.serveDf++;
        // ★ダブルフォルトはサーブを打った選手のミスとして数える（決定率・ミス数・得失点差に反映）。
        //   DFのポイントは選手名なしで記録されるため、ここでサーブ順から割り出した選手に付ける。
        //   後から編集でミスの選手名が入っているDFは、上のループですでにミスとして数えているので二重に数えない。
        if (!pt.player_name) {
          r.total++; r.errors++;
          r.playsErr["double_fault"] = (r.playsErr["double_fault"] ?? 0) + 1;
        }
      }
    }
    if (receiverPlayer) {
      const r = ensure(receiveTeam, receiverPlayer);
      r.receiveTotal++;
    }
    // ★分子（ミス数）は実際にそのポイントで記録された選手名をそのまま使う（ローテーション推定に頼らない）。
    // 　分母（レシーブ機会数）は上のreceiveTotalの通りローテーションからの推定値のまま。
    if (pt.play_type==="receive" && pt.result_type==="error" && pt.player_name && teamOf[pt.player_name]===receiveTeam) {
      const rMiss = ensure(receiveTeam, pt.player_name);
      rMiss.receiveMiss++;
    }
  }
  return Object.values(result);
}

// ============================================================
// ★試合サマリー／AI総評／改善優先順位（自チーム=A視点で集計）
// ============================================================
function calcMatchSummary(match) {
  const allPts = match.games.flatMap(g => g.points);
  const totalA = allPts.filter(p=>p.scoring_team==="A").length;
  const totalB = allPts.filter(p=>p.scoring_team==="B").length;
  const winA   = allPts.filter(p=>p.scoring_team==="A"&&p.is_winner===true).length;
  const winB   = allPts.filter(p=>p.scoring_team==="B"&&p.is_winner===true).length;
  const attackA = winA, oppMissA = totalA-winA, selfMissA = totalB-winB, oppAttackA = winB;
  const decisionRate = (attackA+selfMissA)>0 ? Math.round(attackA/(attackA+selfMissA)*100) : null;

  const stats = calcPlayerStats(match);
  const teamAStats = stats.filter(s=>s.team==="A");
  const scoreRanking = teamAStats.slice().sort((a,b)=>b.winners-a.winners);
  const missRanking  = teamAStats.slice().sort((a,b)=>b.errors-a.errors);
  const topScorer = scoreRanking[0] ?? null;

  // ★自チーム2人それぞれの決定数・ミス数。
  // 　以前は登録順から「前衛／後衛」を決め打ちでラベル付けしていたが、
  // 　ソフトテニスにはダブル前衛・ダブル後衛といった戦術があり、
  // 　登録順とポジションは必ずしも一致しないためラベルは持たせず、選手名だけで表示する。
  const aPlayersSorted = match.players.filter(p=>p.team==="A").sort((a,b)=>a.order_num-b.order_num);
  const posStats = {
    front: { name: aPlayersSorted[1]?.player_name ?? null, win:0, err:0 },
    back:  { name: aPlayersSorted[0]?.player_name ?? null, win:0, err:0 },
  };
  aPlayersSorted.forEach((p,idx)=>{
    const key = idx===0 ? "back" : "front";
    const s = teamAStats.find(x=>x.player_name===p.player_name);
    if (s && posStats[key]) { posStats[key].win += s.winners; posStats[key].err += s.errors; }
  });

  // プレイ別成功率（チーム＝ペア2人で合算。fault除く）
  // ★使用回数が少ないプレー（3回未満）は信頼性が低いため除外はせず、
  // 　isRef フラグを立てて「参考」として一覧の下に表示する
  const playAgg = {};
  teamAStats.forEach(s=>{
    Object.entries(s.playsWin).forEach(([k,n])=>{ playAgg[k]=playAgg[k]||{win:0,err:0}; playAgg[k].win+=n; });
    Object.entries(s.playsErr).forEach(([k,n])=>{ if(k==="fault") return; playAgg[k]=playAgg[k]||{win:0,err:0}; playAgg[k].err+=n; });
  });
  const playRates = Object.entries(playAgg)
    .filter(([k])=>k!=="double_fault") // ★DFは決めることがないプレーなので成功率の一覧には出さない
    .map(([k,v])=>({ key:k, label:getPlayLabel(k), total:v.win+v.err, win:v.win, err:v.err, rate:(v.win+v.err)>0?Math.round(v.win/(v.win+v.err)*100):0, isRef:(v.win+v.err)<3 }))
    .filter(p=>p.total>=1);
  // ★参考（サンプル数が少ない）プレーは、決め率に関係なく必ず一覧の下に来るようにする
  const bestPlays  = playRates.filter(p=>p.rate>0).sort((a,b)=> (a.isRef===b.isRef) ? b.rate-a.rate : (a.isRef?1:-1)).slice(0,4);
  const worstPlays = playRates.filter(p=>p.rate<100).sort((a,b)=> (a.isRef===b.isRef) ? a.rate-b.rate : (a.isRef?1:-1)).slice(0,4);

  // 今日の得点源・失点源（プレー種類別に「決めた数」「ミス数」の実数が多い順）
  const pointSources = Object.entries(playAgg)
    .map(([k,v])=>({ key:k, label:getPlayLabel(k), count:v.win }))
    .filter(p=>p.count>0).sort((a,b)=>b.count-a.count).slice(0,3);
  const missSources = Object.entries(playAgg)
    .map(([k,v])=>({ key:k, label:getPlayLabel(k), count:v.err }))
    .filter(p=>p.count>0).sort((a,b)=>b.count-a.count).slice(0,3);

  // ★サーブ分析（チーム別：A=自チーム／B=相手。fault_count: 0=1stイン/1=2ndイン/2=ダブルフォルト）
  const serveBy = {};
  ["A","B"].forEach(t => { serveBy[t] = { s1:0, s2:0, df:0, total:0, s1Win:0, s2Win:0 }; });
  for (const g of match.games) {
    for (let idx=0; idx<g.points.length; idx++) {
      const pt = g.points[idx];
      const st = g.is_final ? finalServer(g.server_team, idx) : g.server_team;
      const r = serveBy[st]; if (!r) continue;
      r.total++;
      if (pt.fault_count===0){ r.s1++; if(pt.scoring_team===st) r.s1Win++; }
      else if (pt.fault_count===1){ r.s2++; if(pt.scoring_team===st) r.s2Win++; }
      else if (pt.fault_count===2){ r.df++; }
    }
  }
  // 以下は自チーム（A）だけの従来の集計（他の画面・AI総評で使用）
  let serve1st=0, serve2nd=0, serveDf=0, serveTotal=0;
  let firstServeWin=0, firstServeTotal=0, secondServeWin=0, secondServeTotal=0;
  for (const g of match.games) {
    for (let idx=0; idx<g.points.length; idx++) {
      const pt = g.points[idx];
      const serverTeam = g.is_final ? finalServer(g.server_team, idx) : g.server_team;
      if (serverTeam!=="A") continue;
      serveTotal++;
      if (pt.fault_count===0){ serve1st++; firstServeTotal++; if(pt.scoring_team==="A") firstServeWin++; }
      else if (pt.fault_count===1){ serve2nd++; secondServeTotal++; if(pt.scoring_team==="A") secondServeWin++; }
      else if (pt.fault_count===2){ serveDf++; }
    }
  }

  // 試合の流れ：最大連続得点／連続失点
  let curStreak=0, curTeam=null, maxWinStreak=0, maxLoseStreak=0;
  allPts.forEach(p=>{
    if (p.scoring_team===curTeam) curStreak++; else { curTeam=p.scoring_team; curStreak=1; }
    if (curTeam==="A") maxWinStreak=Math.max(maxWinStreak,curStreak);
    else maxLoseStreak=Math.max(maxLoseStreak,curStreak);
  });

  // 得点推移（1ゲーム目）
  const firstGame = match.games[0];
  const timeline = firstGame ? firstGame.points.map(p=>({
    team:p.scoring_team, isWinner:p.is_winner, player:p.player_name, play:p.play_type,
  })) : [];

  return {
    totalA, totalB, attackA, oppMissA, selfMissA, oppAttackA, decisionRate,
    topScorer, scoreRanking, missRanking, posStats, bestPlays, worstPlays, pointSources, missSources,
    serve1st, serve2nd, serveDf, serveTotal, firstServeWin, firstServeTotal, secondServeWin, secondServeTotal, serveBy,
    maxWinStreak, maxLoseStreak, timeline,
  };
}

function buildHighlights(sum) {
  const good = [];
  const bad = [];
  if (sum.bestPlays[0])  good.push(`${sum.bestPlays[0].label}の成功率が${sum.bestPlays[0].rate}%で、この試合最大の得点源でした。`);
  if (sum.worstPlays[0]) bad.push(`${sum.worstPlays[0].label}の成功率が${sum.worstPlays[0].rate}%と低く、次の課題です。`);

  if (sum.totalA>0 && good.length<2) {
    const pct = Math.round(sum.attackA/sum.totalA*100);
    if (pct>=50) good.push(`攻撃で決めた得点の割合が${pct}%と高く、自分たちの形で試合を進められました。`);
  }
  if (sum.secondServeTotal>0) {
    const rate = Math.round(sum.secondServeWin/sum.secondServeTotal*100);
    if (rate>=50 && good.length<2) good.push(`2ndサーブ時の得点率が${rate}%と安定していました。`);
    else if (rate<50 && bad.length<2) bad.push(`2ndサーブ時の得点率が${rate}%と低く、組み立てを見直しましょう。`);
  }
  if (sum.totalB>0 && bad.length<2) {
    const pct = Math.round(sum.oppAttackA/sum.totalB*100);
    if (pct>=50) bad.push(`失点の${pct}%は相手の攻撃によるもので、対策が必要です。`);
  }
  return { good: good.slice(0,2), bad: bad.slice(0,2) };
}

function buildLineText(match) {
  var aP = match.players.filter(function(p){return p.team==="A";}).map(function(p){return p.player_name;}).join("/");
  var bP = match.players.filter(function(p){return p.team==="B";}).map(function(p){return p.player_name;}).join("/");
  var aC = (match.players.find(function(p){return p.team==="A";}) || {}).club_name || "";
  var bC = (match.players.find(function(p){return p.team==="B";}) || {}).club_name || "";
  var aWin = winnerSideOf(match)==="A";
  var t = "\u{1F3BE} \u8A66\u5408\u7D50\u679C\n";
  if (match.tournament_name) t += match.tournament_name + (match.round ? " " + match.round : "") + "\n";
  t += fmtDate(match.match_date) + (match.venue ? " @" + match.venue : "") + "\n\n";
  t += (aWin ? "\u{1F3C6} " : "") + aC + " " + aP + "\n";
  t += (!aWin && match.status==="finished" ? "\u{1F3C6} " : "") + bC + " " + bP + "\n\n";
  t += "\u30B9\u30B3\u30A2 " + match.match_score_a + " - " + match.match_score_b + "\n";
  match.games.forEach(function(g) { t += "G" + g.game_number + (g.is_final ? "(F)" : "") + ": " + g.score_a + "-" + g.score_b + "\n"; });
  return t;
}

// CSV出力
function buildCsv(match) {
  const headers = ["試合日","大会名","何回戦","ゲーム番号","ファイナルゲーム","ポイント番号","得点チーム","チーム区分","選手名","所属","プレイ内容","フォア/バック","コース","ミスの種類","結果","チームA得点","チームB得点"];
  const rows = [];
  for (const g of match.games) {
    for (const f of (g.faults ?? [])) {
      // ★同名選手が両チームにいる場合の取り違えを防ぐため、まずチームも一致する選手を優先して探す
      const pl = match.players.find(p=>p.player_name===f.player_name && p.team===f.server_team)
              ?? match.players.find(p=>p.player_name===f.player_name);
      rows.push([match.match_date,match.tournament_name??"",match.round??"",g.game_number,g.is_final?"YES":"NO","","",f.server_team==="A"?"自チーム":"相手チーム",f.player_name??"",pl?.club_name??""," 1stフォルト","","fault",f.score_a_at,f.score_b_at]);
    }
    for (const pt of g.points) {
      // ★得点(勝ち)なら得点チーム、ミスなら相手チームの選手なので、それに合わせてチームを絞って探す
      const ptTeam = pt.is_winner ? pt.scoring_team : (pt.scoring_team==="A" ? "B" : pt.scoring_team==="B" ? "A" : null);
      const pl = match.players.find(p=>p.player_name===pt.player_name && p.team===ptTeam)
              ?? match.players.find(p=>p.player_name===pt.player_name);
      rows.push([match.match_date,match.tournament_name??"",match.round??"",g.game_number,g.is_final?"YES":"NO",pt.point_number,pt.scoring_team,pt.scoring_team==="A"?"自チーム":"相手チーム",pt.player_name??"",pl?.club_name??"",pt.play_type?getPlayLabel(pt.play_type):"",pt.side_type?getSideLabel(pt.side_type):"",pt.course_type?getCourseLabel(pt.course_type):"",pt.miss_type?getMissLabel(pt.miss_type):"",pt.result_type?getResultLabel(pt.result_type):"",pt.score_a_after,pt.score_b_after]);
    }
  }
  const esc = v => { const s = String(v == null ? "" : v); if (s.indexOf(",") >= 0 || s.indexOf('"') >= 0 || s.indexOf("\n") >= 0) { return '"' + s.split('"').join('""'  ) + '"'; } return s; };
  return "\uFEFF"+[headers,...rows].map(r=>r.map(esc).join(",")).join("\n");
}

function downloadCsv(match) {
  const blob = new Blob([buildCsv(match)],{type:"text/csv;charset=utf-8;"});
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement("a");
  a.href=url; a.download=`softtennis_${match.match_date}.csv`;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a); URL.revokeObjectURL(url);
}

