// ============================================================
// 目標設定画面（チーム共通・1セットのみ・管理者専用）
// ============================================================
const DEFAULT_GOALS = {
  firstServe: "70",
  receiveMiss: "10",
  winnerCount: "3",
  errorCount: "2",
  pointDiff: "1",
};

function GoalSettingsScreen({ onBack }) {
  const [schoolId, setSchoolId] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [firstServe, setFirstServe] = useState(DEFAULT_GOALS.firstServe);
  const [receiveMiss, setReceiveMiss] = useState(DEFAULT_GOALS.receiveMiss);
  const [winnerCount, setWinnerCount] = useState(DEFAULT_GOALS.winnerCount);
  const [errorCount, setErrorCount] = useState(DEFAULT_GOALS.errorCount);
  const [pointDiff, setPointDiff] = useState(DEFAULT_GOALS.pointDiff);
  const backupRef = useRef(null);

  useEffect(() => {
    (async () => {
      const profile = await getMyProfile();
      setIsAdmin(!!profile?.is_admin);
      if (!profile?.school_id) { setLoading(false); return; }
      setSchoolId(profile.school_id);
      const goals = await getSchoolGoals(profile.school_id);
      if (goals) {
        setFirstServe(goals.goal_first_serve_pct!=null ? String(goals.goal_first_serve_pct) : DEFAULT_GOALS.firstServe);
        setReceiveMiss(goals.goal_receive_miss_pct!=null ? String(goals.goal_receive_miss_pct) : DEFAULT_GOALS.receiveMiss);
        setWinnerCount(goals.goal_winner_count!=null ? String(goals.goal_winner_count) : DEFAULT_GOALS.winnerCount);
        setErrorCount(goals.goal_error_count!=null ? String(goals.goal_error_count) : DEFAULT_GOALS.errorCount);
        setPointDiff(goals.goal_point_diff!=null ? String(goals.goal_point_diff) : DEFAULT_GOALS.pointDiff);
      }
      setLoading(false);
    })();
  }, []);

  function handleEdit() {
    if (!isAdmin) return;
    // 編集開始前の値を保持しておき、キャンセル時に復元できるようにする
    backupRef.current = { firstServe, receiveMiss, winnerCount, errorCount, pointDiff };
    setEditMode(true);
  }

  function handleCancel() {
    if (backupRef.current) {
      setFirstServe(backupRef.current.firstServe);
      setReceiveMiss(backupRef.current.receiveMiss);
      setWinnerCount(backupRef.current.winnerCount);
      setErrorCount(backupRef.current.errorCount);
      setPointDiff(backupRef.current.pointDiff);
    }
    setEditMode(false);
  }

  async function handleSave() {
    if (!schoolId || !isAdmin) return;
    setSaving(true);
    try {
      await updateSchoolMaster(schoolId, {
        goal_first_serve_pct: firstServe===""?null:Number(firstServe),
        goal_receive_miss_pct: receiveMiss===""?null:Number(receiveMiss),
        goal_winner_count: winnerCount===""?null:Number(winnerCount),
        goal_error_count: errorCount===""?null:Number(errorCount),
        goal_point_diff: pointDiff===""?null:Number(pointDiff),
      });
      alert("目標を保存しました");
      setEditMode(false);
    } catch(e) {
      alert("保存に失敗しました: "+(e.message||e));
    } finally {
      setSaving(false);
    }
  }

  const canEditNow = isAdmin && editMode;
  const inputStyle = (disabled) => ({
    width:64, textAlign:"center", border:`1px solid ${C.border}`, borderRadius:8, padding:"8px 4px", fontSize:14, fontWeight:700,
    color: disabled ? C.textSec : C.navy,
    background: disabled ? "#f0f1f3" : C.white,
  });
  const row = (num, label, value, setValue, unit) => (
    <>
      <span style={{ fontSize:12,color:C.text,fontWeight:700 }}><span style={{ color:C.textSec,fontWeight:400,marginRight:4 }}>{num}</span>{label}</span>
      <input style={inputStyle(!canEditNow)} type="number" value={value} disabled={!canEditNow} onChange={e=>setValue(e.target.value)} />
      <span style={{ fontSize:11,color:C.textSec,whiteSpace:"nowrap" }}>{unit}</span>
    </>
  );

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onBack}>←</button>
        <span style={{ fontSize:18,fontWeight:800,color:C.white }}>目標設定</span>
      </div>
      <div style={{ padding:14, paddingBottom:90 }}>
        {loading ? (
          <div style={{ textAlign:"center",color:C.textSec,padding:"40px 0" }}>読み込み中...</div>
        ) : !schoolId ? (
          <div style={{ textAlign:"center",color:C.textSec,padding:"40px 0" }}>学校情報が未設定のため目標を設定できません</div>
        ) : (
          <>
            <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4 }}>
              <div style={{ fontSize:20,fontWeight:800 }}>🎯 目標設定</div>
              {isAdmin && !editMode && (
                <button
                  style={{ background:C.navy, color:C.white, border:"none", borderRadius:8, fontSize:12, fontWeight:700, padding:"7px 12px", cursor:"pointer" }}
                  onClick={handleEdit}
                >✏️ 目標値変更</button>
              )}
            </div>
            <div style={{ fontSize:11,color:C.textSec,marginBottom:14 }}>ここで設定した目標は、チーム全選手のスタッツ画面に共通で適用されます</div>
            <div style={{ ...S.card, padding:14, display:"grid", gridTemplateColumns:"1fr 68px 56px", columnGap:8, rowGap:14, alignItems:"center" }}>
              {row("①", "1stサーブ確率", firstServe, setFirstServe, "%以上")}
              {row("②", "決めたプレイ回数", winnerCount, setWinnerCount, "回以上")}
              {row("③", "ミスしたプレイ回数", errorCount, setErrorCount, "回以下")}
              {row("④", "得点差（決めた−ミス）", pointDiff, setPointDiff, "以上")}
            </div>
            {canEditNow && (
              <>
                <button style={{ ...S.btn(`linear-gradient(135deg,${C.navy},#12213f)`), marginTop:14, width:"100%" }} disabled={saving} onClick={handleSave}>
                  {saving?"保存中...":"保存する"}
                </button>
                <button
                  style={{ ...S.btn(C.white,C.textSec), marginTop:10, width:"100%", border:`1px solid ${C.border}` }}
                  disabled={saving}
                  onClick={handleCancel}
                >キャンセル</button>
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ============================================================
// シーズン設定画面（チーム共通・起点日1つ・管理者専用）
// ・世代交代の日を登録しておくと、分析の期間で「◯◯以降」として選べる
// ============================================================
function SeasonSettingsScreen({ onBack }) {
  const [schoolId, setSchoolId] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [startDate, setStartDate] = useState("");
  const [label, setLabel] = useState("");
  // ★呼び名を手で書き換えたら、日付を変えても上書きしない
  const labelTouchedRef = useRef(false);
  const backupRef = useRef(null);

  useEffect(() => {
    (async () => {
      const profile = await getMyProfile();
      setIsAdmin(!!profile?.is_admin);
      if (!profile?.school_id) { setLoading(false); return; }
      setSchoolId(profile.school_id);
      const season = await getSchoolSeason(profile.school_id);
      if (season) {
        setStartDate(season.season_start_date || "");
        setLabel(season.season_start_label || "");
        if (season.season_start_label) labelTouchedRef.current = true;
      }
      setLoading(false);
    })();
  }, []);

  function handleDateChange(v) {
    setStartDate(v);
    if (!labelTouchedRef.current) setLabel(defaultSeasonLabel(v));
  }
  function handleLabelChange(v) {
    labelTouchedRef.current = true;
    setLabel(v);
  }
  function handleEdit() {
    if (!isAdmin) return;
    backupRef.current = { startDate, label, touched: labelTouchedRef.current };
    setEditMode(true);
  }
  function handleCancel() {
    if (backupRef.current) {
      setStartDate(backupRef.current.startDate);
      setLabel(backupRef.current.label);
      labelTouchedRef.current = backupRef.current.touched;
    }
    setEditMode(false);
  }
  async function handleSave() {
    if (!schoolId || !isAdmin) return;
    if (startDate && !label.trim()) { alert("呼び名を入力してください"); return; }
    setSaving(true);
    try {
      await updateSchoolMaster(schoolId, {
        season_start_date: startDate || null,
        season_start_label: startDate ? label.trim() : null,
      });
      alert("シーズン設定を保存しました");
      setEditMode(false);
    } catch(e) {
      alert("保存に失敗しました: "+(e.message||e));
    } finally {
      setSaving(false);
    }
  }
  async function handleClear() {
    if (!schoolId || !isAdmin) return;
    if (!window.confirm("起点日を消しますか？\n分析の期間から「◯◯以降」の選択肢が出なくなります。")) return;
    setSaving(true);
    try {
      await updateSchoolMaster(schoolId, { season_start_date: null, season_start_label: null });
      setStartDate(""); setLabel(""); labelTouchedRef.current = false;
      alert("起点日を消しました");
      setEditMode(false);
    } catch(e) {
      alert("削除に失敗しました: "+(e.message||e));
    } finally {
      setSaving(false);
    }
  }

  const canEditNow = isAdmin && editMode;
  const inputStyle = (disabled) => ({
    width:"100%", border:`1.5px solid ${C.border}`, borderRadius:9, padding:"12px", fontSize:15, fontWeight:700,
    fontFamily:"inherit",
    color: disabled ? C.textSec : C.text,
    background: disabled ? "#f0f1f3" : C.white,
  });

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onBack}>←</button>
        <span style={{ fontSize:18,fontWeight:800,color:C.white }}>シーズン設定</span>
      </div>
      <div style={{ padding:14, paddingBottom:90 }}>
        {loading ? (
          <div style={{ textAlign:"center",color:C.textSec,padding:"40px 0" }}>読み込み中...</div>
        ) : !schoolId ? (
          <div style={{ textAlign:"center",color:C.textSec,padding:"40px 0" }}>学校情報が未設定のためシーズンを設定できません</div>
        ) : (
          <>
            <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4 }}>
              <div style={{ fontSize:20,fontWeight:800 }}>📌 シーズン設定</div>
              {isAdmin && !editMode && (
                <button
                  style={{ background:C.navy, color:C.white, border:"none", borderRadius:8, fontSize:12, fontWeight:700, padding:"7px 12px", cursor:"pointer" }}
                  onClick={handleEdit}
                >✏️ 変更</button>
              )}
            </div>
            <div style={{ fontSize:11,color:C.textSec,marginBottom:14 }}>
              チーム共通の設定です。分析の期間で「◯◯以降」として使えます{!isAdmin && "（編集は管理者のみ）"}
            </div>

            <div style={{ ...S.card, padding:14 }}>
              <div style={{ fontSize:13.5,fontWeight:800,color:C.text,marginBottom:6 }}>起点日</div>
              <input
                type="date" style={inputStyle(!canEditNow)} value={startDate} disabled={!canEditNow}
                onChange={e=>handleDateChange(e.target.value)}
              />
              <div style={{ fontSize:12.5,color:C.textSec,lineHeight:1.7,margin:"6px 0 16px" }}>
                3年生が引退した日や、新チームが始動した日を入れます。分析で「この日以降」を選んだときの開始日になります。
              </div>

              <div style={{ fontSize:13.5,fontWeight:800,color:C.text,marginBottom:6 }}>呼び名</div>
              <input
                type="text" style={inputStyle(!canEditNow)} value={label} disabled={!canEditNow}
                placeholder="例：2026チーム"
                onChange={e=>handleLabelChange(e.target.value)}
              />
              <div style={{ fontSize:12.5,color:C.textSec,lineHeight:1.7,marginTop:6 }}>
                起点日の西暦から自動で入ります。「新チーム」「◯◯世代」など自由に書き換えられます。
              </div>
            </div>

            {startDate && label.trim() && (
              <div style={{ background:C.accentL,border:"1px solid #9fe3c8",borderRadius:10,padding:12,fontSize:13.5,fontWeight:700,color:"#0b7a55",lineHeight:1.7,marginTop:10 }}>
                分析画面の期間に「📌 {label.trim()}以降」が出ます<br/>
                {startDate.replace(/-/g,"/")} 〜 今日
              </div>
            )}
            {!startDate && !canEditNow && (
              <div style={{ background:"#fff4e5",border:"1px solid #f5c979",borderRadius:10,padding:12,fontSize:13,fontWeight:700,color:"#8a5a00",lineHeight:1.7,marginTop:10 }}>
                起点日が未設定です。分析の期間に「◯◯以降」の選択肢は出ません。
              </div>
            )}

            {canEditNow && (
              <>
                <button style={{ ...S.btn(`linear-gradient(135deg,${C.navy},#12213f)`), marginTop:14, width:"100%" }} disabled={saving} onClick={handleSave}>
                  {saving?"保存中...":"保存する"}
                </button>
                <button
                  style={{ ...S.btn(C.white,C.textSec), marginTop:10, width:"100%", border:`1px solid ${C.border}` }}
                  disabled={saving}
                  onClick={handleCancel}
                >キャンセル</button>
                {startDate && (
                  <button
                    style={{ ...S.btn(C.white,C.red), marginTop:10, width:"100%", border:`1px solid ${C.border}` }}
                    disabled={saving}
                    onClick={handleClear}
                  >起点日を消す</button>
                )}
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
}

function HomeScreen({ onNew, onNewTeamMatch, onOpen, onNavigate, onGoPlayerStats, onProfile, onGoToTournaments, onOpenTournament }) {
  const [allMatchesLite, setAllMatchesLite] = useState([]); // ★games/players無しの軽量データ（全体の勝敗集計用）
  const [liveMatch, setLiveMatch] = useState(null);
  const [recent, setRecent] = useState([]);
  const [upcoming, setUpcoming] = useState([]);   // ★これから行う予定の試合
  const [linkedMatches, setLinkedMatches] = useState([]);
  const [tournaments, setTournaments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState(null);
  const [linkedPlayerName, setLinkedPlayerName] = useState(null);
  const [showNewModal, setShowNewModal] = useState(false);
  const [mySchoolName, setMySchoolName] = useState(""); // ★自チーム同士の練習試合判定用
  const [playerRoster, setPlayerRoster] = useState([]); // ★次の試合予定カードの参加選手表示用
  const [participantsModalFor, setParticipantsModalFor] = useState(null); // ★「参加選手」タップ時のポップアップ（大会オブジェクト）

  // ★選手マスターは下の初期読み込みの中でも取得しているため、ここでの重複取得は廃止した。
  // ★以前はgetMatches()でチームの利用期間中の全試合を、出場選手・ゲームごとの得点
  //   付きで取得していたため、試合数が増えるほどホーム画面の表示が遅くなっていた。
  //   ホーム画面が実際に使うのは「進行中の試合」「直近数件のカード」「全体の勝敗数」
  //   「紐づけ選手の勝敗」だけなので、それに絞った軽量取得(getHomeScreenData)に変更。
  //   紐づけ選手名を先に判定してから渡す必要があるため、プロフィール取得と統合した。
  //   ★さらに、以前は「プロフィール → 選手マスター → 学校一覧 → 試合データ」を
  //   　1つずつ順番待ちで取得していたため、通信の往復を4回ぶん重ねて待っていた。
  //   　互いに依存しないものは同時に取得し、待ち時間を2回ぶんに減らす。
  //   　（選手マスターは別のuseEffectでも取得していたので、そちらは廃止して1回にまとめた）
  //   ★他の画面から戻ってきたときも、前回の内容をキャッシュから即表示してから
  //   　裏で最新に差し替える（毎回「読み込み中...」で待たされない）。
  const apply = useCallback(({ p, roster, tns, schoolName, homeData }) => {
    setProfile(p);
    setPlayerRoster(roster);
    setTournaments(tns);
    setMySchoolName(schoolName);
    setLinkedPlayerName(homeData.linkedPlayerName ?? null);
    setAllMatchesLite(homeData.allMatchesLite);
    setLiveMatch(homeData.liveMatch);
    setRecent(homeData.recent);
    setUpcoming(homeData.upcoming ?? []);
    setLinkedMatches(homeData.linkedMatches);
    setLoading(false);
  }, []);

  useEffect(() => {
    const cached = readScreenCache("home");
    if (cached) apply(cached); // まず前回の内容を即表示（裏で最新化を続ける）
    (async () => {
      const [p, roster, schools, tns] = await Promise.all([
        getMyProfile(), getPlayerRoster(), getSchools(), getTournaments(),
      ]);
      let linkedName = null;
      if (p?.linked_player_id) {
        const found = (roster || []).find(r => r.id === p.linked_player_id);
        linkedName = found?.player_name ?? null;
      }
      const school = p?.school_id ? (schools || []).find(s => s.id === p.school_id) : null;
      const homeData = await getHomeScreenData(linkedName);
      const snapshot = {
        p, roster, tns,
        schoolName: school?.name ?? "",
        homeData: { ...homeData, linkedPlayerName: linkedName },
      };
      writeScreenCache("home", snapshot);
      apply(snapshot);
      // ★ホーム画面の表示が終わったら、試合一覧のデータを裏で先に取得しておく
      //   （「試合」を押したときに、読み込みを待たずに大会一覧を出せるように）
      setTimeout(prefetchMatchList, 300);
      setTimeout(prefetchAnalysisBase, 1500); // ★分析メニュー（個人）の表示に必要なデータも先に取っておく
    })();
  }, [apply]);

  const finished = useMemo(() => allMatchesLite.filter(countsAsFinished), [allMatchesLite]);
  const wins = useMemo(() => finished.filter(m=>winnerSideOf(m)==="A").length, [finished]);

  // ★進行中がない場合に表示する、直近の大会予定（大会単位）
  // 同じ日に複数の大会・練習試合がある場合は、すべて表示する
  const todayStr = today();
  const upcomingTournaments = !liveMatch
    ? (() => {
        const sorted = tournaments
          .filter(t => (t.end_date || t.start_date) >= todayStr)
          .sort((a,b) => a.start_date.localeCompare(b.start_date));
        if (sorted.length === 0) return [];
        const nearestDate = sorted[0].start_date;
        return sorted.filter(t => t.start_date === nearestDate);
      })()
    : [];

  // ★成績サマリー：試合数が少ないうちは「集計中」表示に
  const STATS_MIN = 5;
  const isStatsReady = finished.length >= STATS_MIN;
  // ★直近5試合の調子（新しい順）
  const last5 = finished.slice(0, 5).map(m => winnerSideOf(m)==="A");

  // ★紐づけ選手（お子さん/自分）の戦績（getHomeScreenDataで既にその選手の試合だけに絞込済み）
  const linkedFinished = linkedMatches.filter(countsAsFinished);
  function linkedIsWin(m) {
    return winForPlayer(m, linkedPlayerName, mySchoolName);
  }
  const linkedWins = linkedFinished.filter(linkedIsWin).length;
  const linkedWinRate = linkedFinished.length>0 ? Math.round(linkedWins/linkedFinished.length*100) : 0;

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <span style={{ fontSize:20,fontWeight:800,color:C.white }}>
          {profile?.name ? `${profile.name}さん、こんにちは` : "ホーム"}
        </span>
      </div>
      <div style={{ padding:14, paddingBottom:90 }}>
        {loading ? (
          <div style={{ textAlign:"center",color:C.textSec,marginTop:60 }}>読み込み中...</div>
        ) : (
          <>
            {/* ①進行中の試合カード */}
            {liveMatch && (() => {
              const aP = liveMatch.players.filter(p=>p.team==="A").map(p=>p.player_name).join("/");
              const bP = liveMatch.players.filter(p=>p.team==="B").map(p=>p.player_name).join("/");
              const bC = liveMatch.players.find(p=>p.team==="B")?.club_name ?? "";
              return (
                <div style={{ ...S.card, padding:16, marginBottom:14, borderLeft:`4px solid ${C.navy}` }}>
                  <div style={{ fontSize:11,fontWeight:800,color:C.navy,marginBottom:8 }}>記録途中の試合があります</div>
                  <div style={{ fontSize:15,fontWeight:800,color:C.text,marginBottom:2 }}>{aP} vs {bC} {bP}</div>
                  <div style={{ fontSize:12,color:C.textSec,marginBottom:12 }}>
                    {fmtDate(liveMatch.match_date)}{liveMatch.tournament_name ? ` ・ ${liveMatch.tournament_name}` : ""}
                  </div>
                  <button style={{ ...S.btn(C.navy) }} onClick={()=>onOpen(liveMatch.id)}>記録を続ける →</button>
                </div>
              );
            })()}

            {/* ②次の試合予定カード（進行中がない場合のみ、大会基準／同日複数件はすべて表示） */}
            {upcomingTournaments.length > 0 && (
              <div style={{ marginBottom:14 }}>
                <div style={{ fontSize:11,fontWeight:800,color:C.textSec,marginBottom:8 }}>次の試合予定</div>
                {upcomingTournaments.map((t, idx) => {
                  const d = daysUntil(t.start_date);
                  const countdownLabel = d >= 0 ? `あと${d}日` : "";
                  const participantCount = (t.participant_player_ids || []).length;
                  return (
                  <div key={t.id ?? idx} style={{ ...S.card, padding:16, marginBottom: idx===upcomingTournaments.length-1?0:10, borderLeft:`4px solid ${C.textSec}` }}>
                    <div style={{ cursor:"pointer" }} onClick={()=>onOpenTournament && onOpenTournament(t)}>
                      {/* ★大会一覧と同じく、日付（曜日付き）を大会名の上に大きく表示する */}
                      <div style={{ display:"flex", alignItems:"baseline", justifyContent:"space-between", gap:8 }}>
                        <div style={{ fontSize:16,fontWeight:700,color:"#5a6478",marginBottom:2 }}>{fmtDateRangeDow(t.start_date, t.end_date)}</div>
                        {countdownLabel && (
                          <div style={{ fontSize:16,fontWeight:800,color:C.red,whiteSpace:"nowrap" }}>{countdownLabel}</div>
                        )}
                      </div>
                      <div style={{ fontSize:16,fontWeight:800,color:C.text }}>{t.name}</div>
                    </div>
                    {/* ★参加選手・地図・要項を1行にまとめてスペースを節約 */}
                    {(participantCount > 0 || t.venue_link || t.guideline_url) && (
                      <div style={{ display:"flex", gap:8, marginTop:12 }}>
                        {participantCount > 0 && (
                          <button
                            style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", gap:4, borderRadius:10, padding:"9px 4px", fontSize:12, fontWeight:700, background:"#fff", color:"#1e2a44", border:"1px solid #e5e7eb", cursor:"pointer", whiteSpace:"nowrap" }}
                            onClick={e=>{ e.stopPropagation(); setParticipantsModalFor(t); }}
                          ><span>👥</span> {participantCount}人</button>
                        )}
                        {(t.venue_link || t.guideline_url) && (<>
                        <button
                          disabled={!t.venue_link}
                          style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", gap:5, borderRadius:10, padding:"9px 6px", fontSize:12, fontWeight:700, background:"#fff", color: t.venue_link ? "#1e2a44" : "#c3c9d4", border:"1px solid #e5e7eb", cursor: t.venue_link ? "pointer" : "default" }}
                          onClick={e=>{ e.stopPropagation(); if (t.venue_link) window.open(t.venue_link, "_blank", "noopener,noreferrer"); }}
                        ><span style={{ color: t.venue_link ? "#e53935" : "#c3c9d4" }}>📍</span> 地図</button>
                        <button
                          disabled={!t.guideline_url}
                          style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", gap:5, borderRadius:10, padding:"9px 6px", fontSize:12, fontWeight:700, background:"#fff", color: t.guideline_url ? "#1e2a44" : "#c3c9d4", border:"1px solid #e5e7eb", cursor: t.guideline_url ? "pointer" : "default" }}
                          onClick={e=>{ e.stopPropagation(); if (t.guideline_url) window.open(t.guideline_url, "_blank", "noopener,noreferrer"); }}
                        ><span style={{ color: t.guideline_url ? "#1976d2" : "#c3c9d4" }}>📄</span> 要項</button>
                        </>)}
                      </div>
                    )}
                  </div>
                  );
                })}
              </div>
            )}

            {/* 参加選手一覧ポップアップ */}
            {participantsModalFor && (
              <Modal onClose={()=>setParticipantsModalFor(null)}>
                <h3 style={{ fontSize:15, fontWeight:800, marginBottom:12, textAlign:"center" }}>👥 参加選手一覧</h3>
                {(() => {
                  const names = playerRoster.filter(p => (participantsModalFor.participant_player_ids || []).includes(p.id)).map(p => p.player_name);
                  if (names.length === 0) {
                    return <div style={{ fontSize:12, color:C.textSec, textAlign:"center", padding:"12px 0" }}>出場選手が登録されていません。</div>;
                  }
                  return <div>{names.map(n => <span key={n} style={S.chip(false)}>{n}</span>)}</div>;
                })()}
                <button style={{ ...S.btn("#f0f0f0"), color:C.text, marginTop:16 }} onClick={()=>setParticipantsModalFor(null)}>閉じる</button>
              </Modal>
            )}

            {/* ③サマリーカード */}
            <div style={{ ...S.card, padding:16, marginBottom:14 }}>
              <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",textAlign:"center" }}>
                <div>
                  <div style={{ fontSize:22,fontWeight:800,color:C.navy }}>{finished.length}</div>
                  <div style={{ fontSize:11,color:C.textSec }}>総試合数</div>
                </div>
                <div>
                  {isStatsReady ? (
                    <div style={{ fontSize:22,fontWeight:800,color:C.navy }}>{wins}勝{finished.length-wins}敗</div>
                  ) : (
                    <div style={{ fontSize:14,fontWeight:700,color:C.textSec }}>集計中</div>
                  )}
                  <div style={{ fontSize:11,color:C.textSec }}>戦績{!isStatsReady && finished.length>0 ? `（${wins}勝${finished.length-wins}敗）` : ""}</div>
                </div>
                <div>
                  {last5.length>0 ? (
                    <div style={{ display:"flex",justifyContent:"center",gap:4 }}>
                      {last5.map((w,i)=>(
                        <div key={i} style={{ width:16,height:16,borderRadius:"50%",fontSize:10,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center",border:`1px solid ${w?C.navy:C.border}`,color:w?C.text:C.textSec }}>{w?"勝":"負"}</div>
                      ))}
                    </div>
                  ) : (
                    <div style={{ fontSize:14,fontWeight:700,color:C.textSec }}>ー</div>
                  )}
                  <div style={{ fontSize:11,color:C.textSec,marginTop:last5.length>0?6:4 }}>直近{last5.length||5}試合の調子</div>
                </div>
              </div>
            </div>

            {showNewModal && (
              <Modal onClose={()=>setShowNewModal(false)}>
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontSize:32, marginBottom:8 }}>🎾</div>
                  <h3 style={{ fontSize:16, fontWeight:800, marginBottom:16 }}>どちらの試合を記録しますか？</h3>
                  <div style={{ display:"flex", flexDirection:"column", gap:10, marginBottom:12 }}>
                    <button
                      style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), padding:"14px" }}
                      onClick={()=>{ setShowNewModal(false); onNew(); }}
                    >
                      <div style={{ fontSize:15, fontWeight:700, display:"flex", alignItems:"center", justifyContent:"center" }}><span style={{ display:"inline-flex", background:"#fff", borderRadius:7, padding:2, marginRight:8, verticalAlign:"middle" }}><SoloIcon size={22}/></span>個人戦</div>
                      <div style={{ fontSize:11, opacity:0.85, marginTop:2 }}>ダブルス・シングルスの1試合を記録</div>
                    </button>
                    <button
                      style={{ ...S.btn(`linear-gradient(135deg,${C.navy},${C.navyMid})`), padding:"14px" }}
                      onClick={()=>{ setShowNewModal(false); onNewTeamMatch && onNewTeamMatch(); }}
                    >
                      <div style={{ fontSize:15, fontWeight:700, display:"flex", alignItems:"center", justifyContent:"center" }}><span style={{ display:"inline-flex", background:"#fff", borderRadius:7, padding:2, marginRight:8, verticalAlign:"middle" }}><TeamIcon size={22}/></span>団体戦</div>
                      <div style={{ fontSize:11, opacity:0.85, marginTop:2 }}>3番手制の団体戦を登録</div>
                    </button>
                    <button
                      style={{ ...S.btn(`linear-gradient(135deg,#6366f1,#4f52d1)`), padding:"14px" }}
                      onClick={()=>{ setShowNewModal(false); onGoToTournaments && onGoToTournaments(); }}
                    >
                      <div style={{ fontSize:15, fontWeight:700 }}>📋 大会から作成</div>
                      <div style={{ fontSize:11, opacity:0.85, marginTop:2 }}>大会に紐づけて試合を記録</div>
                    </button>
                  </div>
                  <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13 }} onClick={()=>setShowNewModal(false)}>キャンセル</button>
                </div>
              </Modal>
            )}

            {linkedPlayerName && (
              <div style={{ ...S.card, padding:16, marginBottom:14, border:`1px solid ${C.navy}22` }}>
                <div style={{ fontSize:13,fontWeight:700,color:C.navy,marginBottom:10 }}>🎾 {linkedPlayerName}さんの戦績</div>
                {linkedFinished.length===0 ? (
                  <>
                    <div style={{ fontSize:12,color:C.textSec,marginBottom:10 }}>まだ試合記録がありません</div>
                    <button style={{ ...S.btn("#f4f6fa"), color:C.navy, border:`1px solid ${C.border}`, fontSize:12, fontWeight:700, padding:9 }} onClick={onNew}>この選手の試合を記録する</button>
                  </>
                ) : (
                  <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1.35fr",textAlign:"center" }}>
                    <div>
                      <div style={{ fontSize:18,fontWeight:800,color:C.navy }}>{linkedFinished.length}</div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>試合数</div>
                    </div>
                    <div>
                      <div style={{ fontSize:18,fontWeight:800,color:C.accent }}>{linkedWinRate}%</div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>勝率</div>
                    </div>
                    <div>
                      <div style={{ fontSize:18,fontWeight:800,color:C.navy }}><WinLossText wins={linkedWins} losses={linkedFinished.length-linkedWins} /></div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>戦績</div>
                    </div>
                  </div>
                )}
              </div>
            )}

            <button
              style={{ ...S.btn(C.navy), marginBottom:18, display:"flex",alignItems:"center",justifyContent:"center",gap:6 }}
              onClick={onGoPlayerStats}
            >👥 他の選手の戦績を見る</button>

            {/* ★「これからの試合」と「終わった試合」を分けて表示する。
                  以前はまとめて『最近の試合』として出していたため、先の予定が
                  『最近の試合』として並んでしまい分かりにくかった。 */}
            {(() => {
              const renderCard = (m) => {
                const aWin = winnerSideOf(m)==="A";
                const aP = m.players.filter(p=>p.team==="A").map(p=>p.player_name).join("/");
                const bP = m.players.filter(p=>p.team==="B").map(p=>p.player_name).join("/");
                const bC = m.players.find(p=>p.team==="B")?.club_name??"";
                const done = m.status==="finished";
                return (
                  <div key={m.id} style={{ ...S.card, padding:"12px 14px", marginBottom:8, cursor:"pointer" }} onClick={()=>onOpen(m.id)}>
                    <div style={{ display:"flex",justifyContent:"space-between",marginBottom:4 }}>
                      <span style={{ fontSize:12,fontWeight:700 }}>{m.tournament_name||"試合"}</span>
                      <span style={{ fontSize:11,color:C.textSec }}>{fmtDate(m.match_date)}</span>
                    </div>
                    <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",gap:8 }}>
                      <span style={{ fontSize:12,color:C.textSec }}>{aP}{(bC||bP) ? ` vs ${bC} ${bP}` : ""}</span>
                      <span style={{ fontSize:14,fontWeight:800,color:done?(aWin?"#2ecc71":"#f97316"):C.textSec,whiteSpace:"nowrap" }}>
                        {matchStatusShortLabel(m)}
                      </span>
                    </div>
                  </div>
                );
              };
              return (
                <>
                  {allMatchesLite.length===0 && <div style={{ textAlign:"center",color:C.textSec,padding:"20px 0" }}>まだ試合記録がありません</div>}

                  {upcoming.length>0 && (
                    <>
                      <div style={{ fontSize:13,fontWeight:700,color:C.navy,marginBottom:8 }}>🎾 これからの試合</div>
                      {upcoming.map(renderCard)}
                      <div style={{ height:14 }} />
                    </>
                  )}

                  {recent.length>0 && (
                    <>
                      <div style={{ fontSize:13,fontWeight:700,color:C.navy,marginBottom:8 }}>📋 終わった試合</div>
                      {recent.map(renderCard)}
                    </>
                  )}

                  {allMatchesLite.length>0 && (
                    <button style={{ ...S.btn("#f0f0f0"),color:C.text,fontSize:13 }} onClick={()=>onNavigate("list")}>すべての試合を見る →</button>
                  )}
                </>
              );
            })()}
          </>
        )}
      </div>
      <NavBar active="home" onNavigate={onNavigate}/>
    </div>
  );
}

// ============================================================
// 団体戦 予定登録画面
// ============================================================
function TeamMatchSetup({ editId, copyId, onSave, onCancel, prefillTournament, prefillDate, prefillVenue, lockTournament, tournamentStartDate, tournamentEndDate }) {
  const [ready, setReady] = useState(!editId && !copyId);
  const [saving, setSaving] = useState(false);
  const [matchDate, setMatchDate] = useState(prefillDate || today());
  const [venue, setVenue] = useState(prefillVenue || "");
  const [tournamentName, setTournamentName] = useState(prefillTournament || "");
  const [round, setRound] = useState("");
  const [myTeamDivision, setMyTeamDivision] = useState("");
  const [opponentName, setOpponentName] = useState("");
  const [opponentDivision, setOpponentDivision] = useState("");
  const [myEntryNo, setMyEntryNo] = useState(""); // ★自チームの出場番号（任意・若番/遅番の自動判定に使う）
  const [opponentEntryNo, setOpponentEntryNo] = useState(""); // ★相手チームの出場番号（任意）
  const [format, setFormat] = useState("best2");
  const [courtNumber, setCourtNumber] = useState("");
  const [isYounger, setIsYounger] = useState(null); // ★デフォルトは未選択（必ず選んでもらう）
  const [showMatchInfo, setShowMatchInfo] = useState(false); // 試合情報の表示/非表示（デフォルト：非表示、個人戦フォームと統一）
  const [schools, setSchools] = useState([]); // SchoolField用（名前リスト、idなし）
  const [schoolsWithId, setSchoolsWithId] = useState([]); // id解決用
  const [venues, setVenues] = useState([]);
  const [mySchoolId, setMySchoolId] = useState(null);
  const [mySchoolName, setMySchoolName] = useState(""); // 表示用
  const [mySchoolInitialized, setMySchoolInitialized] = useState(false); // プロフィール初期化済みフラグ
  const [mySchoolChanging, setMySchoolChanging] = useState(false); // 変更確認ポップ
  const [mySchoolPrefFilter, setMySchoolPrefFilter] = useState(""); // 自チーム側の都道府県フィルタ
  const [mySchoolDraft, setMySchoolDraft] = useState(""); // ★変更ポップでの入力途中の学校名（決定するまで反映しない）
  const [existingId, setExistingId] = useState(null);
  // 過去の団体戦から候補を取得
  const [pastTournaments, setPastTournaments] = useState([]);
  const [pastRounds, setPastRounds] = useState([]);
  const [pastCourtNumbers, setPastCourtNumbers] = useState([]);
  const [pastDivisions, setPastDivisions] = useState([]);
  const [oppPrefFilter, setOppPrefFilter] = useState("");

  useEffect(() => {
    // ★候補（大会名・回戦など）のためだけに全団体戦を番手・動画まで取得していたのを、必要な項目だけにした
    Promise.all([getSchools(), getKnownSchools(), getKnownVenues(), getMyProfile(), getTeamMatchSuggestions()]).then(([sWithId, sForUI, v, p, tms]) => {
      setSchools(sForUI); // SchoolField用（名前リスト）
      setSchoolsWithId(sWithId); // id解決用
      setVenues(v);
      // mySchoolIdの初期化はsWithId（id付き）を使う
      const s = sWithId;
      if (p?.school_id) {
        // 手動変更済みでない場合のみプロフィールの学校で初期化
        setMySchoolInitialized(alreadyInit => {
          if (alreadyInit) return true; // 変更済みなら何もしない
          setMySchoolId(p.school_id);
          const found = s.find(sc => sc.id === p.school_id);
          if (found) setMySchoolName(found.name);
          return true;
        });
      }
      // 過去の団体戦からサジェスト候補を生成
      setPastTournaments([...new Set(tms.map(m=>m.tournament_name).filter(Boolean))]);
      setPastRounds([...new Set(tms.map(m=>m.round).filter(Boolean))]);
      setPastCourtNumbers([...new Set(tms.map(m=>m.court_number).filter(Boolean))]);
      setPastDivisions([...new Set(tms.map(m=>m.my_team_division).filter(Boolean))]);
    });
    if (editId) {
      getTeamMatch(editId).then(tm => {
        if (!tm) { setReady(true); return; }
        setExistingId(tm.id);
        setMatchDate(tm.match_date || today());
        setVenue(tm.venue || "");
        setTournamentName(tm.tournament_name || "");
        setRound(tm.round || "");
        setMyTeamDivision(tm.my_team_division || "");
        setOpponentName(tm.opponent_name || "");
        setOpponentDivision(tm.opponent_division || "");
        setMyEntryNo(tm.my_entry_no || "");
        setOpponentEntryNo(tm.opponent_entry_no || "");
        setFormat(tm.format || "best2");
        setCourtNumber(tm.court_number || "");
        setIsYounger(tm.is_younger !== false);
        // 編集時：保存済みmy_school_idで名前を復元し、プロフィールによる上書きを防ぐ
        if (tm.my_school_id) {
          setMySchoolId(tm.my_school_id);
          setMySchoolInitialized(true);
          Promise.all([getSchools()]).then(([sc])=>{
            const found = sc.find(s=>s.id===tm.my_school_id);
            if (found) setMySchoolName(found.name);
          });
        }
        setReady(true);
      });
    } else if (copyId) {
      getTeamMatch(copyId).then(tm => {
        if (!tm) { setReady(true); return; }
        // コピー：IDは新規、スコアはクリア
        setMatchDate(today());
        setVenue(tm.venue || "");
        setTournamentName(tm.tournament_name || "");
        setRound(tm.round || "");
        setMyTeamDivision(tm.my_team_division || "");
        setOpponentName(tm.opponent_name || "");
        setOpponentDivision(tm.opponent_division || "");
        // ★出場番号は回戦ごとに変わるため、コピー時は引き継がず空欄にする
        setFormat(tm.format || "best2");
        setCourtNumber(tm.court_number || "");
        setIsYounger(tm.is_younger !== false);
        setReady(true);
      });
    }
  }, [editId]);

  // ★若番／遅番の自動判定：自チーム・相手チーム両方の出場番号が数値であれば、
  //   番号が小さい方＝若番として自動的に決める。
  const myEntryNoNum = Number(myEntryNo.trim());
  const oppEntryNoNum = Number(opponentEntryNo.trim());
  const teamBothEntryNosNumeric = myEntryNo.trim() !== "" && opponentEntryNo.trim() !== "" && !isNaN(myEntryNoNum) && !isNaN(oppEntryNoNum);
  useEffect(() => {
    if (teamBothEntryNosNumeric) setIsYounger(myEntryNoNum < oppEntryNoNum);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [teamBothEntryNosNumeric, myEntryNoNum, oppEntryNoNum]);

  const canSave = isYounger !== null;

  async function handleSave() {
    setSaving(true);
    try {
      const id = existingId || uid();
      // ★自チームに学校マスターに無い学校名を入れた場合は、ここで学校として登録してから保存する
      let schoolIdToSave = mySchoolId;
      if (!schoolIdToSave && mySchoolName.trim()) {
        const fresh = await getSchools(true).catch(() => schoolsWithId);
        const same = (fresh || []).find(s => s.name === mySchoolName.trim());
        if (same) schoolIdToSave = same.id;
        else {
          try {
            const created = await addSchool(mySchoolName.trim(), mySchoolPrefFilter || null, null, "mixed");
            schoolIdToSave = created.id;
          } catch (e) {
            throw new Error(`学校「${mySchoolName.trim()}」を登録できませんでした（学校マスターに追加する権限が無い可能性があります）。\n${e?.message || e}`);
          }
        }
        setMySchoolId(schoolIdToSave);
      }
      const tm = {
        id, match_date: matchDate, venue, tournament_name: tournamentName,
        round, my_school_id: schoolIdToSave, my_team_division: myTeamDivision,
        opponent_name: opponentName.trim(), opponent_division: opponentDivision,
        my_entry_no: myEntryNo.trim() || null, opponent_entry_no: opponentEntryNo.trim() || null,
        format, status: existingId ? undefined : "scheduled",
        court_number: courtNumber, is_younger: isYounger,
      };
      await saveTeamMatch(tm);
      onSave(id);
    } catch(e) {
      alert("保存エラー: " + (e.message || e));
    } finally {
      setSaving(false);
    }
  }

  if (!ready) return <div style={S.page}><div style={S.hdr}><span style={{ fontSize:18,fontWeight:800,color:C.white }}>読み込み中...</span></div></div>;

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
          <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onCancel}>←</button>
          <span style={{ fontSize:18,fontWeight:800,color:C.white, display:"inline-flex", alignItems:"center", gap:6 }}><TeamIcon size={22} light/>団体戦情報登録{editId ? "（編集）" : ""}</span>
        </div>
      </div>
      <div style={{ padding:14 }}>
        <div style={{ marginBottom:14 }}>
          <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
            <span style={{ fontSize:11,fontWeight:700,color:C.navy,letterSpacing:"0.05em" }}>試合情報</span>
            <button
              style={{ background:"#eef0f4", border:"none", borderRadius:20, padding:"4px 12px", fontSize:11, fontWeight:700, color:C.navy, cursor:"pointer" }}
              onClick={() => setShowMatchInfo(v => !v)}
            >
              {showMatchInfo ? "非表示 ▲" : "表示 ▼"}
            </button>
          </div>
          {showMatchInfo && (
          <div style={{ background:C.white,borderRadius:12,border:`1px solid ${C.border}`,overflow:"visible" }}>
          <FormRow label="大会名">
            {lockTournament ? (
              <div style={{ ...S.inp, display:"flex", justifyContent:"space-between", alignItems:"center", fontWeight:700 }}>
                <span>{tournamentName}</span>
                <span style={{ fontSize:12, color:C.textSec, background:"#e2e5eb", padding:"4px 6px", borderRadius:10, fontWeight:700 }}>🔒</span>
              </div>
            ) : (
              <VenueField value={tournamentName} onChange={setTournamentName} venues={pastTournaments} placeholder="例：○○高校選手権"/>
            )}
          </FormRow>
          <FormRow label="試合日">
            {lockTournament && tournamentStartDate && tournamentEndDate && tournamentStartDate !== tournamentEndDate ? (
              <div>
                <input type="date" style={S.inp} value={matchDate} min={tournamentStartDate} max={tournamentEndDate} onChange={e=>setMatchDate(e.target.value)}/>
                <div style={{ fontSize:10, color:C.textSec, marginTop:4 }}>📅 大会期間（{fmtDate(tournamentStartDate)}〜{fmtDate(tournamentEndDate)}）内から選択できます</div>
              </div>
            ) : lockTournament ? (
              <div style={{ ...S.inp, display:"flex", justifyContent:"space-between", alignItems:"center", fontWeight:700 }}>
                <span>{fmtDate(matchDate)}</span>
                <span style={{ fontSize:10, color:C.textSec, background:"#e2e5eb", padding:"2px 8px", borderRadius:10, fontWeight:700 }}>🔒 大会の日程</span>
              </div>
            ) : (
              <input type="date" style={S.inp} value={matchDate} onChange={e=>setMatchDate(e.target.value)}/>
            )}
          </FormRow>
          <FormRow label="場所 / 会場名">
            <VenueField value={venue} onChange={setVenue} venues={venues}/>
          </FormRow>
          <FormRow label="形式">
            <div style={{ display:"flex", gap:8 }}>
              <button style={{ ...S.togBtn(format==="best2", C.navy), flex:1 }} onClick={()=>setFormat("best2")}>2勝先取</button>
              <button style={{ ...S.togBtn(format==="all3", C.navy), flex:1 }} onClick={()=>setFormat("all3")}>3試合全部</button>
            </div>
          </FormRow>
          </div>
          )}
        </div>

        <div style={{ display:"flex", alignItems:"center", fontSize:11.5, color:C.textSec, marginBottom:10 }}>
          <RequiredDot />は必須項目です（それ以外は空欄でも作成できます）
        </div>

        <FormSec title="チーム情報">
          <FormRow label="自チーム名">
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <div style={{ ...S.inp, flex:1, background:C.gray, color:C.text, display:"flex", alignItems:"center", minHeight:38 }}>
                {mySchoolName || "（プロフィールから自動入力）"}
              </div>
              <button
                style={{ padding:"8px 12px", borderRadius:8, border:"1px solid "+C.border, background:C.white, color:C.navy, fontSize:12, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap" }}
                onClick={()=>(setMySchoolDraft(""), setMySchoolChanging(true))}
              >変更</button>
            </div>
          </FormRow>
          <FormRow label="自チーム区分（任意）">
            <VenueField value={myTeamDivision} onChange={setMyTeamDivision} venues={pastDivisions} placeholder="例：Aチーム"/>
          </FormRow>
          <FormRow label="自チームの出場番号（任意）">
            <input style={S.inp} placeholder="例：12" inputMode="numeric" value={myEntryNo} onChange={e=>setMyEntryNo(e.target.value)}/>
          </FormRow>
          <FormRow label="相手校名（任意）" labelRight={<PrefMiniFilter value={oppPrefFilter} onChange={setOppPrefFilter} options={knownPrefsFrom(schools)} />}>
            <SchoolField value={opponentName} onChange={setOpponentName} schools={schools} placeholder="例：鹿児島実業（未定なら空欄でOK）" prefFilter={oppPrefFilter}/>
          </FormRow>
          <FormRow label="相手チーム区分（任意）">
            <input style={S.inp} placeholder="例：Bチーム" value={opponentDivision} onChange={e=>setOpponentDivision(e.target.value)}/>
          </FormRow>
          <FormRow label="相手チームの出場番号（任意）">
            <input style={S.inp} placeholder="例：13" inputMode="numeric" value={opponentEntryNo} onChange={e=>setOpponentEntryNo(e.target.value)}/>
          </FormRow>
        </FormSec>

        <FormSec title="試合詳細">
          <FormRow label="何回戦（任意）">
            <RoundField value={round} onChange={setRound} placeholder="例：準々決勝"/>
          </FormRow>
          <FormRow label="コート番号（任意）">
            <VenueField value={courtNumber} onChange={setCourtNumber} venues={pastCourtNumbers} placeholder="例：3番コート"/>
          </FormRow>
          <FormRow label="若番 / 遅番（必須）" required>
            {teamBothEntryNosNumeric ? (
              <div style={{ fontSize:11.5, color:C.textSec, background:C.gray, borderRadius:8, padding:"8px 10px" }}>
                ✓ 出場番号（{myEntryNo} と {opponentEntryNo}）から自動判定：<b style={{ color:C.navy }}>{isYounger ? "若番" : "遅番"}</b>
                <div style={{ fontSize:10.5, color:C.textSec, marginTop:2 }}>変更したい場合は番号欄を空欄にしてください</div>
              </div>
            ) : (
              <>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>自チームはトーナメント表のどちら側ですか？</div>
                <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                  <button style={S.togBtn(isYounger===true, C.navy)} onClick={()=>setIsYounger(true)}>若番</button>
                  <button style={S.togBtn(isYounger===false, C.navy)} onClick={()=>setIsYounger(false)}>遅番</button>
                </div>
              </>
            )}
          </FormRow>
        </FormSec>

        <button
          style={{ ...S.btn(canSave && !saving ? `linear-gradient(135deg,${C.accent},#00a066)` : C.border, canSave && !saving ? C.white : C.textSec), marginTop:8 }}
          disabled={!canSave || saving}
          onClick={handleSave}
        >
          {saving ? "保存中..." : "💾 保存する"}
        </button>
      </div>

      {/* 自チーム変更確認ポップ */}
      {mySchoolChanging && (
        <Modal onClose={()=>{ setMySchoolChanging(false); setMySchoolPrefFilter(""); }}>
          <div>
            <h3 style={{ fontSize:15, fontWeight:800, marginBottom:6 }}>自チームを変更しますか？</h3>
            <p style={{ fontSize:12, color:C.textSec, marginBottom:14 }}>他校の団体戦を記録する場合など、自チームを変更できます。</p>
            <PrefMiniFilter value={mySchoolPrefFilter} onChange={setMySchoolPrefFilter} options={knownPrefsFrom(schools)} />
            {/* ★以前は1文字入力した時点でポップが閉じてしまい、候補に無い学校名を入れられなかった。
                候補をタップしたときはすぐ確定、手入力のときは「決定」を押すまで確定しない。 */}
            <SchoolField
              value={mySchoolDraft}
              onChange={name => {
                setMySchoolDraft(name);
                // 候補（学校マスター）と完全一致したら、その学校で確定する
                const found = schoolsWithId.find(s => s.name === name);
                if (found) {
                  setMySchoolId(found.id);
                  setMySchoolName(found.name);
                  setMySchoolInitialized(true);
                  setMySchoolChanging(false);
                  setMySchoolPrefFilter("");
                }
              }}
              schools={schools}
              placeholder="学校名を入力・選択"
              prefFilter={mySchoolPrefFilter}
            />
            {mySchoolDraft.trim() && !schoolsWithId.some(s => s.name === mySchoolDraft.trim()) && (
              <div style={{ fontSize:11.5, color:C.textSec, marginTop:6, lineHeight:1.6 }}>候補に無い学校名は、保存するときに新しい学校として登録されます。</div>
            )}
            <div style={{ display:"flex", gap:8, marginTop:14 }}>
              <button style={{ flex:1, padding:10, borderRadius:10, border:"1px solid "+C.border, background:C.white, color:C.text, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>{ setMySchoolChanging(false); setMySchoolPrefFilter(""); }}>キャンセル</button>
              <button
                disabled={!mySchoolDraft.trim()}
                style={{ flex:1, padding:10, borderRadius:10, border:"none", background:mySchoolDraft.trim()?C.accent:C.border, color:C.white, fontSize:13, fontWeight:700, cursor:mySchoolDraft.trim()?"pointer":"default" }}
                onClick={()=>{
                  const name = mySchoolDraft.trim();
                  if (!name) return;
                  const found = schoolsWithId.find(s => s.name === name);
                  setMySchoolId(found ? found.id : null); // 新しい学校は保存時に登録してidを付ける
                  setMySchoolName(name);
                  setMySchoolInitialized(true);
                  setMySchoolChanging(false);
                }}
              >決定</button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ============================================================
// 団体戦 詳細画面（リアルタイム観戦含む）
// ============================================================
function TeamMatchDetail({ teamMatchId, onBack, onOpenMatch, onNewMatch, onStartMatch, onEdit, onEditPlayers, onNavigate, onOpenAiAnalysis, onCopyMatch }) {
  const isViewer = useIsViewer(); // ★閲覧専用アカウントには記録・編集系を出さない
  // ★AI動画分析の閲覧は本人・保護者・管理者だけ（AI分析メニューと同じ基準）
  const aiViewer = useAiAnalysisViewer();
  const [tm, setTm] = useState(null);
  const [notFound, setNotFound] = useState(false); // ★削除済みなどで団体戦が見つからない場合
  const [loading, setLoading] = useState(true);
  const [liveActive, setLiveActive] = useState(true);
  const [lastUpdated, setLastUpdated] = useState(Date.now()); // ★最終更新時刻（差分確認・再開ボタン等で使用）
  const [myUserId, setMyUserId] = useState(null);
  const [myUserName, setMyUserName] = useState("");
  const [schoolMap, setSchoolMap] = useState({}); // school_id -> name
  const [matchDetails, setMatchDetails] = useState({});
  const [aiAnalyses, setAiAnalyses] = useState({}); // match_id -> AI分析行（あれば）
  const [serveSelectInfo, setServeSelectInfo] = useState(null); // サーブ選択モーダル用
  const [simpleResultFor, setSimpleResultFor] = useState(null); // ★結果だけ記録モーダル用（{orderNum, game, aLabel, bLabel, aPlayers, bPlayers}）
  const [simpleResultScoreA, setSimpleResultScoreA] = useState("");
  const [simpleResultScoreB, setSimpleResultScoreB] = useState("");
  const [simpleResultNamesA, setSimpleResultNamesA] = useState([]); // ★結果だけ記録：自チーム選手名（編集可）
  const [simpleResultNamesB, setSimpleResultNamesB] = useState([]); // ★結果だけ記録：相手選手名（編集可）
  const [simpleResultSaving, setSimpleResultSaving] = useState(false);
  const [videoView, setVideoView] = useState(null); // ★番手カードの🎥バッジから開く動画リンク一覧
  const [memoView, setMemoView] = useState(null); // ★番手カードの📝から開く試合メモ
  const [confirmDeleteBout, setConfirmDeleteBout] = useState(null); // ★番手の試合の削除確認 { matchId, gameId, orderNum }
  const [tmMenuOpen, setTmMenuOpen] = useState(false); // ★右上「⋯」メニュー（中断・途中終了・再開）
  const [confirmTmStop, setConfirmTmStop] = useState(false); // ★団体戦の途中終了の確認
  const [tmStatusSaving, setTmStatusSaving] = useState(false);
  const intervalRef = useRef(null);
  const inactiveRef = useRef(null);
  const lastSignatureRef = useRef(null); // ★変化検知用：前回確認時点の軽量シグネチャ
  const lastChangeAtRef = useRef(Date.now()); // ★実際にデータ変化を検知した時刻（無変化チェックでは更新しない）
  const pollingRef = useRef(false); // ★ポーリングの多重実行防止

  const INACTIVITY_MS = 20 * 60 * 1000; // 20分

  async function loadData({ markAsChanged = true } = {}) {
    // ★処理速度改善：以前は「団体戦スコアの再集計（通信3〜4往復）」が終わるまで画面の取得を始めなかったため、
    //   団体戦をタップしてから表示までに時間がかかっていた。再集計は裏で同時に走らせ、画面は先に表示する。
    //   再集計でスコアや状態が変わった場合は、終わった時点で表示を差し替える（下の「再集計の反映」）。
    const recalcPromise = recalcTeamMatchScore(teamMatchId).catch(e => { console.error(e); return null; });
    const [data, schools] = await Promise.all([
      getTeamMatch(teamMatchId),
      getSchools(),
    ]);
    if (!data) { setNotFound(true); setLoading(false); return; }
    // 学校IDマップを作成
    const smap = {};
    (schools || []).forEach(s => { smap[s.id] = s.name; });
    setSchoolMap(smap);
    const matchIds = (data.games || []).filter(g => g.match_id).map(g => g.match_id);
    if (matchIds.length > 0) {
      const { data: matches } = await supabase.from("matches").select("id,match_score_a,match_score_b,status,is_doubles,video_links,memo,order_a,order_b,receive_order_a,receive_order_b,match_players(id,team,player_name,club_name,order_num)").in("id", matchIds);
      const map = {};
      (matches || []).forEach(m => { map[m.id] = m; });
      setMatchDetails(map);
      getAiAnalyses(matchIds).then(rows => {
        const aiMap = {};
        rows.forEach(r => { aiMap[r.match_id] = r; });
        setAiAnalyses(aiMap);
      });
    }
    setTm(data);
    setLoading(false);
    if (markAsChanged) {
      lastChangeAtRef.current = Date.now();
    }
    setLastUpdated(Date.now());

    // ★再集計の反映：裏で走らせた再集計の結果を待ち、スコア・状態・番手の状態を最新にする
    const r = await recalcPromise;
    let latest = data;
    if (r && r.changed) {
      const fresh = await getTeamMatch(teamMatchId); // 番手の状態も同期されるので取り直す（変化があった時だけ）
      if (fresh) latest = fresh;
    }
    // ★不整合データの自動修復：どの番手も実際には開始されていないのに
    // 団体戦全体のstatusだけが"active"のまま残っているケースを検知し、"scheduled"に戻す。
    // （放置すると本当は始まっていない試合でLIVE自動更新が動き続けてしまう）
    // 　再集計が"active"に書き換えることがあるため、再集計が終わった後に行う（以前と同じ順序）。
    if (latest.status === "active" && !(latest.games || []).some(g => g.status === "active" || g.status === "finished")) {
      await supabase.from("team_matches").update({ status:"scheduled" }).eq("id", teamMatchId).eq("status","active");
      latest = { ...latest, status: "scheduled" };
    }
    if (latest !== data) setTm(latest);
    // 今回取得した内容を基準に、次回以降の「変化なし」判定用シグネチャを更新しておく
    lastSignatureRef.current = await getTeamMatchChangeSignature(teamMatchId, matchIds);
  }

  // ★品質改善（フェーズ2）：自動更新のたびに毎回すべて取り直すのではなく、
  // まず軽量な問い合わせで「前回確認時から何か変わったか」だけを確認し、
  // 変化が無ければ重い再取得（loadData／recalcTeamMatchScore）はスキップする。
  async function checkAndMaybeReload() {
    if (pollingRef.current) return false;
    pollingRef.current = true;
    try {
      const matchIds = (tm?.games || []).filter(g => g.match_id).map(g => g.match_id);
      const sig = await getTeamMatchChangeSignature(teamMatchId, matchIds);
      if (sig !== null && lastSignatureRef.current !== null && sig === lastSignatureRef.current) {
        // 変化なし：重い再取得はしない。lastChangeAtRefも更新しないため、
        // 20分間スコア変化がなければ自動更新を停止できる。
        return false;
      }
      await loadData({ markAsChanged: true });
      return true;
    } finally {
      pollingRef.current = false;
    }
  }

  useEffect(() => {
    getAuthUserFast().then(user => {
      setMyUserId(user?.id ?? null);
    });
    getMyProfile().then(p => { setMyUserName(p?.name || ""); });
    loadData();
  }, [teamMatchId]);

  // 自動更新（実際に試合が進行中の時だけポーリングする。予定・終了時は通信しない）
  useEffect(() => {
    if (!liveActive || tm?.status !== "active") return;
    intervalRef.current = setInterval(async () => {
      const now = Date.now();
      if (now - lastChangeAtRef.current > INACTIVITY_MS) {
        setLiveActive(false);
        clearInterval(intervalRef.current);
        return;
      }
      await checkAndMaybeReload();
    }, 10000);
    return () => clearInterval(intervalRef.current);
  }, [liveActive, teamMatchId, tm?.status]);

  if (notFound) {
    return (
      <div style={S.page}>
        <div style={S.hdr}>
          <div style={{ display:"flex", alignItems:"center", gap:12 }}>
            <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onBack}>←</button>
            <span style={{ fontSize:17,fontWeight:800,color:C.white }}>団体戦</span>
          </div>
        </div>
        <div style={{ padding:24, textAlign:"center", color:C.textSec }}>
          <div style={{ fontSize:32, marginBottom:10 }}>🗑</div>
          この団体戦は削除されているため表示できません。<br/>試合一覧から最新の状態を確認してください。
        </div>
      </div>
    );
  }
  if (loading || !tm) {
    return <div style={S.page}><div style={S.hdr}><span style={{ fontSize:18,fontWeight:800,color:C.white }}>読み込み中...</span></div></div>;
  }

  const myLabel = [(tm.my_school_id ? schoolMap[tm.my_school_id] : null) || "自チーム", tm.my_team_division].filter(Boolean).join("");
  const oppLabel = [tm.opponent_name, tm.opponent_division].filter(Boolean).join("");
  const isSameSchool = false; // 同校対決は学校ID比較で判定（簡略化）
  const isCreator = tm.created_by === myUserId; // 編集・削除権限用（維持）
  // 番手ごとの操作権限：recorder_idがnull（未ロック）または自分の場合に操作可能
  const canOperateGame = (game) => {
    if (!game) return true; // 未作成は誰でも操作可
    if (!game.recorder_id) return true; // 未ロックは誰でも操作可
    return game.recorder_id === myUserId; // 自分がロック中なら操作可
  };

  // 番手ごとの状態表示
  const gameStatuses = [1,2,3].map(num => {
    const g = (tm.games || []).find(g => g.order_num === num);
    const m = g?.match_id ? matchDetails[g.match_id] : null;
    return { orderNum: num, game: g, match: m };
  });

  const statusLabel = tm.status === "finished"
    ? (tm.my_score > tm.opponent_score ? `🏆 ${tm.my_score}-${tm.opponent_score} 勝利` : tm.my_score < tm.opponent_score ? `❌ ${tm.my_score}-${tm.opponent_score} 敗北` : `${tm.my_score}-${tm.opponent_score} 全試合終了`)
    : tm.status === "active" ? `⏳ ${tm.my_score}-${tm.opponent_score} 進行中`
    : tm.status === "suspended" ? `⏸ ${tm.my_score}-${tm.opponent_score} 中断中`
    : tm.status === "abandoned" ? `⛔ ${tm.my_score}-${tm.opponent_score} 途中終了`
    : "📅 予定";

  // ★団体戦そのものの中断・途中終了（右上の「⋯」から操作）
  //   suspended＝中断中（残りの番手は開始できない。再開で進行中に戻る）
  //   abandoned＝途中終了（まだ行っていない番手は打ち切り。チームの勝敗成績には数えない）
  const tmHold = tm.status === "suspended" || tm.status === "abandoned";
  const showTmMenu = !isViewer && (tm.status === "active" || tmHold);
  const boutRecordingNow = (tm.games || []).some(g => g.status === "active");
  async function changeTmStatus(next) {
    if (tmStatusSaving) return;
    if ((next === "suspended" || next === "abandoned") && boutRecordingNow) {
      alert("記録中の番手があります。先にその番手を終了するか中断してから操作してください。");
      return;
    }
    setTmStatusSaving(true);
    try {
      const { error } = await supabase.from("team_matches").update({ status: next }).eq("id", teamMatchId);
      if (error) throw error;
      // 再開・取り消しのときは、番手の結果から状態（進行中／終了）を計算し直す
      if (next === "active") await recalcTeamMatchScore(teamMatchId);
      setTmMenuOpen(false); setConfirmTmStop(false);
      await loadData({ markAsChanged:true });
    } catch (e) {
      alert("エラー: " + (e?.message || e));
    } finally {
      setTmStatusSaving(false);
    }
  }

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
          <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onBack}>←</button>
          <span style={{ fontSize:17,fontWeight:800,color:C.white,flex:1 }}>{myLabel||"自チーム"} vs {oppLabel||"相手"}</span>
          {/* ★団体戦情報はチーム全員で共有・記録するデータのため、作成者以外も編集できるようにする */}
          <button style={{ background:"rgba(255,255,255,0.15)",border:"none",borderRadius:8,color:C.white,fontSize:13,padding:"5px 8px",cursor:"pointer" }} onClick={()=>onEdit&&onEdit(tm.id)}>✏️</button>
          {showTmMenu && (
            <button aria-label="その他の操作" style={{ background:"rgba(255,255,255,0.15)",border:"none",borderRadius:8,color:C.white,fontSize:15,fontWeight:900,padding:"3px 10px",cursor:"pointer",lineHeight:1.2 }} onClick={()=>setTmMenuOpen(v=>!v)}>⋯</button>
          )}
        </div>
      </div>
      {tmMenuOpen && showTmMenu && (
        <>
          <div style={{ position:"fixed", inset:0, zIndex:50, background:"rgba(0,0,0,0.08)" }} onClick={()=>setTmMenuOpen(false)}/>
          <div style={{ position:"fixed", top:52, right:12, zIndex:51, background:C.white, borderRadius:12, boxShadow:"0 8px 24px rgba(0,0,0,0.22)", minWidth:200, overflow:"hidden" }}>
            {[
              ...(tm.status === "active" ? [["⏸ 中断する", C.navy, ()=>changeTmStatus("suspended")]] : []),
              ...(tm.status === "suspended" ? [["▶ 再開する", C.navy, ()=>changeTmStatus("active")]] : []),
              ...(tm.status === "active" || tm.status === "suspended" ? [["⛔ 途中終了する", C.red, ()=>{ setTmMenuOpen(false); if (boutRecordingNow) { alert("記録中の番手があります。先にその番手を終了するか中断してから操作してください。"); return; } setConfirmTmStop(true); }]] : []),
              ...(tm.status === "abandoned" ? [["↩ 途中終了を取り消す", C.navy, ()=>changeTmStatus("active")]] : []),
            ].map(([label, color, fn], i) => (
              <button key={label} disabled={tmStatusSaving} onClick={fn}
                style={{ display:"block", width:"100%", textAlign:"left", padding:"13px 16px", background:C.white, border:"none", borderTop: i ? `1px solid ${C.border}` : "none", fontSize:14, fontWeight:700, color, cursor:"pointer" }}>{label}</button>
            ))}
          </div>
        </>
      )}

      <div style={{ padding:"12px 14px", paddingBottom:90 }}>
        {/* 試合情報カード */}
        <div style={{ ...S.card, padding:"12px 14px", marginBottom:12 }}>
          <div style={{ fontSize:15,fontWeight:800,color:C.navy,marginBottom:4 }}>{tm.tournament_name||"団体戦"}{tm.round ? ` · ${tm.round}` : ""}</div>
          {tm.match_date && <div style={{ fontSize:11,color:C.textSec }}>{fmtDate(tm.match_date)}{tm.venue ? ` · ${tm.venue}` : ""}</div>}
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginTop:8 }}>
            <span style={{ fontSize:15,fontWeight:800,color:tm.status==="finished"?(tm.my_score>tm.opponent_score?C.teamA:C.teamB):tmHold?C.textSec:C.navy }}>{statusLabel}</span>
            <span style={{ fontSize:11,color:C.textSec }}>{tm.format==="best2" ? "2勝先取" : "3試合全部"}</span>
          </div>
        </div>

        {/* ライブ更新バー */}
        {tm.status === "active" && (
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"8px 14px", background:"#fff3cd", borderRadius:10, marginBottom:12, border:"1px solid #ffd699" }}>
            {liveActive ? (
              <span style={{ fontSize:11,color:"#7a5800",fontWeight:700 }}>🔴 LIVE 差分確認中（変更時のみ再取得）</span>
            ) : (
              <span style={{ fontSize:11,color:"#7a5800",fontWeight:700 }}>⏸ 更新停止中（20分間動きなし）</span>
            )}
            <div style={{ display:"flex", gap:6 }}>
              <button style={{ fontSize:11,padding:"4px 8px",background:C.navy,color:C.white,border:"none",borderRadius:6,cursor:"pointer" }} onClick={()=>{ loadData({ markAsChanged:true }); }}>今すぐ更新</button>
              {!liveActive && <button style={{ fontSize:11,padding:"4px 8px",background:C.accent,color:C.white,border:"none",borderRadius:6,cursor:"pointer" }} onClick={()=>{ setLiveActive(true); setLastUpdated(Date.now()); }}>再開する</button>}
            </div>
          </div>
        )}

        {/* 番手ごとのカード */}
        {gameStatuses.map(({ orderNum, game, match }) => {
          const recorderName = game?.recorder_name;
          const isRecording = game?.status === "active";
          // ★スコアがそのゲーム形式の先取本数に達していれば、statusが"abandoned"でも
          // 　実際には最後まで消化された試合とみなし「終了」表示にする（誤操作の途中終了ボタン対策）
          const naturallyFinished = match && looksNaturallyFinished(match);
          const isFinished = game?.status === "finished" || (match?.status === "abandoned" && naturallyFinished);
          const isAbandoned = match?.status === "abandoned" && !naturallyFinished;
          const isSuspended = game?.status === "suspended" && !isAbandoned && !naturallyFinished;
          const isWaiting = !game || game.status === "waiting";

          const aPlayers = match?.match_players?.filter(p=>p.team==="A").sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name).join("/") || "";
          const bPlayers = match?.match_players?.filter(p=>p.team==="B").sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name).join("/") || "";

          const resultColor = match?.status === "finished"
            ? (winnerSideOf(match)==="A" ? C.teamA : C.teamB)
            : C.textSec;

          const canStart = isWaiting || (isSuspended && !isRecording);
          // ★団体戦を中断・途中終了しているときの、まだ終わっていない番手
          const boutOnHold = tmHold && !isFinished && !isAbandoned && !isRecording && match?.status !== "finished";
          const boutCut = boutOnHold && tm.status === "abandoned";
          const boutVideoLinks = normalizeVideoLinks(match?.video_links);
          const hasVideo = boutVideoLinks.length > 0;
          const finishedNow = isFinished || match?.status === "finished";
          // ★選手名の編集：終了済み・途中終了の番手はいつでも、進行前・中断中は操作ロックを持っている人だけ
          const canEditPlayers = !isViewer && !!match?.id && ((isFinished || isAbandoned) || canOperateGame(game));
          const boutAWin = finishedNow && match && winnerSideOf(match)==="A";
          const boutBWin = finishedNow && match && winnerSideOf(match)==="B";
          const myClubLabel = ((tm.my_school_id ? schoolMap[tm.my_school_id] : null) || "自チーム") + (tm.my_team_division || "");
          const oppClubLabel = (tm.opponent_name || "相手") + (tm.opponent_division || "");
          // ★個人戦一覧のカードと同じ「勝ち＝緑／負け＝オレンジ／進行中＝オレンジ／待機中～予定＝緑／中断・途中終了＝グレー」の色帯
          const stripeColor = isRecording ? C.orange
            : isSuspended ? C.textSec
            : isAbandoned ? C.textSec
            : finishedNow ? (match && winnerSideOf(match)==="A" ? C.teamA : match ? C.teamB : C.border)
            : C.accent;

          return (
            <div key={orderNum} style={{ position:"relative" }}>
            <div style={{ ...S.card, marginBottom:10, boxShadow:"0 1px 4px rgba(0,0,0,0.08)", ...(boutCut ? { opacity:0.7 } : {}) }}>
              <div style={{ height:4, background: boutCut ? C.border : stripeColor }}/>
              {/* ★大会詳細の個人戦カードと同じ構造・同じ文字サイズで描画する（行タップで詳細へ） */}
              <div style={{ padding:"10px 14px", cursor: match?.id ? "pointer" : "default" }} onClick={()=>{ if (match?.id) onOpenMatch && onOpenMatch(match.id); }}>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:4, display:"flex", alignItems:"center", gap:6 }}>
                  {orderNum}番手
                  {isRecording && recorderName && match?.status !== "finished" && (
                    <span style={{ fontSize:8.5, fontWeight:700, padding:"2px 7px", borderRadius:99, background:"#fdecea", color:"#dc2626", border:"1px solid #f5c6c0" }}>🔴 {recorderName} 記録中</span>
                  )}
                  {finishedNow && match?.id && aiAnalyses[match.id] && (
                    <span
                      onClick={e=>{ if (!canViewAiAnalysisFor(match, aiViewer)) return; e.stopPropagation(); onOpenAiAnalysis && onOpenAiAnalysis(match, aiAnalyses[match.id]); }}
                      style={{ fontSize:8.5, fontWeight:700, padding:"2px 7px", borderRadius:99, background:"#eef0ff", color:C.purple, border:"1px solid #dcdffc" }}
                    >🤖 AI</span>
                  )}
                  <span style={{
                    marginLeft:"auto", fontSize:10.5, fontWeight:700, borderRadius:99, padding:"2px 9px", whiteSpace:"nowrap",
                    border:`1px solid ${isRecording?C.orange:C.border}`,
                    color:isRecording?C.orange:C.textSec,
                    background:isRecording?"#fff3e0":"transparent",
                  }}>
                    {finishedNow ? "終了" : isAbandoned ? "途中終了" : boutCut ? "打ち切り" : isSuspended ? "中断" : isRecording ? "試合中" : "予定"}
                  </span>
                </div>
                <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:13, fontWeight:boutAWin?800:600, color:C.teamA }}>
                      <span style={{ fontSize:13, fontWeight:700, color:"#5a6478", marginRight:6 }}>{myClubLabel}</span>{aPlayers || "未登録"}
                    </div>
                    <div style={{ fontSize:13, fontWeight:boutBWin?800:600, color:bPlayers?(boutBWin?C.teamB:C.text):C.textSec, marginTop:2 }}>
                      <span style={{ fontSize:13, fontWeight:700, color:"#5a6478", marginRight:6 }}>{oppClubLabel}</span>{bPlayers || "未登録"}
                    </div>
                  </div>
                  {match && !isWaiting && (
                    <div style={{ fontSize:22, fontWeight:900, color:boutAWin?C.teamA:boutBWin?C.teamB:C.textSec, minWidth:48, textAlign:"right" }}>{match.match_score_a}-{match.match_score_b}</div>
                  )}
                </div>
              </div>

              {/* ★操作ボタンも個人戦カードと同じ「枠いっぱい・区切り線だけ」のボタン列にする */}
              {boutOnHold ? (
                tm.status === "suspended" ? (
                  <div style={{ borderTop:"1px solid "+C.border, padding:"7px", background:"#eef0f3", color:C.textSec, fontSize:11, fontWeight:700, textAlign:"center" }}>中断中（⋯ から再開できます）</div>
                ) : null
              ) : (!isFinished && !isAbandoned && canOperateGame(game)) ? (
                <>
                  {isWaiting && (aPlayers || bPlayers) && game?.match_id && (
                    <div style={{ display:"flex", borderTop:"1px solid "+C.border }}>
                      <button
                        style={{ flex:1, padding:"8px", background:C.accent, color:C.white, border:"none", fontSize:11, fontWeight:700, cursor:"pointer" }}
                        onClick={async ()=>{
                          const { data: matchData } = await supabase.from("matches").select("id,match_players(team,player_name,order_num)").eq("id", game.match_id).single();
                          setServeSelectInfo({ matchData, orderNum, game });
                        }}
                      >🎾 試合開始</button>
                      <button
                        style={{ flex:1, padding:"8px", background:"#f5f5f5", color:C.navy, border:"none", borderLeft:"1px solid "+C.border, fontSize:11, fontWeight:700, cursor:"pointer" }}
                        onClick={()=>{
                          const aP = (match?.match_players||[]).filter(p=>p.team==="A").sort((a,b)=>a.order_num-b.order_num);
                          const bP = (match?.match_players||[]).filter(p=>p.team==="B").sort((a,b)=>a.order_num-b.order_num);
                          setSimpleResultFor({ orderNum, game, aLabel:aPlayers||"自チーム", bLabel:bPlayers||"相手", aPlayers:aP, bPlayers:bP, gameFormat: match?.game_format ?? 7 });
                          setSimpleResultScoreA(""); setSimpleResultScoreB("");
                          setSimpleResultNamesA(aP.map(p=>p.player_name));
                          setSimpleResultNamesB(bP.map(p=>p.player_name));
                        }}
                      >📝 結果だけ記録</button>
                    </div>
                  )}
                  {(isWaiting && !(aPlayers || bPlayers)) && (
                    <div style={{ display:"flex", borderTop:"1px solid "+C.border }}>
                      <button
                        style={{ flex:1, padding:"8px", background:C.accent, color:C.white, border:"none", fontSize:11, fontWeight:700, cursor:"pointer" }}
                        onClick={()=>onNewMatch && onNewMatch(tm, orderNum, game)}
                      >🎾 ペアを登録して試合開始</button>
                    </div>
                  )}
                  {isSuspended && (
                    <div style={{ display:"flex", borderTop:"1px solid "+C.border }}>
                      <button
                        style={{ flex:1, padding:"8px", background:C.accent, color:C.white, border:"none", fontSize:11, fontWeight:700, cursor:"pointer" }}
                        onClick={async ()=>{
                          const { data: matchData } = await supabase.from("matches").select("id,match_players(team,player_name,order_num)").eq("id", game.match_id).single();
                          setServeSelectInfo({ matchData, orderNum, game });
                        }}
                      >🎾 試合を再開する</button>
                    </div>
                  )}
                </>
              ) : (
                // ★ロック（recorder_id）が残っているのに進行中でもない＝操作不能になっている状態。
                //   通信断や画面を閉じただけでロックだけ残ることがあるため、手動で解除できる手段を用意する。
                (!isFinished && !isAbandoned && !isRecording) && (
                  <div style={{ display:"flex", borderTop:"1px solid "+C.border }}>
                    <button
                      style={{ flex:1, padding:"8px", background:"#fdecea", color:C.red, border:"none", fontSize:11, fontWeight:700, cursor:"pointer" }}
                      onClick={async ()=>{
                        if (!window.confirm("この番手の操作ロックを解除しますか？\n（他の人が今まさに記録中でないことを確認してください）")) return;
                        try {
                          await updateTeamMatchGame(game.id, { recorder_id:null, recorder_name:null });
                          await loadData({ markAsChanged:true });
                        } catch(e) {
                          alert("エラー: " + (e.message || e));
                        }
                      }}
                    >🔓 操作できないためロックを解除する</button>
                  </div>
                )
              )}

              {/* ★個人戦カードと同じボタン列：左下🗑 → コピー → 📝メモ → 🎥動画（右下） → 🤖 */}
              {match?.id && (
                <div style={{ display:"flex", borderTop:"1px solid "+C.border }}>
                  {!isViewer && <button style={{ width:52, padding:"8px", background:"#fdecea", color:C.red, border:"none", borderRight:"1px solid "+C.border, fontSize:11, fontWeight:700, cursor:"pointer" }} onClick={()=>setConfirmDeleteBout({ matchId: match.id, gameId: game?.id, orderNum })}>🗑</button>}
                  {!isViewer && <button style={{ flex:1, padding:"8px 12px", textAlign:"left", background:"#f5f5f5", color:C.navy, border:"none", fontSize:11, fontWeight:700, cursor:"pointer" }} onClick={()=>onCopyMatch && onCopyMatch(match.id)}>📋 コピーして新規作成</button>}
                  {canEditPlayers && (
                    <button
                      style={{ width:44, padding:"8px", background:"#f5f5f5", color:C.navy, border:"none", borderLeft:"1px solid "+C.border, fontSize:12, fontWeight:700, cursor:"pointer" }}
                      onClick={()=>onEditPlayers && onEditPlayers(match.id, orderNum)}
                    >✏️</button>
                  )}
                  {match.memo && (
                    <button
                      style={{ width:44, padding:"8px", background:C.accentL, color:C.navy, border:"none", borderLeft:"1px solid "+C.border, fontSize:12, fontWeight:700, cursor:"pointer" }}
                      onClick={()=>setMemoView(match)}
                    >📝</button>
                  )}
                  {hasVideo && (
                    <button
                      style={{ width:52, padding:"8px", background:"#fdeceb", color:"#c4302b", border:"none", borderLeft:"1px solid "+C.border, fontSize:11, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap" }}
                      onClick={()=>setVideoView({ video_links: boutVideoLinks })}
                    >🎥{boutVideoLinks.length}</button>
                  )}
                  {finishedNow && aiAnalyses[match.id] && (
                    canViewAiAnalysisFor(match, aiViewer) ? (
                      <button
                        style={{ width:44, padding:"8px", background:"#eef0f6", color:"#3a4152", border:"none", borderLeft:"1px solid "+C.border, fontSize:12, fontWeight:700, cursor:"pointer" }}
                        onClick={()=>onOpenAiAnalysis && onOpenAiAnalysis(match, aiAnalyses[match.id])}
                      >🤖</button>
                    ) : (
                      <button
                        style={{ width:44, padding:"8px", background:"#f4f4f6", color:"#b7bcc7", border:"none", borderLeft:"1px solid "+C.border, fontSize:12, fontWeight:700, cursor:"default" }}
                      >🤖</button>
                    )
                  )}
                </div>
              )}
            </div>
            </div>
          );
        })}
      </div>
      <NavBar active="list" onNavigate={onNavigate}/>

      {/* サーブ選択モーダル */}
      {serveSelectInfo && (() => {
        const { matchData, orderNum, game } = serveSelectInfo;
        const aPlayers = (matchData?.match_players||[]).filter(p=>p.team==="A").sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name);
        const bPlayers = (matchData?.match_players||[]).filter(p=>p.team==="B").sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name);
        const aP = aPlayers.join("/") || "自チーム";
        const bP = bPlayers.join("/") || "相手チーム";
        return (
          <ServeOrderModal
            aLabel={aP} bLabel={bP}
            aP1={aPlayers[0]} aP2={aPlayers[1]} bP1={bPlayers[0]} bP2={bPlayers[1]}
            isDoubles={aPlayers.length>1 || bPlayers.length>1}
            initialOrders={matchData}
            onCancel={()=>setServeSelectInfo(null)}
            onConfirm={(team, orderA, orderB, recvA, recvB)=>{
              setServeSelectInfo(null);
              onStartMatch && onStartMatch(matchData.id, orderNum, game, team, orderA, orderB, recvA, recvB);
            }}
          />
        );
      })()}

      {/* ★番手カードの📝から開く試合メモ（個人戦一覧と同じ表示） */}
      {memoView && (
        <Modal onClose={()=>setMemoView(null)}>
          <h3 style={{ fontSize:14,fontWeight:800,color:C.navy,marginBottom:12 }}>📝 試合メモ</h3>
          <div style={{ fontSize:13,lineHeight:1.75,whiteSpace:"pre-wrap",background:C.accentL,borderRadius:10,padding:"12px 13px",color:C.text }}>{memoView.memo}</div>
          <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:14, padding:"11px" }} onClick={()=>setMemoView(null)}>閉じる</button>
        </Modal>
      )}

      {/* ★番手の試合の削除（個人戦一覧の削除と同じくゴミ箱行き。番手はペア未登録の状態に戻す） */}
      {confirmTmStop && (
        <Modal onClose={()=>setConfirmTmStop(false)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:40,marginBottom:8 }}>⛔</div>
            <h3 style={{ fontSize:16,fontWeight:800,marginBottom:8 }}>団体戦を途中終了しますか？</h3>
            <p style={{ fontSize:12,color:C.textSec,marginBottom:20,lineHeight:1.7,textAlign:"left" }}>
              {tm.my_score}-{tm.opponent_score} の時点で終了します。<br/>
              ・まだ行っていない番手は「打ち切り」になります<br/>
              ・勝敗が決まっていないため、チームの勝敗成績には数えません<br/>
              ・終わった番手の個人の成績はそのまま残ります<br/>
              ・あとから「⋯」→「途中終了を取り消す」で戻せます
            </p>
            <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:8 }}>
              <button style={{ padding:"11px",background:"#f0f0f0",color:C.text,border:"none",borderRadius:10,fontSize:13,fontWeight:700,cursor:"pointer" }} onClick={()=>setConfirmTmStop(false)}>キャンセル</button>
              <button disabled={tmStatusSaving} style={{ padding:"11px",background:C.red,color:C.white,border:"none",borderRadius:10,fontSize:13,fontWeight:700,cursor:"pointer" }} onClick={()=>changeTmStatus("abandoned")}>{tmStatusSaving ? "保存中..." : "途中終了する"}</button>
            </div>
          </div>
        </Modal>
      )}

      {confirmDeleteBout && (
        <Modal onClose={()=>setConfirmDeleteBout(null)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:40,marginBottom:8 }}>⚠️</div>
            <h3 style={{ fontSize:16,fontWeight:800,marginBottom:8 }}>{confirmDeleteBout.orderNum}番手の試合を削除しますか？</h3>
            <p style={{ fontSize:12,color:C.textSec,marginBottom:20,lineHeight:1.6 }}>試合はゴミ箱に移動し、この番手は「ペア未登録」に戻ります。</p>
            <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:8 }}>
              <button style={{ padding:"11px",background:"#f0f0f0",color:C.text,border:"none",borderRadius:10,fontSize:13,fontWeight:700,cursor:"pointer" }} onClick={()=>setConfirmDeleteBout(null)}>キャンセル</button>
              <button
                style={{ padding:"11px",background:C.red,color:C.white,border:"none",borderRadius:10,fontSize:13,fontWeight:700,cursor:"pointer" }}
                onClick={async()=>{
                  const { matchId: delId, gameId } = confirmDeleteBout;
                  try {
                    await deleteMatch(delId);
                    // ★番手の紐づけを外して「ペア未登録」に戻す
                    if (gameId) await updateTeamMatchGame(gameId, { match_id:null, status:"waiting", recorder_id:null, recorder_name:null });
                    // ★団体戦スコアを再集計。番手が1つも残らない場合は再集計されないので、0-0・予定に戻す
                    const r = await recalcTeamMatchScore(teamMatchId);
                    const { data: rest } = await supabase.from("team_match_games").select("match_id").eq("team_match_id", teamMatchId).not("match_id","is",null);
                    if (!r && (rest || []).length === 0) {
                      await supabase.from("team_matches").update({ my_score:0, opponent_score:0, status:"scheduled" }).eq("id", teamMatchId);
                    }
                    setConfirmDeleteBout(null);
                    await loadData({ markAsChanged:true });
                  } catch(e) {
                    alert("エラー: " + (e.message || e));
                  }
                }}
              >削除する</button>
            </div>
          </div>
        </Modal>
      )}

      {/* ★番手カードの🎥バッジから開く動画リンク一覧 */}
      {videoView && (
        <Modal onClose={()=>setVideoView(null)}>
          <h3 style={{ fontSize:14,fontWeight:800,color:C.navy,marginBottom:12 }}>🎥 動画リンク</h3>
          {(videoView.video_links || []).map(v=>(
            <a
              key={v.id}
              href={v.url}
              target="_blank"
              rel="noopener noreferrer"
              style={{ display:"flex",alignItems:"center",gap:10,border:`1px solid ${C.border}`,borderRadius:10,padding:8,marginBottom:9,textDecoration:"none",color:"inherit" }}
            >
              <img src={youtubeThumbOf(v.id)} alt="" style={{ width:88,height:52,objectFit:"cover",borderRadius:7,background:"#000",flexShrink:0 }}/>
              <div>
                <div style={{ fontSize:12.5,fontWeight:700,color:C.navy }}>{v.title || "動画"}</div>
                <div style={{ fontSize:10.5,color:"#c4302b",fontWeight:700,marginTop:3 }}>▶ YouTubeで開く</div>
              </div>
            </a>
          ))}
          <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:6, padding:"11px" }} onClick={()=>setVideoView(null)}>閉じる</button>
        </Modal>
      )}

      {/* ★結果だけ記録モーダル（2面展開などでポイントを付けられない時に、ゲームカウントだけ記録する） */}
      {simpleResultFor && (
        <Modal onClose={()=>setSimpleResultFor(null)}>
          <div>
            <div style={{ fontSize:15, fontWeight:800, marginBottom:4 }}>{simpleResultFor.orderNum}番手・結果だけ記録</div>
            <div style={{ fontSize:11, color:C.textSec, marginBottom:16 }}>ポイントを記録せず、ゲームカウントだけ入力します</div>

            {(simpleResultFor.aPlayers?.length>0 || simpleResultFor.bPlayers?.length>0) && (
              <div style={{ marginBottom:14 }}>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:8 }}>選手名（必要であれば修正できます）</div>
                {simpleResultFor.aPlayers?.map((p,i)=>(
                  <input key={p.id} value={simpleResultNamesA[i]??""} onChange={e=>setSimpleResultNamesA(prev=>{ const next=[...prev]; next[i]=e.target.value; return next; })}
                    style={{ width:"100%", padding:"7px 9px", borderRadius:8, border:`1px solid ${C.border}`, fontSize:13, marginBottom:6, color:C.text, boxSizing:"border-box" }} placeholder="自チーム選手名" />
                ))}
                {simpleResultFor.bPlayers?.map((p,i)=>(
                  <input key={p.id} value={simpleResultNamesB[i]??""} onChange={e=>setSimpleResultNamesB(prev=>{ const next=[...prev]; next[i]=e.target.value; return next; })}
                    style={{ width:"100%", padding:"7px 9px", borderRadius:8, border:`1px solid ${C.border}`, fontSize:13, marginBottom:6, color:C.text, boxSizing:"border-box" }} placeholder="相手選手名" />
                ))}
              </div>
            )}

            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
              <div style={{ flex:1, minWidth:0, textAlign:"center" }}>
                <div style={{ fontSize:12, fontWeight:700, color:C.teamA, marginBottom:6, minHeight:18, lineHeight:"18px", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{simpleResultFor.aLabel}</div>
                <input type="number" inputMode="numeric" value={simpleResultScoreA} onChange={e=>setSimpleResultScoreA(e.target.value)}
                  style={{ width:"100%", boxSizing:"border-box", textAlign:"center", fontSize:24, fontWeight:800, padding:"10px 4px", borderRadius:10, border:`2px solid ${C.teamA}`, color:C.teamA }} />
              </div>
              <div style={{ fontSize:18, color:C.textSec, marginTop:24 }}>-</div>
              <div style={{ flex:1, minWidth:0, textAlign:"center" }}>
                <div style={{ fontSize:12, fontWeight:700, color:C.teamB, marginBottom:6, minHeight:18, lineHeight:"18px", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{simpleResultFor.bLabel}</div>
                <input type="number" inputMode="numeric" value={simpleResultScoreB} onChange={e=>setSimpleResultScoreB(e.target.value)}
                  style={{ width:"100%", boxSizing:"border-box", textAlign:"center", fontSize:24, fontWeight:800, padding:"10px 4px", borderRadius:10, border:`2px solid ${C.teamB}`, color:C.teamB }} />
              </div>
            </div>
            <button
              style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), marginTop:14 }}
              disabled={simpleResultSaving || simpleResultScoreA==="" || simpleResultScoreB==="" || simpleResultScoreA===simpleResultScoreB}
              onClick={async ()=>{
                const a = parseInt(simpleResultScoreA,10), b = parseInt(simpleResultScoreB,10);
                if (isNaN(a) || isNaN(b) || a<0 || b<0) { alert("正しいゲームカウントを入力してください"); return; }
                if (a===b) { alert("同点にはできません（勝敗がつく数字を入力してください）"); return; }
                // ★試合形式（〇Gマッチ）に必要な勝利ゲーム数に達していないスコアでは
                //   誤って「終了」扱いにできないようにする（例：7Gマッチなのに3-1で確定してしまう不具合対策）
                const requiredWins = calcWinGames(simpleResultFor.gameFormat ?? 7);
                if (Math.max(a,b) < requiredWins) { alert(`${simpleResultFor.gameFormat ?? 7}Gマッチは${requiredWins}ゲーム先取が必要です。まだ試合は終了できません。`); return; }
                setSimpleResultSaving(true);
                try {
                  // ★選手名が編集されていれば、スコア保存の前に反映する
                  const nameUpdates = [
                    ...(simpleResultFor.aPlayers||[]).map((p,i)=>({ p, name: simpleResultNamesA[i] })),
                    ...(simpleResultFor.bPlayers||[]).map((p,i)=>({ p, name: simpleResultNamesB[i] })),
                  ].filter(({p,name}) => name && name.trim() && name.trim() !== p.player_name);
                  for (const { p, name } of nameUpdates) {
                    const { error: nameErr } = await supabase.from("match_players").update({ player_name: name.trim() }).eq("id", p.id);
                    if (nameErr) throw nameErr;
                  }
                  await supabase.from("matches").update({ match_score_a:a, match_score_b:b, status:"finished" }).eq("id", simpleResultFor.game.match_id);
                  await updateTeamMatchGame(simpleResultFor.game.id, { status:"finished" });
                  setSimpleResultFor(null);
                  await loadData({ markAsChanged:true });
                } catch(e) {
                  alert("保存エラー: " + (e.message || e));
                } finally {
                  setSimpleResultSaving(false);
                }
              }}
            >{simpleResultSaving ? "保存中..." : "この結果で確定する"}</button>
            <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }} onClick={()=>setSimpleResultFor(null)}>キャンセル</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ============================================================
// 団体戦 番手ペア登録→試合開始（v1.0のMatchSetupFormを流用）
// ============================================================
function TeamMatchGameSetupWrapper({ teamMatchId, orderNum, onSave, onSavePairOnly, onCancel, editMatchId }) {
  const [tm, setTm] = useState(null);
  const [participantIds, setParticipantIds] = useState(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    (async () => {
      const data = await getTeamMatch(teamMatchId);
      setTm(data);
      // ★このチーム戦がどの大会に属しているかは団体戦側にtournament_idの列がないため、
      //   大会名＋日付（大会の開催期間内かどうか）で該当する大会を探し、
      //   その大会の「参加選手」リストがあればペア選択の候補をそこだけに絞り込む。
      if (data?.tournament_name) {
        const tournaments = await getTournaments();
        const match = tournaments.find(t =>
          t.name === data.tournament_name &&
          (!data.match_date || !t.start_date || (data.match_date >= t.start_date && data.match_date <= (t.end_date || t.start_date)))
        ) || tournaments.find(t => t.name === data.tournament_name);
        if (match?.participant_player_ids?.length) setParticipantIds(match.participant_player_ids);
      }
      setReady(true);
    })();
  }, [teamMatchId]);

  if (!ready) return <div style={S.page}><div style={S.hdr}><span style={{ fontSize:18,fontWeight:800,color:C.white }}>読み込み中...</span></div></div>;

  const orderLabel = ["1番手","2番手","3番手"][orderNum-1] || `${orderNum}番手`;

  return (
    <MatchSetup
      sourceMatchId={null}
      editMatchId={editMatchId || null}
      initialMatchType="tournament"
      headerLabel={<span style={{ display:"inline-flex", alignItems:"center", gap:6 }}><TeamIcon size={22} light/>{editMatchId ? `団体戦 ${orderLabel} 選手を編集` : `団体戦 ${orderLabel} ペア登録`}</span>}
      prefillTournament={tm?.tournament_name || ""}
      prefillRound={tm?.round || ""}
      prefillVenue={tm?.venue || ""}
      prefillDate={tm?.match_date || ""}
      prefillOpponent={tm?.opponent_name || ""}
      prefillIsYounger={tm?.is_younger !== false}
      isTeamMatchGame={true}
      teamMatchMyDivision={tm?.my_team_division || ""}
      teamMatchOppDivision={tm?.opponent_division || ""}
      teamMatchMySchoolId={tm?.my_school_id || null}
      tournamentParticipantIds={participantIds || undefined}
      onScheduled={null}
      onSave={onSave}
      onSavePairOnly={editMatchId ? undefined : onSavePairOnly}
      onCancel={onCancel}
    />
  );
}

// ============================================================
// 統計画面（複数試合をまたいだ分析）
// ============================================================
const STATS_FILTER_STORAGE_KEY = "statsFilterPrefsV1";
function loadStatsFilterPrefs() {
  try {
    const raw = localStorage.getItem(STATS_FILTER_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) { return {}; }
}
function saveStatsFilterPrefs(prefs) {
  try { localStorage.setItem(STATS_FILTER_STORAGE_KEY, JSON.stringify(prefs)); } catch (e) {}
}
const STATS_CAT_LABELS = { all: "すべて", tournament: "大会", team: "団体戦", individual: "個人戦" };
const STATS_PERIOD_LABELS = { all: "全期間", month1: "直近1ヶ月", month3: "直近3ヶ月", season: "シーズン" };

// ============================================================
// 個人分析画面：①選手選択 → ②試合選択 → ③分析結果
// 何も設定していない時は「自分（またはお子さん）・直近5試合」をデフォルト表示する
// ============================================================
// ============================================================
// 集計対象の設定シート（個人・ペア・チーム共通）
// ・期間 → 大会 → 試合数 → 対象試合 の順。条件は重ねがけ（AND）。
// ・試合数は、期間・大会でしぼった中から新しい順に取る。
// ============================================================
function ScopeSheet({ matches, scope, seasonStart, seasonLabel, teamMatchIds, onApply, onClose, onChangePlayer, playerLabel }) {
  const [draft, setDraft] = useState(scope);
  const [pickOpen, setPickOpen] = useState(false);
  const [remember, setRemember] = useState(true);

  const set = (patch) => setDraft(v => ({ ...v, ...patch }));

  // 大会の候補（期間でしぼっている場合は、その期間に試合がある大会だけ）
  const tournamentOptions = useMemo(() => {
    const start = scopePeriodStart(draft, seasonStart), end = scopePeriodEnd(draft);
    const inPeriod = new Set(), all = new Set();
    matches.forEach(m => {
      const t = m.tournament_name || "";
      if (!t) return;
      all.add(t);
      const d = m.match_date || "";
      if ((!start || d >= start) && (!end || d <= end)) inPeriod.add(t);
    });
    return { inPeriod:[...inPeriod].sort(), outside:[...all].filter(t=>!inPeriod.has(t)).sort() };
  }, [matches, draft.period, draft.rangeStart, draft.rangeEnd, seasonStart]);

  const preview = applyScope(matches, draft, { seasonStart, teamMatchIds });

  // 期間を変えると、選んでいる大会が対象外になることがあるので確認する
  function changePeriod(next) {
    const trial = { ...draft, period: next };
    if ((draft.tournaments ?? []).length > 0) {
      const start = scopePeriodStart(trial, seasonStart), end = scopePeriodEnd(trial);
      const stillOk = draft.tournaments.filter(t =>
        matches.some(m => (m.tournament_name||"")===t && (!start || (m.match_date||"")>=start) && (!end || (m.match_date||"")<=end))
      );
      if (stillOk.length < draft.tournaments.length) {
        if (!window.confirm("選択中の大会が対象から外れますがよろしいですか？")) return;
        trial.tournaments = stillOk;
      }
    }
    setDraft(trial);
  }

  const Chip = ({ on, children, onClick }) => (
    <div onClick={onClick} style={{ padding:"11px 14px", borderRadius:9, fontSize:14, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap",
      border:`1.5px solid ${on?C.navy:C.border}`, background:on?C.navy:C.white, color:on?C.white:C.textSec }}>{children}</div>
  );
  const Group = ({ title, note, children }) => (
    <div style={{ marginBottom:14 }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", gap:8, marginBottom:9 }}>
        <div style={{ fontSize:14, fontWeight:800, color:C.text }}>{title}</div>
        {note && <div style={{ fontSize:13, fontWeight:700, color:"#5a6478" }}>{note}</div>}
      </div>
      {children}
    </div>
  );
  const Row = ({ children }) => <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:6 }}>{children}</div>;
  const hint = { fontSize:12.5, color:C.textSec, lineHeight:1.7, margin:"4px 0 10px" };
  const divider = { height:1, background:C.border, margin:"12px 0" };

  // 個別選択の画面
  if (pickOpen) {
    const sorted = [...matches].sort((a,b)=> new Date(b.match_date)-new Date(a.match_date));
    const picked = new Set(draft.pickedIds ?? []);
    return (
      <div style={{ minHeight:"100vh", background:C.white }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"15px 16px", borderBottom:`1px solid ${C.border}` }}>
          <div style={{ fontSize:17, fontWeight:800 }}>✓ 試合を個別に選ぶ</div>
          <div onClick={()=>setPickOpen(false)} style={{ color:C.textSec, fontSize:19, cursor:"pointer" }}>✕</div>
        </div>
        <div style={{ padding:"14px 16px 100px" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
            <div style={{ fontSize:13.5, color:C.textSec, fontWeight:700 }}>新しい順</div>
            <div onClick={()=>set({ pickedIds: [] })} style={{ fontSize:13, fontWeight:700, color:C.navy, cursor:"pointer" }}>すべて解除</div>
          </div>
          {sorted.map(m => {
            const on = picked.has(m.id);
            const win = winnerSideOf(m)==="A";
            return (
              <div key={m.id} onClick={()=>{
                  const nx = new Set(picked);
                  if (on) nx.delete(m.id); else nx.add(m.id);
                  set({ pickedIds: [...nx] });
                }}
                style={{ display:"flex", alignItems:"center", gap:10, padding:"11px 12px", borderBottom:`1px solid ${C.border}`, cursor:"pointer", background:on?C.accentL:"transparent" }}>
                <div style={{ width:20, height:20, borderRadius:5, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center",
                  border:`2px solid ${on?C.accent:C.border}`, background:on?C.accent:"transparent", color:C.white, fontSize:12, fontWeight:900 }}>{on?"✓":""}</div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:12.5, color:C.textSec }}>{(m.match_date||"").replace(/-/g,"/")}　{m.tournament_name||""}</div>
                  <div style={{ fontSize:14, fontWeight:700, color:C.text, marginTop:1, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                    {m.round ? m.round+"・" : ""}{(m.players.filter(p=>p.team==="B").map(p=>p.player_name).join("/")) || "（相手なし）"}
                  </div>
                </div>
                <div style={{ fontSize:12.5, fontWeight:800, borderRadius:6, padding:"3px 9px", flexShrink:0,
                  color: win?C.accent:C.red, background: win?C.accentL:C.redL }}>{win?"勝":"負"} {m.match_score_a}-{m.match_score_b}</div>
              </div>
            );
          })}
        </div>
        <div style={{ position:"fixed", left:0, right:0, bottom:0, padding:"12px 16px 16px", background:C.white, borderTop:`1px solid ${C.border}` }}>
          <button onClick={()=>setPickOpen(false)} style={{ width:"100%", padding:15, borderRadius:11, border:"none", background:C.navy, color:C.white, fontSize:16, fontWeight:800, cursor:"pointer" }}>
            この{(draft.pickedIds??[]).length}試合にする
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight:"100vh", background:C.white }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"15px 16px", borderBottom:`1px solid ${C.border}` }}>
        <div style={{ fontSize:17, fontWeight:800 }}>🎚️ 集計対象の設定</div>
        <div onClick={onClose} style={{ color:C.textSec, fontSize:19, cursor:"pointer" }}>✕</div>
      </div>
      <div style={{ padding:"14px 16px 20px" }}>

        {onChangePlayer && (
          <>
            {/* ★他校（対戦相手）の選手も分析できることが分かるよう、見出しの右に案内を出す */}
            <Group title="選手" note="他チームの選手も選べます">
              {/* ★気づかれにくかったため、色付きの背景＋太い枠＋ボタン形の「変更する」で目立たせる */}
              <div onClick={onChangePlayer} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:10,
                background:"#eaf1ff", border:`2px solid ${C.navy}`, borderRadius:12, padding:"12px 14px", cursor:"pointer" }}>
                <span style={{ fontSize:17, fontWeight:800, color:C.navy, minWidth:0 }}>{playerLabel}</span>
                <span style={{ flexShrink:0, fontSize:14, fontWeight:800, color:C.white, background:C.navy, borderRadius:20, padding:"8px 14px", whiteSpace:"nowrap" }}>変更する ›</span>
              </div>
            </Group>
            <div style={divider}/>
          </>
        )}

        <Group title="期間">
          <Row>
            {seasonStart && <Chip on={draft.period==="season"} onClick={()=>changePeriod("season")}>📌 {seasonLabel||"起点日"}以降</Chip>}
            <Chip on={draft.period==="all"} onClick={()=>changePeriod("all")}>全期間</Chip>
            <Chip on={draft.period==="1m"} onClick={()=>changePeriod("1m")}>1ヶ月</Chip>
            <Chip on={draft.period==="3m"} onClick={()=>changePeriod("3m")}>3ヶ月</Chip>
            <Chip on={draft.period==="fy"} onClick={()=>changePeriod("fy")}>今年度</Chip>
            <Chip on={draft.period==="range"} onClick={()=>changePeriod("range")}>📅 日付指定</Chip>
          </Row>
          {draft.period==="range" && (
            <div style={{ display:"flex", gap:8, alignItems:"center", marginTop:8 }}>
              <input type="date" value={draft.rangeStart} onChange={e=>set({ rangeStart:e.target.value })}
                style={{ flex:1, padding:11, borderRadius:9, border:`1.5px solid ${C.border}`, fontSize:14, fontFamily:"inherit" }}/>
              <span style={{ color:C.textSec }}>〜</span>
              <input type="date" value={draft.rangeEnd} onChange={e=>set({ rangeEnd:e.target.value })}
                style={{ flex:1, padding:11, borderRadius:9, border:`1.5px solid ${C.border}`, fontSize:14, fontFamily:"inherit" }}/>
            </div>
          )}
          {!seasonStart && <div style={hint}>設定 → シーズン設定 で起点日を登録すると「◯◯以降」が選べます。</div>}
        </Group>

        <div style={divider}/>

        <Group title="大会">
          <Row>
            <Chip on={(draft.tournaments??[]).length===0} onClick={()=>set({ tournaments: [] })}>すべての試合</Chip>
          </Row>
          {tournamentOptions.inPeriod.length===0 ? (
            <div style={hint}>この期間に大会の記録がありません。</div>
          ) : (
            <Row>
              {tournamentOptions.inPeriod.map(t => {
                const on = (draft.tournaments??[]).includes(t);
                return <Chip key={t} on={on} onClick={()=>set({ tournaments: on ? draft.tournaments.filter(x=>x!==t) : [...(draft.tournaments??[]), t] })}>{t}</Chip>;
              })}
            </Row>
          )}
          <div style={hint}>複数選べます。期間をしぼっている場合は、その期間に開催された大会だけが出ます。</div>
        </Group>

        <div style={divider}/>

        <Group title="試合数">
          <Row>
            <Chip on={!draft.limit} onClick={()=>set({ limit:0 })}>すべて（上限{SCOPE_MAX}）</Chip>
            {[1,3,5,10,20,50].map(n => <Chip key={n} on={draft.limit===n} onClick={()=>set({ limit:n })}>直近{n}</Chip>)}
          </Row>
          <div style={hint}>新しい試合から数えます。上の期間・大会でしぼった中から数えます。</div>
        </Group>

        <div style={divider}/>

        <Group title="対象試合">
          <Row>
            <Chip on={draft.kind==="all"} onClick={()=>set({ kind:"all" })}>すべて</Chip>
            <Chip on={draft.kind==="individual"} onClick={()=>set({ kind:"individual" })}>個人戦のみ</Chip>
            <Chip on={draft.kind==="team"} onClick={()=>set({ kind:"team" })}>団体戦のみ</Chip>
          </Row>
          <div style={hint}>団体戦の1番手・2番手…として戦った試合を分けて集計できます。</div>
        </Group>

        <div style={divider}/>

        <Group title="試合を個別に選ぶ">
          <Row>
            <Chip on={(draft.pickedIds??[]).length===0} onClick={()=>set({ pickedIds: [] })}>使わない</Chip>
            <Chip on={(draft.pickedIds??[]).length>0} onClick={()=>setPickOpen(true)}>
              ✓ 試合を選ぶ{(draft.pickedIds??[]).length>0 ? `（${draft.pickedIds.length}件）` : ""}
            </Chip>
          </Row>
          <div style={hint}>選ぶと上の条件は使わず、選んだ試合だけを集計します。</div>
        </Group>

        <div style={{ background:C.accentL, border:"1px solid #9fe3c8", borderRadius:9, padding:12, fontSize:14, fontWeight:700, color:"#0b7a55", margin:"14px 0" }}>
          この条件の対象：{preview.list.length}試合
          {preview.capped > 0 && <div style={{ fontSize:13, fontWeight:700, marginTop:4 }}>該当{preview.list.length+preview.capped}件のうち、新しい{SCOPE_MAX}試合を対象にしています</div>}
        </div>

        <div onClick={()=>setRemember(v=>!v)} style={{ display:"flex", alignItems:"center", gap:10, background:"#eef2f7",
          border:`1.5px solid ${C.navy}`, borderRadius:11, padding:12, cursor:"pointer", marginBottom:14 }}>
          <div style={{ width:21, height:21, borderRadius:5, background:remember?C.navy:C.white, border:`2px solid ${C.navy}`,
            display:"flex", alignItems:"center", justifyContent:"center", color:C.white, fontSize:13, fontWeight:900, flexShrink:0 }}>{remember?"✓":""}</div>
          <div style={{ fontSize:13.5, fontWeight:700, color:C.navy, lineHeight:1.6 }}>この条件を次に開いたときも使う</div>
        </div>

        <button onClick={()=>onApply(draft, remember)} disabled={preview.list.length===0}
          style={{ width:"100%", padding:15, borderRadius:11, border:"none", fontSize:16, fontWeight:800, marginBottom:8,
            background: preview.list.length===0 ? "#d5dae2" : C.navy, color:C.white, cursor:"pointer" }}>
          {preview.list.length===0 ? "この条件では試合がありません" : `この${preview.list.length}試合で表示する`}
        </button>
        <button onClick={()=>setDraft({ ...DEFAULT_SCOPE, period: seasonStart ? "season" : "all" })}
          style={{ width:"100%", padding:12, borderRadius:11, background:"none", border:"none", color:C.textSec, fontSize:13.5, fontWeight:700, cursor:"pointer" }}>
          条件をリセット
        </button>
      </div>
    </div>
  );
}

// ============================================================
// ペア分析画面：自分たち（自チームのペア）／相手分析（過去に対戦した相手ペア）
// ============================================================
// ★分析の「個人／ペア／チーム」タブ（試合一覧の「大会／団体戦／個人戦」と同じ見た目）
function AnalysisTabs({ current, onPersonal, onPair, onTeam }) {
  const tabs = [["personal","👤 個人",onPersonal],["pair","👥 ペア",onPair],["team","🏫 チーム",onTeam]];
  return (
    <div style={{ display:"flex", background:"#e6e9ef", borderRadius:12, padding:4, gap:4, marginBottom:10 }}>
      {tabs.map(([k,l,fn]) => {
        const on = current === k;
        return (
          <div key={k} onClick={on ? undefined : fn}
            style={{ flex:1, textAlign:"center", padding:"10px 2px", fontSize:14.5, fontWeight:800, borderRadius:9, whiteSpace:"nowrap",
              background: on ? C.white : "transparent", color: on ? C.navy : C.textSec,
              boxShadow: on ? "0 1px 4px rgba(0,0,0,0.12)" : "none", cursor: on ? "default" : "pointer" }}>{l}</div>
        );
      })}
    </div>
  );
}
// ★期間の切り替え（「期間 ▾」のボタン。押すとスマホのいつもの選択画面が開く）
function PeriodPicker({ period, setPeriod, seasonLabel }) {
  const opts = [...(seasonLabel ? [["season", `📌 ${seasonLabel}以降`]] : []), ["month1","直近1ヶ月"], ["all","全期間"]];
  const cur = opts.find(o => o[0] === period) || opts[opts.length-1];
  return (
    <div style={{ position:"relative", flexShrink:0, maxWidth:"52%" }}>
      <div style={{ display:"flex", alignItems:"center", gap:4, padding:"9px 11px", borderRadius:10, background:C.white, border:`1.5px solid ${C.border}`, fontSize:12.5, fontWeight:800, color:C.navy, whiteSpace:"nowrap", overflow:"hidden" }}>
        <span style={{ fontSize:10.5, color:C.textSec, fontWeight:700, flexShrink:0 }}>期間</span>
        <span style={{ overflow:"hidden", textOverflow:"ellipsis" }}>{cur[1]}</span>
        <span style={{ flexShrink:0 }}>▾</span>
      </div>
      <select aria-label="期間" value={cur[0]} onChange={e=>setPeriod(e.target.value)}
        style={{ position:"absolute", inset:0, width:"100%", height:"100%", opacity:0, cursor:"pointer", fontSize:16 }}>
        {opts.map(([v,l]) => <option key={v} value={v}>{l}</option>)}
      </select>
    </div>
  );
}

// ★自チームのペアを選ぶシート（画面の下からせり上がる）
//   ・名前の一部で絞り込める
//   ・最近1ヶ月に試合したペアを上に出し、それ以外は「その他のペア」にまとめて閉じておく
function PairPickerSheet({ pairs, selectedKey, onSelect, onClose, allowAll }) {
  const [q, setQ] = useState("");
  const [showOthers, setShowOthers] = useState(false);
  const norm = (t) => String(t||"").replace(/[\s　・]/g, "");
  const rows = pairs.map(p => {
    let w = 0, l = 0, last = "";
    p.matches.forEach(m => {
      const ws = winnerSideOf(m);
      if (ws === "A") w++; else if (ws === "B") l++;
      if ((m.match_date||"") > last) last = m.match_date || "";
    });
    return { ...p, w, l, last };
  });
  const cutoff = (() => { const d = new Date(); d.setDate(d.getDate() - 30); return d.toISOString().slice(0,10); })();
  const byRecent = (a,b) => (b.last||"").localeCompare(a.last||"") || (b.matches.length - a.matches.length);
  const query = norm(q);
  const hits = query ? rows.filter(r => norm(r.label).includes(query)).sort((a,b)=>b.matches.length-a.matches.length) : null;
  let recent = rows.filter(r => r.last && r.last >= cutoff).sort(byRecent);
  let others = rows.filter(r => !(r.last && r.last >= cutoff)).sort((a,b)=>b.matches.length-a.matches.length);
  if (recent.length === 0) { recent = others; others = []; } // 最近の試合が無い期間は、全部をそのまま並べる
  const md = (d) => d ? d.slice(5).split("-").map(x=>String(Number(x))).join("/") : "";
  const Row = ({ r }) => {
    const on = r.key === selectedKey;
    return (
      <div onClick={()=>onSelect(r.key)}
        style={{ display:"flex", alignItems:"center", gap:10, padding:"10px 12px", border:`1.5px solid ${on ? "#0b6e75" : "#e3e7ee"}`, background: on ? "#eef8f8" : C.white, borderRadius:12, marginBottom:6, cursor:"pointer" }}>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontSize:15, fontWeight:800, color:C.text, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{r.label}</div>
          <div style={{ fontSize:11.5, color:C.textSec, fontWeight:700 }}>{r.last ? `最後の試合 ${md(r.last)}` : ""}</div>
        </div>
        <div style={{ textAlign:"right", flexShrink:0 }}>
          <div style={{ fontSize:14, fontWeight:900, color:C.text, whiteSpace:"nowrap" }}>{r.w}勝{r.l}敗</div>
          <div style={{ fontSize:11, color:C.textSec, fontWeight:700 }}>{r.matches.length}試合</div>
        </div>
        {on && <span style={{ width:22, height:22, borderRadius:"50%", background:"#0b6e75", color:C.white, fontSize:13, fontWeight:900, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>✓</span>}
      </div>
    );
  };
  const sec = (t) => <div style={{ fontSize:12, fontWeight:800, color:C.textSec, margin:"12px 2px 6px" }}>{t}</div>;
  return (
    <div onClick={onClose} style={{ position:"fixed", inset:0, background:"rgba(10,20,40,0.5)", zIndex:300, display:"flex", alignItems:"flex-end", justifyContent:"center" }}>
      <div onClick={e=>e.stopPropagation()}
        style={{ width:"100%", maxWidth:520, maxHeight:"85vh", background:C.white, borderRadius:"18px 18px 0 0", display:"flex", flexDirection:"column", paddingBottom:"env(safe-area-inset-bottom)" }}>
        <div style={{ padding:"8px 14px 0" }}>
          <div style={{ width:40, height:5, borderRadius:3, background:"#d5dae3", margin:"0 auto 10px" }} />
          <div style={{ display:"flex", alignItems:"center", marginBottom:10 }}>
            <div style={{ flex:1, fontSize:16.5, fontWeight:900, color:C.navy }}>自チームのペアを選ぶ</div>
            <button aria-label="閉じる" onClick={onClose} style={{ padding:0, width:32, height:32, borderRadius:"50%", border:"none", background:"#f0f2f5", color:C.textSec, fontSize:16, fontWeight:800, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>✕</button>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:6, background:"#f4f6f9", border:`1px solid ${C.border}`, borderRadius:10, padding:"0 11px", marginBottom:4 }}>
            <span style={{ fontSize:14 }}>🔍</span>
            <input value={q} onChange={e=>setQ(e.target.value)} placeholder="名前で探す（例：川崎）"
              style={{ flex:1, border:"none", outline:"none", background:"transparent", fontSize:16, padding:"9px 0", color:C.text, minWidth:0 }} />
            {/* ★スマホ本体の戻るは「✕」を押してシートを閉じるため、文字を消すボタンは別の記号にする */}
            {q && <button aria-label="文字を消す" onClick={()=>setQ("")} style={{ border:"none", background:"none", color:C.textSec, fontSize:13, cursor:"pointer", padding:"0 2px" }}>✖</button>}
          </div>
        </div>
        <div style={{ overflowY:"auto", padding:"0 14px 16px", WebkitOverflowScrolling:"touch" }}>
          {hits ? (
            <>
              {sec(`「${q}」のペア（${hits.length}組）`)}
              {hits.length === 0 && <div style={{ textAlign:"center", color:C.textSec, fontSize:13, padding:"18px 0" }}>見つかりませんでした</div>}
              {hits.map(r => <Row key={r.key} r={r} />)}
            </>
          ) : (
            <>
              {allowAll && (
                <div onClick={()=>onSelect("all")}
                  style={{ display:"flex", alignItems:"center", gap:10, padding:"12px", border:`1.5px solid ${selectedKey==="all" ? "#0b6e75" : "#e3e7ee"}`, background: selectedKey==="all" ? "#eef8f8" : C.white, borderRadius:12, margin:"10px 0 4px", cursor:"pointer" }}>
                  <div style={{ flex:1, fontSize:15, fontWeight:800, color:C.text }}>👥 すべてのペア<span style={{ fontSize:11.5, color:C.textSec, fontWeight:700, marginLeft:6 }}>チーム全体の対戦相手</span></div>
                  {selectedKey==="all" && <span style={{ width:22, height:22, borderRadius:"50%", background:"#0b6e75", color:C.white, fontSize:13, fontWeight:900, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>✓</span>}
                </div>
              )}
              {sec(others.length ? "最近試合したペア（直近1ヶ月）" : `ペア（${recent.length}組）`)}
              {recent.map(r => <Row key={r.key} r={r} />)}
              {others.length > 0 && (
                <>
                  {sec(`その他のペア（${others.length}組）`)}
                  {showOthers
                    ? others.map(r => <Row key={r.key} r={r} />)
                    : <div onClick={()=>setShowOthers(true)} style={{ textAlign:"center", fontSize:13, fontWeight:800, color:C.navy, padding:10, border:"1.5px dashed #c4cbd8", borderRadius:12, cursor:"pointer" }}>▾ その他のペアを表示</div>}
                </>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function PairAnalysisScreen({ onNavigate, onOpenPersonal, onOpenTeamStats, onOpenMatch }) {
  const [mySchoolName, setMySchoolName] = useState("");
  const [allMatches, setAllMatches] = useState([]);
  const [loading, setLoading] = useState(true);

  const [side, setSide] = useState(() => readScreenCache("pairAnalysis")?.side ?? "own");
  const [ownPairKey, setOwnPairKey] = useState(() => readScreenCache("pairAnalysis")?.ownPairKey ?? "");
  const [oppPairKey, setOppPairKey] = useState(() => readScreenCache("pairAnalysis")?.oppPairKey ?? "");
  const [oppOwnFilter, setOppOwnFilter] = useState(() => new Set()); // ★相手ペアの画面で、自チームのペアを選んで絞り込む（複数可）
  useEffect(() => { setOppOwnFilter(new Set()); }, [oppPairKey]);

  const [detailMatches, setDetailMatches] = useState([]); // 詳細（points込み）
  const [detailLoading, setDetailLoading] = useState(false);
  const [recordOpen, setRecordOpen] = useState(false);    // 通算成績の内訳の開閉
  const [pairPickerOpen, setPairPickerOpen] = useState(false); // ★自チームのペアを選ぶシート
  const [oppQuery, setOppQuery] = useState("");                // ★相手分析：学校名・選手名で絞り込み
  const [oppSort, setOppSort] = useState("count");             // ★相手分析：学校・ペアの並び順（rate|win|lose|count）
  const [openSchools, setOpenSchools] = useState(() => new Set()); // ★相手分析：開いている学校
  const [breakdownDim, setBreakdownDim] = useState("play");
  const [schoolId, setSchoolId] = useState(null);
  const [notes, setNotes] = useState([]);
  const [noteEditing, setNoteEditing] = useState(null); // {id?, text, match_id}
  const [noteOrder, setNoteOrder] = useState("desc"); // ★対戦メモの並び（desc=新しい順／asc=古い順）
  // ★期間（チームタブ・選手の戦績画面とそろえる）。シーズン設定があれば「📌◯◯以降」が初期値
  // ★開いた時点で前回の期間が保存されていたか（保存処理が先に走って上書きされる前に覚えておく）
  const cachedPeriodRef = useRef(readScreenCache("pairAnalysis")?.period);
  const [period, setPeriod] = useState(() => cachedPeriodRef.current ?? "all");
  const [seasonStart, setSeasonStart] = useState(null);
  const [seasonLabel, setSeasonLabel] = useState("");

  // ★前回開いたときのデータをすぐ表示し、裏で最新に差し替える（「読み込み中...」で待たせない）
  //   期間の初期値（シーズン）を決めるのは最初の1回だけ。裏の更新で、選び直した期間が戻らないようにする。
  const periodInitRef = useRef(false);
  const applyData = useCallback(([p, list, schools, simpleList, season]) => {
    if (p?.school_id) {
      setSchoolId(p.school_id);
      const s = (schools||[]).find(s => s.id === p.school_id);
      if (s) setMySchoolName(s.name);
      if (season?.season_start_date) {
        setSeasonStart(season.season_start_date);
        setSeasonLabel(season.season_start_label || defaultSeasonLabel(season.season_start_date));
        if (!cachedPeriodRef.current && !periodInitRef.current) setPeriod("season");
      } else {
        setSeasonStart(null);
        setPeriod(v => v==="season" ? "all" : v);
      }
    }
    periodInitRef.current = true;
    setAllMatches([...list, ...(simpleList||[])]);
    setLoading(false);
  }, []);
  useEffect(() => {
    const cached = readScreenCache("pairAnalysisData");
    if (cached) applyData(cached);
    (async () => {
      // ★トーナメント表で「結果だけ記録」した試合も勝敗に含める（チームタブと同じ数え方にする）
      // ★シーズン設定も同時に取得する（以前はプロフィール等を待ってから、もう1往復していた）
      const fresh = await Promise.all([getMyProfile(), getMatchesCached(), getSchools(), getSimpleRecordedDrawMatches(), getMySchoolSeason()]);
      writeScreenCache("pairAnalysisData", fresh);
      applyData(fresh);
    })();
  }, [applyData]);

  // ★試合スタッツを見て戻ってきたときに、選んでいたペアと画面の状態を復元する
  useEffect(() => {
    writeScreenCache("pairAnalysis", { side, ownPairKey, oppPairKey, period });
  }, [side, ownPairKey, oppPairKey, period]);

  // 自チームが出場した、終了済みの試合（自チーム側をA側にそろえたもの。期間で絞り込み）
  const ownMatches = useMemo(() => {
    const list = ownPerspectiveMatches(allMatches, mySchoolName);
    if (period === "month1") return withinLastDays(list, 30);
    if (period === "season" && seasonStart) return list.filter(m => (m.match_date||"") >= seasonStart);
    return list;
  }, [allMatches, mySchoolName, period, seasonStart]);

  // 自チームのペア一覧（出場試合数の多い順）
  const ownPairs = useMemo(() => {
    const map = {};
    ownMatches.forEach(m => {
      const pr = ownPairOf(m, mySchoolName);
      if (!pr) return;
      const rec = (map[pr.key] ??= { ...pr, matches: [], votes: {} });
      rec.matches.push(m);
      rec.votes[pr.names.join("\t")] = (rec.votes[pr.names.join("\t")] ?? 0) + 1;
    });
    // ★表示は「選手1（後衛）・選手2（前衛）」の順（そのペアの試合で一番多い入力順）
    return Object.values(map).map(r => {
      const o = majorityPairOrder(r.votes);
      return o.length ? { ...r, names: o, label: o.join("・") } : r;
    }).sort((a,b)=>b.matches.length-a.matches.length);
  }, [ownMatches, mySchoolName]);

  useEffect(() => {
    if (ownPairs.length === 0) return;
    // ★選んでいたペアが一覧に無い（データ更新で消えた等）ときや、
    //   「すべて」のまま自分たちタブに切り替えたときは、先頭のペアに戻す
    const valid = ownPairs.some(p => p.key === ownPairKey) || (side === "opp" && ownPairKey === "all");
    if (!valid) setOwnPairKey(ownPairs[0].key);
  }, [ownPairs, ownPairKey, side]);

  const selectedOwnPair = ownPairs.find(p => p.key === ownPairKey) || null;

  // 相手ペア一覧（自チームのペア指定に応じて対象試合を変える）
  const oppPairs = useMemo(() => {
    // ★相手分析では自チームのペアは選ばず、チーム全体が対戦した相手を並べる
    const base = ownMatches;
    const map = {};
    base.forEach(m => {
      // ★自チーム同士の部内戦は「対戦相手」ではないので除く
      const bClub = m.players.find(p=>p.team==="B")?.club_name;
      if (mySchoolName && bClub && bClub.trim() === mySchoolName.trim()) return;
      const op = oppPairOf(m);
      if (!op || !op.names[0]) return;
      const rec = (map[op.key] ??= { ...op, matches: [], w:0, l:0, ownPairKeys:new Set(), votes: {} });
      rec.matches.push(m);
      rec.votes[op.names.join("\t")] = (rec.votes[op.names.join("\t")] ?? 0) + 1;
      const ourSide = winnerSideOf(m);
      if (ourSide === "A") rec.w++; else if (ourSide === "B") rec.l++;
      const mine = ownPairOf(m, mySchoolName);
      if (mine) rec.ownPairKeys.add(mine.key);
    });
    return Object.values(map).map(r => {
      const o = majorityPairOrder(r.votes);
      return o.length ? { ...r, names: o, label: o.join("・") } : r;
    }).sort((a,b)=>b.matches.length-a.matches.length);
  }, [ownMatches, ownPairKey, selectedOwnPair, mySchoolName]);

  const selectedOppPair = oppPairs.find(p => p.key === oppPairKey) || null;

  // ★相手ペアを開いたら、そのペアのメモを読み込む
  useEffect(() => {
    if (!schoolId || !selectedOppPair) { setNotes([]); return; }
    let cancelled = false;
    getOpponentNotes(schoolId, selectedOppPair.key).then(rows => { if (!cancelled) setNotes(rows); });
    return () => { cancelled = true; };
  }, [schoolId, oppPairKey, selectedOppPair?.key]);

  async function handleSaveNote() {
    if (!noteEditing || !noteEditing.text.trim() || !schoolId || !selectedOppPair) return;
    try {
      await saveOpponentNote({
        id: noteEditing.id, school_id: schoolId,
        opponent_club: selectedOppPair.club, pair_key: selectedOppPair.key,
        pair_label: selectedOppPair.label, note_text: noteEditing.text,
        match_id: noteEditing.match_id,
      });
      setNoteEditing(null);
      setNotes(await getOpponentNotes(schoolId, selectedOppPair.key));
    } catch(e) { alert("保存に失敗しました: "+(e.message||e)); }
  }
  async function handleDeleteNote(id) {
    if (!window.confirm("このメモを削除しますか？")) return;
    try {
      await deleteOpponentNote(id);
      setNotes(await getOpponentNotes(schoolId, selectedOppPair.key));
    } catch(e) { alert("削除に失敗しました: "+(e.message||e)); }
  }

  // 表示対象の試合（自分たち＝そのペアの全試合／相手分析＝その相手ペアとの試合）
  const targetMatches = side === "own"
    ? (selectedOwnPair?.matches ?? [])
    : (selectedOppPair?.matches ?? []).filter(m => oppOwnFilter.size === 0 || oppOwnFilter.has(ownPairOf(m, mySchoolName)?.key));
  // ★この相手と当たった自チームのペア（勝敗・最後の対戦）
  const oppOwnRows = (() => {
    if (side !== "opp" || !selectedOppPair) return [];
    const map = {};
    selectedOppPair.matches.forEach(m => {
      const pr = ownPairOf(m, mySchoolName); if (!pr) return;
      const names = (m.players||[]).filter(p=>p.team==="A").sort((a,b)=>(a.order_num??0)-(b.order_num??0)).map(p=>p.player_name);
      const r = (map[pr.key] ??= { key:pr.key, label:names.join("・") || pr.label, n:0, w:0, l:0, last:null });
      r.n++;
      const ws = winnerSideOf(m); if (ws === "A") r.w++; else if (ws === "B") r.l++;
      if (!r.last || String(m.match_date||"") > String(r.last.match_date||"") || (m.match_date===r.last.match_date && roundProgressRank(m.round) > roundProgressRank(r.last.round))) r.last = m;
    });
    return Object.values(map).sort((a,b)=> b.n - a.n || String(b.last?.match_date||"").localeCompare(String(a.last?.match_date||"")));
  })();

  // ★対戦メモの時系列：自チームのペアの絞り込みに関係なく、この相手ペアと戦った全試合を並べる
  //   （メモは相手ペアごとに学校で共有しているので、どの自チームペアの試合のメモも一緒に読めるようにする）
  const allVsOppMatches = (side === "opp" && selectedOppPair)
    ? ownMatches.filter(m => {
        const bClub = m.players.find(p=>p.team==="B")?.club_name;
        if (mySchoolName && bClub && bClub.trim() === mySchoolName.trim()) return false;
        return oppPairOf(m)?.key === selectedOppPair.key;
      })
    : [];
  const noteTimeline = (() => {
    if (side !== "opp" || !selectedOppPair) return [];
    const byMatch = new Map(allVsOppMatches.map(m => [m.id, { type:"match", m, date:(m.match_date||"").slice(0,10), rank:roundProgressRank(m.round), notes:[] }]));
    const events = [...byMatch.values()];
    notes.forEach(n => {
      const ev = n.match_id && byMatch.get(n.match_id);
      if (ev) ev.notes.push(n);
      else events.push({ type:"free", date:(n.created_at||"").slice(0,10), rank:1000, notes:[n] });
    });
    events.forEach(ev => ev.notes.sort((a,b) => String(a.created_at||"").localeCompare(String(b.created_at||""))));
    const cmp = (a,b) => a.date.localeCompare(b.date) || (a.rank - b.rank) || String(a.notes[0]?.created_at||"").localeCompare(String(b.notes[0]?.created_at||""));
    events.sort(cmp);
    if (noteOrder === "desc") events.reverse();
    return events;
  })();
  // ★その試合で登録した順（後衛→前衛）で、自チームのペア名を出す
  const ownPairNamesOf = (m) => (m.players||[]).filter(p=>p.team==="A").sort((a,b)=>(a.order_num??0)-(b.order_num??0)).map(p=>String(p.player_name||"").trim()).filter(Boolean);

  // ★points込みの詳細は、見る対象が決まったタイミングでその分だけ読み込む
  useEffect(() => {
    // ★簡易記録（ポイントなし）の試合は詳細の読み込み対象から外す
    const ids = targetMatches.filter(m=>!m.is_simple_draw_result).map(m=>m.id);
    if (ids.length === 0) { setDetailMatches([]); return; }
    let cancelled = false;
    (async () => {
      setDetailLoading(true);
      const full = await getFullMatchesByIds(ids);
      if (cancelled) return;
      full.sort((a,b)=> new Date(a.match_date)-new Date(b.match_date));
      setDetailMatches(full);
      setDetailLoading(false);
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
    // ★相手分析で自チームのペアを選んで絞り込んだときも、内訳・サーブ・コースなどを読み直す
  }, [side, ownPairKey, oppPairKey, allMatches.length, period, seasonStart, [...oppOwnFilter].sort().join("|")]);

  const wins = targetMatches.filter(m => winnerSideOf(m)==="A").length;
  const losses = targetMatches.filter(m => winnerSideOf(m)==="B").length;

  // 集計（自分たち＝自チームペア、相手分析＝相手ペアの2人）
  const statNames = side === "own"
    ? (selectedOwnPair?.names ?? [])
    : (selectedOppPair?.names ?? []);
  const { pair: pairAgg, byPlayer } = useMemo(() => {
    if (statNames.length < 2 || detailMatches.length === 0) return { pair:null, byPlayer:{} };
    return aggregatePairStats(detailMatches, statNames[0], statNames[1], mySchoolName, side === "opp");
  }, [detailMatches, statNames.join("|"), mySchoolName, side]);

  const topWin = pairAgg ? Object.entries(pairAgg.playsWin).sort((a,b)=>b[1]-a[1]).slice(0,5) : [];
  const topErr = pairAgg ? Object.entries(pairAgg.playsErr).sort((a,b)=>b[1]-a[1]).slice(0,5) : [];
  const maxPlay = Math.max(1, ...topWin.map(x=>x[1]), ...topErr.map(x=>x[1]));
  const courseStats = pairAgg ? buildCourseStats(pairAgg) : null;

  // ★試合展開：1ゲーム目を取れたかどうか、ファイナル、ストレート勝ちなど
  const flowStats = useMemo(() => {
    if (detailMatches.length === 0) return null;
    // 相手分析のときは「相手から見た」展開にするため、勝ち側を入れ替える
    const weAreA = side === "own";
    let firstWon = { n:0, w:0 }, firstLost = { n:0, w:0 }, finalGame = { n:0, w:0 }, straight = 0;
    detailMatches.forEach(m => {
      const games = [...(m.games ?? [])].sort((a,b)=>(a.game_number??0)-(b.game_number??0));
      if (games.length === 0) return;
      const winA = winnerSideOf(m) === "A";
      const won = weAreA ? winA : !winA;
      const g1 = games[0];
      if (g1 && g1.winner_team) {
        const g1Mine = weAreA ? g1.winner_team === "A" : g1.winner_team === "B";
        const bucket = g1Mine ? firstWon : firstLost;
        bucket.n++; if (won) bucket.w++;
      }
      // ファイナルゲーム（最終ゲームまでもつれた試合）
      const need = Math.ceil((m.game_format ?? 7) / 2) + 1;
      const a = m.match_score_a ?? 0, b = m.match_score_b ?? 0;
      if (Math.min(a,b) === need - 1) { finalGame.n++; if (won) finalGame.w++; }
      if (won && Math.min(a,b) === 0) straight++;
    });
    return { firstWon, firstLost, finalGame, straight };
  }, [detailMatches, side]);

  const SplitBar = ({ pull, nagashi, total }) => (
    <>
      <div style={{ display:"flex", height:26, borderRadius:7, overflow:"hidden", background:"#eef0f3" }}>
        {pull>0 && <div style={{ width:`${pull/total*100}%`, background:COURSE_PULL_COLOR, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13, fontWeight:800, color:C.white }}>{Math.round(pull/total*100)}%</div>}
        {nagashi>0 && <div style={{ width:`${nagashi/total*100}%`, background:COURSE_NAGASHI_COLOR, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13, fontWeight:800, color:C.white }}>{Math.round(nagashi/total*100)}%</div>}
      </div>
      <div style={{ display:"flex", justifyContent:"space-between", fontSize:13, color:C.textSec, marginTop:6 }}>
        <span>引っ張り <b style={{ fontSize:15, fontWeight:800, color:C.text }}>{pull}</b>本</span>
        <span>流し <b style={{ fontSize:15, fontWeight:800, color:C.text }}>{nagashi}</b>本</span>
      </div>
    </>
  );

  const Bar = ({ label, count, color }) => (
    <div style={{ display:"flex", alignItems:"center", fontSize:13.5, padding:"6px 0" }}>
      <div style={{ width:100, color:C.text, fontWeight:700, whiteSpace:"nowrap" }}>{getPlayLabel ? getPlayLabel(label) : label}</div>
      <div style={{ flex:1, height:10, background:"#eef0f3", borderRadius:5, margin:"0 8px", overflow:"hidden" }}>
        <div style={{ height:"100%", width:`${count/maxPlay*100}%`, background:color, borderRadius:5 }}/>
      </div>
      <div style={{ width:30, textAlign:"right", fontWeight:800, color:C.navy }}>{count}</div>
    </div>
  );

  const selStyle = { width:"100%", padding:"11px 10px", borderRadius:9, border:`1.5px solid ${C.border}`,
    background:C.white, fontSize:14.5, fontWeight:700, color:C.text, marginBottom:10, fontFamily:"inherit" };

  return (
    <div style={{ minHeight:"100vh", background:C.gray, paddingBottom:90, fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
      <div style={{ ...S.hdr, color:C.white }}>
        <div style={{ fontSize:20, fontWeight:800 }}>分析</div>
      </div>
      <div style={{ padding:14 }}>

        {pairPickerOpen && (
          <PairPickerSheet pairs={ownPairs} selectedKey={ownPairKey} allowAll={side === "opp"}
            onSelect={k=>{ setOwnPairKey(k); setOppPairKey(""); setRecordOpen(false); setPairPickerOpen(false); window.scrollTo(0,0); }}
            onClose={()=>setPairPickerOpen(false)} />
        )}
        <AnalysisTabs current="pair" onPersonal={()=>onOpenPersonal && onOpenPersonal()} onTeam={()=>onOpenTeamStats && onOpenTeamStats()} />

        {/* ★「自分たち／相手分析」の切り替えと期間を1行にまとめる */}
        <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:12 }}>
          <div style={{ display:"flex", flex:1, minWidth:0, border:`2px solid ${C.navy}`, borderRadius:10, overflow:"hidden" }}>
            {[["own","自分たち"],["opp","相手分析"]].map(([k,l])=>(
              <div key={k} onClick={()=>{ setSide(k); setOppPairKey(""); }}
                style={{ flex:1, textAlign:"center", padding:"9px 2px", fontSize:14, fontWeight:800, cursor:"pointer", whiteSpace:"nowrap",
                  background: side===k ? C.navy : C.white, color: side===k ? C.white : C.navy }}
              >{l}</div>
            ))}
          </div>
          <PeriodPicker period={period} setPeriod={setPeriod} seasonLabel={seasonStart ? seasonLabel : null} />
        </div>

        {loading ? (
          <div style={{ textAlign:"center", color:C.textSec, padding:"40px 0" }}>読み込み中...</div>
        ) : ownPairs.length === 0 ? (
          <div style={{ textAlign:"center", color:C.textSec, padding:"40px 0", fontSize:13.5 }}>この期間の試合記録がありません</div>
        ) : (
          <>
            {/* ============ 相手分析：対戦した学校ごとの一覧 ============ */}
            {side === "opp" && !selectedOppPair && (() => {
              const norm = (t) => String(t||"").replace(/[\s　・]/g, "");
              const qq = norm(oppQuery);
              const schools = {};
              oppPairs.forEach(p => {
                const club = p.club || "（学校名なし）";
                const sc = (schools[club] ??= { club, pairs:[], n:0, w:0, l:0 });
                sc.pairs.push(p); sc.n += p.matches.length; sc.w += p.w; sc.l += p.l;
              });
              const rec = (x) => ({ wins:x.w, losses:x.l, total:x.n ?? x.matches.length });
              const cmp = (a,b) => sortByRecord(oppSort)(rec(a), rec(b));
              let list = Object.values(schools).sort((a,b)=> cmp(a,b) || a.club.localeCompare(b.club, "ja"));
              if (qq) {
                list = list.map(sc => norm(sc.club).includes(qq) ? sc : { ...sc, pairs: sc.pairs.filter(p => norm(p.label).includes(qq)) })
                           .filter(sc => sc.pairs.length > 0);
              }
              const wlColor = (w,l) => w > l ? C.accent : w < l ? C.teamB : C.textSec;
              return (
                <>
                  <div style={{ display:"flex", alignItems:"center", gap:6, background:C.white, border:`1.5px solid ${C.border}`, borderRadius:10, padding:"0 11px", marginBottom:4 }}>
                    <span style={{ fontSize:14 }}>🔍</span>
                    <input value={oppQuery} onChange={e=>setOppQuery(e.target.value)} placeholder="学校名・選手名で探す"
                      style={{ flex:1, border:"none", outline:"none", background:"transparent", fontSize:16, padding:"10px 0", color:C.text, minWidth:0 }} />
                    {oppQuery && <button aria-label="文字を消す" onClick={()=>setOppQuery("")} style={{ border:"none", background:"none", color:C.textSec, fontSize:13, cursor:"pointer", padding:"0 2px" }}>✖</button>}
                  </div>
                  <div style={{ fontSize:12, fontWeight:800, color:C.textSec, margin:"12px 2px 6px" }}>
                    {qq ? `「${oppQuery}」で見つかった学校（${list.length}校）` : `対戦した学校（${list.length}校）`}
                  </div>
                  {/* ★並び順（チーム分析と同じ） */}
                  <div style={{ display:"flex", gap:5, marginBottom:8 }}>
                    {[["rate","勝率順"],["win","勝数順"],["lose","負数順"],["count","試合数順"]].map(([k,l])=>(
                      <button key={k} style={{ ...S.togBtn(oppSort===k,C.navy), flex:1, fontSize:12.5, padding:"7px 4px", whiteSpace:"nowrap" }} onClick={()=>setOppSort(k)}>{l}</button>
                    ))}
                  </div>
                  {list.length === 0 && <div style={{ textAlign:"center", color:C.textSec, padding:"30px 0", fontSize:13.5 }}>{qq ? "見つかりませんでした" : "対戦した記録がありません"}</div>}
                  {list.map(sc => {
                    const open = !!qq || openSchools.has(sc.club);
                    return (
                      <div key={sc.club} style={{ ...S.card, marginBottom:8 }}>
                        <div onClick={()=>setOpenSchools(prev => { const nx = new Set(prev); nx.has(sc.club) ? nx.delete(sc.club) : nx.add(sc.club); return nx; })}
                          style={{ display:"flex", alignItems:"center", gap:8, padding:12, cursor:"pointer" }}>
                          <div style={{ flex:1, minWidth:0, fontSize:15.5, fontWeight:900, color:C.text }}>
                            {sc.club}<span style={{ fontSize:11.5, color:C.textSec, fontWeight:700, marginLeft:6 }}>{sc.pairs.length}ペア・{sc.n}試合</span>
                          </div>
                          <div style={{ fontSize:14, fontWeight:900, color:wlColor(sc.w, sc.l), whiteSpace:"nowrap" }}>{sc.w}勝{sc.l}敗</div>
                          <span style={{ color:"#a0a8b8", fontSize:13 }}>{open ? "▴" : "▾"}</span>
                        </div>
                        {open && (
                          <div style={{ borderTop:`1px solid ${C.border}`, background:"#fafbfc", padding:"4px 10px 6px" }}>
                            {[...sc.pairs].sort((a,b)=> sortByRecord(oppSort)({ wins:a.w, losses:a.l, total:a.matches.length }, { wins:b.w, losses:b.l, total:b.matches.length })).map((p, idx, arr) => (
                              <div key={p.key} onClick={()=>{ setOppPairKey(p.key); window.scrollTo(0,0); }}
                                style={{ display:"flex", alignItems:"center", gap:8, padding:"10px 4px", borderBottom: idx===arr.length-1 ? "none" : `1px solid ${C.border}`, cursor:"pointer" }}>
                                <span style={{ flex:1, minWidth:0, fontSize:14, fontWeight:800, color:C.text }}>
                                  {p.label}
                                  <span style={{ display:"block", fontSize:11, color:C.textSec, fontWeight:700, marginTop:1 }}>自チーム{p.ownPairKeys.size}ペアと対戦・{p.matches.length}試合</span>
                                </span>
                                <span style={{ fontSize:13.5, fontWeight:900, color:wlColor(p.w, p.l), whiteSpace:"nowrap" }}>{p.w}勝{p.l}敗</span>
                                <span style={{ color:"#a0a8b8", fontSize:16 }}>›</span>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </>
              );
            })()}

            {/* ============ 集計（自分たち／相手ペア詳細） ============ */}
            {(side === "own" || selectedOppPair) && (
              <>
                {side === "opp" && (
                  <div onClick={()=>{ setOppPairKey(""); window.scrollTo(0,0); }} style={{ fontSize:13.5, fontWeight:700, color:C.navy, marginBottom:10, cursor:"pointer" }}>← 相手ペアの一覧に戻る</div>
                )}

                <div onClick={side==="own" ? undefined : ()=>setRecordOpen(v=>!v)} style={{ ...S.card, padding:14, marginBottom:12, cursor: side==="own" ? "default" : "pointer" }}>
                  {side === "own" ? (() => {
                    const recent = [...targetMatches].sort((a,b)=> String(b.match_date||"").localeCompare(String(a.match_date||"")) || (roundProgressRank(b.round)-roundProgressRank(a.round))).slice(0,5);
                    return (
                      <>
                        <div style={{ fontSize:12, fontWeight:800, color:C.textSec, marginBottom:3 }}>自チームのペア</div>
                        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                          <div style={{ flex:1, minWidth:0, fontSize:19, fontWeight:900, color:C.text }}>{selectedOwnPair?.label}</div>
                          <button onClick={()=>setPairPickerOpen(true)}
                            style={{ flexShrink:0, fontSize:13, fontWeight:800, color:C.navy, background:"#eceff4", border:"none", borderRadius:16, padding:"7px 12px", whiteSpace:"nowrap", cursor:"pointer" }}>変更 ▾</button>
                        </div>
                        <div style={{ display:"flex", alignItems:"baseline", gap:8, marginTop:6 }}>
                          <span style={{ fontSize:28, fontWeight:900, color:C.text }}><WinLossText wins={wins} losses={losses} /></span>
                          <span style={{ fontSize:13.5, color:C.textSec, fontWeight:700 }}>
                            {targetMatches.length}試合{targetMatches.length>0 && `・勝率${Math.round(wins/targetMatches.length*100)}%`}
                          </span>
                        </div>
                        <div style={{ display:"flex", alignItems:"center", gap:4, marginTop:8 }}>
                          {recent.map(m => { const w = winnerSideOf(m)==="A"; return (
                            <span key={m.id} style={{ width:22, height:22, borderRadius:"50%", background: w ? C.accent : C.red, color:C.white, fontSize:11, fontWeight:800, display:"inline-flex", alignItems:"center", justifyContent:"center" }}>{w?"勝":"敗"}</span>
                          ); })}
                          {recent.length > 0 && <span style={{ fontSize:11.5, color:C.textSec, fontWeight:700, marginLeft:4 }}>直近{recent.length}試合</span>}
                          <span onClick={()=>setRecordOpen(v=>!v)} style={{ marginLeft:"auto", fontSize:13, fontWeight:800, color:C.navy, cursor:"pointer", padding:"4px 0 4px 8px", whiteSpace:"nowrap" }}>試合一覧 {recordOpen?"▴":"▾"}</span>
                        </div>
                      </>
                    );
                  })() : (
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                    <div>
                      {side === "opp" && <div style={{ fontSize:12.5, color:C.textSec, fontWeight:700 }}>{selectedOppPair.club}</div>}
                      <div style={{ fontSize:19, fontWeight:900, color:C.text, margin:"2px 0 6px" }}>
                        {side === "own" ? selectedOwnPair?.label : selectedOppPair.label}
                      </div>
                      <div>
                        <span style={{ fontSize:24, fontWeight:900, color:C.text }}>{wins}</span><span style={{ fontSize:14, color:C.textSec }}>勝</span>
                        <span style={{ fontSize:24, fontWeight:900, color:C.text, marginLeft:4 }}>{losses}</span><span style={{ fontSize:14, color:C.textSec }}>敗</span>
                        <span style={{ fontSize:13.5, color:C.textSec, marginLeft:8 }}>
                          {targetMatches.length}試合{targetMatches.length>0 && `・勝率${Math.round(wins/targetMatches.length*100)}%`}
                        </span>
                      </div>
                      {side === "opp" && ((oppOwnFilter.size === 0 || oppOwnFilter.size === oppOwnRows.length)
                        ? <div style={{ fontSize:11.5, color:C.textSec, fontWeight:700, marginTop:3 }}>自チーム全体での通算</div>
                        : <div style={{ display:"flex", alignItems:"center", flexWrap:"wrap", gap:6, fontSize:11.5, color:"#0b6e75", fontWeight:800, marginTop:4 }}>
                            <span>{oppOwnFilter.size === 1 ? `${oppOwnRows.find(r=>oppOwnFilter.has(r.key))?.label ?? ""} との対戦だけ表示中` : `${oppOwnFilter.size}ペアとの対戦だけ表示中`}</span>
                            <span onClick={e=>{ e.stopPropagation(); setOppOwnFilter(new Set()); }} style={{ background:"#e3f3f3", borderRadius:10, padding:"2px 9px", cursor:"pointer", whiteSpace:"nowrap" }}>全体に戻す</span>
                          </div>)}
                    </div>
                    <div style={{ color:C.textSec, fontSize:15 }}>{recordOpen?"▲":"▼"}</div>
                  </div>
                  )}

                  {recordOpen && (
                    <div style={{ marginTop:12, borderTop:`1px solid ${C.border}`, paddingTop:10 }}>
                      {[...targetMatches].sort((a,b)=> new Date(b.match_date)-new Date(a.match_date)).map(m => {
                        const win = winnerSideOf(m)==="A";
                        const other = side==="own" ? oppPairOf(m) : ownPairOf(m, mySchoolName);
                        return (
                          <div key={m.id} onClick={e=>{ e.stopPropagation(); if (!m.is_simple_draw_result) onOpenMatch && onOpenMatch(m.id); }}
                            style={{ display:"flex", alignItems:"center", gap:8, padding:"9px 0", borderBottom:`1px solid ${C.border}`, fontSize:13.5, cursor:"pointer" }}>
                            <span style={{ color:C.textSec, fontSize:12.5, width:42, flexShrink:0 }}>{(m.match_date||"").slice(5).replace("-","/")}</span>
                            <span style={{ flex:1, minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                              {other ? `${other.club ? other.club+" " : ""}${other.label}` : ""}
                            </span>
                            <span style={{ fontWeight:800 }}>{m.match_score_a}-{m.match_score_b}</span>
                            <span style={{ fontWeight:900, color:win?C.accent:C.red, width:26, textAlign:"right" }}>{win?"勝":"敗"}</span>
                            <span style={{ color:C.textSec, fontSize:15 }}>›</span>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>

                {/* ★この相手と当たった自チームのペア（押すと、そのペアとの試合だけに絞る。複数選べる） */}
                {side === "opp" && selectedOppPair && oppOwnRows.length > 0 && (
                  <div style={{ ...S.card, padding:"12px 12px 6px", marginBottom:12 }}>
                    {/* ★まとめて選ぶ／外す */}
                    <div style={{ display:"flex", justifyContent:"flex-end", gap:6, marginBottom:8 }}>
                      <button onClick={()=>setOppOwnFilter(new Set(oppOwnRows.map(r=>r.key)))}
                        style={{ fontSize:12.5, fontWeight:800, color:C.navy, background:"#eceff4", border:"none", borderRadius:16, padding:"6px 12px", cursor:"pointer" }}>すべて選択</button>
                      <button onClick={()=>setOppOwnFilter(new Set())} disabled={oppOwnFilter.size===0}
                        style={{ fontSize:12.5, fontWeight:800, color: oppOwnFilter.size ? C.textSec : "#c4cbd8", background:C.white, border:`1.5px solid ${C.border}`, borderRadius:16, padding:"5px 12px", cursor: oppOwnFilter.size ? "pointer" : "default" }}>クリア</button>
                    </div>
                    {oppOwnRows.map(r => {
                      const on = oppOwnFilter.has(r.key);
                      const col = r.w > r.l ? C.accent : r.w < r.l ? C.teamB : C.textSec;
                      const md = (r.last?.match_date||"").slice(5).split("-").map(x=>String(Number(x))).join("/");
                      return (
                        <div key={r.key} onClick={()=>setOppOwnFilter(prev => { const nx = new Set(prev); nx.has(r.key) ? nx.delete(r.key) : nx.add(r.key); return nx; })}
                          style={{ display:"flex", alignItems:"center", gap:8, background: on ? "#eef8f8" : C.gray, border:`1.5px solid ${on ? "#0b6e75" : "transparent"}`, borderRadius:10, padding:"10px 11px", marginBottom:6, cursor:"pointer" }}>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ fontSize:14.5, fontWeight:800, color:C.text }}>{r.label}</div>
                            <div style={{ fontSize:11, color:C.textSec, fontWeight:700 }}>{r.n}試合{md && `・最後 ${md}`}{r.last?.round ? ` ${r.last.round}` : ""}</div>
                          </div>
                          <div style={{ fontSize:14, fontWeight:900, color:col, whiteSpace:"nowrap" }}>{r.w}勝{r.l}敗</div>
                          {on
                            ? <span style={{ width:20, height:20, borderRadius:"50%", background:"#0b6e75", color:C.white, fontSize:12, fontWeight:900, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>✓</span>
                            : <span style={{ width:20, height:20, borderRadius:"50%", border:"1.5px solid #c4cbd8", flexShrink:0 }} />}
                        </div>
                      );
                    })}
                  </div>
                )}

                {/* ★相手ペアへのメモ */}
                {side === "opp" && selectedOppPair && (
                  <div style={S.card}>
                    <div style={{ padding:14 }}>
                      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
                        <div style={{ fontSize:15, fontWeight:800, color:C.navy }}>📝 対戦メモ（{notes.length}件）</div>
                        {!noteEditing && (
                          <button onClick={()=>setNoteEditing({ text:"", match_id:null })}
                            style={{ background:`linear-gradient(135deg,${C.navy},${C.navyMid})`, border:"none", borderRadius:20, fontSize:14, fontWeight:800, color:C.white, padding:"9px 16px", cursor:"pointer", flexShrink:0, whiteSpace:"nowrap", boxShadow:"0 2px 6px rgba(15,32,68,0.25)" }}>＋ メモを書く</button>
                        )}
                      </div>

                      {noteEditing && (
                        <div style={{ background:C.gray, borderRadius:10, padding:12, marginBottom:10 }}>
                          <textarea
                            value={noteEditing.text}
                            onChange={e=>setNoteEditing(v=>({ ...v, text:e.target.value }))}
                            placeholder={"気づいたことを書いてください\n例：田中のポーチが速い。ロブで一度下げてから展開する。"}
                            style={{ width:"100%", boxSizing:"border-box", minHeight:110, padding:12, borderRadius:9, border:`1.5px solid ${C.border}`,
                              fontSize:14.5, lineHeight:1.75, color:C.text, fontFamily:"inherit", resize:"vertical" }}
                          />
                          <div style={{ fontSize:13, fontWeight:700, color:C.text, margin:"10px 0 6px" }}>どの試合のメモですか？（任意）</div>
                          <div style={{ display:"flex", flexDirection:"column", gap:6, marginBottom:10 }}>
                            {[...allVsOppMatches].sort((a,b)=> String(b.match_date||"").localeCompare(String(a.match_date||"")) || (roundProgressRank(b.round)-roundProgressRank(a.round))).map(m => {
                              const on = noteEditing.match_id === m.id;
                              const win = winnerSideOf(m)==="A";
                              const md = (m.match_date||"").slice(5).split("-").map(x=>String(Number(x))).join("/");
                              return (
                                <div key={m.id} onClick={()=>setNoteEditing(v=>({ ...v, match_id: on ? null : m.id }))}
                                  style={{ display:"flex", alignItems:"center", gap:8, padding:"9px 12px", borderRadius:9, fontSize:13, fontWeight:700, cursor:"pointer",
                                    border:`1.5px solid ${on?C.navy:C.border}`, background:on?C.navy:C.white, color:on?C.white:C.textSec }}>
                                  <span style={{ minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{md} {m.round||""}　{ownPairNamesOf(m).map(n=>n.split(/[\s　]+/)[0]).join("・")}</span>
                                  <span style={{ marginLeft:"auto", fontWeight:900, whiteSpace:"nowrap" }}>{m.match_score_a}-{m.match_score_b} {win?"勝":"敗"}</span>
                                </div>
                              );
                            })}
                          </div>
                          <button onClick={handleSaveNote} disabled={!noteEditing.text.trim()}
                            style={{ width:"100%", padding:14, borderRadius:10, border:"none", fontSize:15, fontWeight:800, marginBottom:8,
                              background: noteEditing.text.trim() ? C.navy : "#d5dae2", color:C.white, cursor:"pointer" }}>保存する</button>
                          <button onClick={()=>setNoteEditing(null)}
                            style={{ width:"100%", padding:12, borderRadius:10, border:`1.5px solid ${C.border}`, background:C.white, fontSize:14, fontWeight:700, color:C.textSec, cursor:"pointer" }}>キャンセル</button>
                        </div>
                      )}

                      {noteTimeline.length > 1 && !noteEditing && (
                        <div style={{ display:"flex", background:C.gray, borderRadius:9, padding:3, gap:3, marginBottom:12 }}>
                          {[["desc","新しい順"],["asc","古い順"]].map(([v,l]) => (
                            <button key={v} onClick={()=>setNoteOrder(v)}
                              style={{ flex:1, padding:"7px 4px", borderRadius:7, border:"none", fontSize:12.5, fontWeight:800, cursor:"pointer",
                                background: noteOrder===v ? C.white : "transparent", color: noteOrder===v ? C.navy : C.textSec,
                                boxShadow: noteOrder===v ? "0 1px 3px rgba(0,0,0,0.12)" : "none" }}>{l}</button>
                          ))}
                        </div>
                      )}

                      {notes.length === 0 && !noteEditing && (
                        <div style={{ textAlign:"center", color:C.textSec, fontSize:13.5, padding:"6px 0 14px" }}>
                          まだメモがありません。次に当たるときのために書いておけます。
                        </div>
                      )}

                      {/* ★試合の流れに沿ってメモを並べる（メモのない試合も並べて、対戦の流れが途切れないようにする） */}
                      {noteTimeline.length > 0 && (
                        <div style={{ position:"relative", paddingLeft:20 }}>
                          <div style={{ position:"absolute", left:6, top:6, bottom:6, width:2, background:C.border }} />
                          {noteTimeline.map((ev, idx) => {
                            const isMatch = ev.type === "match";
                            const m = ev.m;
                            const win = isMatch && winnerSideOf(m)==="A";
                            const dotColor = !isMatch ? "#c4cbd8" : win ? C.accent : C.red;
                            const ours = isMatch ? ownPairNamesOf(m).join("・") : "";
                            const title = isMatch ? [m.tournament_name, m.round].filter(Boolean).join("・") : "";
                            return (
                              <div key={isMatch ? m.id : "free-"+ev.notes[0].id} style={{ position:"relative", marginBottom: idx===noteTimeline.length-1 ? 0 : 14 }}>
                                <span style={{ position:"absolute", left:-19, top:5, width:12, height:12, borderRadius:"50%", background:dotColor, border:"2px solid #fff", boxShadow:`0 0 0 1.5px ${dotColor}` }} />
                                <div style={{ display:"flex", alignItems:"baseline", gap:6, flexWrap:"wrap" }}>
                                  <span style={{ fontSize:13, fontWeight:800, color: isMatch ? C.navy : "#8a5a00" }}>{(ev.date||"").replace(/-/g,"/")}</span>
                                  {isMatch
                                    ? (title && <span style={{ fontSize:12.5, color:"#5a6478", fontWeight:700 }}>{title}</span>)
                                    : <span style={{ fontSize:11, fontWeight:800, color:"#8a5a00", background:"#fff4e5", border:"1px solid #f5c979", borderRadius:6, padding:"1px 7px" }}>試合に紐づけなし</span>}
                                </div>
                                {isMatch && (
                                  <div onClick={()=>{ if (!m.is_simple_draw_result) onOpenMatch && onOpenMatch(m.id); }}
                                    style={{ display:"flex", alignItems:"center", gap:8, marginTop:3, fontSize:13.5, cursor: m.is_simple_draw_result ? "default" : "pointer" }}>
                                    <span style={{ flex:1, minWidth:0, fontWeight:700, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{ours}</span>
                                    <span style={{ fontWeight:800 }}>{m.match_score_a}-{m.match_score_b}</span>
                                    <span style={{ fontWeight:900, width:20, textAlign:"right", color: win ? C.accent : C.red }}>{win?"勝":"敗"}</span>
                                  </div>
                                )}
                                {isMatch && ev.notes.length === 0 && (
                                  <div style={{ fontSize:12, color:"#a0a8b8", marginTop:5 }}>この試合のメモはありません</div>
                                )}
                                {ev.notes.map(n => (
                                  <div key={n.id} style={{ background:"#fffdf5", border:"1px solid #f0dfa8", borderRadius:10, padding:"10px 12px", marginTop:8 }}>
                                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", fontSize:12, color:C.textSec, fontWeight:700, marginBottom:5 }}>
                                      <span>{(n.created_at||"").slice(5,10).split("-").map(x=>String(Number(x))).join("/")} に記入</span>
                                      <span style={{ display:"flex", alignItems:"center", gap:12 }}>
                                        <span onClick={()=>handleDeleteNote(n.id)} style={{ color:C.red, cursor:"pointer", padding:"2px 0" }}>削除</span>
                                        <span onClick={()=>setNoteEditing({ id:n.id, text:n.note_text, match_id:n.match_id })} style={{ color:C.navy, cursor:"pointer", padding:"2px 0" }}>編集</span>
                                      </span>
                                    </div>
                                    <div style={{ fontSize:14, color:C.text, lineHeight:1.75, whiteSpace:"pre-wrap" }}>{n.note_text}</div>
                                  </div>
                                ))}
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {detailLoading ? (
                  <div style={{ textAlign:"center", color:C.textSec, padding:"30px 0" }}>集計中...</div>
                ) : !pairAgg || pairAgg.total === 0 ? (
                  <div style={{ ...S.card, padding:20, textAlign:"center", color:C.textSec, fontSize:13.5 }}>
                    得点の記録がある試合がありません
                  </div>
                ) : (
                  <>
                    <div style={S.card}>
                      <div style={{ padding:14 }}>
                        <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:10 }}>
                          {side==="own" ? "📋 決めた・ミスの内訳" : "🔴 この相手の決めた・ミスの内訳"}
                        </div>
                        <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:12 }}>
                          <div style={{ textAlign:"center", padding:"12px 2px", background:C.gray, borderRadius:10 }}>
                            <div style={{ fontSize:21, fontWeight:800, color:C.navy }}>{pairAgg.winners}</div>
                            <div style={{ fontSize:12, color:C.textSec, marginTop:3 }}>決めた</div>
                          </div>
                          <div style={{ textAlign:"center", padding:"12px 2px", background:C.gray, borderRadius:10 }}>
                            <div style={{ fontSize:21, fontWeight:800, color:C.navy }}>{pairAgg.errors}</div>
                            <div style={{ fontSize:12, color:C.textSec, marginTop:3 }}>ミス</div>
                          </div>
                          <div style={{ textAlign:"center", padding:"12px 2px", background:C.gray, borderRadius:10 }}>
                            <div style={{ fontSize:21, fontWeight:800, color:C.navy }}>{pairAgg.total>0?Math.round(pairAgg.winners/pairAgg.total*100):0}%</div>
                            <div style={{ fontSize:12, color:C.textSec, marginTop:3 }}>決定率</div>
                          </div>
                        </div>
                        <div style={{ fontSize:13, color:C.textSec, fontWeight:700, marginBottom:5 }}>✅ 決めた</div>
                        {topWin.map(([l,c])=><Bar key={"w"+l} label={l} count={c} color={C.accent}/>)}
                        <div style={{ fontSize:13, color:C.textSec, fontWeight:700, margin:"12px 0 5px" }}>⚠️ ミス</div>
                        {topErr.map(([l,c])=><Bar key={"e"+l} label={l} count={c} color={C.red}/>)}
                      </div>
                    </div>

                    <div style={S.card}>
                      <div style={{ padding:14 }}>
                        <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:10 }}>🤝 2人それぞれの成績</div>
                        <div style={{ display:"flex", gap:8 }}>
                          {statNames.map(n => {
                            const a = byPlayer[n];
                            return (
                              <div key={n} style={{ flex:1, background:C.gray, borderRadius:10, padding:12, textAlign:"center" }}>
                                <div style={{ fontSize:15, fontWeight:800, color:C.text, marginBottom:6 }}>{n}</div>
                                <div style={{ fontSize:13, color:C.textSec }}>
                                  決め <b style={{ fontSize:16, color:C.text }}>{a?.winners ?? 0}</b>
                                  　ミス <b style={{ fontSize:16, color:C.text }}>{a?.errors ?? 0}</b>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </div>

                    <div style={S.card}>
                      <div style={{ padding:14 }}>
                        <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:10 }}>🎾 サーブ</div>
                        {[["1stサーブ得点率", pairAgg.serve1st, pairAgg.serve1stWin],
                          ["2ndサーブ得点率", pairAgg.serve2nd, pairAgg.serve2ndWin]].map(([label,tot,win])=>(
                          <div key={label} style={{ display:"flex", justifyContent:"space-between", padding:"9px 0", borderBottom:`1px solid ${C.border}`, fontSize:13.5 }}>
                            <span style={{ color:C.textSec, fontWeight:700 }}>{label}</span>
                            <span style={{ color:C.text, fontWeight:800 }}>{tot>0 ? `${win}／${tot}本（${Math.round(win/tot*100)}%）` : "記録なし"}</span>
                          </div>
                        ))}
                        <div style={{ display:"flex", justifyContent:"space-between", padding:"9px 0", fontSize:13.5 }}>
                          <span style={{ color:C.textSec, fontWeight:700 }}>ダブルフォルト</span>
                          <span style={{ color:C.text, fontWeight:800 }}>{pairAgg.serveDf}本</span>
                        </div>
                      </div>
                    </div>

                    {courseStats && courseStats.all > 0 && (
                      <div style={S.card}>
                        <div style={{ padding:14 }}>
                          <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:10 }}>🎯 コース傾向</div>

                          <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:7 }}>① 引っ張り / 流し</div>
                          <SplitBar pull={courseStats.pull} nagashi={courseStats.nagashi} total={courseStats.all} />

                          <div style={{ marginTop:16, paddingTop:14, borderTop:`1px solid ${C.border}` }}>
                            <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:8 }}>② フォア / バック別</div>
                            {courseStats.sides.filter(sd=>sd.total>0).map(sd => (
                              <div key={sd.side} style={{ marginBottom:12 }}>
                                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", fontSize:13.5, fontWeight:700, color:C.text, marginBottom:6 }}>
                                  <span>{sd.label}</span><span style={{ fontSize:13, fontWeight:400, color:C.textSec }}><b style={{ fontSize:15, fontWeight:800, color:C.text }}>{sd.total}</b>本</span>
                                </div>
                                <SplitBar pull={sd.pull} nagashi={sd.nagashi} total={sd.total} />
                              </div>
                            ))}
                          </div>

                          <div style={{ marginTop:16, paddingTop:14, borderTop:`1px solid ${C.border}` }}>
                            <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:10 }}>③ コース別の 決めた / ミス</div>
                            {courseStats.rows.map(r => {
                              const rate = r.total>0 ? Math.round(r.win/r.total*100) : 0;
                              return (
                                <div key={r.key} style={{ marginBottom:13 }}>
                                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", fontSize:13.5, fontWeight:700, color:C.text, marginBottom:6 }}>
                                    <span>{r.label}</span>
                                    {r.total>0
                                      ? <span style={{ fontSize:13, fontWeight:400, color:C.textSec }}>{r.total}本中 <b style={{ fontSize:14.5, fontWeight:800, color:rate<40?C.red:C.text }}>決定率 {rate}%</b></span>
                                      : <span style={{ fontSize:13, fontWeight:400, color:C.textSec }}>記録なし</span>}
                                  </div>
                                  {r.total>0 && (
                                    <div style={{ display:"flex", height:26, borderRadius:7, overflow:"hidden", background:"#eef0f3" }}>
                                      {r.win>0 && <div style={{ width:`${r.win/r.total*100}%`, background:C.accent, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13, fontWeight:800, color:C.white, whiteSpace:"nowrap", overflow:"hidden" }}>決めた {r.win}</div>}
                                      {r.err>0 && <div style={{ width:`${r.err/r.total*100}%`, background:C.red, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13, fontWeight:800, color:C.white, whiteSpace:"nowrap", overflow:"hidden" }}>ミス {r.err}</div>}
                                    </div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                          <div style={{ fontSize:12, color:"#8a92a0", marginTop:6, lineHeight:1.6 }}>
                            ※コースが入力された{courseStats.all}本をもとに集計しています。
                          </div>
                        </div>
                      </div>
                    )}

                    {flowStats && (
                      <div style={S.card}>
                        <div style={{ padding:14 }}>
                          <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:10 }}>📈 試合展開</div>
                          {[["1ゲーム目を取った試合", flowStats.firstWon],
                            ["1ゲーム目を落とした試合", flowStats.firstLost],
                            ["ファイナルゲームまでもつれた試合", flowStats.finalGame]].map(([label,v])=>(
                            <div key={label} style={{ display:"flex", justifyContent:"space-between", padding:"9px 0", borderBottom:`1px solid ${C.border}`, fontSize:13.5 }}>
                              <span style={{ color:C.textSec, fontWeight:700 }}>{label}</span>
                              <span style={{ color:C.text, fontWeight:800 }}>
                                {v.n>0 ? `${v.n}試合 → ${v.w}勝${v.n-v.w}敗` : "なし"}
                              </span>
                            </div>
                          ))}
                          <div style={{ display:"flex", justifyContent:"space-between", padding:"9px 0", fontSize:13.5 }}>
                            <span style={{ color:C.textSec, fontWeight:700 }}>ストレート勝ち</span>
                            <span style={{ color:C.text, fontWeight:800 }}>{flowStats.straight}試合</span>
                          </div>
                        </div>
                      </div>
                    )}
                  </>
                )}

                {/* ★一番下にも戻るボタンを置く（下まで読んだあと上まで戻らなくて済むように） */}
                {side === "opp" && (
                  <button
                    onClick={()=>{ setOppPairKey(""); window.scrollTo(0,0); }}
                    style={{ width:"100%", padding:15, marginTop:4, borderRadius:11, border:`1.5px solid ${C.border}`,
                      background:C.white, color:C.navy, fontSize:15, fontWeight:800, cursor:"pointer" }}
                  >← 相手ペアの一覧に戻る</button>
                )}
              </>
            )}
          </>
        )}
      </div>
      <NavBar active="stats" onNavigate={onNavigate} />
    </div>
  );
}

function PersonalAnalysisScreen({ onNavigate, onOpenPairAnalysis, onOpenTeamStats, onOpenMatch }) {
  // ★前回の分析結果（同じ選手なら、開いた瞬間にこれを表示し、裏で最新に差し替える）
  const restoredResultRef = useRef(readScreenCache("personalAnalysisResult"));
  const resultReqRef = useRef(0);
  useEffect(() => { perfLog("個人分析画面を表示開始"); }, []);
  // ※最初はtrueのままにする（選手が決まる前に「選手選択画面」へ飛ばないように。キャッシュがあれば直後に解除される）
  const [loading, setLoading] = useState(true);
  const [roster, setRoster] = useState([]);
  const [linkedPlayerName, setLinkedPlayerName] = useState(null);
  const [mySchoolName, setMySchoolName] = useState("");
  const [allMatches, setAllMatches] = useState([]); // 一覧用の軽量データ

  const [mode, setMode] = useState("results"); // results | wizardPlayer | scope
  // ★集計対象（期間・大会・試合数・対象試合）。端末に保存して次回も同じ条件から始める
  const [scope, setScope] = useState(loadAnalysisScope);
  const [seasonStart, setSeasonStart] = useState(null);
  const [seasonLabel, setSeasonLabel] = useState("");
  const [teamMatchIds, setTeamMatchIds] = useState(new Set());
  const [resultCapped, setResultCapped] = useState(0);
  const [selectedPlayer, setSelectedPlayer] = useState(null);
  const [selectedSchoolName, setSelectedSchoolName] = useState(""); // 空なら自チーム
  const [schoolPickerOpen, setSchoolPickerOpen] = useState(false);
  const [schoolSearch, setSchoolSearch] = useState("");
  const [teamSearch, setTeamSearch] = useState(""); // 選手検索キーワード

  const [selectSubTab, setSelectSubTab] = useState("all"); // period | tournament | individual | all
  const [periodStart, setPeriodStart] = useState("");
  const [periodEnd, setPeriodEnd] = useState("");
  const [selectedTournaments, setSelectedTournaments] = useState([]);
  const [selectedMatchIds, setSelectedMatchIds] = useState([]);

  // 期間タブのカレンダーUI用
  const [calFilterMode, setCalFilterMode] = useState("range"); // day | range | month
  const [calDay, setCalDay] = useState(null);
  const [calRangeStart, setCalRangeStart] = useState(null);
  const [calRangeEnd, setCalRangeEnd] = useState(null);
  const [calRangeStep, setCalRangeStep] = useState("start");
  const [calMonth, setCalMonth] = useState(null);
  const [calViewYear, setCalViewYear] = useState(new Date().getFullYear());
  const [calViewMonth, setCalViewMonth] = useState(new Date().getMonth());
  const [calMonthViewYear, setCalMonthViewYear] = useState(new Date().getFullYear());

  const [resultMatches, setResultMatches] = useState([]); // 詳細データ込みの試合（分析対象）
  const [resultLoading, setResultLoading] = useState(false);
  const [resultCondLabel, setResultCondLabel] = useState("");
  const [hasLoadedDefault, setHasLoadedDefault] = useState(false);
  const [autoPickNote, setAutoPickNote] = useState("");
  const [resultFilter, setResultFilter] = useState("all"); // ★勝敗フィルター：all | win | lose
  // ★得点・ミスの内訳の切り替え：play=プレイ別（ストローク/ボレー…） course=コース別（引っ張り/流し…）
  const [breakdownDim, setBreakdownDim] = useState("play");
  const [resultListOpen, setResultListOpen] = useState(false); // ★勝敗内訳一覧の開閉（初期は閉じた状態）
  // ★選手選択画面を開いた時点の「選手・学校」を覚えておく。
  //   学校を切り替えると選手が一旦未選択になるため、そのまま「←」（スマホの戻る）で戻ると
  //   選手名が空のまま結果画面に戻り、勝敗も0勝0敗になってしまっていた。
  //   選び直さずに戻ったときは、開いた時点の選手・学校に戻す。
  const wizardSnapRef = useRef(null);
  useEffect(() => {
    if (mode === "wizardPlayer") wizardSnapRef.current = { player: selectedPlayer, school: selectedSchoolName };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode]);
  function cancelWizard() {
    const snap = wizardSnapRef.current;
    setSchoolPickerOpen(false);
    if (snap?.player) {
      setSelectedPlayer(snap.player);
      setSelectedSchoolName(snap.school);
      setMode("results");
    } else {
      // まだ誰も選んでいない（結果画面に戻っても表示するものがない）ときはホームへ
      onNavigate && onNavigate("home");
    }
  }

  // ★画面を開くたびに全部を取り直して「読み込み中...」で待つのをやめ、
  //   前回開いたときの内容をすぐ表示してから、裏で最新に差し替える。
  //   （選手を選び直した後に裏の更新が届いても、選択が勝手に戻らないようにしている）
  const initializedRef = useRef(false);
  // ★対象試合（個人戦のみ／団体戦のみ）のしぼり込みに使う番手の試合IDも、土台のデータと一緒に取得する
  //   （以前は別々に取得しており、番手のIDが届く前に初回の集計が走ると、しぼり込みが効かないことがあった）
  const apply = useCallback(([p, rosterList, list, schools, teamIds], { fromCache = false } = {}) => {
    // ★覚えておいた内容からは「誰の分析か」が決まらないとき（プロフィールや選手マスターが取れていなかった等）は、
    //   それを使わずに最新の取得を待つ。以前はここで「未選択」のまま確定してしまい、選手選択画面が開いていた。
    if (fromCache && !initializedRef.current && !pickDefaultAnalysisPlayer(p, rosterList) && !loadLastAnalysisPlayer()) return;
    setRoster(rosterList);
    setAllMatches(list);
    if (teamIds) setTeamMatchIds(new Set(teamIds));
    let linked = null;
    if (p?.linked_player_id) {
      const found = (rosterList || []).find(r => r.id === p.linked_player_id);
      linked = found?.player_name ?? null;
      setLinkedPlayerName(linked);
    }
    if (p?.school_id) {
      const s = (schools || []).find(s => s.id === p.school_id);
      if (s) {
        setMySchoolName(s.name);
        // ★シーズン設定の起点日（分析の「◯◯以降」で使う）
        setSeasonStart(s.season_start_date || null);
        setSeasonLabel(s.season_start_label || "");
      }
    }
    if (!initializedRef.current) {
      initializedRef.current = true;
      // ★linked_player_idが選手マスターの再登録などで古いID（存在しないID）を指したままになっていると、
      //   紐づく選手が見つからず、以前は「ロースター先頭の選手」が勝手にデフォルト選択されてしまい、
      //   ログインした本人とは全く違う人の分析が表示される不具合があった。
      //   まずは自分のプロフィール名と選手マスターの名前が一致するものが無いか探し（自動復旧）、
      //   それでも見つからない場合は他の誰かを勝手に選ばず「未選択」のままにする。
      // ★紐づけから選手が決まらないときは、前回この画面で分析した選手を出す（毎回選手選択画面に戻らないように）
      const lastPick = loadLastAnalysisPlayer();
      const linkedPlayer = pickDefaultAnalysisPlayer(p, rosterList);
      const defaultPlayer = linkedPlayer || lastPick?.player || null;
      // ★誰の分析か決まらないときだけ、選手選択画面を案内する（選手の設定と同じタイミングで切り替える）
      if (!defaultPlayer) {
        setHasLoadedDefault(true);
        setMode("wizardPlayer");
        // ★調査用：自動で選手を決められなかった理由を、選択画面の下に小さく表示する
        setAutoPickNote(`自動選択できませんでした（${fromCache ? "保存データ" : "最新データ"}／プロフィール${p ? "あり" : "なし"}／紐づけ${p?.linked_player_id ? ((rosterList || []).some(r => r.id === p.linked_player_id) ? "あり・一覧にあり" : "あり・一覧に無し") : "なし"}／選手${rosterList?.length ?? 0}人／前回の選手${lastPick?.player ? "あり" : "なし"}）`);
      }
      if (!linkedPlayer && lastPick?.player && lastPick.school) setSelectedSchoolName(lastPick.school);
      perfLog(`前回の選手: ${lastPick?.player || "なし"}`);
      perfLog(`既定の選手: ${defaultPlayer || "なし"}（プロフィール${p ? "あり" : "なし"} / 紐づけID${p?.linked_player_id ? "あり" : "なし"} / 紐づけ先${p?.linked_player_id ? ((rosterList || []).some(r => r.id === p.linked_player_id) ? "選手マスターにあり" : "選手マスターに無し") : "-"} / 選手${rosterList?.length ?? 0}人）`);
      setSelectedPlayer(defaultPlayer || null);
      // ★前回の結果が同じ選手（自チーム）のものなら、集計を待たずにそのまま表示する
      const r = restoredResultRef.current;
      if (r && defaultPlayer && r.player === defaultPlayer && (r.school || "") === (linkedPlayer ? "" : (lastPick?.school || ""))) {
        setResultMatches(r.matches);
        setResultCondLabel(r.condLabel);
        setResultCapped(r.capped);
      } else {
        restoredResultRef.current = null;
      }
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    const cached = readScreenCache("personalAnalysis");
    perfLog(cached ? "土台データ: 覚えていた内容あり" : "土台データ: 覚えていた内容なし（取得を待つ）");
    if (cached) apply(cached, { fromCache: true }); // まず前回の内容を即表示（裏で最新化を続ける）
    (async () => {
      // ★以前は「プロフィール・選手マスター・全試合」を取得し終わってから、
      //   さらに学校一覧をもう1往復かけて取りに行っていた（その分まるまる待たされていた）。
      //   学校一覧は他の取得結果に依存しないので、最初から同時に取得する。
      const fresh = await perfTime("土台データの最新取得", () => Promise.all([
        getMyProfile(), getPlayerRoster(), getMatchesCached(), getSchools(),
        getTeamMatchMatchIds().then(ids => Array.from(ids)),
      ]));
      perfLog(`土台データ: 全試合${fresh[2]?.length ?? 0}件 / 選手${fresh[1]?.length ?? 0}人`);
      // ★プロフィールの取得が一時的に失敗する（通信・ログイン情報の更新中など）と「誰の分析か」が決まらず、
      //   選手選択画面が開いてしまっていた。決まらないときは、プロフィールと選手マスターを1回だけ取り直す。
      if (!pickDefaultAnalysisPlayer(fresh[0], fresh[1]) && !loadLastAnalysisPlayer()) {
        perfLog("既定の選手が決まらないため、プロフィールと選手マスターを取り直し");
        _profileCache = null;
        const [p2, r2] = await Promise.all([
          getMyProfile().catch(() => null),
          getPlayerRoster({ fresh: true }).catch(() => fresh[1]),
        ]);
        if (p2) fresh[0] = p2;
        if (r2) fresh[1] = r2;
      }
      writeScreenCache("personalAnalysis", fresh);
      apply(fresh);
    })();
  }, [apply]);

  const effectiveSchoolName = selectedSchoolName || mySchoolName;
  const isOwnSchool = effectiveSchoolName === mySchoolName;
  const ownRoster = useMemo(() => roster.filter(r => r.is_own_team !== false), [roster]);
  // ★以前は下の3つを毎回の再描画で計算し直していたため、
  //   検索欄に1文字入力する・カレンダーを1回タップするたびに全試合を何度も走査していた。
  //   元になるデータが変わったときだけ計算するようにする。
  // 選択中の学校に応じた選手候補（自チームなら選手マスター、それ以外は試合記録から拾った名前）
  const rosterForSchool = useMemo(() => isOwnSchool
    ? ownRoster.map(r => ({ id: r.id, player_name: r.player_name }))
    : Array.from(new Set(
        allMatches.flatMap(m => m.players.filter(p => p.club_name && p.club_name.trim() === effectiveSchoolName.trim()).map(p => p.player_name))
      )).map(name => ({ id: name, player_name: name })),
    [isOwnSchool, ownRoster, allMatches, effectiveSchoolName]);
  // 候補となる学校名（自チーム＋これまで対戦した相手校）
  const knownSchoolNames = useMemo(() => Array.from(new Set(
    [mySchoolName, ...allMatches.flatMap(m => m.players.map(p => p.club_name))].filter(Boolean)
  )), [mySchoolName, allMatches]);
  const playerMatches = useMemo(() => selectedPlayer
    ? allMatches.filter(m => countsAsFinished(m) && ownSideFor(m, selectedPlayer, effectiveSchoolName))
    : [],
    [allMatches, selectedPlayer, effectiveSchoolName]);

  async function loadResults(matchSummaries, condLabel, capped = 0, { silent = false } = {}) {
    // silent：前回の結果を表示したまま裏で差し替える（「集計中...」を出さない・フィルターも戻さない）
    if (!silent) {
      setResultLoading(true);
      setResultFilter("all");
    }
    setResultCondLabel(condLabel);
    setResultCapped(capped);
    const player = selectedPlayer, school = selectedSchoolName;
    const reqNo = ++resultReqRef.current;
    perfLog(`集計開始（${matchSummaries.length}試合${silent ? "・前回の結果を表示中" : ""}）`);
    const full = await getFullMatchesByIds(matchSummaries.map(m => m.id));
    // ★待っている間に別の条件で集計し直していたら、古い結果で上書きしない
    if (reqNo !== resultReqRef.current) return;
    full.sort((a, b) => {
      const d = new Date(a.match_date) - new Date(b.match_date);
      if (d !== 0) return d;
      return roundProgressRank(a.round) - roundProgressRank(b.round);
    });
    setResultMatches(full);
    setResultLoading(false);
    if (!silent) setMode("results");
    writeScreenCache("personalAnalysisResult", { player, school, condLabel, capped, matches: full });
    saveLastAnalysisPlayer(player, school);
  }

  // 初回表示：条件未設定なら「直近5試合」を自動で読み込む
  useEffect(() => {
    if (!loading && selectedPlayer && !hasLoadedDefault) {
      setHasLoadedDefault(true);
      const { list, capped } = applyScope(playerMatches, scope, { seasonStart, teamMatchIds });
      // ★前回の結果を表示済みなら、「集計中...」を出さずに裏で差し替える
      loadResults(list, scopeShortLabel(scope, seasonLabel), capped, { silent: !!restoredResultRef.current });
    }
    // ※「誰の分析か決まらないときに選手選択画面へ進む」判断は、ここではなく apply() の中で行う。
    //   以前はここで「読み込み完了なのに選手が未設定」を見て選択画面へ進めていたが、
    //   端末によっては「読み込み完了」と「選手の設定」が別々のタイミングで画面に反映され、
    //   その一瞬のすき間で、選手が決まっているのに選択画面へ進んでしまっていた（戻る矢印で結果が出るのはこのため）。
    // eslint-disable-next-line
  }, [loading, selectedPlayer]);

  // ★計測用：画面が描かれた時点を記録する（集計・描画の時間を含む）
  useEffect(() => {
    if (!PERF_ON) return;
    const label = loading ? "「読み込み中...」を表示" : resultLoading ? "「集計中...」を表示" : resultMatches.length > 0 ? `結果を表示（${resultMatches.length}試合）` : `画面を表示（${mode}）`;
    requestAnimationFrame(() => perfLog(label));
  }, [loading, resultLoading, resultMatches, mode]);
  if (loading) {
    return (
      <div style={{ minHeight:"100vh", background:C.gray, fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
        <div style={{ ...S.hdr, color:C.white }}>
          <div style={{ fontSize:20, fontWeight:800 }}>分析</div>
        </div>
        <div style={{ padding:14 }}>
          <AnalysisTabs current="personal" />
          <div style={{ padding:40, textAlign:"center", color:C.textSec }}>読み込み中...</div>
        </div>
      </div>
    );
  }

  // ============ ① 選手選択 ============
  if (mode === "wizardPlayer") {
    // 学校を変更する（検索）画面
    if (schoolPickerOpen) {
      const filteredSchools = knownSchoolNames.filter(n => !schoolSearch.trim() || n.toLowerCase().includes(schoolSearch.trim().toLowerCase()));
      return (
        <div style={{ minHeight:"100vh", background:C.gray, fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
          <div style={{ ...S.hdr, color:C.white }}>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <span style={{ cursor:"pointer", fontSize:18 }} onClick={()=>setSchoolPickerOpen(false)}>←</span>
              <div>
                <div style={{ fontSize:20, fontWeight:800 }}>分析</div>
                <div style={{ fontSize:11, color:"#b9c2d6" }}>チームを選択</div>
              </div>
            </div>
          </div>
          <div style={{ padding:14 }}>
            <div style={{ display:"flex", alignItems:"center", background:C.white, border:`1px solid ${C.navy}`, borderRadius:10, padding:"9px 12px", marginBottom:10, fontSize:13, gap:6 }}>
              🔍<input value={schoolSearch} onChange={e=>setSchoolSearch(e.target.value)} placeholder="学校名・チーム名で検索" style={{ flex:1, border:"none", outline:"none", fontSize:13, background:"transparent" }} autoFocus />
            </div>
            <div style={S.card}>
              {filteredSchools.length===0 && <div style={{ padding:16, textAlign:"center", color:C.textSec, fontSize:12 }}>見つかりません</div>}
              {filteredSchools.map(name => (
                <div key={name} onClick={()=>{
                  setSelectedSchoolName(name === mySchoolName ? "" : name);
                  setSelectedPlayer(null);
                  setSchoolSearch(""); setSchoolPickerOpen(false);
                }} style={{ display:"flex", alignItems:"center", gap:8, padding:"12px 14px", borderBottom:`1px solid ${C.border}`, cursor:"pointer" }}>
                  <div style={{ fontSize:13, fontWeight:700, color:C.text, flex:1 }}>{name}</div>
                  {name===mySchoolName && <span style={{ fontSize:9.5,color:C.accent,background:C.accentL,padding:"2px 7px",borderRadius:6 }}>自チーム</span>}
                </div>
              ))}
            </div>
            <div style={{ fontSize:11, color:C.textSec, padding:"6px 4px" }}>これまで対戦した相手チームも候補に出てきます。選ぶとその学校の選手一覧に切り替わります。</div>
          </div>
        </div>
      );
    }

    const filteredRoster = rosterForSchool.filter(p => !teamSearch.trim() || p.player_name.toLowerCase().includes(teamSearch.trim().toLowerCase()));
    return (
      <div style={{ minHeight:"100vh", background:C.gray, paddingBottom:80, fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
        <div style={{ ...S.hdr, color:C.white }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
            <span style={{ cursor:"pointer", fontSize:18 }} onClick={cancelWizard}>←</span>
            <div>
              <div style={{ fontSize:20, fontWeight:800 }}>分析</div>
              <div style={{ fontSize:11, color:"#b9c2d6" }}>選手を選択</div>
            </div>
          </div>
        </div>
        <div style={{ padding:14 }}>
          {/* ★「学校やチームはどこで切り替えるの？」と気づかれにくかったため、
               色付きの背景＋太い枠で囲み、切り替えられることを文章でも示す */}
          <div style={{ fontSize:14, fontWeight:800, color:C.text, marginBottom:7 }}>🏫 チーム・学校<span style={{ fontSize:13, fontWeight:700, color:"#5a6478", marginLeft:8 }}>他校の選手もここで切り替え</span></div>
          <div onClick={()=>setSchoolPickerOpen(true)} style={{ background:"#eaf1ff", border:`2px solid ${C.navy}`, borderRadius:12, marginBottom:12, padding:"12px 14px", display:"flex", alignItems:"center", justifyContent:"space-between", cursor:"pointer" }}>
            <div style={{ minWidth:0 }}>
              <div style={{ fontSize:18, fontWeight:800, color:C.navy }}>{effectiveSchoolName || "（未設定）"}</div>
              <div style={{ fontSize:13, color:"#5a6478", marginTop:2 }}>{isOwnSchool ? "自分の所属チーム（デフォルト）" : "相手チーム"}</div>
            </div>
            {/* ★押せることが分かるよう、文字だけでなくボタンの形にする */}
            <div style={{ flexShrink:0, marginLeft:10, fontSize:14, fontWeight:800, color:C.white, background:C.navy, borderRadius:20, padding:"8px 14px", whiteSpace:"nowrap" }}>変更する ›</div>
          </div>

          {/* ★「チーム・学校」と区別できるよう、選手の一覧にも見出しを付ける */}
          <div style={{ fontSize:14, fontWeight:800, color:C.text, margin:"18px 0 7px" }}>👤 選手一覧<span style={{ fontSize:13, fontWeight:700, color:"#5a6478", marginLeft:8 }}>分析する選手を選んでください</span></div>
          <div style={{ display:"flex", alignItems:"center", background:C.white, border:`1px solid ${C.border}`, borderRadius:10, padding:"9px 12px", marginBottom:10, fontSize:13, gap:6 }}>
            🔍<input value={teamSearch} onChange={e=>setTeamSearch(e.target.value)} placeholder="選手名で検索" style={{ flex:1, border:"none", outline:"none", fontSize:13, background:"transparent" }} />
          </div>
          <div style={S.card}>
            {filteredRoster.length===0 && <div style={{ padding:16, textAlign:"center", color:C.textSec, fontSize:12 }}>選手が見つかりません</div>}
            {filteredRoster.map(p => (
              <div key={p.id} onClick={()=>{ setSelectedPlayer(p.player_name); saveLastAnalysisPlayer(p.player_name, selectedSchoolName); }}
                style={{ display:"flex", alignItems:"center", gap:10, padding:"12px 14px", borderBottom:`1px solid ${C.border}`, cursor:"pointer", background:p.player_name===selectedPlayer?C.accentL:"transparent" }}>
                <div style={{ width:34,height:34,borderRadius:"50%",background:C.accentL,color:C.accent,fontWeight:800,fontSize:13,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0 }}>{p.player_name[0]}</div>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:13.5, fontWeight:700, color:C.text }}>{p.player_name}{p.player_name===linkedPlayerName && <span style={{ fontSize:9.5,color:C.purple,background:"#eef0fe",padding:"2px 7px",borderRadius:6,marginLeft:6 }}>自分</span>}</div>
                  <div style={{ fontSize:10.5, color:C.textSec, marginTop:1 }}>{effectiveSchoolName}</div>
                </div>
                <div style={{ width:19,height:19,borderRadius:"50%",border:`2px solid ${p.player_name===selectedPlayer?C.accent:C.border}`,background:p.player_name===selectedPlayer?C.accent:"transparent" }}/>
              </div>
            ))}
          </div>
        </div>
        <div style={{ position:"fixed", left:0, right:0, bottom:0, padding:14, background:C.gray, borderTop:`1px solid ${C.border}` }}>
          <button
            disabled={!selectedPlayer}
            onClick={()=>setMode("scope")}
            style={{ width:"100%", padding:13, borderRadius:11, border:"none", fontSize:14, fontWeight:800, cursor:selectedPlayer?"pointer":"default",
              background: selectedPlayer ? C.navy : "#d5dae2", color:"#fff" }}
          >{selectedPlayer ? "次へ →" : "選手を選んでください"}</button>
          {autoPickNote && <div style={{ fontSize:10, color:"#9aa3b5", marginTop:6, textAlign:"center" }}>{autoPickNote}</div>}
        </div>
      </div>
    );
  }

  // ============ ② 集計対象の設定（期間・大会・試合数・対象試合を1画面で） ============
  if (mode === "scope") {
    return (
      <ScopeSheet
        matches={playerMatches}
        scope={scope}
        seasonStart={seasonStart}
        seasonLabel={seasonLabel}
        teamMatchIds={teamMatchIds}
        playerLabel={selectedPlayer || "未選択"}
        onChangePlayer={()=>setMode("wizardPlayer")}
        onClose={()=>setMode("results")}
        onApply={(next, remember)=>{
          setScope(next);
          if (remember) { try { localStorage.setItem("analysisScope", JSON.stringify(next)); } catch {} }
          const { list, capped } = applyScope(playerMatches, next, { seasonStart, teamMatchIds });
          loadResults(list, scopeShortLabel(next, seasonLabel), capped);
        }}
      />
    );
  }

  // ============ （旧）試合選択ウィザード ============
  if (mode === "wizardMatchesLegacy") {
    const tournamentNames = Array.from(new Set(playerMatches.map(m=>m.tournament_name).filter(Boolean)));
    let candidateMatches = playerMatches;
    if (selectSubTab === "period" && (periodStart || periodEnd)) {
      candidateMatches = candidateMatches.filter(m => {
        if (!m.match_date) return false;
        if (periodStart && m.match_date < periodStart) return false;
        if (periodEnd && m.match_date > periodEnd) return false;
        return true;
      });
    } else if (selectSubTab === "tournament" && selectedTournaments.length > 0) {
      candidateMatches = candidateMatches.filter(m => selectedTournaments.includes(m.tournament_name));
    } else if (selectSubTab === "individual") {
      candidateMatches = candidateMatches.filter(m => selectedMatchIds.includes(m.id));
    }
    const sortedForList = [...playerMatches].sort((a,b)=> new Date(b.match_date)-new Date(a.match_date));

    const condLabelFor = () => {
      if (selectSubTab === "all") return "すべて";
      if (selectSubTab === "period") return (periodStart||periodEnd) ? `${periodStart||"…"}〜${periodEnd||"…"}` : "期間未指定";
      if (selectSubTab === "tournament") return selectedTournaments.length ? selectedTournaments.join("・") : "大会未選択";
      return `個別選択（${selectedMatchIds.length}件）`;
    };

    return (
      <div style={{ minHeight:"100vh", background:C.gray, fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
        <div style={{ ...S.hdr, color:C.white }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
            <span style={{ cursor:"pointer", fontSize:18 }} onClick={()=>setMode("wizardPlayer")}>←</span>
            <div>
              <div style={{ fontSize:20, fontWeight:800 }}>分析</div>
              <div style={{ fontSize:11, color:"#b9c2d6" }}>{selectedPlayer}さんの試合を選択</div>
            </div>
          </div>
        </div>
        <div style={{ padding:14, paddingBottom:90 }}>
          <div style={{ display:"flex", background:C.white, border:`1px solid ${C.border}`, borderRadius:10, padding:3, marginBottom:12 }}>
            {[["all","すべて"],["period","期間"],["tournament","大会"],["individual","個別"]].map(([v,l])=>(
              <div key={v} onClick={()=>setSelectSubTab(v)} style={{ flex:1, textAlign:"center", fontSize:11.5, fontWeight:700, padding:"8px 2px", borderRadius:8, cursor:"pointer", background:selectSubTab===v?C.navy:"transparent", color:selectSubTab===v?"#fff":C.textSec }}>{l}</div>
            ))}
          </div>

          {selectSubTab === "period" && (() => {
            const daysInMonth = new Date(calViewYear, calViewMonth+1, 0).getDate();
            const firstDow = new Date(calViewYear, calViewMonth, 1).getDay();
            const todayIso = today();
            const padMonth = (m) => String(m+1).padStart(2,"0");
            const toIso = (d) => `${calViewYear}-${padMonth(calViewMonth)}-${String(d).padStart(2,"0")}`;
            const handleDayClick = (d) => {
              const iso = toIso(d);
              if (calFilterMode === "day") {
                setCalDay(iso); setPeriodStart(iso); setPeriodEnd(iso);
              } else if (calFilterMode === "range") {
                if (calRangeStep === "start") {
                  setCalRangeStart(iso); setCalRangeEnd(null); setCalRangeStep("end");
                } else {
                  if (iso < calRangeStart) { setCalRangeStart(iso); setCalRangeStep("end"); }
                  else { setCalRangeEnd(iso); setCalRangeStep("start"); setPeriodStart(calRangeStart); setPeriodEnd(iso); }
                }
              }
            };
            const getDayClass = (iso) => {
              if (calFilterMode === "day") return iso === calDay ? "sel" : "";
              if (calFilterMode === "range") {
                if (iso === calRangeStart) return "rs";
                if (iso === calRangeEnd) return "re";
                if (calRangeStart && calRangeEnd && iso > calRangeStart && iso < calRangeEnd) return "ir";
              }
              return "";
            };
            const DOW = ["日","月","火","水","木","金","土"];
            return (
              <div style={{ background:C.white, borderRadius:14, border:`1.5px solid ${C.border}`, overflow:"hidden", marginBottom:12 }}>
                <div style={{ display:"flex", borderBottom:`1.5px solid ${C.border}` }}>
                  {[["day","1日指定"],["range","期間指定"],["month","月指定"]].map(([v,l])=>(
                    <button key={v} onClick={()=>{ setCalFilterMode(v); if(v==="range"){setCalRangeStart(null);setCalRangeEnd(null);setCalRangeStep("start");} }} style={{ flex:1, padding:"10px 4px", textAlign:"center", fontSize:13, fontWeight:700, color:calFilterMode===v?C.accent:C.textSec, border:"none", background:"none", cursor:"pointer", borderBottom:calFilterMode===v?`2px solid ${C.accent}`:"2px solid transparent" }}>{l}</button>
                  ))}
                </div>
                <div style={{ padding:"12px 14px 0" }}>
                  {(calFilterMode==="day"||calFilterMode==="range") && (<>
                    {calFilterMode==="range" && (
                      <p style={{ fontSize:11, color:C.textSec, textAlign:"center", marginBottom:8 }}>
                        {calRangeStep==="start" ? <>開始日 → 終了日の順にタップ（<b style={{color:C.accent}}>開始日</b>を選択中）</> : <>開始日 → 終了日の順にタップ（<b style={{color:C.accent}}>終了日</b>を選択中）</>}
                      </p>
                    )}
                    <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:10 }}>
                      <button onClick={()=>{ if(calViewMonth===0){setCalViewMonth(11);setCalViewYear(y=>y-1);}else setCalViewMonth(m=>m-1); }} style={{ background:"none", border:"none", fontSize:20, cursor:"pointer", color:C.navy, padding:"4px 8px" }}>‹</button>
                      <span style={{ fontSize:15, fontWeight:800, color:C.navy }}>{calViewYear}年{calViewMonth+1}月</span>
                      <button onClick={()=>{ if(calViewMonth===11){setCalViewMonth(0);setCalViewYear(y=>y+1);}else setCalViewMonth(m=>m+1); }} style={{ background:"none", border:"none", fontSize:20, cursor:"pointer", color:C.navy, padding:"4px 8px" }}>›</button>
                    </div>
                    <div style={{ display:"grid", gridTemplateColumns:"repeat(7,1fr)", gap:2, marginBottom:10 }}>
                      {DOW.map((d,i)=>(
                        <div key={d} style={{ textAlign:"center", fontSize:11, fontWeight:700, color:i===0?"#e53935":i===6?"#1565c0":C.textSec, padding:"3px 0" }}>{d}</div>
                      ))}
                      {Array.from({length:firstDow}).map((_,i)=><div key={"e"+i}/>)}
                      {Array.from({length:daysInMonth}).map((_,i)=>{
                        const d=i+1; const iso=toIso(d); const dc=getDayClass(iso);
                        const dow=(firstDow+i)%7;
                        const isToday=iso===todayIso;
                        const isSel=dc==="sel"||dc==="rs"||dc==="re";
                        const isInRange=dc==="ir";
                        return (
                          <button key={d} onClick={()=>handleDayClick(d)} style={{
                            textAlign:"center", fontSize:13, padding:"7px 2px", borderRadius: dc==="rs"?"8px 0 0 8px":dc==="re"?"0 8px 8px 0":"8px",
                            cursor:"pointer", fontWeight:600, border:"none",
                            background:isSel?C.accent:isInRange?C.accentL:"transparent",
                            color:isSel?"#fff":isInRange?"#00874f":dow===0?"#e53935":dow===6?"#1565c0":isToday?C.accent:C.text,
                            outline:isToday&&!isSel?`1.5px solid ${C.accent}`:"none",
                          }}>{d}</button>
                        );
                      })}
                    </div>
                  </>)}
                  {calFilterMode==="month" && (<>
                    <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:16, marginBottom:10 }}>
                      <button onClick={()=>setCalMonthViewYear(y=>y-1)} style={{ background:"none", border:"none", fontSize:18, cursor:"pointer", color:C.navy }}>‹</button>
                      <span style={{ fontSize:15, fontWeight:800, color:C.navy }}>{calMonthViewYear}年</span>
                      <button onClick={()=>setCalMonthViewYear(y=>y+1)} style={{ background:"none", border:"none", fontSize:18, cursor:"pointer", color:C.navy }}>›</button>
                    </div>
                    <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:10 }}>
                      {Array.from({length:12}).map((_,i)=>{
                        const mStr = `${calMonthViewYear}-${String(i+1).padStart(2,"0")}`;
                        const isSel = calMonth===mStr;
                        const hasData = playerMatches.some(m=>(m.match_date||"").slice(0,7)===mStr);
                        return (
                          <button key={i} onClick={()=>{
                            setCalMonth(mStr);
                            const lastDay = new Date(calMonthViewYear, i+1, 0).getDate();
                            setPeriodStart(`${mStr}-01`); setPeriodEnd(`${mStr}-${String(lastDay).padStart(2,"0")}`);
                          }} style={{ padding:"10px 4px", textAlign:"center", borderRadius:8, cursor:"pointer", fontSize:14, fontWeight:700, border: isSel?`1.5px solid ${C.accent}`:hasData?`1.5px solid ${C.accent}`:`1.5px solid ${C.border}`, background:isSel?C.accent:"#fff", color:isSel?"#fff":hasData?"#00874f":C.text }}>{i+1}月</button>
                        );
                      })}
                    </div>
                    <p style={{ fontSize:11, color:C.textSec, textAlign:"center", marginBottom:10 }}>枠線あり＝試合データあり</p>
                  </>)}
                </div>
                {(periodStart || periodEnd) && (
                  <div style={{ padding:"0 14px 14px" }}>
                    <button onClick={()=>{ setPeriodStart(""); setPeriodEnd(""); setCalDay(null); setCalRangeStart(null); setCalRangeEnd(null); setCalMonth(null); }} style={{ width:"100%", padding:"9px", background:C.gray, color:C.textSec, border:"none", borderRadius:10, fontSize:12.5, fontWeight:700, cursor:"pointer" }}>選択をクリア（{periodStart||"…"} 〜 {periodEnd||"…"}）</button>
                  </div>
                )}
              </div>
            );
          })()}

          {selectSubTab === "tournament" && (
            <div style={S.card}>
              <div style={{ padding:"6px 4px" }}>
                {tournamentNames.length===0 && <div style={{ padding:16, textAlign:"center", color:C.textSec, fontSize:12 }}>対象の大会がありません</div>}
                {tournamentNames.map(name => (
                  <div key={name} onClick={()=>setSelectedTournaments(prev => prev.includes(name) ? prev.filter(n=>n!==name) : [...prev, name])}
                    style={{ display:"flex", alignItems:"center", gap:10, padding:"10px 12px", borderBottom:`1px solid ${C.border}`, cursor:"pointer" }}>
                    <div style={{ width:18,height:18,borderRadius:5,border:`2px solid ${selectedTournaments.includes(name)?C.accent:C.border}`, background:selectedTournaments.includes(name)?C.accent:"transparent", color:"#fff", fontSize:11, display:"flex",alignItems:"center",justifyContent:"center" }}>{selectedTournaments.includes(name)?"✓":""}</div>
                    <div style={{ fontSize:12.5, fontWeight:600 }}>{name}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {selectSubTab === "individual" && (
            <div style={S.card}>
              <div style={{ padding:"6px 4px", maxHeight:360, overflowY:"auto" }}>
                {sortedForList.length===0 && <div style={{ padding:16, textAlign:"center", color:C.textSec, fontSize:12 }}>対象の試合がありません</div>}
                {sortedForList.map(m => {
                  const win = winForPlayer(m, selectedPlayer, effectiveSchoolName);
                  const oppSide = m.players.find(p=>p.player_name!==selectedPlayer && p.team!==(ownSideFor(m,selectedPlayer,effectiveSchoolName)));
                  const on = selectedMatchIds.includes(m.id);
                  return (
                    <div key={m.id} onClick={()=>setSelectedMatchIds(prev => on ? prev.filter(id=>id!==m.id) : [...prev, m.id])}
                      style={{ display:"flex", alignItems:"center", gap:10, padding:"10px 4px", borderBottom:`1px solid ${C.border}`, cursor:"pointer" }}>
                      <div style={{ width:18,height:18,borderRadius:5,border:`2px solid ${on?C.accent:C.border}`, background:on?C.accent:"transparent", color:"#fff", fontSize:11, display:"flex",alignItems:"center",justifyContent:"center", flexShrink:0 }}>{on?"✓":""}</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontSize:10, color:C.textSec }}>{fmtDate(m.match_date)}・{m.tournament_name}</div>
                        <div style={{ fontSize:12, fontWeight:700, color:C.text, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>vs {oppSide?.club_name || ""} {m.players.filter(p=>p.team!==ownSideFor(m,selectedPlayer,effectiveSchoolName)).map(p=>p.player_name).join("/")}</div>
                      </div>
                      <div style={{ fontSize:11, fontWeight:800, padding:"2px 8px", borderRadius:6, color:win?C.accent:C.red, background:win?C.accentL:C.redL, flexShrink:0 }}>{win?"勝ち":"負け"}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {selectSubTab === "all" && (
            <div style={{ ...S.card, padding:"12px 14px" }}>
              <div style={{ fontSize:12, color:C.textSec }}>選手が出場したすべての試合が対象になります</div>
            </div>
          )}

          <div style={{ ...S.card, padding:"12px 14px" }}>
            <div style={{ fontSize:12, color:C.textSec }}>この条件に一致する試合</div>
            <div style={{ fontSize:20, fontWeight:800, color:C.navy, marginTop:2 }}>{candidateMatches.length}試合</div>
          </div>

          <button style={S.btn(`linear-gradient(135deg,${C.accent},#00a066)`)} disabled={candidateMatches.length===0 || resultLoading}
            onClick={()=>loadResults(candidateMatches, condLabelFor())}>
            {resultLoading ? "読み込み中..." : `この${candidateMatches.length}試合を分析する →`}
          </button>
        </div>
      </div>
    );
  }

  // ============ ③ 分析結果（デフォルト表示もここ） ============
  const wonMatches = resultMatches.filter(m => winForPlayer(m, selectedPlayer, effectiveSchoolName) === true);
  const lostMatches = resultMatches.filter(m => winForPlayer(m, selectedPlayer, effectiveSchoolName) === false);
  const wonRates = keyRatesFromAgg(aggregatePlayerStats(wonMatches, selectedPlayer, effectiveSchoolName));
  const lostRates = keyRatesFromAgg(aggregatePlayerStats(lostMatches, selectedPlayer, effectiveSchoolName));

  // ★勝敗フィルター：すべて／勝った試合／負けた試合で下の集計を絞り込む
  const displayedMatches = resultFilter==="win" ? wonMatches : resultFilter==="lose" ? lostMatches : resultMatches;
  // ★一覧表示用：新しい試合を上にする。同じ日の試合は、あとに記録された試合（元の並びで後ろ）を上にする。
  const newestFirst = (list) => list
    .map((m,i)=>({ m, i }))
    .sort((x,y)=> (new Date(y.m.match_date) - new Date(x.m.match_date)) || (y.i - x.i))
    .map(x=>x.m);
  const displayedMatchesNewest = newestFirst(displayedMatches);

  const agg = aggregatePlayerStats(displayedMatches, selectedPlayer, effectiveSchoolName);
  const topPlaysWin = Object.entries(agg.playsWin).sort((a,b)=>b[1]-a[1]).slice(0,4);
  const topPlaysErr = Object.entries(agg.playsErr).sort((a,b)=>b[1]-a[1]).slice(0,4);
  const maxPlayCount = Math.max(1, ...topPlaysWin.map(x=>x[1]), ...topPlaysErr.map(x=>x[1]));

  // ★ミスの傾向（ネット／オーバー／チップ／サイドアウト、フォア／バック、多い組み合わせ）
  //   ミスの種類は入力が任意なので、母数は「種類まで入力されたミスの件数」を使う。
  const missTypeRows = MISS_TYPES
    .map(mt => [mt.label, agg.missTypes?.[mt.key] ?? 0])
    .filter(([,n]) => n > 0);
  const missSideRows = SIDE_TYPES
    .map(sd => [sd.label, agg.sideErr?.[sd.key] ?? 0])
    .filter(([,n]) => n > 0);
  const missSideTotal = missSideRows.reduce((a,[,n]) => a + n, 0);
  const topMissCombos = Object.entries(agg.missCombos ?? {}).sort((a,b)=>b[1]-a[1]).slice(0,3);

  // ★コース分析（① 引っ張り/流し → ② フォア/バック別 → ③ コース別の決めた/ミス）
  const courseStats = buildCourseStats(agg);
  const hasMissDetail = (agg.missTyped ?? 0) > 0 || missSideTotal > 0;

  // ★サーブ分析（集計）：1st/2nd/DFの本数と、それぞれのサーブ時の得点率
  const serveStats = (() => {
    const total = agg.serveTotal ?? 0;
    const s1 = agg.serve1st ?? 0, s2 = agg.serve2nd ?? 0, df = agg.serveDf ?? 0;
    const s1Win = agg.serve1stWin ?? 0, s2Win = agg.serve2ndWin ?? 0;
    return { total, s1, s2, df, s1Win, s2Win };
  })();

  // ミスの傾向カードで使う1行分の横棒
  const MissRow = ({ label, count, total, max, color }) => (
    <div style={{ display:"flex", alignItems:"center", fontSize:12, padding:"5px 0" }}>
      <div style={{ width:76, color:C.text, fontWeight:700 }}>{label}</div>
      <div style={{ flex:1, height:8, background:"#eef0f3", borderRadius:4, margin:"0 8px", overflow:"hidden" }}>
        <div style={{ height:"100%", width:`${max>0?count/max*100:0}%`, background:color, borderRadius:4 }}/>
      </div>
      <div style={{ width:60, textAlign:"right", fontWeight:700, color:C.navy }}>
        {count}回 {total>0?Math.round(count/total*100):0}%
      </div>
    </div>
  );

  // ★成長の推移：集計対象の試合を1試合ずつ集計し、1st/2ndサーブ得点率の変化を並べる。
  //   試合数が多いと棒が細くなりすぎるため、新しい方から最大10試合だけを対象にする。
  const TREND_MAX = 10;
  const serveTrend = (() => {
    const src = displayedMatches;
    if (!src || src.length < 2) return null;
    // ★同じ日に何試合もある大会では日付だけでは順番が決まらないため、日付→回戦の順で並べる
    const ordered = [...src].sort((a,b) => {
      const d = new Date(a.match_date) - new Date(b.match_date);
      if (d !== 0) return d;
      return roundProgressRank(a.round) - roundProgressRank(b.round);
    });
    const target = ordered.slice(-TREND_MAX);
    // ★同じ日に何試合もあるので、その日の何試合目かを番号で表す（回戦名は長すぎて入らない）
    const dayCount = {};
    const rows = target.map(m => {
      const d = m.match_date || "";
      dayCount[d] = (dayCount[d] ?? 0) + 1;
      const a = aggregatePlayerStats([m], selectedPlayer, effectiveSchoolName);
      const s1 = a.serve1st ?? 0, s2 = a.serve2nd ?? 0;
      return {
        id: m.id,
        date: d,
        no: dayCount[d],
        round: m.round || "",
        r1: s1 > 0 ? Math.round((a.serve1stWin ?? 0) / s1 * 100) : null,
        r2: s2 > 0 ? Math.round((a.serve2ndWin ?? 0) / s2 * 100) : null,
      };
    });
    // ★データが1試合分しかないと「推移」にならないので、2試合以上ある指標だけ出す
    const has1 = rows.filter(r => r.r1 !== null).length >= 2;
    const has2 = rows.filter(r => r.r2 !== null).length >= 2;
    if (!has1 && !has2) return null;
    return { rows, has1, has2, omitted: src.length - target.length };
  })();

  // 推移カード1枚分（棒グラフ）
  const TrendCard = ({ title, pick, color }) => (
    <div style={S.card}>
      <div style={{ padding:14 }}>
        <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:2 }}>{title}</div>
        <div style={{ fontSize:12.5, color:C.textSec, marginBottom:6 }}>← 古い　新しい →（棒をタップすると試合へ）</div>
        <div style={{ display:"flex", alignItems:"flex-end", gap:6, height:120, paddingTop:20 }}>
          {serveTrend.rows.map(r => {
            const v = pick(r);
            return (
              <div key={r.id} onClick={()=>onOpenMatch && onOpenMatch(r.id)}
                style={{ flex:"1 1 0", minWidth:0, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"flex-end", height:"100%", cursor:"pointer" }}>
                <div style={{ fontSize:13.5, fontWeight:800, color:v===null?C.textSec:C.text, marginBottom:4, whiteSpace:"nowrap" }}>{v===null?"—":`${v}%`}</div>
                <div style={{ width:"100%", height:`${v===null?2:Math.max(v,3)}%`, background:v===null?"#e3e7ee":color, borderRadius:"5px 5px 0 0" }}/>
              </div>
            );
          })}
        </div>
        <div style={{ display:"flex", gap:6, marginTop:6 }}>
          {serveTrend.rows.map(r => (
            <div key={r.id} style={{ flex:"1 1 0", minWidth:0, textAlign:"center" }}>
              <div style={{ fontSize:14, fontWeight:800, color:C.text }}>{r.no}</div>
              <div style={{ fontSize:11.5, color:C.textSec }}>
                {r.date ? `${Number(r.date.slice(5,7))}/${Number(r.date.slice(8,10))}` : ""}
              </div>
            </div>
          ))}
        </div>
        <div style={{ fontSize:12, color:"#8a92a0", marginTop:8, lineHeight:1.6 }}>
          数字はその日の何試合目かを表します。「—」はサーブの記録が無い試合です。
        </div>
      </div>
    </div>
  );

  // ★レシーブミス率は算出方法が複雑で誤差が出やすいため、比較表からは外す（内部計算・keyRatesFromAggは維持）
  const metricLabel = { serveRate:"1stサーブ成功率", decisionRate:"決定率" };

  return (
    <div style={{ minHeight:"100vh", background:C.gray, paddingBottom:70, fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
      <div style={{ ...S.hdr, color:C.white }}>
        <div style={{ fontSize:20, fontWeight:800 }}>分析</div>
      </div>
      <div style={{ padding:14 }}>
        {/* ★個人／ペア／チームのタブ。ペアは未実装のため準備中の案内を出す */}
        <AnalysisTabs current="personal" onPair={()=>onOpenPairAnalysis && onOpenPairAnalysis()} onTeam={onOpenTeamStats} />

        <div
          onClick={()=>setMode("scope")}
          style={{ background:C.navy, color:"#fff", borderRadius:14, padding:14, marginBottom:12, display:"flex", alignItems:"center", justifyContent:"space-between", cursor:"pointer" }}
        >
          <div>
            <div style={{ fontSize:12.5, color:"#c6cee0", marginBottom:5 }}>{resultCondLabel}</div>
            <div style={{ fontSize:23, fontWeight:900, lineHeight:1.25 }}>{selectedPlayer}</div>
            <div style={{ fontSize:14, color:"#d5dbe8", fontWeight:700, marginTop:3 }}>
              {resultMatches.length}試合
              {resultMatches.length>0 && `（${(resultMatches[0].match_date||"").replace(/-/g,"/")} 〜 ${(resultMatches[resultMatches.length-1].match_date||"").replace(/-/g,"/")}）`}
            </div>
          </div>
          <div style={{ fontSize:13, fontWeight:700, color:"#c6cee0", display:"flex", alignItems:"center", gap:3, flexShrink:0, marginLeft:10 }}>🔧 変更 ›</div>
        </div>

        {resultCapped > 0 && (
          <div style={{ background:"#fff4e5", border:"1px solid #f5c979", borderRadius:10, padding:12, fontSize:13, fontWeight:700, color:"#8a5a00", lineHeight:1.7, marginBottom:12 }}>
            ⚠️ 該当する試合が{resultMatches.length + resultCapped}件ありますが、新しい{SCOPE_MAX}試合を対象にしています。<br/>
            それ以前も見たい場合は、期間や大会でしぼってください。
          </div>
        )}

        {/* ★戦績カード（勝敗の○×一覧） */}
        {resultMatches.length>0 && (
          <div style={S.card}>
            <div style={{ padding:14 }}>
              <div style={{ fontSize:13, fontWeight:800, color:C.navy, marginBottom:10 }}>🏅 戦績</div>
              <div>
                <span style={{ fontSize:24, fontWeight:900, color:C.text }}>{wonMatches.length}</span>
                <span style={{ fontSize:14, color:C.textSec }}>勝</span>
                <span style={{ fontSize:24, fontWeight:900, color:C.text, marginLeft:4 }}>{lostMatches.length}</span>
                <span style={{ fontSize:14, color:C.textSec }}>敗</span>
              </div>
              <div style={{ fontSize:13, color:C.textSec, marginTop:2 }}>勝率{resultMatches.length>0?Math.round(wonMatches.length/resultMatches.length*100):0}%（{resultCondLabel}）</div>
              <div style={{ display:"flex", gap:10, marginTop:10, flexWrap:"wrap" }}>
                {resultMatches.map(m=>{
                  const w = winForPlayer(m, selectedPlayer, effectiveSchoolName);
                  return <span key={m.id} style={{ fontSize:20, fontWeight:900, color:C.text, lineHeight:1 }}>{w?"○":"×"}</span>;
                })}
              </div>
            </div>
          </div>
        )}

        {/* ★勝敗フィルター */}
        {resultMatches.length>0 && (
          <div style={{ display:"flex", gap:6, marginBottom:12 }}>
            {[["all",`すべて（${resultMatches.length}）`],["win",`○ 勝った試合（${wonMatches.length}）`],["lose",`× 負けた試合（${lostMatches.length}）`]].map(([key,label])=>{
              const active = resultFilter===key;
              const activeColor = key==="win" ? C.accent : key==="lose" ? C.red : C.navy;
              const activeBg = key==="win" ? C.accentL : key==="lose" ? C.redL : C.navy;
              return (
                <button
                  key={key}
                  onClick={()=>{ setResultFilter(key); setResultListOpen(false); }}
                  style={{ flex:1, padding:"12px 4px", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap",
                    border:`1px solid ${active?activeColor:C.border}`,
                    background:active?activeBg:"#fff",
                    color:active?(key==="all"?"#fff":activeColor):C.textSec }}
                >{label}</button>
              );
            })}
          </div>
        )}

        <div style={{ fontSize:13, color:C.textSec, fontWeight:700, marginBottom:6 }}>選手はそのままで試合数だけ変える</div>
        <div style={{ display:"flex", gap:6, marginBottom:12 }}>
          {[1,3,5,10].map(n => {
            const active = scope.limit === n && (scope.pickedIds??[]).length===0;
            return (
              <button
                key={n}
                disabled={resultLoading}
                onClick={()=>{
                  // ★シートを開かずに試合数だけ変えるショートカット。条件（scope）も合わせて更新する
                  const next = { ...scope, limit:n, pickedIds:[] };
                  setScope(next);
                  const { list, capped } = applyScope(playerMatches, next, { seasonStart, teamMatchIds });
                  loadResults(list, scopeShortLabel(next, seasonLabel), capped);
                }}
                style={{ flex:1, padding:"9px 4px", borderRadius:9, fontSize:12, fontWeight:700, cursor:resultLoading?"default":"pointer",
                  border:`1px solid ${active?C.navy:C.border}`, background:active?C.navy:"#fff", color:active?"#fff":C.textSec }}
              >直近{n}試合</button>
            );
          })}
          <button
            disabled={resultLoading}
            onClick={()=>{
              const next = { ...scope, limit:0, pickedIds:[] };
              setScope(next);
              const { list, capped } = applyScope(playerMatches, next, { seasonStart, teamMatchIds });
              loadResults(list, scopeShortLabel(next, seasonLabel), capped);
            }}
            style={{ flex:1, padding:"9px 4px", borderRadius:9, fontSize:12, fontWeight:700, cursor:resultLoading?"default":"pointer",
              border:`1px solid ${!scope.limit?C.navy:C.border}`, background:!scope.limit?C.navy:"#fff", color:!scope.limit?"#fff":C.textSec }}
          >全部</button>
        </div>


        {/* ★どの試合を集計しているのかを、切り替えボタンのすぐ下で確認できるようにする。
              以前は上の条件バーまで戻らないと分からず、絞り込むたびに往復が必要だった。 */}
        {!resultLoading && resultMatches.length>0 && (
          <div style={{ background:C.white, border:`1.5px solid ${C.accent}`, borderRadius:12, padding:"11px 13px", marginBottom:12 }}>
            <div style={{ fontSize:13, fontWeight:800, color:C.accent, marginBottom:7 }}>✓ いま集計している試合（{resultMatches.length}件）</div>
            {newestFirst(resultMatches)
              .slice(0,3)
              .map((m,i,arr)=>{
                const team = ownSideFor(m, selectedPlayer, effectiveSchoolName) ?? m.players.find(p=>p.player_name===selectedPlayer)?.team;
                const oppTeam = team==="A" ? "B" : "A";
                const oppNames = m.players.filter(p=>p.team===oppTeam).map(p=>p.player_name).join("/");
                const myScore = team==="A" ? m.match_score_a : m.match_score_b;
                const oppScore = team==="A" ? m.match_score_b : m.match_score_a;
                const win = winForPlayer(m, selectedPlayer, effectiveSchoolName);
                return (
                  <div
                    key={m.id}
                    onClick={()=>onOpenMatch && onOpenMatch(m.id)}
                    style={{ display:"flex", alignItems:"center", gap:8, fontSize:13.5, padding:"6px 0",
                      borderBottom: i===arr.length-1 ? "none" : "1px solid #f2f4f8", cursor:"pointer" }}
                  >
                    <span style={{ color:C.textSec, fontSize:13, width:38, flexShrink:0 }}>{(m.match_date||"").slice(5).replace("-","/")}</span>
                    <span style={{ flex:1, minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                      {m.round ? m.round+"・" : ""}{oppNames || "相手未登録"}
                    </span>
                    <span style={{ fontWeight:800, fontSize:13, borderRadius:20, padding:"2px 8px", whiteSpace:"nowrap",
                      color:win?C.accent:C.red, background:win?C.accentL:C.redL }}>{win?"○":"●"} {myScore}-{oppScore}</span>
                  </div>
                );
              })}
            {resultMatches.length > 3 && (
              <div style={{ fontSize:13, color:C.textSec, marginTop:6 }}>
                ほか{resultMatches.length - 3}試合（下の「試合の一覧」で確認できます）
              </div>
            )}
          </div>
        )}

        {resultLoading ? (
          <div style={{ textAlign:"center", padding:40, color:C.textSec }}>集計中...</div>
        ) : resultMatches.length===0 ? (
          <div style={{ ...S.card, padding:24, textAlign:"center", color:C.textSec, fontSize:12.5 }}>対象の試合がありません</div>
        ) : (
          <>
            {/* ★勝敗内訳の一覧（初期は閉じた状態。▼タップで開閉） */}
            <div style={S.card}>
              <div style={{ padding:14 }}>
                <button
                  onClick={()=>setResultListOpen(v=>!v)}
                  style={{ width:"100%", display:"flex", alignItems:"center", justifyContent:"space-between", background:"none", border:"none", cursor:"pointer", padding:0 }}
                >
                  <span style={{ fontSize:13, fontWeight:800, color:C.navy }}>
                    {resultFilter==="win" ? "○ 勝った試合の一覧" : resultFilter==="lose" ? "× 負けた試合の一覧" : "すべての試合の一覧"}
                  </span>
                  <span style={{ fontSize:12, color:C.textSec, transform:resultListOpen?"rotate(180deg)":"none", transition:"transform .15s" }}>▼</span>
                </button>
                {resultListOpen && (
                  <div style={{ marginTop:10 }}>
                    {displayedMatches.length===0 ? (
                      <div style={{ fontSize:12, color:C.textSec }}>該当する試合がありません</div>
                    ) : displayedMatchesNewest.map(m=>{
                      const team = ownSideFor(m, selectedPlayer, effectiveSchoolName) ?? m.players.find(p=>p.player_name===selectedPlayer)?.team;
                      const oppTeam = team==="A" ? "B" : "A";
                      const oppClub = m.players.find(p=>p.team===oppTeam)?.club_name || "";
                      const myScore = team==="A" ? m.match_score_a : m.match_score_b;
                      const oppScore = team==="A" ? m.match_score_b : m.match_score_a;
                      const win = winForPlayer(m, selectedPlayer, effectiveSchoolName);
                      // ★タップでその試合の「スタッツ」タブを開く
                      return (
                        <div
                          key={m.id}
                          onClick={()=>onOpenMatch && onOpenMatch(m.id)}
                          style={{ border:`1px solid ${C.border}`, borderRadius:10, padding:12, marginBottom:8, cursor:"pointer" }}
                        >
                          <div style={{ display:"flex", justifyContent:"space-between", marginBottom:6 }}>
                            <span style={{ fontSize:12, fontWeight:700, color:C.text }}>{m.tournament_name || "（大会外）"}{m.round ? "・"+m.round : ""}</span>
                            <span style={{ fontSize:13, color:C.textSec }}>{m.match_date}</span>
                          </div>
                          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                            <span style={{ fontSize:13, fontWeight:800, padding:"3px 8px", borderRadius:6, color:win?C.accent:C.red, background:win?C.accentL:C.redL }}>{win?"勝利":"敗北"}</span>
                            <span style={{ fontSize:15, fontWeight:900, color:win?C.accent:C.red }}>{myScore} - {oppScore}</span>
                            {oppClub && <span style={{ marginLeft:"auto", fontSize:13, color:C.textSec }}>対 {oppClub}</span>}
                            <span style={{ fontSize:13, color:C.textSec, marginLeft: oppClub?6:"auto" }}>›</span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>

            {/* ★サーブ分析（集計）：1st/2nd/DFの本数比率をドーナツ図＋凡例で、それぞれのサーブ時得点率も表示 */}
            {serveStats.total > 0 && (
              <div style={S.card}>
                <div style={{ padding:14 }}>
                  <div style={{ fontSize:13, fontWeight:800, color:C.navy, marginBottom:2 }}>🎾 サーブ分析（集計）</div>
                  <div style={{ fontSize:13, color:C.textSec, marginBottom:12 }}>サーブ総数：{serveStats.total}本</div>

                  <div style={{ display:"flex", alignItems:"center", gap:16, marginBottom:12 }}>
                    <div style={{
                      width:96, height:96, borderRadius:"50%", flexShrink:0, position:"relative",
                      background:`conic-gradient(${C.accent} 0% ${serveStats.s1/serveStats.total*100}%, ${C.serve} ${serveStats.s1/serveStats.total*100}% ${(serveStats.s1+serveStats.s2)/serveStats.total*100}%, ${C.red} ${(serveStats.s1+serveStats.s2)/serveStats.total*100}% 100%)`,
                    }}>
                      <div style={{ position:"absolute", inset:14, background:C.white, borderRadius:"50%", display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column" }}>
                        <div style={{ fontSize:16, fontWeight:900, color:C.text }}>{serveStats.total}本</div>
                        <div style={{ fontSize:8.5, color:C.textSec }}>サーブ総数</div>
                      </div>
                    </div>
                    <div style={{ flex:1 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:6, padding:"5px 0" }}>
                        <span style={{ width:10, height:10, borderRadius:3, background:C.accent, flexShrink:0 }}/>
                        <span style={{ fontSize:12.5, fontWeight:700, flex:1 }}>1stイン</span>
                        <span style={{ fontSize:14, fontWeight:800 }}>{serveStats.s1}／{serveStats.total}（{Math.round(serveStats.s1/serveStats.total*100)}%）</span>
                      </div>
                      <div style={{ display:"flex", alignItems:"center", gap:6, padding:"5px 0" }}>
                        <span style={{ width:10, height:10, borderRadius:3, background:C.serve, flexShrink:0 }}/>
                        <span style={{ fontSize:12.5, fontWeight:700, flex:1 }}>2ndイン</span>
                        <span style={{ fontSize:14, fontWeight:800 }}>{serveStats.s2}／{serveStats.total}（{Math.round(serveStats.s2/serveStats.total*100)}%）</span>
                      </div>
                      <div style={{ display:"flex", alignItems:"center", gap:6, padding:"5px 0" }}>
                        <span style={{ width:10, height:10, borderRadius:3, background:C.red, flexShrink:0 }}/>
                        <span style={{ fontSize:12.5, fontWeight:700, flex:1 }}>DF</span>
                        <span style={{ fontSize:14, fontWeight:800, color:C.red }}>{serveStats.df}／{serveStats.total}（{Math.round(serveStats.df/serveStats.total*100)}%）</span>
                      </div>
                    </div>
                  </div>

                  <div style={{ fontSize:13, color:C.text, fontWeight:700, lineHeight:1.9, paddingTop:8, borderTop:`1px solid ${C.border}` }}>
                    1stサーブ時の得点率：<b style={{ fontSize:15 }}>{serveStats.s1>0 ? `${serveStats.s1Win}／${serveStats.s1}本（${Math.round(serveStats.s1Win/serveStats.s1*100)}%）` : "記録なし"}</b><br/>
                    2ndサーブ時の得点率：<b style={{ fontSize:15 }}>{serveStats.s2>0 ? `${serveStats.s2Win}／${serveStats.s2}本（${Math.round(serveStats.s2Win/serveStats.s2*100)}%）` : "記録なし"}</b>
                  </div>
                </div>
              </div>
            )}

            {/* ★成長の推移：サーブ分析（合計）のすぐ下で、試合ごとの変化を見る */}
            {serveTrend && (
              <>
                <div style={{ fontSize:15, fontWeight:800, color:C.navy, margin:"16px 0 2px" }}>📈 成長の推移</div>
                <div style={{ fontSize:12.5, color:C.textSec, marginBottom:8 }}>
                  いま集計している{displayedMatches.length}試合を1試合ずつ集計しています
                </div>
                {serveTrend.has1 && <TrendCard title="1stサーブ得点率（試合ごと）" pick={r=>r.r1} color={C.accent} />}
                {serveTrend.has2 && <TrendCard title="2ndサーブ得点率（試合ごと）" pick={r=>r.r2} color="#8fdcbb" />}
                {serveTrend.omitted > 0 && (
                  <div style={{ fontSize:12.5, color:C.textSec, textAlign:"center", marginTop:-4, marginBottom:12 }}>
                    直近{TREND_MAX}試合を表示しています（ほか{serveTrend.omitted}試合）
                  </div>
                )}
              </>
            )}

            {/* 得点・ミスの内訳 */}
            <div style={S.card}>
              <div style={{ padding:14 }}>
                <div style={{ fontSize:13, fontWeight:800, color:C.navy, marginBottom:10 }}>📋 得点・ミスの内訳（{resultFilter==="win"?"勝った試合のみ":resultFilter==="lose"?"負けた試合のみ":"合計"}）</div>
                <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:10 }}>
                  <div style={{ textAlign:"center", padding:"10px 2px", background:C.gray, borderRadius:10 }}>
                    <div style={{ fontSize:18, fontWeight:800, color:C.navy }}>{agg.winners}</div>
                    <div style={{ fontSize:12, color:C.textSec, marginTop:2 }}>総得点</div>
                  </div>
                  <div style={{ textAlign:"center", padding:"10px 2px", background:C.gray, borderRadius:10 }}>
                    <div style={{ fontSize:18, fontWeight:800, color:C.navy }}>{agg.errors}</div>
                    <div style={{ fontSize:12, color:C.textSec, marginTop:2 }}>総ミス</div>
                  </div>
                  <div style={{ textAlign:"center", padding:"10px 2px", background:C.gray, borderRadius:10 }}>
                    <div style={{ fontSize:18, fontWeight:800, color:agg.winners-agg.errors>=0?C.accent:C.red }}>{agg.winners-agg.errors>=0?"+":""}{agg.winners-agg.errors}</div>
                    <div style={{ fontSize:12, color:C.textSec, marginTop:2 }}>得失点差</div>
                  </div>
                </div>

                {/* ★プレイ別／コース別の切り替え。以前は別々のカードだったものを1枚にまとめている */}
                <div style={{ display:"flex", background:C.gray, borderRadius:12, padding:5, gap:5, marginBottom:14 }}>
                  {[["play","プレイ別"],["course","コース別"]].map(([k,l])=>(
                    <div key={k} onClick={()=>setBreakdownDim(k)}
                      style={{ flex:1, textAlign:"center", padding:"11px 4px", fontSize:14, fontWeight:breakdownDim===k?800:700, borderRadius:9, cursor:"pointer",
                        background:breakdownDim===k?C.white:"transparent", color:breakdownDim===k?C.navy:C.textSec,
                        boxShadow:breakdownDim===k?"0 1px 4px rgba(0,0,0,0.12)":"none" }}
                    >{l}</div>
                  ))}
                </div>

                {breakdownDim==="play" && (<>
                {topPlaysWin.map(([label,count])=>(
                  <div key={"w"+label} style={{ display:"flex", alignItems:"center", fontSize:13.5, padding:"6px 0" }}>
                    <div style={{ width:100, color:C.text, fontWeight:700, whiteSpace:"nowrap" }}>{getPlayLabel ? getPlayLabel(label) : label}</div>
                    <div style={{ flex:1, height:10, background:"#eef0f3", borderRadius:5, margin:"0 8px", overflow:"hidden" }}><div style={{ height:"100%", width:`${count/maxPlayCount*100}%`, background:C.accent, borderRadius:5 }}/></div>
                    <div style={{ width:30, textAlign:"right", fontWeight:800, color:C.navy }}>{count}</div>
                  </div>
                ))}
                {topPlaysWin.length>0 && topPlaysErr.length>0 && <div style={{ height:8 }}/>}
                {topPlaysErr.map(([label,count])=>(
                  <div key={"e"+label} style={{ display:"flex", alignItems:"center", fontSize:13.5, padding:"6px 0" }}>
                    <div style={{ width:100, color:C.text, fontWeight:700, whiteSpace:"nowrap" }}>{getPlayLabel ? getPlayLabel(label) : label}</div>
                    <div style={{ flex:1, height:10, background:"#eef0f3", borderRadius:5, margin:"0 8px", overflow:"hidden" }}><div style={{ height:"100%", width:`${count/maxPlayCount*100}%`, background:C.red, borderRadius:5 }}/></div>
                    <div style={{ width:30, textAlign:"right", fontWeight:800, color:C.navy }}>{count}</div>
                  </div>
                ))}
                </>)}

                {breakdownDim==="course" && courseStats.all===0 && (
                  <div style={{ padding:"20px 0", textAlign:"center", color:C.textSec, fontSize:13 }}>コースが入力されたポイントがありません</div>
                )}
              </div>
            </div>

            {/* ★コース分析：①引っ張り/流し → ②フォア/バック別 → ③コース別の決めた/ミス と、
                だんだん細かく見ていく構成。本数は割合より大きな文字にして読み取りやすくしている。 */}
            {breakdownDim==="course" && courseStats.all > 0 && (
              <div style={{ ...S.card, marginTop:-4 }}>
                <div style={{ padding:14 }}>

                  {/* ① 引っ張り / 流し */}
                  <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:7 }}>① 引っ張り / 流し</div>
                  <div style={{ display:"flex", height:34, borderRadius:8, overflow:"hidden", background:"#eef0f3" }}>
                    {courseStats.pull>0 && (
                      <div style={{ width:`${courseStats.pull/courseStats.all*100}%`, background:COURSE_PULL_COLOR, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13.5, fontWeight:800, color:C.white }}>
                        {Math.round(courseStats.pull/courseStats.all*100)}%
                      </div>
                    )}
                    {courseStats.nagashi>0 && (
                      <div style={{ width:`${courseStats.nagashi/courseStats.all*100}%`, background:COURSE_NAGASHI_COLOR, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13.5, fontWeight:800, color:C.white }}>
                        {Math.round(courseStats.nagashi/courseStats.all*100)}%
                      </div>
                    )}
                  </div>
                  <div style={{ display:"flex", justifyContent:"space-between", fontSize:13, color:C.textSec, marginTop:6 }}>
                    <span>引っ張り <b style={{ fontSize:15, fontWeight:800, color:C.text }}>{courseStats.pull}</b>本</span>
                    <span>流し <b style={{ fontSize:15, fontWeight:800, color:C.text }}>{courseStats.nagashi}</b>本</span>
                  </div>

                  {/* ② フォア／バック別の 引っ張り / 流し */}
                  <div style={{ marginTop:16, paddingTop:14, borderTop:`1px solid ${C.border}` }}>
                    <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:4 }}>② フォア / バック別</div>
                    {courseStats.sides.map((sd, sdIdx) => (
                      <div key={sd.side} style={{ marginTop: sdIdx===0 ? 0 : 14 }}>
                        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", fontSize:13.5, fontWeight:700, color:C.text, marginBottom:5 }}>
                          <span>{sd.label}</span>
                          {sd.total>0
                            ? <span style={{ fontSize:12, fontWeight:400, color:C.textSec }}><b style={{ fontSize:13.5, fontWeight:800, color:C.text }}>{sd.total}</b>本</span>
                            : <span style={{ fontSize:12, fontWeight:400, color:C.textSec }}>記録なし</span>}
                        </div>
                        {sd.total>0 && (
                          <>
                            <div style={{ display:"flex", height:20, borderRadius:6, overflow:"hidden", background:"#eef0f3" }}>
                              {sd.pull>0 && (
                                <div style={{ width:`${sd.pull/sd.total*100}%`, background:COURSE_PULL_COLOR, display:"flex", alignItems:"center", justifyContent:"center", fontSize:12.5, fontWeight:800, color:C.white }}>
                                  {Math.round(sd.pull/sd.total*100)}%
                                </div>
                              )}
                              {sd.nagashi>0 && (
                                <div style={{ width:`${sd.nagashi/sd.total*100}%`, background:COURSE_NAGASHI_COLOR, display:"flex", alignItems:"center", justifyContent:"center", fontSize:12.5, fontWeight:800, color:C.white }}>
                                  {Math.round(sd.nagashi/sd.total*100)}%
                                </div>
                              )}
                            </div>
                            <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, color:C.textSec, marginTop:5, marginBottom:8 }}>
                              <span>引っ張り <b style={{ fontSize:13.5, fontWeight:800, color:C.text }}>{sd.pull}</b>本</span>
                              <span>流し <b style={{ fontSize:13.5, fontWeight:800, color:C.text }}>{sd.nagashi}</b>本</span>
                            </div>
                            
                          </>
                        )}
                      </div>
                    ))}
                  </div>

                  {/* 気づき（本数が少ないと割合が極端に出るため、3本以上のコースだけを対象にしている） */}
                  <div style={{ background:"#f7f9fc", borderLeft:`3px solid ${C.navy}`, borderRadius:6, padding:"8px 10px", fontSize:13, lineHeight:1.65, marginTop:16 }}>
                    {courseStats.best ? (
                      <>
                        よく決まっているのは<b>{courseStats.best.label}</b>（決定率{Math.round(courseStats.best.rate*100)}%・{courseStats.best.total}本）。
                        {courseStats.worst && courseStats.worst.key !== courseStats.best.key && (<><br/>苦しいのは<b>{courseStats.worst.label}</b>（決定率{Math.round(courseStats.worst.rate*100)}%・{courseStats.worst.total}本）。</>)}
                      </>
                    ) : "まだ本数が少なく、傾向は出ていません。"}
                  </div>

                  {/* ③ コース別の 決めた / ミス */}
                  <div style={{ marginTop:16, paddingTop:14, borderTop:`1px solid ${C.border}` }}>
                    <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:10 }}>③ コース別の 決めた / ミス</div>
                    {courseStats.rows.map(r => {
                      const rate = r.total>0 ? Math.round(r.win/r.total*100) : 0;
                      return (
                      <div key={r.key} style={{ marginBottom:13 }}>
                        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", fontSize:13.5, fontWeight:700, color:C.text, marginBottom:6 }}>
                          <span>{r.label}</span>
                          {r.total>0
                            ? <span style={{ fontSize:13, fontWeight:400, color:C.textSec }}>{r.total}本中 <b style={{ fontSize:14.5, fontWeight:800, color:rate<40?C.red:C.text }}>決定率 {rate}%</b></span>
                            : <span style={{ fontSize:13, fontWeight:400, color:C.textSec }}>記録なし</span>}
                        </div>
                        {r.total>0 && (
                          <div style={{ display:"flex", height:26, borderRadius:7, overflow:"hidden", background:"#eef0f3" }}>
                            {r.win>0 && (
                              <div style={{ width:`${r.win/r.total*100}%`, background:C.accent, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13, fontWeight:800, color:C.white, whiteSpace:"nowrap", overflow:"hidden" }}>
                                決めた {r.win}
                              </div>
                            )}
                            {r.err>0 && (
                              <div style={{ width:`${r.err/r.total*100}%`, background:C.red, display:"flex", alignItems:"center", justifyContent:"center", fontSize:13, fontWeight:800, color:C.white, whiteSpace:"nowrap", overflow:"hidden" }}>
                                ミス {r.err}
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                      );
                    })}
                  </div>

                  <div style={{ fontSize:12, color:"#8a92a0", marginTop:10, lineHeight:1.6 }}>
                    ※コースが入力された{courseStats.all}本をもとに集計しています。
                  </div>
                </div>
              </div>
            )}

            {/* ★ミスの傾向（今回追加した「ミスの種類」と、これまで記録のみだった「フォア/バック」を集計） */}
            {hasMissDetail && (
              <div style={S.card}>
                <div style={{ padding:14 }}>
                  <div style={{ fontSize:13, fontWeight:800, color:C.navy, marginBottom:10 }}>⚠️ ミスの傾向</div>

                  {missTypeRows.length>0 && (
                    <>
                      <div style={{ fontSize:13, color:C.textSec, fontWeight:700, marginBottom:4 }}>ミスの種類（全{agg.missTyped}回）</div>
                      {missTypeRows.map(([label,count]) => (
                        <MissRow key={label} label={label} count={count} total={agg.missTyped}
                          max={Math.max(...missTypeRows.map(r=>r[1]))} color={C.red}/>
                      ))}
                    </>
                  )}

                  {missSideRows.length>0 && (
                    <>
                      <div style={{ fontSize:13, color:C.textSec, fontWeight:700, margin:"10px 0 4px" }}>フォア / バック</div>
                      {missSideRows.map(([label,count]) => (
                        <MissRow key={label} label={label} count={count} total={missSideTotal}
                          max={Math.max(...missSideRows.map(r=>r[1]))} color={C.red}/>
                      ))}
                    </>
                  )}

                  {topMissCombos.length>0 && (
                    <>
                      <div style={{ fontSize:13, color:C.textSec, fontWeight:700, margin:"10px 0 4px" }}>多いミスの組み合わせ</div>
                      {topMissCombos.map(([key,count],i) => (
                        <div key={key} style={{ display:"flex", alignItems:"center", gap:6, fontSize:12, padding:"5px 0", borderBottom: i<topMissCombos.length-1?`1px solid ${C.border}`:"none" }}>
                          <span style={{ fontSize:9, fontWeight:800, color:"#fff", background:C.navy, borderRadius:5, padding:"1px 5px" }}>{i+1}</span>
                          <span style={{ flex:1, color:C.text }}>{missComboLabel(key)}</span>
                          <b style={{ color:C.navy }}>{count}回</b>
                        </div>
                      ))}
                    </>
                  )}

                  {/* ★ミスの種類は入力が任意で、過去の試合には入っていないため、必ず母数を添える */}
                  <div style={{ fontSize:9.5, color:"#9aa1ad", marginTop:8, lineHeight:1.5 }}>
                    ※ミスの種類が入力された {agg.missTyped}/{agg.errors}件をもとに集計しています
                  </div>
                </div>
              </div>
            )}

            {/* 勝敗別データ比較 */}
            <div style={S.card}>
              <div style={{ padding:14 }}>
                <div style={{ fontSize:13, fontWeight:800, color:C.navy, marginBottom:10 }}>⚖️ 勝った試合 と 負けた試合の比較</div>
                {wonMatches.length===0 || lostMatches.length===0 ? (
                  <div style={{ fontSize:12, color:C.textSec }}>比較するには、勝った試合・負けた試合の両方が必要です</div>
                ) : (
                  <table style={{ width:"100%", borderCollapse:"collapse", fontSize:12 }}>
                    <thead>
                      <tr>
                        <th></th>
                        <th style={{ fontSize:10.5,color:C.accent,fontWeight:700,padding:"6px 4px" }}>勝ち（{wonMatches.length}試合）</th>
                        <th style={{ fontSize:10.5,color:C.red,fontWeight:700,padding:"6px 4px" }}>負け（{lostMatches.length}試合）</th>
                      </tr>
                    </thead>
                    <tbody>
                      {Object.keys(metricLabel).map(key => (
                        <tr key={key}>
                          <td style={{ padding:"8px 4px", color:C.textSec, fontWeight:600, borderTop:`1px solid ${C.border}` }}>{metricLabel[key]}</td>
                          <td style={{ padding:"8px 4px", textAlign:"center", fontWeight:700, color:C.accent, borderTop:`1px solid ${C.border}` }}>{wonRates[key]==null?"—":wonRates[key]+"%"}</td>
                          <td style={{ padding:"8px 4px", textAlign:"center", fontWeight:700, color:C.red, borderTop:`1px solid ${C.border}` }}>{lostRates[key]==null?"—":lostRates[key]+"%"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          </>
        )}

      </div>
      <NavBar active="stats" onNavigate={onNavigate}/>
    </div>
  );
}


function StatsScreen({ onNavigate, onOpenPlayer, onOpenOpponent, onOpenMatch }) {
  const initialPrefs = useState(() => loadStatsFilterPrefs())[0];

  const [allMatches, setAllMatches] = useState([]);
  const [roster, setRoster] = useState([]);
  const [loading, setLoading] = useState(true);
  const [teamMatchIds, setTeamMatchIds] = useState(new Set()); // 団体戦の一戦として作成されたmatch.idの集合

  // ①試合対象カテゴリ（新規）：all(すべて) | tournament(大会) | team(団体戦) | individual(個人戦)
  const [statsCat, setStatsCat] = useState(initialPrefs.statsCat ?? "all");
  const [statsCatSub, setStatsCatSub] = useState(initialPrefs.statsCatSub ?? "allsub"); // allsub | specific
  const [statsCatTournament, setStatsCatTournament] = useState(initialPrefs.statsCatTournament ?? "");
  // ★以前の版で保存された期間が残っていると「undefined」と表示されていたため、知らない値は全期間に戻す
  const [period, setPeriod] = useState(() => ["all","month1","month3","season"].includes(initialPrefs.period) ? initialPrefs.period : "all"); // all | month1 | month3 | season
  // ★シーズン設定（起点日・呼び名）。設定されていれば「📌◯◯以降」を初期表示の期間にする
  const [seasonStart, setSeasonStart] = useState(null);
  const [seasonLabel, setSeasonLabel] = useState("");
  const [trendOpen, setTrendOpen] = useState(false); // 月別の勝率推移（折りたたみ）
  const [scoreOpen, setScoreOpen] = useState(false); // 得点・ミス（折りたたみ）
  const [filterOpen, setFilterOpen] = useState(false);

  // ②見る内容タブ：players(選手別) | pairs(ペア別) | opponents(対戦別)
  // ★自チーム／対戦チームの2分割。既存の「選手別・ペア別・対戦別」をこの2つに振り分ける
  //   （自チーム＝選手別/ペア別、対戦チーム＝対戦別）。開いたときは対戦チーム側。
  const [side, setSide] = useState(initialPrefs.side ?? "opp");
  // ★自チームの得点・ミス集計：対象選手をチェックで絞れる（初期は全員）
  const [pickOpen, setPickOpen] = useState(false);
  const [excluded, setExcluded] = useState(new Set()); // チェックを外した選手
  const [ownDetail, setOwnDetail] = useState([]);
  const [ownDetailLoading, setOwnDetailLoading] = useState(false);
  // ★以前の設定に "opponents" が保存されている場合があるので、自チーム側では選手別に寄せる
  // ★見る内容は「players（自チーム選手）｜pairs（自チームペア）｜opponents（対戦校）」の3つ
  const [tab, setTab] = useState(() => {
    if (initialPrefs.side === "opp") return "opponents";
    return ["players","pairs","opponents"].includes(initialPrefs.tab) ? initialPrefs.tab : "players";
  });
  const [pairMode, setPairMode] = useState(initialPrefs.pairMode ?? "own"); // own | opp
  const [oppMode, setOppMode] = useState(initialPrefs.oppMode ?? "team"); // team | pair
  const [sort, setSort] = useState("rate"); // rate(勝率順) | win(勝数順) | lose(負数順) | count(試合数順)
  // ★以前は勝率順だったが、1試合100%が7試合100%より上に来てしまい実力が分からなかったため、
  //   勝数・負数の多い順に変更（同数なら試合数が多い方を上にする）
  const sortRows = sortByRecord(sort);

  const [showBreakdown, setShowBreakdown] = useState(false); // 総合成績カードの内訳一覧
  const [breakdownFilter, setBreakdownFilter] = useState("all"); // ★総合成績の内訳：all | win | lose
  const [deletedTournamentNames, setDeletedTournamentNames] = useState([]); // ゴミ箱に入っている大会名（絞り込み選択肢から除外用）
  const [mySchoolName, setMySchoolName] = useState(""); // ★自チーム同士の練習試合判定用

  // ★以前は「試合」「選手マスター」「プロフィール→学校」「ゴミ箱の大会」「団体戦」を
  //   別々のuseEffectでバラバラに取得していた。取得自体は同時に走るものの、
  //   プロフィール→学校だけは順番待ちになっており、また画面を開き直すたびに
  //   全部を取り直して「読み込み中...」で待たされていた。
  //   ここでは①まとめて同時取得し、②前回の内容をキャッシュから即表示してから
  //   裏で最新に差し替える、という動きにする。
  const apply = useCallback(({ list, simpleList, rosterList, schoolName, deletedNames, teamIds }) => {
    setAllMatches([...list, ...simpleList]);
    setRoster(rosterList);
    setMySchoolName(schoolName);
    setDeletedTournamentNames(deletedNames);
    setTeamMatchIds(new Set(teamIds));
    setLoading(false);
  }, []);

  useEffect(() => {
    const cached = readScreenCache("teamStats");
    if (cached) apply(cached); // まず前回の内容を即表示（裏で最新化を続ける）
    (async () => {
      // ★以前は団体戦を動画リンクまで全部取得していたが、ここで使うのは「番手の試合ID」だけなので、
      //   試合一覧で取得済みのものを使い回す。削除済み大会は名前だけ取る。シーズン設定も同時に取得する。
      const seasonP = getMySchoolSeason();
      const [list, simpleList, rosterList, p, schools, deletedNamesList, teamIdSet] = await Promise.all([
        getMatchesCached(), getSimpleRecordedDrawMatches(), getPlayerRoster(),
        getMyProfile(), getSchools(), getDeletedTournamentNames(), getTeamMatchMatchIds(),
      ]);
      const school = p?.school_id ? (schools || []).find(s => s.id === p.school_id) : null;
      if (p?.school_id) {
        seasonP.then(season => {
          if (season?.season_start_date) {
            setSeasonStart(season.season_start_date);
            setSeasonLabel(season.season_start_label || defaultSeasonLabel(season.season_start_date));
            setPeriod("season");
          } else {
            setPeriod(v => v==="season" ? "all" : v);
          }
        });
      }
      // ★団体戦の一戦として作成された試合（match）のIDを集めておく（個人戦との区別に使う）
      const teamIds = Array.from(teamIdSet);
      const snapshot = {
        list, simpleList, rosterList,
        schoolName: school?.name ?? "",
        // ★ゴミ箱に入っている大会名。試合データ自体は削除しないが、
        //   絞り込みプルダウンには削除済みの大会名を出さないようにするため。
        deletedNames: deletedNamesList,
        teamIds,
      };
      writeScreenCache("teamStats", snapshot);
      apply(snapshot);
    })();
  }, [apply]);

  // ①の絞り込み条件が変わるたびに端末に保存（次回開いたときも保持される）
  useEffect(() => {
    saveStatsFilterPrefs({ statsCat, statsCatSub, statsCatTournament, period, side: tab==="opponents" ? "opp" : "own", tab, pairMode, oppMode });
  }, [statsCat, statsCatSub, statsCatTournament, period, tab, pairMode, oppMode]);

  function resetStatsFilter() {
    setStatsCat("all"); setStatsCatSub("allsub"); setStatsCatTournament(""); setPeriod(seasonStart ? "season" : "all");
  }

  // ★以前は下記の絞り込み・集計を「毎回の再描画」で全試合ぶん計算し直していたため、
  //   タブを切り替える・並び順を変える・内訳を開くといった操作のたびに
  //   試合数に比例した計算が走り、試合数が増えるほど画面がもたついていた。
  //   元になるデータや条件が変わったときだけ計算するようにする。

  // 削除済みの大会名は絞り込み候補に出さない（毎回の配列検索を避けるためSetにしておく）
  const deletedTournamentNameSet = useMemo(() => new Set(deletedTournamentNames), [deletedTournamentNames]);

  // 大会名の選択肢（登録されている試合から重複なく抽出。日付が新しい大会を上にする。削除済みの大会名は除外）
  const tournamentOptions = useMemo(() => Array.from(
    new Map(
      allMatches
        .filter(m => m.tournament_name && !deletedTournamentNameSet.has(m.tournament_name))
        .slice()
        .sort((a,b) => new Date(b.match_date) - new Date(a.match_date))
        .map(m => [m.tournament_name, m.tournament_name])
    ).values()
  ), [allMatches, deletedTournamentNameSet]);

  // ①カテゴリ・期間による絞り込み
  const finished = useMemo(() => {
    let categoryMatches;
    if (statsCat === "tournament") categoryMatches = allMatches.filter(m => m.tournament_name && !deletedTournamentNameSet.has(m.tournament_name));
    else if (statsCat === "team") categoryMatches = allMatches.filter(m => teamMatchIds.has(m.id));
    else if (statsCat === "individual") categoryMatches = allMatches.filter(m => !teamMatchIds.has(m.id));
    else categoryMatches = allMatches; // all

    if (statsCat !== "all" && statsCatSub === "specific" && statsCatTournament) {
      categoryMatches = categoryMatches.filter(m => m.tournament_name === statsCatTournament);
    }

    const periodMatches = period==="month1" ? withinLastDays(categoryMatches, 30)
      : period==="month3" ? withinLastDays(categoryMatches, 90)
      : (period==="season" && seasonStart) ? categoryMatches.filter(m => (m.match_date||"") >= seasonStart)
      : categoryMatches;
    return periodMatches.filter(countsAsFinished);
  }, [allMatches, deletedTournamentNameSet, teamMatchIds, statsCat, statsCatSub, statsCatTournament, period, seasonStart]);

  const teamRecord = useMemo(() => recordOf(finished, m=>winnerSideOf(m)==="A"), [finished]);

  // ペア別成績（自チームAのペア名を「選手1／選手2」形式で集計）
  // ★相手チームが同じ学校（練習試合）の場合は、B側のペアも自チームのペアとして含める
  // ★A側に記録されているのが本来「自チーム」のはずでも、対戦相手の学校名の入力ミスなどで
  //   実際には相手選手が紛れ込んでいるケースがあるため、選手マスターで自チーム登録されている
  //   選手同士のペアのみを「自チームのペア」として集計する（マスター未登録の名前が混ざるものは除外）
  const ownNameSet = useMemo(() => new Set(roster.filter(p => p.is_own_team !== false).map(p => (p.player_name||"").trim())), [roster]);
  const byPair = useMemo(() => {
  const byPair = {};
  finished.forEach(m => {
    const aPlayers = m.players.filter(p => p.team === "A").sort((a,b) => a.order_num - b.order_num);
    // ★名前の並び順が試合ごとに違っても同じペアとして数える（集計は名前順のキーでまとめ、
    //   表示は「選手1（後衛）／選手2（前衛）」の順。並び順は各試合の入力順を記録しておく）
    const aOrdered = aPlayers.map(p => (p.player_name||"").trim()).filter(Boolean);
    const aNames = [...aOrdered].sort();
    if (aNames.length && aNames.every(n => ownNameSet.has(n))) {
      const pairKey = aNames.join("／") || "（不明）";
      (byPair[pairKey] ??= []).push({ match: m, win: winnerSideOf(m)==="A", order: aOrdered.join("\t") });
    }
    const bPlayers = m.players.filter(p => p.team === "B").sort((a,b) => a.order_num - b.order_num);
    const bClub = bPlayers[0]?.club_name;
    if (mySchoolName && bClub && bClub.trim()===mySchoolName.trim()) {
      const bOrdered = bPlayers.map(p => (p.player_name||"").trim()).filter(Boolean);
      const bNames = [...bOrdered].sort();
      if (bNames.length && bNames.every(n => ownNameSet.has(n))) {
        const bPairKey = bNames.join("／") || "（不明）";
        (byPair[bPairKey] ??= []).push({ match: m, win: winnerSideOf(m)==="B", order: bOrdered.join("\t") });
      }
    }
  });
  return byPair;
  }, [finished, ownNameSet, mySchoolName]);
  const pairRows = useMemo(() => {
    const rows = Object.entries(byPair).map(([key, list]) => {
      const votes = {};
      list.forEach(x => { if (x.order) votes[x.order] = (votes[x.order] ?? 0) + 1; });
      const ordered = majorityPairOrder(votes);
      return { name: ordered.length ? ordered.join("／") : key, ...recordOf(list, x => x.win) };
    });
    rows.sort(sortRows);
    return rows;
  }, [byPair, sort]);

  // 相手チームのペア別成績（対戦相手Bのペア名で集計。勝敗は相手側から見た勝敗）
  // ★部内戦（B側の所属校が自チームと同じ＝東福岡 対 東福岡など）は「対戦相手」として
  // 　不自然になるため集計から除外する
  const byOppPair = useMemo(() => {
  const byOppPair = {};
  finished.forEach(m => {
    const bPlayers = m.players.filter(p => p.team === "B").sort((a,b) => a.order_num - b.order_num);
    const club = bPlayers[0]?.club_name || "";
    if (mySchoolName && club && club.trim() === mySchoolName.trim()) return;
    const pairKey = bPlayers.map(p => p.player_name).filter(Boolean).join("／") || "（不明）";
    const key = club ? `${pairKey}（${club}）` : pairKey;
    (byOppPair[key] ??= []).push(m);
  });
  return byOppPair;
  }, [finished, mySchoolName]);
  const oppPairRows = useMemo(() => {
    const rows = Object.entries(byOppPair).map(([name, list]) => ({
      name, ...recordOf(list, m => winnerSideOf(m)==="B"),
    }));
    rows.sort(sortRows);
    return rows;
  }, [byOppPair, sort]);

  // 選手別成績（選手マスターの自チーム選手のみ）
  // ★重要：同姓の相手チーム選手がいる場合の取り違えを防ぐため、
  // 　自チーム(team==="A")として出場した試合だけを対象にする。
  // 　ただし相手チームが同じ学校（東福岡 対 東福岡の練習試合など）の場合は、
  // 　B側で出場した試合も自チームの成績として含める。
  // ★以前は「自チーム選手の人数 × 全試合数」の回数だけ判定していた（40人×500試合＝2万回）。
  //   試合を1回だけ走査し、その試合に出ていた選手にだけ振り分ける方式にする。
  const playerRows = useMemo(() => {
    const byPlayer = {};
    roster.filter(p=>p.is_own_team!==false).forEach(p => { byPlayer[p.player_name] = { total:0, wins:0 }; });
    finished.forEach(m => {
      // 同じ試合に同じ名前が複数行ある場合でも1試合として数える（1試合1回だけ判定する）
      const seen = new Set();
      m.players.forEach(mp => {
        const rec = byPlayer[mp.player_name];
        if (!rec || seen.has(mp.player_name)) return;
        seen.add(mp.player_name);
        if (!ownSideFor(m, mp.player_name, mySchoolName)) return;
        rec.total++;
        if (winForPlayer(m, mp.player_name, mySchoolName)) rec.wins++;
      });
    });
    const rows = Object.entries(byPlayer)
      .filter(([,r]) => r.total > 0)
      .map(([name, r]) => ({
        name, total: r.total, wins: r.wins, losses: r.total - r.wins,
        rate: r.total ? Math.round(r.wins / r.total * 100) : 0,
      }));
    rows.sort(sortRows);
    return rows;
  }, [roster, finished, mySchoolName, sort]);

  // 対戦相手（学校）別成績
  // ★部内戦（B側の所属校が自チームと同じ＝東福岡 対 東福岡など）は
  // 　「対戦相手チーム」として不自然になるため集計から除外する
  const opponentRows = useMemo(() => {
    const byOpponent = {};
    finished.forEach(m=>{
      const club = m.players.find(p=>p.team==="B")?.club_name || "";
      if (mySchoolName && club && club.trim() === mySchoolName.trim()) return;
      const name = club || "（相手不明）";
      (byOpponent[name] ??= []).push(m);
    });
    const rows = Object.entries(byOpponent).map(([name,list])=>({
      name, ...recordOf(list, m=>winnerSideOf(m)==="A"),
    }));
    rows.sort(sortRows);
    return rows;
  }, [finished, mySchoolName, sort]);

  // ★自チームの得点・ミス：集計対象の試合だけポイントを読み込む（自チームタブを開いたときだけ）
  const ownIdsKey = finished.map(m=>m.id).sort().join(",");
  useEffect(() => {
    // ★得点・ミスを開いたときだけポイントを読み込む（重いため）
    if (!(tab === "players" && scoreOpen)) return;
    const ids = ownIdsKey ? ownIdsKey.split(",") : [];
    if (ids.length === 0) { setOwnDetail([]); return; }
    let cancelled = false;
    (async () => {
      setOwnDetailLoading(true);
      // ★全試合のポイントを一度に読むと重いので、新しい方から最大100試合に絞る
      const capped = ids.slice(0, SCOPE_MAX);
      const full = await getFullMatchesByIds(capped);
      if (!cancelled) { setOwnDetail(full); setOwnDetailLoading(false); }
    })();
    return () => { cancelled = true; };
  }, [ownIdsKey, tab, scoreOpen]);

  // 集計対象に出場している自チームの選手（チェックボックスの候補）
  const ownPlayerNames = useMemo(() => {
    const set = new Set();
    ownDetail.forEach(m => m.players.filter(p=>p.team==="A").forEach(p => {
      if (!mySchoolName || !p.club_name || p.club_name.trim()===mySchoolName.trim()) set.add(p.player_name);
    }));
    return [...set].sort();
  }, [ownDetail, mySchoolName]);

  const selectedOwnNames = ownPlayerNames.filter(n => !excluded.has(n));

  // 選んだ選手の合算（決めた・ミス・プレイ別内訳）
  const ownAgg = useMemo(() => {
    if (ownDetail.length === 0 || selectedOwnNames.length === 0) return null;
    const sum = { total:0, winners:0, errors:0, playsWin:{}, playsErr:{} };
    selectedOwnNames.forEach(n => {
      const a = aggregatePlayerStats(ownDetail, n, mySchoolName);
      sum.total += a.total ?? 0; sum.winners += a.winners ?? 0; sum.errors += a.errors ?? 0;
      for (const k in (a.playsWin??{})) sum.playsWin[k] = (sum.playsWin[k]??0) + a.playsWin[k];
      for (const k in (a.playsErr??{})) sum.playsErr[k] = (sum.playsErr[k]??0) + a.playsErr[k];
    });
    return sum;
  }, [ownDetail, selectedOwnNames.join("|"), mySchoolName]);

  const subLabel = statsCat!=="all" ? (statsCatSub==="specific" && statsCatTournament ? `（${statsCatTournament}）` : "（すべて）") : "";
  const periodLabel = period==="season" && seasonStart ? `📌 ${seasonLabel}以降` : (STATS_PERIOD_LABELS[period] ?? "全期間");
  const filterSummary = `${periodLabel}・${statsCat==="all" ? "すべての試合" : STATS_CAT_LABELS[statsCat]}${subLabel}`;

  return (
    <div style={S.page}>
      <div style={{ ...S.hdr, color:C.white }}>
        <div style={{ fontSize:20, fontWeight:800 }}>分析</div>
      </div>
      <div style={{ padding:14, paddingBottom:90 }}>
        <AnalysisTabs current="team" onPersonal={()=>onNavigate&&onNavigate("stats")} onPair={()=>onNavigate && onNavigate("pairAnalysis")} />
        {loading ? (
          <div style={{ textAlign:"center",color:C.textSec,marginTop:60 }}>読み込み中...</div>
        ) : allMatches.filter(countsAsFinished).length===0 ? (
          <div style={{ textAlign:"center",color:C.textSec,marginTop:60 }}>集計できる試合がまだありません</div>
        ) : (
          <>
            {/* 折りたたみ式：①試合対象・期間フィルター */}
            <div style={{ background:C.white, border:"1px solid "+C.border, borderRadius:12, marginBottom:12, overflow:"hidden" }}>
              <div
                style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:8, padding:"12px 14px", cursor:"pointer" }}
                onClick={()=>setFilterOpen(v=>!v)}
              >
                <span style={{ fontSize:15, fontWeight:800, color:C.text, minWidth:0 }}>{filterSummary}</span>
                <span style={{ fontSize:13, fontWeight:700, color:C.navy, flexShrink:0 }}>{filterOpen ? "条件 ▲" : "条件 ▼"}</span>
              </div>
              {filterOpen && (
                <div style={{ padding:"12px 14px 14px", borderTop:"1px solid "+C.border }}>
                  <div style={{ fontSize:13,color:"#5a6478",fontWeight:800,marginBottom:6 }}>試合の種類</div>
                  <div style={{ display:"flex", gap:6, marginBottom:8 }}>
                    {[["all","すべて"],["tournament","大会"],["team","団体戦"],["individual","個人戦"]].map(([v,l])=>(
                      <button
                        key={v}
                        style={{ ...S.togBtn(statsCat===v, C.navy), flex:1, fontSize:13.5, padding:"9px 2px" }}
                        onClick={()=>{ setStatsCat(v); setStatsCatSub("allsub"); }}
                      >{l}</button>
                    ))}
                  </div>
                  {statsCat!=="all" && (
                    <div style={{ marginBottom:8 }}>
                      <div style={{ display:"flex", gap:8, marginBottom:8 }}>
                        {[["allsub","すべて"],["specific","大会を指定"]].map(([v,l])=>(
                          <button
                            key={v}
                            style={{ ...S.togBtn(statsCatSub===v, C.navy), flex:1, fontSize:13.5, padding:"8px 4px" }}
                            onClick={()=>setStatsCatSub(v)}
                          >{l}</button>
                        ))}
                      </div>
                      {statsCatSub==="specific" && (
                        <select
                          value={statsCatTournament}
                          onChange={e=>setStatsCatTournament(e.target.value)}
                          style={{ width:"100%", padding:"10px", borderRadius:8, border:"1px solid "+C.border, fontSize:16, color:C.text, background:C.white }}
                        >
                          <option value="">大会を選択してください</option>
                          {tournamentOptions.map(name => (
                            <option key={name} value={name}>{name}</option>
                          ))}
                        </select>
                      )}
                    </div>
                  )}
                  <div style={{ fontSize:13,color:"#5a6478",fontWeight:800,margin:"10px 0 6px" }}>期間</div>
                  <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:8 }}>
                    {[
                      ...(seasonStart ? [["season",`📌 ${seasonLabel}以降`]] : []),
                      ["month1","直近1ヶ月"],["month3","直近3ヶ月"],["all","全期間"],
                    ].map(([v,l])=>(
                      <button key={v} style={{ ...S.togBtn(period===v, C.navy), flex:"1 1 auto", fontSize:13.5, padding:"9px 8px" }} onClick={()=>setPeriod(v)}>{l}</button>
                    ))}
                  </div>
                  <div style={{ textAlign:"right" }}>
                    <span style={{ fontSize:13, fontWeight:700, color:C.navy, textDecoration:"underline", cursor:"pointer" }} onClick={resetStatsFilter}>条件をリセット</span>
                  </div>
                </div>
              )}
            </div>

            {/* 総合成績（チーム全体） */}
            <div style={{ ...S.card, padding:16, marginBottom:12 }}>
              <div style={{ fontSize:15,fontWeight:800,color:C.navy,marginBottom:10 }}>総合成績</div>
              <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1.35fr",textAlign:"center", cursor:"pointer" }} onClick={()=>{ setBreakdownFilter("all"); setShowBreakdown(true); }}>
                <div>
                  <div style={{ fontSize:24,fontWeight:800 }}>{teamRecord.total}</div>
                  <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>試合数</div>
                </div>
                <div>
                  <div style={{ fontSize:24,fontWeight:800,color:C.accent }}>{teamRecord.rate}%</div>
                  <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>勝率</div>
                </div>
                <div>
                  <div style={{ fontSize:24,fontWeight:800 }}><WinLossText wins={teamRecord.wins} losses={teamRecord.losses} /></div>
                  <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>戦績</div>
                </div>
              </div>
              {/* ★ここのボタンで試合一覧を開けるため、「タップして試合一覧を見る ›」の文字は削除 */}
              <div style={{ display:"flex", gap:6, marginTop:12 }}>
                {[["all",`すべて（${teamRecord.total}）`,C.navy,C.navy],["win",`○ 勝ち（${teamRecord.wins}）`,C.accent,C.accentL],["lose",`× 負け（${teamRecord.losses}）`,C.red,C.redL]].map(([key,label,fg,bg])=>(
                  <button
                    key={key}
                    onClick={()=>{ setBreakdownFilter(key); setShowBreakdown(true); }}
                    style={{ flex:1, padding:"10px 2px", borderRadius:9, fontSize:13, fontWeight:800, cursor:"pointer", whiteSpace:"nowrap",
                      border:`1px solid ${C.border}`, background:key==="all"?"#fff":bg, color:key==="all"?C.navy:fg }}
                  >{label}</button>
                ))}
              </div>
            </div>
            <MonthlyTrendCard finishedMatches={finished} winFn={m=>winnerSideOf(m)==="A"} open={trendOpen} onToggle={()=>setTrendOpen(v=>!v)} />

            {/* ★見る内容：3つに統一（相手ペアの一覧はペアタブと同じ内容のため、ペアタブに任せる） */}
            <div style={{ display:"flex",gap:6,margin:"4px 0 8px" }}>
              {[["players","自チーム選手"],["pairs","自チームペア"],["opponents","対戦校"]].map(([v,l])=>(
                <button key={v}
                  style={{ ...S.togBtn(tab===v,C.navy),flex:1,fontSize:14.5,fontWeight:800,padding:"11px 2px" }}
                  onClick={()=>setTab(v)}
                >{l}</button>
              ))}
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:6, margin:"0 2px 8px" }}>
              <span style={{ fontSize:12, color:"#5a6478", minWidth:0 }}>
                {tab==="players" ? "タップで選手の戦績へ" : tab==="pairs" ? "タップでペアの詳細へ" : "タップで学校の詳細へ"}
              </span>
              <div style={{ display:"flex", gap:4, flexShrink:0 }}>
                {[["rate","勝率順"],["win","勝数順"],["lose","負数順"],["count","試合数順"]].map(([k,l])=>(
                  <button key={k} style={{ ...S.togBtn(sort===k,C.navy),fontSize:12,padding:"6px 6px",whiteSpace:"nowrap" }} onClick={()=>setSort(k)}>{l}</button>
                ))}
              </div>
            </div>

            {(() => {
              const rows = tab==="players" ? playerRows : tab==="pairs" ? pairRows : opponentRows;
              if (rows.length===0) return <div style={{ textAlign:"center",color:C.textSec,margin:"30px 0",fontSize:14 }}>この条件の試合記録がありません</div>;
              return rows.map(r=>(
                <div key={r.name}
                  style={{ ...S.card, padding:"13px 14px", marginBottom:8, cursor:"pointer", display:"flex",justifyContent:"space-between",alignItems:"center",gap:8 }}
                  onClick={()=>{
                    if (tab==="players") onOpenPlayer(r.name);
                    else if (tab==="opponents") onOpenOpponent(r.name);
                    else {
                      // ★ペアタブのそのペアを開く（ペアタブは開いたときに前回の選択を読み込むので、先に書き込んでおく）
                      const [n1, n2] = r.name.split("／");
                      writeScreenCache("pairAnalysis", { side:"own", ownPairKey: pairKeyOf(n1, n2), oppPairKey:"" });
                      onNavigate && onNavigate("pairAnalysis");
                    }
                  }}>
                  <span style={{ fontSize:15,fontWeight:700,minWidth:0 }}>{r.name}</span>
                  <span style={{ fontSize:14,color:"#5a6478",flexShrink:0 }}>{r.wins}勝{r.losses}敗（{r.total}試合）・<span style={{ fontSize:15,fontWeight:800,color:C.accent }}>{r.rate}%</span></span>
                </div>
              ));
            })()}

            {/* ★得点・ミス（対象選手を選んで合算）は「自チーム選手」のときだけ、一覧の下に折りたたみで出す */}
            {tab==="players" && (
              <>
                <div onClick={()=>setScoreOpen(v=>!v)}
                  style={{ ...S.card, padding:"13px 14px", margin:"12px 0 8px", display:"flex", justifyContent:"space-between", alignItems:"center", cursor:"pointer" }}>
                  <span style={{ fontSize:15, fontWeight:800, color:C.navy }}>📊 得点・ミス（対象選手を選べます）</span>
                  <span style={{ fontSize:14, color:C.textSec }}>{scoreOpen?"▲":"▼"}</span>
                </div>
                {scoreOpen && (ownDetailLoading && ownDetail.length===0
                  ? <div style={{ ...S.card, padding:20, textAlign:"center", color:C.textSec, fontSize:14 }}>集計中...</div>
                  : (<>
            {/* ★自チームの得点・ミス：対象選手をチェックで絞って集計する */}
            {ownPlayerNames.length>0 && (
              <>
                <div onClick={()=>setPickOpen(v=>!v)}
                  style={{ ...S.card, padding:13, marginBottom:8, display:"flex", justifyContent:"space-between", alignItems:"center", cursor:"pointer" }}>
                  <div style={{ fontSize:14.5, fontWeight:800, color:C.text }}>対象選手</div>
                  <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                    <span onClick={e=>{ e.stopPropagation(); setExcluded(excluded.size>0 ? new Set() : new Set(ownPlayerNames)); }}
                      style={{ fontSize:13, fontWeight:700, color:C.navy }}>{excluded.size>0 ? "すべて選択" : "すべて解除"}</span>
                    <span style={{ fontSize:14, color:C.textSec }}>{pickOpen?"▲":"▼"}</span>
                  </div>
                </div>
                {pickOpen && (
                  <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:10 }}>
                    {ownPlayerNames.map(n => {
                      const on = !excluded.has(n);
                      return (
                        <div key={n} onClick={()=>{
                            const nx = new Set(excluded);
                            if (on) nx.add(n); else nx.delete(n);
                            setExcluded(nx);
                          }}
                          style={{ display:"flex", alignItems:"center", gap:6, padding:"9px 12px", borderRadius:9, fontSize:13.5, fontWeight:700, cursor:"pointer",
                            border:`1.5px solid ${on?C.navy:C.border}`, background:on?"#eef2f7":C.white, color:on?C.navy:C.textSec }}>
                          <span style={{ width:17, height:17, borderRadius:4, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center",
                            border:`2px solid ${on?C.navy:C.border}`, background:on?C.navy:"transparent", color:C.white, fontSize:11, fontWeight:900 }}>{on?"✓":""}</span>
                          {n}
                        </div>
                      );
                    })}
                  </div>
                )}
                <div style={{ fontSize:12.5, color:C.textSec, textAlign:"center", marginBottom:12 }}>
                  {selectedOwnNames.length===ownPlayerNames.length
                    ? `${ownPlayerNames.length}名すべてを集計しています`
                    : selectedOwnNames.length===0 ? "選手を1人以上選んでください"
                    : `${selectedOwnNames.length}名を集計しています`}
                </div>

                {ownDetailLoading ? (
                  <div style={{ ...S.card, padding:20, textAlign:"center", color:C.textSec, fontSize:13 }}>集計中...</div>
                ) : ownAgg && ownAgg.total > 0 && (() => {
                  const tw = Object.entries(ownAgg.playsWin).sort((a,b)=>b[1]-a[1]).slice(0,5);
                  const te = Object.entries(ownAgg.playsErr).sort((a,b)=>b[1]-a[1]).slice(0,5);
                  const mx = Math.max(1, ...tw.map(x=>x[1]), ...te.map(x=>x[1]));
                  const Bar = ({label,count,color}) => (
                    <div style={{ display:"flex", alignItems:"center", fontSize:13.5, padding:"6px 0" }}>
                      <div style={{ width:100, color:C.text, fontWeight:700, whiteSpace:"nowrap" }}>{getPlayLabel(label)}</div>
                      <div style={{ flex:1, height:10, background:"#eef0f3", borderRadius:5, margin:"0 8px", overflow:"hidden" }}>
                        <div style={{ height:"100%", width:`${count/mx*100}%`, background:color, borderRadius:5 }}/>
                      </div>
                      <div style={{ width:30, textAlign:"right", fontWeight:800, color:C.navy }}>{count}</div>
                    </div>
                  );
                  return (
                    <div style={{ ...S.card, padding:14, marginBottom:12 }}>
                      <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:10 }}>📊 得点・ミス</div>
                      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:12 }}>
                        {[["決めた",ownAgg.winners],["ミス",ownAgg.errors],["決定率",`${Math.round(ownAgg.winners/ownAgg.total*100)}%`]].map(([k,v])=>(
                          <div key={k} style={{ textAlign:"center", padding:"12px 2px", background:C.gray, borderRadius:10 }}>
                            <div style={{ fontSize:21, fontWeight:800, color:C.navy }}>{v}</div>
                            <div style={{ fontSize:12, color:C.textSec, marginTop:3 }}>{k}</div>
                          </div>
                        ))}
                      </div>
                      <div style={{ fontSize:13, color:C.textSec, fontWeight:700, marginBottom:5 }}>✅ 決めた</div>
                      {tw.map(([l,c])=><Bar key={"w"+l} label={l} count={c} color={C.accent}/>)}
                      <div style={{ fontSize:13, color:C.textSec, fontWeight:700, margin:"12px 0 5px" }}>⚠️ ミス</div>
                      {te.map(([l,c])=><Bar key={"e"+l} label={l} count={c} color={C.red}/>)}
                      {finished.length > SCOPE_MAX && (
                        <div style={{ fontSize:12, color:"#8a92a0", marginTop:10, lineHeight:1.6 }}>
                          ※該当{finished.length}試合のうち、新しい{SCOPE_MAX}試合をもとに集計しています
                        </div>
                      )}
                    </div>
                  );
                })()}
              </>
            )}

                  </>))}
              </>
            )}
          </>
        )}
      </div>
      <NavBar active="stats" onNavigate={onNavigate}/>

      {showBreakdown && (
        <Modal onClose={()=>setShowBreakdown(false)}>
          <div style={{ maxHeight:"75vh", overflowY:"auto" }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:2 }}>
              <div style={{ fontSize:15, fontWeight:800 }}>総合成績の内訳</div>
              <button
                style={{ border:"none", background:"none", fontSize:20, color:C.textSec, cursor:"pointer", lineHeight:1, padding:0, marginLeft:8, marginRight:10, flex:"none" }}
                onClick={()=>setShowBreakdown(false)}
                aria-label="閉じる"
              >×</button>
            </div>
            <div style={{ fontSize:11.5, color:C.textSec, marginBottom:10 }}>
              {teamRecord.total}試合（{teamRecord.wins}勝{teamRecord.losses}敗）・タップすると試合詳細を開きます
            </div>
            <div style={{ display:"flex", gap:6, marginBottom:12 }}>
              {[["all",`すべて（${teamRecord.total}）`,C.navy,C.navy],["win",`○ 勝った試合（${teamRecord.wins}）`,C.accent,C.accentL],["lose",`× 負けた試合（${teamRecord.losses}）`,C.red,C.redL]].map(([key,label,fg,bg])=>{
                const active = breakdownFilter===key;
                return (
                  <button
                    key={key}
                    onClick={()=>setBreakdownFilter(key)}
                    style={{ flex:1, padding:"9px 4px", borderRadius:9, fontSize:10.5, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap",
                      border:`1px solid ${active?fg:C.border}`, background:active?bg:"#fff", color:active?(key==="all"?"#fff":fg):C.textSec }}
                  >{label}</button>
                );
              })}
            </div>
            {finished
              .filter(m => breakdownFilter==="all" ? true : breakdownFilter==="win" ? winnerSideOf(m)==="A" : winnerSideOf(m)==="B")
              .slice().sort((a,b)=> new Date(b.match_date)-new Date(a.match_date)).map(m=>{
              const aWin = winnerSideOf(m)==="A";
              const aPlayers = m.players.filter(p=>p.team==="A").sort((a,b)=>a.order_num-b.order_num);
              const bPlayers = m.players.filter(p=>p.team==="B").sort((a,b)=>a.order_num-b.order_num);
              const aNames = aPlayers.map(p=>p.player_name).join("/");
              const bNames = bPlayers.map(p=>p.player_name).join("/");
              const bClub = bPlayers[0]?.club_name || "";
              return (
                <div
                  key={m.id}
                  style={{ border:"1px solid "+C.border, borderRadius:10, padding:"10px 12px", marginBottom:8, cursor:"pointer" }}
                  onClick={()=>{ setShowBreakdown(false); onOpenMatch && onOpenMatch(m.id); }}
                >
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4 }}>
                    <span style={{ fontSize:10.5, color:C.textSec }}>{fmtDate(m.match_date)}{m.tournament_name ? ` · ${m.tournament_name}` : ""}</span>
                    <span style={{ fontSize:16, fontWeight:900, color:aWin?C.teamA:C.teamB }}>{m.match_score_a}-{m.match_score_b}</span>
                  </div>
                  <div style={{ fontSize:12.5, fontWeight: aWin?700:400, color: aWin?C.teamA:C.text }}>{aNames}</div>
                  <div style={{ fontSize:11, color:C.textSec, marginTop:2 }}>vs {bClub && `${bClub} `}{bNames}</div>
                </div>
              );
            })}
            {finished.filter(m => breakdownFilter==="all" ? true : breakdownFilter==="win" ? winnerSideOf(m)==="A" : winnerSideOf(m)==="B").length===0 && <div style={{ textAlign:"center", color:C.textSec, padding:"20px 0" }}>この条件の試合記録がありません</div>}
          </div>
        </Modal>
      )}
    </div>
  );
}


// ============================================================
// 特定選手の戦績画面（保護者の「お子さんの戦績」/選手本人の「自分の戦績」）
// ============================================================
function PlayerStatsScreen({ onBack, onOpen, initialPlayerName }) {
  const [loading, setLoading] = useState(true);
  const [roster, setRoster] = useState([]);
  const [linkedPlayerName, setLinkedPlayerName] = useState(null);
  const [playerName, setPlayerName] = useState(initialPlayerName || null); // 現在表示中の選手（未選択ならnull＝選択画面）
  const [matches, setMatches] = useState([]);
  const [period, setPeriod] = useState("all");
  const [sort, setSort] = useState("rate");
  const [mySchoolName, setMySchoolName] = useState(""); // ★自チーム同士の練習試合判定用
  // ★シーズン設定（起点日・呼び名）。設定されていれば「📌◯◯以降」を初期表示の期間にする
  const [seasonStart, setSeasonStart] = useState(null);
  const [seasonLabel, setSeasonLabel] = useState("");

  // ★前回開いたときのデータをすぐ表示し、裏で最新に差し替える。
  //   期間の初期値（シーズン）を決めるのは最初の1回だけ（裏の更新で選び直した期間が戻らないように）。
  const periodInitRef = useRef(false);
  useEffect(() => {
    const applyData = ([profile, season, rosterList, schools, list, simpleList]) => {
      if (season?.season_start_date) {
        setSeasonStart(season.season_start_date);
        setSeasonLabel(season.season_start_label || defaultSeasonLabel(season.season_start_date));
        if (!periodInitRef.current) setPeriod("season");
      }
      periodInitRef.current = true;
      setRoster(rosterList);
      if (profile?.linked_player_id) {
        const found = rosterList.find(p => p.id === profile.linked_player_id);
        setLinkedPlayerName(found?.player_name ?? null);
      }
      if (profile?.school_id) {
        const s = (schools || []).find(s => s.id === profile.school_id);
        if (s) setMySchoolName(s.name);
      }
      setMatches([...list, ...(simpleList||[])]);
      setLoading(false);
    };
    const cached = readScreenCache("playerStatsData");
    if (cached) applyData(cached);
    (async () => {
      // ★以前は「プロフィール→シーズン→選手マスター→学校→試合」と5回順番に待っていた。すべて同時に取得する。
      // ★トーナメント表で「結果だけ記録」した試合も勝敗に含める（チームタブ・ペアタブと同じ数え方にする）
      const fresh = await Promise.all([
        getMyProfile(), getMySchoolSeason(), getPlayerRoster(), getSchools(),
        getMatchesCached(), getSimpleRecordedDrawMatches(),
      ]);
      writeScreenCache("playerStatsData", fresh);
      applyData(fresh);
    })();
  }, []);

  // ★一覧から選手を選んで詳細表示に切り替える際、トップレベルのscreenは変わらないため
  // 画面の途中までスクロールしたままになるのを防ぎ、常にページ先頭から表示する
  useEffect(() => { window.scrollTo(0, 0); }, [playerName]);

  const periodMatches = period==="month1" ? withinLastDays(matches, 30)
    : (period==="season" && seasonStart) ? matches.filter(m => (m.match_date||"") >= seasonStart)
    : matches;
  const ownRoster = roster.filter(p=>p.is_own_team!==false);
  const myMatches = playerName ? periodMatches.filter(m => ownSideFor(m, playerName, mySchoolName)) : [];
  const finished = myMatches.filter(countsAsFinished);
  const rec = recordOf(finished, m=>winForPlayer(m, playerName, mySchoolName));

  // ペア（相方）別成績
  const byPartner = {};
  finished.forEach(m=>{
    const partner = partnerOf(m, playerName, mySchoolName) || "（相方不明）";
    (byPartner[partner] ??= []).push(m);
  });
  const partnerRows = Object.entries(byPartner).map(([name,list])=>({
    name, ...recordOf(list, m=>winForPlayer(m,playerName,mySchoolName)),
  }));
  partnerRows.sort(sortByRecord(sort));

  // 全試合（未確定含む）は日付の新しい順表示用に元のmyMatchesを使う（期間でフィルタ済み）
  const allFinishedForTrend = playerName ? matches.filter(m=>countsAsFinished(m) && ownSideFor(m, playerName, mySchoolName)) : [];

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <div style={{ display:"flex",alignItems:"center",gap:12 }}>
          <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={()=>{ if (playerName && !initialPlayerName) setPlayerName(null); else onBack(); }}>←</button>
          <span style={{ fontSize:18,fontWeight:800,color:C.white }}>{playerName ? `${playerName}さんの戦績` : "選手を選ぶ"}</span>
        </div>
      </div>
      <div style={{ padding:14, paddingBottom:40 }}>
        {loading ? (
          <div style={{ textAlign:"center",color:C.textSec,marginTop:60 }}>読み込み中...</div>
        ) : !playerName ? (
          // ★選手選択画面
          ownRoster.length===0 ? (
            <div style={{ textAlign:"center",color:C.textSec,marginTop:60 }}>選手マスター(自チーム)に選手が登録されていません。</div>
          ) : (
            <>
              <div style={{ fontSize:14,fontWeight:700,color:"#5a6478",marginBottom:10 }}>戦績を見たい選手を選んでください</div>
              {ownRoster.map(p=>(
                <div
                  key={p.id}
                  style={{ ...S.card, padding:"12px 14px", marginBottom:8, cursor:"pointer", display:"flex",justifyContent:"space-between",alignItems:"center" }}
                  onClick={()=>setPlayerName(p.player_name)}
                >
                  <span style={{ fontSize:16,fontWeight:700 }}>{p.player_name}{p.player_name===linkedPlayerName ? "（自分／お子さん）" : ""}</span>
                  <span style={{ fontSize:14,color:C.textSec }}>→</span>
                </div>
              ))}
            </>
          )
        ) : (
          <>
            {/* ★一番上は期間の切り替えだけ（並び替えは「ペア別の成績」の枠内に移動） */}
            <div style={{ display:"flex",gap:6,marginBottom:12 }}>
              {seasonStart && (
                <button style={{ ...S.togBtn(period==="season",C.navy),flex:1.4,fontSize:13,padding:"9px 4px" }} onClick={()=>setPeriod("season")}>📌 {seasonLabel}以降</button>
              )}
              <button style={{ ...S.togBtn(period==="month1",C.navy),flex:1,fontSize:13,padding:"9px 4px" }} onClick={()=>setPeriod("month1")}>直近1ヶ月</button>
              <button style={{ ...S.togBtn(period==="all",C.navy),flex:1,fontSize:13,padding:"9px 4px" }} onClick={()=>setPeriod("all")}>全期間</button>
            </div>

            {finished.length===0 ? (
              <div style={{ textAlign:"center",color:C.textSec,marginTop:40 }}>この期間の試合記録がありません</div>
            ) : (
              <>
                <div style={{ ...S.card, padding:16, marginBottom:16 }}>
                  <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1.35fr",textAlign:"center" }}>
                    <div>
                      <div style={{ fontSize:26,fontWeight:800,color:C.navy }}>{rec.total}</div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>試合数</div>
                    </div>
                    <div>
                      <div style={{ fontSize:26,fontWeight:800,color:C.accent }}>{rec.rate}%</div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>勝率</div>
                    </div>
                    <div>
                      <div style={{ fontSize:26,fontWeight:800,color:C.navy }}><WinLossText wins={rec.wins} losses={rec.losses} /></div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>戦績</div>
                    </div>
                  </div>
                </div>

                {/* ペア別成績 */}
                <div style={{ ...S.card, padding:16, marginBottom:16 }}>
                  <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,marginBottom:10 }}>
                    <div style={{ fontSize:15,fontWeight:800,color:C.navy }}>ペア別の成績</div>
                    {/* ★並び替えはペアが2組以上のときだけ出す（1組では並び替える意味がないため） */}
                    {partnerRows.length>=2 && (
                      <div style={{ display:"flex",gap:4 }}>
                        {[["rate","勝率順"],["win","勝数順"],["lose","負数順"],["count","試合数順"]].map(([k,l])=>(
                          <button key={k} style={{ ...S.togBtn(sort===k,C.navy),fontSize:12,padding:"6px 6px",whiteSpace:"nowrap" }} onClick={()=>setSort(k)}>{l}</button>
                        ))}
                      </div>
                    )}
                  </div>
                  {partnerRows.map(r=>(
                    <div key={r.name} style={{ display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:`1px solid ${C.border}` }}>
                      <span style={{ fontSize:15,fontWeight:700 }}>{r.name}</span>
                      <span style={{ fontSize:14,color:"#5a6478" }}>{r.wins}勝{r.losses}敗（{r.total}試合）・<span style={{ fontSize:15,fontWeight:800,color:C.accent }}>{r.rate}%</span></span>
                    </div>
                  ))}
                </div>

                <MonthlyTrendCard finishedMatches={allFinishedForTrend} winFn={m=>winForPlayer(m,playerName,mySchoolName)} />

                <div style={{ fontSize:15,fontWeight:800,color:C.navy,marginBottom:8 }}>試合一覧</div>
                {myMatches.map(m=>{
                  const win = m.status==="finished" ? winForPlayer(m,playerName,mySchoolName) : null;
                  const aP = m.players.filter(p=>p.team==="A").map(p=>p.player_name).join("/");
                  const bC = m.players.find(p=>p.team==="B")?.club_name??"";
                  const bP = m.players.filter(p=>p.team==="B").map(p=>p.player_name).join("/");
                  return (
                    <div key={m.id} style={{ ...S.card, padding:"12px 14px", marginBottom:8, cursor:"pointer" }} onClick={()=>onOpen(m.id)}>
                      <div style={{ display:"flex",justifyContent:"space-between",marginBottom:4 }}>
                        <span style={{ fontSize:14.5,fontWeight:800 }}>{m.tournament_name||"試合"}</span>
                        <span style={{ fontSize:13,color:"#5a6478",flexShrink:0,marginLeft:8 }}>{fmtDate(m.match_date)}</span>
                      </div>
                      <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:m.memo?6:0 }}>
                        <span style={{ fontSize:14,color:"#5a6478",lineHeight:1.5,minWidth:0 }}>{aP} vs {bC} {bP}</span>
                        <span style={{ fontSize:19,fontWeight:900,flexShrink:0,marginLeft:8,color:m.status==="finished"?(win?C.teamA:C.teamB):C.textSec }}>
                          {matchStatusShortLabel(m)}
                        </span>
                      </div>
                      {/* ★「途中終了」は記録中の画面から押すものに統一したため、ここには置かない */}
                      {m.memo && (
                        <div style={{ fontSize:13,color:C.navy,background:C.accentL,borderRadius:6,padding:"7px 9px",marginTop:4,lineHeight:1.5 }}>📝 {m.memo}</div>
                      )}
                    </div>
                  );
                })}
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ============================================================
// 対戦相手（学校）別の戦績画面
// ============================================================
// ★「187勝46敗」の表示。数字は大きく、「勝」「敗」は小さくして、狭い画面でも2段に折り返さないようにする
function WinLossText({ wins, losses }) {
  const u = { fontSize:"0.72em", fontWeight:800, margin:"0 1px" };
  return <span style={{ whiteSpace:"nowrap" }}>{wins}<span style={u}>勝</span>{losses}<span style={u}>敗</span></span>;
}

function OpponentStatsScreen({ schoolName, onBack, onOpen }) {
  const [loading, setLoading] = useState(true);
  const [matches, setMatches] = useState([]);
  const [period, setPeriod] = useState("all");
  const [sort, setSort] = useState("rate");
  const [mySchoolName, setMySchoolName] = useState("");
  const [detail, setDetail] = useState([]);       // points込みの詳細
  const [detailLoading, setDetailLoading] = useState(false);

  useEffect(() => { getMatchesCached().then(list=>{ setMatches(list); setLoading(false); }); }, []);
  useEffect(() => {
    (async () => {
      const [p, schools] = await Promise.all([getMyProfile(), getSchools()]);
      if (p?.school_id) {
        const sc = (schools||[]).find(x => x.id === p.school_id);
        if (sc) setMySchoolName(sc.name);
      }
    })();
  }, []);

  const oppOf = m => m.players.find(p=>p.team==="B")?.club_name || "";
  const periodMatches = period==="month1" ? withinLastDays(matches, 30) : matches;
  const vsMatches = periodMatches.filter(m => oppOf(m)===schoolName);
  const finished = vsMatches.filter(countsAsFinished);
  const rec = recordOf(finished, m=>winnerSideOf(m)==="A");

  // 相手選手別・相手ペア別（こちらの勝率で集計）
  const byOppPlayer = {};
  const byOppPair = {};
  finished.forEach(m=>{
    const bNames = m.players.filter(p=>p.team==="B").map(p=>p.player_name);
    bNames.forEach(name => { (byOppPlayer[name] ??= []).push(m); });
    const pairKey = bNames.slice().sort().join(" / ");
    if (pairKey) (byOppPair[pairKey] ??= []).push(m);
  });
  const oppPlayerRows = Object.entries(byOppPlayer).map(([name,list])=>({ name, ...recordOf(list, mm=>winnerSideOf(mm)==="A") }));
  oppPlayerRows.sort(sortByRecord(sort));
  const oppPairRows = Object.entries(byOppPair).map(([name,list])=>({ name, ...recordOf(list, mm=>winnerSideOf(mm)==="A") }));
  oppPairRows.sort(sortByRecord(sort));

  const allFinishedForTrend = matches.filter(m => countsAsFinished(m) && oppOf(m)===schoolName);

  // ★この学校との試合だけポイントを読み込む（学校を開いた時点で読むので待ち時間が短い）
  const finishedIdsKey = finished.map(m=>m.id).sort().join(",");
  useEffect(() => {
    const ids = finishedIdsKey ? finishedIdsKey.split(",") : [];
    if (ids.length === 0) { setDetail([]); return; }
    let cancelled = false;
    (async () => {
      setDetailLoading(true);
      const full = await getFullMatchesByIds(ids);
      if (!cancelled) { setDetail(full); setDetailLoading(false); }
    })();
    return () => { cancelled = true; };
  }, [finishedIdsKey]);

  // ★自チーム側の得点・ミス（この学校と戦ったときの数字）
  const vsAgg = useMemo(() => {
    if (detail.length === 0) return null;
    const names = new Set();
    detail.forEach(m => m.players.filter(p=>p.team==="A").forEach(p => names.add(p.player_name)));
    const list = [...names];
    if (list.length === 0) return null;
    const base = aggregatePlayerStats(detail, list[0], mySchoolName);
    const sum = { ...base };
    const numKeys = ["total","winners","errors","serve1st","serve2nd","serveDf","serve1stWin","serve2ndWin"];
    const mapKeys = ["playsWin","playsErr"];
    numKeys.forEach(k => { sum[k] = 0; });
    mapKeys.forEach(k => { sum[k] = {}; });
    list.forEach(n => {
      const a = aggregatePlayerStats(detail, n, mySchoolName);
      numKeys.forEach(k => { sum[k] += (a[k] ?? 0); });
      mapKeys.forEach(k => { for (const key in (a[k]??{})) sum[k][key] = (sum[k][key]??0) + a[k][key]; });
    });
    return sum;
  }, [detail, mySchoolName]);

  // ★相性：相手ペアごとに、自チームの誰が当たって何勝何敗か
  const compatRows = useMemo(() => {
    const byOpp = {};
    finished.forEach(m => {
      const op = pairOnSide(m, "B");
      const mine = pairOnSide(m, "A");
      if (!op || !mine) return;
      const rec = (byOpp[op.key] ??= { label:op.label, w:0, l:0, own:{} });
      const win = winnerSideOf(m)==="A";
      if (win) rec.w++; else rec.l++;
      const o = (rec.own[mine.key] ??= { label:mine.label, w:0, l:0, matches:[] });
      if (win) o.w++; else o.l++;
      o.matches.push(m);
    });
    return Object.values(byOpp)
      .map(r => ({ ...r, own: Object.values(r.own).sort((a,b)=>(b.w+b.l)-(a.w+a.l)) }))
      .sort((a,b)=> (b.w+b.l)-(a.w+a.l));
  }, [finished]);

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <div style={{ display:"flex",alignItems:"center",gap:12 }}>
          <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onBack}>←</button>
          <span style={{ fontSize:18,fontWeight:800,color:C.white }}>{schoolName}との対戦成績</span>
        </div>
      </div>
      <div style={{ padding:14, paddingBottom:40 }}>
        {loading ? (
          <div style={{ textAlign:"center",color:C.textSec,marginTop:60 }}>読み込み中...</div>
        ) : (
          <>
            <PeriodSortBar period={period} setPeriod={setPeriod} sort={sort} setSort={setSort} />
            {finished.length===0 ? (
              <div style={{ textAlign:"center",color:C.textSec,marginTop:40 }}>この期間の対戦記録がありません</div>
            ) : (
              <>
                <div style={{ ...S.card, padding:16, marginBottom:16 }}>
                  <div style={{ fontSize:12,fontWeight:700,color:C.navy,marginBottom:10 }}>総合成績（自チーム視点）</div>
                  <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1.35fr",textAlign:"center" }}>
                    <div>
                      <div style={{ fontSize:24,fontWeight:800 }}>{rec.total}</div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>試合数</div>
                    </div>
                    <div>
                      <div style={{ fontSize:24,fontWeight:800,color:C.accent }}>{rec.rate}%</div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>勝率</div>
                    </div>
                    <div>
                      <div style={{ fontSize:24,fontWeight:800 }}><WinLossText wins={rec.wins} losses={rec.losses} /></div>
                      <div style={{ fontSize:13,fontWeight:700,color:"#5a6478",marginTop:2 }}>戦績</div>
                    </div>
                  </div>
                </div>

                <div style={{ ...S.card, padding:16, marginBottom:16 }}>
                  <div style={{ fontSize:12,fontWeight:700,color:C.navy,marginBottom:10 }}>相手選手別の成績（自チームの勝率）</div>
                  {oppPlayerRows.map(r=>(
                    <div key={r.name} style={{ display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:`1px solid ${C.border}` }}>
                      <span style={{ fontSize:14 }}>{r.name}</span>
                      <span style={{ fontSize:13,color:C.textSec,whiteSpace:"nowrap",marginLeft:8 }}>{r.wins}勝{r.losses}敗（{r.total}試合）・<span style={{ fontWeight:700,color:C.accent }}>{r.rate}%</span></span>
                    </div>
                  ))}
                </div>

                <div style={{ ...S.card, padding:16, marginBottom:16 }}>
                  <div style={{ fontSize:12,fontWeight:700,color:C.navy,marginBottom:10 }}>相手ペア別の成績（自チームの勝率）</div>
                  {oppPairRows.map(r=>(
                    <div key={r.name} style={{ display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:`1px solid ${C.border}` }}>
                      <span style={{ fontSize:14 }}>{r.name}</span>
                      <span style={{ fontSize:13,color:C.textSec,whiteSpace:"nowrap",marginLeft:8 }}>{r.wins}勝{r.losses}敗（{r.total}試合）・<span style={{ fontWeight:700,color:C.accent }}>{r.rate}%</span></span>
                    </div>
                  ))}
                </div>

                <MonthlyTrendCard finishedMatches={allFinishedForTrend} winFn={m=>winnerSideOf(m)==="A"} />

                {/* ★この学校との得点・ミス（自チーム側） */}
                {detailLoading ? (
                  <div style={{ ...S.card, padding:20, textAlign:"center", color:C.textSec, fontSize:13 }}>集計中...</div>
                ) : vsAgg && vsAgg.total > 0 && (() => {
                  const tw = Object.entries(vsAgg.playsWin).sort((a,b)=>b[1]-a[1]).slice(0,5);
                  const te = Object.entries(vsAgg.playsErr).sort((a,b)=>b[1]-a[1]).slice(0,5);
                  const mx = Math.max(1, ...tw.map(x=>x[1]), ...te.map(x=>x[1]));
                  const Bar = ({label,count,color}) => (
                    <div style={{ display:"flex", alignItems:"center", fontSize:13.5, padding:"6px 0" }}>
                      <div style={{ width:100, color:C.text, fontWeight:700, whiteSpace:"nowrap" }}>{getPlayLabel(label)}</div>
                      <div style={{ flex:1, height:10, background:"#eef0f3", borderRadius:5, margin:"0 8px", overflow:"hidden" }}>
                        <div style={{ height:"100%", width:`${count/mx*100}%`, background:color, borderRadius:5 }}/>
                      </div>
                      <div style={{ width:30, textAlign:"right", fontWeight:800, color:C.navy }}>{count}</div>
                    </div>
                  );
                  return (
                    <div style={{ ...S.card, padding:14, marginBottom:12 }}>
                      <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:10 }}>📊 この学校との得点・ミス</div>
                      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8, marginBottom:12 }}>
                        {[["決めた",vsAgg.winners],["ミス",vsAgg.errors],["決定率",`${Math.round(vsAgg.winners/vsAgg.total*100)}%`]].map(([k,v])=>(
                          <div key={k} style={{ textAlign:"center", padding:"12px 2px", background:C.gray, borderRadius:10 }}>
                            <div style={{ fontSize:21, fontWeight:800, color:C.navy }}>{v}</div>
                            <div style={{ fontSize:12, color:C.textSec, marginTop:3 }}>{k}</div>
                          </div>
                        ))}
                      </div>
                      <div style={{ fontSize:13, color:C.textSec, fontWeight:700, marginBottom:5 }}>✅ 決めた</div>
                      {tw.map(([l,c])=><Bar key={"w"+l} label={l} count={c} color={C.accent}/>)}
                      <div style={{ fontSize:13, color:C.textSec, fontWeight:700, margin:"12px 0 5px" }}>⚠️ ミス</div>
                      {te.map(([l,c])=><Bar key={"e"+l} label={l} count={c} color={C.red}/>)}
                    </div>
                  );
                })()}

                {/* ★相性：相手ペアごとに、自チームの誰が当たって何勝何敗か */}
                {compatRows.length > 0 && (
                  <>
                    <div style={{ fontSize:15, fontWeight:800, color:C.navy, marginBottom:4 }}>🤝 相性</div>
                    <div style={{ fontSize:12.5, color:C.textSec, marginBottom:8, lineHeight:1.7 }}>
                      相手ペアごとに、自チームの誰が当たって何勝何敗かが分かります
                    </div>
                    {compatRows.map(r => (
                      <div key={r.label} style={{ ...S.card, padding:"12px 13px", marginBottom:8 }}>
                        <div style={{ fontSize:14.5, fontWeight:800, color:C.text, marginBottom:8 }}>
                          <span style={{ fontSize:13, fontWeight:900, color:C.teamB, marginRight:4 }}>vs</span>{r.label}　<span style={{ fontSize:13, fontWeight:700, color:C.textSec }}>{r.w}勝{r.l}敗</span>
                        </div>
                        {r.own.map(o => (
                          <div key={o.label} style={{ display:"flex", justifyContent:"space-between", alignItems:"center",
                            background:C.gray, borderRadius:9, padding:"10px 11px", marginBottom:6 }}>
                            <div>
                              <div style={{ fontSize:14, fontWeight:800, color:C.text }}>{o.label}</div>
                              <div style={{ fontSize:12.5, color:C.textSec, marginTop:1 }}>{o.w+o.l}試合</div>
                            </div>
                            <div style={{ fontSize:14, fontWeight:900, color:C.text }}>{o.w}勝{o.l}敗</div>
                          </div>
                        ))}
                      </div>
                    ))}
                  </>
                )}

                <div style={{ fontSize:13,fontWeight:700,color:C.navy,marginBottom:8 }}>試合一覧</div>
                {vsMatches.map(m=>{
                  const win = m.status==="finished" ? winnerSideOf(m)==="A" : null;
                  const aP = m.players.filter(p=>p.team==="A").map(p=>p.player_name).join("/");
                  const bP = m.players.filter(p=>p.team==="B").map(p=>p.player_name).join("/");
                  return (
                    <div key={m.id} style={{ ...S.card, padding:"12px 14px", marginBottom:8, cursor:"pointer" }} onClick={()=>onOpen(m.id)}>
                      <div style={{ display:"flex",justifyContent:"space-between",marginBottom:4 }}>
                        <span style={{ fontSize:12,fontWeight:700 }}>{m.tournament_name||"試合"}</span>
                        <span style={{ fontSize:11,color:C.textSec }}>{fmtDate(m.match_date)}</span>
                      </div>
                      <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:m.memo?6:0 }}>
                        <span style={{ fontSize:12,color:C.textSec }}>{aP} vs {bP}</span>
                        <span style={{ fontSize:14,fontWeight:800,color:m.status==="finished"?(win?C.teamA:C.teamB):C.textSec }}>
                          {matchStatusShortLabel(m)}
                        </span>
                      </div>
                      {m.memo && (
                        <div style={{ fontSize:11,color:C.navy,background:C.accentL,borderRadius:6,padding:"6px 8px",marginTop:4 }}>📝 {m.memo}</div>
                      )}
                    </div>
                  );
                })}
              </>
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ============================================================
// セットアップ用 固定コンポーネント（関数外定義でフォーカスを保持）
// ============================================================
function FormSec({ title, children }) {
  return (
    <div style={{ marginBottom:14 }}>
      <div style={{ fontSize:14,fontWeight:800,color:C.navy,marginBottom:7 }}>{title}</div>
      <div style={{ background:C.white,borderRadius:12,border:`1px solid ${C.border}`,overflow:"visible" }}>{children}</div>
    </div>
  );
}
// ★必須項目の目印（赤い丸）。FormRow の required と、フォーム上部の凡例で使う
const RequiredDot = () => (
  // ★目立つように：以前の8pxから大きくし、薄い赤の輪を付けた
  <span style={{ display:"inline-block", width:12, height:12, borderRadius:"50%", background:C.red, boxShadow:"0 0 0 3px rgba(229,57,53,0.22)", marginLeft:3, marginRight:9, verticalAlign:"middle", flexShrink:0 }} />
);

function FormRow({ label, labelRight, children, required }) {
  return (
    <div style={{ padding:"12px 14px",borderBottom:`1px solid ${C.border}` }}>
      <div style={{ display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:4 }}>
        <label style={{ fontSize:13,fontWeight:700,color:"#5a6478",display:"flex",alignItems:"center" }}>{required && <RequiredDot />}{label}</label>
        {labelRight}
      </div>
      {children}
    </div>
  );
}

// schools（{name,prefecture}[] または {prefecture}を持つ配列）から、絞り込み候補の都道府県一覧を作る
function knownPrefsFrom(schools) {
  return Array.from(new Set(schools.map(s=>s.prefecture).filter(Boolean))).sort((a,b)=>a.localeCompare(b,"ja"));
}

// ★学校名選択欄のラベル横に置く、小さな都道府県絞り込みプルダウン
function PrefMiniFilter({ value, onChange, options }) {
  if (options.length === 0) return null;
  return (
    <select
      value={value}
      onChange={e=>onChange(e.target.value)}
      style={{ fontSize:10,padding:"3px 6px",borderRadius:6,border:`1px solid ${C.border}`,background:C.white,color:C.textSec,maxWidth:130 }}
    >
      <option value="">都道府県で絞込み</option>
      {options.map(p => <option key={p} value={p}>{p}</option>)}
    </select>
  );
}

// 会場名入力＋候補サジェストコンポーネント
// 何回戦の選択肢（決め打ちリスト＋自由入力）
const ROUND_OPTIONS = [
  "リーグ","トーナメント",
  "1回戦","2回戦","3回戦","4回戦","5回戦",
  "準々決勝","準決勝","3位決定戦","決勝",
];
function RoundField({ value, onChange, placeholder }) {
  const isPreset = ROUND_OPTIONS.includes(value);
  const [customMode, setCustomMode] = useState(!!value && !isPreset);
  return (
    <div>
      <select
        style={S.inp}
        value={customMode ? "__custom__" : (value || "")}
        onChange={e => {
          if (e.target.value === "__custom__") { setCustomMode(true); onChange(""); }
          else { setCustomMode(false); onChange(e.target.value); }
        }}
      >
        <option value="">リストから選択</option>
        <option value="__custom__">✏️ 自由入力する</option>
        {ROUND_OPTIONS.map(r => <option key={r} value={r}>{r}</option>)}
      </select>
      {customMode && (
        <input
          style={{ ...S.inp, marginTop:8 }}
          placeholder={placeholder || "例：準々決勝"}
          value={value ?? ""}
          onChange={e => onChange(e.target.value)}
        />
      )}
    </div>
  );
}

function VenueField({ value, onChange, venues, placeholder }) {
  const safeValue = value ?? "";
  const safeVenues = venues ?? [];
  const filtered = safeValue.trim() ? safeVenues.filter(v => v.includes(safeValue.trim())) : safeVenues.slice(0, 5);
  const [open, setOpen] = useState(false);
  return (
    <div style={{ position:"relative" }}>
      <input style={S.inp} placeholder={placeholder || "例：○○市民コート"} value={safeValue}
        onChange={e => { onChange(e.target.value); setOpen(true); }}
        onFocus={() => setOpen(true)}
        onBlur={() => setTimeout(() => setOpen(false), 200)}
      />
      {open && filtered.length > 0 && (
        <div style={{ position:"absolute", top:"100%", left:0, right:0, background:C.white, border:"1px solid "+C.border, borderRadius:8, zIndex:200, boxShadow:"0 4px 16px rgba(0,0,0,0.15)", maxHeight:200, overflowY:"auto" }}>
          {filtered.map(v => (
            <div key={v} style={{ padding:"12px 14px", fontSize:13, color:C.text, borderBottom:"1px solid "+C.border, cursor:"pointer", background:C.white }}
              onMouseDown={e => { e.preventDefault(); onChange(v); setOpen(false); }}
            >{v}</div>
          ))}
        </div>
      )}
    </div>
  );
}

// ★大会の会場欄：前に使った会場を新しい順に最大10件。文字を入れると、その文字を含む会場にしぼり込む。
//   リンクがある会場には印を付け、選んだときに onPick で会場リンクも入れられるようにする。
function VenueHistoryField({ value, onChange, onPick, history, placeholder }) {
  const [open, setOpen] = useState(false);
  const safeValue = value ?? "";
  const q = safeValue.trim();
  const list = (history ?? []).filter(h => !q || h.name.includes(q)).slice(0, 10);
  const md = (d) => d ? `${Number(d.slice(5,7))}/${Number(d.slice(8,10))}` : "";
  const hl = (name) => {
    if (!q) return name;
    const i = name.indexOf(q);
    if (i < 0) return name;
    return <>{name.slice(0,i)}<span style={{ background:"#fff3b0" }}>{name.slice(i, i+q.length)}</span>{name.slice(i+q.length)}</>;
  };
  return (
    <div style={{ position:"relative" }}>
      <input style={S.inp} placeholder={placeholder || "例：○○市民コート"} value={safeValue}
        onChange={e => { onChange(e.target.value); setOpen(true); }}
        onFocus={() => setOpen(true)}
        onBlur={() => setTimeout(() => setOpen(false), 200)}
      />
      {open && list.length > 0 && (
        <div style={{ position:"absolute", top:"100%", left:0, right:0, background:C.white, border:"1px solid "+C.border, borderRadius:10, zIndex:200, boxShadow:"0 6px 18px rgba(0,0,0,0.14)", maxHeight:300, overflowY:"auto", WebkitOverflowScrolling:"touch" }}>
          <div style={{ fontSize:11.5, color:C.textSec, background:"#f5f6f8", padding:"6px 12px", fontWeight:700 }}>{q ? `「${q}」を含む会場` : "前に使った会場（新しい順）"}</div>
          {list.map(h => (
            <div key={h.name} style={{ display:"flex", alignItems:"center", gap:8, padding:"11px 12px", fontSize:14.5, color:C.text, borderTop:"1px solid #eef0f3", cursor:"pointer", background:C.white }}
              onMouseDown={e => { e.preventDefault(); (onPick || (x=>onChange(x.name)))(h); setOpen(false); }}>
              <span style={{ minWidth:0 }}>{hl(h.name)}</span>
              {h.link && <span style={{ flexShrink:0, fontSize:11, fontWeight:800, color:"#0b6e75", background:"#e3f4f2", borderRadius:6, padding:"1px 6px" }}>🔗リンクあり</span>}
              <span style={{ marginLeft:"auto", flexShrink:0, fontSize:11, color:"#8a92a0" }}>{md(h.date)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ★学校名の誤入力防止用：入力しながら候補が絞り込まれるサジェスト式の入力欄
// schools は {name, prefecture}[] 形式（prefectureはnullの場合あり）
// prefFilter: 親から渡される都道府県絞り込み値（任意）
function SchoolField({ value, onChange, schools, placeholder, prefFilter }) {
  const [open, setOpen] = useState(false);
  const safeValue = value || "";
  const visibleSchools = prefFilter ? schools.filter(s => s.prefecture === prefFilter) : schools;
  const q = safeValue.trim();
  const filtered = q ? visibleSchools.filter(s => s.name.includes(q)) : visibleSchools;

  return (
    <div style={{ position:"relative" }}>
      <input
        style={S.inp}
        placeholder={placeholder}
        value={safeValue}
        onChange={e => { onChange(e.target.value); setOpen(true); }}
        onFocus={() => setOpen(true)}
        onBlur={() => setTimeout(() => setOpen(false), 200)}
      />
      {open && filtered.length > 0 && (
        <div style={{ position:"absolute", top:"100%", left:0, right:0, background:C.white, border:"1px solid "+C.border, borderRadius:8, zIndex:200, boxShadow:"0 4px 16px rgba(0,0,0,0.15)", maxHeight:220, overflowY:"auto", WebkitOverflowScrolling:"touch", overscrollBehavior:"contain", touchAction:"pan-y" }}>
          <div style={{ padding:"4px 14px", fontSize:10, color:C.textSec, background:"#f5f6f8" }}>{filtered.length}件中 最大200件を表示（枠内をスクロールできます）</div>
          {filtered.slice(0, 200).map(s => (
            <div key={s.name} style={{ padding:"12px 14px", fontSize:13, color:C.text, borderBottom:"1px solid "+C.border, cursor:"pointer", background:C.white }}
              onMouseDown={e => { e.preventDefault(); onChange(s.name); setOpen(false); }}
            >{s.name}{s.prefecture ? `（${s.prefecture}）` : ""}</div>
          ))}
        </div>
      )}
      {value && (
        <div style={{ fontSize:12, color:"#5a6478", marginTop:5 }}>✎ 「{value}A」のように自由に文字を足すこともできます</div>
      )}
    </div>
  );
}

// ★プロフィール・新規登録用：学校マスターから選ぶだけ（自由入力不可、管理者のみがマスターを編集できる）
// prefFilter: 親から渡される都道府県絞り込み値（任意）
function SchoolIdSelect({ value, onChange, schools, prefFilter, genderCategory }) {
  if (schools.length === 0) {
    return (
      <div style={{ fontSize:12,color:C.textSec,padding:"10px 0" }}>
        学校がまだ登録されていません。管理者に学校の追加を依頼してください。
      </div>
    );
  }

  const visibleSchools = schools
    .filter(s => !prefFilter || s.prefecture === prefFilter)
    .filter(s => schoolMatchesGender(s, genderCategory));

  return (
    <select
      style={{ ...S.inp, background:"transparent" }}
      value={value || ""}
      onChange={e=>onChange(e.target.value || null)}
    >
      <option value="">選択してください</option>
      {visibleSchools.map(s => {
        const tags = [categoryLabel(s.category), s.prefecture].filter(Boolean).join("・");
        return <option key={s.id} value={s.id}>{s.name}{tags ? `（${tags}）` : ""}</option>;
      })}
    </select>
  );
}

// ★新規登録画面用：学校名をキーワード入力→候補一覧から選ぶ形式のフィールド。
// SchoolIdSelect（プルダウン）と違い、試合作成の「チーム名/学校名」入力と同じ操作感にするためのもの。
// ただしこちらは実在する学校（school_id）を必ず1つ選ぶ必要があるため、候補をタップして確定するまでは
// 「未選択」のまま（自由な文字列では確定できない）。
function SchoolIdSearchField({ value, onChange, schools, prefFilter, placeholder }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const selected = schools.find(s => s.id === value) || null;

  if (schools.length === 0) {
    return (
      <div style={{ fontSize:12,color:C.textSec,padding:"10px 0" }}>
        学校がまだ登録されていません。管理者に学校の追加を依頼してください。
      </div>
    );
  }

  const visibleSchools = prefFilter ? schools.filter(s => s.prefecture === prefFilter) : schools;
  const q = query.trim();
  const filtered = q ? visibleSchools.filter(s => s.name.includes(q)) : visibleSchools;

  if (selected) {
    return (
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", background:C.accentL, border:`1.5px solid ${C.accent}`, borderRadius:8, padding:"10px 12px" }}>
        <span style={{ fontSize:14, fontWeight:800, color:C.navy }}>✅ {selected.name}</span>
        <span style={{ fontSize:12, color:C.textSec, cursor:"pointer", textDecoration:"underline" }} onClick={()=>{ onChange(null); setQuery(""); }}>変更する</span>
      </div>
    );
  }

  return (
    <div style={{ position:"relative" }}>
      <input
        style={S.inp}
        placeholder={placeholder || "学校名を入力（例：東福岡）"}
        value={query}
        onChange={e=>{ setQuery(e.target.value); setOpen(true); }}
        onFocus={()=>setOpen(true)}
        onBlur={()=>setTimeout(()=>setOpen(false), 200)}
        autoCapitalize="none"
      />
      {open && filtered.length > 0 && (
        <div style={{ position:"absolute", top:"100%", left:0, right:0, background:C.white, border:"1px solid "+C.border, borderRadius:8, zIndex:200, boxShadow:"0 4px 16px rgba(0,0,0,0.15)", maxHeight:220, overflowY:"auto", WebkitOverflowScrolling:"touch" }}>
          <div style={{ padding:"4px 14px", fontSize:10, color:C.textSec, background:"#f5f6f8" }}>{filtered.length}件</div>
          {filtered.slice(0, 200).map(s => {
            const tags = [categoryLabel(s.category), s.prefecture].filter(Boolean).join("・");
            return (
              <div key={s.id} style={{ padding:"12px 14px", fontSize:13, color:C.text, borderBottom:"1px solid "+C.border, cursor:"pointer", background:C.white }}
                onMouseDown={e=>{ e.preventDefault(); onChange(s.id); setQuery(""); setOpen(false); }}
              >{s.name}{tags ? `（${tags}）` : ""}</div>
            );
          })}
        </div>
      )}
      {!prefFilter && (
        <div style={{ fontSize:11, color:"#aaa", marginTop:4 }}>💡 都道府県を選ぶと候補が絞られます</div>
      )}
    </div>
  );
}

// ============================================================
// 試合セットアップ
// ============================================================
function MatchSetup({ onSave, onCancel, sourceMatchId, editMatchId, initialMatchType, onScheduled, headerLabel, prefillTournament, prefillRound, prefillVenue, prefillDate, prefillOpponent, prefillIsYounger, isTeamMatchGame, teamMatchMyDivision, teamMatchOppDivision, teamMatchMySchoolId, onSavePairOnly, lockTournament, tournamentStartDate, tournamentEndDate, tournamentParticipantIds }) {
  const [ready, setReady] = useState(!editMatchId && !sourceMatchId);
  const [editing, setEditing] = useState(null);
  const [source,  setSource]  = useState(null);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const [e, s] = await Promise.all([
          editMatchId ? getMatch(editMatchId) : Promise.resolve(null),
          sourceMatchId ? getMatch(sourceMatchId) : Promise.resolve(null),
        ]);
        if (cancelled) return;
        setEditing(e); setSource(s); setReady(true);
      } catch (err) {
        if (cancelled) return;
        alert("試合データの読み込みに失敗しました。もう一度お試しください。\n" + (err.message || err));
        onCancel && onCancel();
      }
    }
    load();
    return () => { cancelled = true; };
  }, [editMatchId, sourceMatchId]);

  if (!ready) {
    return (
      <div style={S.page}>
        <div style={S.hdr}><span style={{ fontSize:18,fontWeight:800,color:C.white }}>読み込み中...</span></div>
      </div>
    );
  }
  // ★key を付けて、編集対象・コピー元が変わったら必ず作り直す。
  //   付けないと前回開いたときの入力内容や「予定として登録済みのID」が残ったままになり、
  //   別の試合を上書きしてしまう恐れがある。
  return <MatchSetupForm key={`${editMatchId || "new"}_${sourceMatchId || "none"}`} onSave={onSave} onCancel={onCancel} editing={editing} source={source} initialMatchType={initialMatchType} onScheduled={onScheduled} headerLabel={headerLabel} prefillTournament={prefillTournament} prefillRound={prefillRound} prefillVenue={prefillVenue} prefillDate={prefillDate} prefillOpponent={prefillOpponent} prefillIsYounger={prefillIsYounger} isTeamMatchGame={isTeamMatchGame} teamMatchMyDivision={teamMatchMyDivision} teamMatchOppDivision={teamMatchOppDivision} teamMatchMySchoolId={teamMatchMySchoolId} onSavePairOnly={onSavePairOnly} lockTournament={lockTournament} tournamentStartDate={tournamentStartDate} tournamentEndDate={tournamentEndDate} tournamentParticipantIds={tournamentParticipantIds} />;
}

function MatchSetupForm({ onSave, onCancel, editing, source, initialMatchType, onScheduled, headerLabel, prefillTournament, prefillRound, prefillVenue, prefillDate, prefillOpponent, prefillIsYounger, isTeamMatchGame, teamMatchMyDivision, teamMatchOppDivision, teamMatchMySchoolId, onSavePairOnly, lockTournament, tournamentStartDate, tournamentEndDate, tournamentParticipantIds }) {
  const base    = editing || source;

  // 試合開始済み（active/finished）の場合のみ形式設定をロック
  // 予定（scheduled）は編集可能
  const locked = !!editing && (editing.status === "active" || editing.status === "finished");

  const aBase = base ? base.players.find(p=>p.team==="A") : null;
  const aBase2 = base ? base.players.find(p=>p.team==="A" && p.order_num===2) : null;
  const bBase = base ? base.players.find(p=>p.team==="B") : null;
  const bBase2 = base ? base.players.find(p=>p.team==="B" && p.order_num===2) : null;

  // ★各フィールドを独立したstateに分離（フォーカス維持のため）
  const [matchDate,      setMatchDate]      = useState(base?.match_date ?? prefillDate ?? today());
  const [venue,          setVenue]          = useState(base?.venue ?? prefillVenue ?? "");
  const [tournamentName, setTournamentName] = useState(base?.tournament_name ?? prefillTournament ?? "");
  const [round,          setRound]          = useState(base?.round ?? prefillRound ?? "");
  const [matchNumber,    setMatchNumber]    = useState(base?.match_number ?? "");
  const [matchType,      setMatchType]      = useState(base?.match_type ?? initialMatchType ?? "tournament");
  const [courtNumber,    setCourtNumber]    = useState(base?.court_number ?? "");
  const [isYounger,      setIsYounger]      = useState(base ? (base?.is_younger !== false ? true : false) : (prefillIsYounger !== undefined && prefillIsYounger !== null ? prefillIsYounger : true)); // ★未指定のときは若番を初期値にする（ペア番号を入れれば自動判定で上書きされる）
  const [gameFormat,     setGameFormat]     = useState(base?.game_format ?? 7);
  const [isDoubles,      setIsDoubles]      = useState(base?.is_doubles ?? true);
  const [firstServer,    setFirstServer]    = useState(base?.first_server ?? null);
  // ★サーブ・レシーブ順（各ペアの「サーブの1人目」「レシーブの1人目」）。試合情報で管理する。
  //   初期値は登録順の1人目。レシーブがnullの間は「サーブと同じ人」。
  const [orders, setOrders] = useState({
    order_a: base?.order_a === "p2" ? "p2" : "p1",
    receive_order_a: base?.receive_order_a ?? null,
    order_b: base?.order_b === "p2" ? "p2" : "p1",
    receive_order_b: base?.receive_order_b ?? null,
  });
  // 保存時にA/Bを入れ替える場合（自チームが相手欄に入っていた時）は、順番も一緒に入れ替える
  const ordersFor = (swap) => swap
    ? { order_a: orders.order_b, receive_order_a: orders.receive_order_b ?? null, order_b: orders.order_a, receive_order_b: orders.receive_order_a ?? null }
    : { order_a: orders.order_a, receive_order_a: orders.receive_order_a ?? null, order_b: orders.order_b, receive_order_b: orders.receive_order_b ?? null };
  const [aClub,  setAClub]  = useState(aBase?.club_name ?? "");
  const [aP1,    setAP1]    = useState(aBase?.player_name ?? "");
  const [aP2,    setAP2]    = useState(aBase2?.player_name ?? "");
  const [bClub,  setBClub]  = useState(bBase?.club_name ?? prefillOpponent ?? "");
  const [bP1,    setBP1]    = useState(bBase?.player_name ?? "");
  const [bP2,    setBP2]    = useState(bBase2?.player_name ?? "");

  const isScheduledEdit = editing?.status === "scheduled";
  // ★対戦相手の選手名が分からない場合に「あ」「ああ」等の仮名前を毎回入力する手間を無くすため、
  //   相手選手名は空欄でも保存できるようにする（保存時に「選手A」「選手B」を自動で補う）。
  //   自チーム側の選手名だけは必須のままにする。
  const canSave = aP1.trim() && (!isDoubles || aP2.trim()) && isYounger !== null;
  const withPlaceholder = (v, label) => (v && v.trim()) || label;

  const [saving, setSaving] = useState(false);
  const [scheduledId, setScheduledId] = useState(editing?.status==="scheduled" ? editing.id : null); // 予定登録済みのID
  const [serveSelectForSave, setServeSelectForSave] = useState(null);
  const [showMatchInfo, setShowMatchInfo] = useState(false); // 試合情報の表示/非表示（デフォルト：非表示）

  // ★選手マスター（同じ学校のメンバーで共有）を読み込み、入力時にチップで選べるようにする
  const [roster, setRoster] = useState([]);
  useEffect(() => { getPlayerRoster().then(setRoster); }, []);
  // 自チーム・相手チームとも team_name で絞り込む（同じ仕様）
  const ownRosterAll = roster; // チップ表示時に team_name で絞る
  const oppRosterBase = roster;
  // 同校対決：相手チームが自チームと同じ学校名の場合、自チームの選手もチップに表示
  const isSameSchool = aClub && bClub && aClub.trim() === bClub.trim();
  const ownRosterLocal = roster.filter(p => p.is_own_team !== false);
  const oppRoster = isSameSchool
    ? [...ownRosterLocal, ...oppRosterBase.filter(p => p.team_name === bClub && p.is_own_team === false)]
    : oppRosterBase;

  // ★学校名の候補一覧（誤入力防止）
  const [schools, setSchools] = useState([]);
  useEffect(() => { getKnownSchools().then(setSchools); }, []);

  // ★会場名の候補一覧
  const [venues, setVenues] = useState([]);
  useEffect(() => { getKnownVenues().then(setVenues); }, []);

  // ★この試合がドローの枠から作られたものであれば、エントリー番号もここで一緒に編集できるようにする
  //   ドローと紐づいていない通常の試合でも、ペアの出場番号を直接入力できるようにする
  //   （その場合はmatch_players.entry_noに直接保存する）
  const [drawLink, setDrawLink] = useState(null); // { id, side_a_entry_id, side_b_entry_id }
  const [aEntryNo, setAEntryNo] = useState(aBase?.entry_no ?? "");
  const [bEntryNo, setBEntryNo] = useState(bBase?.entry_no ?? "");
  useEffect(() => {
    if (!editing?.id) return;
    getDrawMatchByMatchId(editing.id).then(async (link) => {
      if (!link) return;
      setDrawLink(link);
      const ids = [link.side_a_entry_id, link.side_b_entry_id].filter(Boolean);
      if (ids.length) {
        const { data } = await supabase.from("draw_entries").select("id, entry_no").in("id", ids);
        (data || []).forEach(row => {
          if (row.id === link.side_a_entry_id) setAEntryNo(row.entry_no != null ? String(row.entry_no) : "");
          if (row.id === link.side_b_entry_id) setBEntryNo(row.entry_no != null ? String(row.entry_no) : "");
        });
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editing?.id]);

  // ★ペア出場番号を入力すると、同じ大会の別の試合で使われている同じ番号のチーム名・選手名を自動で探して入力する。
  //   （前の回戦を勝ち上がった同じペアの情報を、毎回手入力しなくて済むようにするため）
  //   既に入力済みの項目は上書きしない。見つかった/見つからなかったは小さく表示する。
  const [aEntryLookup, setAEntryLookup] = useState(null); // "found" | "notfound" | null
  const [bEntryLookup, setBEntryLookup] = useState(null);
  useEffect(() => {
    const n = aEntryNo.trim();
    if (!n || !tournamentName.trim()) { setAEntryLookup(null); return; }
    const timer = setTimeout(async () => {
      const found = await findPairByEntryNo(tournamentName, n).catch(() => null);
      if (found) {
        setAEntryLookup("found");
        // ★チーム名・選手名ともに「未入力のときだけ」ではなく、番号入力で見つかった時点で常に反映する。
        //   「コピーして新規作成」した試合では前の回戦の選手名がすでに入っているため、
        //   未入力チェックのままだと番号を書き換えても古い選手名が残ってしまうため。
        if (!isTeamMatchGame && found.club_name) setAClub(found.club_name);
        if (found.player1) setAP1(found.player1);
        if (found.player2) setAP2(found.player2);
      } else {
        setAEntryLookup("notfound");
      }
    }, 500);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [aEntryNo, tournamentName]);
  useEffect(() => {
    const n = bEntryNo.trim();
    if (!n || !tournamentName.trim()) { setBEntryLookup(null); return; }
    const timer = setTimeout(async () => {
      const found = await findPairByEntryNo(tournamentName, n).catch(() => null);
      if (found) {
        setBEntryLookup("found");
        if (!isTeamMatchGame && found.club_name) setBClub(found.club_name);
        if (found.player1) setBP1(found.player1);
        if (found.player2) setBP2(found.player2);
      } else {
        setBEntryLookup("notfound");
      }
    }, 500);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [bEntryNo, tournamentName]);

  // ★若番／遅番の自動判定：自チーム・相手チームの両方にペア出場番号が入っていれば、
  //   番号が小さい方＝若番として自動的に決める（毎回手動で選ばなくてよいように）。
  //   どちらかの番号が空欄／数値でない場合は、従来通り手動で選んでもらう。
  const aEntryNoNum = Number(aEntryNo.trim());
  const bEntryNoNum = Number(bEntryNo.trim());
  const bothEntryNosNumeric = aEntryNo.trim() !== "" && bEntryNo.trim() !== "" && !isNaN(aEntryNoNum) && !isNaN(bEntryNoNum);
  useEffect(() => {
    if (bothEntryNosNumeric) setIsYounger(aEntryNoNum < bEntryNoNum);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [bothEntryNosNumeric, aEntryNoNum, bEntryNoNum]);

  // ★チーム名/学校名の都道府県絞り込み（自チーム・相手チームそれぞれ独立）
  const [aClubPref, setAClubPref] = useState("");
  const [bClubPref, setBClubPref] = useState("");

  // ★自チーム学校名の初期化
  // 団体戦ペア登録時はteamMatchMySchoolIdを優先、通常はプロフィールの学校名
  useEffect(() => {
    if (base) return; // 編集・コピー時は既存のチーム名をそのまま使う
    (async () => {
      const allSchools = await getSchools();
      if (isTeamMatchGame && teamMatchMySchoolId) {
        const mine = allSchools.find(s => s.id === teamMatchMySchoolId);
        if (mine) { setAClub(mine.name); return; }
      }
      const profile = await getMyProfile();
      if (!profile?.school_id) return;
      const mine = allSchools.find(s => s.id === profile.school_id);
      if (mine) setAClub(prev => prev || mine.name);
    })();
  }, []);

  // ★本当の自チーム名（プロフィール上の所属校）を別途保持しておく。
  //   「自チーム(A)」「相手チーム(B)」どちらの欄に自チーム名を入れても、
  //   保存時に自チームが必ずチームA（緑）になるようにするための判定に使う。
  const [ownSchoolName, setOwnSchoolName] = useState("");
  useEffect(() => {
    (async () => {
      const allSchools = await getSchools();
      if (isTeamMatchGame && teamMatchMySchoolId) {
        const mine = allSchools.find(s => s.id === teamMatchMySchoolId);
        if (mine) { setOwnSchoolName(mine.name); return; }
      }
      const profile = await getMyProfile();
      if (!profile?.school_id) return;
      const mine = allSchools.find(s => s.id === profile.school_id);
      if (mine) setOwnSchoolName(mine.name);
    })();
  }, []);

  // 自チーム選手の入力チェック
  const canSchedule = aP1.trim() && (!isDoubles || aP2.trim()) && isYounger !== null;

  async function handleSchedule() {
    // 2回目以降は確認ポップアップ
    if (scheduledId) {
      if (!window.confirm("予定情報を更新しますか？")) return;
    }
    setSaving(true);
    try {
      const mid = scheduledId || uid();
      // ★自チームが誤って「相手チーム(B)」欄に入力されていた場合、保存時に必ずチームA（緑）になるよう入れ替える
      const swap = ownSchoolName && bClub.trim() === ownSchoolName && aClub.trim() !== ownSchoolName;
      const fAClub = swap ? bClub : aClub, fAP1 = swap ? bP1 : aP1, fAP2 = swap ? bP2 : aP2;
      const fBClub = swap ? aClub : bClub, fBP1 = swap ? aP1 : bP1, fBP2 = swap ? aP2 : bP2;
      const fFirstServer = swap ? (firstServer === "A" ? "B" : firstServer === "B" ? "A" : firstServer) : firstServer;
      const players = [
        { id:uid(), match_id:mid, team:"A", player_name:fAP1.trim(), club_name:fAClub.trim(), position:null, order_num:1, entry_no: (swap ? bEntryNo : aEntryNo).trim() || null },
        ...(isDoubles && fAP2.trim() ? [{ id:uid(), match_id:mid, team:"A", player_name:fAP2.trim(), club_name:fAClub.trim(), position:null, order_num:2, entry_no: (swap ? bEntryNo : aEntryNo).trim() || null }] : []),
        ...(fBP1.trim() || fBClub.trim() ? [{ id:uid(), match_id:mid, team:"B", player_name:withPlaceholder(fBP1, "選手A"), club_name:fBClub.trim(), position:null, order_num:1, entry_no: (swap ? aEntryNo : bEntryNo).trim() || null }] : []),
        ...(isDoubles && (fBP1.trim() || fBClub.trim()) ? [{ id:uid(), match_id:mid, team:"B", player_name:withPlaceholder(fBP2, "選手B"), club_name:fBClub.trim(), position:null, order_num:2, entry_no: (swap ? aEntryNo : bEntryNo).trim() || null }] : []),
      ];
      const match = {
        id:mid, created_by:"me",
        match_date:matchDate, venue, tournament_name:tournamentName, round, match_number:matchNumber||null,
        match_type:matchType, game_format:gameFormat, is_doubles:isDoubles, first_server:fFirstServer,
        status:"scheduled", match_score_a:0, match_score_b:0, memo:"", court_number:courtNumber||null, is_younger:isYounger, players, games:[],
        ...ordersFor(swap),
      };
      await saveMatch(match, { isNew: !scheduledId });
      setScheduledId(mid);
      onScheduled && onScheduled();
    } catch(e) {
      alert("登録に失敗しました: " + (e.message || e));
    } finally {
      setSaving(false);
    }
  }


  // サーブ選択ポップアップ → handleSave本体を呼ぶ
  function handleSaveWithServeSelect() {
    if (isYounger === null || isYounger === undefined) { alert("若番／遅番を選択してください"); return; }
    if (editing) { handleSave(null); return; } // 編集時はサーブ選択不要
    // ★自チームが「相手チーム(B)」欄に入力されていても、保存時にチームAへ入れ替えるのに合わせて、
    //   このサーブ選択画面でも自チームが必ず緑（A）側に表示されるようにする
    const swap = ownSchoolName && bClub.trim() === ownSchoolName && aClub.trim() !== ownSchoolName;
    const aLabel = (swap
      ? [bP1.trim(), isDoubles ? bP2.trim() : ""]
      : [aP1.trim(), isDoubles ? aP2.trim() : ""]).filter(Boolean).join("/") || "自チーム";
    const bLabel = (swap
      ? [aP1.trim(), isDoubles ? aP2.trim() : ""]
      : [bP1.trim(), isDoubles ? bP2.trim() : ""]).filter(Boolean).join("/") || "相手チーム";
    setServeSelectForSave({ aLabel, bLabel });
  }

  async function handleSave(selectedServer) {
    setSaving(true);
    try {
      if (editing) {
        // 既存試合の試合情報・選手情報のみ更新（スコア・ゲームは変更しない）
        // ★対戦相手情報が何も入力されていない場合はB側の選手行自体を作らない
        //   （新規作成・予定試合の登録と挙動を揃え、「選手A/選手B」が出たり出なかったりする不整合をなくす）
        // ★注意：編集時は新規作成と違い、既にgames/pointsにA/Bで得点が記録されている場合があるため、
        //   ここで自動的にチームを入れ替えることはできない（入れ替えるとスタッツが逆転してしまう）。
        //   自チームがB側で保存されてしまっている試合は、下の「🔄 チームを入れ替える」ボタンで
        //   ゲーム・ポイントの記録も含めて正しく入れ替える。
        const bEntered = bP1.trim() || bClub.trim();
        const updatedPlayers = [
          { id: aBase?.id ?? uid(), match_id: editing.id, team:"A", player_name:aP1.trim(), club_name:aClub.trim(), position:aBase?.position ?? null, order_num:1, entry_no: aEntryNo.trim() || null },
          ...(isDoubles && aP2.trim() ? [{ id: aBase2?.id ?? uid(), match_id: editing.id, team:"A", player_name:aP2.trim(), club_name:aClub.trim(), position:aBase2?.position ?? null, order_num:2, entry_no: aEntryNo.trim() || null }] : []),
          ...(bEntered ? [{ id: bBase?.id ?? uid(), match_id: editing.id, team:"B", player_name:withPlaceholder(bP1, "選手A"), club_name:bClub.trim(), position:bBase?.position ?? null, order_num:1, entry_no: bEntryNo.trim() || null }] : []),
          ...(isDoubles && bEntered ? [{ id: bBase2?.id ?? uid(), match_id: editing.id, team:"B", player_name:withPlaceholder(bP2, "選手B"), club_name:bClub.trim(), position:bBase2?.position ?? null, order_num:2, entry_no: bEntryNo.trim() || null }] : []),
        ];
        // ★選手名を変更したときは、すでに記録済みのポイント・フォルトに残っている
        //   古い名前（「選手A」などの仮名を含む）も一緒に書き換える。
        //   これをしないと、試合の途中で相手の名前が分かって登録し直しても、
        //   スタッツ画面が「選手A」のままになってしまう。
        const renameMap = {};
        [[aBase, updatedPlayers.find(p=>p.team==="A"&&p.order_num===1)],
         [aBase2, updatedPlayers.find(p=>p.team==="A"&&p.order_num===2)],
         [bBase,  updatedPlayers.find(p=>p.team==="B"&&p.order_num===1)],
         [bBase2, updatedPlayers.find(p=>p.team==="B"&&p.order_num===2)]].forEach(([before, after]) => {
          const oldName = (before?.player_name ?? "").trim();
          const newName = (after?.player_name ?? "").trim();
          if (oldName && newName && oldName !== newName) renameMap[oldName] = newName;
        });
        const applyRename = (name) => (name && renameMap[name]) ? renameMap[name] : name;
        const renamedGames = Object.keys(renameMap).length === 0
          ? editing.games
          : (editing.games ?? []).map(g => ({
              ...g,
              points: (g.points ?? []).map(pt => ({ ...pt, player_name: applyRename(pt.player_name) })),
              faults: (g.faults ?? []).map(f  => ({ ...f,  player_name: applyRename(f.player_name) })),
            }));

        const updated = {
          ...editing,
          match_date:matchDate, venue, tournament_name:tournamentName, round, match_number:matchNumber||null, match_type:matchType, court_number:courtNumber||null,
          players: updatedPlayers,
          games: renamedGames,
          ...ordersFor(false), // ★サーブ・レシーブ順（記録中に直した場合は、試合の最初から新しい順番で集計される）
          // 予定の場合は形式設定も更新可能
          ...((editing.status === "scheduled" || editing.status === "waiting") ? { game_format:gameFormat, is_doubles:isDoubles, first_server:firstServer, is_younger:isYounger } : { is_younger:isYounger }),
        };
        await saveMatch(updated);
        if (drawLink) {
          await Promise.all([
            updateDrawEntryNo(drawLink.side_a_entry_id, aEntryNo.trim()),
            updateDrawEntryNo(drawLink.side_b_entry_id, bEntryNo.trim()),
          ]);
        }
        onSave(editing.id);
        return;
      }

      // 新規作成 or コピー作成
      const mid = uid();
      // ★自チームが誤って「相手チーム(B)」欄に入力されていた場合、保存時に必ずチームA（緑）になるよう入れ替える
      const swap = ownSchoolName && bClub.trim() === ownSchoolName && aClub.trim() !== ownSchoolName;
      const fAClub = swap ? bClub : aClub, fAP1 = swap ? bP1 : aP1, fAP2 = swap ? bP2 : aP2;
      const fBClub = swap ? aClub : bClub, fBP1 = swap ? aP1 : bP1, fBP2 = swap ? aP2 : bP2;
      const fServer = selectedServer;
      const fFirstServer = swap ? (firstServer === "A" ? "B" : firstServer === "B" ? "A" : firstServer) : firstServer;
      const fBEntered = fBP1.trim() || fBClub.trim();
      const players = [
        { id:uid(), match_id:mid, team:"A", player_name:fAP1.trim(), club_name:fAClub.trim(), position:null, order_num:1, entry_no: (swap ? bEntryNo : aEntryNo).trim() || null },
        ...(isDoubles && fAP2.trim() ? [{ id:uid(), match_id:mid, team:"A", player_name:fAP2.trim(), club_name:fAClub.trim(), position:null, order_num:2, entry_no: (swap ? bEntryNo : aEntryNo).trim() || null }] : []),
        ...(fBEntered ? [{ id:uid(), match_id:mid, team:"B", player_name:withPlaceholder(fBP1, "選手A"), club_name:fBClub.trim(), position:null, order_num:1, entry_no: (swap ? aEntryNo : bEntryNo).trim() || null }] : []),
        ...(isDoubles && fBEntered ? [{ id:uid(), match_id:mid, team:"B", player_name:withPlaceholder(fBP2, "選手B"), club_name:fBClub.trim(), position:null, order_num:2, entry_no: (swap ? aEntryNo : bEntryNo).trim() || null }] : []),
      ];
      const match = {
        id:mid, created_by:"me",
        match_date:matchDate, venue, tournament_name:tournamentName, round, match_number:matchNumber||null,
        match_type:matchType, game_format:gameFormat, is_doubles:isDoubles, first_server:fServer || fFirstServer || "A",
        status:"active", match_score_a:0, match_score_b:0, memo:"", court_number:courtNumber||null, is_younger:isYounger, players, games:[],
        ...ordersFor(swap),
      };
      const savedRow = await saveMatch(match, { isNew: true });
      // ★記録画面を開くときにサーバーから取り直さなくて済むよう、今保存した内容を渡しておく
      primeMatch(rowToMatchFull({ ...match, ...savedRow }, match.players, [], [], []));
      if (selectedServer) markAutoStart(mid); // ★サーブを選んで開始したので、記録画面ですぐ第1ゲームを始める
      // 選手マスターに自動登録（直接入力された選手のみ。マスター未登録の場合）
      // ★完了を待たずに記録画面へ進む（以前は4人分の登録が終わるまで画面が切り替わらなかった）
      autoRegisterPlayersToRoster([
        { name: fAP1, teamName: fAClub.trim(), isOwnTeam: true },
        ...(isDoubles && fAP2.trim() ? [{ name: fAP2, teamName: fAClub.trim(), isOwnTeam: true }] : []),
        ...(fBP1.trim() ? [{ name: fBP1, teamName: fBClub.trim(), isOwnTeam: false }] : []),
        ...(isDoubles && fBP2.trim() ? [{ name: fBP2, teamName: fBClub.trim(), isOwnTeam: false }] : []),
      ]);
      onSave(mid);
    } catch (e) {
      alert("保存エラー: " + JSON.stringify({msg: e?.message, code: e?.code, details: e?.details, hint: e?.hint}));
    } finally {
      setSaving(false);
    }
  }

  // ★自チーム(A)の選手候補チップ：選択中の「チーム名/学校名」(aClub)と一致する選手のみ表示する。
  //   aClubを東福岡から別のチームに変えたら候補もそのチームの選手に切り替わるようにする。
  //   さらに、大会側で「出場選手」が設定されている場合は、そのメンバーのみに絞り込む
  //   （選手が多いと候補が多すぎて選びにくいため）。設定が無い/空の大会では従来通り全員を表示する。
  const ownRosterForAAll = roster.filter(p => aClub ? p.team_name === aClub : p.is_own_team !== false).sort(byPlayerNameKana);
  const ownRosterForA = (tournamentParticipantIds && tournamentParticipantIds.length > 0)
    ? ownRosterForAAll.filter(p => tournamentParticipantIds.includes(p.id))
    : ownRosterForAAll;

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <div style={{ display:"flex",alignItems:"center",gap:12 }}>
          <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onCancel}>←</button>
          <span style={{ fontSize:18,fontWeight:800,color:C.white }}>{headerLabel || (editing?"試合情報を編集":source?"試合をコピー":"新規試合")}</span>
        </div>
      </div>
      {source && (
        <div style={{ background:"#fff8e6",borderBottom:"1px solid #f5d99b",padding:"10px 14px",fontSize:12,color:"#7a5800" }}>
          📋 「{source.tournament_name || "前の試合"}」の情報をコピーしました。内容を確認・変更してください（スコアはコピーされません）。
        </div>
      )}
      {locked && (
        <div style={{ background:"#f5f5f5",borderBottom:"1px solid #e0e0e0",padding:"10px 14px",fontSize:12,color:C.textSec }}>
          ✏️ 試合情報・選手名を編集できます。ゲーム数・種目・サーブ順は試合開始後のため変更できません。
        </div>
      )}
      <div style={{ padding:14 }}>
        <div style={{ display:"flex", alignItems:"center", fontSize:11.5, color:C.textSec, marginBottom:10 }}>
          <RequiredDot />は必須項目です（それ以外は空欄でも試合を始められます）
        </div>

        {/* 団体戦ペア登録モード：試合情報を非表示 */}
        {!isTeamMatchGame && (
          <>
        <div style={{ marginBottom:14 }}>
          <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
            <span style={{ fontSize:11,fontWeight:700,color:C.navy,letterSpacing:"0.05em" }}>試合情報</span>
            <button
              style={{ background:"#eef0f4", border:"none", borderRadius:20, padding:"4px 12px", fontSize:11, fontWeight:700, color:C.navy, cursor:"pointer" }}
              onClick={() => setShowMatchInfo(v => !v)}
            >
              {showMatchInfo ? "非表示 ▲" : "表示 ▼"}
            </button>
          </div>
          {showMatchInfo && (
          <div style={{ background:C.white,borderRadius:12,border:`1px solid ${C.border}`,overflow:"visible" }}>
          <FormRow label="大会名">
            {lockTournament ? (
              <div style={{ ...S.inp, display:"flex", justifyContent:"space-between", alignItems:"center", fontWeight:700 }}>
                <span>{tournamentName}</span>
                <span style={{ fontSize:12, color:C.textSec, background:"#e2e5eb", padding:"4px 6px", borderRadius:10, fontWeight:700 }}>🔒</span>
              </div>
            ) : (
              <input style={S.inp} placeholder="例：○○中学校選手権" value={tournamentName} onChange={e => setTournamentName(e.target.value)}/>
            )}
          </FormRow>
          <FormRow label="試合日">
            {lockTournament && tournamentStartDate && tournamentEndDate && tournamentStartDate !== tournamentEndDate ? (
              <div>
                <input type="date" style={S.inp} value={matchDate} min={tournamentStartDate} max={tournamentEndDate} onChange={e => setMatchDate(e.target.value)}/>
                <div style={{ fontSize:10, color:C.textSec, marginTop:4 }}>📅 大会期間（{fmtDate(tournamentStartDate)}〜{fmtDate(tournamentEndDate)}）内から選択できます</div>
              </div>
            ) : lockTournament ? (
              <div style={{ ...S.inp, display:"flex", justifyContent:"space-between", alignItems:"center", fontWeight:700 }}>
                <span>{fmtDate(matchDate)}</span>
                <span style={{ fontSize:10, color:C.textSec, background:"#e2e5eb", padding:"2px 8px", borderRadius:10, fontWeight:700 }}>🔒 大会の日程</span>
              </div>
            ) : (
              <input type="date" style={S.inp} value={matchDate} onChange={e => setMatchDate(e.target.value)}/>
            )}
          </FormRow>
          <FormRow label="場所 / 会場名">
            <VenueField value={venue} onChange={setVenue} venues={venues} />
          </FormRow>
          <FormRow label="ゲーム数（デフォルト：7G）">
            {locked ? (
              <div style={{ fontSize:14,fontWeight:700,color:C.textSec,padding:"4px 0" }}>{gameFormat}G 🔒</div>
            ) : (
              <div style={{ display:"flex",gap:8 }}>
                {GAME_FORMATS.map(v => (
                  <button key={v} style={S.togBtn(gameFormat===v)} onClick={() => setGameFormat(v)}>{v}G</button>
                ))}
              </div>
            )}
          </FormRow>
          <FormRow label="種目">
            {locked ? (
              <div style={{ fontSize:14,fontWeight:700,color:C.textSec,padding:"4px 0" }}>{isDoubles?"ダブルス":"シングルス"} 🔒</div>
            ) : (
              <div style={{ display:"flex",gap:8 }}>
                {[["ダブルス",true],["シングルス",false]].map(([l,v]) => (
                  <button key={l} style={S.togBtn(isDoubles===v)} onClick={() => setIsDoubles(v)}>{l}</button>
                ))}
              </div>
            )}
          </FormRow>
          </div>
          )}
        </div>
          </>
        )}

        {/* 団体戦ペア登録モード：チーム区分・相手校を表示のみ */}
        {isTeamMatchGame && (
          <div style={{ ...S.card, padding:"10px 14px", marginBottom:14, background:"#f0f4ff", border:`1px solid ${C.border}` }}>
            <div style={{ fontSize:11,color:C.textSec,marginBottom:4 }}>自チーム区分</div>
            <div style={{ fontSize:14,fontWeight:700,color:C.navy,marginBottom:8 }}>{teamMatchMyDivision || "（なし）"}</div>
            <div style={{ fontSize:11,color:C.textSec,marginBottom:4 }}>相手チーム</div>
            <div style={{ fontSize:14,fontWeight:700,color:C.navy }}>{prefillOpponent || "（未設定）"}{teamMatchOppDivision ? `（${teamMatchOppDivision}）` : ""}</div>
          </div>
        )}

        <FormSec title="自チーム (A)">
          <FormRow label="ペア出場番号（任意）">
            <input style={S.inp} placeholder="例：12" inputMode="numeric" value={aEntryNo} onChange={e => setAEntryNo(e.target.value)}/>
            {aEntryLookup === "found" && (
              <div style={{ fontSize:10.5, color:C.accent, marginTop:4 }}>✓ 同じ番号のペアが見つかったので自動入力しました</div>
            )}
            {aEntryLookup === "notfound" && (
              <div style={{ fontSize:10.5, color:C.textSec, marginTop:4 }}>この大会でこの番号のペアはまだ見つかりません</div>
            )}
          </FormRow>
          <FormRow label="チーム名 / 学校名" labelRight={isTeamMatchGame ? null : <PrefMiniFilter value={aClubPref} onChange={setAClubPref} options={knownPrefsFrom(schools)} />}>
            {isTeamMatchGame ? (
              <div style={{ ...S.inp, color:C.text, background:C.gray }}>{aClub || "（自チーム）"}</div>
            ) : (
              <SchoolField value={aClub} onChange={setAClub} schools={schools} placeholder="例：○○中学校" prefFilter={aClubPref} />
            )}
          </FormRow>
          <FormRow label={isDoubles ? "選手1（必須）" : "選手名（必須）"} required>
            <input style={S.inp} placeholder="選手名" value={aP1} onChange={e => setAP1(e.target.value)}/>
            {ownRosterForA.length>0 && (
              <div style={{ marginTop:6 }}>
                {ownRosterForA.map(p=>(
                  <span key={p.id} style={S.chip(aP1===p.player_name)} onClick={()=>setAP1(p.player_name)}>{p.player_name}</span>
                ))}
              </div>
            )}
          </FormRow>
          {isDoubles && (
            <FormRow label="選手2（ペア・必須）" required>
              <input style={S.inp} placeholder="選手名" value={aP2} onChange={e => setAP2(e.target.value)}/>
              {ownRosterForA.length>0 && (
                <div style={{ marginTop:6 }}>
                  {ownRosterForA.map(p=>(
                    <span key={p.id} style={S.chip(aP2===p.player_name)} onClick={()=>setAP2(p.player_name)}>{p.player_name}</span>
                  ))}
                </div>
              )}
            </FormRow>
          )}
        </FormSec>

        <FormSec title="相手チーム (B)">
          <FormRow label="ペア出場番号（任意）">
            <input style={S.inp} placeholder="例：13" inputMode="numeric" value={bEntryNo} onChange={e => setBEntryNo(e.target.value)}/>
            {bEntryLookup === "found" && (
              <div style={{ fontSize:10.5, color:C.accent, marginTop:4 }}>✓ 同じ番号のペアが見つかったので自動入力しました</div>
            )}
            {bEntryLookup === "notfound" && (
              <div style={{ fontSize:10.5, color:C.textSec, marginTop:4 }}>この大会でこの番号のペアはまだ見つかりません</div>
            )}
          </FormRow>
          <FormRow label="チーム名 / 学校名" labelRight={isTeamMatchGame ? null : <PrefMiniFilter value={bClubPref} onChange={setBClubPref} options={knownPrefsFrom(schools)} />}>
            {isTeamMatchGame ? (
              <div style={{ ...S.inp, color:C.text, background:C.gray }}>{bClub || prefillOpponent || "（相手チーム）"}</div>
            ) : (
              <SchoolField value={bClub} onChange={setBClub} schools={schools} placeholder="例：相手チーム名" prefFilter={bClubPref} />
            )}
          </FormRow>
          <FormRow label={isDoubles ? "選手1" : "選手名"}>
            <input style={S.inp} placeholder="選手名（不明な場合は空欄でOK）" value={bP1} onChange={e => setBP1(e.target.value)}/>
            {bClub && oppRoster.filter(p => p.team_name === bClub).length>0 && (
              <div style={{ marginTop:6 }}>
                {oppRoster.filter(p => p.team_name === bClub).sort(byPlayerNameKana).map(p=>(
                  <span key={p.id} style={S.chip(bP1===p.player_name)} onClick={()=>setBP1(p.player_name)}>{p.player_name}</span>
                ))}
              </div>
            )}
          </FormRow>
          {isDoubles && (
            <FormRow label="選手2（ペア）">
              <input style={S.inp} placeholder="選手名（不明な場合は空欄でOK）" value={bP2} onChange={e => setBP2(e.target.value)}/>
              {bClub && oppRoster.filter(p => p.team_name === bClub).length>0 && (
                <div style={{ marginTop:6 }}>
                  {oppRoster.filter(p => p.team_name === bClub).sort(byPlayerNameKana).map(p=>(
                    <span key={p.id} style={S.chip(bP2===p.player_name)} onClick={()=>setBP2(p.player_name)}>{p.player_name}</span>
                  ))}
                </div>
              )}
            </FormRow>
          )}
          {oppRoster.length===0 && (
            <div style={{ padding:"0 14px 12px",fontSize:11,color:C.textSec }}>
              マスター画面の「👥 選手マスター」(他チーム)で対戦相手の選手を登録しておくと、ここで選んで入力できます。
            </div>
          )}
        </FormSec>

        <FormSec title="試合詳細">
          <FormRow label="何回戦（任意）">
            <RoundField value={round} onChange={setRound} placeholder="例：準々決勝"/>
          </FormRow>
          <FormRow label="何試合目（任意）">
            <input style={S.inp} placeholder="例：1" inputMode="numeric" value={matchNumber} onChange={e => setMatchNumber(e.target.value)}/>
          </FormRow>
          <FormRow label="コート番号（任意）">
            <input style={S.inp} placeholder="例：3番コート" value={courtNumber} onChange={e => setCourtNumber(e.target.value)}/>
          </FormRow>
        </FormSec>

        {/* ★サーブ・レシーブ順：各ペアの「サーブの1人目」「レシーブの1人目」。
            試合情報の時点では最初のサーブは決まっていないので、ここでは順番だけを設定する。
            記録中に違っていたと気付いたら、記録画面右上の✏️からこの画面を開いて直す（試合の最初から集計し直される） */}
        {isDoubles && (
          <FormSec title="🎾 サーブ・レシーブ順">
            <div style={{ padding:"12px 12px 2px" }}>
            <div style={{ fontSize:11.5, color:C.textSec, lineHeight:1.6, marginBottom:10 }}>
              各ゲームで最初にサーブ・レシーブする人です。分からないところは、そのままで大丈夫です（試合の途中でも、ここから直せます）。
            </div>
            <ServeReceiveOrderEditor
              aName={[aClub.trim(), [aP1.trim(), aP2.trim()].filter(Boolean).join("/")].filter(Boolean).join("　") || "自チーム"}
              bName={[bClub.trim(), [bP1.trim(), bP2.trim()].filter(Boolean).join("/")].filter(Boolean).join("　") || "相手チーム"}
              aP1={aP1.trim() || "選手1"} aP2={aP2.trim() || "選手2"}
              bP1={bP1.trim() || "選手A"} bP2={bP2.trim() || "選手B"}
              value={orders} onChange={setOrders} mode="info" inset
            />
            </div>
          </FormSec>
        )}

        {/* ★若番／遅番：試合開始ボタンのすぐ上に置く（必須項目なので、押す直前に選び忘れに気づけるように） */}
        {!isTeamMatchGame && (
          <FormSec title="若番 / 遅番">
            <FormRow label="若番 / 遅番（必須）" required>
              {bothEntryNosNumeric ? (
                <div style={{ fontSize:11.5, color:C.textSec, background:C.gray, borderRadius:8, padding:"8px 10px" }}>
                  ✓ ペア出場番号（{aEntryNo} と {bEntryNo}）から自動判定：<b style={{ color:C.navy }}>{isYounger ? "若番" : "遅番"}</b>
                  <div style={{ fontSize:10.5, color:C.textSec, marginTop:2 }}>変更したい場合は番号欄を空欄にしてください</div>
                </div>
              ) : (
                <>
                  <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>自チームはトーナメント表のどちら側ですか？</div>
                  <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                    <button style={S.togBtn(isYounger===true, C.navy)} onClick={()=>setIsYounger(true)}>若番</button>
                    <button style={S.togBtn(isYounger===false, C.navy)} onClick={()=>setIsYounger(false)}>遅番</button>
                  </div>
                </>
              )}
            </FormRow>
          </FormSec>
        )}

        <button
          style={{ ...S.btn((canSave&&!saving) ? `linear-gradient(135deg,${C.accent},#00a066)` : C.border, (canSave&&!saving) ? C.white : C.textSec), marginTop:4, marginBottom:8 }}
          disabled={!canSave || saving}
          onClick={editing ? ()=>handleSave(null) : handleSaveWithServeSelect}
        >
          {saving ? "保存中..." : (editing ? "保存する 💾" : isTeamMatchGame ? "ペアを登録して試合開始 🎾" : "試合を開始する 🎾")}
        </button>
        {/* 団体戦ペア登録モード：ペアだけ保存して戻るボタン */}
        {isTeamMatchGame && onSavePairOnly && (
          <button
            style={{ ...S.btn(canSave && !saving ? C.navy : C.border, canSave && !saving ? C.white : C.textSec), marginTop:4, marginBottom:8 }}
            disabled={!canSave || saving}
            onClick={async ()=>{
              setSaving(true);
              try {
                const mid = uid();
                const players = [
                  { id:uid(), match_id:mid, team:"A", player_name:aP1.trim(), club_name:aClub.trim(), position:null, order_num:1 },
                  ...(isDoubles && aP2.trim() ? [{ id:uid(), match_id:mid, team:"A", player_name:aP2.trim(), club_name:aClub.trim(), position:null, order_num:2 }] : []),
                  // ★相手が未定（空欄）でも、他の保存処理と同じく仮名「選手A／選手B」で2人分を必ず保存する。
                  //   以前は空欄のまま1人分しか保存しておらず、サーブ選択や得点入力の選手ボタンが空の枠になり、
                  //   ダブルスでは相手2人のポイントを区別できなかった。仮名は後で本名を入れると記録ごと書き換えられる。
                  { id:uid(), match_id:mid, team:"B", player_name:withPlaceholder(bP1, "選手A"), club_name:bClub.trim(), position:null, order_num:1 },
                  ...(isDoubles ? [{ id:uid(), match_id:mid, team:"B", player_name:withPlaceholder(bP2, "選手B"), club_name:bClub.trim(), position:null, order_num:2 }] : []),
                ];
                const match = {
                  id:mid, created_by:"me",
                  match_date:matchDate, venue, tournament_name:tournamentName, round, match_number:matchNumber||null,
                  match_type:matchType, game_format:gameFormat, is_doubles:isDoubles, first_server: "A",
                  status:"scheduled", match_score_a:0, match_score_b:0, memo:"", court_number:courtNumber||null, is_younger:isYounger, players, games:[],
                  ...ordersFor(false),
                };
                await saveMatch(match, { isNew: true });
                onSavePairOnly(mid, { aP1: aP1.trim(), aP2: aP2.trim(), bP1: bP1.trim(), bP2: bP2.trim() });
              } catch(e) {
                alert("保存エラー: " + (e.message || e));
              } finally {
                setSaving(false);
              }
            }}
          >
            {saving ? "保存中..." : "💾 ペアを登録して戻る"}
          </button>
        )}
        {!editing && !isTeamMatchGame && (
          <button
            style={{ ...S.btn(canSchedule ? "linear-gradient(135deg,#7b1fa2,#9c27b0)" : C.border, canSchedule ? C.white : C.textSec), marginTop:4 }}
            disabled={!canSchedule || saving}
            onClick={handleSchedule}
          >
            {saving ? "登録中..." : scheduledId ? "📅 試合予定を更新する" : "📅 試合予定として登録する"}
          </button>
        )}
        {/* ★画面の一番下まで入力したあと、上まで戻らずに抜けられるようにする（大会詳細の「← 戻る」と同じ見た目） */}
        {onCancel && (
          <button
            style={{ ...S.btn("#fff"), border:`1px solid ${C.border}`, color:C.navy, fontSize:13, marginTop:8, marginBottom:24 }}
            disabled={saving}
            onClick={onCancel}
          >← 戻る</button>
        )}
      </div>

      {/* サーブ選択モーダル */}
      {serveSelectForSave && (
        <Modal onClose={()=>setServeSelectForSave(null)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:36, marginBottom:8 }}>🎾</div>
            <h3 style={{ fontSize:16, fontWeight:800, margin:"8px 0 4px" }}>最初のサーブを選択</h3>
            <p style={{ fontSize:12, color:C.textSec, marginBottom:16 }}>どちらがサーブから始めますか？</p>
            <div style={{ display:"flex", gap:10, marginBottom:12 }}>
              {[["A", serveSelectForSave.aLabel], ["B", serveSelectForSave.bLabel]].map(([team, label]) => (
                <button key={team}
                  style={{ flex:1, padding:"14px 8px", borderRadius:10, border:`2px solid ${team==="A"?"#2ecc71":"#f97316"}`, background:"transparent", cursor:"pointer", fontSize:13, fontWeight:700, color:team==="A"?"#2ecc71":"#f97316" }}
                  onClick={()=>{ setServeSelectForSave(null); handleSave(team); }}
                >{label}<br/><span style={{ fontSize:11, fontWeight:400 }}>（サーブ）</span></button>
              ))}
            </div>
            <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:12 }} onClick={()=>setServeSelectForSave(null)}>キャンセル</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ============================================================
// スコア記録
// ============================================================
// ★AI動画分析の閲覧権限を判定するための共通フック。
//   AI分析メニュー(AiAnalysisListScreen)と同じ基準にそろえる：
//   管理者か、その試合に出場している本人（保護者アカウントも連携先が同じ選手名になるので含む）だけが開ける。
//   これが無いと、AI分析メニュー側で鍵をかけても試合詳細のボタンから素通りできてしまう。
function useAiAnalysisViewer() {
  const [viewer, setViewer] = useState({ isAdmin: false, linkedPlayerName: null, loaded: false });
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const p = await getMyProfile();
        let name = null;
        if (p?.linked_player_id) {
          const roster = await getPlayerRoster();
          name = roster.find(r => r.id === p.linked_player_id)?.player_name ?? null;
        }
        if (alive) setViewer({ isAdmin: !!p?.is_admin, linkedPlayerName: name, loaded: true });
      } catch (e) {
        // 取得に失敗したときは「見せない」側に倒す（権限判定は安全側に寄せる）
        if (alive) setViewer({ isAdmin: false, linkedPlayerName: null, loaded: true });
      }
    })();
    return () => { alive = false; };
  }, []);
  return viewer;
}

function canViewAiAnalysisFor(match, viewer) {
  if (!viewer?.loaded) return false;
  if (viewer.isAdmin) return true;
  if (!viewer.linkedPlayerName) return false;
  return (match?.players || []).some(p => p.player_name === viewer.linkedPlayerName);
}

function ScoreRecord({ matchId, onBack, onEdit, onNavigate, teamMatchId, onOpenAiAnalysis, initialTab }) {
  const [initialMatch, setInitialMatch] = useState(null);
  const [loadKey, setLoadKey] = useState(0);
  const [refreshing, setRefreshing] = useState(false);
  const [viewOnly, setViewOnly] = useState(false); // 観戦モード
  const isViewer = useIsViewer(); // ★閲覧専用アカウントは常に観戦モード
  // ★中断／途中終了の試合は、記録者本人であっても「自分が記録者になる（続きから記録する）」を
  //   押すまでは観戦モード（閲覧のみ）にしておく。押した瞬間だけこのフラグをtrueにして即アクティブ化する。
  const [statusLockOverride, setStatusLockOverride] = useState(false);
  useEffect(() => { setStatusLockOverride(false); }, [matchId]);

  const handleRefresh = async () => {
    setRefreshing(true);
    try {
      const m = await getMatch(matchId);
      setInitialMatch(m);
    } catch (e) {
      alert("更新に失敗しました。もう一度お試しください。\n" + (e?.message || e));
    } finally {
      setRefreshing(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    // ★別の試合に切り替わった瞬間は、前の試合のデータを必ず捨てる。
    //   これをしないと読み込みが終わるまで前の試合（スコア・終了状態）がそのまま表示され、
    //   その画面を操作すると意図しない試合に書き込んでしまう恐れがある。
    setInitialMatch(null);
    (async () => {
      try {
        // ★試合データ・ログイン中のユーザー・（団体戦なら）番手の記録者を同時に取得する。
        //   以前は「試合＋ユーザー」→「番手の記録者」と順番に待っていたため、開くまでに時間がかかっていた。
        // ★作成した直後の試合は、保存した内容をそのまま使う（サーバーからの取り直しを省く）
        const primed = takePrimedMatch(matchId);
        const [m, user, tmgRes] = await Promise.all([
          (primed ? Promise.resolve(primed) : getMatch(matchId)).then(mm => {
            // ★DBから読み込んだ（または保存したばかりの）内容を、差分保存の控えにする
            if (mm && !primed) seedSavedSnapshot(mm);
            return mm;
          }),
          getAuthUserFast(),
          teamMatchId
            ? supabase.from("team_match_games").select("recorder_id, status").eq("match_id", matchId).single()
            : Promise.resolve({ data: null }),
        ]);
        if (cancelled) return;
        setInitialMatch(m);
        if (m && user) {
          const suspendedLike = m.status === "abandoned" || m.status === "suspended";
          if (teamMatchId) {
            // 団体戦：team_match_gamesのrecorder_idと自分のIDを比較
            const tmg = tmgRes?.data ?? null;
            // recorder_idが設定されていて自分以外 → 観戦モード
            // recorder_idがnull（誰も記録していない）→ 観戦モード（スコア詳細から入った場合）
            // ★毎回true/falseを確定させる（一度観戦モードになった後、自分が記録者になっても
            // 　falseに戻らなかったバグがあったため）
            const baseViewOnly = !tmg || !tmg.recorder_id || tmg.recorder_id !== user.id;
            setViewOnly(baseViewOnly || (suspendedLike && !statusLockOverride));
          } else {
            // ★個人戦も団体戦と同じ「記録者ロック」で判定する。
            //   試合を作る人と実際に記録する人は別なことが多いため、created_byでは判定しない。
            //   recorder_idがまだ無い古い試合は、これまで通り作成者を記録者とみなす（移行のための保険）。
            const baseViewOnly = m.recorder_id
              ? m.recorder_id !== user.id
              : m.created_by !== user.id;
            setViewOnly(baseViewOnly || (suspendedLike && !statusLockOverride));
          }
        }
      } catch(e) {
        if (!cancelled) alert("試合読み込みエラー: " + (e?.message || e));
      }
    })();
    return () => { cancelled = true; };
  }, [matchId, loadKey]);

  if (!initialMatch) {
    return (
      <div style={S.page}>
        <div style={S.hdr}><span style={{ fontSize:18,fontWeight:800,color:C.white }}>読み込み中...</span></div>
      </div>
    );
  }
  return (
    <ErrorBoundary>
      <ScoreRecordInner
        key={initialMatch.id}
        initialMatch={initialMatch}
        initialTab={initialTab}
        onBack={onBack}
        onEdit={onEdit}
        onReload={()=>setLoadKey(k=>k+1)}
        onClaimRecorder={()=>setStatusLockOverride(true)}
        onRefresh={handleRefresh}
        refreshing={refreshing}
        onNavigate={onNavigate}
        viewOnly={viewOnly || isViewer}
        isViewer={isViewer}
        teamMatchId={teamMatchId}
        onOpenAiAnalysis={onOpenAiAnalysis}
      />
    </ErrorBoundary>
  );
}

function ScoreRecordInner({ initialMatch, onBack, onEdit, onReload, onClaimRecorder, onRefresh, refreshing, onNavigate, viewOnly, isViewer, teamMatchId, onOpenAiAnalysis, initialTab }) {
  const [match,  setMatch]  = useState(initialMatch);
  // ★観戦モード（閲覧のみ）では、親から渡されるinitialMatchが「最新に更新」で
  // 　差し替わった時にこの内部stateへ反映されないと画面が更新されない。
  // 　（useState(initialMatch)は初回マウント時の値しか使わないため）
  useEffect(() => {
    if (viewOnly) setMatch(initialMatch);
  }, [initialMatch, viewOnly]);
  // ★分析画面の試合一覧から開いたときなど、最初から「スタッツ」タブを表示したい場合に使う
  const [tab,    setTab]    = useState(initialTab ?? "record");
  const [fault,  setFault]  = useState(0);
  const [modal,  setModal]  = useState(null);
  const [serveSelectModal, setServeSelectModal] = useState(false); // サーブ選択モーダル
  // 4段階選択状態
  const [selPlay,   setSelPlay]   = useState(null);   // プレイ内容
  const [selSide,   setSelSide]   = useState(null);   // フォア / バック
  // ★「＋どんなプレー？」は毎回開くのが手間なので、最初から開いた状態にしておく。
  //   閉じたときはその状態を覚えて、記録が進んでも勝手に開き直さないようにする。
  const [playDetailOpen, setPlayDetailOpen] = useState(true);
  const [selResult, setSelResult] = useState(null);   // 結果
  const [selPlayer, setSelPlayer] = useState(null);   // 選手（表示名・記録用）
  const [selPlayerId, setSelPlayerId] = useState(null); // 選手（チップ選択状態の判定用・一意ID）
  // ★得点入力ウィザード（①どちらに1点→②決めた/相手ミス→③誰が、の3タップ）
  const [scoreStep, setScoreStep] = useState(1); // 1|2|3
  const [pendingTeam, setPendingTeam] = useState(null); // ①で選んだ得点チーム
  // ★一画面記録：①サーブ ②得点チーム ③決めた/ミスした ④誰が ⑤プレー ⑥よりくわしく を同じ画面で選び、「記録する」で1点を確定する
  const [osTeam,   setOsTeam]   = useState(null);  // ②得点したチーム "A"|"B"
  const [osKind,   setOsKind]   = useState(null);  // ③ "winner"=決めた / "error"=ミスした
  const [osPlayer, setOsPlayer] = useState(null);  // ④選手名
  const [osPlay,   setOsPlay]   = useState(null);  // ⑤プレー
  const [osSide,   setOsSide]   = useState(null);  // ⑥フォア/バック
  const [osMiss,   setOsMiss]   = useState(null);  // ⑥ミスの種類（ミスした時だけ）
  const [osCourse, setOsCourse] = useState(null);  // ⑥コース
  const [osToast,  setOsToast]  = useState("");    // 記録直後の「〇〇に1点」表示
  const [osMenu,   setOsMenu]   = useState(false); // 「⋯ その他」（中断・途中終了など）
  // ★自動スクロールのON/OFF（端末ごとに覚えておく。初期値はON）
  const [osAutoScroll, setOsAutoScroll] = useState(() => { try { return localStorage.getItem("os_auto_scroll") !== "off"; } catch(e) { return true; } });
  const toggleOsAutoScroll = () => setOsAutoScroll(v => { const nv = !v; try { localStorage.setItem("os_auto_scroll", nv ? "on" : "off"); } catch(e) {} return nv; });
  const osToastTimer = useRef(null);
  const osRefs = { sv:useRef(null), team:useRef(null), kind:useRef(null), player:useRef(null), play:useRef(null), side:useRef(null), miss:useRef(null), course:useRef(null) };
  const osAnchorY = useRef(null);   // ①サーブのボタンが最初に表示される画面上の高さ（自動スクロールの基準）
  const osScrollTimer = useRef(null);
  // ★④の前衛・後衛表示用：選手マスター（2分キャッシュ済みなので記録画面を開いた時に1回読むだけ）
  const [osRoster, setOsRoster] = useState([]);
  useEffect(() => { getPlayerRoster().then(setOsRoster).catch(()=>{}); }, []);
  const [correctMode, setCorrectMode] = useState(false); // 試合終了後のスコア修正モード
  // ★特定のゲームだけを修正するときに、そのゲームIDを入れる（nullなら全ゲームを表示）
  const [correctGameId, setCorrectGameId] = useState(null);
  const [showGamePicker, setShowGamePicker] = useState(false); // 「どのゲームを直すか」の選択モーダル
  // ★記録し忘れた最初のゲームを、第1ゲームの前に「スコアだけ」で追加する（途中のゲームから記録を始めた場合用）
  const [insertFirst, setInsertFirst] = useState(null); // null | { left:"", right:"" }
  // ★記録中のゲームを「飛ばす」（取ったチームだけ選んで次のゲームへ）。null | { winner, left, right }
  const [skipGame, setSkipGame] = useState(null);
  // ★試合の途中から記録する（前のゲームは取ったチームだけ入れる）。null | { startNum, winners:{1:"A",...}, server }
  const [midStart, setMidStart] = useState(null);
  const [orderDraft, setOrderDraft] = useState(null); // サーブレシーブの順番変更の下書き（保存を押すまで反映しない）
  // ★個人戦の試合にもAI動画分析を追加できるようにする（団体戦の各番手と同様の機能）
  // 　undefined=未確認、null=未登録、オブジェクト=登録済み
  const [aiAnalysis, setAiAnalysis] = useState(undefined);
  // ★AI動画分析は本人・保護者・管理者だけが開ける（AI分析メニューと同じ基準）
  const aiViewer = useAiAnalysisViewer();
  const canViewAi = canViewAiAnalysisFor(match, aiViewer);
  useEffect(() => {
    if (!teamMatchId && match.status === "finished" && match.id) {
      getAiAnalyses([match.id]).then(rows => setAiAnalysis(rows[0] ?? null));
    }
  }, [match.id, match.status, teamMatchId]);
  // ★個人戦でもポイントを付けずゲームカウントだけで結果を記録できるようにする（団体戦の「結果だけ記録」と同様）
  const [showSimpleResult, setShowSimpleResult] = useState(false);
  const [simpleScoreA, setSimpleScoreA] = useState("");
  const [simpleScoreB, setSimpleScoreB] = useState("");
  const [simpleResultSaving2, setSimpleResultSaving2] = useState(false);
  const [isWithdrawalResult, setIsWithdrawalResult] = useState(false); // ★棄権による試合終了（ゲームカウントの大小に関わらず終了できる）
  const [withdrawalWinner, setWithdrawalWinner] = useState(null); // "A" | "B"（棄権時は数字だけでは勝者が決まらないため明示的に選ぶ）
  const [editingPoint, setEditingPoint] = useState(null); // 修正中のポイント { gameId, point }
  const [addingPoint, setAddingPoint] = useState(null); // 追加位置 { gameId, atIndex }
  const [memoDraft, setMemoDraft] = useState(initialMatch.memo || ""); // 試合メモ（下書き）
  // ★動画リンク（複数）の下書き。メモと同じ「保存ボタンを押したら反映」の流れに合わせる。
  const [videoLinksDraft, setVideoLinksDraft] = useState(normalizeVideoLinks(initialMatch.video_links));
  const [videoUrlInput, setVideoUrlInput] = useState("");
  const [videoUrlError, setVideoUrlError] = useState("");
  const [memoSaved, setMemoSaved] = useState(true); // メモが保存済みかどうか
  const [memoSaving, setMemoSaving] = useState(false); // ★保存中は「戻る」ボタンを押しても未保存警告が出ないよう、保存完了まで待つ
  const [showVideoModal, setShowVideoModal] = useState(false); // ★動画リンクの追加・一覧はボタンを押したときだけモーダルで開く
  const [videoSaving, setVideoSaving] = useState(false); // ★保存中は「戻る」ボタンを押しても未保存警告が出ないよう、保存完了までモーダルを閉じない
  const [suspendConfirm, setSuspendConfirm] = useState(false); // 中断確認ダイアログ
  const [abandonConfirm, setAbandonConfirm] = useState(false); // 途中終了確認ダイアログ
  const [undoConfirm, setUndoConfirm] = useState(false); // 1点前に戻す確認ダイアログ
  const [gameOverUndoConfirm, setGameOverUndoConfirm] = useState(false); // ゲーム終了直後の「1点前に戻す」確認ダイアログ
  const [resetConfirm, setResetConfirm] = useState(false); // スコアリセット確認ダイアログ

  // ★オフライン対応：保存処理
  //   ・入力するたびに、まず端末のローカル(localStorage)に控えを保存する（電波が無くても記録が消えないように）
  //   ・サーバーへの保存はバックグラウンドで試み、失敗してもポップアップは出さず静かにリトライし続ける
  //   ・保存中に次の更新が来た場合は、常に「最新の状態」だけを送ればよい（1つ前の途中経過は送らなくてよい）ので、
  //     最新のもの1つだけを保持して送信する
  const LOCAL_DRAFT_KEY = `offline_match_draft_${initialMatch.id}`;
  const [syncStatus, setSyncStatus] = useState("synced"); // "synced" | "pending" | "error"
  const [syncErrorMsg, setSyncErrorMsg] = useState(""); // ★保存に失敗した本当の理由（原因調査用）
  const [restoredNotice, setRestoredNotice] = useState(false);
  const latestUnsavedRef = useRef(null);
  const savingRef = useRef(false);

  const attemptSave = useCallback(() => {
    if (savingRef.current) return;
    const toSave = latestUnsavedRef.current;
    if (!toSave) return;
    savingRef.current = true;
    // ★記録中の保存は差分保存（変わった行だけを送る）。控えが無いとき・状態が変わるときは自動で全部保存になる
    saveMatch(toSave, { incremental: true })
      .then(() => {
        if (latestUnsavedRef.current === toSave) {
          latestUnsavedRef.current = null;
          try { localStorage.removeItem(LOCAL_DRAFT_KEY); } catch(e) {}
          setSyncStatus("synced");
          setSyncErrorMsg("");
          // ★「復元しました」の案内は、保存が終わった時点で役目が終わるので自動で消す。
          //   以前は✕を押すまで残り続け、保存できたのかどうか分からなかった。
          setRestoredNotice(false);
        }
      })
      .catch((e) => {
        // ★以前はエラー内容を捨てて一律「電波待ち」と表示していたため、
        //   実際にはサーバー側のエラー（列が無い・権限が無い等）なのに
        //   電波のせいだと思い込んで、いつまでも直せない状態になっていた。
        //   オンラインかどうかで文言を分け、原因もそのまま表示する。
        setSyncStatus("error");
        setSyncErrorMsg(e?.message || String(e || "不明なエラー"));
      })
      .finally(() => {
        savingRef.current = false;
        if (latestUnsavedRef.current) setTimeout(attemptSave, 1500); // 未保存分が残っていれば少し待って再試行
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const persist = useCallback((m) => {
    setMatch({...m});
    try { localStorage.setItem(LOCAL_DRAFT_KEY, JSON.stringify(m)); } catch(e) {}
    latestUnsavedRef.current = m;
    setSyncStatus("pending");
    attemptSave();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attemptSave]);

  // ★電波が復活した瞬間（オンラインイベント）に、すぐ再送を試みる
  useEffect(() => {
    const onOnline = () => attemptSave();
    window.addEventListener("online", onOnline);
    return () => window.removeEventListener("online", onOnline);
  }, [attemptSave]);

  // ★画面を開いた直後：前回、同期できないまま終了してしまった記録がローカルに残っていれば、
  //   それを復元して改めて保存を試みる（アプリを閉じても記録が消えないようにするための仕組み）
  useEffect(() => {
    try {
      const raw = localStorage.getItem(LOCAL_DRAFT_KEY);
      if (raw) {
        const draft = JSON.parse(raw);
        const draftPointCount = (draft.games || []).reduce((n,g)=>n+(g.points?.length||0), 0);
        const initialPointCount = (initialMatch.games || []).reduce((n,g)=>n+(g.points?.length||0), 0);
        if (draftPointCount >= initialPointCount && JSON.stringify(draft) !== JSON.stringify(initialMatch)) {
          setMatch(draft);
          latestUnsavedRef.current = draft;
          setSyncStatus("pending");
          setRestoredNotice(true);
          attemptSave();
        } else {
          localStorage.removeItem(LOCAL_DRAFT_KEY);
        }
      }
    } catch(e) {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const winGames = calcWinGames(match.game_format);
  const currentGame = match.games.length>0&&!match.games[match.games.length-1].winner_team ? match.games[match.games.length-1] : null;
  const currentGameIsFinal = currentGame ? currentGame.is_final : isFinalGame(match.game_format,match.match_score_a,match.match_score_b);
  const nonFaultPts = currentGame?.points??[];
  const curServer = currentGame ? (currentGame.is_final ? finalServer(currentGame.server_team,nonFaultPts.length) : currentGame.server_team) : null;
  // ★サーブ表示：2ポイントごとの交代ルールを反映し、今まさにサーブする「個人」を出す
  const curServerOrderFlag = curServer==="A" ? (match.order_a==="p2"?"p2":"p1") : (match.order_b==="p2"?"p2":"p1");
  const curServerPlayersRaw = curServer ? match.players.filter(p=>p.team===curServer).sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name) : [];
  const curServerPlayers = curServerPlayersRaw.length>1 && curServerOrderFlag==="p2" ? [curServerPlayersRaw[1], curServerPlayersRaw[0]] : curServerPlayersRaw;
  const curServeTurn = currentGame ? (currentGameIsFinal
    ? nonFaultPts.filter((_,i)=>finalServer(currentGame.server_team,i)===curServer).length
    : nonFaultPts.length) : 0;
  const curServerIndividual = curServerPlayers.length<=1 ? (curServerPlayers[0]??null) : (Math.floor(curServeTurn/2)%2===0 ? curServerPlayers[0] : curServerPlayers[1]);
  const serverLabel = curServerIndividual ?? (curServer==="A" ? match.players.filter(p=>p.team==="A").map(p=>p.player_name).join("/") : match.players.filter(p=>p.team==="B").map(p=>p.player_name).join("/"));
  const teamAPlayers = match.players.filter(p=>p.team==="A");
  const teamBPlayers = match.players.filter(p=>p.team==="B");
  const teamALabel = teamAPlayers.map(p=>p.player_name).join("/");
  const teamBLabel = teamBPlayers.map(p=>p.player_name).join("/");
  // ★サーブ・レシーブ順の設定欄で使う：選手を登録順に並べた名前と、「学校名　選手/選手」の見出し
  const sortedTeamNames = (t) => match.players.filter(p=>p.team===t).sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name);
  const orderEditorName = (t) => {
    const club = (t==="A" ? teamAPlayers : teamBPlayers)[0]?.club_name || "";
    const names = t==="A" ? teamALabel : teamBLabel;
    return club ? `${club}　${names}` : names;
  };
  // ★LINE共有：待機中／試合開始／試合中のタイミングで、自チームのペア名・コート番号・状況・スコアをワンタップで共有する
  //   「自チーム／相手」ではなく学校名を見出しにし、ペア出場番号が入っていれば併記する
  const teamASchool = teamAPlayers[0]?.club_name || "";
  const teamBSchool = teamBPlayers[0]?.club_name || "";
  const teamAEntryNo = teamAPlayers[0]?.entry_no || "";
  const teamBEntryNo = teamBPlayers[0]?.entry_no || "";
  const shareToLine = (statusLabel) => {
    const aHeading = teamASchool || "自チーム";
    const bHeading = teamBSchool || "相手";
    const lines = [
      `【${statusLabel}】`,
      teamALabel ? `${teamAEntryNo ? `${teamAEntryNo} ` : ""}${aHeading}：${teamALabel}` : null,
      teamBLabel ? `${teamBEntryNo ? `${teamBEntryNo} ` : ""}${bHeading}：${teamBLabel}` : null,
      match.court_number ? `コート：${match.court_number}` : null,
      (match.status==="active" || match.status==="finished") ? `スコア：${match.match_score_a}-${match.match_score_b}` : null,
    ].filter(Boolean);
    const text = lines.join("\n");
    window.open("https://line.me/R/msg/text/?" + encodeURIComponent(text), "_blank");
  };
  // 若番=自チーム左、遅番=自チーム右
  const isYounger = match.is_younger !== false;
  // left=左側表示チーム、right=右側表示チーム
  const leftTeam  = isYounger ? "A" : "B";
  const rightTeam = isYounger ? "B" : "A";
  const leftLabel  = isYounger ? teamALabel : teamBLabel;
  const rightLabel = isYounger ? teamBLabel : teamALabel;
  const aClub = match.players.find(p=>p.team==="A")?.club_name??"";
  const bClub = match.players.find(p=>p.team==="B")?.club_name??"";
  const leftClub   = isYounger ? aClub : bClub;
  const rightClub  = isYounger ? bClub : aClub;
  // ★得点ボタン（+1）の下の表示。同校対決（両チームの学校名が同じ）のときは、
  //   学校名だと両方「東福岡」になり区別できないため、選手の名字（例：豊福/木場）を表示する
  const isSameSchoolMatch = !!aClub.trim() && aClub.trim() === bClub.trim();
  const familyNamesOf = (t) => match.players.filter(p=>p.team===t).sort((x,y)=>(x.order_num??0)-(y.order_num??0))
    .map(p => (p.player_name || "").trim().split(/[\s　]+/)[0]).filter(Boolean).join("/");
  const leftBtnLabel  = isSameSchoolMatch ? (familyNamesOf(leftTeam)  || leftClub)  : leftClub;
  const rightBtnLabel = isSameSchoolMatch ? (familyNamesOf(rightTeam) || rightClub) : rightClub;
  const leftScore  = (g) => isYounger ? g.score_a : g.score_b;
  const rightScore = (g) => isYounger ? g.score_b : g.score_a;
  const leftMatchScore  = isYounger ? match.match_score_a : match.match_score_b;
  const rightMatchScore = isYounger ? match.match_score_b : match.match_score_a;

  function resetSel(){ setSelPlay(null); setSelSide(null); setSelResult(null); setSelPlayer(null); setSelPlayerId(null); setScoreStep(1); setPendingTeam(null);
    setOsTeam(null); setOsKind(null); setOsPlayer(null); setOsPlay(null); setOsSide(null); setOsMiss(null); setOsCourse(null); }

  const startingGameRef = useRef(false); // ★ゲーム開始の二重呼び出し防止（duplicate key・空ゲーム量産の対策）
  const [startingGame, setStartingGame] = useState(false); // ★開始処理中はボタンを押せなくする
  function startNewGame(base=match, overrideServer=null, overrideOrderA=null, overrideOrderB=null){
    if (startingGameRef.current) return; // 連打・多重タップは無視
    const server = overrideServer || base.first_server;
    if (!server) {
      // ★サーブ選択モーダルを出している間もロックしておく。
      //   以前はここでロックしていなかったため、モーダルで決定 → 保存の通信を待っている間に
      //   まだ残っている「第1ゲーム開始」ボタンをもう一度押せてしまい、
      //   モーダルが2回出て空のゲームが2つ作られる不具合があった。
      startingGameRef.current = true;
      setStartingGame(true);
      setServeSelectModal(true);
      return;
    }
    // ★まだ点が入っていない進行中のゲームがあるなら、新しく作らずそのまま使う。
    //   何らかの経路で二重に呼ばれても空ゲームが増えないようにするための最後の砦。
    const last = base.games[base.games.length-1];
    if (last && !last.winner_team && (last.points?.length ?? 0) === 0) {
      startingGameRef.current = false;
      setStartingGame(false);
      return;
    }
    startingGameRef.current = true;
    setStartingGame(true);
    // ★予定(scheduled)・待機中(waiting)のまま作成された試合（ドロー経由など）が、採点開始後も
    //   ずっとその表示のままにならないよう、ここで進行中(active)に切り替える
    const statusFix = (base.status === "scheduled" || base.status === "waiting") ? { status: "active" } : {};
    base = { ...base, ...statusFix, first_server: server,
      order_a: overrideOrderA || base.order_a || "p1", order_b: overrideOrderB || base.order_b || "p1" };
    const num=base.games.length+1;
    const isFin=isFinalGame(base.game_format,base.match_score_a,base.match_score_b);
    const srv=gameServer(base.first_server||server,num);
    const g={id:uid(),match_id:base.id,game_number:num,server_team:srv,is_final:isFin,score_a:0,score_b:0,winner_team:null,points:[],faults:[]};
    persist({...base,games:[...base.games,g]});
    setTimeout(()=>{ startingGameRef.current = false; setStartingGame(false); }, 800); // 保存が実行された後にロック解除
  }

  // ★サーブを選んで「試合開始」した直後は、「第1ゲームの準備」画面を出さずにそのまま第1ゲームを始める
  //   （準備画面にあった順番の変更などは、記録画面の「⋯」→「サーブレシーブの順番変更」でできる）
  useEffect(() => {
    if (!takeAutoStart(initialMatch.id)) return;
    if (viewOnly || match.status === "finished" || match.games.length > 0) return;
    startNewGame(match.first_server ? match : { ...match, first_server:"A" });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ★サーブレシーブの順番変更を保存する。最初にサーブするペアを変えた場合は、各ゲームのサーブ側も付け直す
  function saveOrderDraft(d){
    const fsChanged = d.first_server !== (match.first_server || "A");
    const games = fsChanged ? match.games.map(g => ({ ...g, server_team: gameServer(d.first_server, g.game_number) })) : match.games;
    persist({ ...match, games, first_server:d.first_server, order_a:d.order_a, order_b:d.order_b, receive_order_a:d.receive_order_a, receive_order_b:d.receive_order_b });
  }

  function addPoint(team, resultKey=selResult, playerName=selPlayer, extra=null){
    if(!currentGame) return;
    const cg=currentGame;
    const newA=team==="A"?cg.score_a+1:cg.score_a;
    const newB=team==="B"?cg.score_b+1:cg.score_b;
    const isWin = resultKey ? isWinnerResult(resultKey) : null;
    const pt={
      id:uid(),game_id:cg.id,match_id:match.id,
      point_number:nonFaultPts.length+1,
      scoring_team:team,
      player_name:playerName??null,
      play_type:extra ? (extra.play_type??null) : (selPlay??null),
      side_type:extra ? (extra.side_type??null) : (selSide??null),
      // ★一画面記録では、コース・ミスの種類も「記録する」の前に選んでまとめて保存する
      course_type:extra ? (extra.course_type??null) : null,
      miss_type:extra ? (extra.miss_type??null) : null,
      result_type:resultKey??null,
      is_winner:isWin,
      fault_count:fault, // ★このポイントの前に何回フォルトがあったか（0=1stイン、1=2ndイン、2=ダブルフォルト）
      score_a_after:newA, score_b_after:newB,
      scored_at:new Date().toISOString(), // ★動画同期用：得点をタップした瞬間の時刻
    };
    const updG={...cg,points:[...cg.points,pt],score_a:newA,score_b:newB};
    const gWin=cg.is_final?checkFinalWinner(newA,newB):checkNormalWinner(newA,newB);
    if(gWin) updG.winner_team=gWin;
    const newMA=match.match_score_a+(gWin==="A"?1:0);
    const newMB=match.match_score_b+(gWin==="B"?1:0);
    const updM={...match,games:match.games.map(g=>g.id===cg.id?updG:g),match_score_a:newMA,match_score_b:newMB};
    resetSel(); setFault(0);
    if(gWin){
      if(newMA>=winGames||newMB>=winGames){ persist(updM); setModal({type:"matchOver",winner:gWin,gameId:cg.id,sA:newMA,sB:newMB}); }
      else { persist(updM); setModal({type:"gameOver",winner:gWin,num:cg.game_number,gameId:cg.id,sA:newMA,sB:newMB}); }
    } else { persist(updM); }
  }

  // ★ウィザードのステップ操作
  function wizardChooseTeam(team){
    setPendingTeam(team);
    setScoreStep(2);
  }
  function wizardChooseReason(resultKey){
    setSelResult(resultKey);
    setScoreStep(3);
  }
  function wizardBack(){
    if(scoreStep===3){ setSelResult(null); setScoreStep(2); }
    else if(scoreStep===2){ setPendingTeam(null); setScoreStep(1); }
  }
  function wizardChoosePlayer(name){
    addPoint(pendingTeam, selResult, name);
  }
  function wizardSkipPlayer(){
    addPoint(pendingTeam, selResult, null);
  }

  // ★handleFault（トグル式フォルト記録の旧実装）は使われていないため削除済み。
  //   サーブのフォルト記録は handleServeRadio（1st/2nd/df 選択方式）に統一されている。

  function handleServeRadio(v){
    if(!currentGame) return;
    const cg=currentGame;
    if(v==="1st"){
      if(fault===0) return; // すでに1stの表示のまま：何もしない
      // 2nd/df から選び直した場合：この得点用に仮登録していたフォルトを取り消して1stに戻す
      const faults = cg.faults ?? [];
      const newFaults = faults.length>0 ? faults.slice(0,-1) : faults;
      persist({...match,games:match.games.map(g=>g.id===cg.id?{...cg,faults:newFaults}:g)});
      setFault(0);
      return;
    }
    if(v==="2nd"){
      if(fault===1) return; // すでに2nd：何もしない
      if(fault===0){
        const f={id:uid(),game_id:cg.id,match_id:match.id,fault_number:(cg.faults?.length??0)+1,server_team:curServer,player_name:curServerIndividual??null,score_a_at:cg.score_a,score_b_at:cg.score_b};
        persist({...match,games:match.games.map(g=>g.id===cg.id?{...cg,faults:[...(cg.faults??[]),f]}:g)});
      }
      // df(2)から2ndへ選び直す場合はフォルト登録は既にあるのでそのまま件数据え置き
      setFault(1);
      return;
    }
    if(v==="df"){
      if(fault===2) return; // すでにdf：何もしない
      if(fault===0){
        const f={id:uid(),game_id:cg.id,match_id:match.id,fault_number:(cg.faults?.length??0)+1,server_team:curServer,player_name:curServerIndividual??null,score_a_at:cg.score_a,score_b_at:cg.score_b};
        persist({...match,games:match.games.map(g=>g.id===cg.id?{...cg,faults:[...(cg.faults??[]),f]}:g)});
      }
      // dfはここでは即座に得点を入れず、「レシーブ側の得点ボタン」を押して初めて確定する状態にする
      setFault(2);
    }
  }

  // ★得点ボタンを先に押す流れ用：指定したゲームの最後のポイントの詳細を後から書き換える（試合中・ゲーム終了直後どちらでも使える汎用版）
  function updatePointDetail(gameId, field, value){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g || g.points.length===0) return;
    const idx = g.points.length-1;
    const lastPt = g.points[idx];
    const newVal = lastPt[field]===value ? null : value; // 同じチップをもう一度押したら解除
    const updatedPt = {...lastPt, [field]:newVal};
    if(field==="result_type"){
      updatedPt.is_winner = newVal ? isWinnerResult(newVal) : null;
    }
    const newPoints = g.points.map((p,i)=> i===idx ? updatedPt : p);
    persist({...match, games: match.games.map(gm=>gm.id===gameId?{...g,points:newPoints}:gm)});
  }
  function updateLastPoint(field, value){
    if(!currentGame) return;
    updatePointDetail(currentGame.id, field, value);
  }
  // ★ゲーム終了画面：詳細は記録する前に入れているので、まず「最後の1点」の内容だけを表示する。
  //   直したいときだけ「直す」を押すと、これまでの詳細入力欄が開く。
  const [lastPtEditOpen, setLastPtEditOpen] = useState(false);
  useEffect(() => { setLastPtEditOpen(false); }, [modal?.gameId]);
  function renderLastPointSummary(gameId){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g || g.points.length===0) return null;
    const lp = g.points[g.points.length-1];
    const who = osDisp(lp.player_name) || (lp.fault_count===2 ? "ダブルフォルト" : "");
    const parts = [lp.result_type && (isWinnerResult(lp.result_type) ? "決め" : "ミス"), lp.side_type&&getSideLabel(lp.side_type), lp.result_type==="error"&&lp.miss_type&&getMissLabel(lp.miss_type), lp.course_type&&getCourseLabel(lp.course_type)].filter(Boolean);
    return (
      <div style={{ textAlign:"left", marginTop:14, paddingTop:12, borderTop:`1px solid ${C.border}` }}>
        <div style={{ fontSize:12, color:C.textSec, fontWeight:700, marginBottom:4 }}>最後の1点</div>
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <div style={{ flex:1, minWidth:0, fontSize:15, fontWeight:800, color:C.text, lineHeight:1.5 }}>
            {who || "（選手未入力）"}{lp.play_type ? `（${getPlayLabel(lp.play_type)}）` : ""}
            {parts.length>0 && <div style={{ fontSize:12.5, fontWeight:700, color:C.textSec }}>{parts.join("・")}</div>}
          </div>
          <button style={{ flexShrink:0, padding:"8px 12px", background:C.white, border:`1px solid ${C.border}`, borderRadius:10, fontSize:13, fontWeight:800, color:C.navy, cursor:"pointer" }}
            onClick={()=>setLastPtEditOpen(v=>!v)}>{lastPtEditOpen ? "▲ 閉じる" : "✏️ 直す"}</button>
        </div>
        {lastPtEditOpen && renderLastPointEditor(gameId)}
      </div>
    );
  }
  // ★最後の1点の複数の項目をまとめて書き換える（1項目ずつ保存すると前の変更が上書きされるため）
  function setLastPointFields(gameId, fields){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g || g.points.length===0) return;
    const idx = g.points.length-1;
    const updatedPt = { ...g.points[idx], ...fields };
    if ("result_type" in fields) updatedPt.is_winner = fields.result_type ? isWinnerResult(fields.result_type) : null;
    persist({ ...match, games: match.games.map(gm=>gm.id===gameId ? { ...g, points: g.points.map((p,i)=>i===idx?updatedPt:p) } : gm) });
  }
  // ★ゲーム終了画面の「✏️ 直す」：記録画面（一画面記録）と同じ見た目・並びで最後の1点を直す
  function renderLastPointEditor(gameId){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g || g.points.length===0) return null;
    const lp = g.points[g.points.length-1];
    if (lp.fault_count===2 && !lp.result_type) {
      return <div style={{ marginTop:12, fontSize:13, color:C.textSec, background:"#f7f8fb", borderRadius:12, padding:12 }}>ダブルフォルトの1点なので、直す項目はありません。間違いのときは「1点前に戻す」で記録し直してください。</div>;
    }
    const SEL = "#0b6e75";
    const kind = lp.result_type ? (isWinnerResult(lp.result_type) ? "winner" : "error") : null;
    const scoreTeam = lp.scoring_team;
    const target = kind==="winner" ? scoreTeam : kind==="error" ? osOther(scoreTeam) : null;
    const btn = { borderRadius:12, borderWidth:2, borderStyle:"solid", borderColor:C.border, background:C.white, color:C.text, fontWeight:800, cursor:"pointer", textAlign:"center", outline:"none", minWidth:0, WebkitTapHighlightColor:"transparent" };
    const sel = (on, color=SEL) => on ? { background:color, borderColor:color, color:C.white } : { borderColor:C.border };
    const head = (n, text, hint) => (
      <div style={{ display:"flex", alignItems:"center", gap:8, fontSize:15, fontWeight:800, color:C.text, margin:"0 0 8px" }}>
        <span style={{ width:24, height:24, borderRadius:"50%", background:C.navy, color:C.white, fontSize:13, display:"inline-flex", alignItems:"center", justifyContent:"center" }}>{n}</span>
        <span>{text}</span>{hint && <span style={{ fontSize:12, color:C.textSec, fontWeight:700 }}>{hint}</span>}
      </div>
    );
    const sub = (t) => <div style={{ fontSize:12.5, fontWeight:800, color:C.textSec, margin:"10px 0 5px 2px" }}>{t}</div>;
    const toggle = (field, v) => setLastPointFields(gameId, { [field]: lp[field]===v ? null : v });
    const group = (t) => {
      const off = !!target && target!==t, wide = !!target && target===t, color = osTeamColor(t);
      return (
        <div key={t} style={{ flex: wide ? "1.8 1 0" : "1 1 0", minWidth:0, borderRadius:12, padding:6, background: t==="A" ? "#e9f8ef" : "#fff1e6", transition:"flex .25s, opacity .2s", ...(off ? { opacity:0.3, pointerEvents:"none", filter:"grayscale(.6)" } : {}) }}>
          <div style={{ fontSize:13, fontWeight:800, color, borderLeft:`3px solid ${color}`, paddingLeft:6, margin:"0 0 6px 2px", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{osTeamName(t)}</div>
          <div style={{ display:"flex", gap:6 }}>
            {osPlayersOf(t).map(p => {
              const on = lp.player_name===p.name;
              const pos = osPositionOf(p);
              const parts = p.label.split(/[\s　]+/);
              const sameSurname = match.players.filter(x => osSurname(x.player_name) === parts[0]).length > 1;
              const lines = (parts.length>1 && sameSurname) ? [parts[0], parts.slice(1).join(" ")] : [parts[0] || p.name];
              return (
                <button key={p.id} onClick={()=>setLastPointFields(gameId, { player_name: p.name })} style={{ ...btn, ...sel(on), flex:"1 1 0", minHeight:58, padding:"6px 4px", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", overflow:"hidden" }}>
                  <FitLines lines={lines} maxPx={lines.length>1 ? 16 : 21} minPx={10} lineHeight={1.2} />
                  {pos && <span style={{ fontSize:11.5, fontWeight:700, opacity:0.8, marginTop:2 }}>{pos}</span>}
                </button>
              );
            })}
          </div>
        </div>
      );
    };
    return (
      <div style={{ marginTop:12, background:"#f7f8fb", border:`1px solid ${C.border}`, borderRadius:14, padding:12, textAlign:"left" }}>
        <div style={{ marginBottom:12 }}>
          {head(1, "この得点は？")}
          <div style={{ display:"flex", gap:8 }}>
            <button onClick={()=>{ if(kind!=="winner") setLastPointFields(gameId, { result_type:"winner", player_name:null, miss_type:null }); }} style={{ ...btn, ...sel(kind==="winner"), flex:1, padding:"10px 4px", fontSize:16 }}>
              決めた<div style={{ fontSize:12, fontWeight:700, opacity:0.8, marginTop:2 }}>（{osTeamName(scoreTeam)}の得点）</div>
            </button>
            <button onClick={()=>{ if(kind!=="error") setLastPointFields(gameId, { result_type:"error", player_name:null, ...(lp.play_type==="serve"?{ play_type:null }:{}) }); }} style={{ ...btn, ...sel(kind==="error","#d8645c"), flex:1, padding:"10px 4px", fontSize:16 }}>
              ミスした<div style={{ fontSize:12, fontWeight:700, opacity:0.8, marginTop:2 }}>（{osTeamName(osOther(scoreTeam))}のミス）</div>
            </button>
          </div>
        </div>
        <div style={{ marginBottom:12, ...(kind ? {} : { opacity:0.35, pointerEvents:"none" }) }}>
          {head(2, kind==="error" ? "誰がミスした？" : kind==="winner" ? "誰が決めた？" : "誰が？")}
          <div style={{ display:"flex", gap:8 }}>{group(leftTeam)}{group(rightTeam)}</div>
        </div>
        <div style={{ marginBottom:12 }}>
          {head(3, "どんなプレー？", "（任意）")}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:6 }}>
            {PLAY_TYPES.map(p => (
              <button key={p.key} disabled={playDisabledFor(lp.result_type, p.key)} onClick={()=>toggle("play_type", p.key)} style={{ ...btn, ...sel(lp.play_type===p.key), padding:"10px 2px", fontSize:14, ...(playDisabledFor(lp.result_type, p.key) ? PLAY_OFF_STYLE : {}) }}>{p.label}</button>
            ))}
          </div>
        </div>
        <div>
          {head(4, "よりくわしく", "（任意）")}
          {sub("フォア／バック")}
          <div style={{ display:"flex", gap:8 }}>
            {SIDE_TYPES.map(sd => <button key={sd.key} onClick={()=>toggle("side_type", sd.key)} style={{ ...btn, ...sel(lp.side_type===sd.key), flex:1, padding:"10px 2px", fontSize:15 }}>{sd.label}</button>)}
          </div>
          {kind==="error" && (<>
            {sub("ミスの種類")}
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              {MISS_TYPES.map(m => <button key={m.key} onClick={()=>toggle("miss_type", m.key)} style={{ ...btn, ...sel(lp.miss_type===m.key), flex:1, padding:"10px 2px", fontSize:15 }}>{m.label}</button>)}
            </div>
          </>)}
          {sub("コース")}
          <div style={{ display:"flex", gap:8 }}>
            {COURSE_TYPES.map(c => <button key={c.key} onClick={()=>toggle("course_type", normCourse(lp.course_type)===c.key ? lp.course_type : c.key)} style={{ ...btn, ...sel(normCourse(lp.course_type)===c.key), flex:1, padding:"10px 2px", fontSize:15 }}>{c.dir}</button>)}
          </div>
        </div>
        <button onClick={()=>setLastPtEditOpen(false)} style={{ width:"100%", marginTop:14, padding:12, background:C.white, border:`1px solid ${C.border}`, borderRadius:10, fontSize:14, fontWeight:800, color:C.navy, cursor:"pointer" }}>▲ 閉じる（変更はすぐ保存されます）</button>
      </div>
    );
  }
  // ★ゲーム終了直後の「最後の1点」に詳細を追記するための共通UIブロック（旧版・現在は未使用）
  function renderPointDetailEditor(gameId){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g || g.points.length===0) return null;
    const lp = g.points[g.points.length-1];
    const isMiss = lp.result_type==="error"; // 相手ミスのときだけ③を出す
    const detailParts=[lp.player_name,lp.play_type&&getPlayLabel(lp.play_type),lp.result_type&&getResultLabel(lp.result_type),lp.side_type&&getSideLabel(lp.side_type),lp.course_type&&getCourseLabel(lp.course_type),isMiss&&lp.miss_type&&getMissLabel(lp.miss_type)].filter(Boolean);
    return (
      <div style={{ textAlign:"left",marginTop:14,paddingTop:14,borderTop:`1px solid ${C.border}` }}>
        <div style={{ fontSize:11,color:C.textSec,fontWeight:700,marginBottom:4 }}>最後の1点の詳細を追加（任意）</div>
        <div style={{ fontSize:13,fontWeight:700,color:"#2f64a8",marginBottom:8 }}>{detailParts.length>0?detailParts.join("・"):"選手・結果・プレイ内容は未選択"}</div>
        <div style={{ marginBottom:8 }}>
          {allPlayers.map(p=>{ const isSel=lp.player_name===p.name; return <span key={p.id} style={S.chip(isSel)} onClick={()=>updatePointDetail(gameId,"player_name",p.name)}>{p.name}</span>; })}
        </div>
        <div style={{ marginBottom:8 }}>
          {RESULT_TYPES.map(r=>{ const isSel=lp.result_type===r.key; return <span key={r.key} style={S.chip(isSel)} onClick={()=>updatePointDetail(gameId,"result_type",r.key)}>{r.label}</span>; })}
        </div>
        <div style={{ marginBottom:8 }}>
          <div style={{ fontSize:13,color:"#5a6478",fontWeight:800,marginBottom:6 }}>① プレー内容</div>
          {playTypesFor(lp.result_type).map(p=>{ const isSel=lp.play_type===p.key; return <span key={p.key} style={S.chip(isSel)} onClick={()=>updatePointDetail(gameId,"play_type",p.key)}>{p.label}</span>; })}
        </div>
        <div style={{ marginBottom:8 }}>
          <div style={{ fontSize:13,color:"#5a6478",fontWeight:800,marginBottom:6 }}>② フォア / バック</div>
          {SIDE_TYPES.map(s=>{ const isSel=lp.side_type===s.key; return <span key={s.key} style={S.chip(isSel)} onClick={()=>updatePointDetail(gameId,"side_type",s.key)}>{s.label}</span>; })}
        </div>
        {/* ★コースまで入力するのは負担が大きいという声があったため、コースは最後に置く */}
        {isMiss && (
          <div style={{ marginBottom:8 }}>
            <div style={{ fontSize:13,color:"#5a6478",fontWeight:800,marginBottom:6 }}>③ ミスの種類</div>
            {MISS_TYPES.map(m=>{ const isSel=lp.miss_type===m.key; return <span key={m.key} style={S.chip(isSel)} onClick={()=>updatePointDetail(gameId,"miss_type",m.key)}>{m.label}</span>; })}
          </div>
        )}
        <div>
          <div style={{ fontSize:13,color:"#5a6478",fontWeight:800,marginBottom:6 }}>{isMiss ? "④" : "③"} コース</div>
          <CoursePicker value={lp.course_type ?? null} onChange={v=>updatePointDetail(gameId,"course_type",v)}/>
        </div>
      </div>
    );
  }

  function undo(){
    if(!currentGame||currentGame.points.length===0) return;
    const cg=currentGame;
    const newPts=cg.points.slice(0,-1);
    const last=newPts[newPts.length-1];
    const updG={...cg,points:newPts,score_a:last?.score_a_after??0,score_b:last?.score_b_after??0,winner_team:null};
    persist({...match,games:match.games.map(g=>g.id===cg.id?updG:g)});
    setFault(0);
  }

  // ★このゲームを飛ばす：取ったチームだけ決めて（分かればスコアも）、次のゲームへ進む。
  //   ここまで記録したポイントは消さずに残す（スタッツにはそのまま入る）。
  function skipCurrentGame(winner, scoreA, scoreB){
    if(!currentGame || !winner) return;
    const cg = currentGame;
    const updG = { ...cg, score_a: scoreA ?? 0, score_b: scoreB ?? 0, winner_team: winner };
    const games = match.games.map(g=>g.id===cg.id?updG:g);
    const sA = games.filter(g=>g.winner_team==="A").length, sB = games.filter(g=>g.winner_team==="B").length;
    resetSel(); setFault(0);
    if (sA >= winGames || sB >= winGames) {
      persist({ ...match, games, match_score_a:sA, match_score_b:sB });
      setModal({ type:"matchOver", winner, gameId:cg.id, sA, sB });
      return;
    }
    const num = games.length + 1;
    const srv = gameServer(match.first_server || "A", num);
    const ng = { id:uid(), match_id:match.id, game_number:num, server_team:srv, is_final:isFinalGame(match.game_format, sA, sB), score_a:0, score_b:0, winner_team:null, points:[], faults:[] };
    persist({ ...match, games:[...games, ng], match_score_a:sA, match_score_b:sB });
  }

  // ★試合の途中から記録する：第1〜第(N-1)ゲームは取ったチームだけ入れ、第Nゲームから1点ずつ記録する
  function startFromMiddle(startNum, winners, serverN){
    if (startingGameRef.current) return;
    const first = (startNum % 2 === 1) ? serverN : (serverN === "A" ? "B" : "A"); // 第Nゲームのサーブから第1ゲームのサーブを逆算
    const prior = [];
    for (let k=1; k<startNum; k++) {
      prior.push({ id:uid(), match_id:match.id, game_number:k, server_team:gameServer(first, k), is_final:false, score_a:0, score_b:0, winner_team:winners[k], points:[], faults:[] });
    }
    const sA = prior.filter(g=>g.winner_team==="A").length, sB = prior.filter(g=>g.winner_team==="B").length;
    const ng = { id:uid(), match_id:match.id, game_number:startNum, server_team:serverN, is_final:isFinalGame(match.game_format, sA, sB), score_a:0, score_b:0, winner_team:null, points:[], faults:[] };
    const statusFix = (match.status === "scheduled" || match.status === "waiting") ? { status:"active" } : {};
    startingGameRef.current = true; setStartingGame(true);
    persist({ ...match, ...statusFix, first_server:first, order_a: match.order_a || "p1", order_b: match.order_b || "p1",
      games:[...prior, ng], match_score_a:sA, match_score_b:sB });
    setTimeout(()=>{ startingGameRef.current = false; setStartingGame(false); }, 800);
  }

  // ★ゲーム終了直後（「第Nゲーム終了！」画面）に、その決着点だけを取り消して試合を続けられるようにする。
  //   通常のundo()はcurrentGame（勝者未確定のゲーム）にしか使えないため、
  //   すでにwinner_teamが確定した直後のゲームを対象にする専用処理を用意する。
  function undoGameEndingPoint(gameId, winner){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g || g.points.length===0) return;
    const newPts = g.points.slice(0,-1);
    const last = newPts[newPts.length-1];
    const updG = { ...g, points:newPts, score_a:last?.score_a_after??0, score_b:last?.score_b_after??0, winner_team:null };
    const newMA = match.match_score_a - (winner==="A"?1:0);
    const newMB = match.match_score_b - (winner==="B"?1:0);
    persist({ ...match, games: match.games.map(gm=>gm.id===gameId?updG:gm), match_score_a:newMA, match_score_b:newMB });
    setModal(null);
    resetSel();
    setFault(0);
  }

  // ★試合終了後、過去の任意のゲームのポイント構成が変わった際にスコア・勝敗を再計算して保存する共通処理
  function applyGamePointsChange(gameId, newPoints){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g) return;
    let a=0, b=0;
    const recalced = newPoints.map((p,i)=>{
      if(p.scoring_team==="A") a++; else b++;
      return {...p, point_number:i+1, score_a_after:a, score_b_after:b};
    });
    const finalA = recalced.length ? recalced[recalced.length-1].score_a_after : 0;
    const finalB = recalced.length ? recalced[recalced.length-1].score_b_after : 0;
    const newWinner = g.is_final ? checkFinalWinner(finalA,finalB) : checkNormalWinner(finalA,finalB);
    // ★「飛ばした」「勝敗のみ」など、点の記録とスコアが合っていないゲームは、
    //   あとから点を足している途中（まだ勝者が決まらない間）は、入れてあった勝敗・スコアをそのまま残す
    const oldA = (g.points||[]).filter(p=>p.scoring_team==="A").length, oldB = (g.points||[]).filter(p=>p.scoring_team==="B").length;
    const wasManual = !!g.winner_team && (oldA !== (g.score_a??0) || oldB !== (g.score_b??0));
    const updG = (wasManual && !newWinner)
      ? {...g, points:recalced}
      : {...g, points:recalced, score_a:finalA, score_b:finalB, winner_team:newWinner};
    const newGames = match.games.map(gm=>gm.id===gameId?updG:gm);
    const newScoreA = newGames.filter(gm=>gm.winner_team==="A").length;
    const newScoreB = newGames.filter(gm=>gm.winner_team==="B").length;
    persist({...match, games:newGames, match_score_a:newScoreA, match_score_b:newScoreB});
  }

  function deletePointFromGame(gameId, pointId){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g) return;
    applyGamePointsChange(gameId, g.points.filter(p=>p.id!==pointId));
  }

  function updatePointInGame(gameId, pointId, updates){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g) return;
    applyGamePointsChange(gameId, g.points.map(p=>p.id===pointId?{...p,...updates}:p));
  }

  // ★試合終了後、過去の任意のゲームの好きな位置にポイントを挿入する
  function insertPointInGame(gameId, atIndex, values){
    const g = match.games.find(gm=>gm.id===gameId);
    if(!g) return;
    const newPoint = { id:uid(), game_id:gameId, match_id:match.id, ...values };
    const newPoints = [...g.points.slice(0,atIndex), newPoint, ...g.points.slice(atIndex)];
    applyGamePointsChange(gameId, newPoints);
  }

  const allPlayers = match.players.map(p=>({ id:p.id, name:p.player_name, team:p.team }));

  // ============================================================
  // ★一画面記録（画面を切り替えずに①〜⑥を選んで「記録する」）
  // ============================================================
  const osOther = (t) => t==="A" ? "B" : "A";
  const osTeamColor = (t) => t==="A" ? C.teamA : C.teamB;
  // チームの呼び名：同校対決のときは学校名では区別できないので名字で呼ぶ
  const osTeamName = (t) => {
    const club = (t==="A" ? aClub : bClub).trim();
    const n = (isSameSchoolMatch ? familyNamesOf(t) : club) || familyNamesOf(t) || (t==="A" ? "自チーム" : "相手");
    return [...n].length > 10 ? [...n].slice(0,10).join("") + "…" : n; // ★10文字を超える学校名は「…」で省略
  };
  // 選手（登録順）。名前が空欄なら仮名（自チーム=選手1/選手2、相手=選手A/選手B）
  // ★相手ペアを選ばずに始めた試合は相手の選手データが無いため、仮名の選手を補って必ずボタンを出す。
  //   相手の仮名は記録上は「選手A／選手B」（あとで本名に置き換える仕組みと合わせるため）、画面では「選手1／選手2」と表示する。
  const osDisp = (n) => n==="選手A" ? "選手1" : n==="選手B" ? "選手2" : n;
  const osPlayersOf = (t) => {
    const rows = match.players.filter(p=>p.team===t).sort((x,y)=>(x.order_num??0)-(y.order_num??0));
    const need = Math.max(rows.length, match.players.filter(p=>p.team==="A").length, match.players.filter(p=>p.team==="B").length, 1);
    const list = rows.map((p,i)=>({ id:p.id, idx:i, name:(p.player_name && p.player_name.trim()) || (t==="B" ? PLACEHOLDER_NAMES[i] : `選手${i+1}`), club:(p.club_name||"").trim() }));
    for (let i=list.length; i<need; i++) list.push({ id:`ph-${t}-${i}`, idx:i, name: t==="B" ? (PLACEHOLDER_NAMES[i] ?? `選手${i+1}`) : `選手${i+1}`, club:"" });
    return list.map(p => ({ ...p, label: osDisp(p.name) }));
  };
  const osSurname = (n) => String(n||"").trim().split(/[\s　]+/)[0];
  // ★前衛・後衛：選手マスターに登録があれば表示（学校名で絞ってから名前で探す）。無ければ表示しない。
  //   選手未登録の仮名（選手1/選手2・選手A/選手B）のときは、1人目＝後衛、2人目＝前衛と表示する。
  const osPositionOf = (p) => {
    if (/^選手[12AB]$/.test(p.name)) return p.idx===0 ? "後衛" : "前衛";
    const same = osRoster.filter(r => (r.player_name||"").trim() === p.name);
    if (same.length === 0) return "";
    let hit = p.club ? same.filter(r => (r.team_name||"").trim() === p.club) : [];
    if (hit.length !== 1 && same.length === 1 && !(same[0].team_name||"").trim()) hit = same;
    if (hit.length !== 1) return "";
    const pos = hit[0].position;
    return (pos==="前衛" || pos==="後衛") ? pos : "";
  };
  const osIsDF = fault===2;
  // DFのときは得点チーム＝レシーブ側に自動で決まる
  const osScoreTeam = osIsDF ? (curServer ? osOther(curServer) : null) : osTeam;
  // ④で押せるチーム：決めた＝得点したチーム／ミスした＝ミスした側（相手）
  const osTargetTeam = osIsDF || !osKind || !osTeam ? null : (osKind==="winner" ? osTeam : osOther(osTeam));
  const osReady = !!currentGame && (osIsDF ? !!osScoreTeam : (!!osTeam && !!osKind && !!osPlayer));
  // ★自動スクロール：次に押すボタンの列が、①サーブのボタンが最初に表示されていた高さに来るようにする
  function osGoTo(key, ratio=1){
    clearTimeout(osScrollTimer.current);
    if (!osAutoScroll) return; // ★自動スクロールOFFのときは動かさない
    osScrollTimer.current = setTimeout(() => {
      const el = osRefs[key]?.current, sv = osRefs.sv.current;
      if (!el || !sv) return;
      const docTop = (e) => e.getBoundingClientRect().top + window.scrollY;
      if (osAnchorY.current == null) osAnchorY.current = Math.max(80, docTop(sv) - (window.scrollY > 0 ? 0 : 0));
      // ★なめらかスクロール中にタップすると、スマホではタップが「スクロールを止める」動作に使われて
      //   ボタンが反応しない（画面が固まったように見える）ため、一瞬で移動させる
      window.scrollTo({ top: Math.max(0, (docTop(el) - osAnchorY.current) * ratio), behavior:"auto" });
    }, 30);
  }
  function osPickServe(v){ // "1st" | "2nd" | "df"
    handleServeRadio(v);
    setOsTeam(null); setOsKind(null); setOsPlayer(null); setOsPlay(null); setOsSide(null); setOsMiss(null); setOsCourse(null);
    if (v !== "df") osGoTo("team", 0.5);
  }
  function osPickTeam(t){ setOsTeam(t); setOsKind(null); setOsPlayer(null); setOsMiss(null); osGoTo("kind"); }
  function osPickKind(k){ setOsKind(k); setOsPlayer(null); setOsMiss(null); if (k==="error" && osPlay==="serve") setOsPlay(null); osGoTo("player"); }
  function osPickPlayer(n){ setOsPlayer(n); osGoTo("play"); }
  function osPickPlay(k){ const v = osPlay===k ? null : k; setOsPlay(v); if (v) osGoTo("side"); }
  function osPickSide(k){ const v = osSide===k ? null : k; setOsSide(v); if (v) osGoTo(osKind==="error" ? "miss" : "course"); }
  function osPickMiss(k){ const v = osMiss===k ? null : k; setOsMiss(v); if (v) osGoTo("course"); }
  function osPickCourse(k){ setOsCourse(osCourse===k ? null : k); }
  function osClear(){
    if (fault!==0) handleServeRadio("1st");
    resetSel();
    window.scrollTo({ top:0, behavior:"auto" });
  }
  function osRecord(){
    if (!osReady) return;
    clearTimeout(osScrollTimer.current);
    const team = osScoreTeam;
    const sc = currentGame ? { a: currentGame.score_a + (team==="A"?1:0), b: currentGame.score_b + (team==="B"?1:0) } : null;
    if (osIsDF) addPoint(team, null, null, {});
    else addPoint(team, osKind, osPlayer, { play_type:osPlay, side_type:osSide, course_type:osCourse, miss_type: osKind==="error" ? osMiss : null });
    if (sc) {
      const l = isYounger ? sc.a : sc.b, r = isYounger ? sc.b : sc.a;
      setOsToast(`${osTeamName(team)}に1点（${l}-${r}）`);
      clearTimeout(osToastTimer.current);
      osToastTimer.current = setTimeout(()=>setOsToast(""), 1600);
    }
    window.scrollTo({ top:0, behavior:"auto" });
  }
  const osRecording = tab==="record" && !correctMode && !!currentGame && match.status!=="finished" && !viewOnly;

  const [navigatingBack, setNavigatingBack] = useState(false);
  async function handleBack() {
    // ★未同期のデータが残っている状態でこの画面を離れると、自動リトライが止まってしまうため、
    //   一度確認する（オフラインで記録を続けている最中に誤って戻るのを防ぐ）
    if (syncStatus !== "synced") {
      if (!window.confirm("まだサーバーに保存できていない記録があります。\n" + (syncErrorMsg ? "原因：" + syncErrorMsg + "\n" : "") + "このまま戻ると自動での再送が止まります。\n記録自体は端末に残っているので、この画面をもう一度開けば再送は再開されます。\n\n戻りますか？")) {
        return;
      }
    }
    setNavigatingBack(true);
    onBack();
  }

  return (
    <div style={S.page}>
      {restoredNotice && (
        <div style={{ background:"#fff3e0", borderBottom:"1px solid #ffd9b3", padding:"8px 14px", fontSize:11.5, color:"#8a5a00", display:"flex", alignItems:"center", gap:8 }}>
          <span style={{ flex:1 }}>⚠️ 前回、同期できないまま終了した記録を復元しました。保存できる状態になり次第、自動で保存されます。</span>
          <button style={{ background:"none", border:"none", color:"#8a5a00", fontWeight:700, fontSize:13, cursor:"pointer" }} onClick={()=>setRestoredNotice(false)}>✕</button>
        </div>
      )}
      {/* スコアボードヘッダー */}
      <div style={{ background:`linear-gradient(135deg,${C.navy},${C.navyMid})`, padding:"10px 14px" }}>
        <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10 }}>
          <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer", opacity:navigatingBack?0.5:1, flex:"none" }} disabled={navigatingBack} onClick={handleBack}>{navigatingBack?"…":"←"}</button>
          <div style={{ textAlign:"center", flex:1, minWidth:0, padding:"0 6px" }}>
            {match.tournament_name&&<div style={{ fontSize:11,color:"rgba(255,255,255,0.8)",fontWeight:700,overflowWrap:"break-word" }}>{match.tournament_name}{match.round?` · ${match.round}`:""}</div>}
            {/* ★記録画面では日付・会場は表示しない（スコア表示を広く使うため）。日付・会場は✏️（試合情報）で確認できる */}
            <div style={{ fontSize:10.5,color:"rgba(255,255,255,0.6)" }}>{match.court_number?`${match.court_number} · `:""}{match.game_format}Gマッチ</div>
            {!viewOnly && (match.status==="active" || match.status==="waiting" || match.status==="scheduled") && (
              <div style={{ marginTop:3, display:"inline-flex", alignItems:"center", gap:4, fontSize:9.5, fontWeight:700, borderRadius:99, padding:"1px 8px",
                background: syncStatus==="synced" ? "rgba(46,204,113,0.2)" : syncStatus==="error" ? "rgba(255,255,255,0.15)" : "rgba(249,115,22,0.2)",
                color: syncStatus==="synced" ? "#7CF0B0" : syncStatus==="error" ? "#ffb199" : "#ffcf8f" }}>
                {syncStatus==="synced"
                  ? "🟢 同期済み"
                  : syncStatus==="error"
                    ? (navigator.onLine ? "🔴 保存できません（タップで原因）" : "🔴 未同期（電波待ち・記録は端末に保存済み）")
                    : "🟡 保存中…"}
              </div>
            )}
            {/* ★オンラインなのに保存できない＝サーバー側の問題。原因をそのまま見せて直せるようにする。 */}
            {!viewOnly && syncStatus==="error" && navigator.onLine && syncErrorMsg && (
              <div
                style={{ marginTop:4, fontSize:9.5, color:"#ffd5c9", lineHeight:1.5, cursor:"pointer", wordBreak:"break-all" }}
                onClick={()=>alert("サーバーに保存できませんでした。\n\n原因：" + syncErrorMsg + "\n\n記録は端末に残っています。原因を解消してからこの画面を開き直すと、自動で再送されます。")}
              >{syncErrorMsg}</div>
            )}
          </div>
          <div style={{ display:"flex", gap:6, flex:"none" }}>
            {match.status==="active" && (
              <button
                style={{ background:"rgba(255,255,255,0.15)",border:"none",borderRadius:8,color:C.white,fontSize:13,padding:"5px 8px",cursor:"pointer", opacity: refreshing ? 0.5 : 1 }}
                onClick={onRefresh}
                disabled={refreshing}
                title="最新データに更新"
              >{refreshing ? "..." : "🔄"}</button>
            )}
            {/* ★記録中はLINE共有を「⋯」（その他の操作）に入れたので、ヘッダーには出さない（観戦中・試合前後は従来通り） */}
            {(match.status==="active" || match.status==="finished") && (viewOnly || !currentGame || match.status==="finished") && (
              <button
                style={{ background:"#06C755",border:"none",borderRadius:8,padding:"5px 8px",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center" }}
                onClick={()=>shareToLine(match.status==="waiting" ? "待機中" : match.status==="finished" ? "試合終了" : "試合中")}
                title="LINEで共有"
              ><svg viewBox="0 0 24 24" width="15" height="15" fill="none"><path d="M12 3C6.48 3 2 6.69 2 11.25c0 2.99 1.91 5.61 4.79 7.08-.21.79-.76 2.83-.87 3.27-.14.55.2.54.42.4.17-.11 2.77-1.88 3.89-2.65.57.08 1.16.13 1.77.13 5.52 0 10-3.69 10-8.25S17.52 3 12 3z" fill="white"/></svg></button>
            )}
            {/* ★団体戦の1戦を記録し直したいとき用。以前は団体戦詳細の一覧側にあったボタンをこちらに統一した */}
            {teamMatchId && match.status==="finished" && !viewOnly && (
              <button
                style={{ background:"rgba(255,255,255,0.15)",border:"none",borderRadius:8,color:C.white,fontSize:13,padding:"5px 8px",cursor:"pointer" }}
                title="点数から記録し直す"
                onClick={async ()=>{
                  const { data: gamesData } = await supabase.from("games").select("id, points(id)").eq("match_id", match.id);
                  const hasPoints = (gamesData||[]).some(g => (g.points||[]).length>0);
                  const msg = hasPoints
                    ? "すでに記録されたポイントがすべて消えます。ポイントから記録し直しますか？"
                    : "スコアをリセットして、ポイントから記録し直しますか？";
                  if (!window.confirm(msg)) return;
                  try {
                    await resetMatchToUnrecorded(match.id);
                    await supabase.from("team_match_games").update({ status:"waiting", recorder_id:null, recorder_name:null }).eq("match_id", match.id);
                    onBack && onBack();
                  } catch(e) {
                    alert("エラー: " + (e.message || e));
                  }
                }}
              >🎾</button>
            )}
            <button style={{ background:"rgba(255,255,255,0.15)",border:"none",borderRadius:8,color:C.white,fontSize:13,padding:"5px 8px",cursor:"pointer" }} onClick={()=>onEdit&&onEdit(match.id)} title="試合情報を編集">✏️</button>
          </div>
        </div>

        {/* スコアボード: 行ごとgridで左右高さを統一 */}
        <div style={{ background:"rgba(0,0,0,0.25)",borderRadius:14,padding:"10px 8px" }}>
          {/* ★文字が見えにくいという声への対応（学校名・選手名・ゲームカウントを大きく）。
               サーブ側は、学校名の上の「🎾 サーブ」の文字ではなく、ポイント数字の横（中央の枠のすぐ横）の黄色いバーで示す。
               バーの意味が分かるよう、ゲームカウントの枠の上に「▮ サーブ」の説明を出す。 */}
          {/* チーム名行：学校名はチーム色のバッジ（長い学校名は2行まで・10文字を超えたら「…」） */}
          <div style={{ display:"grid",gridTemplateColumns:"minmax(0,1fr) 100px minmax(0,1fr)",gap:6,marginBottom:4,alignItems:"start" }}>
            {[leftTeam, null, rightTeam].map((t,i)=> t==null ? <div key={i}/> : (
              <div key={i} style={{ minWidth:0, textAlign:"center" }}>
                {(t===leftTeam?leftClub:rightClub) && (
                  <FitBadge text={t===leftTeam?leftClub:rightClub} maxPx={16} minPx={10} style={{ fontWeight:800, color:C.white, background:t==="A"?C.teamA:C.teamB, borderRadius:7, padding:"2px 9px" }} />
                )}
              </div>
            ))}
          </div>
          {/* 選手名行（ダブルスは1人1行）。入りきらない長い名前は文字を小さく→それでも無理なら名字だけ */}
          <div style={{ display:"grid",gridTemplateColumns:"minmax(0,1fr) 100px minmax(0,1fr)",gap:6,marginBottom:6 }}>
            {[leftLabel, null, rightLabel].map((lab,i)=> lab==null ? <div key={i}/> : (
              <div key={i} style={{ minWidth:0, textAlign:"center", color:C.white, fontWeight:800 }}>
                {(()=>{ const t = i===0 ? leftTeam : rightTeam; const names = osPlayersOf(t).map(p=>p.label); return names.length>0 && (
                  <FitLines lines={names} fallbackLines={names.map(n=>String(n).trim().split(/[\s　]+/)[0])} maxPx={18} minPx={12} lineHeight={1.3} />
                ); })()}
              </div>
            ))}
          </div>
          {/* 左右=ゲーム内ポイント（大きく）、中央=ゲームカウント */}
          <div style={{ display:"grid",gridTemplateColumns:"1fr 100px 1fr",gap:6,alignItems:"center" }}>
            {/* 左 */}
            <div style={{ position:"relative",textAlign:"center" }}>
              <div style={{ fontSize:56,fontWeight:900,color:C.white,lineHeight:1 }}>
                {currentGame ? leftScore(currentGame) : "—"}
              </div>
              {curServer && curServer===leftTeam && <span style={{ position:"absolute",right:2,top:"50%",transform:"translateY(-50%)",width:6,height:44,borderRadius:3,background:C.serve }}/>}
            </div>
            {/* 中央：ゲームカウント */}
            {/* ★「▮ サーブ」の説明は枠の上にはみ出す形（absolute）で置き、行の高さに含めない。
                 こうすると左右のポイント数字と黄色いバーが、ゲームカウントの枠の上下中央にそろう。 */}
            <div style={{ textAlign:"center",position:"relative" }}>
              {/* ★サーブ側は、得点の横の大きい黄色の棒だけで示す（ゲームカウントの上の小さい表示は廃止） */}
              <div style={{ background:"rgba(255,255,255,0.15)",borderRadius:10,padding:"6px 4px" }}>
                <div style={{ fontSize:11,fontWeight:700,color:"rgba(255,255,255,0.75)",marginBottom:2 }}>
                  {currentGame ? ("G" + currentGame.game_number + (currentGame.is_final ? " F" : "")) : ""}
                </div>
                <div style={{ display:"flex",gap:6,alignItems:"center",justifyContent:"center" }}>
                  <span style={{ fontSize:28,fontWeight:900,lineHeight:1.1,color:leftMatchScore>=winGames?"#fbbf24":C.white }}>{leftMatchScore}</span>
                  {/* ★ハイフンが小さく見えにくかったため、数字とバランスが取れる太さ・大きさにする */}
                  <span style={{ color:"rgba(255,255,255,0.8)",fontSize:24,fontWeight:900,lineHeight:1 }}>-</span>
                  <span style={{ fontSize:28,fontWeight:900,lineHeight:1.1,color:rightMatchScore>=winGames?"#fbbf24":C.white }}>{rightMatchScore}</span>
                </div>
                {fault===1 && <div style={{ fontSize:11,color:C.serve,marginTop:2,fontWeight:700 }}>1st F</div>}
              </div>
            </div>
            {/* 右 */}
            <div style={{ position:"relative",textAlign:"center" }}>
              {curServer && curServer===rightTeam && <span style={{ position:"absolute",left:2,top:"50%",transform:"translateY(-50%)",width:6,height:44,borderRadius:3,background:C.serve }}/>}
              <div style={{ fontSize:56,fontWeight:900,color:C.white,lineHeight:1 }}>
                {currentGame ? rightScore(currentGame) : "—"}
              </div>
            </div>
          </div>
        </div>

        {/* ゲームバッジ */}
        <div style={{ display:"flex",gap:5,marginTop:8,flexWrap:"wrap",justifyContent:"center" }}>
          {match.games.map(g=>(
            <div key={g.id} style={{ padding:"2px 8px",borderRadius:20,fontSize:10,fontWeight:700,background:g.winner_team===leftTeam?(isYounger?"#2ecc71":"#f97316"):g.winner_team===rightTeam?(isYounger?"#f97316":"#2ecc71"):"rgba(255,255,255,0.2)",color:C.white,
              ...(isWinOnlyGame(g) ? { background:"transparent", border:`1.5px dashed ${g.winner_team==="A"?"#2ecc71":"#f97316"}`, color:g.winner_team==="A"?"#7ee2a8":"#ffb27a", padding:"1px 7px" } : {}) }}>
              {g.is_final?"🔥":""}G{g.game_number}: {isWinOnlyGame(g) ? osTeamName(g.winner_team) : `${leftScore(g)}-${rightScore(g)}`}
            </div>
          ))}
        </div>
        {currentGameIsFinal&&currentGame&&<div style={{ textAlign:"center",marginTop:6 }}><span style={{ fontSize:10,fontWeight:800,color:C.white,background:"#dc2626",padding:"2px 10px",borderRadius:20 }}>🔥 ファイナルゲーム（7点先取）</span></div>}
      </div>

      {/* タブ */}
      {viewOnly && (
        <div style={{ background:"#f5f5f5", borderBottom:"1px solid #e0e0e0", padding:"8px 14px" }}>
          {/* ★誰が記録中かを表示（団体戦の番手一覧と同じ見せ方にそろえる） */}
          {!teamMatchId && match.recorder_name && match.status!=="finished" && (
            <div style={{ marginBottom:6 }}>
              <span style={{ fontSize:11, color:"#dc2626", fontWeight:700, background:"#fdecea", padding:"3px 9px", borderRadius:20 }}>🔴 {match.recorder_name} 記録中</span>
            </div>
          )}
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
            <span style={{ fontSize:12, color:C.textSec, fontWeight:700 }}>{isViewer ? "👀 閲覧専用（記録・編集はできません）" : "👁 観戦モード（スコア閲覧のみ）"}</span>
            <button
              style={{ background:C.navy, border:"none", borderRadius:8, color:"#fff", fontSize:12, padding:"5px 10px", cursor:"pointer", opacity: refreshing ? 0.5 : 1 }}
              onClick={onRefresh} disabled={refreshing}
            >{refreshing ? "更新中..." : "🔄 最新に更新"}</button>
          </div>
          {/* ★試合が終了していなければ、いつでも自分が記録者としてロックを引き継げるようにする
                （記録者ロックが自分以外・または不整合になっていても、これで即座に復帰できる） */}
          {!isViewer && match.status!=="finished" && (
            <button
              style={{ ...S.btn(C.navy), fontSize:12, padding:"9px", marginTop:8 }}
              onClick={async ()=>{
                try {
                  const { data:{ user } } = await supabase.auth.getUser();
                  const profile = await getMyProfile();
                  if (teamMatchId) {
                    const { data: tmg } = await supabase.from("team_match_games").select("id").eq("match_id", match.id).maybeSingle();
                    if (tmg) await updateTeamMatchGame(tmg.id, { recorder_id:user.id, recorder_name: profile?.name || null });
                  } else {
                    // ★created_byは「誰が試合を作ったか」の記録なので書き換えない。記録者だけを付け替える。
                    await supabase.from("matches").update({ recorder_id:user.id, recorder_name: profile?.name || null }).eq("id", match.id);
                  }
                  onClaimRecorder && onClaimRecorder();
                  onReload();
                } catch(e) {
                  alert("エラー: " + (e.message || e));
                }
              }}
            >🔓 自分が記録者になる（続きから記録する）</button>
          )}
          {/* ★記録者ロックが残ったまま操作不能になった場合の逃げ道（団体戦と同じ）。
                通信が切れた・画面をそのまま閉じた等でロックが外れないことがあるため。 */}
          {!isViewer && !teamMatchId && match.recorder_name && match.status!=="finished" && (
            <div style={{ textAlign:"center", marginTop:6 }}>
              <button
                style={{ background:"none", border:"none", color:C.textSec, fontSize:11, textDecoration:"underline", cursor:"pointer" }}
                onClick={async ()=>{
                  if (!window.confirm("この試合の記録者ロックを解除しますか？\n（他の人が今まさに記録中でないことを確認してください）")) return;
                  try {
                    await releaseMatchRecorder(match.id);
                    onReload();
                  } catch(e) { alert("エラー: " + (e.message || e)); }
                }}
              >記録者ロックを解除する</button>
            </div>
          )}
          {/* ★「結果だけ記録」で終えた試合（ゲームが1つも無いまま終了扱い）は、
                ここから直接ポイント記録に切り替えられるようにする */}
          {match.status==="finished" && match.games.length===0 && (
            <button
              style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), fontSize:12, padding:"9px", marginTop:8 }}
              onClick={async ()=>{
                const msg = "スコアをリセットして、ここからポイントを記録し直しますか？";
                if (!window.confirm(msg)) return;
                try {
                  const { data:{ user } } = await supabase.auth.getUser();
                  const profile = await getMyProfile();
                  await resetMatchToUnrecorded(match.id);
                  if (teamMatchId) {
                    const { data: tmg } = await supabase.from("team_match_games").select("id").eq("match_id", match.id).maybeSingle();
                    if (tmg) await updateTeamMatchGame(tmg.id, { status:"waiting", recorder_id:user.id, recorder_name: profile?.name || null });
                  } else {
                    await supabase.from("matches").update({ recorder_id:user.id, recorder_name: profile?.name || null }).eq("id", match.id);
                  }
                  onReload();
                } catch(e) {
                  alert("エラー: " + (e.message || e));
                }
              }}
            >🎾 ここからポイントを記録し直す</button>
          )}
        </div>
      )}
      <div style={{ display:"flex",background:C.white,borderBottom:`1px solid ${C.border}` }}>
        {[["record","記録"],["score","スコア"],["stats","スタッツ"],["sheet","検算"]].map(([v,l])=>(
          <button key={v} style={{ flex:1,padding:11,border:"none",cursor:"pointer",background:"transparent",fontWeight:tab===v?700:400,fontSize:14,color:tab===v?C.accent:C.textSec,borderBottom:tab===v?`3px solid ${C.accent}`:"3px solid transparent" }} onClick={()=>setTab(v)}>{l}</button>
        ))}
      </div>

      {/* 記録タブ */}
      {tab==="record"&&(
        <div style={{ padding:"10px 12px 20px" }}>
          {match.games.length>0 && !viewOnly && !osRecording && (
            <div style={{ textAlign:"right", marginBottom:8 }}>
              <button
                style={{ border:"1px solid "+C.border, background:C.gray, borderRadius:8, fontSize:11, color:C.textSec, cursor:"pointer", padding:"5px 10px", fontWeight:700 }}
                onClick={()=>setResetConfirm(true)}
              >🗑️ スコア全削除</button>
            </div>
          )}
          {!correctMode&&match.games.length===0&&match.status!=="finished"&&!viewOnly&&(
            <div style={{ padding:"4px 0 0" }}>
              {/* ★第1ゲームの準備カード（案A）：最初にサーブするペアを切り替えボタンで選び、
                  第1ゲームで分かる2つ（サーブ側のサーブの1人目・レシーブ側のレシーブの1人目）だけを並べる。
                  ここで変えると試合情報の値も変わる。残りの2つは試合情報（✏️）で確認・修正する */}
              {(() => {
                // ★最初にサーブするペアが未設定の試合は、自チーム（A）が選ばれた状態から始める
                const fs = match.first_server || "A";
                const COLORS = { A: C.teamA, B: C.orange };
                const pairShort = (t) => familyNamesOf(t) || (t==="A" ? teamALabel : teamBLabel) || (t==="A" ? "自チーム" : "相手");
                const isDoublesMatch = match.players.filter(p=>p.team==="A").length>1;
                const other = fs==="A" ? "B" : "A";
                const saveOrders = (key, v) => persist({ ...match, [key]: v });
                const pickRow = (team, role) => {
                  const names = sortedTeamNames(team);
                  const key = role==="serve" ? (team==="A"?"order_a":"order_b") : (team==="A"?"receive_order_a":"receive_order_b");
                  const cur = role==="serve" ? ((team==="A"?match.order_a:match.order_b)==="p2"?"p2":"p1") : effectiveReceiveOrder(match, team);
                  return (
                    <div style={{ marginTop:12 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:13.5, fontWeight:800, marginBottom:6 }}>
                        <span style={{ fontSize:11.5, fontWeight:800, color:C.white, background:COLORS[team], borderRadius:5, padding:"2px 6px" }}>{role==="serve"?"サーブ":"レシーブ"}</span>
                        <span style={{ color:COLORS[team] }}>{pairShort(team)} の1人目</span>
                      </div>
                      <div style={{ display:"flex", gap:8 }}>
                        <OrderSegBtn active={cur!=="p2"} color={COLORS[team]} onClick={()=>saveOrders(key,"p1")}>{names[0] || "選手1"}</OrderSegBtn>
                        <OrderSegBtn active={cur==="p2"} color={COLORS[team]} onClick={()=>saveOrders(key,"p2")}>{names[1] || "選手2"}</OrderSegBtn>
                      </div>
                    </div>
                  );
                };
                return (
                  <div style={{ background:C.white, border:`1px solid ${C.border}`, borderRadius:14, padding:14, marginBottom:12, textAlign:"left" }}>
                    <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:12 }}>🎾 第1ゲームの準備</div>
                    <div style={{ fontSize:15, fontWeight:800, color:C.text, marginBottom:8, textAlign:"center" }}>最初にサーブするペア</div>
                    <div style={{ display:"flex", background:C.gray, borderRadius:12, padding:4, gap:4 }}>
                      {["A","B"].map(t => (
                        <button key={t}
                          onClick={()=>{ if (fs !== t) persist({ ...match, first_server: t }); }}
                          style={{ flex:1, border:"none", borderRadius:9, padding:"13px 4px", fontSize:16, fontWeight:800, cursor:"pointer",
                            background: fs===t ? COLORS[t] : "transparent", color: fs===t ? C.white : C.textSec }}
                        >{pairShort(t)}</button>
                      ))}
                    </div>
                    {isDoublesMatch && (
                      <>
                        {pickRow(fs, "serve")}
                        {pickRow(other, "receive")}
                        <div style={{ fontSize:10.5, color:C.textSec, marginTop:12, lineHeight:1.6 }}>第2ゲーム以降の順番は、右上の✏️（試合情報）で確認・修正できます</div>
                      </>
                    )}
                  </div>
                );
              })()}
              <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                <button disabled={startingGame} style={{ width:"100%", padding:"15px 16px", background:startingGame?"#8a96ad":`linear-gradient(135deg,${C.navy},${C.navyMid})`, color:"white", border:"none", borderRadius:14, fontSize:16, fontWeight:700, cursor:startingGame?"default":"pointer" }} onClick={()=>startNewGame(match.first_server ? match : { ...match, first_server:"A" })}>{startingGame?"開始中...":"第1ゲーム開始"}</button>
                <button disabled={startingGame}
                  style={{ width:"100%", padding:"10px 12px", background:"#f2fbf7", border:`1.5px dashed ${C.accent}`, borderRadius:12, color:"#047a4c", fontSize:14, fontWeight:800, cursor:"pointer" }}
                  onClick={()=>{ const n=3; const fs=match.first_server||"A"; setMidStart({ startNum:n, winners:{}, server:gameServer(fs, n) }); }}
                >⏩ 試合の途中から記録する
                  <div style={{ fontSize:13, fontWeight:600, color:"#5a6478", marginTop:3 }}>前のゲームは「どっちが取ったか」だけ入れます</div>
                </button>
                <div style={{ display:"flex", gap:8 }}>
                  <button
                    style={{ flex:1, padding:"13px 16px", background:"#fff", border:"1px solid "+C.border, color:C.navy, borderRadius:12, fontSize:14, fontWeight:700, cursor:"pointer" }}
                    onClick={()=>{ setSimpleScoreA(""); setSimpleScoreB(""); setShowSimpleResult(true); }}
                  >📝 結果だけ記録</button>
                  <button
                    style={{ flex:"0 0 48px", width:48, borderRadius:12, border:"none", background:"#06C755", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}
                    onClick={()=>shareToLine("試合開始")}
                    aria-label="LINEで共有"
                  ><svg viewBox="0 0 24 24" width="22" height="22" fill="none"><path d="M12 3C6.48 3 2 6.69 2 11.25c0 2.99 1.91 5.61 4.79 7.08-.21.79-.76 2.83-.87 3.27-.14.55.2.54.42.4.17-.11 2.77-1.88 3.89-2.65.57.08 1.16.13 1.77.13 5.52 0 10-3.69 10-8.25S17.52 3 12 3z" fill="white"/></svg></button>
                </div>
                {match.status==="scheduled" && (
                  <div style={{ display:"flex", gap:8 }}>
                    <button
                      style={{ flex:1, padding:"13px 16px", background:`linear-gradient(135deg,#7b1fa2,${C.purple})`, color:"white", border:"none", borderRadius:10, fontSize:14, fontWeight:700, cursor:"pointer" }}
                      onClick={()=>persist({ ...match, status:"waiting" })}
                    >⏳ 待機中にする</button>
                    <button
                      style={{ flex:"0 0 48px", width:48, borderRadius:12, border:"none", background:"#06C755", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}
                      onClick={()=>shareToLine("待機中")}
                      aria-label="LINEで共有"
                    ><svg viewBox="0 0 24 24" width="22" height="22" fill="none"><path d="M12 3C6.48 3 2 6.69 2 11.25c0 2.99 1.91 5.61 4.79 7.08-.21.79-.76 2.83-.87 3.27-.14.55.2.54.42.4.17-.11 2.77-1.88 3.89-2.65.57.08 1.16.13 1.77.13 5.52 0 10-3.69 10-8.25S17.52 3 12 3z" fill="white"/></svg></button>
                  </div>
                )}
                {match.status==="waiting" && (
                  <div style={{ display:"flex", alignItems:"stretch", gap:8 }}>
                    <div style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", gap:10, height:48, borderRadius:12, background:"#eef0fe" }}>
                      <span style={{ fontSize:13, color:C.purple, fontWeight:800 }}>⏳ 待機中</span>
                      <button
                        style={{ fontSize:12, fontWeight:700, color:C.text, border:"1px solid #dcdffc", background:C.white, borderRadius:20, padding:"5px 14px", cursor:"pointer" }}
                        onClick={()=>persist({ ...match, status:"scheduled" })}
                      >解除</button>
                    </div>
                    <button
                      style={{ padding:0, flex:"0 0 48px", width:48, height:48, borderRadius:12, border:"none", background:"#06C755", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}
                      onClick={()=>shareToLine("待機中")}
                      aria-label="LINEで共有"
                    ><svg viewBox="0 0 24 24" width="22" height="22" fill="none"><path d="M12 3C6.48 3 2 6.69 2 11.25c0 2.99 1.91 5.61 4.79 7.08-.21.79-.76 2.83-.87 3.27-.14.55.2.54.42.4.17-.11 2.77-1.88 3.89-2.65.57.08 1.16.13 1.77.13 5.52 0 10-3.69 10-8.25S17.52 3 12 3z" fill="white"/></svg></button>
                  </div>
                )}
              </div>
            </div>
          )}
          {/* ★すでに勝利ゲーム数に達しているのに終了できていない試合（終了ポップアップを閉じてしまった等）を救済する。
                 以前はここで「次のゲーム開始」しか出ず、試合を終われなくなっていた。 */}
          {!correctMode&&!currentGame&&match.games.length>0&&match.status!=="finished"&&!viewOnly&&(match.match_score_a>=winGames||match.match_score_b>=winGames)&&(
            <div style={{ textAlign:"center",padding:"30px 0" }}>
              <p style={{ color:C.textSec,marginBottom:6 }}>{winGames}ゲーム先取に達しています</p>
              <p style={{ fontSize:20,fontWeight:900,color:C.navy,marginBottom:16 }}>{leftMatchScore} - {rightMatchScore}</p>
              <button
                style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`) }}
                onClick={()=>persist({ ...match, status:"finished" })}
              >🏆 この結果で試合を終了する</button>
              <button
                disabled={startingGame}
                style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8, cursor:startingGame?"default":"pointer" }}
                onClick={()=>startNewGame()}
              >{startingGame?"開始中...":`第${match.games.length+1}ゲーム開始（続ける）`}</button>
            </div>
          )}
          {!correctMode&&!currentGame&&match.games.length>0&&match.status!=="finished"&&!viewOnly&&!(match.match_score_a>=winGames||match.match_score_b>=winGames)&&(
            <div style={{ textAlign:"center",padding:"30px 0" }}>
              <p style={{ color:C.textSec,marginBottom:16 }}>ゲーム終了。次のゲームへ</p>
              <button disabled={startingGame} style={{ ...S.btn(startingGame?"#9bd9bb":`linear-gradient(135deg,${C.accent},#00a066)`), cursor:startingGame?"default":"pointer" }} onClick={()=>startNewGame()}>{startingGame?"開始中...":`第${match.games.length+1}ゲーム開始`}</button>
            </div>
          )}
          {match.status==="finished"&&!correctMode&&(
            <div>
              {/* 結果サマリー */}
              <div style={{ textAlign:"center",padding:"24px 0 16px" }}>
                <div style={{ fontSize:52 }}>🏆</div>
                <p style={{ fontSize:18,fontWeight:800,color:C.accent,marginTop:8 }}>試合終了</p>
                <p style={{ fontSize:14,fontWeight:700,color:C.white,marginTop:4,background:C.navy,display:"inline-block",padding:"4px 16px",borderRadius:20 }}>
                  {winnerSideOf(match)==="A"?teamALabel:teamBLabel} の勝利！
                </p>
              </div>
              {/* ゲーム別スコア一覧（両チームの選手名を表示） */}
              <div style={{ background:C.white,borderRadius:12,border:"1px solid "+C.border,overflow:"hidden",marginBottom:12 }}>
                <div style={{ background:C.navy,padding:"8px 14px",display:"flex",alignItems:"center" }}>
                  <span style={{ flex:1,fontSize:11,fontWeight:700,color:C.white }}>ゲーム別スコア</span>
                  <span style={{ width:74,fontSize:10,fontWeight:700,color:isYounger?"#2ecc71":"#f97316",textAlign:"center" }}>{leftLabel}</span>
                  <span style={{ width:74,fontSize:10,fontWeight:700,color:isYounger?"#f97316":"#2ecc71",textAlign:"center" }}>{rightLabel}</span>
                </div>
                {match.games.map(g=>(
                  <div key={g.id} style={{ display:"flex",alignItems:"center",padding:"10px 14px",borderBottom:"1px solid "+C.border }}>
                    <span style={{ fontSize:12,color:C.textSec,width:46 }}>{g.is_final?"🔥":""}G{g.game_number}</span>
                    {isWinOnlyGame(g) ? (
                      <span style={{ flex:1,fontSize:12,fontWeight:700,textAlign:"center",color:C.textSec }}>勝敗のみ</span>
                    ) : (
                    <span style={{ flex:1,fontSize:15,fontWeight:700,textAlign:"center" }}>
                      <span style={{ color:g.winner_team===leftTeam?(isYounger?"#2ecc71":"#f97316"):C.textSec }}>{leftScore(g)}</span>
                      <span style={{ color:C.textSec,margin:"0 8px" }}>-</span>
                      <span style={{ color:g.winner_team===rightTeam?(isYounger?"#f97316":"#2ecc71"):C.textSec }}>{rightScore(g)}</span>
                    </span>
                    )}
                    <span style={{ width:74,textAlign:"center" }}>{g.winner_team===leftTeam?<span style={{ display:"inline-block",width:13,height:13,borderRadius:"50%",background:"#d4e157",border:"1px solid #aeb92a" }}/>:""}</span>
                    <span style={{ width:74,textAlign:"center" }}>{g.winner_team===rightTeam?<span style={{ display:"inline-block",width:13,height:13,borderRadius:"50%",background:"#d4e157",border:"1px solid #aeb92a" }}/>:""}</span>
                  </div>
                ))}
                <div style={{ display:"flex",alignItems:"center",padding:"12px 14px",background:C.accentL }}>
                  <span style={{ fontSize:12,fontWeight:700,color:C.navy,width:46 }}>合計</span>
                  <span style={{ flex:1,fontSize:20,fontWeight:900,textAlign:"center" }}>
                    <span style={{ color:leftMatchScore>rightMatchScore?(isYounger?"#2ecc71":"#f97316"):C.textSec }}>{leftMatchScore}</span>
                    <span style={{ color:C.textSec,margin:"0 8px" }}>-</span>
                    <span style={{ color:rightMatchScore>leftMatchScore?(isYounger?"#f97316":"#2ecc71"):C.textSec }}>{rightMatchScore}</span>
                  </span>
                  <span style={{ width:74,textAlign:"center",fontSize:16 }}>{leftMatchScore>rightMatchScore?"🏆":""}</span>
                  <span style={{ width:74,textAlign:"center",fontSize:16 }}>{rightMatchScore>leftMatchScore?"🏆":""}</span>
                </div>
              </div>
              {/* 試合メモ（★記録者以外も書けるようにする。ただし閲覧専用アカウントは読むだけ） */}
              {isViewer ? (
                (match.memo || (match.video_links && match.video_links.length > 0)) && (
                  <div style={{ ...S.card, padding:14, marginBottom:8 }}>
                    {match.memo && (
                      <>
                        <div style={{ fontSize:12,fontWeight:700,color:C.navy,marginBottom:8 }}>📝 試合メモ</div>
                        <div style={{ fontSize:13,lineHeight:1.75,whiteSpace:"pre-wrap",background:C.accentL,borderRadius:10,padding:"12px 13px",color:C.text }}>{match.memo}</div>
                      </>
                    )}
                    {match.video_links && match.video_links.length > 0 && (
                      <>
                        <div style={{ fontSize:12,fontWeight:700,color:C.navy,margin:"14px 0 8px" }}>🎥 動画リンク</div>
                        {match.video_links.map(v=>(
                          <a key={v.id} href={v.url} target="_blank" rel="noopener noreferrer"
                            style={{ display:"flex",alignItems:"center",gap:10,border:`1px solid ${C.border}`,borderRadius:10,padding:8,marginBottom:9,textDecoration:"none",color:"inherit" }}>
                            <img src={youtubeThumbOf(v.id)} alt="" style={{ width:88,height:52,objectFit:"cover",borderRadius:7,background:"#000",flexShrink:0 }}/>
                            <div>
                              <div style={{ fontSize:12.5,fontWeight:700,color:C.navy }}>{v.title || "動画"}</div>
                              <div style={{ fontSize:10.5,color:"#c4302b",fontWeight:700,marginTop:3 }}>▶ YouTubeで開く</div>
                            </div>
                          </a>
                        ))}
                      </>
                    )}
                  </div>
                )
              ) : (
                <>
                  <div style={{ ...S.card, padding:14, marginBottom:8 }}>
                    <div style={{ fontSize:12,fontWeight:700,color:C.navy,marginBottom:8 }}>📝 試合メモ</div>
                    <textarea
                      style={{ width:"100%",minHeight:70,border:`1px solid ${C.border}`,borderRadius:8,padding:10,fontSize:13,fontFamily:"inherit",resize:"vertical" }}
                      placeholder="気づいたこと、課題、次への作戦などを自由にメモできます"
                      value={memoDraft}
                      onChange={e=>{ setMemoDraft(e.target.value); setMemoSaved(false); }}
                    />
                    {/* ★保存ボタンは、メモに未保存の変更があるときだけ出す。
                           何も書いていない・変更していない状態で「保存済み」ボタンを出し続けると、
                           何も入れていないのに保存済みと言われているように見えて紛らわしいため。 */}
                    {!memoSaved && (
                      <button
                        disabled={memoSaving}
                        style={{ ...S.btn(C.navy), color:C.white, fontSize:12, marginTop:10, padding:"9px", opacity: memoSaving?0.6:1 }}
                        onClick={async ()=>{
                          const updated = { ...match, memo: memoDraft };
                          setMemoSaving(true);
                          try {
                            // ★動画リンクと同じ理由：保存完了を待たずに済ませると、直後に
                            //   「試合一覧に戻る」を押したときだけ未保存警告が誤って出てしまう。
                            await saveMatch(updated);
                            setMatch({...updated});
                            setSyncStatus("synced");
                            setSyncErrorMsg("");
                            try { localStorage.removeItem(LOCAL_DRAFT_KEY); } catch(e) {}
                            latestUnsavedRef.current = null;
                            setMemoSaved(true);
                          } catch (e) {
                            persist(updated);
                            setMemoSaved(true);
                          } finally {
                            setMemoSaving(false);
                          }
                        }}
                      >{memoSaving ? "保存中…" : "💾 保存"}</button>
                    )}
                  </div>

                  {/* ★動画リンクは常時入力欄を出さず、AI動画分析と同じ「ボタンを押したら開く」形にする。
                        登録数に応じてボタンの文言を変え、押すと下のモーダルで追加・編集ができる。 */}
                  <button
                    style={{ ...S.btn("#f2f3f6"), color:"#3a4152", border:"1px solid "+C.border, marginBottom:8, display:"flex",alignItems:"center",justifyContent:"center",gap:6 }}
                    onClick={()=>{ setVideoLinksDraft(normalizeVideoLinks(match.video_links)); setVideoUrlInput(""); setVideoUrlError(""); setShowVideoModal(true); }}
                  >🎥 {match.video_links && match.video_links.length > 0 ? `動画リンクを貼る（${match.video_links.length}件）` : "動画リンクを貼る"}</button>
                </>
              )}
              {/* ボタン群 */}
              {/* ★スタッツ／スコアは上部のタブ（記録・スコア・スタッツ・検算）と機能が重複しているため削除。
                    「試合情報を編集」「スコアを修正」は、どちらも記録を直す系なので2列にまとめて省スペース化。 */}
              <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8 }}>
                {/* ★終了した試合の編集は、記録した本人でなくてもできるようにする。
                      記録係と、あとから内容を直す人（顧問など）が別なことが多いため。 */}
                {/* ★閲覧専用アカウントには、編集系はグレー表示で「あるけれど押せない」ことを示す */}
                <button style={{ ...S.btn("#fff"),color:C.navy,border:"1px solid "+C.border,marginBottom:0, ...(isViewer?viewerDisabledStyle:{}) }} onClick={()=>{ if(isViewer){viewerAlert();return;} onEdit&&onEdit(match.id); }}>✏️ 試合情報を編集</button>
                {/* ★「結果だけ記録」で終えた試合は、ポイント記録が無いのでスコア修正画面では直せない。
                       入力し直せるよう、同じ入力モーダルを今の値を入れた状態で開き直す。 */}
                {(match.games?.length ?? 0) === 0 && (
                  <button
                    style={{ ...S.btn("#fff"),color:C.orange,border:"1px solid "+C.orange,marginBottom:0, ...(isViewer?viewerDisabledStyle:{}) }}
                    onClick={()=>{
                      if(isViewer){viewerAlert();return;}
                      setSimpleScoreA(String(match.match_score_a ?? ""));
                      setSimpleScoreB(String(match.match_score_b ?? ""));
                      setIsWithdrawalResult(!!match.walkover_winner);
                      setWithdrawalWinner(match.walkover_winner || null);
                      setShowSimpleResult(true);
                    }}
                  >✏️ 結果を修正する</button>
                )}
                {(match.games?.length ?? 0) > 0 && (
                  <button style={{ ...S.btn("#fff"),color:C.orange,border:"1px solid "+C.orange,marginBottom:0, ...(isViewer?viewerDisabledStyle:{}) }} onClick={()=>{ if(isViewer){viewerAlert();return;} setCorrectGameId(null); setCorrectMode(true); }}>✏️ スコアを修正</button>
                )}
              </div>
              {/* ★「途中終了」は記録中の画面から押すもの。終了済みの画面に置くと
                    「試合終了」と表示しながら「途中終了」ボタンが並ぶことになり紛らわしいので置かない。 */}
              {/* ★AI動画分析・LINE共有は、使用頻度が低いので小さく1行にまとめ、目立たせすぎない。
                    文字色も青系（紫）は避け、グレー系に統一する。 */}
              <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8 }}>
                {/* ★AI動画分析は、管理者か、この試合に出場している本人（保護者アカウント含む）だけに表示する。
                    以前は誰にでも表示していたため、AI分析メニュー側で閲覧制限をかけても
                    この試合詳細のボタンから中身を見られてしまう抜け道になっていた。 */}
                {!teamMatchId && aiAnalysis !== undefined && (aiAnalysis ? canViewAi : true) && (
                  <button style={{ ...S.btn("#f2f3f6"),color:"#3a4152",border:"1px solid "+C.border,fontSize:11,padding:8,marginBottom:0, ...((isViewer && !aiAnalysis)?viewerDisabledStyle:{}) }}
                    onClick={()=>{ if(isViewer && !aiAnalysis){viewerAlert();return;} onOpenAiAnalysis && onOpenAiAnalysis(match, aiAnalysis); }}
                  >🤖 {aiAnalysis ? "AI分析を見る" : "AI分析"}</button>
                )}
                <button style={{ ...S.btn("#f2f3f6"),color:"#3a4152",border:"1px solid "+C.border,fontSize:11,padding:8,marginBottom:0 }} onClick={()=>window.open("https://line.me/R/msg/text/?"+encodeURIComponent(buildLineText(match)),"_blank")}>💬 LINE共有</button>
              </div>
              <button style={{ ...S.btn("linear-gradient(135deg,"+C.accent+",#00a066)") }} onClick={handleBack}>← 試合一覧に戻る</button>
              {/* ★動画リンクの追加・編集モーダル。「動画リンクを追加する」ボタンを押したときだけ開く。 */}
              {showVideoModal && (
                <div style={{ position:"fixed",inset:0,background:"rgba(0,0,0,0.45)",zIndex:200,display:"flex",alignItems:"flex-end",justifyContent:"center" }} onClick={()=>setShowVideoModal(false)}>
                  <div style={{ background:C.white,borderRadius:"16px 16px 0 0",padding:16,width:"100%",maxWidth:480,maxHeight:"85vh",overflowY:"auto" }} onClick={e=>e.stopPropagation()}>
                    <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10 }}>
                      <div style={{ fontSize:14,fontWeight:800,color:C.navy }}>🎥 動画リンク</div>
                      <div style={{ color:C.textSec,fontSize:18,cursor:"pointer",padding:4 }} onClick={()=>setShowVideoModal(false)}>✕</div>
                    </div>
                    <div style={{ fontSize:11,color:C.textSec,marginBottom:8 }}>YouTubeのリンクを複数登録できます</div>
                    <div style={{ display:"flex",gap:6 }}>
                      <input
                        type="text"
                        style={{ flex:1,minWidth:0,border:`1px solid ${C.border}`,borderRadius:8,padding:"9px 10px",fontSize:13,fontFamily:"inherit" }}
                        placeholder="https://youtu.be/... を貼り付け"
                        value={videoUrlInput}
                        onChange={e=>{ setVideoUrlInput(e.target.value); setVideoUrlError(""); }}
                      />
                      <button
                        style={{ background:C.accent,color:C.white,border:"none",borderRadius:8,padding:"0 14px",fontSize:13,fontWeight:800,cursor:"pointer",whiteSpace:"nowrap" }}
                        onClick={()=>{
                          const vid = youtubeIdOf(videoUrlInput.trim());
                          if (!vid) { setVideoUrlError("YouTubeのURLとして認識できませんでした"); return; }
                          if (videoLinksDraft.some(v=>v.id===vid)) { setVideoUrlError("この動画はすでに登録されています"); return; }
                          setVideoLinksDraft([...videoLinksDraft, { id:vid, title:`動画${videoLinksDraft.length+1}`, url:`https://youtu.be/${vid}` }]);
                          setVideoUrlInput(""); setVideoUrlError("");
                        }}
                      >追加</button>
                    </div>
                    <div style={{ fontSize:10.5,color:C.textSec,marginTop:5,lineHeight:1.5 }}>追加後、タイトル欄をタップすると「1ゲーム目」など自由に名前を付けられます。</div>
                    {videoUrlError && <div style={{ fontSize:10.5,color:C.red,marginTop:5 }}>{videoUrlError}</div>}

                    {videoLinksDraft.length > 0 ? (
                      <div style={{ marginTop:10,display:"flex",flexDirection:"column",gap:8 }}>
                        {videoLinksDraft.map((v,i)=>(
                          <div key={v.id} style={{ display:"flex",alignItems:"center",gap:9,border:`1px solid ${C.border}`,borderRadius:10,padding:"7px 9px",background:"#fafbfd" }}>
                            <img src={youtubeThumbOf(v.id)} alt="" style={{ width:64,height:38,objectFit:"cover",borderRadius:6,background:"#000",flexShrink:0 }}/>
                            <div style={{ flex:1,minWidth:0 }}>
                              <input
                                type="text"
                                value={v.title}
                                placeholder="タイトル"
                                onChange={e=>{
                                  const next = videoLinksDraft.slice();
                                  next[i] = { ...next[i], title: e.target.value };
                                  setVideoLinksDraft(next);
                                }}
                                style={{ width:"100%",border:"none",background:"transparent",fontSize:12,fontWeight:700,color:C.navy,padding:"2px 0",fontFamily:"inherit" }}
                              />
                              {/* ★動画のURLは画面に表示しない（他校・外部SNSへの無断転載をできるだけ防ぐため） */}
                              <div style={{ fontSize:10,color:C.textSec }}>YouTube動画</div>
                            </div>
                            <button
                              style={{ background:"none",border:"none",color:C.red,fontSize:15,cursor:"pointer",padding:4 }}
                              onClick={()=>{ setVideoLinksDraft(videoLinksDraft.filter((_,j)=>j!==i)); }}
                            >🗑</button>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div style={{ fontSize:11.5,color:C.textSec,textAlign:"center",padding:14,border:`1px dashed ${C.border}`,borderRadius:10,marginTop:10 }}>まだ動画が登録されていません</div>
                    )}

                    <button
                      disabled={videoSaving}
                      style={{ ...S.btn("linear-gradient(135deg,"+C.accent+",#00a066)"), marginTop:14, opacity: videoSaving?0.6:1 }}
                      onClick={async ()=>{
                        const cleaned = videoLinksDraft.map((v,i)=>({ ...v, title: v.title.trim() || `動画${i+1}` }));
                        setVideoLinksDraft(cleaned);
                        const updated = { ...match, video_links: cleaned };
                        setVideoSaving(true);
                        try {
                          // ★通常の試合記録（persist）は保存完了を待たず即座に画面を返す作りだが、
                          //   それだと「保存して閉じる」を押した直後に「試合一覧に戻る」を押すと、
                          //   まだ保存が終わっていないだけなのに「未保存の記録があります」という
                          //   警告が出てしまう。動画リンクの保存はすぐ終わるはずなので、ここでは
                          //   実際に保存が完了するのを待ってからモーダルを閉じる。
                          await saveMatch(updated);
                          setMatch({...updated});
                          setSyncStatus("synced");
                          setSyncErrorMsg("");
                          try { localStorage.removeItem(LOCAL_DRAFT_KEY); } catch(e) {}
                          latestUnsavedRef.current = null;
                          setShowVideoModal(false);
                        } catch (e) {
                          // ★オフライン等ですぐに保存できなかった場合だけ、既存の再送の仕組みに乗せて
                          //   閉じる（この場合は本当に未保存なので、戻ろうとしたときの警告は正しい）
                          persist(updated);
                          setShowVideoModal(false);
                        } finally {
                          setVideoSaving(false);
                        }
                      }}
                    >{videoSaving ? "保存中…" : "保存して閉じる"}</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* ★記録中でも、前のゲームの間違いに気づいたときに直せるようにする。
                 どのゲームを直すか選ぶと、試合終了後と同じポイント修正画面がそのゲームだけ開く。 */}
          {!correctMode&&match.games.length>0&&match.status!=="finished"&&!viewOnly&&!osRecording&&(
            <div style={{ textAlign:"center", margin:"4px 0 14px" }}>
              <button
                style={{ background:"none",border:`1px dashed ${C.border}`,borderRadius:8,color:C.textSec,fontSize:11.5,fontWeight:700,cursor:"pointer",padding:"8px 14px",width:"100%" }}
                onClick={()=>setShowGamePicker(true)}
              >🔧 記録済みのゲームを修正する</button>
            </div>
          )}
          {correctMode&&(
            <div>
              <div style={{ background:"#fff3e0",border:"1px solid #ffd699",borderRadius:10,padding:"10px 12px",marginBottom:12,fontSize:14,lineHeight:1.6,color:"#7a5800" }}>
                ✏️ 修正したいポイントをタップすると内容の変更・削除ができます。「＋」では好きな位置にポイントを追加できます。
              </div>
              {!correctGameId && (
                <button
                  style={{ width:"100%",background:"none",border:`1px dashed ${C.accent}`,borderRadius:8,color:C.accent,fontSize:12.5,fontWeight:800,cursor:"pointer",padding:"9px 10px",marginBottom:10 }}
                  onClick={()=>setInsertFirst({ left:"", right:"" })}
                >＋ 第1ゲームの前に、記録していないゲームを追加</button>
              )}
              {match.games.filter(g=>!correctGameId||g.id===correctGameId).map(g=>(
                <div key={g.id} style={S.card}>
                  <div style={{ padding:"10px 14px",background:C.navyMid,color:C.white,display:"flex",justifyContent:"space-between",alignItems:"center" }}>
                    <span style={{ fontWeight:800,fontSize:16 }}>{g.is_final?"🔥":""}第{g.game_number}ゲーム</span>
                    <span style={{ display:"flex",alignItems:"center",gap:10 }}>
                      {/* ★点が1つも入っていない空のゲームは、間違って作られたものなので削除できるようにする。
                            削除すると後ろのゲーム番号が繰り上がる（第2→第1のように詰められる）。 */}
                      {g.points.length===0 && match.games.length>1 && (
                        <button
                          style={{ background:"none",border:"none",color:"#ffb3ab",fontSize:11,fontWeight:700,cursor:"pointer",textDecoration:"underline",padding:0 }}
                          onClick={()=>{
                            if (!window.confirm(`第${g.game_number}ゲームは点が記録されていません。\nこのゲームを削除しますか？\n\n※以降のゲーム番号は繰り上がります。`)) return;
                            const remain = match.games.filter(x=>x.id!==g.id).map((x,i)=>({ ...x, game_number:i+1 }));
                            const newScoreA = remain.filter(x=>x.winner_team==="A").length;
                            const newScoreB = remain.filter(x=>x.winner_team==="B").length;
                            persist({ ...match, games:remain, match_score_a:newScoreA, match_score_b:newScoreB });
                          }}
                        >🗑 削除</button>
                      )}
                      <span style={{ fontWeight:900, fontSize: isWinOnlyGame(g) ? 13 : 20 }}>{isWinOnlyGame(g) ? `勝敗のみ（${osTeamName(g.winner_team)}）` : `${leftScore(g)} - ${rightScore(g)}`}</span>
                    </span>
                  </div>
                  <div style={{ padding:"8px 10px" }}>
                    <div style={{ textAlign:"center" }}>
                      <button style={{ background:"none",border:`1px dashed ${C.border}`,borderRadius:8,color:C.accent,fontSize:14,fontWeight:800,cursor:"pointer",padding:"8px 10px",width:"100%" }} onClick={()=>setAddingPoint({gameId:g.id,atIndex:0})}>＋ 先頭に追加</button>
                    </div>
                    {g.points.length===0&&<div style={{ fontSize:12,color:C.textSec,padding:"10px 4px",textAlign:"center" }}>記録なし</div>}
                    {g.points.map((pt,idx)=>(
                      <div key={pt.id}>
                        {/* ★文字が小さく見えにくいという声への対応：記録画面の「このゲームの記録」と同じ見せ方で大きく表示 */}
                        {(()=>{
                          const l = leftScore({score_a:pt.score_a_after, score_b:pt.score_b_after}), r = rightScore({score_a:pt.score_a_after, score_b:pt.score_b_after});
                          const sv = pt.fault_count===2 ? "DF" : pt.fault_count===1 ? "2nd" : "1st";
                          const tag = { fontSize:12, fontWeight:800, borderRadius:9, padding:"1px 7px", marginLeft:5, whiteSpace:"nowrap", display:"inline-block" };
                          const det = [pt.side_type&&getSideLabel(pt.side_type), pt.miss_type&&getMissLabel(pt.miss_type), pt.course_type&&getCourseLabel(pt.course_type)].filter(Boolean).join("・");
                          const col = pt.scoring_team==="A" ? C.teamA : C.teamB;
                          return (
                            <div style={{ display:"flex",alignItems:"center",gap:10,padding:"10px 10px",background:C.gray,borderRadius:10,marginTop:6,borderLeft:`5px solid ${col}`,cursor:"pointer" }} onClick={()=>setEditingPoint({gameId:g.id,point:pt})}>
                              <span style={{ fontSize:13,fontWeight:800,padding:"3px 8px",borderRadius:20,background:col,color:C.white,whiteSpace:"nowrap",maxWidth:96,overflow:"hidden",textOverflow:"ellipsis",flexShrink:0 }}>{osTeamName(pt.scoring_team)}</span>
                              <span style={{ flex:1,minWidth:0,fontSize:15,fontWeight:700,color:C.text,lineHeight:1.5 }}>
                                {osDisp(pt.player_name) || (pt.fault_count===2 ? "ダブルフォルト" : "—")}{pt.play_type ? `（${getPlayLabel(pt.play_type)}）` : ""}
                                <span style={{ ...tag, color: sv==="DF" ? C.white : "#3d4457", background: sv==="DF" ? "#e74c3c" : "#e6e9ef" }}>{sv}</span>
                                {pt.result_type && <span style={{ ...tag, color: isWinnerResult(pt.result_type) ? "#1565c0" : C.red, background: isWinnerResult(pt.result_type) ? "#e3eefb" : "#fbe6ea" }}>{isWinnerResult(pt.result_type) ? "決め" : "ミス"}</span>}
                                {det && <div style={{ fontSize:13,fontWeight:600,color:C.textSec,marginTop:1 }}>{det}</div>}
                              </span>
                              <span style={{ fontSize:17,fontWeight:900,color:C.text,whiteSpace:"nowrap",fontVariantNumeric:"tabular-nums" }}>{l}-{r}</span>
                              <span style={{ fontSize:18,color:C.textSec,flexShrink:0 }}>›</span>
                            </div>
                          );
                        })()}
                        <div style={{ textAlign:"center",marginTop:4 }}>
                          <button style={{ background:"none",border:"none",color:C.accent,fontSize:13.5,fontWeight:800,cursor:"pointer",padding:"6px 12px" }} onClick={()=>setAddingPoint({gameId:g.id,atIndex:idx+1})}>＋ ここに追加</button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              {/* ★特定のゲームだけを直しているときは「ゲームを追加」は出さない（意図しない進行を防ぐ） */}
              {!correctGameId && match.status==="finished" && (
              <div style={{ textAlign:"center", marginBottom:10 }}>
                <button
                  style={{ background:"none",border:`1px dashed ${C.accent}`,borderRadius:8,color:C.accent,fontSize:12,fontWeight:700,cursor:"pointer",padding:"8px 14px",width:"100%" }}
                  onClick={()=>{
                    // ★「これで試合終了」と判定されていたが、実はまだ続きがあった場合に
                    //   新しいゲームを追加できるようにする。試合は自動的に進行中(active)に戻る。
                    const num = match.games.length + 1;
                    const isFin = isFinalGame(match.game_format, match.match_score_a, match.match_score_b);
                    const srv = gameServer(match.first_server || "A", num);
                    const g = { id:uid(), match_id:match.id, game_number:num, server_team:srv, is_final:isFin, score_a:0, score_b:0, winner_team:null, points:[], faults:[] };
                    persist({ ...match, status:"active", games:[...match.games, g] });
                    setCorrectMode(false); setCorrectGameId(null);
                  }}
                >＋ 第{match.games.length+1}ゲームを追加（試合を再開する）</button>
              </div>
              )}
              <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`),marginTop:4 }} onClick={()=>{ setCorrectMode(false); setCorrectGameId(null); }}>修正を完了</button>
              {/* ★別のゲームを直したいときのために、ゲーム選択に戻れるボタンも置く。
                     修正内容はタップした時点で保存済みなので、どちらで抜けても内容は残る。 */}
              {correctGameId ? (
                <button
                  style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }}
                  onClick={()=>{ setCorrectMode(false); setCorrectGameId(null); setShowGamePicker(true); }}
                >← ゲーム選択に戻る</button>
              ) : (
                <button
                  style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }}
                  onClick={()=>{ setCorrectMode(false); setCorrectGameId(null); }}
                >← 戻る</button>
              )}
            </div>
          )}

          {skipGame && currentGame && (() => {
            const cg = currentGame;
            const pa = cg.points.filter(p=>p.scoring_team===leftTeam).length, pb = cg.points.filter(p=>p.scoring_team===rightTeam).length;
            const lNum = parseInt(skipGame.left, 10), rNum = parseInt(skipGame.right, 10);
            const hasScore = Number.isFinite(lNum) && Number.isFinite(rNum);
            const w = skipGame.winner;
            const scoreBad = hasScore && w && ((w===leftTeam && lNum<=rNum) || (w===rightTeam && rNum<=lNum));
            const tA = w ? match.games.filter(g=>g.id!==cg.id && g.winner_team==="A").length + (w==="A"?1:0) : 0;
            const tB = w ? match.games.filter(g=>g.id!==cg.id && g.winner_team==="B").length + (w==="B"?1:0) : 0;
            const ends = w && (tA >= winGames || tB >= winGames);
            const inp = { width:70, boxSizing:"border-box", padding:"8px 4px", fontSize:22, fontWeight:900, textAlign:"center", border:`2px solid ${C.border}`, borderRadius:10 };
            const teamBtn = (t) => {
              const on = w===t, col = osTeamColor(t);
              return (
                <button key={t} onClick={()=>setSkipGame(v=>({ ...v, winner:t }))}
                  style={{ flex:1, padding:"12px 4px", borderRadius:12, border:`2px solid ${on?col:C.border}`, background:on?col:C.white, color:on?C.white:C.navy, fontSize:17, fontWeight:800, cursor:"pointer" }}>
                  {osTeamName(t)}<div style={{ fontSize:13, fontWeight:600, marginTop:2 }}>{osPlayersOf(t).map(x=>osSurname(x.label)).join("・")}</div>
                </button>
              );
            };
            return (
              <Modal onClose={()=>setSkipGame(null)}>
                <h3 style={{ fontSize:19,fontWeight:800,color:C.navy,marginBottom:10,textAlign:"center" }}>第{cg.game_number}ゲームを飛ばす</h3>
                <p style={{ fontSize:15,color:"#33415c",marginBottom:4,lineHeight:1.65,background:"#f2f6fb",borderRadius:10,padding:"10px 12px" }}>
                  {cg.points.length>0 ? <>ここまで記録した <b>{cg.points.length}ポイント（{pa}-{pb}）</b> は消さずに、スタッツにそのまま残ります。</> : "このゲームは点を記録せず、取ったチームだけ記録します。"}
                </p>
                <div style={{ fontSize:15,fontWeight:800,color:C.navy,margin:"14px 0 8px",display:"flex",alignItems:"center" }}><RequiredDot />このゲームを取ったのは？</div>
                <div style={{ display:"flex", gap:8 }}>{teamBtn(leftTeam)}{teamBtn(rightTeam)}</div>
                <div style={{ fontSize:15,fontWeight:800,color:C.navy,margin:"14px 0 8px" }}>このゲームの最終スコア（分かれば）</div>
                <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:8 }}>
                  <input type="number" inputMode="numeric" min="0" style={inp} value={skipGame.left} onChange={e=>setSkipGame(v=>({ ...v, left:e.target.value }))}/>
                  <b style={{ color:C.textSec }}>-</b>
                  <input type="number" inputMode="numeric" min="0" style={inp} value={skipGame.right} onChange={e=>setSkipGame(v=>({ ...v, right:e.target.value }))}/>
                </div>
                <div style={{ fontSize:13.5,color:scoreBad?C.red:"#5a6478",textAlign:"center",marginTop:7 }}>{scoreBad ? "取ったチームの点数の方が大きくなるように入れてください" : "空欄のままなら「勝敗のみ」で記録します"}</div>
                <button
                  disabled={!w || scoreBad}
                  style={{ ...S.btn((w && !scoreBad) ? `linear-gradient(135deg,${C.accent},#00a066)` : C.border, (w && !scoreBad) ? C.white : C.textSec), marginTop:14 }}
                  onClick={()=>{
                    if (!w || scoreBad) return;
                    const sA = hasScore ? (leftTeam==="A" ? lNum : rNum) : 0;
                    const sB = hasScore ? (leftTeam==="A" ? rNum : lNum) : 0;
                    setSkipGame(null);
                    skipCurrentGame(w, sA, sB);
                  }}
                >{!w ? "取ったチームを選んでください" : ends ? `第${cg.game_number}ゲームを終えて、試合終了` : `第${cg.game_number}ゲームを終えて、第${cg.game_number+1}ゲームへ`}</button>
                <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }} onClick={()=>setSkipGame(null)}>キャンセル</button>
              </Modal>
            );
          })()}

          {midStart && (() => {
            const maxStart = winGames*2 - 1;
            const n = midStart.startNum;
            const prior = Array.from({ length:n-1 }, (_,i)=>i+1);
            const allSet = prior.every(k=>midStart.winners[k]);
            const wa = prior.filter(k=>midStart.winners[k]==="A").length, wb = prior.filter(k=>midStart.winners[k]==="B").length;
            const over = wa >= winGames || wb >= winGames;
            const lw = leftTeam==="A" ? wa : wb, rw = leftTeam==="A" ? wb : wa;
            const pick = (k, t) => setMidStart(v=>({ ...v, winners:{ ...v.winners, [k]:t } }));
            const qLab = { fontSize:15, fontWeight:800, color:C.navy, marginBottom:8, display:"flex", alignItems:"center" };
            const tb = (on, t, onClick, extra={}) => (
              <button onClick={onClick} style={{ flex:1, padding:"10px 2px", borderRadius:10, border:`2px solid ${on?osTeamColor(t):C.border}`, background:on?osTeamColor(t):C.white, color:on?C.white:C.navy, fontSize:15, fontWeight:800, cursor:"pointer", minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", ...extra }}>{osTeamName(t)}</button>
            );
            return (
              <Modal onClose={()=>setMidStart(null)}>
                <h3 style={{ fontSize:19,fontWeight:800,color:C.navy,marginBottom:12,textAlign:"center" }}>試合の途中から記録する</h3>
                <div style={qLab}><RequiredDot />何ゲーム目から記録しますか？</div>
                <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:6, paddingLeft:12 }}>
                  {Array.from({ length:maxStart-1 }, (_,i)=>i+2).map(k=>(
                    <button key={k} onClick={()=>setMidStart(v=>({ ...v, startNum:k, server:gameServer(match.first_server||"A", k) }))}
                      style={{ padding:"9px 0", borderRadius:10, border:`2px solid ${k===n?C.navy:C.border}`, background:k===n?C.navy:C.white, color:k===n?C.white:C.navy, fontSize:15, fontWeight:800, cursor:"pointer" }}>第{k}</button>
                  ))}
                </div>
                <div style={{ ...qLab, marginTop:16 }}><RequiredDot />それまでのゲームを取ったチーム</div>
                {prior.map(k=>(
                  <div key={k} style={{ display:"flex", alignItems:"center", gap:6, marginTop:6, paddingLeft:12 }}>
                    <span style={{ width:46, fontSize:15, fontWeight:800, color:C.navy, flexShrink:0 }}>第{k}G</span>
                    {tb(midStart.winners[k]===leftTeam, leftTeam, ()=>pick(k, leftTeam))}
                    {tb(midStart.winners[k]===rightTeam, rightTeam, ()=>pick(k, rightTeam))}
                  </div>
                ))}
                {over && <div style={{ fontSize:13.5,color:C.red,marginTop:8,lineHeight:1.6 }}>この勝ち数だと、第{n}ゲームの前に試合が終わっています。ゲームの選び方を確認してください。</div>}
                <div style={{ ...qLab, marginTop:16 }}><RequiredDot />第{n}ゲーム目でサーブをするのは？</div>
                <div style={{ display:"flex", gap:8, paddingLeft:12 }}>
                  {tb(midStart.server===leftTeam, leftTeam, ()=>setMidStart(v=>({ ...v, server:leftTeam })), { padding:"11px 2px", fontSize:17 })}
                  {tb(midStart.server===rightTeam, rightTeam, ()=>setMidStart(v=>({ ...v, server:rightTeam })), { padding:"11px 2px", fontSize:17 })}
                </div>
                <button
                  disabled={!allSet || over}
                  style={{ ...S.btn((allSet && !over) ? `linear-gradient(135deg,${C.navy},${C.navyMid})` : C.border, (allSet && !over) ? C.white : C.textSec), marginTop:18 }}
                  onClick={()=>{
                    if (!allSet || over) return;
                    const { startNum, winners, server } = midStart;
                    setMidStart(null);
                    startFromMiddle(startNum, winners, server);
                  }}
                >{allSet ? `${lw}-${rw} から第${n}ゲームを記録開始` : "それまでのゲームを全部選んでください"}</button>
                <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }} onClick={()=>setMidStart(null)}>キャンセル</button>
              </Modal>
            );
          })()}

          {insertFirst && (() => {
            const l = parseInt(insertFirst.left, 10), r = parseInt(insertFirst.right, 10);
            const valid = Number.isFinite(l) && Number.isFinite(r) && l >= 0 && r >= 0 && l !== r;
            const winnerSide = valid ? (l > r ? leftTeam : rightTeam) : null;
            const scoreA = leftTeam === "A" ? l : r, scoreB = leftTeam === "A" ? r : l;
            const inp = { width:"100%", boxSizing:"border-box", padding:"12px 8px", fontSize:22, fontWeight:900, textAlign:"center", border:`2px solid ${C.border}`, borderRadius:10 };
            return (
              <Modal onClose={()=>setInsertFirst(null)}>
                <h3 style={{ fontSize:16,fontWeight:800,color:C.navy,marginBottom:6,textAlign:"center" }}>第1ゲームの前にゲームを追加</h3>
                <p style={{ fontSize:12,color:C.textSec,marginBottom:14,lineHeight:1.6 }}>
                  途中のゲームから記録を始めたときに、記録していない最初のゲームを「スコアだけ」で追加します。今の第1ゲームは第2ゲームになり、以降も1つずつ繰り下がります。
                </p>
                <div style={{ display:"grid", gridTemplateColumns:"1fr auto 1fr", gap:8, alignItems:"end" }}>
                  <div>
                    <div style={{ fontSize:12,fontWeight:800,color:osTeamColor(leftTeam),textAlign:"center",marginBottom:4,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap" }}>{osTeamName(leftTeam)}</div>
                    <input type="number" inputMode="numeric" min="0" style={inp} value={insertFirst.left} onChange={e=>setInsertFirst(v=>({ ...v, left:e.target.value }))} placeholder="0"/>
                  </div>
                  <div style={{ fontSize:22,fontWeight:900,color:C.textSec,paddingBottom:12 }}>-</div>
                  <div>
                    <div style={{ fontSize:12,fontWeight:800,color:osTeamColor(rightTeam),textAlign:"center",marginBottom:4,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap" }}>{osTeamName(rightTeam)}</div>
                    <input type="number" inputMode="numeric" min="0" style={inp} value={insertFirst.right} onChange={e=>setInsertFirst(v=>({ ...v, right:e.target.value }))} placeholder="0"/>
                  </div>
                </div>
                <div style={{ fontSize:12.5,fontWeight:700,color:C.text,textAlign:"center",margin:"10px 0 4px",minHeight:18 }}>
                  {valid ? `${osTeamName(winnerSide)}がこのゲームを取った` : "ゲームのポイント数を入れてください（例：4-2）"}
                </div>
                <button
                  disabled={!valid}
                  style={{ ...S.btn(valid ? `linear-gradient(135deg,${C.accent},#00a066)` : C.border, valid ? C.white : C.textSec), marginTop:10 }}
                  onClick={()=>{
                    if (!valid) return;
                    const first = match.games[0];
                    // 追加するゲームのサーブは、今の第1ゲームの逆（ゲームごとにサーブ側が交代するため）
                    const srv = first?.server_team ? (first.server_team === "A" ? "B" : "A") : (match.first_server || "A");
                    const newG = { id:uid(), match_id:match.id, game_number:1, server_team:srv, is_final:false, score_a:scoreA, score_b:scoreB, winner_team:winnerSide, points:[], faults:[] };
                    let games = [newG, ...match.games];
                    let sA = games.filter(x=>x.winner_team==="A").length, sB = games.filter(x=>x.winner_team==="B").length;
                    const decided = sA >= winGames || sB >= winGames;
                    // 追加で勝敗が決まった場合、最後に作られていた「点が1つも入っていない記録中のゲーム」は不要なので消す
                    const last = games[games.length-1];
                    if (decided && last && !last.winner_team && (last.points?.length ?? 0) === 0) games = games.slice(0, -1);
                    games = games.map((x,i)=>({ ...x, game_number:i+1 }));
                    sA = games.filter(x=>x.winner_team==="A").length; sB = games.filter(x=>x.winner_team==="B").length;
                    persist({ ...match, games, first_server: srv, match_score_a:sA, match_score_b:sB, ...(decided ? { status:"finished" } : {}) });
                    setInsertFirst(null);
                    if (decided) { setCorrectMode(false); setCorrectGameId(null); }
                  }}
                >追加する</button>
                <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }} onClick={()=>setInsertFirst(null)}>キャンセル</button>
              </Modal>
            );
          })()}

          {showGamePicker && (
            <Modal onClose={()=>setShowGamePicker(false)}>
              <h3 style={{ fontSize:17,fontWeight:800,color:C.navy,marginBottom:4,textAlign:"center" }}>🔧 修正するゲームを選んでください</h3>
              <p style={{ fontSize:13,color:C.textSec,marginBottom:14,textAlign:"center" }}>選んだゲームのポイントを1つずつ修正・削除・追加できます</p>
              <button
                style={{ width:"100%",background:"none",border:`1px dashed ${C.accent}`,borderRadius:10,color:C.accent,fontSize:13.5,fontWeight:800,cursor:"pointer",padding:"11px 10px",marginBottom:10 }}
                onClick={()=>{ setShowGamePicker(false); setInsertFirst({ left:"", right:"" }); }}
              >＋ 第1ゲームの前に、記録していないゲームを追加</button>
              {match.games.map(g=>(
                <div
                  key={g.id}
                  style={{ display:"flex",alignItems:"center",gap:10,border:`1px solid ${C.border}`,borderRadius:10,padding:"13px 14px",marginBottom:8,cursor:"pointer" }}
                  onClick={()=>{ setCorrectGameId(g.id); setCorrectMode(true); setShowGamePicker(false); }}
                >
                  <span style={{ fontSize:16,fontWeight:800,color:C.navy,width:70 }}>{g.is_final?"🔥":""}第{g.game_number}G</span>
                  <span style={{ fontSize:isWinOnlyGame(g)?13:19,fontWeight:900,color:C.text }}>{isWinOnlyGame(g) ? "勝敗のみ" : `${leftScore(g)} - ${rightScore(g)}`}</span>
                  <span style={{ marginLeft:"auto",fontSize:13.5,fontWeight:700,color:C.textSec }}>
                    {g.winner_team ? `${osTeamName(g.winner_team)}の勝ち` : "記録中"}
                  </span>
                  <span style={{ fontSize:18,color:C.textSec }}>›</span>
                </div>
              ))}
              <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }} onClick={()=>setShowGamePicker(false)}>キャンセル</button>
            </Modal>
          )}

          {editingPoint && (
            <PointEditModal
              mode="edit"
              point={editingPoint.point}
              players={allPlayers}
              teamALabel={teamALabel}
              teamBLabel={teamBLabel}
              ui={{ leftTeam, rightTeam, teamName:osTeamName, teamColor:osTeamColor, playersOf:osPlayersOf, positionOf:osPositionOf, surname:osSurname, allNames: match.players.map(x=>x.player_name), famOf:(t)=>familyNamesOf(t).split("/").join("・") }}
              onClose={()=>setEditingPoint(null)}
              onSave={(updates)=>{ updatePointInGame(editingPoint.gameId, editingPoint.point.id, updates); setEditingPoint(null); }}
              onDelete={()=>{ if(window.confirm("このポイントを削除しますか？削除後はスコアが自動的に再計算されます。")){ deletePointFromGame(editingPoint.gameId, editingPoint.point.id); setEditingPoint(null); } }}
            />
          )}

          {addingPoint && (
            <PointEditModal
              mode="add"
              point={{ scoring_team:"A", play_type:null, side_type:null, course_type:null, miss_type:null, result_type:null, player_name:null }}
              players={allPlayers}
              teamALabel={teamALabel}
              teamBLabel={teamBLabel}
              ui={{ leftTeam, rightTeam, teamName:osTeamName, teamColor:osTeamColor, playersOf:osPlayersOf, positionOf:osPositionOf, surname:osSurname, allNames: match.players.map(x=>x.player_name), famOf:(t)=>familyNamesOf(t).split("/").join("・") }}
              onClose={()=>setAddingPoint(null)}
              onSave={(values)=>{ insertPointInGame(addingPoint.gameId, addingPoint.atIndex, values); setAddingPoint(null); }}
            />
          )}

          {osRecording&&(()=>{
            // ★一画面記録の見た目の決まり：押したボタン＝深緑、2nd＝黄、ダブルフォルト＝赤、ミスした＝柔らかい赤、②はチーム色、番号は紺
            const SEL = "#0b6e75";
            const stepNum = (n, done) => (
              <span style={{ width:26, height:26, borderRadius:"50%", background: done ? C.navy : "#a9b2c4", color:C.white, fontSize:14, fontWeight:800, display:"inline-flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>{n}</span>
            );
            const head = (n, done, text, hint) => (
              <div style={{ display:"flex", alignItems:"center", gap:8, fontSize:15, fontWeight:800, color:C.text, margin:"0 0 8px" }}>
                {stepNum(n, done)}<span style={{ whiteSpace:"nowrap" }}>{text}</span>{hint && <span style={{ fontSize:12, color:C.textSec, fontWeight:700, minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{hint}</span>}
              </div>
            );
            const btnBase = { borderRadius:12, borderWidth:2, borderStyle:"solid", borderColor:C.border, background:C.white, color:C.text, fontWeight:800, cursor:"pointer", textAlign:"center", userSelect:"none", WebkitTapHighlightColor:"transparent", outline:"none", minWidth:0 };
            // ★borderColorは選択していないときも必ず指定する（指定を外すと枠が黒く残るため）
            const selStyle = (on, color=SEL) => on ? { background:color, borderColor:color, color:C.white } : { borderColor:C.border };
            const dim = (off) => off ? { opacity:0.35, pointerEvents:"none" } : {};
            const step2Off = osIsDF;
            const step3Off = osIsDF || !osTeam;
            const step4Off = osIsDF || !osKind;
            const step56Off = osIsDF || !osPlayer;
            const serverName = curServerIndividual || serverLabel || (curServer ? osTeamName(curServer) : ""); // ★相手の選手名が未登録でも「（相手のサーブ）」と出す
            const summary = osIsDF
              ? `ダブルフォルト（${serverName}）：${osTeamName(osScoreTeam)}に1点`
              : osReady
                ? `${osTeamName(osTeam)}に1点：${osDisp(osPlayer)}${osPlay?`（${getPlayLabel(osPlay)}）`:""} ${osKind==="winner"?"決め":"ミス"}${[osSide&&getSideLabel(osSide), osKind==="error"&&osMiss&&getMissLabel(osMiss), osCourse&&getCourseLabel(osCourse)].filter(Boolean).map(t=>"・"+t).join("")}`
                : "②〜④を選んでください";
            const teamBtn = (t) => {
              const on = osScoreTeam===t, color = osTeamColor(t);
              const fam = familyNamesOf(t).split("/").join("・");
              return (
                <button key={t} onClick={()=>osPickTeam(t)} style={{ ...btnBase, flex:1, padding:"10px 6px", background:color, borderColor:color, color:C.white,
                  opacity: (osScoreTeam && !on) ? 0.35 : 1, boxShadow: on ? "0 0 0 3px #fff inset, 0 3px 10px rgba(0,0,0,.18)" : "none" }}>
                  <FitLines lines={[osTeamName(t)]} maxPx={19} minPx={12} lineHeight={1.2} />
                  {fam && fam!==String(osTeamName(t)).split("/").join("・") && <FitLines lines={[fam]} maxPx={16} minPx={11} lineHeight={1.3} style={{ marginTop:3, opacity:0.95 }} />}
                </button>
              );
            };
            const playerGroup = (t) => {
              const off = !!osTargetTeam && osTargetTeam!==t;
              const wide = !!osTargetTeam && osTargetTeam===t;
              const color = osTeamColor(t);
              return (
                <div key={t} style={{ flex: wide ? "1.8 1 0" : "1 1 0", minWidth:0, borderRadius:12, padding:6, background: t==="A" ? "#e9f8ef" : "#fff1e6", transition:"flex .25s, opacity .2s", ...(off ? { opacity:0.3, pointerEvents:"none", filter:"grayscale(.6)" } : {}) }}>
                  <div style={{ fontSize:13, fontWeight:800, color, borderLeft:`3px solid ${color}`, paddingLeft:6, margin:"0 0 6px 2px", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{osTeamName(t)}</div>
                  <div style={{ display:"flex", gap:6 }}>
                    {osPlayersOf(t).map(p => {
                      const on = osPlayer===p.name && osTargetTeam===t;
                      const pos = osPositionOf(p);
                      // ★選手名は名字だけを大きく表示。ただし試合内に同じ名字の選手がいるときは区別できるよう名前まで出す
                      const parts = p.label.split(/[\s　]+/);
                      const sameSurname = match.players.filter(x => osSurname(x.player_name) === parts[0]).length > 1;
                      const lines = (parts.length>1 && sameSurname) ? [parts[0], parts.slice(1).join(" ")] : [parts[0] || p.name];
                      return (
                        <button key={p.id} onClick={()=>osPickPlayer(p.name)} style={{ ...btnBase, ...selStyle(on), flex:"1 1 0", minHeight:58, padding:"6px 4px", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", overflow:"hidden" }}>
                          <FitLines lines={lines} maxPx={lines.length>1 ? 16 : 21} minPx={10} lineHeight={1.2} />
                          {pos && <span style={{ fontSize:11.5, fontWeight:700, opacity:0.8, marginTop:2 }}>{pos}</span>}
                        </button>
                      );
                    })}
                  </div>
                </div>
              );
            };
            const chip = (on, onClick, label, extra={}) => (
              <button onClick={onClick} style={{ ...btnBase, ...selStyle(on), flex:1, padding:"10px 2px", fontSize:14, ...extra }}>{label}</button>
            );
            return (
              <div style={{ paddingBottom:"60vh" }}>
                {/* 1点前に戻す／選択をクリア */}
                <div style={{ display:"flex", gap:8, marginBottom:8 }}>
                  <button style={{ flex:1, padding:"10px 12px", background:C.white, border:`1px solid ${C.border}`, borderRadius:10, fontSize:14, fontWeight:800, color:"#b4433c", cursor:"pointer" }}
                    onClick={()=>{ if (currentGame.points.length===0) { alert("このゲームにはまだ記録がありません"); return; } setUndoConfirm(true); }}>↩ 1点前に戻す</button>
                  <button style={{ padding:"10px 12px", background:C.white, border:`1px solid ${C.border}`, borderRadius:10, fontSize:14, fontWeight:800, color:C.textSec, cursor:"pointer" }} onClick={osClear}>選択をクリア</button>
                  <button style={{ padding:"10px 12px", background:C.white, border:`1px solid ${C.border}`, borderRadius:10, fontSize:14, fontWeight:800, color:C.textSec, cursor:"pointer" }} onClick={()=>setOsMenu(true)} aria-label="その他の操作">⋯</button>
                </div>
                {osMenu && (
                  <Modal onClose={()=>setOsMenu(false)}>
                    <div style={{ fontSize:16, fontWeight:800, textAlign:"center", marginBottom:6 }}>その他の操作</div>
                    {(() => {
                      // ★「途中から記録する」「結果だけ記録」は、まだ1点も記録していないときだけ出す
                      const noPoints = match.games.every(g => (g.points?.length ?? 0) === 0 && !g.winner_team);
                      return (<>
                        <button style={{ width:"100%",padding:13,background:C.white,border:"1px solid "+C.border,borderRadius:10,color:C.navy,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false);
                          setOrderDraft({ first_server: match.first_server || "A", order_a: match.order_a === "p2" ? "p2" : "p1", order_b: match.order_b === "p2" ? "p2" : "p1",
                            receive_order_a: effectiveReceiveOrder(match, "A"), receive_order_b: effectiveReceiveOrder(match, "B") }); }}>🎾 サーブレシーブの順番変更</button>
                        <button style={{ width:"100%",padding:13,background:C.white,border:"1px solid "+C.border,borderRadius:10,color:C.navy,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false); setSkipGame({ winner:null, left:"", right:"" }); }}>⏭ このゲームを飛ばす</button>
                        {noPoints && <button style={{ width:"100%",padding:13,background:C.white,border:"1px solid "+C.border,borderRadius:10,color:C.navy,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false); const n=3; setMidStart({ startNum:n, winners:{}, server:gameServer(match.first_server||"A", n) }); }}>⏩ 試合の途中から記録する</button>}
                        {noPoints && <button style={{ width:"100%",padding:13,background:C.white,border:"1px solid "+C.border,borderRadius:10,color:C.navy,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false); setSimpleScoreA(""); setSimpleScoreB(""); setShowSimpleResult(true); }}>📝 結果だけ記録</button>}
                      </>);
                    })()}
                    <button style={{ width:"100%",padding:13,background:"#eaeef7",border:"1px solid #b9c4dc",borderRadius:10,color:C.navy,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false); setShowGamePicker(true); }}>🔧 記録済みのゲームを修正する</button>
                    <button style={{ width:"100%",padding:13,background:"#fff3e0",color:"#b45309",border:"1px solid #fbbf24",borderRadius:10,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false); setSuspendConfirm(true); }}>⏸ 中断</button>
                    <button style={{ width:"100%",padding:13,background:C.redL,color:C.red,border:"1px solid #f5b5b0",borderRadius:10,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false); setAbandonConfirm(true); }}>⏹ 途中終了</button>
                    {/* ★自動スクロールのON/OFF（この端末で覚えておく） */}
                    <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:8, padding:"10px 12px", border:`1px solid ${C.border}`, borderRadius:10 }}>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontSize:14, fontWeight:800, color:C.text }}>自動スクロール</div>
                        <div style={{ fontSize:11, color:C.textSec, marginTop:2 }}>選ぶたびに次の項目まで画面を動かします</div>
                      </div>
                      <button onClick={toggleOsAutoScroll} style={{ flexShrink:0, minWidth:76, padding:"9px 12px", borderRadius:20, border:"none", fontSize:14, fontWeight:800, cursor:"pointer", background: osAutoScroll ? "#0b6e75" : "#e6e8ee", color: osAutoScroll ? C.white : C.textSec }}>{osAutoScroll ? "ON" : "OFF"}</button>
                    </div>
                    <button style={{ width:"100%",padding:13,background:"#06C755",color:C.white,border:"none",borderRadius:10,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8,display:"flex",alignItems:"center",justifyContent:"center",gap:8 }} onClick={()=>{ setOsMenu(false); shareToLine("試合中"); }}>
                      <svg viewBox="0 0 24 24" width="18" height="18" fill="none"><path d="M12 3C6.48 3 2 6.69 2 11.25c0 2.99 1.91 5.61 4.79 7.08-.21.79-.76 2.83-.87 3.27-.14.55.2.54.42.4.17-.11 2.77-1.88 3.89-2.65.57.08 1.16.13 1.77.13 5.52 0 10-3.69 10-8.25S17.52 3 12 3z" fill="white"/></svg>
                      LINEで共有する
                    </button>
                    <button style={{ width:"100%",padding:12,background:C.gray,color:C.textSec,border:"1px solid "+C.border,borderRadius:10,fontSize:13,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>{ setOsMenu(false); setResetConfirm(true); }}>🗑️ スコア全削除</button>
                    <button style={{ width:"100%",padding:12,background:"#f0f0f0",color:C.text,border:"none",borderRadius:10,fontSize:13,fontWeight:700,cursor:"pointer",marginTop:14 }} onClick={()=>setOsMenu(false)}>閉じる</button>
                  </Modal>
                )}

                <div style={{ background:C.white, border:`1px solid ${C.border}`, borderRadius:14, padding:12 }}>
                  {/* ① サーブ */}
                  <div style={{ marginBottom:12 }}>
                    {head(1, true, "サーブは？", curServer ? `（${serverName}のサーブ）` : "")}
                    <div ref={osRefs.sv} style={{ display:"flex", gap:8 }}>
                      {[["1st",fault===0,SEL],["2nd",fault===1,"#f5a623"],["df",fault===2,"#e74c3c"]].map(([v,on,col])=>(
                        <button key={v} onClick={()=>osPickServe(v)} style={{ ...btnBase, ...selStyle(on,col), flex:1, minHeight:56, fontSize:17, lineHeight:1.15, display:"flex", alignItems:"center", justifyContent:"center" }}>
                          {v==="df" ? <span>ダブル<br/>フォルト</span> : v}
                        </button>
                      ))}
                    </div>
                    {osIsDF && (
                      <div style={{ marginTop:8, fontSize:13.5, fontWeight:700, color:"#c0392b", background:"#fdecec", borderRadius:8, padding:"7px 10px" }}>
                        {serverName}のダブルフォルト → {osTeamName(osScoreTeam)}に1点。そのまま「記録する」でOK
                      </div>
                    )}
                  </div>

                  {/* ② 得点チーム */}
                  <div style={{ marginBottom:12, ...dim(step2Off) }}>
                    {head(2, !!osScoreTeam, "どちらが得点しましたか？")}
                    <div ref={osRefs.team} style={{ display:"flex", gap:8 }}>
                      {teamBtn(leftTeam)}{teamBtn(rightTeam)}
                    </div>
                  </div>

                  {/* ③ 決めた／ミスした */}
                  <div style={{ marginBottom:12, ...dim(step3Off) }}>
                    {head(3, !!osKind, "この得点は？")}
                    <div ref={osRefs.kind} style={{ display:"flex", gap:8 }}>
                      <button onClick={()=>osPickKind("winner")} style={{ ...btnBase, ...selStyle(osKind==="winner"), flex:1, padding:"10px 4px", fontSize:17 }}>
                        決めた<div style={{ fontSize:12, fontWeight:700, opacity:0.8, marginTop:2 }}>（{osTeam ? osTeamName(osTeam)+"の" : ""}得点）</div>
                      </button>
                      <button onClick={()=>osPickKind("error")} style={{ ...btnBase, ...selStyle(osKind==="error","#d8645c"), flex:1, padding:"10px 4px", fontSize:17 }}>
                        ミスした<div style={{ fontSize:12, fontWeight:700, opacity:0.8, marginTop:2 }}>（{osTeam ? osTeamName(osOther(osTeam)) : "相手"}のミス）</div>
                      </button>
                    </div>
                  </div>

                  {/* ④ 誰が */}
                  <div style={{ marginBottom:12, ...dim(step4Off) }}>
                    {head(4, !!osPlayer, osKind==="error" ? "誰がミスした？" : osKind==="winner" ? "誰が決めた？" : "誰が？")}
                    <div ref={osRefs.player} style={{ display:"flex", gap:8 }}>
                      {playerGroup(leftTeam)}{playerGroup(rightTeam)}
                    </div>
                  </div>

                  {/* ⑤ どんなプレー */}
                  <div style={{ marginBottom:12, ...dim(step56Off) }}>
                    {head(5, !!osPlay, "どんなプレー？", "（任意）")}
                    <div ref={osRefs.play} style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:6 }}>
                      {PLAY_TYPES.map(p => (
                        <button key={p.key} disabled={playDisabledFor(osKind, p.key)} onClick={()=>osPickPlay(p.key)} style={{ ...btnBase, ...selStyle(osPlay===p.key), padding:"10px 2px", fontSize:14, ...(playDisabledFor(osKind, p.key) ? PLAY_OFF_STYLE : {}) }}>{p.label}</button>
                      ))}
                    </div>
                  </div>

                  {/* ⑥ よりくわしく */}
                  <div style={{ ...dim(step56Off) }}>
                    {head(6, !!(osSide||osMiss||osCourse), "よりくわしく", "（任意・分かる範囲で）")}
                    <div style={{ fontSize:12.5, fontWeight:800, color:C.textSec, margin:"0 0 5px 2px" }}>フォア／バック</div>
                    <div ref={osRefs.side} style={{ display:"flex", gap:8 }}>
                      {SIDE_TYPES.map(sd => chip(osSide===sd.key, ()=>osPickSide(sd.key), sd.label, { fontSize:15 }))}
                    </div>
                    {osKind==="error" && (
                      <>
                        <div style={{ fontSize:12.5, fontWeight:800, color:C.textSec, margin:"10px 0 5px 2px" }}>ミスの種類</div>
                        <div ref={osRefs.miss} style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                          {MISS_TYPES.map(m => chip(osMiss===m.key, ()=>osPickMiss(m.key), m.label, { fontSize:15 }))}
                        </div>
                      </>
                    )}
                    <div style={{ fontSize:12.5, fontWeight:800, color:C.textSec, margin:"10px 0 5px 2px" }}>コース</div>
                    <div ref={osRefs.course} style={{ display:"flex", gap:8 }}>
                      {COURSE_TYPES.map(c => (
                        <button key={c.key} onClick={()=>osPickCourse(c.key)} style={{ ...btnBase, ...selStyle(osCourse===c.key), flex:1, padding:"10px 2px", fontSize:15 }}>{c.dir}</button>
                      ))}
                    </div>
                  </div>
                </div>

                {/* このゲームの記録（タップで編集・削除） */}
                {currentGame.points.length>0 && (
                  <div style={{ background:C.white, border:`1px solid ${C.border}`, borderRadius:14, padding:12, marginTop:10 }}>
                    <div style={{ fontSize:13.5, fontWeight:800, marginBottom:6 }}>📝 このゲームの記録 <span style={{ fontSize:11, color:C.textSec, fontWeight:700 }}>（タップで編集・削除）</span></div>
                    {[...currentGame.points].reverse().map(pt => {
                      const mine = pt.scoring_team===leftTeam;
                      const l = isYounger ? pt.score_a_after : pt.score_b_after, r = isYounger ? pt.score_b_after : pt.score_a_after;
                      const sv = pt.fault_count===2 ? "DF" : pt.fault_count===1 ? "2nd" : "1st";
                      const tagStyle = { fontSize:10.5, fontWeight:800, borderRadius:9, padding:"1px 6px", marginLeft:4, whiteSpace:"nowrap" };
                      const det = [pt.side_type&&getSideLabel(pt.side_type), pt.miss_type&&getMissLabel(pt.miss_type), pt.course_type&&getCourseLabel(pt.course_type)].filter(Boolean).join("・");
                      return (
                        <div key={pt.id} onClick={()=>setEditingPoint({gameId:currentGame.id,point:pt})} style={{ display:"flex", alignItems:"center", gap:8, padding:"6px 0", borderBottom:"1px solid #f0f2f6", cursor:"pointer" }}>
                          <span style={{ width:22, height:22, borderRadius:6, display:"inline-flex", alignItems:"center", justifyContent:"center", fontWeight:900, color:osTeamColor(pt.scoring_team), background: pt.scoring_team==="A" ? "#e3f5ea" : "#fff1e6", flexShrink:0 }}>{pt.scoring_team==="A"?"○":"●"}</span>
                          <span style={{ flex:1, minWidth:0, fontSize:13 }}>
                            {osDisp(pt.player_name) || (pt.fault_count===2 ? "ダブルフォルト" : "—")}{pt.play_type ? `（${getPlayLabel(pt.play_type)}）` : ""}
                            <span style={{ ...tagStyle, color: sv==="DF" ? C.white : "#3d4457", background: sv==="DF" ? "#e74c3c" : "#eef0f4" }}>{sv}</span>
                            {pt.result_type && <span style={{ ...tagStyle, color: isWinnerResult(pt.result_type) ? "#1565c0" : C.red, background: isWinnerResult(pt.result_type) ? "#e3eefb" : "#fbe6ea" }}>{isWinnerResult(pt.result_type) ? "決め" : "ミス"}</span>}
                            {det && <div style={{ fontSize:11, color:C.textSec, marginTop:1 }}>{det}</div>}
                          </span>
                          <span style={{ fontSize:14, fontWeight:800, fontVariantNumeric:"tabular-nums", whiteSpace:"nowrap" }}>{l} - {r}</span>
                          <span style={{ fontSize:13, color:C.textSec }}>›</span>
                        </div>
                      );
                    })}
                  </div>
                )}

                {/* ★中断・途中終了などは「記録する」ボタンの近くに置くと押し間違えるため、上の「⋯ その他」にまとめた */}

                {/* 記録するボタン（画面の一番下に固定） */}
                <div style={{ position:"fixed", left:0, right:0, bottom:0, display:"flex", justifyContent:"center", padding:"0 10px calc(10px + env(safe-area-inset-bottom))", pointerEvents:"none", zIndex:50 }}>
                  <button disabled={!osReady} onClick={osRecord} style={{ pointerEvents:"auto", maxWidth:520, width:"100%", border:"none", borderRadius:14, padding:"13px 10px", background: osReady ? "#ffd23f" : "#e6e8ee", color: osReady ? C.navy : "#a6adbd", fontWeight:900, fontSize:18, boxShadow: osReady ? "0 4px 14px rgba(0,0,0,.18)" : "none", cursor: osReady ? "pointer" : "default" }}>
                    🎥 記録する
                    <span style={{ display:"block", fontSize:12, fontWeight:700, marginTop:2, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{summary}</span>
                  </button>
                </div>
                {osToast && (
                  <div style={{ position:"fixed", top:14, left:"50%", transform:"translateX(-50%)", background:C.navy, color:C.white, borderRadius:12, padding:"10px 16px", fontSize:14, fontWeight:800, zIndex:60, maxWidth:"92%", textAlign:"center", boxShadow:"0 4px 14px rgba(0,0,0,.25)" }}>{osToast}</div>
                )}
              </div>
            );
          })()}
        </div>
      )}

      {/* スコアタブ */}
      {tab==="score"&&(
        <div style={{ padding:12 }}>
          {match.games.map(g=>(
            <div key={g.id} style={S.card}>
              <div style={{ padding:"8px 12px",background:g.winner_team==="A"?"#2ecc71":g.winner_team==="B"?"#f97316":C.accent,color:C.white,display:"flex",justifyContent:"space-between" }}>
                <span style={{ fontWeight:700,fontSize:13 }}>{g.is_final?"🔥":""}第{g.game_number}ゲーム</span>
                <span style={{ fontWeight:700 }}>{isWinOnlyGame(g) ? "勝敗のみ" : `${g.score_a} - ${g.score_b}`}</span>
              </div>
              <div style={{ padding:"10px 12px" }}>
                <div style={{ display:"flex",gap:3,flexWrap:"wrap",marginBottom:8 }}>
                  {g.points.map(pt=>(
                    <div key={pt.id} title={[pt.player_name,pt.play_type?getPlayLabel(pt.play_type):"",pt.side_type?getSideLabel(pt.side_type):"",pt.course_type?getCourseLabel(pt.course_type):"",pt.miss_type?getMissLabel(pt.miss_type):"",pt.result_type?getResultLabel(pt.result_type):""].filter(Boolean).join(" ")} style={{ width:22,height:22,borderRadius:5,background:pt.scoring_team==="A"?"#2ecc71":"#f97316",display:"flex",alignItems:"center",justifyContent:"center",cursor:"default" }}>
                      <span style={{ fontSize:9,color:C.white,fontWeight:700 }}>{pt.scoring_team}</span>
                    </div>
                  ))}
                </div>
                <div style={{ overflowX:"auto" }}>
                  <table style={{ borderCollapse:"collapse",minWidth:280,fontSize:10 }}>
                    <tbody>
                      {[["A",teamALabel],["B",teamBLabel]].map(([team,name])=>(
                        <tr key={team}>
                          <td style={{ fontSize:10,color:team==="A"?C.teamA:C.teamB,fontWeight:700,paddingRight:8,whiteSpace:"nowrap" }}>
                            {g.server_team===team && <span style={{ display:"inline-block",width:8,height:8,borderRadius:"50%",background:C.red,marginRight:4,verticalAlign:"middle" }} title="サーブ側"/>}
                            {name}
                          </td>
                          {g.points.map((pt,i)=>(
                            <td key={i} style={{ padding:"2px 4px",textAlign:"center",background:pt.scoring_team===team?(pt.scoring_team==="A"?"#2ecc7118":"#f9731618"):"transparent",minWidth:28 }}>
                              {pt.scoring_team===team&&(
                                <div>
                                  <div style={{ fontSize:10,fontWeight:700,color:team==="A"?C.teamA:C.teamB }}>{pt.score_a_after}-{pt.score_b_after}</div>
                                  {pt.play_type&&<div style={{ fontSize:8,color:C.textSec }}>{getPlayLabel(pt.play_type).slice(0,4)}</div>}
                                </div>
                              )}
                            </td>
                          ))}
                        </tr>
                      ))}
                      {/* ★フォルト行：得点が記載されている列にだけ F / DF を表示 */}
                      <tr>
                        <td style={{ fontSize:10,color:C.textSec,fontWeight:700,paddingRight:8,whiteSpace:"nowrap" }}></td>
                        {g.points.map((pt,i)=>(
                          <td key={i} style={{ padding:"2px 4px",textAlign:"center",minWidth:28 }}>
                            {pt.fault_count===1&&<span style={{ fontSize:10,fontWeight:800,color:C.text }}>F</span>}
                            {pt.fault_count===2&&<span style={{ fontSize:10,fontWeight:800,color:C.text }}>DF</span>}
                          </td>
                        ))}
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ★検算タブ：1ポイントずつサーブ／レシーブ担当と1st・2nd・DFを書き出す */}
      {tab==="sheet"&&<ServeSheetTab match={match} teamALabel={teamALabel} teamBLabel={teamBLabel} onReload={onReload} />}

      {/* スタッツタブ */}
      {tab==="stats"&&<StatsTab match={match} onDownloadCsv={()=>downloadCsv(match)} onShareLine={()=>window.open(`https://line.me/R/msg/text/?${encodeURIComponent(buildLineText(match))}`,"_blank")}/>}

      {/* ★スコア・スタッツ・検算は縦に長くなるため、一番下にも戻るボタンを置く
            （毎回画面の一番上までスクロールし直さなくて済むように） */}
      {(tab==="score"||tab==="stats"||tab==="sheet")&&(
        <div style={{ padding:"4px 14px 20px" }}>
          <button style={{ ...S.btn("#fff"), color:C.navy, border:`1px solid ${C.border}`, fontSize:13 }} onClick={onBack}>← 戻る</button>
        </div>
      )}

      {/* ★サーブレシーブの順番変更（保存を押すまで反映しない） */}
      {orderDraft && (() => {
        const d = orderDraft;
        const fs = d.first_server, other = fs==="A" ? "B" : "A";
        const COLORS = { A: C.teamA, B: C.orange };
        const pairShort = (t) => familyNamesOf(t) || (t==="A" ? teamALabel : teamBLabel) || (t==="A" ? "自チーム" : "相手");
        const isDoublesMatch = match.players.filter(p=>p.team==="A").length>1;
        const row = (team, role) => {
          const names = sortedTeamNames(team);
          const key = role==="serve" ? (team==="A"?"order_a":"order_b") : (team==="A"?"receive_order_a":"receive_order_b");
          const cur = d[key]==="p2" ? "p2" : "p1";
          const set = (v) => setOrderDraft(o => {
            const nx = { ...o, [key]: v };
            return nx;
          });
          return (
            <div style={{ marginTop:12 }}>
              <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:13.5, fontWeight:800, marginBottom:6 }}>
                <span style={{ fontSize:11.5, fontWeight:800, color:C.white, background:COLORS[team], borderRadius:5, padding:"2px 6px" }}>{role==="serve"?"サーブ":"レシーブ"}</span>
                <span style={{ color:COLORS[team] }}>{pairShort(team)} の1人目</span>
              </div>
              <div style={{ display:"flex", gap:8 }}>
                <OrderSegBtn active={cur!=="p2"} color={COLORS[team]} onClick={()=>set("p1")}>{osDisp(names[0]) || "選手1"}</OrderSegBtn>
                <OrderSegBtn active={cur==="p2"} color={COLORS[team]} onClick={()=>set("p2")}>{osDisp(names[1]) || "選手2"}</OrderSegBtn>
              </div>
            </div>
          );
        };
        return (
          <Modal onClose={()=>setOrderDraft(null)}>
            <div style={{ fontSize:18, fontWeight:800, color:C.navy, textAlign:"center", marginBottom:12 }}>サーブレシーブの順番変更</div>
            <div style={{ fontSize:14, fontWeight:800, color:C.navy, marginBottom:8 }}>最初にサーブするペア（第1ゲーム）</div>
            <div style={{ display:"flex", background:C.gray, borderRadius:12, padding:4, gap:4 }}>
              {["A","B"].map(t => (
                <button key={t} onClick={()=>setOrderDraft(o=>({ ...o, first_server:t }))}
                  style={{ flex:1, border:"none", borderRadius:9, padding:"12px 4px", fontSize:15, fontWeight:800, cursor:"pointer", background: fs===t ? COLORS[t] : "transparent", color: fs===t ? C.white : C.textSec }}>{pairShort(t)}</button>
              ))}
            </div>
            {isDoublesMatch && (<>{row(fs, "serve")}{row(other, "receive")}</>)}
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginTop:18 }}>
              <button style={{ padding:13, background:"#f0f0f0", color:C.text, border:"none", borderRadius:12, fontSize:14, fontWeight:700, cursor:"pointer" }} onClick={()=>setOrderDraft(null)}>キャンセル</button>
              <button style={{ padding:13, background:`linear-gradient(135deg,${C.navy},${C.navyMid})`, color:C.white, border:"none", borderRadius:12, fontSize:15, fontWeight:800, cursor:"pointer" }} onClick={()=>{ saveOrderDraft(orderDraft); setOrderDraft(null); }}>保存</button>
            </div>
          </Modal>
        );
      })()}

      {modal?.type==="gameOver"&&(
        <Modal>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:44 }}>🎾</div>
            <h3 style={{ fontSize:18,fontWeight:800,margin:"8px 0" }}>第{modal.num}ゲーム終了！</h3>
            <p style={{ color:C.textSec }}>{osTeamName(modal.winner)}（{modal.winner==="A"?teamALabel:teamBLabel}） 勝利</p>
            <div style={{ fontSize:28,fontWeight:900,margin:"10px 0" }}><span style={{ color:isYounger?"#2ecc71":"#f97316" }}>{isYounger?modal.sA:modal.sB}</span><span style={{ color:C.textSec,margin:"0 8px" }}>-</span><span style={{ color:isYounger?"#f97316":"#2ecc71" }}>{isYounger?modal.sB:modal.sA}</span></div>
            {renderLastPointSummary(modal.gameId)}
            <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`),marginTop:14 }} onClick={()=>{setModal(null);startNewGame();}}>次のゲームへ</button>
            <button style={{ width:"100%",padding:11,background:"#f0f0f0",color:C.textSec,border:"none",borderRadius:10,fontSize:13,fontWeight:700,cursor:"pointer",marginTop:8 }} onClick={()=>setGameOverUndoConfirm(true)}>↩ 1点前に戻す</button>
          </div>
        </Modal>
      )}

      {modal?.type==="matchOver"&&(
        <Modal>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:44 }}>🏆</div>
            <h3 style={{ fontSize:18,fontWeight:800,margin:"8px 0" }}>試合終了！</h3>
            <p style={{ color:C.textSec }}>{osTeamName(modal.winner)}（{modal.winner==="A"?teamALabel:teamBLabel}） 勝利</p>
            <div style={{ fontSize:28,fontWeight:900,margin:"10px 0" }}><span style={{ color:isYounger?"#2ecc71":"#f97316" }}>{isYounger?modal.sA:modal.sB}</span><span style={{ color:C.textSec,margin:"0 8px" }}>-</span><span style={{ color:isYounger?"#f97316":"#2ecc71" }}>{isYounger?modal.sB:modal.sA}</span></div>
            {renderLastPointSummary(modal.gameId)}
            <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`),marginTop:14 }} onClick={()=>{ persist({...match,status:"finished"}); setModal(null); }}>結果を見る</button>
          </div>
        </Modal>
      )}

      {/* サーブ未設定時の選択モーダル */}
      {serveSelectModal && (() => {
        const aPlayers = match.players.filter(p=>p.team==="A").map(p=>p.player_name);
        const bPlayers = match.players.filter(p=>p.team==="B").map(p=>p.player_name);
        return (
          <ServeOrderModal
            aLabel={aPlayers.join("/") || "自チーム"} bLabel={bPlayers.join("/") || "相手チーム"}
            aP1={aPlayers[0]} aP2={aPlayers[1]} bP1={bPlayers[0]} bP2={bPlayers[1]}
            isDoubles={aPlayers.length>1 || bPlayers.length>1}
            initialOrders={match}
            onCancel={()=>{ setServeSelectModal(false); startingGameRef.current = false; setStartingGame(false); }}
            onConfirm={async (team, orderA, orderB, recvA, recvB)=>{
              setServeSelectModal(false);
              // DBのfirst_server・order_a・order_b・receive_order_a・receive_order_bを更新してからゲーム開始
              const updated = {...match, first_server: team, order_a: orderA, order_b: orderB, receive_order_a: recvA, receive_order_b: recvB};
              try {
                await saveMatch(updated);
                setMatch(updated);
              } catch(e) {
                startingGameRef.current = false; setStartingGame(false);
                alert("保存に失敗しました: " + (e.message || e));
                return;
              }
              // ★モーダルを開いた時点でロックしているので、ここで一度解除してから作成処理に入る
              startingGameRef.current = false;
              startNewGame(updated, team, orderA, orderB);
            }}
          />
        );
      })()}

      {undoConfirm && (
        <Modal onClose={()=>setUndoConfirm(false)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:40, marginBottom:8 }}>↩️</div>
            <h3 style={{ fontSize:16, fontWeight:800, marginBottom:8 }}>1点前に戻しますか？</h3>
            <p style={{ fontSize:13, color:C.textSec, marginBottom:20, lineHeight:1.6 }}>{(()=>{
              const lp = currentGame?.points?.[currentGame.points.length-1];
              if (!lp) return "直前に記録した1点が取り消されます。";
              const who = osDisp(lp.player_name) || (lp.fault_count===2 ? "ダブルフォルト" : "");
              const b = lp.scoring_team==="A" ? [lp.score_a_after-1, lp.score_b_after] : [lp.score_a_after, lp.score_b_after-1];
              const l = isYounger ? b[0] : b[1], r = isYounger ? b[1] : b[0];
              return `直前の記録${who?`「${who}${lp.play_type?`（${getPlayLabel(lp.play_type)}）`:""}」`:""}を取り消して、${l} - ${r} に戻します。`;
            })()}</p>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              <button style={{ padding:11, background:"#f0f0f0", color:C.text, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>setUndoConfirm(false)}>キャンセル</button>
              <button style={{ padding:11, background:C.navy, color:C.white, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>{ setUndoConfirm(false); undo(); }}>はい</button>
            </div>
          </div>
        </Modal>
      )}

      {gameOverUndoConfirm && modal?.type==="gameOver" && (
        <Modal onClose={()=>setGameOverUndoConfirm(false)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:40, marginBottom:8 }}>↩️</div>
            <h3 style={{ fontSize:16, fontWeight:800, marginBottom:8 }}>1点前に戻しますか？</h3>
            <p style={{ fontSize:12, color:C.textSec, marginBottom:20 }}>このゲームを決めた1点が取り消され、ゲームの途中から続きを記録できます。</p>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              <button style={{ padding:11, background:"#f0f0f0", color:C.text, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>setGameOverUndoConfirm(false)}>キャンセル</button>
              <button style={{ padding:11, background:C.navy, color:C.white, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>{ const gid=modal.gameId, w=modal.winner; setGameOverUndoConfirm(false); undoGameEndingPoint(gid, w); }}>はい</button>
            </div>
          </div>
        </Modal>
      )}

      {showSimpleResult && (
        <Modal onClose={()=>setShowSimpleResult(false)}>
          <div>
            <div style={{ fontSize:15, fontWeight:800, marginBottom:4 }}>結果だけ記録</div>
            <div style={{ fontSize:11, color:C.textSec, marginBottom:16 }}>ポイントを記録せず、ゲームカウントだけ入力します</div>
            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
              <div style={{ flex:1, minWidth:0, textAlign:"center" }}>
                <div style={{ fontSize:12, fontWeight:700, color:C.teamA, marginBottom:6, minHeight:18, lineHeight:"18px", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{teamALabel || osPlayersOf("A").map(x=>x.label).join("/")}</div>
                <input type="number" inputMode="numeric" value={simpleScoreA} onChange={e=>setSimpleScoreA(e.target.value)}
                  style={{ width:"100%", boxSizing:"border-box", textAlign:"center", fontSize:24, fontWeight:800, padding:"10px 4px", borderRadius:10, border:`2px solid ${C.teamA}`, color:C.teamA }} />
              </div>
              <div style={{ fontSize:18, color:C.textSec, marginTop:24 }}>-</div>
              <div style={{ flex:1, minWidth:0, textAlign:"center" }}>
                <div style={{ fontSize:12, fontWeight:700, color:C.teamB, marginBottom:6, minHeight:18, lineHeight:"18px", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{teamBLabel || osPlayersOf("B").map(x=>x.label).join("/")}</div>
                <input type="number" inputMode="numeric" value={simpleScoreB} onChange={e=>setSimpleScoreB(e.target.value)}
                  style={{ width:"100%", boxSizing:"border-box", textAlign:"center", fontSize:24, fontWeight:800, padding:"10px 4px", borderRadius:10, border:`2px solid ${C.teamB}`, color:C.teamB }} />
              </div>
            </div>

            <label style={{ display:"flex", alignItems:"center", gap:8, marginTop:14, padding:"10px 12px", borderRadius:10, background: isWithdrawalResult ? "#fff3e0" : C.gray, border:`1px solid ${isWithdrawalResult ? "#ffd9b3" : C.border}`, cursor:"pointer" }}>
              <input type="checkbox" checked={isWithdrawalResult} onChange={e=>{ setIsWithdrawalResult(e.target.checked); setWithdrawalWinner(null); }} style={{ width:18, height:18 }} />
              <div>
                <div style={{ fontSize:12.5, fontWeight:700, color:isWithdrawalResult?"#8a5a00":C.text }}>🚩 棄権による試合終了</div>
                <div style={{ fontSize:10.5, color:C.textSec, marginTop:1 }}>ゲームカウントに関係なく終了でき、勝者を直接選べます</div>
              </div>
            </label>

            {isWithdrawalResult && (
              <div style={{ marginTop:10 }}>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>どちらが勝ちましたか？（棄権していない方）</div>
                <div style={{ display:"flex", gap:8 }}>
                  <button
                    onClick={()=>setWithdrawalWinner("A")}
                    style={{ flex:1, padding:"10px 6px", borderRadius:10, fontSize:12.5, fontWeight:700, cursor:"pointer",
                      border:`2px solid ${C.teamA}`, background: withdrawalWinner==="A" ? C.teamA : "#fff", color: withdrawalWinner==="A" ? "#fff" : C.teamA }}
                  >{teamALabel} の勝ち</button>
                  <button
                    onClick={()=>setWithdrawalWinner("B")}
                    style={{ flex:1, padding:"10px 6px", borderRadius:10, fontSize:12.5, fontWeight:700, cursor:"pointer",
                      border:`2px solid ${C.teamB}`, background: withdrawalWinner==="B" ? C.teamB : "#fff", color: withdrawalWinner==="B" ? "#fff" : C.teamB }}
                  >{teamBLabel} の勝ち</button>
                </div>
              </div>
            )}

            <button
              style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), marginTop:14 }}
              disabled={
                simpleResultSaving2 || simpleScoreA==="" || simpleScoreB==="" ||
                (!isWithdrawalResult && simpleScoreA===simpleScoreB) ||
                (isWithdrawalResult && !withdrawalWinner)
              }
              onClick={()=>{
                const a = parseInt(simpleScoreA,10), b = parseInt(simpleScoreB,10);
                if (isNaN(a) || isNaN(b) || a<0 || b<0) { alert("正しいゲームカウントを入力してください"); return; }
                if (!isWithdrawalResult) {
                  if (a===b) { alert("同点にはできません（勝敗がつく数字を入力してください）"); return; }
                  const requiredWins = calcWinGames(match.game_format);
                  if (Math.max(a,b) < requiredWins) { alert(`${match.game_format}Gマッチは${requiredWins}ゲーム先取が必要です。まだ試合は終了できません。`); return; }
                }
                setSimpleResultSaving2(true);
                const withdrawalMemo = isWithdrawalResult
                  ? `棄権による試合終了（${withdrawalWinner==="A" ? teamALabel : teamBLabel} の勝利）`
                  : "";
                // ★修正のたびに棄権メモが積み重ならないよう、前回付けた棄権行はいったん取り除いてから付け直す
                const memoWithoutWithdrawal = (match.memo || "")
                  .split("\n")
                  .filter(line => !line.startsWith("棄権による試合終了"))
                  .join("\n")
                  .trim();
                const newMemo = withdrawalMemo
                  ? [memoWithoutWithdrawal, withdrawalMemo].filter(Boolean).join("\n")
                  : memoWithoutWithdrawal;
                persist({ ...match, games:[], match_score_a:a, match_score_b:b, status:"finished", memo:newMemo, walkover_winner: isWithdrawalResult ? withdrawalWinner : null });
                setSimpleResultSaving2(false);
                setShowSimpleResult(false);
                setIsWithdrawalResult(false);
                setWithdrawalWinner(null);
              }}
            >{simpleResultSaving2 ? "保存中..." : "この結果で確定する"}</button>
            <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:13, marginTop:8 }} onClick={()=>{ setShowSimpleResult(false); setIsWithdrawalResult(false); setWithdrawalWinner(null); }}>キャンセル</button>
          </div>
        </Modal>
      )}

      {resetConfirm && (
        <Modal onClose={()=>setResetConfirm(false)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:40, marginBottom:8 }}>⚠️</div>
            <h3 style={{ fontSize:16, fontWeight:800, marginBottom:8, color:C.red }}>本当にスコアをリセットしますか？</h3>
            <p style={{ fontSize:12, color:C.textSec, marginBottom:20 }}>記録したゲーム・ポイントがすべて削除され、未開始（0-0）の状態に戻ります。<b>この操作は元に戻せません。</b><br/>選手名・学校名・大会情報は残ります。</p>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              <button style={{ padding:11, background:"#f0f0f0", color:C.text, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>setResetConfirm(false)}>キャンセル</button>
              <button
                style={{ padding:11, background:C.red, color:C.white, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }}
                onClick={async ()=>{
                  setResetConfirm(false);
                  // ★意図的な全削除はsaveMatch()の安全装置に阻まれないよう、
                  // 　ここで直接削除してから、リセット後の状態をDBに反映する
                  const updated = { ...match, games:[], match_score_a:0, match_score_b:0, status:"scheduled", first_server:null, walkover_winner:null };
                  setMatch({...updated});
                  dropSavedSnapshot(match.id); // ★差分保存の控えも捨てる（DBを直接書き換えるため）
                  try {
                    const { data: existingGames } = await supabase.from("games").select("id").eq("match_id", match.id);
                    const gameIds = (existingGames ?? []).map(g => g.id);
                    if (gameIds.length) {
                      await supabase.from("points").delete().in("game_id", gameIds);
                      await supabase.from("faults").delete().in("game_id", gameIds);
                      await supabase.from("games").delete().in("id", gameIds);
                    }
                    await supabase.from("matches").update({
                      match_score_a:0, match_score_b:0, status:"scheduled", first_server:null, walkover_winner:null,
                    }).eq("id", match.id);
                  } catch(e) { alert("リセットに失敗しました: "+(e.message||e)); }
                }}
              >リセットする</button>
            </div>
          </div>
        </Modal>
      )}

      {suspendConfirm && (
        <Modal onClose={()=>setSuspendConfirm(false)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:40, marginBottom:8 }}>⏹️</div>
            <h3 style={{ fontSize:16, fontWeight:800, marginBottom:8 }}>試合を中断しますか？</h3>
            <p style={{ fontSize:12, color:C.textSec, marginBottom:20 }}>現在のスコアは保存されますが、勝敗の集計には含まれません。</p>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              <button style={{ padding:11, background:"#f0f0f0", color:C.text, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>setSuspendConfirm(false)}>キャンセル</button>
              <button style={{ padding:11, background:"#b45309", color:C.white, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={async ()=>{
                setSuspendConfirm(false);
                // ★「中断」は「終了(finished)」とは別の状態にし、勝敗・スタッツ集計から除外する
                const updated = { ...match, status:"suspended" };
                persist(updated);
                if (teamMatchId) {
                  try {
                    const { data: tmg } = await supabase.from("team_match_games").select("id").eq("match_id", match.id).maybeSingle();
                    if (tmg) await updateTeamMatchGame(tmg.id, { status:"suspended", recorder_id:null, recorder_name:null });
                  } catch(e) { /* 同期に失敗しても中断自体は継続 */ }
                }
                onBack();
              }}>中断する</button>
            </div>
          </div>
        </Modal>
      )}

      {abandonConfirm && (
        <Modal onClose={()=>setAbandonConfirm(false)}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:40, marginBottom:8 }}>⏹️</div>
            <h3 style={{ fontSize:16, fontWeight:800, marginBottom:8 }}>この試合を「途中終了」にしますか？</h3>
            <p style={{ fontSize:12, color:C.textSec, marginBottom:20 }}>現在のスコアはそのまま残ります（消えません）が、勝敗の集計には含まれません。<br/>ホーム画面の「記録途中の試合」には表示されなくなり、この試合は今後再開できなくなります。</p>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              <button style={{ padding:11, background:"#f0f0f0", color:C.text, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={()=>setAbandonConfirm(false)}>キャンセル</button>
              <button style={{ padding:11, background:C.red, color:C.white, border:"none", borderRadius:10, fontSize:13, fontWeight:700, cursor:"pointer" }} onClick={async ()=>{
                setAbandonConfirm(false);
                // ★「途中終了」は「中断」と同じく勝敗・スタッツ集計から除外するが、
                // 　ホーム画面の「記録途中の試合」には表示させず、再開もできない状態にする
                const updated = { ...match, status:"abandoned" };
                persist(updated);
                if (teamMatchId) {
                  try {
                    const { data: tmg } = await supabase.from("team_match_games").select("id").eq("match_id", match.id).maybeSingle();
                    if (tmg) await updateTeamMatchGame(tmg.id, { status:"suspended", recorder_id:null, recorder_name:null });
                  } catch(e) { /* 同期に失敗しても途中終了自体は継続 */ }
                }
                onBack();
              }}>途中終了</button>
            </div>
          </div>
        </Modal>
      )}

      {/* ★記録中はメニューバーを出さない（「記録する」ボタンとの押し間違い防止・画面を広く使うため）。戻るのは左上の「←」 */}
      {!osRecording && !(modal?.type==="gameOver" || modal?.type==="matchOver") && <NavBar active="record" onNavigate={onNavigate}/>}
    </div>
  );
}

// ============================================================
// スタッツタブ（★相手チームスタッツのバグ修正）
// ============================================================
// ============================================================
// ★試合サマリー／AI総評／改善優先順位／詳細分析パネル
// ============================================================
// ★part："summary"＝①試合サマリーだけ／"details"＝②詳細分析だけ／"all"＝両方
//   スタッツタブでは、詳細分析を選手ごとの内訳の下（LINE共有ボタンの上）に置くため分けて使う。
function MatchSummaryPanel({ match, part="all" }) {
  const sum = calcMatchSummary(match);
  const highlights = buildHighlights(sum);
  const teamALabel = match.players.find(p=>p.team==="A")?.club_name || "自チーム";
  const teamBLabel = match.players.find(p=>p.team==="B")?.club_name || "相手チーム";
  const isFinished = match.status==="finished";
  const aWin = winnerSideOf(match)==="A";

  const detailBox = { background:C.white, border:`1px solid ${C.border}`, borderRadius:12, marginBottom:10, overflow:"hidden" };
  const summaryBtn = { fontSize:12, fontWeight:700, color:C.text, padding:"12px 14px", cursor:"pointer", listStyle:"none", display:"flex", alignItems:"center", gap:6 };

  function CompareRow({ label, a, b }) {
    return (
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"7px 0", borderBottom:`1px solid ${C.border}`, fontSize:12 }}>
        <span style={{ fontWeight:700, color:C.teamA }}>{a}</span>
        <span style={{ color:C.textSec, fontSize:11 }}>{label}</span>
        <span style={{ fontWeight:700, color:C.teamB }}>{b}</span>
      </div>
    );
  }

  return (
    <div style={{ marginBottom:14 }}>
      {part!=="details" && (<>
      {/* ①試合サマリー（試合結果／決定率・総得点・決めた数・自分のミス／最多得点） */}
      <div style={{ ...detailBox, padding:14 }}>
        <div style={{ fontSize:13, fontWeight:800, marginBottom:12, display:"flex", alignItems:"center", gap:6 }}>
          📋 試合サマリー
          <span style={{ marginLeft:"auto", fontSize:9.5, fontWeight:800, color:C.purple, background:"#eef0fe", borderRadius:6, padding:"2px 6px" }}>ペア合計</span>
        </div>

        {isFinished && (
          <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:10, background:C.gray, borderRadius:10, padding:14, marginBottom:14 }}>
            <span style={{ fontSize:13, fontWeight:800, padding:"4px 12px", borderRadius:20, color:C.white, background:aWin?C.accent:C.textSec }}>{aWin?"勝利":"敗北"}</span>
            <span style={{ fontSize:20, fontWeight:900, color:C.text }}>{match.match_score_a} - {match.match_score_b}</span>
          </div>
        )}

        {sum.decisionRate!=null && (
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginBottom:10 }}>
            <div style={{ background:C.gray, borderRadius:10, padding:12, textAlign:"center" }}>
              <div style={{ fontSize:20, fontWeight:900, color:C.navy }}>{sum.decisionRate}%</div>
              <div style={{ fontSize:10.5, color:C.textSec, marginTop:2 }}>決定率</div>
            </div>
            <div style={{ background:C.gray, borderRadius:10, padding:12, textAlign:"center" }}>
              <div style={{ fontSize:20, fontWeight:900, color:C.navy }}>{sum.totalA}</div>
              <div style={{ fontSize:10.5, color:C.textSec, marginTop:2 }}>総得点</div>
            </div>
            <div style={{ background:C.gray, borderRadius:10, padding:12, textAlign:"center" }}>
              <div style={{ fontSize:20, fontWeight:900, color:C.navy }}>{sum.attackA}</div>
              <div style={{ fontSize:10.5, color:C.textSec, marginTop:2 }}>決めた数</div>
            </div>
            <div style={{ background:C.gray, borderRadius:10, padding:12, textAlign:"center" }}>
              <div style={{ fontSize:20, fontWeight:900, color:C.navy }}>{sum.selfMissA}</div>
              <div style={{ fontSize:10.5, color:C.textSec, marginTop:2 }}>自分達のミス</div>
            </div>
          </div>
        )}

        {sum.topScorer && (
          <div style={{ background:C.gray, borderRadius:10, padding:12, textAlign:"center" }}>
            <div style={{ fontSize:15, fontWeight:800, color:C.text }}>{sum.topScorer.player_name}</div>
            <div style={{ fontSize:10.5, color:C.textSec, marginTop:2 }}>最多得点（{sum.topScorer.winners}点）</div>
          </div>
        )}

        {sum.decisionRate!=null && (
          <div style={{ marginTop:10, background:C.gray, borderRadius:10, padding:"12px 14px" }}>
            <div style={{ fontSize:10.5, color:C.textSec, fontWeight:700, marginBottom:6 }}>決定率の内訳</div>
            <div style={{ fontSize:12.5, fontWeight:800, color:C.text, lineHeight:1.7 }}>
              決めた数 {sum.attackA} ÷（決めた数 {sum.attackA} ＋ 自分達のミス {sum.selfMissA}）＝ {sum.decisionRate}%
            </div>
            <div style={{ marginTop:8, fontSize:10.5, color:C.textSec, lineHeight:1.5 }}>
              ※相手のミスでもらった得点／相手の好プレーで取られた失点は含みません。「決めた数」と「自分達のミス」だけで比べた割合です。
            </div>
          </div>
        )}
      </div>

      </>)}

      {part!=="summary" && (<>
      {/* ②詳細分析（折りたたみ） */}
      <div style={{ fontSize:11, color:C.textSec, fontWeight:700, margin:"14px 2px 6px" }}>▼ 詳細分析</div>

      {(sum.posStats.front.name || sum.posStats.back.name) && (
        <details style={detailBox}>
          <summary style={summaryBtn}>
            📍 決定率の内訳
            <span style={{ marginLeft:"auto", fontSize:9.5, fontWeight:800, color:C.navy, background:"#eaeef7", borderRadius:6, padding:"2px 6px" }}>個人別</span>
          </summary>
          <div style={{ padding:"0 14px 14px" }}>
            {["back","front"].map(key=>{
              const p = sum.posStats[key];
              if (!p.name) return null;
              const total = p.win+p.err;
              const rate = total>0 ? Math.round(p.win/total*100) : 0;
              return (
                <div key={key} style={{ marginBottom:8 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", marginBottom:4 }}>
                    <span style={{ fontSize:12, fontWeight:700 }}>{p.name}</span>
                    <span style={{ fontSize:15, fontWeight:900, color:C.text }}>{rate}%</span>
                  </div>
                  <div style={{ height:5, background:C.gray, borderRadius:3, overflow:"hidden" }}>
                    <div style={{ width:`${rate}%`, height:"100%", background:getRateTierColor(rate) }}/>
                  </div>
                  <div style={{ fontSize:11.5, color:C.textSec, marginTop:5, fontWeight:600 }}>決めた{p.win}／ミス{p.err}</div>
                </div>
              );
            })}
          </div>
        </details>
      )}

      {(sum.pointSources.length>0 || sum.missSources.length>0) && (
        <details style={detailBox}>
          <summary style={summaryBtn}>
            🎯 得点源・失点源
            <span style={{ marginLeft:"auto", fontSize:9.5, fontWeight:800, color:C.purple, background:"#eef0fe", borderRadius:6, padding:"2px 6px" }}>ペア合計</span>
          </summary>
          <div style={{ padding:"0 14px 14px", display:"flex", gap:10 }}>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:11.5, fontWeight:800, color:C.accent, marginBottom:8 }}>🟢 今日の得点源</div>
              {sum.pointSources.map((p,i)=>(
                <div key={p.key} style={{ display:"flex", alignItems:"center", gap:6, padding:"7px 0", borderBottom:`1px solid ${C.border}` }}>
                  <span style={{ fontSize:11, fontWeight:800, color:C.textSec, width:14 }}>{i+1}</span>
                  <span style={{ flex:1, fontSize:12, fontWeight:700 }}>{p.label}</span>
                  <span style={{ fontSize:13, fontWeight:900, color:C.accent }}>{p.count}点</span>
                </div>
              ))}
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:11.5, fontWeight:800, color:C.red, marginBottom:8 }}>🔴 今日の失点源</div>
              {sum.missSources.map((p,i)=>(
                <div key={p.key} style={{ display:"flex", alignItems:"center", gap:6, padding:"7px 0", borderBottom:`1px solid ${C.border}` }}>
                  <span style={{ fontSize:11, fontWeight:800, color:C.textSec, width:14 }}>{i+1}</span>
                  <span style={{ flex:1, fontSize:12, fontWeight:700 }}>{p.label}</span>
                  <span style={{ fontSize:13, fontWeight:900, color:C.red }}>{p.count}点</span>
                </div>
              ))}
            </div>
          </div>
        </details>
      )}

      {sum.bestPlays.length>0 && (
        <details style={detailBox}>
          <summary style={summaryBtn}>
            🏆 今日の武器
            <span style={{ marginLeft:"auto", fontSize:9.5, fontWeight:800, color:C.purple, background:"#eef0fe", borderRadius:6, padding:"2px 6px" }}>ペア合計</span>
          </summary>
          <div style={{ padding:"0 14px 14px" }}>
            <div style={{ background:C.gray, borderRadius:10, padding:"10px 12px", marginBottom:10, fontSize:11, color:C.textSec, lineHeight:1.6 }}>
              「使用回数」＝そのプレーを使った合計回数。「成功率」＝決めた数÷使用回数。使用回数が少ないプレーには「参考」タグが付きます。
            </div>
            {sum.bestPlays.map((p,i)=>(
              <div key={p.key} style={{ padding:"10px 0", borderBottom:`1px solid ${C.border}` }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontSize:12, fontWeight:800, color:C.textSec, width:16 }}>{p.isRef?"-":i+1}</span>
                  <span style={{ fontSize:13, fontWeight:800 }}>{p.label}</span>
                  <span style={{ marginLeft:"auto", fontSize:15, fontWeight:900, color:getRateTierColor(p.rate) }}>{p.rate}%</span>
                </div>
                <div style={{ height:5, background:C.gray, borderRadius:3, overflow:"hidden", marginTop:5 }}>
                  <div style={{ width:`${p.rate}%`, height:"100%", background:p.isRef?C.border:getRateTierColor(p.rate) }}/>
                </div>
                <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:5 }}>
                  {p.isRef ? (
                    <>
                      <span style={{ fontSize:10, fontWeight:800, color:C.textSec, background:C.border, borderRadius:6, padding:"2px 7px" }}>参考</span>
                      <span style={{ fontSize:10.5, color:C.textSec }}>使用{p.total}回（決め{p.win}／ミス{p.err}）</span>
                    </>
                  ) : (
                    <>
                      <span style={{ fontSize:11, fontWeight:800, color:C.navy, background:C.gray, borderRadius:6, padding:"2px 8px" }}>使用{p.total}回</span>
                      <span style={{ marginLeft:"auto", fontSize:10.5, color:C.textSec }}>決め{p.win}／ミス{p.err}</span>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        </details>
      )}

      {sum.worstPlays.length>0 && (
        <details style={detailBox}>
          <summary style={summaryBtn}>
            📉 改善ポイント
            <span style={{ marginLeft:"auto", fontSize:9.5, fontWeight:800, color:C.purple, background:"#eef0fe", borderRadius:6, padding:"2px 6px" }}>ペア合計</span>
          </summary>
          <div style={{ padding:"0 14px 14px" }}>
            {sum.worstPlays.map((p,i)=>(
              <div key={p.key} style={{ padding:"10px 0", borderBottom:`1px solid ${C.border}` }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontSize:12, fontWeight:800, color:C.textSec, width:16 }}>{p.isRef?"-":i+1}</span>
                  <span style={{ fontSize:13, fontWeight:800 }}>{p.label}</span>
                  <span style={{ marginLeft:"auto", fontSize:15, fontWeight:900, color:getRateTierColor(p.rate) }}>{p.rate}%</span>
                </div>
                <div style={{ height:5, background:C.gray, borderRadius:3, overflow:"hidden", marginTop:5 }}>
                  <div style={{ width:`${p.rate}%`, height:"100%", background:p.isRef?C.border:getRateTierColor(p.rate) }}/>
                </div>
                <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:5 }}>
                  {p.isRef ? (
                    <>
                      <span style={{ fontSize:10, fontWeight:800, color:C.textSec, background:C.border, borderRadius:6, padding:"2px 7px" }}>参考</span>
                      <span style={{ fontSize:10.5, color:C.textSec }}>使用{p.total}回（決め{p.win}／ミス{p.err}）</span>
                    </>
                  ) : (
                    <>
                      <span style={{ fontSize:11, fontWeight:800, color:C.navy, background:C.gray, borderRadius:6, padding:"2px 8px" }}>使用{p.total}回</span>
                      <span style={{ marginLeft:"auto", fontSize:10.5, color:C.textSec }}>決め{p.win}／ミス{p.err}</span>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        </details>
      )}

      {(sum.serveBy.A.total>0 || sum.serveBy.B.total>0) && (() => {
        // ★サーブ分析：左＝自チーム（緑）／右＝相手（オレンジ）。色＝チームの意味に統一する
        //   （以前は自チームの数字だけを「本数＝緑・割合＝オレンジ」で並べていて、色の意味が分かりにくかった）
        const A = sum.serveBy.A, B = sum.serveBy.B;
        const pct = (n, d) => d>0 ? `${Math.round(n/d*100)}%` : "—";
        const cnt = (r, n) => r.total>0 ? `${n}本（${pct(n, r.total)}）` : "—";
        const winRate = (w, n) => n>0 ? `${w}/${n}（${pct(w, n)}）` : "—";
        const sameName = teamALabel === teamBLabel;
        const nameA = sameName ? "自チーム" : teamALabel, nameB = sameName ? "相手" : teamBLabel;
        const row = (label, a, b, note) => (
          <div style={{ display:"grid", gridTemplateColumns:"1fr auto 1fr", alignItems:"center", gap:8, padding:"8px 0", borderBottom:`1px solid ${C.border}` }}>
            <span style={{ fontSize:13, fontWeight:800, color:C.teamA }}>{a}</span>
            <span style={{ fontSize:11, color:C.textSec, textAlign:"center", lineHeight:1.3 }}>{label}{note && <><br/><span style={{ fontSize:9.5 }}>{note}</span></>}</span>
            <span style={{ fontSize:13, fontWeight:800, color:C.teamB, textAlign:"right" }}>{b}</span>
          </div>
        );
        return (
          <details style={detailBox}>
            <summary style={summaryBtn}>🎾 サーブ分析</summary>
            <div style={{ padding:"0 14px 14px" }}>
              <div style={{ display:"grid", gridTemplateColumns:"1fr auto 1fr", alignItems:"center", gap:8, paddingBottom:6, borderBottom:`2px solid ${C.border}` }}>
                <span style={{ fontSize:12, fontWeight:800, color:C.white, background:C.teamA, borderRadius:6, padding:"3px 8px", justifySelf:"start", maxWidth:"100%", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{nameA}</span>
                <span style={{ fontSize:10, color:C.textSec }}>サーブ{A.total}本 / {B.total}本</span>
                <span style={{ fontSize:12, fontWeight:800, color:C.white, background:C.teamB, borderRadius:6, padding:"3px 8px", justifySelf:"end", maxWidth:"100%", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{nameB}</span>
              </div>
              {row("1stイン", cnt(A, A.s1), cnt(B, B.s1))}
              {row("2ndイン", cnt(A, A.s2), cnt(B, B.s2))}
              {row("ダブルフォルト", cnt(A, A.df), cnt(B, B.df))}
              {row("1stサーブ時の得点", winRate(A.s1Win, A.s1), winRate(B.s1Win, B.s1), "得点/本数")}
              {row("2ndサーブ時の得点", winRate(A.s2Win, A.s2), winRate(B.s2Win, B.s2), "得点/本数")}
            </div>
          </details>
        );
      })()}

      <details style={detailBox}>
        <summary style={summaryBtn}>🔥 試合の流れ</summary>
        <div style={{ padding:"0 14px 14px" }}>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
            <div style={{ background:C.gray, borderRadius:8, padding:10 }}>
              <div style={{ fontSize:10, color:C.textSec, fontWeight:700 }}>最大連続得点</div>
              <div style={{ fontSize:16, fontWeight:800, color:C.accent }}>{sum.maxWinStreak}点</div>
            </div>
            <div style={{ background:C.gray, borderRadius:8, padding:10 }}>
              <div style={{ fontSize:10, color:C.textSec, fontWeight:700 }}>最大連続失点</div>
              <div style={{ fontSize:16, fontWeight:800, color:C.red }}>{sum.maxLoseStreak}点</div>
            </div>
          </div>
        </div>
      </details>

      {sum.timeline.length>0 && (
        <details style={detailBox}>
          <summary style={summaryBtn}>📈 得点推移（1ゲーム目）</summary>
          <div style={{ padding:"0 14px 14px" }}>
            {(() => {
              // ★アイコンは「自チームの得点＝緑の○」「失点＝赤の×」の2種類だけにする。
              //   右側にはそのポイント時点のカウント（自チーム-相手）を出す。
              let a = 0, b = 0;
              return sum.timeline.map((p,i)=>{
                const isWin = p.team==="A";
                if (isWin) a++; else b++;
                return (
                  <div key={i} style={{ display:"flex", alignItems:"center", gap:8, fontSize:12, padding:"4px 0" }}>
                    <span style={{ width:24, height:24, borderRadius:7, display:"flex", alignItems:"center", justifyContent:"center", fontSize:15, fontWeight:900, color:isWin?C.accent:C.red, background:isWin?"#e3f5ea":"#fbe6ea", flexShrink:0 }}>{isWin?"○":"×"}</span>
                    <span style={{ flex:1, minWidth:0 }}>
                      {p.player ? `${p.player}${p.play?`（${getPlayLabel(p.play)}）`:""}` : (isWin?"相手ミス":"相手の攻撃/自分ミス")}
                      {/* ★そのプレーが「決め（ウィナー）」か「ミス」かを小さなバッジで表示 */}
                      {p.player && (p.isWinner===true || p.isWinner===false) && (
                        <span style={{ display:"inline-block", marginLeft:6, padding:"1px 7px", borderRadius:10, fontSize:11, fontWeight:800, verticalAlign:"1px",
                          color: p.isWinner ? "#1565c0" : C.red, background: p.isWinner ? "#e3eefb" : "#fbe6ea" }}>{p.isWinner ? "決め" : "ミス"}</span>
                      )}
                    </span>
                    <span style={{ flexShrink:0, fontSize:14, fontWeight:800, fontVariantNumeric:"tabular-nums" }}>
                      <span style={{ color:isWin?C.teamA:C.textSec }}>{a}</span>
                      <span style={{ color:C.textSec, margin:"0 3px" }}>-</span>
                      <span style={{ color:isWin?C.textSec:C.teamB }}>{b}</span>
                    </span>
                  </div>
                );
              });
            })()}
          </div>
        </details>
      )}
      </>)}
    </div>
  );
}

// ============================================================
// ★検算シート：1ポイントずつ「誰がサーブし、誰がレシーブし、1stイン/2ndイン/DFのどれだったか」を
//   すべて書き出す画面。スタッツの数字が本当に合っているかを目で確かめるためのもの。
//   担当者の割り出しは buildServeReceiveRows() を使う＝スタッツとまったく同じ計算なので、
//   ここに出ている内容とスタッツの数字は必ず一致する。
// ============================================================
function ServeSheetTab({ match, teamALabel, teamBLabel, onReload }) {
  const rows = buildServeReceiveRows(match);
  // ★「選手A」「選手B」のまま記録されたポイントが残っていないか
  const placeholderCount = countPlaceholderRecords(match);
  const [repairing, setRepairing] = useState(false);
  const byGame = {};
  rows.forEach(r => { (byGame[r.game.id] ??= []).push(r); });

  const serveResultLabel = (k) => k==="1st" ? "1stイン" : k==="2nd" ? "2ndイン" : k==="df" ? "ダブルフォルト" : "－";
  const serveResultColor = (k) => k==="1st" ? "#16a34a" : k==="2nd" ? "#d97706" : k==="df" ? C.red : C.textSec;
  const teamColor = (t) => t==="A" ? C.teamA : C.teamB;
  const teamName  = (t) => t==="A" ? teamALabel : teamBLabel;

  // ★選手ごとのサーブ集計（スタッツ画面の「サーブ分析」と同じ数字になるはず）
  const tally = {};
  rows.forEach(r => {
    if (!r.serverPlayer || !r.serveResult) return;
    const key = r.serverTeam + "__" + r.serverPlayer;
    tally[key] ??= { team:r.serverTeam, name:r.serverPlayer, first:0, second:0, df:0 };
    if (r.serveResult==="1st") tally[key].first++;
    else if (r.serveResult==="2nd") tally[key].second++;
    else if (r.serveResult==="df") tally[key].df++;
  });
  const tallyRows = Object.values(tally);

  if (rows.length === 0) {
    return <div style={{ padding:30, textAlign:"center", color:C.textSec, fontSize:12.5 }}>まだポイントが記録されていません</div>;
  }

  return (
    <div style={{ padding:12 }}>
      <div style={{ fontSize:11.5, color:C.navy, background:"#eef0ff", border:"1px solid #dcdffc", borderRadius:10, padding:"10px 12px", lineHeight:1.6, marginBottom:12 }}>
        💡 1ポイントずつ、誰がサーブして誰がレシーブしたかを書き出しています。サーブ担当は「2本ずつ交代」、レシーブ担当は「1本ごとに交代」というルールから自動で割り出しています。実際と違っていた場合は、記録タブの「サーブ・レシーブ順を修正」で直せます。
      </div>

      {/* ★相手の名前が分からないまま記録した試合は、1点ごとの記録に「選手A」「選手B」という
            仮の名前が残る。あとから正しい名前を登録しても記録側は直らないため、ここでまとめて直す。 */}
      {placeholderCount > 0 && (
        <div style={{ fontSize:11.5, color:"#92400e", background:"#fff7ed", border:"1px solid #fed7aa", borderRadius:10, padding:"10px 12px", lineHeight:1.6, marginBottom:12 }}>
          ⚠️ 「選手A」「選手B」という仮の名前のまま記録されたポイントが {placeholderCount} 件あります。今の相手選手名（{(match.players??[]).filter(p=>p.team==="B").sort((a,b)=>a.order_num-b.order_num).map(p=>p.player_name).join("／")}）に置き換えられます。
          <button
            style={{ ...S.btn("#f97316", C.white), fontSize:12, padding:"9px", marginTop:8 }}
            disabled={repairing}
            onClick={async ()=>{
              if (!window.confirm("記録に残っている「選手A」「選手B」を、今の相手選手名に置き換えます。よろしいですか？")) return;
              setRepairing(true);
              try {
                const n = await repairPlaceholderPlayerNames(match);
                alert(n + "件を修正しました。");
                onReload && onReload();
              } catch(e) {
                alert("修正に失敗しました: " + (e.message || e));
              } finally {
                setRepairing(false);
              }
            }}
          >{repairing ? "修正中..." : "今の選手名に直す"}</button>
        </div>
      )}

      {match.games.map(g => {
        const gRows = byGame[g.id] ?? [];
        if (gRows.length === 0) return null;
        return (
          <div key={g.id} style={{ ...S.card, overflow:"hidden", marginBottom:12 }}>
            <div style={{ padding:"8px 12px", background:g.winner_team==="A"?"#2ecc71":g.winner_team==="B"?"#f97316":C.accent, color:C.white, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <span style={{ fontWeight:700, fontSize:13 }}>{g.is_final?"🔥":""}第{g.game_number}ゲーム</span>
              <span style={{ fontWeight:700, fontSize:13 }}>{g.score_a} - {g.score_b}</span>
            </div>
            {gRows.map((r, i) => {
              const pt = r.point;
              return (
                <div key={pt.id ?? i} style={{ padding:"9px 12px", borderBottom:`1px solid ${C.border}` }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                    <span style={{ fontSize:10, fontWeight:800, color:C.textSec, background:C.gray, borderRadius:5, padding:"2px 6px", minWidth:20, textAlign:"center" }}>{r.idx+1}</span>
                    <span style={{ fontSize:13, fontWeight:800, color:C.text }}>{pt.score_a_after}-{pt.score_b_after}</span>
                    <span style={{ fontSize:10.5, fontWeight:700, color:teamColor(pt.scoring_team), marginLeft:"auto" }}>
                      {teamName(pt.scoring_team)} の得点
                    </span>
                  </div>

                  {r.serverTeam ? (
                    <div style={{ fontSize:11.5, color:C.text, lineHeight:1.7 }}>
                      <div>
                        <span style={{ color:C.textSec }}>サーブ　</span>
                        <span style={{ fontWeight:700, color:teamColor(r.serverTeam) }}>{r.serverPlayer || "（選手不明）"}</span>
                        <span style={{ marginLeft:6, fontWeight:800, color:serveResultColor(r.serveResult) }}>{serveResultLabel(r.serveResult)}</span>
                      </div>
                      <div>
                        <span style={{ color:C.textSec }}>レシーブ　</span>
                        <span style={{ fontWeight:700, color:teamColor(r.receiveTeam) }}>{r.receiverPlayer || "（選手不明）"}</span>
                      </div>
                    </div>
                  ) : (
                    <div style={{ fontSize:11.5, color:C.textSec }}>サーブ側が記録されていません</div>
                  )}

                  {(pt.player_name || pt.play_type) && (
                    <div style={{ fontSize:11, color:C.textSec, marginTop:3 }}>
                      内容　{[pt.player_name, pt.play_type?getPlayLabel(pt.play_type):"", pt.side_type?getSideLabel(pt.side_type):"", pt.course_type?getCourseLabel(pt.course_type):"", pt.miss_type?getMissLabel(pt.miss_type):"", pt.is_winner?"決めた":"ミス"].filter(Boolean).join("・")}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        );
      })}

      {tallyRows.length > 0 && (
        <div style={{ ...S.card, overflow:"hidden" }}>
          <div style={{ padding:"9px 12px", background:C.navy, color:C.white, fontSize:12.5, fontWeight:800 }}>
            この試合のサーブ集計（スタッツと同じ数字）
          </div>
          <div style={{ overflowX:"auto" }}>
            <table style={{ borderCollapse:"collapse", width:"100%", fontSize:11.5 }}>
              <thead>
                <tr style={{ background:C.gray }}>
                  <th style={{ textAlign:"left", padding:"7px 10px", color:C.textSec, fontWeight:700 }}>選手</th>
                  <th style={{ padding:"7px 6px", color:C.textSec, fontWeight:700 }}>1st</th>
                  <th style={{ padding:"7px 6px", color:C.textSec, fontWeight:700 }}>2nd</th>
                  <th style={{ padding:"7px 6px", color:C.textSec, fontWeight:700 }}>DF</th>
                  <th style={{ padding:"7px 6px", color:C.textSec, fontWeight:700 }}>計</th>
                </tr>
              </thead>
              <tbody>
                {tallyRows.map(t => (
                  <tr key={t.team+t.name} style={{ borderTop:`1px solid ${C.border}` }}>
                    <td style={{ padding:"8px 10px", fontWeight:700, color:teamColor(t.team), whiteSpace:"nowrap" }}>{t.name}</td>
                    <td style={{ padding:"8px 6px", textAlign:"center", fontWeight:700 }}>{t.first}</td>
                    <td style={{ padding:"8px 6px", textAlign:"center", fontWeight:700 }}>{t.second}</td>
                    <td style={{ padding:"8px 6px", textAlign:"center", fontWeight:800, color:t.df>0?C.red:C.text }}>{t.df}</td>
                    <td style={{ padding:"8px 6px", textAlign:"center", fontWeight:800 }}>{t.first+t.second+t.df}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function StatsTab({ match, onDownloadCsv, onShareLine }) {
  const [teamFilter, setTeamFilter] = useState("A");
  const stats    = calcPlayerStats(match);
  // ★修正: teamFilterで絞る（Bも正しく表示）
  const filtered = stats.filter(s => s.team === teamFilter);

  // ★チーム共通の目標値（自チーム＝Aのみに適用）
  const [goals, setGoals] = useState(null);
  useEffect(() => {
    (async () => {
      const profile = await getMyProfile();
      if (profile?.school_id) setGoals(await getSchoolGoals(profile.school_id));
    })();
  }, []);

  const allPts = match.games.flatMap(g => g.points);
  const totalA = allPts.filter(p=>p.scoring_team==="A").length;
  const totalB = allPts.filter(p=>p.scoring_team==="B").length;
  const winA   = allPts.filter(p=>p.scoring_team==="A"&&p.is_winner===true).length;
  const winB   = allPts.filter(p=>p.scoring_team==="B"&&p.is_winner===true).length;

  // ★内訳を1行の横棒で表す小さな部品（ミスの種類・フォア/バック用）
  function MiniBar({ label, count, max, total, color }) {
    const pct = total > 0 ? Math.round(count / total * 100) : 0;
    return (
      <div style={{ display:"flex",alignItems:"center",gap:8,marginBottom:4 }}>
        <span style={{ fontSize:10,color:C.textSec,width:70,flexShrink:0 }}>{label}</span>
        <span style={{ fontSize:10,fontWeight:700,color:"#555",flexShrink:0,width:52 }}>{count}回 {pct}%</span>
        <div style={{ flex:1,maxWidth:"50%",height:5,background:"#e8e8e8",borderRadius:3 }}>
          <div style={{ width:`${max>0?Math.round(count/max*100):0}%`,height:"100%",background:color,borderRadius:3 }}/>
        </div>
      </div>
    );
  }
  // ★内訳セクションの共通描画（ネット/オーバー/チップ、フォア/バック）
  function Breakdown({ title, entries, total, color }) {
    const rows = entries.filter(([,n]) => n > 0);
    if (rows.length === 0) return null;
    const max = Math.max(...rows.map(r => r[1]));
    return (
      <>
        <div style={{ borderTop:`1px dashed ${C.border}`,margin:"8px 0" }}/>
        <div style={{ fontSize:10,fontWeight:700,color:C.textSec,marginBottom:6 }}>{title}</div>
        {rows.map(([label,n]) => <MiniBar key={label} label={label} count={n} max={max} total={total} color={color}/>)}
      </>
    );
  }

  function Bar({ a, b, label }) {
    const max = Math.max(a, b, 1);
    const pctA = Math.round((a / max) * 100);
    const pctB = Math.round((b / max) * 100);
    return (
      <div style={{ marginBottom:12 }}>
        {/* 数値ラベル行 */}
        <div style={{ display:"flex", alignItems:"center", marginBottom:4 }}>
          <span style={{ fontSize:13, fontWeight:700, color:C.teamA, width:28, textAlign:"left" }}>{a}</span>
          <span style={{ flex:1, fontSize:11, color:C.textSec, textAlign:"center" }}>{label}</span>
          <span style={{ fontSize:13, fontWeight:700, color:C.teamB, width:28, textAlign:"right" }}>{b}</span>
        </div>
        {/* バー行：左=自チームA（右寄せ）、中央区切り、右=相手B（左寄せ） */}
        <div style={{ display:"grid", gridTemplateColumns:"1fr 2px 1fr", alignItems:"center", height:8, gap:2 }}>
          {/* A側：右寄せ */}
          <div style={{ display:"flex", justifyContent:"flex-end", height:8, background:"#e8edf3", borderRadius:"4px 0 0 4px", overflow:"hidden" }}>
            <div style={{ width:`${pctA}%`, background:C.teamA, height:"100%", borderRadius:"4px 0 0 4px", transition:"width 0.3s" }}/>
          </div>
          {/* 中央区切り線 */}
          <div style={{ width:2, height:14, background:C.border }}/>
          {/* B側：左寄せ */}
          <div style={{ display:"flex", justifyContent:"flex-start", height:8, background:"#e8edf3", borderRadius:"0 4px 4px 0", overflow:"hidden" }}>
            <div style={{ width:`${pctB}%`, background:C.teamB, height:"100%", borderRadius:"0 4px 4px 0", transition:"width 0.3s" }}/>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding:14 }}>
      <MatchSummaryPanel match={match} part="summary" />

      {/* チーム比較 */}
      <div style={{ background:C.white,borderRadius:12,border:`1px solid ${C.border}`,padding:14,marginBottom:12 }}>
        <div style={{ display:"flex",justifyContent:"space-between",marginBottom:12 }}>
          <span style={{ fontSize:12,fontWeight:700,color:C.teamA }}>自チーム</span>
          <span style={{ fontSize:11,color:C.textSec }}>チーム比較</span>
          <span style={{ fontSize:12,fontWeight:700,color:C.teamB }}>相手チーム</span>
        </div>
        <Bar a={totalA} b={totalB} label="総ポイント"/>
        <Bar a={winA}   b={winB}   label="決めた得点"/>
        <Bar a={totalA-winA} b={totalB-winB} label="相手ミスで得点"/>
      </div>

      {/* ★自チーム/相手チーム切替タブ */}
      <div style={{ display:"flex",background:"#f0f2f6",padding:3,borderRadius:10,marginBottom:12 }}>
        {[["A","自チーム"],["B","相手チーム"]].map(([t,l])=>(
          <button key={t} style={{ flex:1,padding:7,border:"none",cursor:"pointer",borderRadius:8,fontSize:12,fontWeight:700,background:teamFilter===t?C.white:"transparent",color:teamFilter===t?C.navy:C.textSec,boxShadow:teamFilter===t?"0 1px 4px rgba(0,0,0,0.1)":"none" }} onClick={()=>setTeamFilter(t)}>{l}</button>
        ))}
      </div>

      {/* ★選手別スタッツ（filtered で正しくBも表示） */}
      {filtered.length===0&&(
        <div style={{ textAlign:"center",color:C.textSec,padding:"30px 0" }}>
          <div style={{ fontSize:32,marginBottom:8 }}>📊</div>
          選手データがありません<br/>
          <span style={{ fontSize:12 }}>ポイント記録時に選手を選択すると表示されます</span>
        </div>
      )}
      {filtered.map(p=>{
        const winPlays = Object.entries(p.playsWin).sort((a,b)=>b[1]-a[1]);
        const errPlays = Object.entries(p.playsErr).sort((a,b)=>b[1]-a[1]);
        const hasGoals = p.team==="A" && !!goals; // ★目標は自チームのみ適用
        const pointDiff = p.winners - p.errors;
        const diffGood = hasGoals && goals.goal_point_diff!=null ? pointDiff >= goals.goal_point_diff : pointDiff > 0;
        return (
          <div key={`${p.team}__${p.player_name}`} style={{ ...S.card,marginBottom:10 }}>
            <div style={{ background:p.team==="A"?C.navyMid:C.navy,padding:"8px 12px",display:"flex",alignItems:"center",gap:8 }}>
              <div style={{ width:26,height:26,borderRadius:"50%",background:p.team==="A"?"#2ecc71":"#f97316",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:700,color:C.white }}>{p.player_name[0]}</div>
              <span style={{ fontSize:13,fontWeight:700,color:C.white,flex:1 }}>{p.player_name}</span>
              <span style={{ fontSize:10,color:"#8099cc" }}>計 {p.total}pt</span>
            </div>
            <div style={{ padding:12 }}>
              <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6,marginBottom:10 }}>
                {[
                  ["得点",p.winners,C.accent],
                  ["ミス",p.errors,C.red],
                  ["得点差", pointDiff>=0?`+${pointDiff}`:`${pointDiff}`, diffGood?C.accent:C.red],
                ].map(([l,v,c])=>(
                  <div key={l} style={{ background:`${c}11`,borderRadius:8,padding:"8px 4px",textAlign:"center" }}>
                    <div style={{ fontSize:18,fontWeight:700,color:c }}>{v}</div>
                    <div style={{ fontSize:9,color:C.textSec,fontWeight:700 }}>{l}</div>
                  </div>
                ))}
              </div>
              {/* ★サーブ・レシーブ（2ポイントごとの交代を反映。関与があった選手のみ表示。目標比較で色分け） */}
              {(p.serveTotal>0||p.receiveTotal>0)&&(
                <>
                  <div style={{ fontSize:10,color:C.textSec,fontWeight:700,marginBottom:6 }}>🎾 サーブ・レシーブ</div>
                  {p.serveTotal>0&&(()=>{
                    const inCount=p.serveTotal-p.serveFault; const rate=Math.round(inCount/p.serveTotal*100);
                    const good = hasGoals && goals.goal_first_serve_pct!=null ? rate>=goals.goal_first_serve_pct : null;
                    const barColor = good===null?C.accent:(good?C.accent:C.red);
                    return (
                      <div style={{ display:"flex",alignItems:"center",gap:8,marginBottom:4,paddingLeft:10 }}>
                        <span style={{ fontSize:10,color:C.textSec,width:84,flexShrink:0 }}>1stサーブ確率</span>
                        <span style={{ fontSize:11,fontWeight:700,color:good===null?C.navy:(good?C.accent:C.red),whiteSpace:"nowrap",flexShrink:0,display:"flex",alignItems:"center",gap:4 }}>
                          {inCount}/{p.serveTotal}・{rate}%
                          {good!==null&&<span style={{ fontSize:9,padding:"1px 5px",borderRadius:8,background:good?`${C.accent}22`:`${C.red}22`,color:good?C.accent:C.red }}>{good?"達成":"未達"}</span>}
                        </span>
                        <div style={{ flex:1,maxWidth:"50%",height:6,background:C.border,borderRadius:3 }}><div style={{ width:`${rate}%`,height:"100%",background:barColor,borderRadius:3 }}/></div>
                      </div>
                    );
                  })()}
                  {/* ★レシーブミス率（%）は算出方法が複雑で誤差が出やすいため、実際に記録された回数のみ表示する */}
                  {/* ★自チームは「レシーブミス0回」を目標とし、0回でも表示して達成／1回でもあれば未達を付ける。
                       （レシーブの機会があった選手のみ。相手チームは従来どおりミスがあったときだけ回数を表示） */}
                  {(()=>{
                    const rMiss = p.playsErr["receive"]||0;
                    const isOwn = p.team==="A";
                    if (isOwn ? !(p.receiveTotal>0 || rMiss>0) : rMiss===0) return null;
                    const good = rMiss===0;
                    return (
                      <div style={{ display:"flex",alignItems:"center",gap:8,marginBottom:4,paddingLeft:10 }}>
                        <span style={{ fontSize:10,color:C.textSec,width:84,flexShrink:0 }}>レシーブミス</span>
                        <span style={{ fontSize:11,fontWeight:700,color:good?C.accent:C.red,whiteSpace:"nowrap",flexShrink:0,display:"flex",alignItems:"center",gap:4 }}>
                          {rMiss}回
                          {isOwn&&<span style={{ fontSize:9,padding:"1px 5px",borderRadius:8,background:good?`${C.accent}22`:`${C.red}22`,color:good?C.accent:C.red }}>{good?"達成":"未達"}</span>}
                        </span>
                      </div>
                    );
                  })()}
                </>
              )}

              {/* ★プレイ結果と内訳（決めた／ミスしたの2グループに分解。目標比較で色分け） */}
              {(winPlays.length>0||errPlays.length>0)&&(
                <div style={{ marginTop:8 }}>
                  <div style={{ fontSize:10,color:C.textSec,fontWeight:700,marginBottom:6 }}>プレイ結果と内訳</div>
                  {winPlays.length>0&&(()=>{
                    const good = hasGoals && goals.goal_winner_count!=null ? p.winners>=goals.goal_winner_count : null;
                    return (
                      <div style={{ background:C.white,borderRadius:8,padding:"8px 10px",marginBottom:8 }}>
                        <div style={{ fontSize:10,fontWeight:700,color:C.accent,marginBottom:6,display:"flex",alignItems:"center",gap:6 }}>
                          ✓ 決めたプレイ（{p.winners}回）
                          {good!==null&&<span style={{ fontSize:9,padding:"1px 5px",borderRadius:8,background:good?`${C.accent}22`:`${C.red}22`,color:good?C.accent:C.red }}>目標{goals.goal_winner_count}回以上：{good?"達成":"未達"}</span>}
                        </div>
                        {winPlays.map(([k,n])=>(
                          <div key={k} style={{ display:"flex",alignItems:"center",gap:8,marginBottom:4 }}>
                            <span style={{ fontSize:10,color:C.textSec,width:70,flexShrink:0 }}>{getPlayLabel(k)}</span>
                            <span style={{ fontSize:10,fontWeight:700,color:"#555",flexShrink:0 }}>{n}回</span>
                            <div style={{ flex:1,maxWidth:"50%",height:5,background:"#e8e8e8",borderRadius:3 }}><div style={{ width:`${Math.round(n/p.winners*100)}%`,height:"100%",background:"#7bdba0",borderRadius:3 }}/></div>
                          </div>
                        ))}
                        {/* ★フォア/バック別の得点（記録はしていたが今まで集計していなかった項目） */}
                        <Breakdown
                          title="フォア / バック別の得点"
                          entries={SIDE_TYPES.map(sd => [sd.label, p.sideWin?.[sd.key] ?? 0])}
                          total={Object.values(p.sideWin ?? {}).reduce((a,b)=>a+b,0)}
                          color="#7bdba0"
                        />
                        {/* ★コース別の得点 */}
                        <Breakdown
                          title="コース別の得点"
                          entries={COURSE_TYPES.map(ct => [getCourseLabel(ct.key), p.courseWin?.[ct.key] ?? 0])}
                          total={Object.values(p.courseWin ?? {}).reduce((a,b)=>a+b,0)}
                          color="#7bdba0"
                        />
                      </div>
                    );
                  })()}
                  {errPlays.length>0&&(()=>{
                    const good = hasGoals && goals.goal_error_count!=null ? p.errors<=goals.goal_error_count : null;
                    return (
                      <div style={{ background:C.white,borderRadius:8,padding:"8px 10px" }}>
                        <div style={{ fontSize:10,fontWeight:700,color:C.red,marginBottom:6,display:"flex",alignItems:"center",gap:6 }}>
                          ✕ ミスしたプレイ（{p.errors}回）
                          {good!==null&&<span style={{ fontSize:9,padding:"1px 5px",borderRadius:8,background:good?`${C.accent}22`:`${C.red}22`,color:good?C.accent:C.red }}>目標{goals.goal_error_count}回以下：{good?"達成":"未達"}</span>}
                        </div>
                        {errPlays.map(([k,n])=>(
                          <div key={k} style={{ display:"flex",alignItems:"center",gap:8,marginBottom:4 }}>
                            <span style={{ fontSize:10,color:C.textSec,width:70,flexShrink:0 }}>{getPlayLabel(k)}</span>
                            <span style={{ fontSize:10,fontWeight:700,color:"#555",flexShrink:0 }}>{n}回</span>
                            <div style={{ flex:1,maxWidth:"50%",height:5,background:"#e8e8e8",borderRadius:3 }}><div style={{ width:`${Math.round(n/p.errors*100)}%`,height:"100%",background:"#f0a49c",borderRadius:3 }}/></div>
                          </div>
                        ))}
                        {/* ★ミスの種類（ネット／オーバー／チップ） */}
                        <Breakdown
                          title="ミスの種類"
                          entries={MISS_TYPES.map(mt => [mt.label, p.missTypes?.[mt.key] ?? 0])}
                          total={p.missTyped ?? 0}
                          color="#f0a49c"
                        />
                        {/* ★フォア/バック別のミス */}
                        <Breakdown
                          title="フォア / バック別のミス"
                          entries={SIDE_TYPES.map(sd => [sd.label, p.sideErr?.[sd.key] ?? 0])}
                          total={Object.values(p.sideErr ?? {}).reduce((a,b)=>a+b,0)}
                          color="#f0a49c"
                        />
                        {/* ★コース別のミス */}
                        <Breakdown
                          title="コース別のミス"
                          entries={COURSE_TYPES.map(ct => [getCourseLabel(ct.key), p.courseErr?.[ct.key] ?? 0])}
                          total={Object.values(p.courseErr ?? {}).reduce((a,b)=>a+b,0)}
                          color="#f0a49c"
                        />
                        {/* ★ミスの種類は入力が任意なので、必ず母数を添える */}
                        {(p.missTyped ?? 0) > 0 && (
                          <div style={{ fontSize:9.5,color:"#9aa1ad",marginTop:6 }}>※ミスの種類が入力された {p.missTyped}/{p.errors}件をもとに集計</div>
                        )}
                      </div>
                    );
                  })()}
                </div>
              )}
            </div>
          </div>
        );
      })}

      {/* ★詳細分析は選手ごとの内訳の下に置く */}
      <MatchSummaryPanel match={match} part="details" />

      <div style={{ display:"flex",flexDirection:"column",gap:10 }}>
        <button style={S.btn("#06c755")} onClick={onShareLine}>💬 LINEで結果を共有</button>
        <button style={S.btn(C.navy)} onClick={onDownloadCsv}>📊 CSVをダウンロード</button>
      </div>
    </div>
  );
}

