// 選手マスター画面（同じ学校のメンバーで共有）
// ============================================================
const POSITIONS = ["前衛", "後衛", "その他"];
function PositionButtons({ value, onChange }) {
  return (
    <div style={{ display:"flex", gap:6 }}>
      {POSITIONS.map(pos => (
        <button key={pos} style={{ flex:1, padding:"8px 4px", fontSize:12, borderRadius:8, border:"none", cursor:"pointer",
          background: value===pos ? C.navy : C.gray, color: value===pos ? C.white : C.text, fontWeight: value===pos ? 700 : 400 }}
          onClick={() => onChange(value===pos ? "" : pos)}>{pos}</button>
      ))}
    </div>
  );
}
function HandButtons({ value, onChange }) {
  return (
    <div style={{ display:"flex", gap:6 }}>
      {[["right","右利き"],["left","左利き"]].map(([k,l]) => (
        <button key={k} style={{ flex:1, padding:"8px 4px", fontSize:12, borderRadius:8, border:"none", cursor:"pointer",
          background: value===k ? C.accent : C.gray, color: value===k ? C.white : C.text, fontWeight: value===k ? 700 : 400 }}
          onClick={() => onChange(value===k ? "" : k)}>{l}</button>
      ))}
    </div>
  );
}
// ============================================================
// 選手マスター：テキストを貼り付けて選手を一括登録
// ★対戦表・名簿の文字をコピーして貼り付け、選手マスターに直接登録する（ペアマスターを経由しない）。
//   形式はペアマスターの一括登録と同じ（1行1ペア、タブ・カンマ・全角スペース・連続半角スペース区切り）。
//   ・「出場番号　学校名　選手1　選手2」…先頭が数字なら出場番号として読み飛ばす
//   ・「学校名　選手名」…選手1人だけの行もOK
//   ・「選手名」だけの行は自チームの選手として扱う
//   確認画面は「ペアマスターから選手マスターへ登録」と同じ作り（未登録の選手だけ、自チーム判定、✏️で修正）。
// ============================================================
function parseRosterImportText(text, mySchoolName) {
  const out = [];
  text.split("\n").map(l => l.trim()).filter(Boolean).forEach(line => {
    let cols = (line.includes("\t") ? line.split("\t") : line.split(/,|　| {2,}/)).map(c => (c || "").trim());
    if (cols.length > 1 && /^[0-9０-９]+$/.test(cols[0])) cols = cols.slice(1); // 出場番号
    cols = cols.filter(Boolean);
    if (cols.length === 0) return;
    if (cols.length === 1) { out.push({ name: cols[0], clubName: mySchoolName || "" }); return; }
    const [club, ...names] = cols;
    names.forEach(n => out.push({ name: n, clubName: club }));
  });
  return out;
}

function RosterTextImportScreen({ mySchoolName, onBack }) {
  const [step, setStep] = useState("paste"); // paste | confirm
  const [text, setText] = useState("");
  const [loading, setLoading] = useState(false);
  const [candidates, setCandidates] = useState([]); // [{ name, clubName, isOwn, checked }]
  const [skipped, setSkipped] = useState([]);       // 既に選手マスターにいる選手名
  const [registering, setRegistering] = useState(false);
  const [progress, setProgress] = useState(0);
  const [editIdx, setEditIdx] = useState(-1);
  const [editName, setEditName] = useState("");
  const [editClub, setEditClub] = useState("");

  const parsed = parseRosterImportText(text, mySchoolName);
  const pairLines = text.split("\n").map(l => l.trim()).filter(Boolean).length;

  async function goConfirm() {
    if (parsed.length === 0) { alert("読み取れる選手がいません。"); return; }
    setLoading(true);
    try {
      const roster = await getPlayerRoster({ fresh: true });
      const existing = new Set(roster.map(p => normalizePlayerName(p.player_name)));
      const seen = new Set();
      const list = [], skip = [];
      parsed.forEach(({ name, clubName }) => {
        const key = normalizePlayerName(name);
        if (!key || seen.has(key)) return; // ★同じ選手が何度出てきても1名として扱う
        seen.add(key);
        if (existing.has(key)) { skip.push(name); return; }
        list.push({ name, clubName, isOwn: !!mySchoolName && clubName === mySchoolName, checked: true });
      });
      setCandidates(list);
      setSkipped(skip);
      setStep("confirm");
    } catch (e) {
      alert("選手マスターの読み込みに失敗しました: " + (e.message || e));
    } finally {
      setLoading(false);
    }
  }

  function toggle(i) { setCandidates(l => l.map((c, j) => j === i ? { ...c, checked: !c.checked } : c)); }
  function toggleOwn(i) { setCandidates(l => l.map((c, j) => j === i ? { ...c, isOwn: !c.isOwn } : c)); }
  function toggleAll(checked) { setCandidates(l => l.map(c => ({ ...c, checked }))); }
  function openEdit(i) { setEditIdx(i); setEditName(candidates[i].name); setEditClub(candidates[i].clubName); }
  function saveEdit() {
    const n = editName.trim(), club = editClub.trim();
    if (!n) { alert("選手名を入力してください。"); return; }
    // ★この画面の中だけで直す（ペアマスターなど他のデータは書き換えない）
    setCandidates(l => l.map((c, j) => j === editIdx ? { ...c, name: n, clubName: club, isOwn: !!mySchoolName && club === mySchoolName } : c));
    setEditIdx(-1);
  }

  async function handleRegister() {
    const targets = candidates.filter(c => c.checked);
    if (targets.length === 0) { alert("登録する選手を選んでください。"); return; }
    setRegistering(true);
    setProgress(0);
    let ok = 0, fail = 0, done = 0;
    // ★1人ずつ順番に保存すると人数が多いときに時間がかかるため、5人ずつ同時に保存する
    for (let i = 0; i < targets.length; i += 5) {
      await Promise.all(targets.slice(i, i + 5).map(async c => {
        try {
          await savePlayer({ player_name: c.name, is_own_team: c.isOwn, team_name: (c.isOwn ? (c.clubName || mySchoolName) : c.clubName) || null });
          ok++;
        } catch (e) { fail++; }
        done++;
        setProgress(done);
      }));
    }
    setRegistering(false);
    if (fail === 0) { alert(`${ok}名を選手マスターに登録しました。`); onBack(); }
    else alert(`${ok}名を登録しました。${fail}名は登録に失敗しました。通信状況を確認して、もう一度お試しください。`);
  }

  const allChecked = candidates.length > 0 && candidates.every(c => c.checked);
  const checkedCount = candidates.filter(c => c.checked).length;

  return (
    <div style={S.page}>
      <div style={{ ...S.hdr, display:"flex", alignItems:"center", gap:10 }}>
        <button style={{ background:"none", border:"none", color:C.white, fontSize:20, cursor:"pointer" }} disabled={registering}
          onClick={() => step === "confirm" ? setStep("paste") : onBack()}>←</button>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontSize:16, fontWeight:800, color:C.white }}>{step === "paste" ? "📋 テキストから一括登録" : "登録する選手の確認"}</div>
          <div style={{ fontSize:11, color:"rgba(255,255,255,0.7)", marginTop:2 }}>{step === "paste" ? "選手マスター" : "貼り付けた内容から"}</div>
        </div>
      </div>

      {step === "paste" ? (
        <div style={{ padding:14 }}>
          <div style={{ fontSize:11.5, color:C.navy, background:"#eef0ff", border:"1px solid #dcdffc", borderRadius:10, padding:"10px 12px", lineHeight:1.6, marginBottom:10 }}>
            💡 対戦表や名簿をコピーして貼り付けてください。ペアマスターの取り込みと同じ形式が使えます（1行1ペア、タブ・カンマ・全角スペース区切り）。
            <div style={{ background:C.white, border:`1px solid ${C.border}`, borderRadius:8, padding:"8px 10px", marginTop:6, fontFamily:"monospace", fontSize:11, color:C.textSec, lineHeight:1.6 }}>
              1　東福岡　清見 祐吾　田中 蓮<br/>2　真颯館　福永 清春　保科 空伽
            </div>
            <div style={{ marginTop:6 }}>出場番号は無くても構いません。1行に選手1人だけ（「学校名　選手名」）でも読み取れます。</div>
          </div>
          <textarea
            value={text}
            onChange={e => setText(e.target.value)}
            placeholder="ここに貼り付け"
            style={{ width:"100%", height:200, border:`2px solid ${C.navy}`, borderRadius:12, padding:10, fontSize:13, fontFamily:"inherit", boxSizing:"border-box", resize:"vertical", background:C.white, color:C.text }}
          />
          <button
            style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`, C.white), marginTop:10 }}
            disabled={loading || parsed.length === 0}
            onClick={goConfirm}
          >{loading ? "読み込み中..." : parsed.length === 0 ? "貼り付けると確認できます" : `内容を確認する（${pairLines}行・${parsed.length}名）→`}</button>
        </div>
      ) : (
        <div style={{ padding:14 }}>
          <div style={{ fontSize:11.5, color:C.textSec, background:"#f7f8fa", border:`1px solid ${C.border}`, borderRadius:10, padding:"9px 11px", lineHeight:1.6, marginBottom:10 }}>
            選手マスターにまだいない選手だけを一覧にしています。学校名から自チーム／他チームを自動判定しています。違っていればタップで切り替え、✏️で名前・学校名を直せます。
          </div>
          {candidates.length === 0 ? (
            <div style={{ textAlign:"center", color:C.textSec, marginTop:30, fontSize:12.5, lineHeight:1.8 }}>
              <div style={{ fontSize:36, marginBottom:10 }}>✅</div>
              貼り付けた選手は全員、既に選手マスターに登録されています
            </div>
          ) : (
            <>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", margin:"2px 2px 8px" }}>
                <div style={{ fontSize:11.5, fontWeight:700, color:C.navy }}>未登録の選手（{candidates.length}名）</div>
                <button style={{ background:"none", border:"none", color:C.navy, fontSize:11.5, fontWeight:700, cursor:"pointer" }} onClick={() => toggleAll(!allChecked)} disabled={registering}>
                  {allChecked ? "全て解除" : "全て選択"}
                </button>
              </div>
              <div style={S.card}>
                {candidates.map((c, i) => (
                  <div key={c.name + "_" + i} style={{ padding:"11px 14px", borderBottom:`1px solid ${C.border}`, display:"flex", alignItems:"center", gap:10 }}>
                    <input type="checkbox" checked={c.checked} onChange={() => toggle(i)} disabled={registering} style={{ width:18, height:18, flexShrink:0 }} />
                    <div style={{ flex:1, minWidth:0, cursor:"pointer" }} onClick={() => !registering && toggle(i)}>
                      <div style={{ fontSize:13.5, fontWeight:700, color:C.text, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                        {c.name}
                        <span style={{ fontWeight:400, color:C.textSec }}> ／ {c.clubName || "（学校名未入力）"}</span>
                      </div>
                    </div>
                    <span style={S.chip(c.isOwn)} onClick={() => !registering && toggleOwn(i)}>{c.isOwn ? "自チーム" : "他チーム"}</span>
                    <button style={{ background:"none", border:"none", fontSize:15, cursor:"pointer", padding:"2px 0", flexShrink:0 }}
                      onClick={() => openEdit(i)} disabled={registering} title="選手名・学校名を修正">✏️</button>
                  </div>
                ))}
              </div>
            </>
          )}
          {skipped.length > 0 && (
            <div style={{ ...S.card, marginTop:8, padding:"10px 14px", fontSize:12, color:C.textSec, lineHeight:1.6 }}>
              登録済みのため省略：{skipped.length}名（{skipped.slice(0, 3).join("、")}{skipped.length > 3 ? " ほか" : ""}）
            </div>
          )}
          {candidates.length > 0 && (
            <button
              style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`, C.white), marginTop:12 }}
              disabled={registering || checkedCount === 0}
              onClick={handleRegister}
            >{registering ? `登録中...（${progress}/${checkedCount}）` : `選択した選手を登録する（${checkedCount}名）`}</button>
          )}
        </div>
      )}

      {editIdx >= 0 && candidates[editIdx] && (
        <Modal onClose={() => setEditIdx(-1)}>
          <h3 style={{ fontSize:15, fontWeight:800, marginBottom:4 }}>選手名・学校名を修正</h3>
          <div style={{ fontSize:10.5, color:C.textSec, marginBottom:12, lineHeight:1.6 }}>この画面の中だけで修正します（ペアマスターなどは変わりません）。</div>
          <div style={{ fontSize:11, fontWeight:700, color:C.textSec, marginBottom:4 }}>選手名</div>
          <input style={{ width:"100%", padding:"9px 12px", borderRadius:10, border:`1px solid ${C.border}`, background:C.white, fontSize:13.5, color:C.text, boxSizing:"border-box", marginBottom:12 }}
            value={editName} onChange={e => setEditName(e.target.value)} />
          <div style={{ fontSize:11, fontWeight:700, color:C.textSec, marginBottom:4 }}>学校名・チーム名</div>
          <input style={{ width:"100%", padding:"9px 12px", borderRadius:10, border:`1px solid ${C.border}`, background:C.white, fontSize:13.5, color:C.text, boxSizing:"border-box", marginBottom:16 }}
            value={editClub} onChange={e => setEditClub(e.target.value)} />
          <div style={{ display:"flex", gap:8 }}>
            <button style={{ flex:1, padding:11, borderRadius:10, border:`1px solid ${C.border}`, background:C.white, fontSize:13, fontWeight:700, color:C.textSec, cursor:"pointer" }} onClick={() => setEditIdx(-1)}>キャンセル</button>
            <button style={{ flex:1, padding:11, borderRadius:10, border:"none", background:C.navy, fontSize:13, fontWeight:800, color:C.white, cursor:"pointer" }} onClick={saveEdit}>保存</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ★名字だけの記録をまとめる
//   当初「西」のように名字だけで選手マスターに登録して試合を記録し、あとからフルネームの選手を別に登録した場合、
//   過去の試合には「西」の文字のまま残り、対戦成績・スタッツが「西」と「西 優」に分かれてしまう。
//   過去の試合（match_players）から名字だけの名前を探し、同じ学校の選手マスターにいる同じ名字のフルネームの選手を候補に出して、
//   ユーザーが確認したものだけ、出場選手・ポイント・フォルトの名前をフルネームに書き換える。
const isSurnameOnlyName = (n) => { const t = String(n || "").trim(); return !!t && !/[\s　]/.test(t); };
const surnameOfName = (n) => String(n || "").trim().split(/[\s　]+/)[0];

async function mergeSurnameRecords(item, newName) {
  // item: { name, rowIds, matchIds }
  const { error: mpErr } = await supabase.from("match_players").update({ player_name: newName }).in("id", item.rowIds);
  if (mpErr) throw mpErr;
  const { error: ptErr } = await supabase.from("points").update({ player_name: newName }).eq("player_name", item.name).in("match_id", item.matchIds);
  if (ptErr) throw ptErr;
  const { error: flErr } = await supabase.from("faults").update({ player_name: newName }).eq("player_name", item.name).in("match_id", item.matchIds);
  if (flErr) throw flErr;
}

function MergeSurnameScreen({ mySchoolName, onBack }) {
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [items, setItems] = useState([]);        // 候補あり
  const [noMatch, setNoMatch] = useState([]);    // 候補なし
  const [choice, setChoice] = useState({});      // key -> まとめ先のフルネーム（null=まとめない）
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [running, setRunning] = useState(false);
  const [done, setDone] = useState(null);        // { results:[{from,to,count}], failed:[{from,msg}], matchCount }

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [roster, mpRes] = await Promise.all([
          getPlayerRoster({ fresh: true }),
          fetchAllRows("match_players", "id, match_id, team, player_name, club_name", q => q.order("id")),
        ]);
        if (mpRes.error) throw mpRes.error;
        const own = (mySchoolName || "").trim();
        // 学校ごとの選手マスター（自チームの選手は自分の学校として扱う）
        const rosterBySchool = {};
        (roster || []).forEach(p => {
          const school = p.is_own_team !== false ? own : (p.team_name || "").trim();
          if (!school) return;
          (rosterBySchool[school] ??= []).push(String(p.player_name || "").trim());
        });
        // 名字だけの名前を「チーム側・学校・名前」ごとに集める
        const groups = {};
        (mpRes.data || []).forEach(r => {
          const name = String(r.player_name || "").trim();
          if (!isSurnameOnlyName(name)) return;
          const school = (r.club_name || "").trim() || (r.team === "A" ? own : "");
          const key = `${r.team}|${school}|${name}`;
          const g = (groups[key] ??= { key, team: r.team, school, name, rowIds: [], matchIds: [] });
          g.rowIds.push(r.id);
          if (!g.matchIds.includes(r.match_id)) g.matchIds.push(r.match_id);
        });
        const found = [], missing = [];
        Object.values(groups).forEach(g => {
          const cands = [...new Set((rosterBySchool[g.school] || []).filter(n => !isSurnameOnlyName(n) && surnameOfName(n) === g.name))].sort();
          if (cands.length) found.push({ ...g, cands, isOwn: !!own && g.school === own });
          else missing.push(g);
        });
        // 自チームを先に、そのあと学校名順・名前順
        found.sort((a, b) => (b.isOwn - a.isOwn) || a.school.localeCompare(b.school, "ja") || a.name.localeCompare(b.name, "ja"));
        missing.sort((a, b) => a.school.localeCompare(b.school, "ja") || a.name.localeCompare(b.name, "ja"));
        // ポイント数（確認用の目安）
        const counts = await Promise.all(found.map(g =>
          supabase.from("points").select("id", { count: "exact", head: true }).eq("player_name", g.name).in("match_id", g.matchIds)
            .then(r => r.count ?? null).catch(() => null)
        ));
        found.forEach((g, i) => { g.pointCount = counts[i]; });
        if (cancelled) return;
        const init = {};
        // 候補が1人なら最初からチェック。2人以上なら、間違いを防ぐため選んでもらう
        found.forEach(g => { init[g.key] = g.cands.length === 1 ? g.cands[0] : null; });
        setItems(found); setNoMatch(missing); setChoice(init); setLoading(false);
      } catch (e) {
        if (!cancelled) { setLoadError(e?.message || String(e)); setLoading(false); }
      }
    })();
    return () => { cancelled = true; };
  }, [mySchoolName]);

  const chosen = items.filter(g => choice[g.key]);
  const multiChosen = chosen.filter(g => g.cands.length > 1);

  async function runMerge() {
    setRunning(true);
    const results = [], failed = [];
    const touched = new Set();
    for (const g of chosen) {
      try {
        await mergeSurnameRecords(g, choice[g.key]);
        results.push({ from: g.name, to: choice[g.key], count: g.matchIds.length });
        g.matchIds.forEach(id => touched.add(id));
      } catch (e) {
        failed.push({ from: g.name, msg: e?.message || String(e) });
      }
    }
    invalidateMatchCaches();
    dropSavedSnapshot();
    invalidateRosterCache();
    setRunning(false); setConfirmOpen(false);
    setDone({ results, failed, matchCount: touched.size });
  }

  const SEL = "#0b6e75";
  const hdr = (
    <div style={S.hdr}>
      <div style={{ display:"flex", alignItems:"center", gap:12 }}>
        <button style={{ background:"none", border:"none", color:C.white, fontSize:20, cursor:"pointer" }} onClick={onBack} disabled={running}>←</button>
        <span style={{ fontSize:17, fontWeight:800, color:C.white, flex:1 }}>名字だけの記録をまとめる</span>
      </div>
    </div>
  );

  if (done) {
    return (
      <div style={S.page}>
        {hdr}
        <div style={{ padding:"30px 16px", textAlign:"center" }}>
          <div style={{ fontSize:44 }}>{done.failed.length ? "⚠️" : "✅"}</div>
          <h3 style={{ margin:"8px 0 6px", fontSize:18, fontWeight:800 }}>{done.results.length ? "まとめました" : "まとめられませんでした"}</h3>
          {done.results.length > 0 && <p style={{ fontSize:13, color:C.textSec, lineHeight:1.7, margin:"0 0 16px" }}>{done.matchCount}試合の記録をフルネームに書き換えました。</p>}
          {done.results.length > 0 && (
            <div style={{ ...S.card, textAlign:"left", marginBottom:16 }}>
              {done.results.map((r, i) => (
                <div key={i} style={{ padding:"9px 12px", borderBottom:`1px solid ${C.border}`, fontSize:13 }}>{r.from} → {r.to}（{r.count}試合）</div>
              ))}
            </div>
          )}
          {done.failed.length > 0 && (
            <div style={{ background:"#fdecea", border:"1px solid #f5b5b0", borderRadius:10, padding:"10px 12px", fontSize:12.5, color:C.red, textAlign:"left", marginBottom:16, lineHeight:1.7 }}>
              次の名前は書き換えに失敗しました。もう一度お試しください。<br/>
              {done.failed.map((f, i) => <div key={i}>・{f.from}：{f.msg}</div>)}
            </div>
          )}
          <button style={{ ...S.btn(`linear-gradient(135deg,${C.navy},${C.navyMid})`), padding:15, fontSize:16, borderRadius:12 }} onClick={onBack}>選手マスターに戻る</button>
        </div>
      </div>
    );
  }

  // 学校ごとにまとめて表示
  const bySchool = [];
  items.forEach(g => {
    const label = g.school || "学校名なし";
    let sec = bySchool.find(s => s.label === label && s.isOwn === g.isOwn);
    if (!sec) { sec = { label, isOwn: g.isOwn, list: [] }; bySchool.push(sec); }
    sec.list.push(g);
  });

  return (
    <div style={{ ...S.page, paddingBottom:0, display:"flex", flexDirection:"column" }}>
      {hdr}
      <div style={{ padding:14, flex:1 }}>
        {loading ? (
          <div style={{ textAlign:"center", color:C.textSec, marginTop:60, fontSize:14 }}>過去の試合を調べています...</div>
        ) : loadError ? (
          <div style={{ background:"#fdecea", border:"1px solid #f5b5b0", borderRadius:10, padding:12, fontSize:13, color:C.red }}>読み込みに失敗しました：{loadError}</div>
        ) : (
          <>
            <div style={{ background:"#eaeef7", border:"1px solid #b9c4dc", borderRadius:10, padding:"10px 12px", fontSize:12.5, lineHeight:1.7, color:C.navy, marginBottom:4 }}>
              過去の試合で名字だけで記録された選手のうち、<b>同じ学校</b>の選手マスターに<b>同じ名字のフルネームの選手</b>がいるものを探しました。まとめたいものにチェックを入れてください。
            </div>

            {items.length === 0 && (
              <div style={{ textAlign:"center", color:C.textSec, fontSize:13, margin:"30px 0 10px" }}>まとめられる名前は見つかりませんでした。</div>
            )}

            {bySchool.map(sec => (
              <div key={sec.label + sec.isOwn}>
                <div style={{ fontSize:12, fontWeight:800, color:C.textSec, margin:"14px 2px 6px" }}>{sec.label}（{sec.isOwn ? "自チーム" : "相手チーム"}）</div>
                <div style={{ ...S.card, marginBottom:0 }}>
                  {sec.list.map(g => {
                    const sub = `${g.matchIds.length}試合${g.pointCount != null ? `・${g.pointCount}ポイント` : ""}`;
                    if (g.cands.length > 1) {
                      return (
                        <div key={g.key} style={{ padding:"11px 12px", borderBottom:`1px solid ${C.border}`, background:"#fffaf0" }}>
                          <div style={{ fontSize:13, fontWeight:800, marginBottom:8 }}>「{g.name}」（{sub}）は、どの選手ですか？</div>
                          <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                            {g.cands.map(n => {
                              const on = choice[g.key] === n;
                              return <button key={n} onClick={() => setChoice(c => ({ ...c, [g.key]: n }))} style={{ padding:"8px 12px", borderRadius:10, border:`2px solid ${on ? SEL : C.border}`, background:on ? SEL : C.white, color:on ? C.white : C.text, fontSize:13.5, fontWeight:800, cursor:"pointer" }}>{n}</button>;
                            })}
                            {(() => { const on = !choice[g.key]; return (
                              <button onClick={() => setChoice(c => ({ ...c, [g.key]: null }))} style={{ padding:"8px 12px", borderRadius:10, border:`2px solid ${on ? "#7a8499" : C.border}`, background:on ? "#eef0f4" : C.white, color:C.textSec, fontSize:13.5, fontWeight:700, cursor:"pointer" }}>まとめない</button>
                            ); })()}
                          </div>
                        </div>
                      );
                    }
                    const on = !!choice[g.key];
                    return (
                      <div key={g.key} onClick={() => setChoice(c => ({ ...c, [g.key]: on ? null : g.cands[0] }))}
                        style={{ display:"flex", alignItems:"center", gap:10, padding:"11px 12px", borderBottom:`1px solid ${C.border}`, cursor:"pointer" }}>
                        <div style={{ width:24, height:24, borderRadius:7, border:`2px solid ${on ? SEL : "#c4cbd8"}`, background:on ? SEL : C.white, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center", color:C.white, fontWeight:900, fontSize:15 }}>{on ? "✓" : ""}</div>
                        <div style={{ flex:1, minWidth:0 }}>
                          <div style={{ fontSize:15, fontWeight:800, display:"flex", alignItems:"center", gap:6, flexWrap:"wrap" }}>
                            <span style={{ color:C.textSec, textDecoration:"line-through", textDecorationColor:"#c4cbd8" }}>{g.name}</span>
                            <span style={{ color:SEL, fontWeight:900 }}>→</span>
                            <span>{g.cands[0]}</span>
                          </div>
                          <div style={{ fontSize:11.5, color:C.textSec, marginTop:3 }}>{sub}</div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}

            {noMatch.length > 0 && (
              <>
                <div style={{ fontSize:12, fontWeight:800, color:C.textSec, margin:"14px 2px 6px" }}>候補が見つからなかった名前</div>
                <div style={{ ...S.card, padding:"10px 12px", fontSize:12, color:C.textSec, lineHeight:1.7 }}>
                  {noMatch.map(g => `${g.name}（${g.school || "学校名なし"}）`).join("・")}
                  <br/>選手マスターに同じ名字のフルネームの選手がいないため、そのままにします。
                </div>
              </>
            )}
          </>
        )}
      </div>

      {!loading && !loadError && items.length > 0 && (
        <div style={{ position:"sticky", bottom:0, background:C.white, borderTop:`1px solid ${C.border}`, padding:"12px 14px calc(12px + env(safe-area-inset-bottom))" }}>
          <button
            disabled={chosen.length === 0}
            onClick={() => setConfirmOpen(true)}
            style={{ ...S.btn(chosen.length ? `linear-gradient(135deg,${C.navy},${C.navyMid})` : "#b8bfcc"), padding:15, fontSize:16, borderRadius:12, cursor:chosen.length ? "pointer" : "default" }}
          >{chosen.length ? `チェックした${chosen.length}件をまとめる` : "まとめる名前を選んでください"}</button>
          {multiChosen.length > 0 && (
            <div style={{ textAlign:"center", fontSize:11, color:C.textSec, marginTop:6 }}>
              {multiChosen.map(g => `${g.name}は「${choice[g.key]}」`).join("、")}でまとめます
            </div>
          )}
        </div>
      )}

      {confirmOpen && (
        <Modal onClose={() => { if (!running) setConfirmOpen(false); }}>
          <h3 style={{ margin:"0 0 10px", fontSize:17, fontWeight:800, textAlign:"center" }}>{chosen.length}件の名前をまとめますか？</h3>
          <p style={{ fontSize:13, lineHeight:1.75, margin:"0 0 12px", textAlign:"left" }}>過去の試合の出場選手・ポイント・フォルトの名前をフルネームに書き換えます。対戦成績・スタッツ・選手別の成績がまとめて集計されるようになります。</p>
          <div style={{ background:"#fdecea", border:"1px solid #f5b5b0", color:C.red, borderRadius:10, padding:"9px 12px", fontSize:12.5, fontWeight:700, marginBottom:14, textAlign:"left" }}>⚠ 書き換えた名前は元に戻せません</div>
          <button disabled={running} onClick={runMerge} style={{ ...S.btn(running ? "#8a96ad" : `linear-gradient(135deg,${C.navy},${C.navyMid})`), padding:15, fontSize:16, borderRadius:12, marginBottom:8 }}>{running ? "書き換え中..." : "まとめる"}</button>
          <button disabled={running} onClick={() => setConfirmOpen(false)} style={{ ...S.btn("#f0f0f0", C.text), borderRadius:12 }}>キャンセル</button>
        </Modal>
      )}
    </div>
  );
}

function PlayerRosterScreen({ onBack }) {
  const [players, setPlayers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState("own"); // own | other
  const [schools, setSchools] = useState([]);
  const [mySchoolName, setMySchoolName] = useState("");
  const [filterSchool, setFilterSchool] = useState("");
  const [newLastName, setNewLastName] = useState("");
  const [newFirstName, setNewFirstName] = useState("");
  const [schoolPrefFilter, setSchoolPrefFilter] = useState("");
  const [newPosition, setNewPosition] = useState("");
  const [showNewSchoolInput, setShowNewSchoolInput] = useState(false); // ★一覧に無い新しい対戦相手の学校を、検索入力で追加する時だけ表示
  const [newDominantHand, setNewDominantHand] = useState("");
  const [newMemo, setNewMemo] = useState("");     // ★特徴などの自由メモ
  const [editingId, setEditingId] = useState(null);
  const [editLastName, setEditLastName] = useState("");
  const [editFirstName, setEditFirstName] = useState("");
  const [editPosition, setEditPosition] = useState("");
  const [editTeamName, setEditTeamName] = useState("");
  const [editDominantHand, setEditDominantHand] = useState("");
  const [editMemo, setEditMemo] = useState("");
  const [errorMsg, setErrorMsg] = useState("");
  const [nameSearch, setNameSearch] = useState(""); // ★学校を問わず選手名で直接検索するための入力
  const [menuOpen, setMenuOpen] = useState(false);     // ★右上「⋯」メニュー
  const [textImportOpen, setTextImportOpen] = useState(false); // ★テキストから一括登録の画面
  const [mergeOpen, setMergeOpen] = useState(false); // ★名字だけの記録をまとめる画面

  const reload = useCallback(() => {
    setLoading(true);
    // ★選手マスターの管理画面では、ほかの人の変更も含めて必ず最新を表示する
    getPlayerRoster({ fresh: true }).then(list => { setPlayers(list); setLoading(false); });
  }, []);

  useEffect(() => {
    reload();
    getSchools().then(list => {
      setSchools(list);
      getMyProfile().then(p => {
        if (p?.school_id) {
          const s = list.find(s => s.id === p.school_id);
          if (s) setMySchoolName(s.name);
        }
      });
    });
  }, [reload]);

  const ownPlayers = players.filter(p => p.is_own_team !== false);
  const otherPlayers = players.filter(p => p.is_own_team === false);
  const otherSchoolNames = [...new Set(otherPlayers.map(p => p.team_name).filter(Boolean))].sort();
  // ★登録済みの対戦相手の学校名 → 都道府県 の対応表（都道府県チップでの絞り込み用）
  const schoolPrefByName = {};
  schools.forEach(s => { schoolPrefByName[s.name] = s.prefecture; });
  // ★特定の学校を選んでいなくても、都道府県チップで絞り込んでいればその都道府県の選手だけに絞る
  //   （これまでは学校未選択時に都道府県フィルタが効かず、他県の選手も一覧に混ざってしまっていた）
  const visibleOtherPlayers = filterSchool
    ? otherPlayers.filter(p => p.team_name === filterSchool)
    : schoolPrefFilter
      ? otherPlayers.filter(p => schoolPrefByName[p.team_name] === schoolPrefFilter)
      : otherPlayers;
  const availablePrefs = [...new Set(schools.map(s => s.prefecture).filter(Boolean))].sort();
  const filteredOtherSchoolNames = schoolPrefFilter
    ? otherSchoolNames.filter(n => schoolPrefByName[n] === schoolPrefFilter)
    : otherSchoolNames;

  const handLabel = (k) => k==="right" ? "右利き" : k==="left" ? "左利き" : "";

  async function handleAdd() {
    setErrorMsg("");
    const fullName = [newLastName.trim(), newFirstName.trim()].filter(Boolean).join(" ");
    if (!fullName) return;
    try {
      const finalTeamName = tab==="own" ? mySchoolName : filterSchool;
      if (tab==="other" && !finalTeamName.trim()) { setErrorMsg("学校を選択してください"); return; }
      // ★「他チーム」で自チームと同じ学校名を入力した場合は自動的に自チーム扱いにする
      const isOwn = tab==="own" || (!!mySchoolName && finalTeamName.trim() === mySchoolName.trim());
      await savePlayer({ player_name: fullName, position: newPosition || null, dominant_hand: newDominantHand || null, is_own_team: isOwn, team_name: finalTeamName, memo: newMemo.trim() || null });
      // ★学校の選択（filterSchool）はリセットしない → 同じ学校の選手を続けて登録しやすくする
      setNewLastName(""); setNewFirstName(""); setNewPosition(""); setNewDominantHand(""); setNewMemo("");
      reload();
    } catch (e) { setErrorMsg("追加に失敗しました: " + (e.message || JSON.stringify(e))); }
  }
  async function handleUpdate(id) {
    setErrorMsg("");
    const fullName = [editLastName.trim(), editFirstName.trim()].filter(Boolean).join(" ");
    if (!fullName) return;
    try {
      const finalTeamName = editTeamName;
      // ★学校名が自チームと同じかどうかで自チーム／他チームを判定する（タブではなく実際の学校名で判定）
      const isOwn = !!mySchoolName && finalTeamName.trim() === mySchoolName.trim();
      const oldName = players.find(p => p.id === id)?.player_name;
      await savePlayer({ id, player_name: fullName, position: editPosition || null, dominant_hand: editDominantHand || null, is_own_team: isOwn, team_name: finalTeamName, memo: editMemo.trim() || null });
      // ★名前を変更した場合、過去の試合記録（そのチーム側の出場分）にも反映する
      if (oldName && oldName !== fullName) {
        try {
          const n = await renamePlayerEverywhere(oldName, fullName, isOwn ? "A" : "B", isOwn ? null : finalTeamName);
          if (n === 0) {
            alert(`選手情報は更新しましたが、「${oldName}」名義の過去の試合記録は見つかりませんでした。`);
          }
        } catch (renameErr) {
          alert("選手情報は更新しましたが、過去の試合記録への反映でエラーが起きました:\n" + (renameErr.message || renameErr));
        }
      }
      setEditingId(null); reload();
    } catch (e) { setErrorMsg("更新に失敗しました: " + (e.message || JSON.stringify(e))); }
  }
  function startEdit(p) {
    setEditingId(p.id);
    const parts = (p.player_name || "").trim().split(/\s+/);
    setEditLastName(parts[0] || "");
    setEditFirstName(parts.slice(1).join(" ") || "");
    setEditPosition(p.position||"");
    setEditTeamName(p.team_name||"");
    setEditDominantHand(p.dominant_hand||"");
    setEditMemo(p.memo||"");
  }
  async function handleDelete(id) {
    if (!window.confirm("この選手をマスターから削除しますか？")) return;
    setErrorMsg("");
    try { await deletePlayerFromRoster(id); reload(); }
    catch (e) { setErrorMsg("削除に失敗しました: " + (e.message || e)); }
  }

  if (mergeOpen) {
    return <MergeSurnameScreen mySchoolName={mySchoolName} onBack={() => { setMergeOpen(false); reload(); }} />;
  }
  if (textImportOpen) {
    return <RosterTextImportScreen mySchoolName={mySchoolName} onBack={() => { setTextImportOpen(false); reload(); }} />;
  }

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
          <button style={{ background:"none", border:"none", color:C.white, fontSize:20, cursor:"pointer" }} onClick={onBack}>←</button>
          <span style={{ fontSize:18, fontWeight:800, color:C.white, flex:1 }}>選手マスター</span>
          {/* ★右上の「⋯」メニュー（テキストから一括登録） */}
          <button
            style={{ padding:0, width:40, height:34, borderRadius:9, border:"none", background:"rgba(255,255,255,0.14)", color:C.white, fontSize:18, fontWeight:800, cursor:"pointer", letterSpacing:1, flexShrink:0 }}
            onClick={() => setMenuOpen(v => !v)}
            aria-label="メニュー"
          >⋯</button>
        </div>
        {menuOpen && (
          <>
            <div style={{ position:"fixed", inset:0, zIndex:50 }} onClick={() => setMenuOpen(false)} />
            <div style={{ position:"absolute", top:"100%", right:10, marginTop:4, background:C.white, borderRadius:12, boxShadow:"0 6px 20px rgba(0,0,0,0.18)", border:`1px solid ${C.border}`, zIndex:51, minWidth:230 }}>
              <button
                style={{ display:"block", width:"100%", textAlign:"left", padding:"12px 14px", background:"none", border:"none", cursor:"pointer" }}
                onClick={() => { setMenuOpen(false); setTextImportOpen(true); }}
              >
                <div style={{ fontSize:13.5, fontWeight:700, color:C.text }}>📋 テキストから一括登録</div>
                <div style={{ fontSize:11, color:C.textSec, marginTop:2 }}>対戦表・名簿を貼り付けて登録</div>
              </button>
              <button
                style={{ display:"block", width:"100%", textAlign:"left", padding:"12px 14px", background:"none", border:"none", borderTop:`1px solid ${C.border}`, cursor:"pointer" }}
                onClick={() => { setMenuOpen(false); setMergeOpen(true); }}
              >
                <div style={{ fontSize:13.5, fontWeight:700, color:C.text }}>🔗 名字だけの記録をまとめる</div>
                <div style={{ fontSize:11, color:C.textSec, marginTop:2 }}>過去の試合の「西」などをフルネームに直す</div>
              </button>
            </div>
          </>
        )}
      </div>
      <div style={{ display:"flex", gap:6, padding:"12px 14px 0" }}>
        {[["own","自チーム"],["other","他チーム"]].map(([v,l])=>(
          <button key={v} style={{ ...S.togBtn(tab===v,C.navy), flex:1, fontSize:13, padding:"9px 4px" }}
            onClick={()=>{ setTab(v); setEditingId(null); setFilterSchool(""); setShowNewSchoolInput(false); }}>{l}</button>
        ))}
      </div>
      <div style={{ padding:14 }}>
        <div style={{ background:"#f5f5f5", border:"1px solid #e0e0e0", borderRadius:10, padding:"10px 14px", fontSize:12, color:C.textSec, marginBottom:14 }}>
          {tab==="own" ? "ℹ️ ここで登録した選手は、同じ学校のメンバー全員が試合作成時に「自チーム」として選べます。" : "ℹ️ 対戦相手の選手を登録しておくと、試合作成時に「相手チーム」として選べ、対戦相手別の分析もしやすくなります。"}
        </div>

        {/* ★学校を問わず、選手名で直接検索・削除できるようにする（誤登録を素早く探す用） */}
        <div style={{ marginBottom:14 }}>
          <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>選手名で検索（学校を問わず、このタブ内の全選手が対象）</div>
          <input style={S.inp} placeholder="例：前衛" value={nameSearch} onChange={e=>setNameSearch(e.target.value)} />
          {nameSearch.trim() && (
            <div style={{ ...S.card, marginTop:10, padding:0 }}>
              {(tab==="own" ? ownPlayers : otherPlayers).filter(p => p.player_name.includes(nameSearch.trim())).length===0 ? (
                <div style={{ padding:14, fontSize:12, color:C.textSec, textAlign:"center" }}>該当する選手が見つかりません</div>
              ) : (tab==="own" ? ownPlayers : otherPlayers).filter(p => p.player_name.includes(nameSearch.trim())).map(p=>(
                <div key={p.id} style={{ display:"flex", alignItems:"center", padding:"12px 14px", gap:10, borderBottom:`1px solid ${C.border}` }}>
                  <div style={{ flex:1 }}>
                    <div style={{ fontSize:14, fontWeight:700, color:C.text }}>{p.player_name}</div>
                    <div style={{ fontSize:11, color:C.textSec }}>{[p.team_name, p.position, handLabel(p.dominant_hand)].filter(Boolean).join(" ・ ")}</div>
                    {p.memo && <div style={{ fontSize:11, color:C.text, marginTop:4, whiteSpace:"pre-wrap", lineHeight:1.5 }}>📝 {p.memo}</div>}
                  </div>
                  <button style={{ background:"none", border:"none", fontSize:16, cursor:"pointer", color:C.red }} onClick={()=>handleDelete(p.id)}>🗑</button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* ★他チームタブ：先に都道府県→学校をチップで選び、登録済み選手を確認してから選手名を入力する流れ */}
        {tab==="other" && (
          <>
            {availablePrefs.length > 0 && otherSchoolNames.length > 0 && (
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>都道府県で絞り込み</div>
                <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                  <button style={{ ...S.togBtn(schoolPrefFilter==="", C.navy), fontSize:11, padding:"6px 10px" }} onClick={()=>setSchoolPrefFilter("")}>すべて</button>
                  {availablePrefs.map(pref=>(
                    <button key={pref} style={{ ...S.togBtn(schoolPrefFilter===pref, C.navy), fontSize:11, padding:"6px 10px" }} onClick={()=>setSchoolPrefFilter(pref)}>{pref}</button>
                  ))}
                </div>
              </div>
            )}

            {otherSchoolNames.length > 0 && (
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>学校で絞り込み</div>
                <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                  <button style={{ ...S.togBtn(filterSchool==="" && !showNewSchoolInput, C.navy), fontSize:11, padding:"6px 10px" }} onClick={()=>{ setFilterSchool(""); setShowNewSchoolInput(false); }}>すべて</button>
                  {filteredOtherSchoolNames.map(name=>(
                    <button key={name} style={{ ...S.togBtn(filterSchool===name && !showNewSchoolInput, C.navy), fontSize:11, padding:"6px 10px" }} onClick={()=>{ setFilterSchool(name); setShowNewSchoolInput(false); }}>{name}</button>
                  ))}
                  <button style={{ ...S.togBtn(showNewSchoolInput, C.navy), fontSize:11, padding:"6px 10px" }} onClick={()=>{ setShowNewSchoolInput(v=>!v); setFilterSchool(""); }}>＋ 新しい学校</button>
                </div>
              </div>
            )}

            {(showNewSchoolInput || otherSchoolNames.length===0) && (
              <div style={{ marginBottom:12 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4 }}>
                  <div style={{ fontSize:11, color:C.textSec }}>新しい対戦相手の学校を検索</div>
                  <PrefMiniFilter value={schoolPrefFilter} onChange={setSchoolPrefFilter} options={availablePrefs} />
                </div>
                <SchoolField value={filterSchool} onChange={setFilterSchool} schools={schools} prefFilter={schoolPrefFilter} placeholder="学校名を入力"/>
              </div>
            )}

          </>
        )}

        {tab==="other" && (
          <div style={{ marginBottom:14 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
              <div style={{ fontSize:12, fontWeight:800, color:C.textSec }}>{filterSchool ? `${filterSchool} の登録済み選手` : schoolPrefFilter ? `登録済み選手（${schoolPrefFilter}）` : "登録済み選手（すべて）"}</div>
              <div style={{ fontSize:11, color:C.textSec, fontWeight:700 }}>{visibleOtherPlayers.length}人</div>
            </div>
            {visibleOtherPlayers.length===0 && <div style={{ textAlign:"center", color:C.textSec, padding:"14px 0", fontSize:12 }}>まだ登録されていません</div>}
            {visibleOtherPlayers.map(p => (
              <div key={p.id} style={S.card}>
                {editingId===p.id ? (
                  <div style={{ padding:12 }}>
                    <div style={{ display:"flex", gap:8, marginBottom:8 }}>
                      <input style={{ ...S.inp, flex:1 }} placeholder="姓" value={editLastName} onChange={e=>setEditLastName(e.target.value)} />
                      <input style={{ ...S.inp, flex:1 }} placeholder="名（任意）" value={editFirstName} onChange={e=>setEditFirstName(e.target.value)} />
                    </div>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4 }}>
                      <div style={{ fontSize:11, color:C.textSec }}>学校名・チーム名</div>
                      <PrefMiniFilter value={schoolPrefFilter} onChange={setSchoolPrefFilter} options={availablePrefs} />
                    </div>
                    <div style={{ marginBottom:8 }}>
                      <SchoolField value={editTeamName} onChange={setEditTeamName} schools={schools} prefFilter={schoolPrefFilter} placeholder="学校名を入力"/>
                    </div>
                    <div style={{ fontSize:11, color:C.textSec, marginBottom:4 }}>ポジション</div>
                    <div style={{ marginBottom:8 }}><PositionButtons value={editPosition} onChange={setEditPosition} /></div>
                    <div style={{ fontSize:11, color:C.textSec, marginBottom:4 }}>利き手</div>
                    <div style={{ marginBottom:8 }}><HandButtons value={editDominantHand} onChange={setEditDominantHand} /></div>
                    <div style={{ fontSize:11, color:C.textSec, marginBottom:4 }}>メモ（特徴・注意点など）</div>
                    <textarea
                      style={{ ...S.inp, minHeight:64, resize:"vertical", lineHeight:1.6, fontFamily:"inherit", marginBottom:10 }}
                      placeholder="例：カットサーブが速い／バック側が苦手"
                      value={editMemo}
                      onChange={e=>setEditMemo(e.target.value)}
                    />
                    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                      <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:12 }} onClick={()=>setEditingId(null)}>キャンセル</button>
                      <button style={{ ...S.btn(C.accent), fontSize:12 }} onClick={()=>handleUpdate(p.id)}>保存</button>
                    </div>
                  </div>
                ) : (
                  <div style={{ display:"flex", alignItems:"center", padding:"12px 14px", gap:10 }}>
                    <div style={{ flex:1 }}>
                      <div style={{ fontSize:14, fontWeight:700, color:C.text }}>{p.player_name}</div>
                      <div style={{ fontSize:11, color:C.textSec }}>{[p.team_name, p.position, handLabel(p.dominant_hand)].filter(Boolean).join(" ・ ")}</div>
                      {p.memo && <div style={{ fontSize:11, color:C.text, marginTop:4, whiteSpace:"pre-wrap", lineHeight:1.5 }}>📝 {p.memo}</div>}
                    </div>
                    <button style={{ background:"none", border:"none", fontSize:16, cursor:"pointer" }} onClick={()=>startEdit(p)}>✏️</button>
                    <button style={{ background:"none", border:"none", fontSize:16, cursor:"pointer", color:C.red }} onClick={()=>handleDelete(p.id)}>🗑</button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        <FormSec title={tab==="own" ? "自チームの選手を追加" : (filterSchool ? `${filterSchool} に選手を追加` : "他チームの選手を追加")}>
          <FormRow label="選手名">
            <div style={{ display:"flex", gap:8 }}>
              <input style={{ ...S.inp, flex:1 }} placeholder="姓（例：田中）" value={newLastName} onChange={e=>setNewLastName(e.target.value)} />
              <input style={{ ...S.inp, flex:1 }} placeholder="名（例：蓮・任意）" value={newFirstName} onChange={e=>setNewFirstName(e.target.value)} />
            </div>
          </FormRow>
          {tab==="own" && (
            <FormRow label="学校名・チーム名">
              <div style={{ ...S.inp, background:C.gray, color:C.textSec, display:"flex", alignItems:"center" }}>{mySchoolName || "（プロフィールから自動入力）"}</div>
            </FormRow>
          )}
          <FormRow label="ポジション（任意）">
            <PositionButtons value={newPosition} onChange={setNewPosition} />
          </FormRow>
          <FormRow label="利き手（任意）">
            <HandButtons value={newDominantHand} onChange={setNewDominantHand} />
          </FormRow>
          <FormRow label="メモ（任意）">
            <textarea
              style={{ ...S.inp, minHeight:64, resize:"vertical", lineHeight:1.6, fontFamily:"inherit" }}
              placeholder="例：カットサーブが速い／バック側が苦手／ロブで崩すと有効"
              value={newMemo}
              onChange={e=>setNewMemo(e.target.value)}
            />
          </FormRow>
        </FormSec>
        {errorMsg && <div style={{ color:C.red, fontSize:12, marginBottom:10 }}>{errorMsg}</div>}
        <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), marginBottom:16 }} onClick={handleAdd}>＋ 追加する</button>

        {loading && <div style={{ textAlign:"center", color:C.textSec, padding:"20px 0" }}>読み込み中...</div>}
        {!loading && tab==="own" && ownPlayers.length===0 && <div style={{ textAlign:"center", color:C.textSec, padding:"20px 0" }}>登録されている選手がいません</div>}

        {tab==="own" && ownPlayers.map(p => (
          <div key={p.id} style={S.card}>
            {editingId===p.id ? (
              <div style={{ padding:12 }}>
                <div style={{ display:"flex", gap:8, marginBottom:8 }}>
                  <input style={{ ...S.inp, flex:1 }} placeholder="姓" value={editLastName} onChange={e=>setEditLastName(e.target.value)} />
                  <input style={{ ...S.inp, flex:1 }} placeholder="名（任意）" value={editFirstName} onChange={e=>setEditFirstName(e.target.value)} />
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4 }}>
                  <div style={{ fontSize:11, color:C.textSec }}>学校名・チーム名</div>
                  <PrefMiniFilter value={schoolPrefFilter} onChange={setSchoolPrefFilter} options={availablePrefs} />
                </div>
                <div style={{ marginBottom:8 }}>
                  <SchoolField value={editTeamName} onChange={setEditTeamName} schools={schools} prefFilter={schoolPrefFilter} placeholder="学校名を入力"/>
                </div>
                {editTeamName.trim() !== mySchoolName.trim() && editTeamName.trim() !== "" && (
                  <div style={{ fontSize:11, color:C.orange, marginBottom:8 }}>⚠️ 自チーム（{mySchoolName}）と異なる学校名です。保存すると「他チーム」に移動します。</div>
                )}
                <div style={{ fontSize:11, color:C.textSec, marginBottom:4 }}>ポジション</div>
                <div style={{ marginBottom:8 }}><PositionButtons value={editPosition} onChange={setEditPosition} /></div>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:4 }}>利き手</div>
                <div style={{ marginBottom:8 }}><HandButtons value={editDominantHand} onChange={setEditDominantHand} /></div>
                <div style={{ fontSize:11, color:C.textSec, marginBottom:4 }}>メモ（特徴・注意点など）</div>
                <textarea
                  style={{ ...S.inp, minHeight:64, resize:"vertical", lineHeight:1.6, fontFamily:"inherit", marginBottom:10 }}
                  placeholder="例：カットサーブが速い／バック側が苦手"
                  value={editMemo}
                  onChange={e=>setEditMemo(e.target.value)}
                />
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                  <button style={{ ...S.btn("#f0f0f0"), color:C.text, fontSize:12 }} onClick={()=>setEditingId(null)}>キャンセル</button>
                  <button style={{ ...S.btn(C.accent), fontSize:12 }} onClick={()=>handleUpdate(p.id)}>保存</button>
                </div>
              </div>
            ) : (
              <div style={{ display:"flex", alignItems:"center", padding:"12px 14px", gap:10 }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:14, fontWeight:700, color:C.text }}>{p.player_name}</div>
                  <div style={{ fontSize:11, color:C.textSec }}>{[p.team_name, p.position, handLabel(p.dominant_hand)].filter(Boolean).join(" ・ ")}</div>
                  {p.memo && <div style={{ fontSize:11, color:C.text, marginTop:4, whiteSpace:"pre-wrap", lineHeight:1.5 }}>📝 {p.memo}</div>}
                </div>
                <button style={{ background:"none", border:"none", fontSize:16, cursor:"pointer" }} onClick={()=>startEdit(p)}>✏️</button>
                <button style={{ background:"none", border:"none", fontSize:16, cursor:"pointer", color:C.red }} onClick={()=>handleDelete(p.id)}>🗑</button>
              </div>
            )}
          </div>
        ))}

      </div>
    </div>
  );
}

// ============================================================
// 学校マスター管理画面（管理者専用）
// ============================================================
function AdminSchoolsScreen({ onBack }) {
  const [schools, setSchools] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newName, setNewName] = useState("");
  const [newPrefecture, setNewPrefecture] = useState("");
  const [newCategory, setNewCategory] = useState(null);
  const [newGenderRestriction, setNewGenderRestriction] = useState("mixed");
  const [editingId, setEditingId] = useState(null);
  const [editName, setEditName] = useState("");
  const [editPrefecture, setEditPrefecture] = useState("");
  const [editCategory, setEditCategory] = useState(null);
  const [editGenderRestriction, setEditGenderRestriction] = useState("mixed");
  const [errorMsg, setErrorMsg] = useState("");
  const [listPrefFilter, setListPrefFilter] = useState("");

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const list = await getSchools(true);
      setSchools(list);
      // ★管理画面は「今のDBの正しい状態」を見る場所なので、
      //   古いキャッシュを使い回さず必ずサーバーへ再取得しにいく（force=true）
    } catch (e) {
      console.error("学校マスターの再読み込みに失敗しました:", e);
      alert("学校一覧の取得に失敗しました。\n通信状態を確認して、もう一度再読み込みしてください。");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { reload(); }, [reload]);

  async function handleAdd() {
    setErrorMsg("");
    if (!newName.trim()) return;
    if (!newCategory) { setErrorMsg("区分（高校・中学校など）を選択してください"); return; }
    try {
      await addSchool(newName.trim(), newPrefecture.trim(), newCategory, newGenderRestriction);
      setNewName(""); setNewPrefecture(""); setNewCategory(null); setNewGenderRestriction("mixed");
      reload();
    } catch (e) {
      console.error("学校追加エラー（詳細）:", e);
      const friendly = e.message?.includes("duplicate") ? "同じ名前・同じ区分の学校がすでに登録されています" : (e.message || "追加に失敗しました");
      setErrorMsg(friendly + " [詳細] " + (e.message||"") + " / " + (e.details||"") + " / " + (e.hint||""));
    }
  }

  async function handleUpdate(id) {
    setErrorMsg("");
    if (!editName.trim()) return;
    if (!editCategory) { setErrorMsg("区分（高校・中学校など）を選択してください"); return; }
    try {
      await updateSchoolMaster(id, { name: editName.trim(), prefecture: editPrefecture.trim() || null, category: editCategory, gender_restriction: editGenderRestriction });
      setEditingId(null);
      reload();
    } catch (e) {
      setErrorMsg(e.message?.includes("duplicate") ? "同じ名前・同じ区分の学校がすでに登録されています" : (e.message || "更新に失敗しました"));
    }
  }

  async function handleDelete(id) {
    if (!window.confirm("この学校をマスターから削除しますか？")) return;
    setErrorMsg("");
    try {
      await deleteSchoolMaster(id);
      reload();
    } catch (e) {
      setErrorMsg(
        (e.message?.includes("foreign key") || e.code === "23503")
          ? "この学校を選択しているメンバーがいるため削除できません。先にメンバーに別の学校を選び直してもらうか、学校名を編集してください。"
          : (e.message || "削除に失敗しました")
      );
    }
  }

  return (
    <div style={S.page}>
      <div style={S.hdr}>
        <div style={{ display:"flex",alignItems:"center",gap:12 }}>
          <button style={{ background:"none",border:"none",color:C.white,fontSize:20,cursor:"pointer" }} onClick={onBack}>←</button>
          <span style={{ fontSize:18,fontWeight:800,color:C.white }}>学校マスター管理</span>
        </div>
      </div>
      <div style={{ padding:14 }}>
        <div style={{ background:"#f5f5f5",border:"1px solid #e0e0e0",borderRadius:10,padding:"10px 14px",fontSize:12,color:C.textSec,marginBottom:14 }}>
          ℹ️ ここで登録した学校だけが、新規登録・プロフィールの学校名選択肢に表示されます。同じ学校名でも区分（高校・中学校など）が違えば別の学校として登録できます。
        </div>

        <FormSec title="学校を追加">
          <FormRow label="学校名">
            <input style={S.inp} placeholder="例：東福岡" value={newName} onChange={e=>setNewName(e.target.value)} />
          </FormRow>
          <FormRow label="区分">
            <div style={{ display:"flex",gap:8,flexWrap:"wrap" }}>
              {CATEGORY_OPTIONS.map(c => (
                <button key={c.key} style={S.togBtn(newCategory===c.key)} onClick={()=>setNewCategory(c.key)}>{c.label}</button>
              ))}
            </div>
          </FormRow>
          <FormRow label="都道府県（任意）">
            <select style={{ ...S.inp, background:"transparent" }} value={newPrefecture} onChange={e=>setNewPrefecture(e.target.value)}>
              <option value="">指定なし</option>
              {PREFECTURES.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </FormRow>
          <FormRow label="男女の制限">
            <div style={{ display:"flex",gap:8,flexWrap:"wrap" }}>
              {GENDER_RESTRICTION_OPTIONS.map(g => (
                <button key={g.key} style={S.togBtn(newGenderRestriction===g.key)} onClick={()=>setNewGenderRestriction(g.key)}>{g.label}</button>
              ))}
            </div>
          </FormRow>
        </FormSec>

        {errorMsg && <div style={{ color:C.red,fontSize:12,marginBottom:10 }}>{errorMsg}</div>}

        <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), marginBottom:16 }} onClick={handleAdd}>＋ 追加する</button>

        {loading && <div style={{ textAlign:"center",color:C.textSec,padding:"20px 0" }}>読み込み中...</div>}
        {!loading && schools.length===0 && <div style={{ textAlign:"center",color:C.textSec,padding:"20px 0" }}>登録されている学校がありません</div>}

        {!loading && schools.length>0 && (
          <select
            style={{ ...S.inp, background:"transparent", marginBottom:10 }}
            value={listPrefFilter}
            onChange={e=>setListPrefFilter(e.target.value)}
          >
            <option value="">都道府県で絞り込み（すべて表示）</option>
            {Array.from(new Set(schools.map(s=>s.prefecture).filter(Boolean))).sort((a,b)=>a.localeCompare(b,"ja")).map(p => (
              <option key={p} value={p}>{p}</option>
            ))}
          </select>
        )}

        {schools.filter(s => !listPrefFilter || s.prefecture === listPrefFilter).map(s => (
          <div key={s.id} style={S.card}>
            {editingId===s.id ? (
              <div style={{ padding:12 }}>
                <input style={{ ...S.inp, marginBottom:8 }} value={editName} onChange={e=>setEditName(e.target.value)} />
                <div style={{ display:"flex",gap:8,flexWrap:"wrap",marginBottom:10 }}>
                  {CATEGORY_OPTIONS.map(c => (
                    <button key={c.key} style={S.togBtn(editCategory===c.key)} onClick={()=>setEditCategory(c.key)}>{c.label}</button>
                  ))}
                </div>
                <select style={{ ...S.inp, background:"transparent", marginBottom:10 }} value={editPrefecture} onChange={e=>setEditPrefecture(e.target.value)}>
                  <option value="">指定なし</option>
                  {PREFECTURES.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
                <div style={{ display:"flex",gap:8,flexWrap:"wrap",marginBottom:10 }}>
                  {GENDER_RESTRICTION_OPTIONS.map(g => (
                    <button key={g.key} style={S.togBtn(editGenderRestriction===g.key)} onClick={()=>setEditGenderRestriction(g.key)}>{g.label}</button>
                  ))}
                </div>
                {errorMsg && <div style={{ color:C.red,fontSize:12,marginBottom:8,padding:"6px 8px",background:"#fdecea",borderRadius:6 }}>{errorMsg}</div>}
                <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:8 }}>
                  <button style={{ ...S.btn("#f0f0f0"),color:C.text,fontSize:12 }} onClick={()=>{setEditingId(null);setErrorMsg("");}}>キャンセル</button>
                  <button style={{ ...S.btn(C.accent),fontSize:12 }} onClick={()=>handleUpdate(s.id)}>保存</button>
                </div>
              </div>
            ) : (
              <div style={{ display:"flex",alignItems:"center",padding:"12px 14px",gap:10 }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:14,fontWeight:700,color:C.text }}>{s.name}</div>
                  <div style={{ fontSize:11,color:C.textSec }}>
                    {[categoryLabel(s.category) || "区分未設定", s.prefecture, genderRestrictionLabel(s.gender_restriction)].filter(Boolean).join("・")}
                  </div>
                </div>
                <button style={{ background:"none",border:"none",fontSize:16,cursor:"pointer" }} onClick={()=>{ setEditingId(s.id); setEditName(s.name); setEditPrefecture(s.prefecture||""); setEditCategory(s.category||null); setEditGenderRestriction(s.gender_restriction||"mixed"); }}>✏️</button>
                <button style={{ background:"none",border:"none",fontSize:16,cursor:"pointer",color:C.red }} onClick={()=>handleDelete(s.id)}>🗑</button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

// ============================================================
// ログイン／新規登録画面
// ============================================================
function translateAuthError(msg) {
  if (!msg) return "登録に失敗しました";
  if (msg.includes("User already registered") || msg.includes("already been registered")) return "このメールアドレスはすでに登録されています。ログインしてください。";
  if (msg.includes("Email rate limit exceeded") || msg.includes("email rate limit")) return "短時間に何度も登録しようとしています。しばらく待ってから再試行してください。";
  if (msg.includes("Invalid email")) return "メールアドレスの形式が正しくありません。";
  if (msg.includes("Password should be")) return "パスワードは6文字以上で入力してください。";
  if (msg.includes("signup is disabled")) return "現在新規登録は無効になっています。管理者にお問い合わせください。";
  if (msg.includes("network") || msg.includes("fetch")) return "通信エラーが発生しました。インターネット接続を確認してください。";
  if (msg.includes("duplicate") || msg.includes("unique")) return "すでに登録済みのデータと重複しています。";
  return "登録に失敗しました（" + msg + "）";
}

// ★新規登録時のusersテーブル保存＋選手マスター連携をまとめた共通処理。
// メール確認が必須の設定だと、登録直後はまだセッションがなく保存に失敗するため、
// その場合は一時保存しておき、確認メール経由で初めてログインできた時にこの関数を呼んで自動で仕上げる。
//
// ★品質改善メモ：
// ・選手を探す際は「名前が同じ」だけでなく「学校IDも同じ」かどうかを見て、
//   同姓同名の別選手に誤ってリンクしてしまわないようにしている。
// ・選手マスターから明示的に選手を選んだ場合（selectedId指定時）は、名前の文字列一致に頼らず
//   選手IDで直接更新・紐づけを行う。姓しか登録されていない選手に名を追記して登録した場合も、
//   文字列が変わって一致しなくなることがないよう、IDベースで確実に同一選手として扱う。
// ・users テーブルの update() は結果(error)を必ず確認し、失敗時ははっきり例外を投げる
//   （黙って0件更新のまま処理が続いてしまうのを防ぐ）。
// ・複数ステップ（プロフィール保存→選手検索→選手作成→ユーザー更新）はDBトランザクションではないため、
//   途中で失敗すると一部だけ保存された状態になり得る。どのステップで失敗したかを例外メッセージに
//   含めることで、少なくとも原因調査と手動リカバリはしやすくしている。
//   （将来的にはSupabaseのRPC/Postgres関数にまとめ、DB側で1トランザクションにするのが望ましい）
// ★新規登録時のusersテーブル保存を担う処理（選手マスターへの連携は含まない）。
// 選手マスター（players）は「同じチームの承認済みユーザーのみ閲覧・登録可」というRLSになっているため、
// アカウント作成・プロフィール承認が完了する前は選手一覧を読み取ることができない。
// そのため、選手マスターとの連携（linkPlayerToUser）は必ずこの後、承認済みの状態で呼び出す。
async function saveProfileOnly(payload) {
  try {
    await saveMyProfile({
      name: payload.fullName,
      school_id: payload.schoolId,
      prefecture: payload.prefecture,
      gender_category: payload.genderCategory,
      category: payload.category,
      invite_code: payload.inviteCode,
      // ★この時点ではまだ選手情報登録（ステップ4）が終わっていないため、明示的に未完了にする。
      // これにより、途中でブラウザバック・再読み込みされても「登録完了済み」と誤判定されず、
      // 次回アクセス時にステップ4から再開できる。
      signup_completed: false,
    });
  } catch(e) {
    throw new Error("プロフィール保存に失敗しました: " + (e.message || e));
  }
}

// ★選手情報登録（ステップ4）が完了したことを記録する。
// これが呼ばれるまでは、途中で離脱してもステップ4からやり直しになる。
async function markSignupCompleted(userId) {
  const { error } = await supabase.from("users").update({ signup_completed: true }).eq("id", userId);
  if (error) throw new Error("登録完了の記録に失敗しました: " + error.message);
}

// ★選手マスターとの連携（作成 or 既存へのID直接紐づけ・名前バックフィル）。
// 呼び出し時点でユーザーがすでに承認済み（is_approved=true）である必要がある
// （RLS: 同じチームの承認済みユーザーのみ players を閲覧・登録できるため）。
//
// ★品質改善メモ：
// ・選手を探す際は「名前が同じ」だけでなく「学校IDも同じ」かどうかを見て、
//   同姓同名の別選手に誤ってリンクしてしまわないようにしている。
// ・選手マスターから明示的に選手を選んだ場合（selectedId指定時）は、名前の文字列一致に頼らず
//   選手IDで直接更新・紐づけを行う。姓しか登録されていない選手に名を追記して登録した場合も、
//   文字列が変わって一致しなくなることがないよう、IDベースで確実に同一選手として扱う。
async function linkPlayerToUser(userId, payload) {
  async function linkOrCreatePlayer(playerName, position, hand, selectedId, backfillFirst) {
    let roster;
    try {
      roster = await getPlayerRoster();
    } catch(e) {
      throw new Error("選手検索に失敗しました: " + (e.message || e));
    }

    let linkedId = null;

    if (selectedId) {
      const existing = roster.find(p => p.id === selectedId);
      if (existing) {
        const trimmedBackfill = (backfillFirst || "").trim();
        const hasGivenName = /\s/.test((existing.player_name || "").trim());
        let finalName = existing.player_name;
        if (!hasGivenName && trimmedBackfill) {
          finalName = `${(existing.player_name || "").trim()} ${trimmedBackfill}`;
        }
        if (finalName !== existing.player_name || position || hand) {
          try {
            await savePlayer({
              ...existing,
              player_name: finalName,
              position: position || existing.position,
              dominant_hand: hand || existing.dominant_hand,
            });
          } catch(e) {
            throw new Error("選手マスターの更新に失敗しました: " + (e.message || e));
          }
        }
        linkedId = existing.id;
      }
    }

    if (!linkedId) {
      // 同姓同名でも別の学校の選手を誤ってリンクしないよう、学校IDも条件に含める
      const existing = roster.find(p => normalizePlayerName(p.player_name) === normalizePlayerName(playerName) && p.is_own_team && p.school_id === payload.schoolId);
      linkedId = existing?.id;
      if (!existing) {
        try {
          await savePlayer({ player_name: playerName, position, dominant_hand: hand, is_own_team: true, school_id: payload.schoolId });
        } catch(e) {
          throw new Error("選手の新規作成に失敗しました: " + (e.message || e));
        }
        let refreshed;
        try {
          refreshed = await getPlayerRoster();
        } catch(e) {
          throw new Error("作成した選手の再取得に失敗しました: " + (e.message || e));
        }
        const saved = refreshed.find(p => normalizePlayerName(p.player_name) === normalizePlayerName(playerName) && p.is_own_team && p.school_id === payload.schoolId);
        linkedId = saved?.id;
      }
    }

    if (linkedId) {
      const { error } = await supabase.from("users").update({ linked_player_id: linkedId }).eq("id", userId);
      if (error) throw new Error("ユーザーと選手の紐づけに失敗しました: " + error.message);
    }
  }

  if (payload.registerMode === "player") {
    await linkOrCreatePlayer(payload.fullName, payload.playerPosition, payload.playerHand, payload.playerSelectedId, payload.playerBackfillFirst);
  }

  if (payload.registerMode === "guardian" && payload.childName) {
    await linkOrCreatePlayer(payload.childName, payload.childPosition, payload.childHand, payload.childSelectedId, payload.childBackfillFirst);
  }
}

// ★メール確認が必須の設定だと、登録直後はまだセッションがなく保存に失敗するため、
// その場合は一時保存しておき、確認メール経由で初めてログインできた時にこの関数を呼んで自動で仕上げる。
// （この経路では選手マスターの閲覧ができない状態から始まるため、選手の紐づけまで一括で行う）
async function completeProfileRegistration(userId, payload) {
  await saveProfileOnly(payload);
  await linkPlayerToUser(userId, payload);
  await markSignupCompleted(userId);
}

function AuthScreen({ onAuthed }) {
  const [mode, setMode] = useState("login"); // login | signup
  // 新規登録のステップ：1=基本情報 2=登録区分 3=招待コード（ここでアカウントを作成） 4=選手情報（作成後、承認済みの状態で選手マスターに接続）
  const [step, setStep] = useState(1);
  const [email,    setEmail]    = useState("");
  const [password, setPassword] = useState("");
  const [lastName,     setLastName]     = useState("");
  const [firstName,    setFirstName]    = useState("");
  const [schoolId,    setSchoolId]    = useState(null);
  const [prefecture,  setPrefecture]  = useState("東京都");
  const [genderCategory, setGenderCategory] = useState(null);
  const [category,    setCategory]    = useState(null);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [schools, setSchools] = useState([]);
  const [roster, setRoster] = useState([]);
  const [schoolPrefFilter, setSchoolPrefFilter] = useState("");
  const [inviteInput, setInviteInput] = useState("");
  // 登録区分: null=未選択, "player"=選手, "guardian"=保護者
  const [registerMode, setRegisterMode] = useState(null);
  const [playerPosition, setPlayerPosition] = useState(null);
  const [playerHand, setPlayerHand] = useState(null);
  // 選手（本人）を選手マスターと連携する方法： "auto"=名前で自動連携, "master"=マスターから選び直す
  const [playerLinkMode, setPlayerLinkMode] = useState("auto");
  const [playerSelectedId, setPlayerSelectedId] = useState(null);
  const [playerBackfillFirst, setPlayerBackfillFirst] = useState("");
  // 保護者：お子さん・関連選手
  const [childMode, setChildMode] = useState("master"); // master | manual
  const [childSelectedId, setChildSelectedId] = useState(null);
  const [childBackfillFirst, setChildBackfillFirst] = useState("");
  const [childLastName, setChildLastName] = useState("");
  const [childFirstName, setChildFirstName] = useState("");
  const [childPosition, setChildPosition] = useState(null);
  const [childHand, setChildHand] = useState(null);
  // 招待コード確認後に作成されたユーザーID（この時点から選手マスターを読める＝承認済みになる）
  const [createdUserId, setCreatedUserId] = useState(null);
  const [showForgot, setShowForgot] = useState(false);
  const [forgotEmail, setForgotEmail] = useState("");
  const [forgotSent, setForgotSent] = useState(false);
  const [forgotLoading, setForgotLoading] = useState(false);
  const [forgotError, setForgotError] = useState("");
  // ★メール確認が必須の環境向け：確認メール送信後は二重送信を防ぐため専用の状態で固定する
  const [emailConfirmSent, setEmailConfirmSent] = useState(false);
  // ★ページ再読み込み・ブラウザバック等でReactのstateが初期化された後、
  // 既にアカウント作成済み（ステップ4途中）かどうかを判定できるまでは登録ボタンを触らせない
  const [sessionRestoreChecked, setSessionRestoreChecked] = useState(false);

  async function handleForgotSubmit() {
    setForgotError("");
    if (!forgotEmail.trim()) { setForgotError("メールアドレスを入力してください"); return; }
    setForgotLoading(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(forgotEmail.trim());
      if (error) throw error;
      setForgotSent(true);
    } catch (e) {
      setForgotError(translateAuthError(e.message) || "送信に失敗しました");
    } finally {
      setForgotLoading(false);
    }
  }

  useEffect(() => { getSchools().then(setSchools); }, []);

  // ★新規登録の入力状態を全て初期化する。「新規登録」タブを新しく開始する時にだけ呼ぶ。
  // アカウント作成済み・選手情報登録が未完了（ステップ4途中）の場合はここは呼ばない
  // （下の復元用useEffectがステップ4をそのまま復元するため）。
  function resetSignupState() {
    setEmail(""); setPassword("");
    setLastName(""); setFirstName("");
    setSchoolId(null); setPrefecture("東京都"); setSchoolPrefFilter("");
    setGenderCategory(null); setCategory(null);
    setInviteInput("");
    setRegisterMode(null);
    setPlayerPosition(null); setPlayerHand(null);
    setPlayerLinkMode("auto"); setPlayerSelectedId(null); setPlayerBackfillFirst("");
    setChildMode("master"); setChildSelectedId(null); setChildBackfillFirst("");
    setChildLastName(""); setChildFirstName("");
    setChildPosition(null); setChildHand(null);
    setCreatedUserId(null);
    setErrorMsg("");
    setEmailConfirmSent(false);
    setStep(1);
  }

  // 新規登録タブを開始する（ログインから来た場合も含め、常にクリーンな状態から始める）
  function startFreshSignup() {
    resetSignupState();
    setMode("signup");
  }

  // ★ブラウザバック・画面再読み込みでReactのstateが消えた後の復元処理。
  // すでにSupabase側でアカウントが作成済み（＝ステップ3を通過済み）なのに、
  // ステップ1に戻ってしまい、もう一度招待コードを確認しようとすると
  // 「すでに登録済みです」エラーになってしまう不具合を防ぐ。
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session?.user) { if (!cancelled) setSessionRestoreChecked(true); return; }

        // usersテーブルの登録状態を確認する
        const { data: profileRow } = await supabase.from("users").select("*").eq("id", session.user.id).maybeSingle();

        if (cancelled) return;

        if (profileRow?.is_approved && profileRow?.signup_completed) {
          // 選手情報登録まで完了済み＝登録は完了している → そのままホームへ
          onAuthed();
          return;
        }
        if (profileRow?.is_approved) {
          // プロフィール保存（ステップ3）までは完了しているが、選手情報登録（ステップ4）が未完了
          // → 入力し直させず、ステップ4をそのまま復元する
          setCreatedUserId(session.user.id);
          setMode("signup");
          setStep(4);
        }
      } catch (e) {
        console.error("登録状態の復元チェックに失敗:", e);
      } finally {
        if (!cancelled) setSessionRestoreChecked(true);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  // ★選手マスター（players）はRLSで「同じチームの承認済みユーザーのみ閲覧可」となっており、
  // 新規登録の途中（まだアカウント未作成・未承認）の状態では誰であっても取得できない
  // （＝関係のない選手の個人情報が外部に見えてしまうことはない）。
  // そのため、招待コード確認・アカウント作成が完了して承認済みになった後（step4）にのみ取得する。
  useEffect(() => {
    if (step === 4 && createdUserId) {
      getPlayerRoster().then(setRoster).catch(e => {
        console.error(e);
        setErrorMsg("選手マスターの取得に失敗しました。通信状態を確認してもう一度お試しください。");
      });
    }
  }, [step, createdUserId]);

  const fullName = [lastName.trim(), firstName.trim()].filter(Boolean).join(" ");

  // 選択中の学校に紐づく自チームの選手一覧（選手マスターから選ぶ用）
  const schoolRoster = roster.filter(p => p.is_own_team && p.school_id === schoolId);

  function goStep1() { setErrorMsg(""); setStep(1); }
  function goStep2() {
    setErrorMsg("");
    if (!email.trim()) { setErrorMsg("メールアドレスを入力してください"); return; }
    if (password.length < 6) { setErrorMsg("パスワードは6文字以上で入力してください"); return; }
    if (!fullName) { setErrorMsg("お名前（姓）を入力してください"); return; }
    if (!schoolId) { setErrorMsg("学校名を選択してください"); return; }
    if (!category) { setErrorMsg("所属区分を選択してください"); return; }
    if (!genderCategory) { setErrorMsg("チーム区分を選択してください"); return; }
    setStep(2);
  }
  function goStep3() {
    setErrorMsg("");
    if (!registerMode) { setErrorMsg("選手本人／保護者・関係者のいずれかを選択してください"); return; }
    setStep(3);
  }

  // ★招待コードを確認し、その場でアカウントを作成する。
  // 選手マスターの閲覧・選択（ステップ4）は、ここでユーザーが承認済みになった後でないと行えない。
  async function handleCreateAccount() {
    setErrorMsg("");
    if (!inviteInput.trim()) { setErrorMsg("招待コードを入力してください"); return; }
    const codeOk = await verifyInviteCode(schoolId, inviteInput);
    if (!codeOk) { setErrorMsg("招待コードが正しくありません。管理者に確認してください。"); return; }

    setLoading(true);
    try {
      const { data, error } = await supabase.auth.signUp({ email: email.trim(), password });
      if (error) throw error;
      if (data.user) {
        const basePayload = { fullName, schoolId, prefecture, genderCategory, category, registerMode, inviteCode: inviteInput.trim().toUpperCase() };
        if (data.session) {
          await saveProfileOnly(basePayload);
          // ★ブラウザバック・再読み込みでReactのstateが消えても、この後ステップ4を復元できるようにする
          try { localStorage.setItem("signup_step4_pending_" + data.user.id, "1"); } catch(e){}
          setCreatedUserId(data.user.id);
          setLoading(false);
          setStep(4);
          return;
        } else {
          // ★メール確認が必須の環境向けフォールバック：
          // この時点では選手マスターにまだアクセスできないため、選手の紐づけは
          // 「入力済みのお名前で自動連携」のみ行い、保護者のお子さん登録は
          // 確認メール経由の初回ログイン後にプロフィール画面から追加してもらう。
          const payload = {
            ...basePayload,
            playerPosition: null, playerHand: null, playerSelectedId: null, playerBackfillFirst: "",
            childName: "", childPosition: null, childHand: null, childSelectedId: null, childBackfillFirst: "",
          };
          try { localStorage.setItem("pendingProfile_"+email.trim(), JSON.stringify(payload)); } catch(e){}
          setLoading(false);
          // ★確認メール送信後は、もう一度「次へ」を押しても再度signUpされて
          // 「すでに登録済み」エラーになってしまうため、専用の完了表示に切り替えて
          // ボタンを二度と押せないようにする（alertでは無く画面自体を切り替える）。
          setEmailConfirmSent(true);
          return;
        }
      }
    } catch (e) {
      setErrorMsg(translateAuthError(e.message) || "登録に失敗しました");
    } finally {
      setLoading(false);
    }
  }

  // ★選手マスターとの連携を確定し、登録を完了する（この時点でアカウントはすでに作成・承認済み）
  async function handleFinalizeLink() {
    setErrorMsg("");
    if (registerMode === "player" && playerLinkMode === "master" && !playerSelectedId) {
      setErrorMsg("選手マスターから選手を選択してください"); return;
    }
    const childName = [childLastName.trim(), childFirstName.trim()].filter(Boolean).join(" ");
    setLoading(true);
    try {
      const payload = {
        fullName, schoolId, registerMode,
        playerPosition, playerHand,
        playerSelectedId: registerMode==="player" && playerLinkMode==="master" ? playerSelectedId : null,
        playerBackfillFirst,
        childName,
        childPosition, childHand,
        childSelectedId: registerMode==="guardian" && childMode==="master" ? childSelectedId : null,
        childBackfillFirst,
      };
      await linkPlayerToUser(createdUserId, payload);
      // ★選手登録まで完了したことを記録する（お子さんを紐づけない保護者の場合でも、
      // これが無いと linked_player_id が付かず「まだ未完了」と誤判定され続けてしまうため）
      await markSignupCompleted(createdUserId);
      // ★登録完了後は復元用フラグを消しておく（次回リロード時にステップ4へ引き戻されないように）
      try { localStorage.removeItem("signup_step4_pending_" + createdUserId); } catch(e){}
      onAuthed();
    } catch (e) {
      setErrorMsg(e.message || "登録に失敗しました");
    } finally {
      setLoading(false);
    }
  }

  // ---- 選手マスターの選択肢（姓のみの選手には「名 未登録」の目印を付ける） ----
  function rosterOptionLabel(p) {
    const hasGiven = /\s/.test((p.player_name || "").trim());
    return hasGiven ? p.player_name : `${p.player_name}（名 未登録）`;
  }

  const stepLabels = [["基本情報",1], ["登録区分",2], ["招待コード",3], ["選手情報",4]];
  function StepBar() {
    const curNum = step;
    return (
      <div style={{ marginBottom:16 }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:6, marginBottom:6 }}>
          {[1,2,3,4].map((n,i) => (
            <Fragment key={n}>
              <div style={{ width:24, height:24, borderRadius:"50%", fontSize:11, fontWeight:800, display:"flex", alignItems:"center", justifyContent:"center", background:n < curNum ? C.accent : (n === curNum ? C.navy : C.border), color:n <= curNum ? C.white : C.textSec }}>{n}</div>
              {i < 3 && <div style={{ width:22, height:2, background:n < curNum ? C.accent : C.border }} />}
            </Fragment>
          ))}
        </div>
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:10, color:C.textSec, padding:"0 2px" }}>
          {stepLabels.map(([l,n]) => <span key={n} style={{ fontWeight:n===curNum?800:400, color:n===curNum?C.navy:C.textSec }}>{l}</span>)}
        </div>
      </div>
    );
  }

  async function handleLoginSubmit({ email: loginEmail, password: loginPassword }) {
    const { error } = await supabase.auth.signInWithPassword({ email: loginEmail, password: loginPassword });
    if (error) {
      throw new Error(error.message === "Invalid login credentials" ? "メールアドレスまたはパスワードが違います" : (translateAuthError(error.message) || "ログインに失敗しました"));
    }
    onAuthed();
  }

  // ★アカウント作成済み（ステップ4途中）かどうかの確認が終わるまでは、
  // 一瞬でもステップ1が見えてから飛び直す、という見た目のガタつきを避けるため簡易ローディングを表示する
  if (!sessionRestoreChecked) {
    return (
      <div style={{ minHeight:"100vh", display:"flex", alignItems:"center", justifyContent:"center", background:"#f4f6f9", fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
        <div style={{ textAlign:"center", color:C.textSec }}>
          <div style={{ fontSize:36, marginBottom:8 }}>🎾</div>
          読み込み中...
        </div>
      </div>
    );
  }

  // ★ログイン画面はデザイン刷新済みの LoginScreen コンポーネントに全面的に委譲する。
  // 新規登録（4ステップウィザード）は既存のまま、こちらの下に続けて描画する。
  if (mode === "login") {
    return (
      <>
        <LoginScreen
          onLogin={handleLoginSubmit}
          onSwitchToSignup={startFreshSignup}
          onForgotPassword={()=>{ setForgotSent(false); setForgotError(""); setShowForgot(true); }}
        />
        {showForgot && (
          <Modal onClose={()=>setShowForgot(false)}>
            <h3 style={{ fontSize:15, fontWeight:800, marginBottom:10, textAlign:"center" }}>パスワード再設定</h3>
            {forgotSent ? (
              <div style={{ fontSize:12.5, color:C.textSec, textAlign:"center", padding:"8px 0 4px" }}>
                入力されたメールアドレス宛に、パスワード再設定用のリンクを送信しました。メール内のリンクから再設定してください。
              </div>
            ) : (
              <>
                <div style={{ fontSize:12, color:C.textSec, marginBottom:10, textAlign:"center" }}>登録したメールアドレスを入力してください。再設定用のリンクをお送りします。</div>
                <input type="email" autoCapitalize="none" style={S.inp} placeholder="example@email.com" value={forgotEmail} onChange={e=>setForgotEmail(e.target.value)} />
                {forgotError && (
                  <div style={{ background:C.redL, color:C.red, fontSize:12, padding:"10px 14px", borderRadius:10, marginTop:12, fontWeight:700 }}>⚠️ {forgotError}</div>
                )}
                <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), marginTop:16, opacity:forgotLoading?0.6:1 }} disabled={forgotLoading} onClick={handleForgotSubmit}>
                  {forgotLoading ? "送信中..." : "送信する"}
                </button>
              </>
            )}
            <button style={{ ...S.btn("#f0f0f0"), color:C.text, marginTop:8 }} onClick={()=>setShowForgot(false)}>閉じる</button>
          </Modal>
        )}
      </>
    );
  }

  return (
    <main className="st-login-page">
      <section className="st-login-hero">
        <div className="st-login-visual" aria-hidden="true">
          <span className="st-login-emoji">🎾</span>
        </div>
        <div className="st-login-heading">
          <h1>ソフトテニス<br/>記録アプリ</h1>
          <p>スコア記録・データ分析で<br/>チームの成長をサポート</p>
        </div>

        <div className="st-login-card">
          {/* タブ切替（アカウント作成後の選手情報ステップでは切替不可にする） */}
          <div className="st-login-tabs" role="tablist" aria-label="認証方法">
            <button
              type="button" role="tab" aria-selected={mode==="login"}
              className={mode==="login" ? "st-login-tab is-active" : "st-login-tab"}
              disabled={step===4}
              onClick={()=>{ if(step===4) return; setErrorMsg(""); setMode("login"); }}
            >👤 ログイン</button>
            <button
              type="button" role="tab" aria-selected={mode==="signup"}
              className={mode==="signup" ? "st-login-tab is-active" : "st-login-tab"}
              disabled={step===4}
              onClick={()=>{ if(step===4) return; resetSignupState(); setMode("signup"); }}
            >✎ 新規登録</button>
          </div>

          <StepBar />
        </div>

      {/* ============ STEP 1: 基本情報 ============ */}
      {mode==="signup" && step===1 && (
        <>
          <div style={{ fontSize:13, fontWeight:800, color:C.navy, margin:"4px 0 8px" }}>① アカウント情報</div>
          <div style={S.card}>
            <div style={{ padding:"14px 16px" }}>
              <label style={S.lbl}>メールアドレス</label>
              <input type="email" style={S.inp} placeholder="example@email.com" value={email} onChange={e=>setEmail(e.target.value)} autoCapitalize="none"/>
            </div>
            <div style={{ padding:"14px 16px", borderTop:"1px solid "+C.border }}>
              <label style={S.lbl}>パスワード（6文字以上）</label>
              <input type="password" style={S.inp} placeholder="••••••••" value={password} onChange={e=>setPassword(e.target.value)}/>
            </div>
            <div style={{ padding:"14px 16px", borderTop:"1px solid "+C.border }}>
              <label style={S.lbl}>お名前（ご本人）</label>
              <div style={{ display:"flex", gap:10 }}>
                <input style={{ ...S.inp, flex:1 }} placeholder="姓（名字）" value={lastName} onChange={e=>setLastName(e.target.value)}/>
                <input style={{ ...S.inp, flex:1 }} placeholder="名（任意）" value={firstName} onChange={e=>setFirstName(e.target.value)}/>
              </div>
              <div style={{ fontSize:11, color:"#aaa", marginTop:4 }}>💡 姓だけでも登録できます</div>
            </div>
          </div>

          <div style={{ fontSize:13, fontWeight:800, color:C.navy, margin:"14px 0 8px" }}>② 所属情報</div>
          <div style={S.card}>
            <div style={{ padding:"14px 16px" }}>
              <label style={S.lbl}>都道府県</label>
              <select style={{ ...S.inp, background:"transparent" }} value={prefecture} onChange={e=>{ setPrefecture(e.target.value); setSchoolPrefFilter(e.target.value); setSchoolId(null); }}>
                {PREFECTURES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div style={{ padding:"14px 16px", borderTop:"1px solid "+C.border }}>
              <label style={S.lbl}>学校名またはチーム名</label>
              <SchoolIdSearchField value={schoolId} onChange={setSchoolId} schools={schools} prefFilter={schoolPrefFilter} />
            </div>
            <div style={{ padding:"14px 16px", borderTop:"1px solid "+C.border }}>
              <label style={S.lbl}>所属区分</label>
              <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                {CATEGORY_OPTIONS.filter(c=>["adult","university","high_school","junior_high"].includes(c.key)).map(c => (
                  <button key={c.key} style={S.togBtn(category===c.key)} onClick={()=>setCategory(c.key)}>{c.label}</button>
                ))}
              </div>
            </div>
            <div style={{ padding:"14px 16px", borderTop:"1px solid "+C.border }}>
              <label style={S.lbl}>チーム区分</label>
              <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                {GENDER_OPTIONS.map(g => (
                  <button key={g.key} style={S.togBtn(genderCategory===g.key)} onClick={()=>setGenderCategory(g.key)}>{g.label}</button>
                ))}
              </div>
            </div>
          </div>

          {errorMsg && (
            <div style={{ background:C.redL, color:C.red, fontSize:12, padding:"10px 14px", borderRadius:10, marginTop:12, fontWeight:700 }}>⚠️ {errorMsg}</div>
          )}
          <button style={{ ...S.btn(C.navy), marginTop:16 }} onClick={goStep2}>次へ</button>
        </>
      )}

      {/* ============ STEP 2: 登録区分 ============ */}
      {mode==="signup" && step===2 && (
        <>
          <div style={{ fontSize:13, fontWeight:800, color:C.navy, margin:"4px 0 8px" }}>③ 登録区分</div>
          <div style={{ fontSize:11.5, color:C.textSec, marginBottom:10 }}>ご自身の立場を選択してください</div>

          <div onClick={()=>setRegisterMode("player")} style={{ display:"flex", alignItems:"center", gap:12, padding:16, border:`1.5px solid ${registerMode==="player"?C.navy:C.border}`, borderRadius:12, marginBottom:10, cursor:"pointer", background:registerMode==="player"?"#eef3ff":C.white }}>
            <div style={{ width:42, height:42, borderRadius:"50%", background:registerMode==="player"?C.navy:"#eef1f8", display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>🎾</div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:14, fontWeight:800, color:C.navy }}>選手本人として登録</div>
              <div style={{ fontSize:11, color:C.textSec, marginTop:2 }}>ご自身の試合記録やデータを管理します</div>
            </div>
            <div style={{ width:18, height:18, borderRadius:"50%", border:`2px solid ${registerMode==="player"?C.navy:"#ccc"}`, background:registerMode==="player"?C.navy:C.white, flexShrink:0 }} />
          </div>

          <div onClick={()=>setRegisterMode("guardian")} style={{ display:"flex", alignItems:"center", gap:12, padding:16, border:`1.5px solid ${registerMode==="guardian"?C.navy:C.border}`, borderRadius:12, marginBottom:10, cursor:"pointer", background:registerMode==="guardian"?"#eef3ff":C.white }}>
            <div style={{ width:42, height:42, borderRadius:"50%", background:registerMode==="guardian"?C.navy:"#eef1f8", display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>👤</div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:14, fontWeight:800, color:C.navy }}>保護者・関係者として登録</div>
              <div style={{ fontSize:11, color:C.textSec, marginTop:2 }}>選手の試合記録やデータを管理・サポートします</div>
            </div>
            <div style={{ width:18, height:18, borderRadius:"50%", border:`2px solid ${registerMode==="guardian"?C.navy:"#ccc"}`, background:registerMode==="guardian"?C.navy:C.white, flexShrink:0 }} />
          </div>

          <div style={{ background:"#eef3ff", color:"#2b4f9e", fontSize:11, padding:"9px 12px", borderRadius:8, marginBottom:4 }}>ℹ️ 選択した区分によって、次の入力項目が変わります。</div>

          {errorMsg && (
            <div style={{ background:C.redL, color:C.red, fontSize:12, padding:"10px 14px", borderRadius:10, marginTop:12, fontWeight:700 }}>⚠️ {errorMsg}</div>
          )}
          <button style={{ ...S.btn(C.navy), marginTop:16 }} onClick={goStep3}>次へ</button>
          <button style={{ ...S.btn(C.white,C.textSec), marginTop:8, border:`1.5px solid ${C.border}` }} onClick={goStep1}>戻る</button>
        </>
      )}

      {/* ============ STEP 3: 招待コード（ここでアカウントを作成） ============ */}
      {mode==="signup" && step===3 && emailConfirmSent && (
        <>
          <div style={{ fontSize:13, fontWeight:800, color:C.navy, margin:"4px 0 8px" }}>④ 確認メールを送信しました</div>
          <div style={S.card}>
            <div style={{ padding:"20px 16px", textAlign:"center" }}>
              <div style={{ fontSize:36, marginBottom:10 }}>📩</div>
              <div style={{ fontSize:13, color:C.text, lineHeight:1.7 }}>
                「{email}」宛に確認メールを送信しました。<br/>
                メール内のリンクをタップしてから、ログインタブよりログインしてください。<br/>
                ログイン後、選手情報の登録画面が自動的に表示されます。
              </div>
            </div>
          </div>
          <button style={{ ...S.btn(C.navy), marginTop:16 }} onClick={()=>{ resetSignupState(); setMode("login"); }}>ログイン画面へ</button>
        </>
      )}
      {mode==="signup" && step===3 && !emailConfirmSent && (
        <>
          <div style={{ fontSize:13, fontWeight:800, color:C.navy, margin:"4px 0 8px" }}>④ 招待コード</div>
          <div style={{ fontSize:11.5, color:C.textSec, marginBottom:10 }}>チームの管理者から受け取った招待コードを入力してください</div>

          <div style={S.card}>
            <div style={{ padding:"14px 16px" }}>
              <label style={S.lbl}>招待コード</label>
              <input
                style={{ ...S.inp, textAlign:"center", fontSize:18, fontWeight:800, letterSpacing:6 }}
                placeholder=""
                value={inviteInput}
                maxLength={6}
                onChange={e=>setInviteInput(e.target.value.toUpperCase())}
              />
              <div style={{ fontSize:11, color:C.textSec, marginTop:4 }}>コードを確認すると、この画面でアカウントが作成されます。選手の詳細情報は次のステップで入力します。</div>
            </div>
          </div>

          {errorMsg && (
            <div style={{ background:C.redL, color:C.red, fontSize:12, padding:"10px 14px", borderRadius:10, marginTop:12, fontWeight:700 }}>⚠️ {errorMsg}</div>
          )}
          <button style={{ ...S.btn(C.navy), marginTop:16, opacity:loading?0.6:1 }} disabled={loading} onClick={handleCreateAccount}>
            {loading ? "確認中..." : "コードを確認して次へ"}
          </button>
          <button style={{ ...S.btn(C.white,C.textSec), marginTop:8, border:`1.5px solid ${C.border}` }} onClick={()=>{ setErrorMsg(""); setStep(2); }}>戻る</button>
        </>
      )}

      {/* ============ STEP 4: 選手情報（アカウント作成・承認済みの状態で選手マスターに接続） ============ */}
      {mode==="signup" && step===4 && (
        <>
          <div style={{ fontSize:13, fontWeight:800, color:C.navy, margin:"4px 0 8px" }}>
            ⑤ {registerMode==="player" ? "選手情報" : "お子さん・関連選手の情報"}
          </div>
          <div style={{ fontSize:11.5, color:C.textSec, marginBottom:10 }}>アカウントの作成が完了しました。最後に選手情報を登録してください。</div>

          <div style={S.card}>
            {registerMode==="player" ? (
              <div style={{ padding:"14px 16px" }}>
                <label style={S.lbl}>選手マスターとの連携</label>
                <div style={{ display:"flex", background:"#f0f2f6", padding:3, borderRadius:9, marginBottom:10 }}>
                  <button style={{ flex:1, border:"none", padding:8, fontSize:12, fontWeight:700, borderRadius:7, cursor:"pointer", background:playerLinkMode==="auto"?C.white:"transparent", color:playerLinkMode==="auto"?C.navy:C.textSec, boxShadow:playerLinkMode==="auto"?"0 1px 4px rgba(0,0,0,.08)":"none" }} onClick={()=>setPlayerLinkMode("auto")}>「{fullName || "お名前"}」で自動連携</button>
                  <button style={{ flex:1, border:"none", padding:8, fontSize:12, fontWeight:700, borderRadius:7, cursor:"pointer", background:playerLinkMode==="master"?C.white:"transparent", color:playerLinkMode==="master"?C.navy:C.textSec, boxShadow:playerLinkMode==="master"?"0 1px 4px rgba(0,0,0,.08)":"none" }} onClick={()=>setPlayerLinkMode("master")}>選手マスターから選び直す</button>
                </div>

                {playerLinkMode==="auto" ? (
                  <div style={{ fontSize:11, color:C.textSec }}>ステップ①で入力したお名前「{fullName || "―"}」で選手マスターに自動登録・連携します。</div>
                ) : (
                  <>
                    <select style={{ ...S.inp, background:"transparent" }} value={playerSelectedId || ""} onChange={e=>{ setPlayerSelectedId(e.target.value || null); setPlayerBackfillFirst(""); }}>
                      <option value="">選手を選択してください</option>
                      {schoolRoster.map(p => <option key={p.id} value={p.id}>{rosterOptionLabel(p)}</option>)}
                    </select>
                    {schoolRoster.length === 0 && (
                      <div style={{ fontSize:11, color:C.textSec, marginTop:6 }}>この学校にはまだ選手マスターが登録されていません。</div>
                    )}
                    {playerSelectedId && !/\s/.test((schoolRoster.find(p=>p.id===playerSelectedId)?.player_name||"").trim()) && (
                      <div style={{ marginTop:10, border:`1.5px solid ${C.border}`, borderRadius:10, padding:"10px 12px" }}>
                        <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>名（選手マスターに未登録のため入力してください）</div>
                        <input style={S.inp} placeholder="名（例：太郎）" value={playerBackfillFirst} onChange={e=>setPlayerBackfillFirst(e.target.value)} />
                        <div style={{ fontSize:11, color:"#046a45", background:C.accentL, borderRadius:8, padding:"8px 10px", marginTop:8 }}>ℹ️ 入力すると選手マスターにも反映されます。</div>
                      </div>
                    )}
                  </>
                )}
                <div style={{ fontSize:11, color:C.textSec, marginTop:8 }}>※部活動で使用している正式な氏名で連携してください。</div>
              </div>
            ) : (
              <div style={{ padding:"14px 16px" }}>
                <label style={S.lbl}>登録方法（任意）</label>
                <div style={{ display:"flex", gap:10, marginBottom:10 }}>
                  <div onClick={()=>setChildMode("master")} style={{ flex:1, textAlign:"center", padding:"14px 8px", border:`1.5px solid ${childMode==="master"?C.navy:C.border}`, borderRadius:12, cursor:"pointer", background:childMode==="master"?"#eef3ff":C.white }}>
                    <div style={{ fontSize:20, marginBottom:6 }}>🔍</div>
                    <div style={{ fontSize:12, fontWeight:700, color:C.navy }}>選手マスターから選ぶ</div>
                  </div>
                  <div onClick={()=>setChildMode("manual")} style={{ flex:1, textAlign:"center", padding:"14px 8px", border:`1.5px solid ${childMode==="manual"?C.navy:C.border}`, borderRadius:12, cursor:"pointer", background:childMode==="manual"?"#eef3ff":C.white }}>
                    <div style={{ fontSize:20, marginBottom:6 }}>✏️</div>
                    <div style={{ fontSize:12, fontWeight:700, color:C.navy }}>新しく登録する</div>
                  </div>
                </div>

                {childMode==="master" ? (
                  <>
                    <label style={S.lbl}>選手名</label>
                    <select style={{ ...S.inp, background:"transparent" }} value={childSelectedId || ""} onChange={e=>{ setChildSelectedId(e.target.value || null); setChildBackfillFirst(""); }}>
                      <option value="">選手を選択してください</option>
                      {schoolRoster.map(p => <option key={p.id} value={p.id}>{rosterOptionLabel(p)}</option>)}
                    </select>
                    {schoolRoster.length === 0 && (
                      <div style={{ fontSize:11, color:C.textSec, marginTop:6 }}>この学校にはまだ選手マスターが登録されていません。</div>
                    )}
                    {childSelectedId && !/\s/.test((schoolRoster.find(p=>p.id===childSelectedId)?.player_name||"").trim()) && (
                      <div style={{ marginTop:10, border:`1.5px solid ${C.border}`, borderRadius:10, padding:"10px 12px" }}>
                        <div style={{ fontSize:11, color:C.textSec, marginBottom:6 }}>名（選手マスターに未登録のため入力してください）</div>
                        <input style={S.inp} placeholder="名（例：太郎）" value={childBackfillFirst} onChange={e=>setChildBackfillFirst(e.target.value)} />
                        <div style={{ fontSize:11, color:"#046a45", background:C.accentL, borderRadius:8, padding:"8px 10px", marginTop:8 }}>ℹ️ 入力すると選手マスターにも反映されます。</div>
                      </div>
                    )}
                  </>
                ) : (
                  <>
                    <label style={S.lbl}>選手名（本名）</label>
                    <div style={{ display:"flex", gap:10 }}>
                      <input style={{ ...S.inp, flex:1 }} placeholder="姓（例：福岡）" value={childLastName} onChange={e=>setChildLastName(e.target.value)}/>
                      <input style={{ ...S.inp, flex:1 }} placeholder="名（例：太郎）" value={childFirstName} onChange={e=>setChildFirstName(e.target.value)}/>
                    </div>
                  </>
                )}
                <div style={{ fontSize:11, color:C.textSec, marginTop:8 }}>※部活動で使用している正式な氏名でご登録ください。入力しなくても後からプロフィール画面で追加できます。</div>
              </div>
            )}

            <div style={{ padding:"14px 16px", borderTop:"1px solid "+C.border }}>
              <div style={{ fontSize:12, color:C.textSec, marginBottom:8 }}>ポジション（任意）</div>
              <div style={{ display:"flex", gap:8, marginBottom:12 }}>
                {["前衛","後衛"].map(v => {
                  const cur = registerMode==="player" ? playerPosition : childPosition;
                  const set = registerMode==="player" ? setPlayerPosition : setChildPosition;
                  return <button key={v} style={S.togBtn(cur===v)} onClick={()=>set(cur===v?null:v)}>{v}</button>;
                })}
              </div>
              <div style={{ fontSize:12, color:C.textSec, marginBottom:8 }}>利き手（任意）</div>
              <div style={{ display:"flex", gap:8 }}>
                {["右","左"].map(v => {
                  const cur = registerMode==="player" ? playerHand : childHand;
                  const set = registerMode==="player" ? setPlayerHand : setChildHand;
                  return <button key={v} style={S.togBtn(cur===v)} onClick={()=>set(cur===v?null:v)}>{v}</button>;
                })}
              </div>
            </div>
          </div>

          {errorMsg && (
            <div style={{ background:C.redL, color:C.red, fontSize:12, padding:"10px 14px", borderRadius:10, marginTop:12, fontWeight:700 }}>⚠️ {errorMsg}</div>
          )}
          <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), marginTop:16, opacity:loading?0.6:1 }} disabled={loading} onClick={handleFinalizeLink}>
            {loading ? "処理中..." : "登録を完了する"}
          </button>
        </>
      )}
      </section>
    </main>
  );
}

// ============================================================
// AI動画分析（外部AIで分析したテキストを試合に紐づけて閲覧・登録する）
// ============================================================
function aiMatchLabel(m) {
  const players = m.players || m.match_players || [];
  const a = players.filter(p=>p.team==="A").map(p=>p.player_name).join("/");
  const b = players.filter(p=>p.team==="B").map(p=>p.player_name).join("/");
  return { a, b, text: `${a||"自チーム"} vs ${b||"相手"}` };
}

function AiAnalysisAddScreen({ match, existing, onSaved, onCancel }) {
  const [youtubeUrl, setYoutubeUrl] = useState(existing?.youtube_url || "");
  const [commentText, setCommentText] = useState(existing?.comment_text || "");
  const [saving, setSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const textareaRef = useRef(null);
  const label = aiMatchLabel(match).text;

  // ★選択した文字だけ赤くする／赤を解除する（**で囲んで印をつけ、詳細画面ではその部分だけ赤字で表示する）
  const toggleRedHighlight = () => {
    const ta = textareaRef.current;
    if (!ta) return;
    const s = ta.selectionStart, e = ta.selectionEnd;
    if (s === e) { alert("赤くしたい文字をドラッグして選択してから押してください"); return; }
    const before2 = commentText.slice(Math.max(0, s-2), s);
    const after2 = commentText.slice(e, e+2);
    const selText = commentText.slice(s, e);
    let newText, newS, newE;
    if (before2 === "**" && after2 === "**") {
      // 選択範囲のすぐ外側が**で囲まれている → 解除
      newText = commentText.slice(0, s-2) + selText + commentText.slice(e+2);
      newS = s-2; newE = e-2;
    } else if (selText.startsWith("**") && selText.endsWith("**") && selText.length>=4) {
      // **記号ごと選択されていた → 解除
      const inner = selText.slice(2, -2);
      newText = commentText.slice(0, s) + inner + commentText.slice(e);
      newS = s; newE = s + inner.length;
    } else {
      // まだ赤くなっていない → **で囲んで赤くする
      newText = commentText.slice(0, s) + "**" + selText + "**" + commentText.slice(e);
      newS = s; newE = e + 4;
    }
    setCommentText(newText);
    requestAnimationFrame(() => { ta.focus(); ta.setSelectionRange(newS, newE); });
  };

  const handleSave = async () => {
    if (!commentText.trim()) { setErrorMsg("分析結果のテキストを入力してください"); return; }
    setSaving(true); setErrorMsg("");
    try {
      const row = await saveAiAnalysis({ id: existing?.id, match_id: match.id, youtube_url: youtubeUrl, comment_text: commentText });
      onSaved && onSaved(row);
    } catch (e) {
      setErrorMsg("保存に失敗しました: " + (e.message || e));
    } finally {
      setSaving(false);
    }
  };

  return (
    <div style={{ minHeight:"100vh", background:C.gray, paddingBottom:40, fontFamily:"'Helvetica Neue','Hiragino Kaku Gothic ProN','Meiryo',sans-serif" }}>
      <div style={{ ...S.hdr, color:C.white, display:"flex", alignItems:"center", gap:10 }}>
        <span style={{ cursor:"pointer", fontSize:18 }} onClick={onCancel}>←</span>
        <div style={{ fontSize:18, fontWeight:800 }}>{existing ? "AI動画分析を編集" : "AI動画分析を追加"}</div>
      </div>
      <div style={{ padding:14 }}>
        <div style={S.card}>
          <div style={{ padding:14 }}>
            <div style={{ fontSize:11.5, fontWeight:700, color:C.textSec, marginBottom:6 }}>対象試合</div>
            <div style={{ background:"#f7f9fc", border:"1px solid "+C.border, borderRadius:8, padding:"10px 12px", fontSize:13.5, fontWeight:700, color:C.text, marginBottom:16 }}>🎾 {label}</div>

            <div style={{ fontSize:11.5, fontWeight:700, color:C.textSec, marginBottom:6 }}>YouTubeリンク（任意）</div>
            <input style={S.inp} placeholder="https://youtu.be/..." value={youtubeUrl} onChange={e=>setYoutubeUrl(e.target.value)} />

            <div style={{ fontSize:11.5, fontWeight:700, color:C.textSec, margin:"18px 0 6px" }}>AI分析結果のテキストを貼り付け</div>
            <textarea
              ref={textareaRef}
              style={{ width:"100%", padding:"10px 12px", border:"1px solid "+C.border, borderRadius:8, fontSize:12.5, color:C.text, height:220, boxSizing:"border-box", fontFamily:"inherit", lineHeight:1.6 }}
              placeholder="AI分析結果のテキストを貼り付けてください"
              value={commentText}
              onChange={e=>setCommentText(e.target.value)}
            />
            <button
              style={{ ...S.btn("#fff"), color:C.red, border:"1px solid #f5b5b0", marginTop:8, fontSize:12.5 }}
              onClick={toggleRedHighlight}
              type="button"
            >🔴 選んだ文字を赤くする／戻す</button>
            <div style={{ fontSize:10.5, color:C.textSec, marginTop:4, marginBottom:4 }}>赤くしたい部分をテキスト内でドラッグして選択してから、このボタンを押してください。もう一度押すと元に戻せます。</div>

            {commentText.trim() && (
              <>
                <div style={{ fontSize:11.5, fontWeight:700, color:C.textSec, margin:"14px 0 6px" }}>プレビュー</div>
                <div style={{ background:"#f7f9fc", border:"1px solid "+C.border, borderRadius:8, padding:"10px 12px", fontSize:12.5, color:C.text, whiteSpace:"pre-wrap", lineHeight:1.7 }}>
                  {renderAiComment(commentText)}
                </div>
              </>
            )}

            {errorMsg && <div style={{ background:C.redL, color:C.red, fontSize:12, padding:"10px 14px", borderRadius:10, marginTop:12, fontWeight:700 }}>⚠️ {errorMsg}</div>}

            <button style={{ ...S.btn(`linear-gradient(135deg,${C.accent},#00a066)`), marginTop:16 }} disabled={saving} onClick={handleSave}>
              {saving ? "保存中..." : "この内容で保存する"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ★AI分析コメント内の「**強調テキスト**」を赤字で表示する（AIが要点として太字にした部分をそのまま目立たせる）
function renderAiComment(text) {
  if (!text) return null;
  return text.split(/(\*\*[^*]+\*\*)/g).map((part, i) => {
    const m = part.match(/^\*\*([^*]+)\*\*$/);
    return m ? <span key={i} style={{ color:C.red, fontWeight:800 }}>{m[1]}</span> : part;
  });
}

